  // Accès à une icône illustrée par nom (clé de vue). Renvoie le SVG inline ou "".
  function getIconSvg(name) {
    return (MGC_ICONS && MGC_ICONS[name]) || "";
  }

  // Bibliothèque d'icônes (même style trait que les icônes du menu) proposée pour
