  // Ordre canonique déterministe (ordre de déclaration). Ne contient que des clés canoniques.
  // teams/seasons/competitions y figurent (résolution/garde disponibles) mais restent invisibles
  // (ui.available:false) et inertes (legacy/default:false) — cf. commentaires du registre.
  const FEATURE_CANONICAL_KEYS = Object.freeze(["shop", "stages", "memberships", "teams", "seasons", "competitions"]);

  // Table de résolution clé/alias -> clé canonique. Construite depuis le registre (jamais deux
  // fonctionnalités distinctes « shop » et « boutique » : boutique pointe vers shop).
  const FEATURE_KEY_RESOLUTION = (() => {
    const map = {};
    FEATURE_CANONICAL_KEYS.forEach((canonical) => {
      map[canonical] = canonical;
      (FEATURE_REGISTRY[canonical].aliases || []).forEach((alias) => {
        if (typeof alias === "string" && alias) map[alias] = canonical;
      });
    });
    return Object.freeze(map);
  })();

  // Résout une clé (canonique ou alias) vers sa clé canonique. Chaîne vide = inconnue.
  // Pur, sans exception, sans effet de bord ; aucune coercition de casse/accents.
  function resolveFeatureKey(key) {
    if (typeof key !== "string") return "";
    const trimmed = key.trim();
    if (!trimmed) return "";
    return Object.prototype.hasOwnProperty.call(FEATURE_KEY_RESOLUTION, trimmed)
      ? FEATURE_KEY_RESOLUTION[trimmed]
      : "";
  }

  // Définition canonique d'une fonctionnalité (accepte clé canonique ou alias). null si inconnue.
  // L'objet retourné est gelé (immuable) : impossible de muter le registre au travers.
  function featureDefinition(key) {
    const canonical = resolveFeatureKey(key);
    return canonical ? FEATURE_REGISTRY[canonical] : null;
  }

  // Clés canoniques enregistrées, dans un ordre déterministe, sans alias ni doublon. Nouveau
  // tableau à chaque appel : le muter ne modifie pas le registre.
  function registeredFeatureKeys() {
    return FEATURE_CANONICAL_KEYS.slice();
  }

  // true pour une clé canonique OU un alias reconnu ; false sinon.
  function isRegisteredFeature(key) {
    return resolveFeatureKey(key) !== "";
  }

  // Calcul PUR de l'état effectif d'une fonctionnalité pour un club donné (ses settings complets).
  // Ne modifie NI settingsSource NI enabled. Tolère settingsSource absent / null / partiel /
  // features invalide / enabled invalide / valeurs non booléennes / anciennes sauvegardes.
  //
  // Règles :
  //  - clé inconnue -> false (une clé conservée dans enabled mais absente du registre n'est jamais
  //    exécutée) ;
  //  - configured !== true (club historique) -> legacyEnabled (le contenu de enabled ne prend PAS
  //    effet tant que le club n'est pas explicitement configuré) ;
  //  - configured === true -> priorité : (1) booléen explicite de la clé CANONIQUE ;
  //    (2) booléen explicite d'un alias reconnu ; (3) defaultEnabled du registre.
  function featureEnabledInSettings(key, settingsSource) {
    const canonical = resolveFeatureKey(key);
    if (!canonical) return false;
    const def = FEATURE_REGISTRY[canonical];
    const features = settingsSource && typeof settingsSource === "object" ? settingsSource.features : null;
    const configured = Boolean(features && typeof features === "object" && features.configured === true);
    if (!configured) return def.legacyEnabled === true;
    const enabled = features.enabled && typeof features.enabled === "object" && !Array.isArray(features.enabled) ? features.enabled : {};
    // (1) clé canonique explicite (gagne toujours sur un alias contradictoire).
    if (Object.prototype.hasOwnProperty.call(enabled, canonical) && typeof enabled[canonical] === "boolean") {
      return enabled[canonical];
    }
    // (2) premier alias reconnu portant un booléen explicite.
    const aliases = def.aliases || [];
    for (let i = 0; i < aliases.length; i += 1) {
      const alias = aliases[i];
      if (Object.prototype.hasOwnProperty.call(enabled, alias) && typeof enabled[alias] === "boolean") {
        return enabled[alias];
      }
    }
    // (3) défaut du registre (une config explicitement vide ne masque rien).
    return def.defaultEnabled === true;
  }

  // Helper de contexte courant : lit UNIQUEMENT la variable `settings` du club actuellement chargé
  // et délègue au calcul pur. Aucune autre logique : ne lit ni userStore, ni rôle, ni authSession,
  // ni settings.display, ni visibleModules, ni le sport ; ne mute rien, ne persiste rien, ne
  // journalise rien.
  function hasFeature(key) {
    return featureEnabledInSettings(key, settings);
  }

  // Garde-fou central de MUTATION lié à une fonctionnalité (Lot 2B). N'est PAS une permission :
  // délègue uniquement à hasFeature, ne lit ni rôle ni userStore ni authSession, ne réauthentifie
  // pas, ne mute/persiste/journalise rien. Retourne true si la fonctionnalité est active pour le
  // club courant, false sinon — et affiche alors un message utilisateur non technique (sauf
  // options.silent). À appeler au MOMENT EXACT de chaque mutation (handler, soumission de dialogue,
  // écouteur inline) : le simple masquage d'un bouton n'est jamais une protection suffisante.
  function ensureFeatureEnabledForMutation(featureKey, options = {}) {
    if (hasFeature(featureKey)) return true;
    if (!options.silent && typeof alert === "function") {
      const def = featureDefinition(featureKey);
      const label = def ? def.label : "Cette fonctionnalité";
      alert(`${label} est désactivée pour ce club. Réactivez-la dans les paramètres du club pour modifier ces données.`);
    }
    return false;
  }

  // Lot 2C — fonctionnalités RÉELLEMENT proposables dans l'écran « Fonctionnalités du club ».
  // Filtre sur ui.available === true et trie par ui.order : une fonctionnalité déclarée mais pas
  // encore branchée resterait exclue (ne jamais présenter un interrupteur sans effet).
  // Retourne les définitions gelées du registre (ni copie, ni mutation). Ne lit ni settings, ni
  // rôle, ni affichage : c'est une pure projection du registre.
  function screenFeatures() {
    return FEATURE_CANONICAL_KEYS
      .map((key) => FEATURE_REGISTRY[key])
      .filter((def) => def && def.ui && def.ui.available === true)
      .sort((a, b) => (a.ui.order || 0) - (b.ui.order || 0));
  }

  // Lot 2C — calcul PUR de la prochaine configuration settings.features après un choix utilisateur.
  // Ne persiste rien, n'affiche rien, ne journalise rien, ne rend rien, ne lit ni rôle ni userStore
  // ni authSession, et NE MUTE PAS l'objet reçu. Retourne une NOUVELLE structure normalisée.
  //
  // Règles (voir contrat Lot 2C) :
  //  - clé inconnue OU nextEnabled non booléen strict -> aucun changement : on renvoie l'entrée
  //    simplement normalisée (jamais de bascule configured, jamais d'exécution d'une clé inconnue) ;
  //  - sinon : configured devient true ; on résout la clé canonique ; on RETIRE de `enabled` la clé
  //    canonique ET ses alias reconnus ; on réécrit UNIQUEMENT la clé canonique avec le booléen
  //    choisi ; toutes les autres clés (fonctionnalités connues ET clés inconnues) sont préservées.
  //  - les clés dangereuses (__proto__/prototype/constructor) restent exclues (via normalize).
  function nextFeaturesConfig(features, key, nextEnabled) {
    // normalizeFeaturesSettings (04-settings-normalize.js, chargé avant) : nettoie enabled en booléens
    // stricts, exclut les clés dangereuses et PRÉSERVE les clés inconnues. Ne mute pas la source.
    const normalized = normalizeFeaturesSettings(features);
    if (nextEnabled !== true && nextEnabled !== false) return normalized;
    const canonical = resolveFeatureKey(key);
    if (!canonical) return normalized;
    const def = FEATURE_REGISTRY[canonical];
    const aliasesToDrop = new Set([canonical, ...((def && def.aliases) || [])]);
    const enabled = {};
    Object.keys(normalized.enabled).forEach((existingKey) => {
      if (aliasesToDrop.has(existingKey)) return; // canonique + alias reconnus retirés puis réécrits
      enabled[existingKey] = normalized.enabled[existingKey]; // clés inconnues / autres fonctions préservées
    });
    enabled[canonical] = nextEnabled;
    return { version: FEATURES_SCHEMA_VERSION, configured: true, enabled };
  }
  function hasAppPassword() {
    return Boolean(settings.security?.passwordSalt && settings.security?.passwordHash);
  }

  function randomSecurityToken(bytes = 16) {
    const values = new Uint8Array(bytes);
    if (window.crypto?.getRandomValues) {
      window.crypto.getRandomValues(values);
    } else {
      values.forEach((_, index) => values[index] = Math.floor(Math.random() * 256));
    }
    return Array.from(values).map((value) => value.toString(16).padStart(2, "0")).join("");
  }

  function bufferToHex(buffer) {
    return Array.from(new Uint8Array(buffer)).map((value) => value.toString(16).padStart(2, "0")).join("");
  }

  function fallbackPasswordHash(text) {
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, "0");
  }

  async function hashPassword(password, salt) {
    if (!window.crypto?.subtle) {
      throw new Error("Le chiffrement n'est pas disponible dans ce contexte (API Web Crypto requise).");
    }
    const encoder = new TextEncoder();
    const key = await window.crypto.subtle.importKey("raw", encoder.encode(password), "PBKDF2", false, ["deriveBits"]);
    const bits = await window.crypto.subtle.deriveBits({
      name: "PBKDF2",
      salt: encoder.encode(salt),
      iterations: 120000,
      hash: "SHA-256",
    }, key, 256);
    return `pbkdf2-sha256-v1:${bufferToHex(bits)}`;
  }

  async function verifyAppPassword(password) {
    if (!hasAppPassword()) return true;
    const stored = settings.security.passwordHash || "";
    // Compat : anciens mots de passe hachés avec FNV-1a (algorithme faible, ne plus créer)
    if (stored.startsWith("fallback-v1:")) {
      return stored === `fallback-v1:${fallbackPasswordHash(`${settings.security.passwordSalt}\n${password}`)}`;
    }
    try {
      const expected = await hashPassword(password, settings.security.passwordSalt);
      return expected === stored;
    } catch {
      return false;
    }
  }

  async function setAppPassword(password) {
    const now = new Date().toISOString();
    const salt = randomSecurityToken();
    settings.security = {
      ...(settings.security || {}),
      passwordSalt: salt,
      passwordHash: await hashPassword(password, salt),
      createdAt: settings.security?.createdAt || now,
      updatedAt: now,
    };
    persistSettings();
  }

  // Retire le mot de passe : le logiciel ne le demandera plus au démarrage ni avant le
  // vidage des données. On ne garde aucune empreinte (mot de passe ET code de récupération).
  function removeAppPassword() {
    const { passwordSalt, passwordHash, recoverySalt, recoveryHash, recoveryUpdatedAt, ...rest } = settings.security || {};
    settings.security = { ...rest, updatedAt: new Date().toISOString() };
    persistSettings();
  }

  // ===== Code de récupération (Phase 1) =====
  // Permet de redéfinir le mot de passe si l'utilisateur l'oublie. Le code n'est JAMAIS stocké en
  // clair : seul son hash PBKDF2 (+ salt dédié) est conservé dans settings.security. Le code est
  // affiché une seule fois à l'écran (création / changement / réinitialisation), à la charge de
  // l'utilisateur de le noter. Portée par club (settings.security est propre à chaque club).
  function hasRecoveryCode() {
    return Boolean(settings.security?.recoverySalt && settings.security?.recoveryHash);
  }

  // Alphabet sans caractères ambigus (pas de I, O, 0, 1, L) pour faciliter la recopie.
  function generateRecoveryCode() {
    const alphabet = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
    const length = 16;
    const values = new Uint8Array(length);
    if (window.crypto?.getRandomValues) window.crypto.getRandomValues(values);
    else values.forEach((_, index) => values[index] = Math.floor(Math.random() * 256));
    let raw = "";
    for (let index = 0; index < length; index += 1) raw += alphabet[values[index] % alphabet.length];
    return raw.match(/.{1,4}/g).join("-"); // ex. XXXX-XXXX-XXXX-XXXX
  }

  // Normalise la saisie : majuscules, sans tirets ni espaces (tolère la casse et les séparateurs).
  function normalizeRecoveryCode(code) {
    return asText(code).toUpperCase().replace(/[^A-Z0-9]/g, "");
  }

  async function hashRecoveryCode(code, salt) {
    return hashPassword(`recovery-code-v1\n${normalizeRecoveryCode(code)}`, salt);
  }

  // Génère un nouveau code, stocke uniquement son hash, et RENVOIE le code en clair pour
  // affichage unique. Régénérer invalide automatiquement l'ancien code (usage unique de fait).
  async function generateAndStoreRecoveryCode() {
    const code = generateRecoveryCode();
    const salt = randomSecurityToken();
    settings.security = {
      ...(settings.security || {}),
      recoverySalt: salt,
      recoveryHash: await hashRecoveryCode(code, salt),
      recoveryUpdatedAt: new Date().toISOString(),
    };
    persistSettings();
    return code;
  }

  async function verifyRecoveryCode(code) {
    if (!hasRecoveryCode()) return false;
    const normalized = normalizeRecoveryCode(code);
    if (!normalized) return false;
    try {
      const expected = await hashRecoveryCode(normalized, settings.security.recoverySalt);
      return expected === settings.security.recoveryHash;
    } catch {
      return false;
    }
  }

  function applyGateChrome() {
    document.documentElement.dataset.theme = settings.theme;
    applyThemeOverrides();
    applyTypographySettings();
    applyAppLogo();
  }

  // Bloc d'affichage du code de récupération (réutilisé porte de démarrage ET dialogue Paramètres).
  // Le code est affiché UNE SEULE FOIS ; il n'est jamais restitué ensuite.
  function recoveryCodeCardHtml(code) {
    return `<div class="recovery-code-box">
        <span class="recovery-code-label">Code de récupération</span>
        <code class="recovery-code-value" data-recovery-code>${esc(code)}</code>
        <button type="button" class="recovery-code-copy" data-recovery-copy>Copier</button>
      </div>
      <p class="recovery-code-warn"><strong>Conservez ce code.</strong> Il permet de réinitialiser le mot de passe si vous l'oubliez. Il ne sera plus affiché ensuite. Notez-le ou imprimez-le, et gardez-le en lieu sûr.</p>`;
  }

  function bindRecoveryCopy(root) {
    root.querySelector("[data-recovery-copy]")?.addEventListener("click", (event) => {
      const code = root.querySelector("[data-recovery-code]")?.textContent || "";
      try { window.navigator?.clipboard?.writeText?.(code); } catch { /* hors ligne : ignorer */ }
      const button = event.currentTarget;
      const previous = button.textContent;
      button.textContent = "Copié ✓";
      setTimeout(() => { button.textContent = previous; }, 1500);
    });
  }

  function renderPasswordGate(resolve, message = "") {
    applyGateChrome();
    const creating = !hasAppPassword();
    app.innerHTML = `<main class="password-gate">
      <form class="license-card password-card">
        <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
        <h2>${creating ? "Créer le mot de passe" : "Mot de passe"}</h2>
        <p class="muted">${creating ? "Ce mot de passe protégera l'ouverture du logiciel et le vidage des données. Un code de récupération vous sera fourni juste après." : "Entre le mot de passe du logiciel pour continuer."}</p>
        ${message ? `<div class="form-error">${esc(message)}</div>` : ""}
        <label>Mot de passe
          <input type="password" name="password" autocomplete="${creating ? "new-password" : "current-password"}" autofocus />
        </label>
        ${creating ? `<label>Confirmer
          <input type="password" name="confirmPassword" autocomplete="new-password" />
        </label>` : ""}
        <button class="primary" type="submit">${creating ? "Créer et ouvrir" : "Ouvrir"}</button>
        ${!creating && hasRecoveryCode() ? `<button type="button" class="link-like password-forgot" data-password-forgot>Mot de passe oublié ?</button>` : ""}
      </form>
    </main>`;
    const form = app.querySelector("form");
    form?.querySelector("input")?.focus();
    form?.querySelector("[data-password-forgot]")?.addEventListener("click", () => renderRecoveryGate(resolve));
    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const data = new FormData(form);
      const password = asText(data.get("password"));
      const confirmation = asText(data.get("confirmPassword"));
      if (creating && password.length < PASSWORD_MIN_LENGTH) {
        renderPasswordGate(resolve, `Le mot de passe doit contenir au moins ${PASSWORD_MIN_LENGTH} caractères.`);
        return;
      }
      if (creating) {
        if (password !== confirmation) {
          renderPasswordGate(resolve, "Les deux mots de passe ne correspondent pas.");
          return;
        }
        await setAppPassword(password);
        const code = await generateAndStoreRecoveryCode();
        renderRecoveryCodeScreen(resolve, code, "Mot de passe créé", "Votre mot de passe est créé. Voici votre code de récupération.");
        return;
      }
      if (!(await verifyAppPassword(password))) {
        renderPasswordGate(resolve, "Mot de passe incorrect.");
        return;
      }
      resolve();
    });
  }

  // Étape 1 de récupération : saisie du code de récupération.
  function renderRecoveryGate(resolve, message = "") {
    applyGateChrome();
    app.innerHTML = `<main class="password-gate">
      <form class="license-card password-card">
        <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
        <h2>Mot de passe oublié</h2>
        <p class="muted">Saisissez votre code de récupération pour définir un nouveau mot de passe. Aucune donnée ne sera supprimée.</p>
        <p class="muted recovery-backup-tip">Astuce : avant toute réinitialisation, pensez à conserver une sauvegarde JSON de vos données (depuis l'application, une fois connecté).</p>
        ${message ? `<div class="form-error">${esc(message)}</div>` : ""}
        <label>Code de récupération
          <input type="text" name="recoveryCode" autocomplete="off" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX" autofocus />
        </label>
        <button class="primary" type="submit">Vérifier le code</button>
        <button type="button" class="link-like" data-recovery-back>Retour</button>
      </form>
    </main>`;
    const form = app.querySelector("form");
    form?.querySelector("input")?.focus();
    form?.querySelector("[data-recovery-back]")?.addEventListener("click", () => renderPasswordGate(resolve));
    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const code = asText(new FormData(form).get("recoveryCode"));
      if (!(await verifyRecoveryCode(code))) {
        renderRecoveryGate(resolve, "Code de récupération incorrect.");
        return;
      }
      renderRecoveryNewPassword(resolve);
    });
  }

  // Étape 2 : définir un nouveau mot de passe après vérification du code.
  function renderRecoveryNewPassword(resolve, message = "") {
    applyGateChrome();
    app.innerHTML = `<main class="password-gate">
      <form class="license-card password-card">
        <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
        <h2>Nouveau mot de passe</h2>
        <p class="muted">Définissez un nouveau mot de passe. Un nouveau code de récupération sera généré.</p>
        ${message ? `<div class="form-error">${esc(message)}</div>` : ""}
        <label>Nouveau mot de passe
          <input type="password" name="password" autocomplete="new-password" autofocus />
        </label>
        <label>Confirmer
          <input type="password" name="confirmPassword" autocomplete="new-password" />
        </label>
        <button class="primary" type="submit">Définir le mot de passe</button>
      </form>
    </main>`;
    const form = app.querySelector("form");
    form?.querySelector("input")?.focus();
    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const data = new FormData(form);
      const password = asText(data.get("password"));
      const confirmation = asText(data.get("confirmPassword"));
      if (password.length < PASSWORD_MIN_LENGTH) {
        renderRecoveryNewPassword(resolve, `Le mot de passe doit contenir au moins ${PASSWORD_MIN_LENGTH} caractères.`);
        return;
      }
      if (password !== confirmation) {
        renderRecoveryNewPassword(resolve, "Les deux mots de passe ne correspondent pas.");
        return;
      }
      await setAppPassword(password);
      const code = await generateAndStoreRecoveryCode(); // invalide l'ancien code
      renderRecoveryCodeScreen(resolve, code, "Mot de passe réinitialisé", "Votre nouveau mot de passe est défini. Voici votre nouveau code de récupération (l'ancien ne fonctionne plus).");
    });
  }

  // Étape finale : afficher le code une seule fois puis ouvrir l'application.
  function renderRecoveryCodeScreen(resolve, code, title, intro) {
    applyGateChrome();
    app.innerHTML = `<main class="password-gate">
      <div class="license-card password-card recovery-card">
        <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
        <h2>${esc(title)}</h2>
        <p class="muted">${esc(intro)}</p>
        ${recoveryCodeCardHtml(code)}
        <button class="primary" type="button" data-recovery-continue>J'ai noté ce code, continuer</button>
      </div>
    </main>`;
    const card = app.querySelector(".recovery-card");
    bindRecoveryCopy(card);
    card.querySelector("[data-recovery-continue]")?.addEventListener("click", () => resolve());
  }

  function isDemoMode() {
    return DEMO_MODE;
  }

  function setupDemoClub() {
    const store = normalizeClubStore(rawClubStoreFromStorage() || clubStore);
    const hasRealData = store.clubs.some((club) => {
      const s = store.data[club.id]?.state;
      return s && (s.memberships?.length > 0 || s.shopOrders?.length > 0 || s.stages?.length > 0);
    });
    if (hasRealData) {
      loadActiveClubFromStore(store);
      settings.initialSetupDone = true;
      persistSettings();
      return;
    }
    const demoClub = demoClubIdentity();
    const demoState = buildDemoState(DEMO_CLUB_ID, demoClub);
    const demoSettings = demoSettingsForClub(demoClub);
    const nextStore = normalizeClubStore({
      ...store,
      clubs: [demoClub],
      activeClubId: DEMO_CLUB_ID,
      data: { [DEMO_CLUB_ID]: { state: demoState, settings: demoSettings } },
    });
    writeClubStore(nextStore);
    clubStore = nextStore;
    loadActiveClubFromStore(nextStore);
    settings.initialSetupDone = true;
    persistSettings();
    ui.view = "dashboard";
    ui.contactKind = "members";
  }

  function requirePasswordUnlock() {
    if (isDemoMode()) return Promise.resolve();
    // Le mot de passe est facultatif : s'il n'y en a pas ET que la configuration initiale est
    // déjà faite, l'utilisateur a volontairement choisi de ne pas en avoir -> on ouvre
    // directement, sans forcer la création. (Au tout premier lancement, la création reste proposée.)
    if (!hasAppPassword() && settings.initialSetupDone) return Promise.resolve();
    return new Promise((resolve) => renderPasswordGate(resolve));
  }

  function renderWelcomeWizard(resolve) {
    function applyTheme() {
      document.documentElement.dataset.theme = settings.theme;
      applyThemeOverrides();
      applyTypographySettings();
      applyAppLogo();
    }

    function renderChoice() {
      applyTheme();
      const benefits = [
        "Adhérents, inscriptions et documents au même endroit.",
        "Planning des cours, présences et disponibilités des salles et coachs.",
        "Factures, paiements, avoirs et suivi des règlements.",
      ];
      const modules = [
        "Contacts", "Disciplines", "Groupes", "Coachs", "Salles", "Planning",
        "Présences", "Factures", "Stages", "Boutique", "Disponibilités",
      ];
      app.innerHTML = `<main class="password-gate">
        <div class="welcome-card welcome-card-intro">
          <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
          <div class="welcome-headline">
            <h2>Gérez votre club, simplement.</h2>
            <p class="welcome-subtitle">MonGestaClub réunit vos adhérents, votre planning, vos présences et votre facturation dans un seul logiciel, 100 % sur votre ordinateur.</p>
          </div>
          <ul class="welcome-benefits">
            ${benefits.map((text) => `<li>${esc(text)}</li>`).join("")}
          </ul>
          <ul class="welcome-modules" aria-label="Modules disponibles">
            ${modules.map((name) => `<li class="welcome-module-chip">${esc(name)}</li>`).join("")}
          </ul>
          <div class="welcome-choice-grid">
            <button type="button" class="welcome-choice welcome-choice-primary" data-welcome-action="create">
              <strong>Créer un nouveau club</strong>
              <span>Assistant guidé : identité, activités sportives, installations, groupes. Tout reste modifiable ensuite.</span>
            </button>
            <button type="button" class="welcome-choice" data-welcome-action="import">
              <strong>Importer une sauvegarde</strong>
              <span>Restaurez un club à partir d'un fichier exporté précédemment.</span>
            </button>
            <button type="button" class="welcome-choice" data-welcome-action="demo">
              <strong>Essayer la démo</strong>
              <span>Découvrez le logiciel avec un club fictif déjà rempli.</span>
            </button>
          </div>
          <div class="welcome-demo-note">
            <strong>La démo, sans risque.</strong>
            <p>Elle ouvre un club fictif avec des données d'exemple. Vos vraies données ne sont jamais modifiées.</p>
            <p class="welcome-demo-try">Vous pouvez tester : ajouter un adhérent, construire un planning, faire l'appel, éditer une facture, encaisser un paiement, gérer la boutique et les stages.</p>
          </div>
          <p class="welcome-reassurance">100 % local · aucune donnée envoyée sur Internet · tout reste modifiable</p>
        </div>
      </main>`;
      // Lot 2 — « Créer un nouveau club » ouvre désormais l'assistant multisports guidé
      // (remplace l'ancien formulaire mono-discipline renderCreate, conservé pour compatibilité).
      app.querySelector("[data-welcome-action='create']")?.addEventListener("click", () => startClubWizard({ resolve }));
      // Lot 2 (correctif) — l'import depuis l'accueil passe par un contexte de premier lancement :
      // après un import valide, le club importé devient actif, le provisoire vide disparaît et le
      // premier lancement est résolu (cf. beginFirstLaunchImport / finalizeFirstLaunchImport, src/22).
      app.querySelector("[data-welcome-action='import']")?.addEventListener("click", () => beginFirstLaunchImport(resolve));
      app.querySelector("[data-welcome-action='demo']")?.addEventListener("click", handleDemo);
    }

    function renderCreate() {
      applyTheme();
      app.innerHTML = `<main class="password-gate">
        <form class="welcome-card">
          <img src="${esc(appLogoSrc())}" alt="${esc(settings.clubName || "MonGestaClub")}" />
          <h2>Créer mon club</h2>
          <p class="muted">Le minimum pour démarrer. Tout restera modifiable ensuite dans Paramètres.</p>
          <label>Nom du club<input type="text" name="clubName" value="${esc(settings.clubName || "")}" placeholder="Mon club" autofocus /></label>
          <label>Sous-titre<input type="text" name="clubSubtitle" value="${esc(settings.clubSubtitle || "")}" placeholder="Gestion de club" /></label>
          <label>Discipline principale<input type="text" name="mainDiscipline" placeholder="Ex : Judo, Karaté, Football..." /></label>
          <label>Logo du club<input type="file" name="setupLogo" accept="image/*" /></label>
          <label>Thème<select name="theme">
            ${themes.map((t) => `<option value="${esc(t.id)}" ${settings.theme === t.id ? "selected" : ""}>${esc(t.name)}</option>`).join("")}
          </select></label>
          <div class="inline-actions">
            <button type="button" data-welcome-action="back">Retour</button>
            <button type="submit" class="primary">Créer et ouvrir</button>
          </div>
        </form>
      </main>`;
      const form = app.querySelector("form");
      form?.querySelector("[data-welcome-action='back']")?.addEventListener("click", renderChoice);
      form?.addEventListener("change", async (event) => {
        if (event.target.name === "theme") {
          settings.theme = event.target.value;
          document.documentElement.dataset.theme = settings.theme;
          applyThemeOverrides();
        }
        if (event.target.name === "setupLogo") {
          const file = event.target.files?.[0];
          if (file?.type?.startsWith("image/")) {
            settings.logoDataUrl = await logoFileToDataUrl(file);
            applyAppLogo();
            form.querySelector("img").src = appLogoSrc();
          }
        }
      });
      form?.addEventListener("submit", async (event) => {
        event.preventDefault();
        const data = new FormData(form);
        const clubName = asText(data.get("clubName")) || "Mon club";
        const clubSubtitle = asText(data.get("clubSubtitle")) || "Gestion de club";
        const mainDiscipline = asText(data.get("mainDiscipline"));
        settings.clubName = clubName;
        settings.clubSubtitle = clubSubtitle;
        settings.theme = data.get("theme") || settings.theme;
        settings.initialSetupDone = true;
        persistSettings();
        const existingClub = activeClub();
        const club = defaultClubIdentity({
          clubId: existingClub?.id,
          clubName,
          clubSubtitle,
          theme: settings.theme,
          logoDataUrl: settings.logoDataUrl,
        });
        if (mainDiscipline) {
          club.mainDiscipline = mainDiscipline;
          club.disciplines = [mainDiscipline];
        }
        try {
          saveClub(club, { activate: true, create: false, seedMainDiscipline: true });
        } catch (error) {
          console.error(error);
          alert(error.message || "Impossible de créer le club.");
          return;
        }
        resolve();
      });
    }

    async function handleDemo() {
      // Choix Démo depuis l'accueil : tout contexte d'import de premier lancement en attente
      // (ex. sélecteur ouvert puis annulé) est effacé pour éviter toute fuite.
      if (typeof clearFirstLaunchImportContext === "function") clearFirstLaunchImportContext();
      setupDemoClub();
      ui.saveMessage = `${DEMO_CLUB_NAME} prêt`;
      resolve();
      // Intro spécifique démo, une fois par entrée dans la démo (au clic « Essayer la démo »).
      // Différée après le premier render() : resolve() enchaîne les microtâches d'initApp
      // (requireInitialSetup → statut licence → render), le setTimeout(0) macrotâche passe ensuite,
      // donc le dialogue s'affiche par-dessus l'app rendue. Aucun stockage : ne revient pas à la
      // navigation, réapparaît seulement si l'utilisateur ré-entre volontairement dans la démo.
      setTimeout(() => { try { showDemoIntroDialog(); } catch (error) { /* jamais bloquer la démo */ } }, 0);
    }

    renderChoice();
  }

  // Petite intro affichée à l'entrée dans le club de démonstration. Réutilise le dialogue modal
  // existant (classes .dialog-*) ; aucune modification des données ni du contenu de la démo.
  // Garde de session (mémoire volatile, jamais persistée) : l'intro s'affiche au plus une fois
  // par session, quel que soit le déclencheur (« Essayer la démo » en Electron, chargement direct
  // en démo web) — pas de réapparition à la navigation, pas de double affichage.
  let demoIntroShownThisSession = false;
  function showDemoIntroDialog() {
    if (demoIntroShownThisSession) return;
    if (typeof activeClubId === "function" && activeClubId() !== DEMO_CLUB_ID) return;
    if (typeof dialogForNewWindow !== "function" || typeof showFloatingDialog !== "function") return;
    demoIntroShownThisSession = true;
    const targetDialog = dialogForNewWindow();
    targetDialog.classList.remove("has-identity-photo");
    targetDialog.innerHTML = `<div class="demo-intro">
      <div class="dialog-header"><h2>Vous explorez le club de démo</h2><button class="icon" type="button" data-dialog-close title="Fermer" aria-label="Fermer">×</button></div>
      <div class="dialog-body">
        <p>Toutes les données sont fictives : vous pouvez modifier, tester et supprimer librement. Votre vrai club n'est pas affecté.</p>
        <p class="muted">Essayez par exemple d'ajouter un adhérent, de consulter le planning, de faire l'appel ou d'éditer une facture.</p>
      </div>
      <div class="dialog-footer"><span></span><button type="button" class="primary" data-dialog-close>J'ai compris</button></div>
    </div>`;
    targetDialog.querySelectorAll("[data-dialog-close]").forEach((button) => button.addEventListener("click", () => targetDialog.close()));
    showFloatingDialog(targetDialog, "[data-dialog-close].primary", targetDialog);
  }

  function requireInitialSetup() {
    if (isDemoMode()) {
      setupDemoClub();
      // Démo web (MONGESTACLUB_DEMO / ?demo) : le premier lancement est court-circuité, donc
      // l'intro « Vous explorez le club de démo » (déclenchée par « Essayer la démo » en Electron)
      // ne passerait jamais. On l'affiche ici, différée après le premier render() (même mécanique
      // que handleDemo). Pas de double affichage possible : en Electron isDemoMode() est faux
      // (cette branche ne s'exécute pas) et en démo web le wizard/handleDemo ne s'exécute jamais ;
      // la garde de session dans showDemoIntroDialog verrouille le tout.
      setTimeout(() => { try { showDemoIntroDialog(); } catch (error) { /* jamais bloquer la démo */ } }, 0);
      return Promise.resolve();
    }
    if (settings.initialSetupDone) return Promise.resolve();
    // Sécurité : si des données réelles existent, marquer comme configuré sans afficher le wizard
    try {
      const store = normalizeClubStore(rawClubStoreFromStorage());
      const hasRealData = store.clubs.some((club) => {
        const s = store.data[club.id]?.state;
        return s && (s.memberships?.length > 0 || s.shopOrders?.length > 0 || s.stages?.length > 0);
      });
      if (hasRealData) {
        settings.initialSetupDone = true;
        persistSettings();
        return Promise.resolve();
      }
    } catch {
      return Promise.resolve();
    }
    return new Promise((resolve) => renderWelcomeWizard(resolve));
  }

  function isLogoDataUrl(value) {
    return typeof value === "string" && /^data:image\/(png|jpe?g|webp|gif);base64,/i.test(value);
  }

  function isImageDataUrl(value) {
    return typeof value === "string" && /^data:image\/(png|jpe?g|webp|gif);base64,/i.test(value);
  }

  function appLogoSrc() {
    return settings.logoDataUrl || DEFAULT_LOGO;
  }

  // Logo par défaut (asset bundlé) converti en data URL et mis en cache. Nécessaire pour les
  // documents imprimés/PDF (fenêtre vierge sans base URL : un chemin relatif ne résout pas) et pour
  // afficher le logo sur les factures quand le club n'a pas de logo personnalisé. Échec silencieux ->
  // chaîne vide -> fallback initiales (jamais de facture cassée).
  let defaultLogoDataUrlCache = "";
  let defaultLogoLoading = null;
  async function preloadDefaultLogoDataUrl() {
    if (defaultLogoDataUrlCache) return defaultLogoDataUrlCache;
    if (defaultLogoLoading) return defaultLogoLoading;
    defaultLogoLoading = (async () => {
      try {
        const res = await fetch(DEFAULT_LOGO);
        if (!res.ok) return "";
        const blob = await res.blob();
        const dataUrl = await new Promise((resolve) => {
          const reader = new FileReader();
          reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
          reader.onerror = () => resolve("");
          reader.readAsDataURL(blob);
        });
        if (isLogoDataUrl(dataUrl)) defaultLogoDataUrlCache = dataUrl;
      } catch { /* asset introuvable -> on reste sur le fallback initiales */ }
      defaultLogoLoading = null;
      return defaultLogoDataUrlCache;
    })();
    return defaultLogoLoading;
  }
  function defaultLogoDataUrl() {
    // Déclenche un chargement paresseux si le préchargement de démarrage n'a pas (encore) abouti :
    // la prochaine ouverture de facture aura le logo. Tant qu'indisponible -> "" -> fallback initiales.
    if (!defaultLogoDataUrlCache) { preloadDefaultLogoDataUrl(); return ""; }
    return isLogoDataUrl(defaultLogoDataUrlCache) ? defaultLogoDataUrlCache : "";
  }

  function identityPhoto(row = {}) {
    const linked = contactByLink(contactLinkForRow(row)) || {};
    return row.identityPhotoDataUrl || linked.identityPhotoDataUrl || "";
  }

  function identityNameKey(value) {
    return asText(value)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .split(/[\s-]+/)[0] || "";
  }

  function identityGenderHint(row = {}) {
    const explicit = identityNameKey(row.gender || row.sexe || row.sex || row.civility || row.civilite);
    if (["f", "femme", "female", "madame", "mme", "mlle"].includes(explicit)) return "female";
    if (["m", "homme", "male", "monsieur", "mr", "m"].includes(explicit)) return "male";
    const firstName = identityNameKey(row.firstName || row.prenom);
    if (FEMALE_FIRST_NAMES.has(firstName)) return "female";
    if (MALE_FIRST_NAMES.has(firstName)) return "male";
    if (/(ette|elle|ine|ane|ise|ia|a)$/.test(firstName)) return "female";
    return "male";
  }

  function normalizeIdentityAvatarChoice(value) {
    const key = asText(value).toLowerCase();
    return IDENTITY_AVATAR_CHOICES.some(([choice]) => choice === key) ? key : "auto";
  }

  function identityAvatarChoice(row = {}) {
    const linked = contactByLink(contactLinkForRow(row)) || {};
    return normalizeIdentityAvatarChoice(row.identityAvatarChoice || linked.identityAvatarChoice || "auto");
  }

  function identityAvatarKind(row = {}) {
    const manualChoice = identityAvatarChoice(row);
    if (manualChoice !== "auto") return manualChoice;
    const linked = contactByLink(contactLinkForRow(row)) || {};
    const source = { ...linked, ...row };
    const category = identityNameKey(source.category || memberCategory(source));
    const age = ageFromBirthDate(source.birthDate);
    const child = Number.isFinite(age) ? age < 18 : /enfant|baby|ado|junior|kid/.test(category);
    const female = identityGenderHint(source) === "female";
    if (child) return female ? "girl" : "boy";
    return female ? "woman" : "man";
  }

  function identityAvatarSrc(row = {}) {
    return DEFAULT_IDENTITY_AVATARS[identityAvatarKind(row)] || DEFAULT_IDENTITY_AVATARS.man;
  }

  function identityPhotoDisplaySrc(row = {}) {
    return identityPhoto(row) || identityAvatarSrc(row);
  }

  function identityPhotoInitials(row = {}) {
    const first = asText(row.firstName).charAt(0);
    const last = asText(row.lastName).charAt(0);
    return `${first}${last}`.trim().toUpperCase() || "?";
  }

  function identityPhotoSection(row = {}, editable = true) {
    const src = identityPhoto(row);
    const displaySrc = src || identityAvatarSrc(row);
    const defaultAvatarClass = src ? "" : "default-avatar";
    return `<div class="identity-photo-corner" data-identity-photo-widget ${editable ? "" : "data-identity-photo-readonly"}>
      <button class="identity-photo-frame ${defaultAvatarClass}" type="button" data-action="open-identity-photo" title="${src ? "Ouvrir la photo" : "Ouvrir la silhouette / ajouter une photo"}" data-avatar-src="${esc(displaySrc)}">
        <img src="${esc(displaySrc)}" alt="${src ? "Photo" : "Silhouette"} de ${esc(personLabel(row) || "contact")}" data-identity-photo-preview />
      </button>
      <input type="hidden" name="identityPhotoDataUrl" value="${esc(src)}" data-identity-photo-value />
    </div>`;
  }

  function identityAvatarChoiceField(row = {}) {
    const selected = identityAvatarChoice(row);
    const customized = selected && selected !== "auto";
    // Option secondaire (silhouette par défaut) repliée pour ne pas alourdir le haut du
    // formulaire : le formulaire commence par les vrais champs (Nom, Prénom…). Le select
    // reste dans le DOM (sa valeur est bien enregistrée même replié). Ouverte si personnalisée.
    return `<details class="field-secondary identity-avatar-details" ${customized ? "open" : ""}>
      <summary>Silhouette par défaut${customized ? " · personnalisée" : ""}</summary>
      <label class="identity-avatar-choice">Silhouette si aucune photo
        <select name="identityAvatarChoice" data-identity-avatar-choice>
          ${IDENTITY_AVATAR_CHOICES.map(([value, label]) => `<option value="${esc(value)}" ${value === selected ? "selected" : ""}>${esc(label)}</option>`).join("")}
        </select>
        <small>Automatique choisit selon le prénom et l'âge. Tu peux forcer une silhouette si besoin.</small>
      </label>
    </details>`;
  }

  function applyAppLogo() {
    const logo = appLogoSrc();
    let favicon = document.querySelector('link[rel~="icon"]');
    if (!favicon) {
      favicon = document.createElement("link");
      favicon.rel = "icon";
      document.head.appendChild(favicon);
    }
    favicon.type = "image/png";
    favicon.href = logo;
    window.monGestaClubShell?.setAppLogo?.(settings.logoDataUrl || "");
  }

  function applyVat20MigrationIfNeeded() {
    state.meta = state.meta || {};
    if (state.meta[LEGACY_VAT20_MIGRATION_KEY] && !state.meta[VAT20_MIGRATION_KEY]) {
      state.meta[VAT20_MIGRATION_KEY] = state.meta[LEGACY_VAT20_MIGRATION_KEY];
      delete state.meta[LEGACY_VAT20_MIGRATION_KEY];
    }
  }

  function applyVat20Everywhere() {
    applyVat20MigrationIfNeeded();
  }

  function setPaymentsVat20(payments = []) {
    return payments;
  }

  function migrateObsoleteSourceKeys(value, seen = new WeakSet()) {
    if (!value || typeof value !== "object") return value;
    if (seen.has(value)) return value;
    seen.add(value);
    const oldKey = ["ex", "cel"].join("");
    if (Object.prototype.hasOwnProperty.call(value, oldKey)) {
      value.legacy = value.legacy || value[oldKey];
      delete value[oldKey];
    }
    Object.values(value).forEach((item) => migrateObsoleteSourceKeys(item, seen));
    return value;
  }

  // Auto-réparation : retire les doublons EXACTS par id (deux objets au même id = corruption,
  // ex. « Peupler avec la démo → Ajouter » appliqué deux fois). Garde la 1re occurrence. Les
  // éléments sans id sont conservés. Ne fusionne JAMAIS deux objets d'ids différents (deux
  // groupes de même nom mais d'ids distincts restent distincts).
  function dedupeById(arr) {
    if (!Array.isArray(arr)) return arr;
    const seen = new Set();
    const out = [];
    arr.forEach((item) => {
      const itemId = item && typeof item === "object" ? item.id : undefined;
      if (!itemId) { out.push(item); return; }
      if (seen.has(itemId)) return;
      seen.add(itemId);
      out.push(item);
    });
    return out;
  }

  // ------------------------------------------------------------------------------------------------
  // Lot 3A — IDENTITÉ CANONIQUE DES DISCIPLINES (transition additive, non destructive).
  //  - `discipline.id` devient l'identité canonique ; le libellé (`name`) est conservé pour
  //    l'affichage, la recherche, les exports lisibles et le repli des anciennes données ;
  //  - les références métier (memberships/groups/planningCourses) portent `disciplineId` en plus de
  //    `discipline` (texte historique) ; les collections de coachs/salles conservent leurs listes de
  //    NOMS et reçoivent une liste d'`id` DÉRIVÉE (recomputée à chaque normalisation, idempotente) ;
  //  - aucune fusion automatique de disciplines : les doublons de nom sont conservés (ambiguïté), et
  //    un ancien nom non résolu (absent ou ambigu) n'est jamais supprimé silencieusement.
  // ------------------------------------------------------------------------------------------------
  // Clé de comparaison des libellés : insensible à la casse, aux espaces de bord et à la forme
  // Unicode (NFC), mais SENSIBLE aux accents — cohérent avec le rattachement historique par `===`
  // exact (accent-sensible) déjà en place dans le code (évite toute sur-fusion « Café »/« Cafe »).
  function disciplineNameKey(value) {
    return asText(value).normalize("NFC").trim().toLowerCase();
  }
  function disciplinesListFrom(src) {
    const s = src || (typeof state !== "undefined" ? state : null);
    return (s && s.tariffs && Array.isArray(s.tariffs.disciplines)) ? s.tariffs.disciplines : [];
  }
  function disciplineById(disciplineId, src) {
    const key = asText(disciplineId);
    if (!key) return null;
    return disciplinesListFrom(src).find((d) => d && d.id === key) || null;
  }
  function disciplinesByNameKey(name, src) {
    const key = disciplineNameKey(name);
    if (!key) return [];
    return disciplinesListFrom(src).filter((d) => d && disciplineNameKey(d.name) === key);
  }
  // Résolution NON AMBIGUË d'un nom vers un id, dans le club fourni (ou le club actif par défaut).
  // Retourne "" si aucune discipline ne porte ce nom OU si plusieurs le portent (ambiguïté).
  function resolveDisciplineIdByName(name, src) {
    const matches = disciplinesByNameKey(name, src);
    return matches.length === 1 ? asText(matches[0].id) : "";
  }
  // Libellé d'affichage : privilégie la discipline RÉSOLUE PAR ID (canonique), repli sur le libellé
  // historique stocké (jamais supprimé, y compris si l'id est vide ou pointe une discipline absente).
  function disciplineLabelFor(entity, src) {
    if (!entity || typeof entity !== "object") return "";
    const byId = disciplineById(entity.disciplineId, src);
    return byId ? asText(byId.name) : asText(entity.discipline);
  }
  // Noms de disciplines en doublon (même clé sur ≥ 2 entrées) — pour détection/diagnostic, jamais
  // pour fusionner. Retourne un Set de clés.
  function duplicateDisciplineNameKeys(src) {
    const counts = new Map();
    disciplinesListFrom(src).forEach((d) => {
      const key = disciplineNameKey(d && d.name);
      if (key) counts.set(key, (counts.get(key) || 0) + 1);
    });
    const dups = new Set();
    counts.forEach((n, key) => { if (n > 1) dups.add(key); });
    return dups;
  }
  // Passe centrale de résolution des références de discipline sur un état donné (par club).
  //  - memberships/groups/planningCourses : `disciplineId` rempli UNIQUEMENT s'il est vide ET que le
  //    nom stocké se résout sans ambiguïté ; un id déjà présent (canonique) n'est jamais écrasé. Une
  //    fois l'id RÉSOLU (préexistant ou tout juste rempli), le libellé `discipline` est ALIGNÉ sur le
  //    nom courant de la discipline canonique s'il diffère — répare un libellé devenu obsolète après
  //    un renommage (ex. syncDisciplineName mal invoquée), quelle que soit la collection ou son statut
  //    archivé/actif (l'archivage ne fige jamais ce libellé). Un id INCONNU (discipline absente) ne
  //    modifie JAMAIS le libellé existant, ne l'efface ni ne l'invente. Portée strictement limitée à
  //    ces trois collections : factures, journal d'audit et historique ne portent pas ce couple
  //    id/nom et restent hors d'atteinte par construction ;
  //  - coachs/salles : listes d'`id` DÉRIVÉES des listes de noms (les noms restent la source éditée) ;
  //    les noms non résolus sont conservés, aucun n'est supprimé.
  // Idempotente : deux passes successives sur les mêmes données produisent le même résultat.
  function resolveDisciplineReferences(base) {
    if (!base || typeof base !== "object") return base;
    const fill = (entity) => {
      if (!entity || typeof entity !== "object") return;
      if (!asText(entity.disciplineId)) {
        entity.disciplineId = resolveDisciplineIdByName(entity.discipline, base);
      }
      const resolved = disciplineById(entity.disciplineId, base);
      if (resolved && asText(resolved.name) && entity.discipline !== resolved.name) {
        entity.discipline = resolved.name;
      }
    };
    (Array.isArray(base.memberships) ? base.memberships : []).forEach(fill);
    (Array.isArray(base.groups) ? base.groups : []).forEach(fill);
    (Array.isArray(base.planningCourses) ? base.planningCourses : []).forEach(fill);
    // Coachs / salles (D1) : identité CANONIQUE par identifiant. resolveEntityDisciplines fait, dans
    // l'ordre : (1) union non destructive des id (existants ∪ dérivés non ambigus des noms) ; (2)
    // extraction des valeurs libres/historiques non couvertes par un id sélectionné ; (3) liste de
    // NOMS de compat DÉRIVÉE des id (nom courant) + valeurs libres. Idempotent, isolé par club.
    (Array.isArray(base.coaches) ? base.coaches : []).forEach((coach) => reconcileEntityDisciplines(coach, "specialtyDisciplineIds", "specialties", "specialtiesFree", base));
    (Array.isArray(base.rooms) ? base.rooms : []).forEach((room) => reconcileEntityDisciplines(room, "disciplineIds", "disciplines", "disciplinesFree", base));
    return base;
  }

  // Noms canoniques (nom COURANT) d'une liste d'id de disciplines, dans l'ordre. Les id inconnus
  // (discipline absente) ne produisent aucun nom (mais restent conservés dans la liste d'id).
  function canonicalDisciplineNames(idList, src) {
    return (Array.isArray(idList) ? idList : [])
      .map((did) => disciplineById(did, src))
      .filter(Boolean)
      .map((d) => asText(d.name))
      .filter(Boolean);
  }

  // Lot 3A — CIBLE de compatibilité de discipline. Accepte un nom (legacy) OU un objet
  // { disciplineId, discipline }. Les appelants qui disposent d'un identifiant (course/group.disciplineId)
  // doivent le transmettre : le nom seul ne doit jamais élargir une compatibilité vers un homonyme.
  function disciplineTargetOf(target) {
    if (target && typeof target === "object") return { disciplineId: asText(target.disciplineId), discipline: asText(target.discipline) };
    return { disciplineId: "", discipline: asText(target) };
  }
  // Construit une cible canonique depuis un NOM choisi dans un select (libellé) et l'entité éditée :
  // id résolu si non ambigu ; à défaut, id existant de l'entité si le nom n'a pas changé ; sinon "".
  // Utilisé par les dialogues groupe/cours dont le select de discipline reste libellé par nom.
  function disciplineTargetFromName(name, priorEntity, src) {
    const nm = asText(name);
    const resolved = resolveDisciplineIdByName(nm, src);
    const kept = (priorEntity && disciplineNameKey(nm) === disciplineNameKey(priorEntity.discipline)) ? asText(priorEntity.disciplineId) : "";
    return { disciplineId: resolved || kept, discipline: nm };
  }
  // Lot 3A (clôture) — cible CANONIQUE depuis la valeur d'un select de discipline PAR IDENTIFIANT
  // (dialogues Inscription/Groupe/Cours). La chaîne correcte est : id sélectionné → disciplineById(id)
  // → nom d'affichage. Valeurs possibles (jamais de résolution nominale après une sélection) :
  //  - un id de discipline connu : { disciplineId: id, discipline: nom courant } (homonymes distincts) ;
  //  - "__unknown__:<id encodé>" : identifiant RÉEL mais absent du référentiel → on PRÉSERVE cet id et
  //    le libellé historique de l'entité (aucune rétrogradation vers un id résolu par nom) ;
  //  - "__legacy__" : donnée héritée SANS id → on préserve l'id (vide) et le libellé historique, sans
  //    choisir arbitrairement un homonyme ;
  //  - "" (aucune) : { disciplineId: "", discipline: "" }.
  const UNKNOWN_DISCIPLINE_PREFIX = "__unknown__:";
  function disciplineTargetFromSelectValue(value, priorEntity, src) {
    const v = asText(value);
    if (v.slice(0, UNKNOWN_DISCIPLINE_PREFIX.length) === UNKNOWN_DISCIPLINE_PREFIX) {
      let decoded = v.slice(UNKNOWN_DISCIPLINE_PREFIX.length);
      try { decoded = decodeURIComponent(decoded); } catch (_e) { /* valeur déjà brute */ }
      return { disciplineId: asText(decoded), discipline: asText(priorEntity && priorEntity.discipline) };
    }
    if (v === "__legacy__") {
      return { disciplineId: asText(priorEntity && priorEntity.disciplineId), discipline: asText(priorEntity && priorEntity.discipline) };
    }
    if (v) {
      const d = disciplineById(v, src);
      return { disciplineId: v, discipline: d ? asText(d.name) : asText(priorEntity && priorEntity.discipline) };
    }
    return { disciplineId: "", discipline: "" };
  }
  // Lot 3A (clôture financière) — définition tarifaire d'une CIBLE issue d'un select canonique
  // (FIN-1). Jamais de tarification par nom homonyme :
  //  - cible avec disciplineId CONNU → la discipline correspondante (prix/licence/TVA de CET id) ;
  //  - cible avec disciplineId INCONNU (absent du référentiel) → aucune définition actuelle (null) ;
  //  - cible sans id → résolution nominale UNIQUEMENT si le nom désigne exactement une discipline ;
  //    un nom ambigu ou absent ne fournit AUCUNE définition (null).
  function disciplineDefinitionFromTarget(target, src) {
    const id = asText(target && target.disciplineId);
    if (id) return disciplineById(id, src) || null;
    const uid = resolveDisciplineIdByName(target && target.discipline, src);
    return uid ? (disciplineById(uid, src) || null) : null;
  }
  // Lot 3A (clôture) — compatibilité CANONIQUE Groupe ↔ discipline d'un Cours (F-GRP-1). Le nom
  // n'élargit jamais la compatibilité :
  //  - groupe sans aucune discipline déclarée (ni id ni nom) : non restreint → compatible ;
  //  - cours sans aucune discipline : tous les groupes ;
  //  - les deux avec id : égalité stricte des identifiants ;
  //  - un côté id / l'autre nom (legacy) : compatible seulement si le nom désigne UNE seule discipline,
  //    et que c'est bien celle de l'id ; un nom ambigu ne rend jamais compatible ;
  //  - les deux par nom : compatible seulement si le nom est unique et identique.
  function groupMatchesCourseDiscipline(group, course, src) {
    const cId = asText(course && course.disciplineId);
    const gId = asText(group && group.disciplineId);
    const cName = asText(course && course.discipline);
    const gName = asText(group && group.discipline);
    if (!gId && !gName) return true;            // groupe non restreint
    if (!cId && !cName) return true;            // cours sans discipline
    if (cId && gId) return cId === gId;         // identité canonique stricte
    if (cId) {                                  // cours par id, groupe par nom (legacy)
      const m = disciplinesByNameKey(gName, src);
      return m.length === 1 && asText(m[0].id) === cId;
    }
    // cours par nom (legacy)
    if (disciplinesByNameKey(cName, src).length !== 1) return false; // nom du cours ambigu → aucune compat
    if (gId) { const gd = disciplineById(gId, src); return Boolean(gd) && disciplineNameKey(gd.name) === disciplineNameKey(cName); }
    return disciplineNameKey(gName) === disciplineNameKey(cName);
  }
  // Une entité (coach/salle) prend-elle en charge la CIBLE ? Règles canoniques (aucune sous-chaîne) :
  //  - entité SANS aucune déclaration (ni id, ni valeur libre) : renvoie `emptyUnrestrictedMeansAll`
  //    (coachs : false = non éligible ; salles : true = « accueille tout ») — comportement historique ;
  //  - cible AVEC id : compatibilité = présence EXACTE de l'id dans les id canoniques de l'entité
  //    (les noms/valeurs libres n'élargissent JAMAIS) ;
  //  - cible SANS id (legacy) : repli nominal UNIQUEMENT si le nom désigne EXACTEMENT UNE discipline
  //    du référentiel. Un nom absent (0) ou AMBIGU (≥ 2 homonymes) ne désigne ni l'une ni l'autre →
  //    aucune compatibilité canonique automatique (D-LEG-1). Les valeurs libres (`entityFree`) ne
  //    rendent jamais compatible avec une discipline.
  function entityHandlesDisciplineTarget(entityIds, entityFree, target, src, emptyUnrestrictedMeansAll) {
    const tgt = disciplineTargetOf(target);
    if (!tgt.disciplineId && !tgt.discipline) return true;
    const ids = (Array.isArray(entityIds) ? entityIds : []).map((x) => asText(x)).filter(Boolean);
    const free = (Array.isArray(entityFree) ? entityFree : []).map((x) => asText(x)).filter(Boolean);
    if (ids.length === 0 && free.length === 0) return Boolean(emptyUnrestrictedMeansAll);
    if (tgt.disciplineId) return ids.includes(tgt.disciplineId);
    const key = disciplineNameKey(tgt.discipline);
    if (!key) return true;
    // Cible legacy (sans id) : le nom ne fait autorité que s'il est NON AMBIGU dans le référentiel.
    if (disciplinesByNameKey(tgt.discipline, src).length !== 1) return false;
    return new Set(canonicalDisciplineNames(ids, src).map(disciplineNameKey)).has(key);
  }

  // Vue de sélection des disciplines d'un coach/salle : sépare les id canoniques RÉSOLUS, les id
  // INCONNUS (discipline supprimée/importée), et les noms LIBRES/HISTORIQUES non couverts par un id
  // sélectionné (anciens noms ambigus, valeurs libres). Aucune conversion arbitraire ; aucune
  // duplication entre un nom canonique (dérivé d'un id sélectionné) et une valeur libre.
  // Lot 2B — `archivedIds` : SOUS-ENSEMBLE de `selectedIds` dont la discipline est `archived === true`.
  // Contrat historique PRÉSERVÉ : `selectedIds` continue de contenir TOUTE référence connue (active ou
  // archivée), exactement comme avant ce lot — un appelant qui l'ignore garde le comportement actuel.
  // `archivedIds` est la seule information NOUVELLE, ajoutée pour permettre à l'UI de distinguer les
  // deux sans jamais faire tomber une discipline archivée mais connue dans `unknownIds` (réservé aux id
  // réellement absents du référentiel) ni dans `freeNames` (resolvedKeys inclut toujours son nom).
  function disciplineSelectionView(idList, nameList, src) {
    const seenId = new Set();
    const selectedIds = [];
    const archivedIds = [];
    const unknownIds = [];
    (Array.isArray(idList) ? idList : []).map((x) => asText(x)).filter(Boolean).forEach((did) => {
      if (seenId.has(did)) return;
      seenId.add(did);
      const discipline = disciplineById(did, src);
      if (!discipline) { unknownIds.push(did); return; }
      selectedIds.push(did);
      if (discipline.archived === true) archivedIds.push(did);
    });
    const resolvedKeys = new Set(selectedIds.map((did) => disciplineNameKey(disciplineById(did, src).name)).filter(Boolean));
    const seenFree = new Set();
    const freeNames = [];
    (Array.isArray(nameList) ? nameList : []).map((x) => asText(x)).filter(Boolean).forEach((n) => {
      const k = disciplineNameKey(n);
      if (!k || resolvedKeys.has(k) || seenFree.has(k)) return;
      seenFree.add(k);
      freeNames.push(n);
    });
    return { selectedIds, archivedIds, unknownIds, freeNames };
  }

  // Libellé d'option DISTINCTIF pour un formulaire : ajoute « — discipline N » UNIQUEMENT si le nom
  // est partagé par plusieurs disciplines (homonymes), N = rang déterministe (ordre du référentiel).
  // N'altère JAMAIS discipline.name.
  function disciplineOptionLabel(discipline, src) {
    const list = disciplinesListFrom(src);
    const key = disciplineNameKey(discipline && discipline.name);
    const base0 = asText(discipline && discipline.name) || "Sans nom";
    if (!key) return base0;
    const homonyms = list.filter((d) => d && disciplineNameKey(d.name) === key);
    if (homonyms.length <= 1) return base0;
    const rank = homonyms.findIndex((d) => d && discipline && d.id === discipline.id) + 1;
    return rank > 0 ? `${base0} — discipline ${rank}` : base0;
  }

  // Reconstruit la liste de NOMS de compat d'une entité coach/salle : noms CANONIQUES (courants) de
  // ses id + ses valeurs libres explicites, dédupliqués par chaîne exacte. Ne crée aucun id, ne lit
  // pas les noms comme source. Utilisé au renommage (garde les noms frais) et à la normalisation.
  function rebuildEntityDisciplineNames(entity, idField, nameField, freeField, src) {
    if (!entity || typeof entity !== "object") return;
    const free = (Array.isArray(entity[freeField]) ? entity[freeField] : []).map((x) => asText(x)).filter(Boolean);
    entity[nameField] = [...new Set([...canonicalDisciplineNames(entity[idField], src), ...free])];
  }

  // Réconciliation CANONIQUE d'une entité coach/salle. Source de vérité = IDENTIFIANTS + valeurs
  // libres explicites (`freeField`). `nameField` est une liste de compat DÉRIVÉE ; elle n'est lue
  // comme source QUE pour migrer des données historiques (noms « orphelins » non encore couverts).
  //  1) id existants conservés (inconnus/ambigus jamais effacés) ;
  //  2) MIGRATION des noms orphelins (ni couverts par un id, ni déjà libres) : nom unique → id ajouté,
  //     nom ambigu/libre → valeur libre. Un nom déjà couvert (canonique d'un id, ou libre) n'est
  //     JAMAIS reparsé → aucune dérive vers un homonyme après un renommage ;
  //  3) `nameField` reconstruit = noms canoniques des id + valeurs libres. Idempotent, isolé par club.
  function reconcileEntityDisciplines(entity, idField, nameField, freeField, src) {
    if (!entity || typeof entity !== "object") return;
    const ids = [];
    const pushId = (v) => { const i = asText(v); if (i && !ids.includes(i)) ids.push(i); };
    (Array.isArray(entity[idField]) ? entity[idField] : []).forEach(pushId);
    const free = [];
    const pushFree = (v) => { const n = asText(v); if (n && !free.some((f) => disciplineNameKey(f) === disciplineNameKey(n))) free.push(n); };
    (Array.isArray(entity[freeField]) ? entity[freeField] : []).forEach(pushFree);
    // Noms déjà couverts : noms canoniques des id + valeurs libres (par clé).
    const covered = new Set([...canonicalDisciplineNames(ids, src), ...free].map(disciplineNameKey).filter(Boolean));
    // Migration des noms orphelins (données historiques uniquement).
    (Array.isArray(entity[nameField]) ? entity[nameField] : []).forEach((raw) => {
      const n = asText(raw);
      const k = disciplineNameKey(n);
      if (!k || covered.has(k)) return;
      const rid = resolveDisciplineIdByName(n, src);
      if (rid) { pushId(rid); } else { pushFree(n); }
      covered.add(k);
    });
    entity[idField] = ids;
    // Une valeur libre dont le nom est devenu canonique (couvert par un id) sort de la liste libre.
    const canonKeys = new Set(canonicalDisciplineNames(ids, src).map(disciplineNameKey));
    entity[freeField] = free.filter((f) => !canonKeys.has(disciplineNameKey(f)));
    entity[nameField] = [...new Set([...canonicalDisciplineNames(ids, src), ...entity[freeField]])];
  }

  function normalizeState(source) {
    source = migrateObsoleteSourceKeys(source || {});
    const base = {
      meta: source.meta || {},
      tariffs: source.tariffs || {},
      contacts: source.contacts || {},
      memberships: source.memberships || [],
      shopOrders: source.shopOrders || [],
      invoices: Array.isArray(source.invoices) ? source.invoices : [],
      stageRegistrations: source.stageRegistrations || {},
      notes: [],
      memoRows: [],
      activityLog: Array.isArray(source.activityLog) ? source.activityLog : [],
      seasonArchives: Array.isArray(source.seasonArchives) ? source.seasonArchives : [],
      // Modules sport (gestion de club) — locaux, par club, inclus dans sauvegarde/restauration.
      // Anciennes sauvegardes sans ces clés : défaut [] (compatibilité ascendante).
      groups: Array.isArray(source.groups) ? source.groups : [],
      planningCourses: Array.isArray(source.planningCourses) ? source.planningCourses : [],
      // Exceptions par date (Phase C1) : surcouche d'affichage liée à un créneau récurrent.
      // N'altère JAMAIS planningCourses. Anciennes sauvegardes : défaut [].
      planningExceptions: Array.isArray(source.planningExceptions) ? source.planningExceptions : [],
      attendanceSessions: Array.isArray(source.attendanceSessions) ? source.attendanceSessions : [],
      coaches: Array.isArray(source.coaches) ? source.coaches : [],
      coachReplacements: Array.isArray(source.coachReplacements) ? source.coachReplacements : [],
      rooms: Array.isArray(source.rooms) ? source.rooms : [],
      roomReplacements: Array.isArray(source.roomReplacements) ? source.roomReplacements : [],
      expenses: Array.isArray(source.expenses) ? source.expenses : [],
      creditNotes: Array.isArray(source.creditNotes) ? source.creditNotes : [],
      // Lot 3B-2A — catalogue des catégories sportives (U11, Cadets, Éveil…), une entrée par
      // catégorie, rattachée à UNE discipline. Anciennes sauvegardes : défaut [] — migration NEUTRE,
      // aucun catalogue n'est jamais fabriqué automatiquement (voir normalizeSportCategory).
      sportCategories: Array.isArray(source.sportCategories) ? source.sportCategories : [],
    };
    base.tariffs.articles = base.tariffs.articles || [];
    base.tariffs.disciplines = base.tariffs.disciplines || [];
    base.tariffs.stages = base.tariffs.stages || [];
    base.tariffs.insurance = base.tariffs.insurance || [];
    base.contacts.members = base.contacts.members || [];
    base.contacts.prospects = base.contacts.prospects || [];
    base.contacts.members.forEach((contact) => {
      contact.id = contact.id || id("member");
      contact.birthDate = dateInputValue(contact.birthDate);
      contact.category = memberCategory(contact);
      contact.identityPhotoDataUrl = isImageDataUrl(contact.identityPhotoDataUrl || contact.photoDataUrl || contact.photo) ? (contact.identityPhotoDataUrl || contact.photoDataUrl || contact.photo) : "";
      contact.identityAvatarChoice = normalizeIdentityAvatarChoice(contact.identityAvatarChoice);
      contact.documents = normalizeContactDocuments(contact.documents);
      contact.documentsText = asText(contact.documentsText || contact.documentNotes || "");
      // Lot Contact V2 — responsable légal saisi directement sur le contact (mineur). Mêmes
      // champs texte que ceux déjà utilisés côté membership (src/19-contact-dialogs.js) ;
      // aucune synchronisation entre les deux dans ce lot, cf. audit.
      contact.legalGuardianName = asText(contact.legalGuardianName);
      contact.legalGuardianPhone = asText(contact.legalGuardianPhone);
      contact.legalGuardianEmail = asText(contact.legalGuardianEmail);
      // Lot Contact/Dossier V2 — autorisation parentale et droit à l'image centralisés sur le
      // contact (mêmes champs que côté membership, aucune synchronisation entre les deux, cf. audit).
      contact.parentalAuthorization = Boolean(contact.parentalAuthorization);
      contact.imageRights = Boolean(contact.imageRights);
      // Lot Contact/Dossier V2 (règlement) — même principe pour le règlement signé : information
      // personne, pas discipline (l'assurance, elle, reste sur la membership, inchangée).
      contact.rulesSigned = Boolean(contact.rulesSigned);
    });
    base.contacts.prospects.forEach((contact) => {
      contact.id = contact.id || id("prospect");
      contact.identityPhotoDataUrl = isImageDataUrl(contact.identityPhotoDataUrl || contact.photoDataUrl || contact.photo) ? (contact.identityPhotoDataUrl || contact.photoDataUrl || contact.photo) : "";
      contact.identityAvatarChoice = normalizeIdentityAvatarChoice(contact.identityAvatarChoice);
      contact.documents = normalizeContactDocuments(contact.documents);
      contact.documentsText = asText(contact.documentsText || contact.documentNotes || "");
    });
    base.memberships.forEach((membership) => {
      membership.id = membership.id || id("membership");
      membership.birthDate = dateInputValue(membership.birthDate);
      membership.category = memberCategory(membership);
      membership.identityPhotoDataUrl = isImageDataUrl(membership.identityPhotoDataUrl || membership.photoDataUrl || membership.photo) ? (membership.identityPhotoDataUrl || membership.photoDataUrl || membership.photo) : "";
      membership.identityAvatarChoice = normalizeIdentityAvatarChoice(membership.identityAvatarChoice);
      membership.payments = normalizePayments(membership.payments);
      normalizeMemberSportFields(membership);
    });
    base.shopOrders.forEach((order) => {
      order.payments = normalizePayments(order.payments);
    });
    base.invoices = base.invoices.map((invoice) => normalizeInvoice(invoice));
    Object.values(base.stageRegistrations).forEach((registrations) => {
      (registrations || []).forEach((registration) => {
        registration.event = registration.event || {};
        registration.lodging = registration.lodging || {};
        registration.identityPhotoDataUrl = isImageDataUrl(registration.identityPhotoDataUrl || registration.photoDataUrl || registration.photo) ? (registration.identityPhotoDataUrl || registration.photoDataUrl || registration.photo) : "";
        registration.identityAvatarChoice = normalizeIdentityAvatarChoice(registration.identityAvatarChoice);
        registration.event.payments = normalizePayments(registration.event.payments);
        registration.lodging.payments = normalizePayments(registration.lodging.payments);
      });
    });
    const soldByArticle = new Map();
    for (const order of base.shopOrders) {
      for (const item of order.items || []) {
        soldByArticle.set(item.articleId, (soldByArticle.get(item.articleId) || 0) + asNumber(item.quantity));
      }
    }
    base.tariffs.articles = base.tariffs.articles.map((article, index) => {
      const name = article.name || `Article ${index + 1}`;
      const referenceAuto = article.referenceAuto ?? !article.reference;
      const articleImagesValue = articleImages(article);
      const articleImageCaptionsValue = articleImageCaptions(article, articleImagesValue.length);
      const normalizedArticle = {
        id: article.id || id("article"),
        name,
        reference: referenceAuto ? makeArticleReference(name, index) : article.reference,
        referenceAuto,
        priceOptions: article.priceOptions || [asNumber(article.defaultPrice)],
        defaultPrice: asNumber(article.defaultPrice ?? article.priceOptions?.[0]),
        sizes: article.sizes || [],
        sizeStock: normalizeSizeStock(article.sizeStock),
        image: articleImagesValue[0] || "",
        images: articleImagesValue,
        imageCaptions: articleImageCaptionsValue,
        stockInitial: asNumber(article.stockInitial ?? soldByArticle.get(article.id) ?? 0),
        stockAlert: asNumber(article.stockAlert ?? 0),
        active: article.active !== false,
      };
      applyNormalizedTaxRate(normalizedArticle, article);
      return normalizedArticle;
    });
    base.tariffs.disciplines.forEach((discipline) => {
      // Lot 3A — identité canonique : attribue un id STABLE aux anciennes disciplines qui en sont
      // dépourvues (idempotent : n'écrase jamais un id existant, ne modifie ni le nom ni les autres
      // champs, ne fusionne rien). Persisté atomiquement par le mécanisme de stockage du club.
      if (discipline && typeof discipline === "object" && !asText(discipline.id)) discipline.id = id("discipline");
      // Lot 3B-1 — profil sportif ancré sur la discipline. Migration NEUTRE : les disciplines
      // existantes deviennent « libres » (sportId ""), jamais rattachées à un sport déduit de leur
      // nom (« Judo » ne devient PAS le profil judo). Le choix reste à l'utilisateur.
      //  - sportId : conservé tel quel s'il est renseigné, MÊME inconnu du registre (principe du
      //    Lot 3A sur les identifiants inconnus : on préserve, on ne réinterprète pas) ;
      //  - family : surcharge facultative, retenue seulement si c'est une famille reconnue. La
      //    famille d'un sport officiel n'est JAMAIS recopiée ici (elle se résout depuis le registre) ;
      //  - capabilities : surcharges explicites uniquement, jamais un instantané des capacités
      //    résolues (sinon un enrichissement futur du catalogue ne profiterait pas aux clubs).
      // Idempotente : une seconde passe sur le résultat produit un objet strictement identique.
      // Comme normalizeClubProfile (Lot 1), on n'accepte que des CHAÎNES : un nombre ou un objet
      // n'est pas un identifiant de profil et est neutralisé plutôt que converti en texte.
      if (discipline && typeof discipline === "object") {
        discipline.sportId = typeof discipline.sportId === "string" ? asText(discipline.sportId) : "";
        const familyOverride = typeof discipline.family === "string" ? asText(discipline.family) : "";
        discipline.family = SPORT_FAMILIES.includes(familyOverride) ? familyOverride : "";
        discipline.capabilities = normalizeDisciplineCapabilities(discipline.capabilities);
        // Lot 1 archivage — même doctrine que normalizeSportCategory : booléen STRICT (=== true).
        // Une ancienne sauvegarde sans ce champ, ou toute valeur non booléenne, reste active.
        discipline.archived = discipline.archived === true;
      }
      applyNormalizedTaxRate(discipline, discipline);
    });
    base.tariffs.insurance.forEach((insurance) => applyNormalizedTaxRate(insurance, insurance));
    base.tariffs.stages.forEach((stage) => {
      applyNormalizedTaxRate(stage, stage);
      const lodgingTax = stage.lodgingTaxRate ?? stage.lodgingVatRate ?? stage.lodgingTva;
      if (lodgingTax === undefined || lodgingTax === null || asText(lodgingTax) === "") delete stage.lodgingTaxRate;
      else stage.lodgingTaxRate = Math.max(0, asNumber(lodgingTax));
      stage.publicAccess = normalizeStagePublicAccess(stage.publicAccess);
      stage.investment = asNumber(stage.investment);
      stage.startDate = dateInputValue(stage.startDate);
      stage.endDate = dateInputValue(stage.endDate);
      stage.registrationDeadline = dateInputValue(stage.registrationDeadline);
      stage.registrationReopened = Boolean(stage.registrationReopened);
      // Liens optionnels vers les modules Coachs / Salles (+ replis texte conservés).
      stage.coachId = asText(stage.coachId || "");
      stage.roomId = asText(stage.roomId || "");
      stage.coach = asText(stage.coach || "");
      stage.location = asText(stage.location || "");
    });
    base.tariffs.stages = base.tariffs.stages.filter((stage) => {
      const removeStage = isImportedEmptyStage(stage, base.stageRegistrations[stage.id] || []);
      if (removeStage) delete base.stageRegistrations[stage.id];
      return !removeStage;
    });
    for (const stage of base.tariffs.stages) {
      base.stageRegistrations[stage.id] = base.stageRegistrations[stage.id] || [];
    }
    if (!ui.stageId || !base.tariffs.stages.some((stage) => stage.id === ui.stageId)) {
      ui.stageId = base.tariffs.stages[0]?.id || "stage-1";
    }
    base.memoRows = cleanMemoRows(linkMemoRows(base, Array.isArray(source.memoRows) ? source.memoRows.map(normalizeMemoRow) : []));
    base.notes = normalizeNotes(source.notes);
    base.activityLog = normalizeActivityLog(base.activityLog);
    base.seasonArchives = base.seasonArchives.filter((archive) => archive && typeof archive === "object").slice(-20);
    base.coaches = base.coaches.filter((coach) => coach && typeof coach === "object").map(normalizeCoach);
    base.coachReplacements = base.coachReplacements.filter((rec) => rec && typeof rec === "object").map(normalizeCoachReplacement);
    base.rooms = base.rooms.filter((room) => room && typeof room === "object").map(normalizeRoom);
    base.roomReplacements = base.roomReplacements.filter((rec) => rec && typeof rec === "object").map(normalizeRoomReplacement);
    base.expenses = base.expenses.filter((exp) => exp && typeof exp === "object").map(normalizeExpense);
    base.creditNotes = base.creditNotes.filter((cn) => cn && typeof cn === "object").map(normalizeCreditNote);
    base.groups = base.groups.filter((group) => group && typeof group === "object").map(normalizeGroup);
    base.sportCategories = normalizeSportCategories(base.sportCategories);
    base.planningCourses = base.planningCourses.filter((course) => course && typeof course === "object").map(normalizeCourse);
    // Exceptions par date : normalisées + nettoyage des orphelines (créneau récurrent supprimé).
    const validCourseIds = new Set(base.planningCourses.map((course) => course.id));
    base.planningExceptions = base.planningExceptions
      .filter((ex) => ex && typeof ex === "object")
      .map(normalizePlanningException)
      .filter((ex) => ex.courseId && validCourseIds.has(ex.courseId) && ex.date);
    const validGroupIds = new Set(base.groups.map((group) => group.id));
    base.attendanceSessions = base.attendanceSessions.filter((session) => session && typeof session === "object").map(normalizeAttendanceSession);
    // Sécurité : un membership lié à un groupe supprimé voit son groupId nettoyé.
    base.memberships.forEach((membership) => {
      if (membership.groupId && !validGroupIds.has(membership.groupId)) membership.groupId = "";
    });
    // --- Auto-réparation des doublons exacts par id (toutes les collections où l'id est unique) ---
    base.contacts.members = dedupeById(base.contacts.members);
    base.contacts.prospects = dedupeById(base.contacts.prospects);
    base.memberships = dedupeById(base.memberships);
    base.shopOrders = dedupeById(base.shopOrders);
    base.invoices = dedupeById(base.invoices);
    base.tariffs.articles = dedupeById(base.tariffs.articles);
    base.tariffs.disciplines = dedupeById(base.tariffs.disciplines);
    base.tariffs.insurance = dedupeById(base.tariffs.insurance);
    base.tariffs.stages = dedupeById(base.tariffs.stages);
    base.notes = dedupeById(base.notes);
    base.memoRows = dedupeById(base.memoRows);
    base.activityLog = dedupeById(base.activityLog);
    base.seasonArchives = dedupeById(base.seasonArchives);
    base.coaches = dedupeById(base.coaches);
    base.coachReplacements = dedupeById(base.coachReplacements);
    base.rooms = dedupeById(base.rooms);
    base.roomReplacements = dedupeById(base.roomReplacements);
    base.expenses = dedupeById(base.expenses);
    base.creditNotes = dedupeById(base.creditNotes);
    base.groups = dedupeById(base.groups);
    base.sportCategories = dedupeById(base.sportCategories);
    base.planningCourses = dedupeById(base.planningCourses);
    base.planningExceptions = dedupeById(base.planningExceptions);
    base.attendanceSessions = dedupeById(base.attendanceSessions);
    Object.keys(base.stageRegistrations || {}).forEach((sid) => {
      base.stageRegistrations[sid] = dedupeById(base.stageRegistrations[sid]);
    });
    if (!ui.noteId || !base.notes.some((note) => note.id === ui.noteId)) ui.noteId = base.notes[0]?.id || "";
    // Réparation d'accents AVANT la résolution des références : les libellés (disciplines ET
    // références) sont alors dans leur forme finale, garantissant des clés cohérentes.
    const repaired = repairLegacyAccentData(base);
    // Lot 3A — résolution centralisée des références de discipline (non ambiguë), après que toutes
    // les disciplines ont reçu un id et que les libellés sont réparés/dédupliqués.
    return resolveDisciplineReferences(repaired);
  }

  // Champs « dossier sportif » d'un adhérent (inscription). Valeurs par défaut neutres
  // pour rester compatible avec les anciennes données.
  function normalizeMemberSportFields(member) {
    const str = (v) => asText(v || "");
    member.licenseNumber = str(member.licenseNumber);
    member.licenseFederation = str(member.licenseFederation);
    member.licenseStartDate = dateInputValue(member.licenseStartDate);
    member.licenseEndDate = dateInputValue(member.licenseEndDate);
    member.medicalCertificateDate = dateInputValue(member.medicalCertificateDate);
    member.medicalCertificateEndDate = dateInputValue(member.medicalCertificateEndDate);
    member.emergencyName = str(member.emergencyName);
    member.emergencyPhone = str(member.emergencyPhone);
    member.emergencyRelation = str(member.emergencyRelation);
    member.legalGuardianName = str(member.legalGuardianName);
    member.legalGuardianPhone = str(member.legalGuardianPhone);
    member.legalGuardianEmail = str(member.legalGuardianEmail);
    member.parentalAuthorization = Boolean(member.parentalAuthorization);
    member.imageRights = Boolean(member.imageRights);
    member.rulesSigned = Boolean(member.rulesSigned);
    member.insurance = Boolean(member.insurance);
    member.groupId = str(member.groupId);
    // Lot 3A — référence canonique de discipline (préservée si présente ; résolue par la passe
    // centralisée). Le libellé `member.discipline` reste la source d'affichage/repli. `member.level`
    // (note libre) et `member.practiceType` restent inchangés (hors périmètre du Lot 3A).
    member.disciplineId = str(member.disciplineId);
    // Lot 3B-2A — catégorie sportive de l'inscription. Référence par IDENTIFIANT, facultative,
    // STRICTEMENT distincte de `level` (note libre) et de `practiceType` (énumération) : aucun de
    // ces champs n'est converti, déduit ou remplacé par un autre. Une valeur inconnue du catalogue
    // est conservée telle quelle (aucun repli nominal) ; une valeur non textuelle est neutralisée.
    // Aucun calcul financier ne lit ce champ.
    member.sportCategoryId = typeof member.sportCategoryId === "string" ? asText(member.sportCategoryId) : "";
    member.level = str(member.level);
    member.practiceType = ["Loisir", "Compétition", "Stage", "Autre"].includes(member.practiceType) ? member.practiceType : "";
    // Pièces jointes : on réutilise le même système que les contacts (champ `documents`),
    // pour ne pas créer un second système de fichiers. Migration depuis documentFiles si présent.
    member.documents = normalizeContactDocuments(member.documents || member.documentFiles);
    member.documentsText = asText(member.documentsText || "");
    delete member.documentFiles;
  }

  // Coach / intervenant : identité, spécialités (disciplines), disponibilités hebdo,
  // indisponibilités ponctuelles (dates). Local, par club. Compatible anciennes sauvegardes.
  function normalizeCoach(coach) {
    const days = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"];
    const types = ["Bénévole", "Salarié", "Intervenant extérieur"];
    // Migration : l'ancien mot-clé libre « Multisport » / « Tout » devient l'option
    // polyvalente explicite (coach.versatile). On retire ces jetons des spécialités
    // pour qu'ils ne rendent plus le coach éligible partout de façon cachée.
    const rawSpecs = (Array.isArray(coach.specialties) ? coach.specialties : []).map((s) => asText(s)).filter(Boolean);
    const isWild = (s) => /^(multisport|tout)$/i.test(asText(s).trim());
    const specialties = rawSpecs.filter((s) => !isWild(s));
    const versatile = Boolean(coach.versatile) || rawSpecs.some(isWild);
    return {
      id: coach.id || id("coach"),
      firstName: asText(coach.firstName || ""),
      lastName: asText(coach.lastName || ""),
      photoDataUrl: isImageDataUrl(coach.photoDataUrl) ? coach.photoDataUrl : "",
      avatarChoice: ["neutral", "man", "woman"].includes(coach.avatarChoice) ? coach.avatarChoice : "neutral",
      phone: asText(coach.phone || ""),
      email: asText(coach.email || ""),
      address: asText(coach.address || ""),
      notes: asText(coach.notes || ""),
      archived: Boolean(coach.archived),
      specialties,
      // Lot 3A (D1) — id canoniques des spécialités PRÉSERVÉS (autoritatifs) + valeurs libres/
      // historiques explicites. reconcileEntityDisciplines (dans resolveDisciplineReferences) fait
      // l'union des id et reconstruit `specialties` depuis les id ; rien n'est effacé en silence.
      specialtyDisciplineIds: (Array.isArray(coach.specialtyDisciplineIds) ? coach.specialtyDisciplineIds : []).map((x) => asText(x)).filter(Boolean),
      specialtiesFree: (Array.isArray(coach.specialtiesFree) ? coach.specialtiesFree : []).map((s) => asText(s)).filter(Boolean).filter((s) => !isWild(s)),
      versatile,
      type: types.includes(coach.type) ? coach.type : "",
      qualification: asText(coach.qualification || ""),
      licenseNumber: asText(coach.licenseNumber || ""),
      hourlyRate: coach.hourlyRate === "" || coach.hourlyRate === undefined || coach.hourlyRate === null ? "" : asNumber(coach.hourlyRate),
      // Option comptable EXPLICITE (Phase 2) : le tarif n'est comptabilisé que si activée.
      expenseEnabled: Boolean(coach.expenseEnabled),
      expenseStatus: ["Bénévole", "Salarié", "Intervenant extérieur", "Autre"].includes(coach.expenseStatus) ? coach.expenseStatus : "",
      expenseAmount: coach.expenseAmount === "" || coach.expenseAmount === undefined || coach.expenseAmount === null ? "" : Math.max(0, asNumber(coach.expenseAmount)),
      expenseUnit: ["séance", "heure", "forfait"].includes(coach.expenseUnit) ? coach.expenseUnit : "séance",
      expenseCategory: ["Coach / intervenant", "Rémunération", "Prestation", "Autre dépense"].includes(coach.expenseCategory) ? coach.expenseCategory : "Coach / intervenant",
      expenseNote: asText(coach.expenseNote || ""),
      availability: (Array.isArray(coach.availability) ? coach.availability : [])
        .filter((a) => a && days.includes(a.day))
        .map((a) => ({ day: a.day, start: asText(a.start || ""), end: asText(a.end || "") })),
      unavailabilities: (Array.isArray(coach.unavailabilities) ? coach.unavailabilities : [])
        .filter((u) => u && typeof u === "object")
        .map((u) => ({
          id: u.id || id("unav"),
          startDate: dateInputValue(u.startDate),
          endDate: dateInputValue(u.endDate) || dateInputValue(u.startDate),
          startTime: asText(u.startTime || ""),
          endTime: asText(u.endTime || ""),
          reason: asText(u.reason || ""),
        }))
        .filter((u) => u.startDate),
    };
  }

  // Avoir / note de crédit (Phase 3) : réduit ou annule une recette (réduction, crédit
  // pour plus tard, annulation partielle) sans supprimer l'historique. Local, par club.
  function normalizeCreditNote(cn) {
    const types = ["réduction", "crédit", "annulation"];
    const statuses = ["actif", "utilisé", "annulé"];
    return {
      id: cn.id || id("avoir"),
      date: dateInputValue(cn.date) || todayInputValue(),
      amount: Math.max(0, asNumber(cn.amount)),
      reason: asText(cn.reason || ""),
      type: types.includes(cn.type) ? cn.type : "réduction",
      status: statuses.includes(cn.status) ? cn.status : "actif",
      invoiceId: asText(cn.invoiceId || ""),
      contactId: asText(cn.contactId || ""),
      note: asText(cn.note || ""),
      createdAt: asText(cn.createdAt || ""),
      updatedAt: asText(cn.updatedAt || ""),
    };
  }

  // Dépense manuelle (sortie d'argent du club). Locale, par club, incluse dans la
  // sauvegarde. Saisie manuelle uniquement en Phase 1 (linkedType/linkedId réservés
  // aux futures liaisons coachs/salles/stages, non utilisés automatiquement).
  function normalizeExpense(expense) {
    return {
      id: expense.id || id("expense"),
      date: dateInputValue(expense.date) || todayInputValue(),
      label: asText(expense.label || ""),
      amount: Math.max(0, asNumber(expense.amount)),
      category: asText(expense.category || "Autre dépense"),
      paymentMethod: asText(expense.paymentMethod || ""),
      beneficiary: asText(expense.beneficiary || ""),
      note: asText(expense.note || ""),
      linkedType: asText(expense.linkedType || ""),
      linkedId: asText(expense.linkedId || ""),
      createdAt: asText(expense.createdAt || ""),
      updatedAt: asText(expense.updatedAt || ""),
    };
  }

  // Salle / lieu : identité, type, capacité, disciplines compatibles, disponibilités
  // hebdo, indisponibilités ponctuelles. Local, par club. Compatible anciennes sauvegardes.
  function normalizeRoom(room) {
    const days = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"];
    const types = ["Dojo", "Salle polyvalente", "Gymnase", "Terrain extérieur", "Terrain de football", "Terrain de tennis", "Salle de musculation", "Piscine", "Salle de danse", "Autre"];
    return {
      id: room.id || id("room"),
      name: asText(room.name || ""),
      description: asText(room.description || ""),
      address: asText(room.address || ""),
      photoDataUrl: isImageDataUrl(room.photoDataUrl) ? room.photoDataUrl : "",
      notes: asText(room.notes || ""),
      archived: Boolean(room.archived),
      type: types.includes(room.type) ? room.type : "",
      capacity: room.capacity === "" || room.capacity === undefined || room.capacity === null ? "" : Math.max(0, asNumber(room.capacity)),
      surface: room.surface === "" || room.surface === undefined || room.surface === null ? "" : Math.max(0, asNumber(room.surface)),
      equipment: asText(room.equipment || ""),
      managerName: asText(room.managerName || ""),
      managerPhone: asText(room.managerPhone || ""),
      managerEmail: asText(room.managerEmail || ""),
      rentalPrice: room.rentalPrice === "" || room.rentalPrice === undefined || room.rentalPrice === null ? "" : Math.max(0, asNumber(room.rentalPrice)),
      // Option comptable EXPLICITE (Phase 2) : le tarif n'est comptabilisé que si activée.
      expenseEnabled: Boolean(room.expenseEnabled),
      expenseAmount: room.expenseAmount === "" || room.expenseAmount === undefined || room.expenseAmount === null ? "" : Math.max(0, asNumber(room.expenseAmount)),
      expenseUnit: ["séance", "heure", "réservation", "forfait"].includes(room.expenseUnit) ? room.expenseUnit : "réservation",
      expenseCategory: ["Location salle", "Autre dépense"].includes(room.expenseCategory) ? room.expenseCategory : "Location salle",
      expenseNote: asText(room.expenseNote || ""),
      disciplines: (Array.isArray(room.disciplines) ? room.disciplines : []).map((s) => asText(s)).filter(Boolean),
      // Lot 3A (D1) — id canoniques des disciplines compatibles PRÉSERVÉS (autoritatifs) + valeurs
      // libres/historiques explicites. reconcileEntityDisciplines reconstruit `disciplines` depuis
      // les id (nom courant) + valeurs libres ; aucun id ni nom libre n'est effacé en silence.
      disciplineIds: (Array.isArray(room.disciplineIds) ? room.disciplineIds : []).map((x) => asText(x)).filter(Boolean),
      disciplinesFree: (Array.isArray(room.disciplinesFree) ? room.disciplinesFree : []).map((s) => asText(s)).filter(Boolean),
      availability: (Array.isArray(room.availability) ? room.availability : [])
        .filter((a) => a && days.includes(a.day))
        .map((a) => ({ day: a.day, start: asText(a.start || ""), end: asText(a.end || "") })),
      unavailabilities: (Array.isArray(room.unavailabilities) ? room.unavailabilities : [])
        .filter((u) => u && typeof u === "object")
        .map((u) => ({
          id: u.id || id("roomunav"),
          startDate: dateInputValue(u.startDate),
          endDate: dateInputValue(u.endDate) || dateInputValue(u.startDate),
          startTime: asText(u.startTime || ""),
          endTime: asText(u.endTime || ""),
          reason: asText(u.reason || ""),
        }))
        .filter((u) => u.startDate),
    };
  }

  // Décision de remplacement d'une séance touchée par une indisponibilité de coach.
  // Clé logique : courseId + période (startDate/endDate de l'indisponibilité).
  // status : "replaced" (remplacé), "cancelled" (annulé), "ignored" (ignoré).
  function normalizeCoachReplacement(rec) {
    const statuses = ["replaced", "cancelled", "ignored"];
    return {
      id: rec.id || id("replace"),
      courseId: asText(rec.courseId || ""),
      coachId: asText(rec.coachId || ""),
      replacementCoachId: asText(rec.replacementCoachId || ""),
      periodStart: dateInputValue(rec.periodStart),
      periodEnd: dateInputValue(rec.periodEnd) || dateInputValue(rec.periodStart),
      status: statuses.includes(rec.status) ? rec.status : "ignored",
      decidedAt: asText(rec.decidedAt || ""),
    };
  }

  // Décision de remplacement d'une séance touchée par une indisponibilité de salle (cf. normalizeCoachReplacement).
  function normalizeRoomReplacement(rec) {
    const statuses = ["replaced", "cancelled", "ignored"];
    return {
      id: rec.id || id("roomreplace"),
      courseId: asText(rec.courseId || ""),
      roomId: asText(rec.roomId || ""),
      replacementRoomId: asText(rec.replacementRoomId || ""),
      periodStart: dateInputValue(rec.periodStart),
      periodEnd: dateInputValue(rec.periodEnd) || dateInputValue(rec.periodStart),
      status: statuses.includes(rec.status) ? rec.status : "ignored",
      decidedAt: asText(rec.decidedAt || ""),
    };
  }

  // Lot 3B-2A — CATÉGORIE SPORTIVE (U11, Cadets, Éveil, Débutant…) : une entrée du catalogue d'UNE
  // discipline. Collection PLATE `state.sportCategories`, délibérément PAS imbriquée dans
  // `state.tariffs.disciplines` : une catégorie est une donnée sportive, jamais une ligne
  // financière — aucun calcul de cotisation, licence, assurance, remise, TVA ou facture ne la lit.
  // Le rattachement passe UNIQUEMENT par les identifiants (discipline.id ↔ sportCategory.id) : deux
  // disciplines homonymes (Lot 3A) ont donc deux catalogues disjoints sans traitement particulier,
  // et un « Seniors » de football ne se confond jamais avec un « Seniors » de judo.
  //
  // Règles de champ — toutes déterministes (ni horloge, ni aléatoire, ni libellé) et idempotentes :
  //  - id : conservé si c'est une CHAÎNE non vide, sinon généré UNE seule fois. Comme au Lot 3B-1,
  //    un nombre n'est pas un identifiant : il est neutralisé, jamais converti en texte (asText(42)
  //    donnerait "42" et fabriquerait un identifiant qui n'a jamais été choisi) ;
  //  - disciplineId : même règle. Une valeur inconnue du référentiel est CONSERVÉE telle quelle
  //    (doctrine Lot 3A), jamais rattachée par le libellé, jamais repliée sur une autre discipline ;
  //  - label : nettoyé, JAMAIS clé technique. Un libellé vide est conservé tel quel : on n'invente
  //    pas de repli (« Catégorie 1 ») — ce serait une donnée que l'utilisateur n'a pas saisie — et
  //    on ne rejette pas la ligne, qui reste identifiable par son id et peut déjà être référencée
  //    par une inscription. Exiger un libellé est une règle de SAISIE (Lot 3B-2B), pas de modèle ;
  //  - order : un nombre fini est arrondi et conservé ; toute autre valeur donne `index * pas`,
  //    repli stable qui préserve l'ordre du tableau source et laisse de la place pour insérer ;
  //  - archived : booléen STRICT (=== true). "false", 0 ou 1 n'archivent rien : une valeur non
  //    booléenne ne doit jamais faire disparaître une catégorie d'une liste par accident ;
  //  - clubId : convention des autres collections du club, ré-estampillé par scopeStateToClub.
  // Ne fusionne JAMAIS deux catégories de même libellé : deux id distincts = deux entrées distinctes
  // (la prévention des doublons à la saisie appartient au Lot 3B-2B).
  function normalizeSportCategory(category, index) {
    const src = category && typeof category === "object" && !Array.isArray(category) ? category : {};
    const rawOrder = src.order;
    const fallbackOrder = Number.isInteger(index) ? index * SPORT_CATEGORY_ORDER_STEP : 0;
    return {
      id: (typeof src.id === "string" && asText(src.id)) ? asText(src.id) : id("sportcategory"),
      clubId: asText(src.clubId || ""),
      disciplineId: typeof src.disciplineId === "string" ? asText(src.disciplineId) : "",
      label: typeof src.label === "string" ? asText(src.label) : "",
      order: (typeof rawOrder === "number" && Number.isFinite(rawOrder)) ? Math.round(rawOrder) : fallbackOrder,
      archived: src.archived === true,
      notes: typeof src.notes === "string" ? asText(src.notes) : "",
    };
  }

  // Catalogue complet. Accepte uniquement un tableau (toute autre valeur → []), écarte les entrées
  // non exploitables (null, primitives, tableaux) comme le font les autres collections, préserve
  // l'ordre du tableau source et reste idempotente.
  function normalizeSportCategories(value) {
    if (!Array.isArray(value)) return [];
    return value
      .filter((entry) => entry && typeof entry === "object" && !Array.isArray(entry))
      .map((entry, index) => normalizeSportCategory(entry, index));
  }

  function normalizeGroup(group) {
    const types = ["Débutants", "Confirmés", "Enfants", "Adultes", "Compétition", "Loisir", "Autre"];
    return {
      id: group.id || id("group"),
      name: asText(group.name) || "Groupe",
      type: types.includes(group.type) ? group.type : "Autre",
      // Lot 3A — référence canonique (préservée si présente) + libellé historique conservé.
      disciplineId: asText(group.disciplineId || ""),
      discipline: asText(group.discipline || ""),
      // Lot 3B-2A — catégorie sportive du groupe. Référence par IDENTIFIANT, facultative, distincte
      // de `type` (repère d'affichage historique) et de ageMin/ageMax (tranche indicative) : ces
      // trois champs coexistent et aucun n'est déduit d'un autre. Une valeur inconnue du catalogue
      // est conservée telle quelle ; une valeur non textuelle est neutralisée.
      sportCategoryId: typeof group.sportCategoryId === "string" ? asText(group.sportCategoryId) : "",
      coachId: asText(group.coachId || ""),
      coach: asText(group.coach || ""),
      ageMin: group.ageMin === "" || group.ageMin === undefined || group.ageMin === null ? "" : asNumber(group.ageMin),
      ageMax: group.ageMax === "" || group.ageMax === undefined || group.ageMax === null ? "" : asNumber(group.ageMax),
      maxMembers: group.maxMembers === "" || group.maxMembers === undefined || group.maxMembers === null ? "" : Math.max(0, asNumber(group.maxMembers)),
      color: asText(group.color || ""),
      notes: asText(group.notes || ""),
      archived: Boolean(group.archived),
    };
  }

  // Récurrence d'un créneau : objet structuré + migration de l'ancien format plat (Lot 2).
  function normalizeRecurrence(course) {
    const src = course && course.recurrence;
    // Compat Lot 2 : recurrence "weekly|biweekly|triweekly" (string) + recurrenceStart
    if (typeof src === "string" || (!src && course.recurrenceStart)) {
      const interval = src === "biweekly" ? 2 : src === "triweekly" ? 3 : 1;
      return { type: "weekly", start: course.recurrenceStart ? (dateInputValue(course.recurrenceStart) || "") : "", interval, monthlyMode: "weekday", ordinal: 1, dayOfMonth: "" };
    }
    const r = (src && typeof src === "object") ? src : {};
    const type = r.type === "monthly" ? "monthly" : "weekly";
    const interval = [1, 2, 3, 4].includes(asNumber(r.interval)) ? asNumber(r.interval) : 1;
    const monthlyMode = r.monthlyMode === "date" ? "date" : "weekday";
    const ord = asNumber(r.ordinal); const ordinal = [1, 2, 3, 4, -1].includes(ord) ? ord : 1;
    const dom = asNumber(r.dayOfMonth); const dayOfMonth = (dom >= 1 && dom <= 31) ? dom : "";
    return { type, start: r.start ? (dateInputValue(r.start) || "") : "", interval, monthlyMode, ordinal, dayOfMonth };
  }

  function normalizeCourse(course) {
    return {
      id: course.id || id("course"),
      name: asText(course.name) || "Créneau",
      // Lot 3A — référence canonique (préservée si présente) + libellé historique conservé.
      disciplineId: asText(course.disciplineId || ""),
      discipline: asText(course.discipline || ""),
      groupId: asText(course.groupId || ""),
      coachId: asText(course.coachId || ""),
      coach: asText(course.coach || ""),
      day: asText(course.day || ""),
      startTime: asText(course.startTime || ""),
      endTime: asText(course.endTime || ""),
      roomId: asText(course.roomId || ""),
      location: asText(course.location || ""),
      maxPlaces: course.maxPlaces === "" || course.maxPlaces === undefined || course.maxPlaces === null ? "" : Math.max(0, asNumber(course.maxPlaces)),
      // Récurrence (modèle évolutif) : objet { type, start, interval, monthlyMode, ordinal, dayOfMonth }.
      recurrence: normalizeRecurrence(course),
      notes: asText(course.notes || ""),
      archived: Boolean(course.archived),
    };
  }

  // Exception par date (Phase C1) : liée à un créneau récurrent (courseId) pour UNE date.
  // C1 = annulation + note. Les champs d'override coach/salle/horaire (C2) sont conservés
  // s'ils existent (compat ascendante) mais ne sont pas exploités en C1.
  function normalizePlanningException(ex) {
    return {
      id: ex.id || id("planex"),
      clubId: asText(ex.clubId || ""),
      courseId: asText(ex.courseId || ""),
      date: dateInputValue(ex.date),
      cancelled: Boolean(ex.cancelled),
      note: asText(ex.note || ""),
      // Réservés pour C2 (non utilisés en C1) :
      coachId: asText(ex.coachId || ""),
      coach: asText(ex.coach || ""),
      roomId: asText(ex.roomId || ""),
      location: asText(ex.location || ""),
      startTime: asText(ex.startTime || ""),
      endTime: asText(ex.endTime || ""),
      createdAt: asText(ex.createdAt || "") || new Date().toISOString(),
    };
  }

  function normalizeAttendanceSession(session) {
    const statuses = ["present", "absent", "excused", "injured", "late", "trial"];
    return {
      id: session.id || id("session"),
      date: dateInputValue(session.date) || todayInputValue(),
      courseId: asText(session.courseId || ""),
      groupId: asText(session.groupId || ""),
      coachId: asText(session.coachId || ""),
      coach: asText(session.coach || ""),
      rows: (Array.isArray(session.rows) ? session.rows : [])
        .filter((row) => row && typeof row === "object" && asText(row.memberId))
        .map((row) => ({
          memberId: asText(row.memberId),
          status: statuses.includes(row.status) ? row.status : "present",
          note: asText(row.note || ""),
        })),
    };
  }

  function normalizeContactDocuments(documents = []) {
    return (Array.isArray(documents) ? documents : [])
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        id: item.id || id("doc"),
        name: asText(item.name) || "Document",
        type: asText(item.type) || "application/octet-stream",
        dataUrl: typeof item.dataUrl === "string" ? item.dataUrl : "",
        addedAt: item.addedAt || new Date().toISOString(),
      }))
      .filter((item) => item.dataUrl)
      .slice(-20);
  }

  function normalizeActivityLog(rows = []) {
    return (Array.isArray(rows) ? rows : [])
      .filter((row) => row && typeof row === "object")
      .map((row) => ({
        id: row.id || id("log"),
        at: row.at || new Date().toISOString(),
        message: asText(row.message) || "Modification",
        view: asText(row.view),
      }))
      .slice(-300);
  }

  function applyNormalizedTaxRate(target, source = {}) {
    const raw = source.taxRate ?? source.vatRate ?? source.tva;
    if (raw === undefined || raw === null || asText(raw) === "") {
      delete target.taxRate;
      return;
    }
    target.taxRate = Math.max(0, asNumber(raw));
  }

  function normalizeNotes(notes = []) {
    const rows = Array.isArray(notes) ? notes : [];
    const normalized = rows.map((note) => ({
      id: note.id || id("note"),
      title: asText(note.title) || "Note sans titre",
      content: String(note.content ?? ""),
      updatedAt: note.updatedAt || new Date().toISOString(),
    }));
    return normalized.length ? normalized : [{
      id: id("note"),
      title: "",
      content: "",
      updatedAt: new Date().toISOString(),
    }];
  }

  function isImportedEmptyStage(stage = {}, registrations = []) {
    return /^Stage\s+\d+$/i.test(asText(stage.sheet))
      && /^Stage\s+\d+$/i.test(asText(stage.name))
      && !(registrations || []).length;
  }

  // Lot "Notes contextuelles par page" — targetView : page métier où la note doit s'afficher.
  // "" = "Notes uniquement" (comportement historique, valeur par défaut pour toute note existante ou
  // nouvelle : aucune migration automatique depuis l'ancien champ libre "category"). Une valeur non
  // vide est conservée TELLE QUELLE (asText, jamais réinitialisée à "") même si elle ne correspond à
  // aucun ID connu de la liste éligible — cf. NOTE_TARGET_VIEW_IDS (src/01-constants.js) : c'est le
  // rendu (page Notes / bloc contextuel) qui décide de l'afficher ou de proposer un libellé de repli,
  // jamais la normalisation qui ne doit pas être destructive pour une valeur importée inconnue.
  function normalizeMemoRow(row = {}) {
    const priority = ["Normale", "Important", "Urgent", "Archive"].includes(row.priority) ? row.priority : "Normale";
    return {
      id: row.id || id("memo"),
      sourceType: asText(row.sourceType),
      sourceId: asText(row.sourceId),
      category: asText(row.category || row.type),
      title: asText(row.title || row.subject || row.name),
      note: asText(row.note || row.details || row.comment),
      amount: row.amount ?? "",
      priority,
      targetView: asText(row.targetView),
    };
  }

  function isMemoSystemCategory(row = {}) {
    const category = normalizedPersonText(row.category);
    return ["discipline", "disciplines", "article", "articles", "stage", "stages", "paiement", "paiements"].includes(category);
  }

  function cleanMemoRows(rows = []) {
    const seen = new Set();
    return rows.filter((row) => {
      if (row.sourceType || isMemoSystemCategory(row)) return false;
      // targetView inclus dans la signature : deux notes au texte identique mais affichées dans des
      // pages différentes sont des notes DISTINCTES, jamais un doublon à fusionner.
      const signature = `${normalizedPersonText(row.category)}|${normalizedPersonText(row.title)}|${normalizedPersonText(row.note)}|${asText(row.amount)}|${normalizedPersonText(row.priority)}|${asText(row.targetView)}`;
      if (seen.has(signature)) return false;
      seen.add(signature);
      return true;
    });
  }

  function linkMemoRows(base, rows) {
    return rows.map((row) => {
      if (row.sourceType && memoSource(row, base)) return row;
      const category = normalizedPersonText(row.category);
      const title = normalizedPersonText(row.title);
      if (category.includes("discipline")) {
        const discipline = base.tariffs.disciplines.find((item) => normalizedPersonText(item.name) === title);
        if (discipline) return { ...row, sourceType: "discipline", sourceId: discipline.id || discipline.name };
      }
      if (category.includes("article")) {
        const article = base.tariffs.articles.find((item) => normalizedPersonText(item.name) === title);
        if (article) return { ...row, sourceType: "article", sourceId: article.id };
      }
      if (category.includes("stage")) {
        const stage = base.tariffs.stages.find((item) => normalizedPersonText(item.name) === title);
        if (stage) return { ...row, sourceType: "stage", sourceId: stage.id };
      }
      return row;
    });
  }

  const undoUiKeys = [
    "newsletterAudience",
    "newsletterManualOnly",
    "newsletterTitle",
    "newsletterDetail",
    "newsletterDate",
    "newsletterPlace",
    "newsletterMessage",
    "newsletterNote",
    "newsletterComplement",
    "newsletterSignatureLibre",
    "newsletterTemplateKey",
    "newsletterSubject",
    "newsletterBody",
    "newsletterNewEmail",
    "newsletterExtraEmails",
    "newsletterExcludedEmails",
    "emailTemplateKey",
    "emailTemplateEditing",
    "emailTemplateDraft",
  ];

  function snapshotUiState() {
    return Object.fromEntries(undoUiKeys.map((key) => [key, clone(ui[key])]));
  }

  function applyUiSnapshot(source = {}) {
    undoUiKeys.forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(source, key)) ui[key] = clone(source[key]);
    });
  }

  function parseUndoSnapshot(snapshot) {
    let parsed;
    try {
      parsed = JSON.parse(snapshot);
    } catch (error) {
      console.warn("parseUndoSnapshot: JSON invalide", error);
      return null;
    }
    if (parsed && parsed.version === 2 && parsed.state) {
      return {
        state: parsed.state,
        settings: parsed.settings || settings,
        ui: parsed.ui || {},
      };
    }
    return { state: parsed, settings, ui: {} };
  }

  // Lot UX — états d'interface TRANSITOIRES des barres, exclus de l'historique métier.
  // Le repli/dépli de la barre supérieure (settings.topbarHidden) et du menu latéral
  // (settings.sidebarHidden) sont des états VISUELS, jamais des étapes d'Annuler/Rétablir : on ne les
  // mélange PAS aux snapshots métier (settingsForHistory les retire avant sérialisation) et
  // restoreState conserve leur valeur COURANTE (undo/redo ne les parcourent jamais). Leur persistance
  // entre sessions reste assurée par persistSettings, indépendamment de l'historique. Les états
  // d'ouverture des menus (settingsMenuOpen/boutiqueMenuOpen/openMenuGroups) sont déjà hors historique
  // (absents d'undoUiKeys, aucun recordHistory dans leurs handlers). Rétrocompatible : un ancien
  // snapshot contenant encore ces clés est ignoré au restore (valeur courante préservée). Toute clé de
  // préférence hors de cette liste (thème, layout…) continue de suivre l'historique comme avant.
  const historyExcludedSettingsKeys = ["topbarHidden", "sidebarHidden"];

  function settingsForHistory() {
    const copy = { ...settings };
    for (const key of historyExcludedSettingsKeys) delete copy[key];
    return copy;
  }

  function snapshotState() {
    return JSON.stringify({
      version: 2,
      state,
      settings: settingsForHistory(),
      ui: snapshotUiState(),
    });
  }

  // ===== Checkpoint Undo/Redo transactionnel (Lot correctif MS-AUDIT-001) =====
  // `recordHistory()` (ci-dessous) reste le raccourci pour les mutations SYNCHRONES qui ne peuvent
  // plus être refusées une fois qu'on a décidé de les exécuter (handleAction direct, toggles,
  // suppressions déjà validées en amont…) : snapshot puis engagement dans le même geste, comme
  // avant ce lot. Pour un appelant qui ne sait PAS ENCORE si l'opération va réussir (un `onSave`
  // asynchrone qui peut retourner `false`/`{cancel:true}` ou lever une exception), les deux étapes
  // doivent être séparées : capturer le snapshot AVANT l'opération (`beginHistoryCheckpoint`), puis
  // ne l'engager dans `history.undo` / ne purger `history.redo` qu'APRÈS un succès confirmé
  // (`commitHistoryCheckpoint`). Un refus ou une exception qui interrompt l'appelant avant l'appel à
  // `commitHistoryCheckpoint` ne touche donc jamais aux piles — c'est tout l'objet de ce lot.
  // Une seule logique de déduplication/limite/purge, ici, jamais dupliquée ailleurs.
  function beginHistoryCheckpoint() {
    return snapshotState();
  }

  function commitHistoryCheckpoint(beforeSnapshot) {
    if (history.undo[history.undo.length - 1] !== beforeSnapshot) {
      history.undo.push(beforeSnapshot);
      if (history.undo.length > 80) history.undo.shift();
    }
    history.redo = [];
  }

  function recordHistory() {
    commitHistoryCheckpoint(snapshotState());
  }

  // Variante défensive pour le `catch` d'un onSave transactionnel (Lot correctif régressions) : une
  // exception peut survenir APRÈS que l'opération a déjà écrit dans state/settings/ui, alors que
  // l'appelant n'a jamais pu confirmer de succès pour appeler commitHistoryCheckpoint lui-même.
  // On n'engage le snapshot pré-opération dans Undo QUE si l'état a réellement changé depuis — une
  // exception levée AVANT toute mutation ne doit toucher ni Undo ni Redo.
  function commitHistoryCheckpointIfChanged(beforeSnapshot) {
    if (snapshotState() === beforeSnapshot) return false;
    commitHistoryCheckpoint(beforeSnapshot);
    return true;
  }

  // Restauration PUREMENT EN MÉMOIRE d'un snapshot (v2 ou legacy, via parseUndoSnapshot — jamais
  // normalizeState(JSON.parse(snapshot)) directement sur l'enveloppe, qui produirait un état quasi
  // vide puisque snapshotState() sérialise {version,state,settings,ui} et non le state brut). Ne
  // persist PAS, ne render PAS, ne touche NI history.undo NI history.redo : c'est le rollback d'une
  // opération métier refusée AVANT tout engagement de checkpoint (ex. validate-payment, Lot correctif
  // PAY-P0-1), quand l'appelant (ex. validatePayment) a pu écrire des champs avant de retourner false.
  function restoreHistoryCheckpointInMemory(snapshot) {
    const restored = parseUndoSnapshot(snapshot);
    if (!restored) return false;
    state = normalizeState(restored.state);
    // Même préservation des réglages visuels transitoires que restoreState (voir plus haut).
    const liveTransient = {};
    for (const key of historyExcludedSettingsKeys) liveTransient[key] = settings[key];
    settings = normalizeSettings(restored.settings);
    for (const key of historyExcludedSettingsKeys) settings[key] = liveTransient[key];
    applyUiSnapshot(restored.ui);
    return true;
  }

  const undoCheckpointElements = new WeakSet();

  function recordFieldHistoryOnce(target) {
    if (!target || undoCheckpointElements.has(target)) return;
    recordHistory();
    undoCheckpointElements.add(target);
  }

  function restoreState(snapshot, message) {
    if (!restoreHistoryCheckpointInMemory(snapshot)) return;
    persist(message);
    render();
  }

  function currentNavigationPoint() {
    return {
      view: ui.view,
      contactKind: ui.contactKind,
      stageId: ui.stageId,
      discipline: ui.discipline,
      contactLetter: ui.contactLetter,
      stageLetter: ui.stageLetter,
      disciplineLetter: ui.disciplineLetter,
      query: ui.query,
    };
  }

  function sameNavigationPoint(a = {}, b = {}) {
    return a.view === b.view
      && a.contactKind === b.contactKind
      && a.stageId === b.stageId
      && a.discipline === b.discipline
      && a.contactLetter === b.contactLetter
      && a.stageLetter === b.stageLetter
      && a.disciplineLetter === b.disciplineLetter
      && a.query === b.query;
  }

  function applyNavigationPoint(point) {
    // Pages protégées : on reverrouille tout en quittant un périmètre protégé.
    // On ne garde déverrouillé que le périmètre de la vue de destination, s'il l'était
    // déjà (ainsi on circule librement DANS un menu protégé sans re-saisir le mot de passe,
    // mais on re-saisit dès qu'on en sort puis qu'on y revient).
    const destKey = viewProtectionKey(point.view || "dashboard");
    ui.unlockedGroups = (destKey && ui.unlockedGroups && ui.unlockedGroups[destKey]) ? { [destKey]: true } : {};
    ui.view = point.view || "dashboard";
    ui.contactKind = point.contactKind || "members";
    ui.stageId = point.stageId || ui.stageId;
    ui.discipline = point.discipline || "";
    ui.contactLetter = point.contactLetter || "";
    ui.stageLetter = point.stageLetter || "";
    ui.disciplineLetter = point.disciplineLetter || "";
    ui.query = point.query || "";
  }

  function navigateTo(point) {
    const current = currentNavigationPoint();
    const next = { ...current, ...point };
    if (!Object.prototype.hasOwnProperty.call(point, "query")) next.query = "";
    if (sameNavigationPoint(current, next)) return;
    navigationHistory.back.push(current);
    if (navigationHistory.back.length > 80) navigationHistory.back.shift();
    navigationHistory.forward = [];
    applyNavigationPoint(next);
    render();
  }

  function openSearchView() {
    if (ui.view === "search") {
      render();
      return;
    }
    navigateTo({ view: "search" });
  }

  function navigateToViewFromMenu(view) {
    if (!views.some(([key]) => key === view)) return;
    const isSettingsSubView = settingsViews.some(([key]) => key === view);
    const isBoutiqueSubView = boutiqueViews.some(([key]) => key === view);
    ui.settingsMenuOpen = view === "settings" ? true : isSettingsSubView;
    ui.boutiqueMenuOpen = view === "boutique" ? true : isBoutiqueSubView;
    navigateTo({ view });
  }

  async function handleShellMenuCommand(command = {}) {
    if (!command || typeof command !== "object") return;
    if (command.type === "navigate") {
      navigateToViewFromMenu(command.view);
      return;
    }
    if (command.type === "action" && command.action) {
      await handleAction({ dataset: { action: command.action } });
    }
  }

  function navigateBack() {
    const previous = navigationHistory.back.pop();
    if (!previous) {
      ui.saveMessage = "Aucune page précédente";
      render();
      return;
    }
    navigationHistory.forward.push(currentNavigationPoint());
    applyNavigationPoint(previous);
    render();
  }

  function navigateForward() {
    const next = navigationHistory.forward.pop();
    if (!next) {
      ui.saveMessage = "Aucune page suivante";
      render();
      return;
    }
    navigationHistory.back.push(currentNavigationPoint());
    applyNavigationPoint(next);
    render();
  }

  function undoChange() {
    const previous = history.undo.pop();
    if (!previous) {
      ui.saveMessage = "Aucune modification à annuler";
      render();
      return;
    }
    history.redo.push(snapshotState());
    restoreState(previous, "Modification annulée");
  }

  function redoChange() {
    const next = history.redo.pop();
    if (!next) {
      ui.saveMessage = "Aucune modification à rétablir";
      render();
      return;
    }
    history.undo.push(snapshotState());
    restoreState(next, "Modification rétablie");
  }

  function persist(message = "Enregistré automatiquement") {
    logActivity(message);
    try {
      saveCurrentClubPayload();
    } catch (error) {
      console.error(error);
      ui.saveMessage = "Erreur d'enregistrement";
      return;
    }
    ui.saveMessage = message;
    maybeAutoBackupSeason();
  }

  function logActivity(message) {
    const text = asText(message);
    if (!text || text === "Enregistré automatiquement" || text === "Note enregistrée" || text === "Historique effacé") return;
    state.activityLog = normalizeActivityLog(state.activityLog);
    const last = state.activityLog[state.activityLog.length - 1];
    if (last && last.message === text && Date.now() - (parseDate(last.at)?.getTime() || 0) < 1500) return;
    state.activityLog.push({
      id: id("log"),
      at: new Date().toISOString(),
      message: text,
      view: Object.fromEntries(views)[ui.view] || ui.view || "",
      clubId: activeClubId(),
    });
    if (state.activityLog.length > 300) state.activityLog = state.activityLog.slice(-300);
  }

  function esc(value) {
    return repairLegacyAccentText(value)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;");
  }

  function id(prefix) {
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  }

  function makeArticleReference(name, index) {
    const cleaned = asText(name)
      .normalize("NFD")
      .replace(/\p{Diacritic}/gu, "")
      .replace(/[^a-zA-Z0-9 ]/g, " ")
      .trim()
      .toUpperCase();
    const initials = cleaned.split(/\s+/).map((part) => part[0]).join("");
    const code = (initials || cleaned.slice(0, 3) || "ART").slice(0, 4).padEnd(3, "X");
    return `${code}-${String(index + 1).padStart(3, "0")}`;
  }

  function asNumber(value) {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    if (typeof value === "string") {
      const parsed = Number(value.replace(",", "."));
      return Number.isFinite(parsed) ? parsed : 0;
    }
    return 0;
  }

  function asText(value) {
    return repairLegacyAccentText(value).trim();
  }

  function normalizePaymentCheckCount(value) {
    const count = Math.round(asNumber(value));
    if (!count) return DEFAULT_PAYMENT_CHECK_COUNT;
    return Math.min(MAX_PAYMENT_CHECK_COUNT, Math.max(1, count));
  }

  function paymentCheckCount() {
    return normalizePaymentCheckCount(settings?.paymentCheckCount ?? DEFAULT_PAYMENT_CHECK_COUNT);
  }

  function paymentIndexes(count = paymentCheckCount()) {
    return Array.from({ length: normalizePaymentCheckCount(count) }, (_, index) => index);
  }

  function paymentModeDefinitions() {
    return [
      ["cash", "Espèces"],
      ["check", "Chèque"],
      ["card", "Carte bancaire"],
      ["transfer", "Virement"],
      ["sport_coupon", "Coupons sport"],
      ["holiday_voucher", "Chèques vacances"],
      ["other", "Autre"],
    ];
  }

  function normalizePaymentModeKey(value = "") {
    const raw = asText(value);
    const normalized = normalizedPaymentValue(raw);
    if (!normalized) return "";
    if (/^\d+$/.test(normalized)) return "check";
    if (/^c\d+$/.test(normalized) || normalized === "check" || normalized === "cheque" || normalized === "cheques" || normalized === "chèque") return "check";
    if (/^cb\d+$/.test(normalized) || normalized === "cb" || normalized === "card" || normalized === "carte" || normalized.includes("carte bancaire")) return "card";
    if (/^esp\d+$/.test(normalized) || normalized === "cash" || normalized === "especes" || normalized === "espèce" || normalized === "espèces") return "cash";
    if (/^vir\d*$/.test(normalized) || normalized === "transfer" || normalized === "virement") return "transfer";
    if (normalized === "sport_coupon" || normalized === "coupon sport" || normalized === "coupons sport" || normalized === "coupon") return "sport_coupon";
    if (normalized === "holiday_voucher" || normalized === "holiday_check" || normalized === "cheque vacances" || normalized === "cheques vacances" || normalized === "chèque vacances" || normalized === "chèques vacances") return "holiday_voucher";
    if (normalized === "other" || normalized === "autre") return "other";
    return raw;
  }

  function paymentModeLabel(value = "") {
    const key = normalizePaymentModeKey(value);
    return Object.fromEntries(paymentModeDefinitions())[key] || asText(value) || "Paiement";
  }

  function acceptedPaymentModes(club = null) {
    let sourceClub = club;
    if (!sourceClub) {
      try {
        sourceClub = activeClub();
      } catch (error) {
        sourceClub = null;
      }
    }
    const accepted = (sourceClub?.payments?.acceptedModes || [])
      .map(normalizePaymentModeKey)
      .filter((key) => paymentModeDefinitions().some(([mode]) => mode === key));
    const values = accepted.length ? accepted : ["cash", "check", "card"];
    return uniqueValues(values);
  }

  function defaultPaymentMethod(index = 0) {
    return acceptedPaymentModes()[0] || "cash";
  }

  function paymentMethodOptions(index = 0, selected = "") {
    const value = asText(selected) || defaultPaymentMethod(index);
    const selectedKey = normalizePaymentModeKey(value);
    const options = acceptedPaymentModes();
    const selectedIsKnown = options.includes(selectedKey);
    const allOptions = options.includes(value) ? options : [...options, value];
    const normalizedOptions = selectedIsKnown ? options : allOptions;
    return normalizedOptions.map((option) => {
      const optionKey = normalizePaymentModeKey(option);
      const selectedAttr = selectedIsKnown ? optionKey === selectedKey : option === value;
      return `<option value="${esc(optionKey || option)}" ${selectedAttr ? "selected" : ""}>${esc(paymentModeLabel(option))}</option>`;
    }).join("");
  }

  function paymentMethodLabel(payment = {}, index = 0) {
    const raw = asText(payment.check) || defaultPaymentMethod(index);
    const key = normalizePaymentModeKey(raw);
    if (key === "check") return /^c\d+$/i.test(raw) ? raw.toUpperCase() : `Chèque ${index + 1}`;
    if (key === "card") return /^cb\d+$/i.test(raw) ? raw.toUpperCase() : `CB ${index + 1}`;
    if (key === "cash") return /^esp\d+$/i.test(raw) ? raw.replace(/^esp/i, "Esp") : `Esp ${index + 1}`;
    if (raw === "avoir") return "Avoir";
    return paymentModeLabel(raw);
  }

  function paymentMethodKind(payment = {}) {
    const key = normalizePaymentModeKey(payment.check || "");
    return key || "cash";
  }

  function isImmediatePayment(payment = {}) {
    return paymentMethodKind(payment) !== "check";
  }

  function normalizeImmediatePayment(payment = {}) {
    if (!isImmediatePayment(payment)) return payment;
    // « Refusé » est autorisé quel que soit le mode (chèque, espèces, CB, virement…) : on ne
    // l'efface jamais automatiquement. On nettoie seulement un « Payé » à montant nul (incohérent).
    if (asNumber(payment.amount) <= 0 && paymentStateValue(payment) === "Payé") payment.state = "";
    return payment;
  }

  function activeTheme() {
    return themes.find((theme) => theme.id === settings.theme) || themes[0];
  }

  function iconSvg(...paths) {
    return `<svg class="tool-icon" viewBox="0 0 24 24" aria-hidden="true">${paths.map((path) => `<path d="${path}"></path>`).join("")}</svg>`;
  }

  function toolbarIcon(name) {
    return toolbarIcons[name] || "";
  }

  function navButtonHtml(key, label, active = false) {
    return `<button data-view="${esc(key)}" class="${active ? "active" : ""}"><span class="nav-icon">${menuIconSvg(key)}</span><span class="nav-label">${esc(label)}</span></button>`;
  }

  function normalizedPersonText(value) {
    return asText(value).toLowerCase().normalize("NFD").replace(/\p{Diacritic}/gu, "");
  }

  function personKey(row = {}) {
    return `${normalizedPersonText(row.lastName)}|${normalizedPersonText(row.firstName)}`;
  }

  function personLabel(row = {}) {
    return [row.lastName, row.firstName].filter(Boolean).join(" ").trim() || "Le contact";
  }

  function safeTemplateValue(value) {
    if (value === null || value === undefined) return "";
    if (value instanceof Date) return dateDisplay(value);
    if (typeof value === "number") return Number.isFinite(value) ? String(value) : "";
    if (typeof value === "boolean") return value ? "Oui" : "Non";
    if (typeof value === "object") return "";
    const text = asText(value);
    return ["undefined", "null", "NaN", "[object Object]"].includes(text) ? "" : text;
  }

  function supportedEmailVariableKeys() {
    return [
      "clubNom", "clubSigle", "clubEmail", "clubTelephone", "clubAdresse", "clubCodePostal", "clubVille", "clubPays", "clubSite", "clubSiret", "clubSiren", "clubRna", "clubTva", "clubMentionTva",
      "club", "nomClub", "nom_club", "clubName", "club_name",
      "contactNom", "contactPrenom", "contactEmail", "contactTelephone", "contactPortable", "contactAdresse", "contactCodePostal", "contactVille", "contactDateNaissance", "contactCategorie",
      "nom", "prenom", "nom_complet", "email", "telephone", "portable", "adresse", "ville", "codePostal",
      "montantDu", "resteAPayer", "montantTotal", "montantPaye", "dateEcheance", "modePaiement", "numeroCheque", "statutPaiement", "discipline", "stage", "article",
      "categorie", "detail", "message", "note", "complement", "signatureLibre", "montant", "date", "module",
      "factureNumero", "factureDate", "factureStatut", "factureTotal", "facturePaye", "factureReste", "factureLignes",
      "titre", "public", "lieu", "identifiant",
      // Coachs / salles / séances (Phase E) — défaut "" via emptyEmailContext (jamais undefined/null).
      "coachNom", "coachPrenom", "coachEmail", "coachTelephone", "coachSpecialites",
      "salleNom", "salleAdresse", "salleType", "salleCapacite", "salleResponsableNom", "salleResponsableEmail", "salleResponsableTelephone", "salleTarif",
      "dateSeance", "heureDebut", "heureFin", "statutSeance",
      // Groupes (e-mail aux membres d'un groupe) — défaut "" via emptyEmailContext.
      "groupeNom", "groupeDiscipline", "groupeCoach", "groupeSalle", "groupeNombreMembres",
    ];
  }

  // Contexte de variables pour un coach (valeurs sûres : jamais undefined/null/NaN/[object Object]).
  function coachEmailContext(coach = {}) {
    return {
      coachNom: safeTemplateValue(coach.lastName),
      coachPrenom: safeTemplateValue(coach.firstName),
      coachEmail: safeTemplateValue(coach.email),
      coachTelephone: safeTemplateValue(coach.phone),
      coachSpecialites: safeTemplateValue((Array.isArray(coach.specialties) ? coach.specialties : []).join(", ")),
    };
  }

  // Contexte de variables pour une salle + son responsable.
  function roomEmailContext(room = {}) {
    return {
      salleNom: safeTemplateValue(room.name),
      salleAdresse: safeTemplateValue(room.address),
      salleType: safeTemplateValue(room.type),
      salleCapacite: safeTemplateValue(room.capacity === "" || room.capacity === undefined || room.capacity === null ? "" : room.capacity),
      salleResponsableNom: safeTemplateValue(room.managerName),
      salleResponsableEmail: safeTemplateValue(room.managerEmail),
      salleResponsableTelephone: safeTemplateValue(room.managerPhone),
      salleTarif: safeTemplateValue(room.rentalPrice === "" || room.rentalPrice === undefined || room.rentalPrice === null ? "" : money(room.rentalPrice)),
    };
  }

  // Contexte de variables pour un groupe (valeurs sûres : jamais undefined/null/NaN/[object Object]).
  // Salle : déduite d'un créneau de planning lié au groupe (state.planningCourses du club actif).
  function groupEmailContext(group = {}) {
    if (!group || !group.id) {
      return { groupeNom: "", groupeDiscipline: "", groupeCoach: "", groupeSalle: "", groupeNombreMembres: "" };
    }
    const courses = (state.planningCourses || []).filter((c) => c.groupId === group.id);
    const course = courses.find((c) => !c.archived) || courses[0] || null;
    const salle = course
      ? (typeof courseRoomLabel === "function" ? courseRoomLabel(course) : asText(course.location))
      : "";
    const coachLabel = (typeof coachLabelFor === "function")
      ? coachLabelFor(group.coachId, group.coach)
      : asText(group.coach);
    const count = (typeof getMembersByGroup === "function") ? getMembersByGroup(group.id).length : 0;
    return {
      groupeNom: safeTemplateValue(group.name),
      groupeDiscipline: safeTemplateValue(group.discipline),
      groupeCoach: safeTemplateValue(coachLabel),
      groupeSalle: safeTemplateValue(salle),
      groupeNombreMembres: safeTemplateValue(count),
      // Alias pratique : {discipline} reprend aussi la discipline du groupe pour ce public.
      discipline: safeTemplateValue(group.discipline),
    };
  }

  function emptyEmailContext() {
    return Object.fromEntries(supportedEmailVariableKeys().map((key) => [key, ""]));
  }

  function sanitizeTemplateContext(values = {}) {
    return Object.fromEntries(Object.entries(values || {}).map(([key, value]) => [key, safeTemplateValue(value)]));
  }

  function customEmailTemplateContext(templateKey = "") {
    const row = emailTemplates()[templateKey] || {};
    const fields = emailTemplateCustomFields(templateKey);
    return Object.fromEntries(fields.map(([field]) => [field, safeTemplateValue(row.customVariables?.[field])]));
  }

  function clubEmailContext(club = activeClub()) {
    const source = club || {};
    const contact = source.contact || {};
    const admin = source.admin || {};
    const clubNom = safeTemplateValue(source.name || (!source.id ? settings?.clubName : ""));
    const clubAdresse = [contact.address, contact.address2].map(safeTemplateValue).filter(Boolean).join(", ");
    const clubMentionTva = safeTemplateValue(admin.vatMention || (isVatRegimeExempt(admin.vatRegime) ? "TVA non applicable, art. 293 B du CGI" : ""));
    return {
      clubNom,
      clubSigle: safeTemplateValue(source.shortName),
      clubEmail: safeTemplateValue(contact.email),
      clubTelephone: safeTemplateValue(contact.phone),
      clubAdresse,
      clubCodePostal: safeTemplateValue(contact.postalCode),
      clubVille: safeTemplateValue(contact.city),
      clubPays: safeTemplateValue(contact.country),
      clubSite: safeTemplateValue(contact.website),
      clubSiret: safeTemplateValue(admin.siret),
      clubSiren: safeTemplateValue(admin.siren),
      clubRna: safeTemplateValue(admin.rna),
      clubTva: safeTemplateValue(admin.vatNumber),
      clubMentionTva,
      club: clubNom,
      nomClub: clubNom,
      nom_club: clubNom,
      clubName: clubNom,
      club_name: clubNom,
    };
  }

  // Logo à utiliser dans un e-mail HTML : logo personnalisé du club actif, sinon logo global de
  // l'app, sinon le logo MonGestaClub par défaut — EXACTEMENT la même priorité que les factures/
  // PDF (invoiceDocumentPayload : club.logoDataUrl > settings.logoDataUrl > defaultLogoDataUrl()).
  // Un lot précédent excluait volontairement ce dernier repli des e-mails ; corrigé ici (retour
  // Thierry) car ça créait une incohérence — le logo visible sur facture/PDF et dans l'app
  // disparaissait sans raison du mail dès qu'aucun logo personnalisé n'était configuré (cas de
  // tout club neuf/démo). defaultLogoDataUrl() est déjà préchargé au démarrage
  // (preloadDefaultLogoDataUrl) ; "" tant qu'il n'est pas encore prêt -> renderEmailHtml bascule
  // proprement sur le nom du club, jamais d'image cassée.
  function resolveClubLogoForEmail(club = activeClub()) {
    const source = club || {};
    if (typeof isLogoDataUrl === "function" && isLogoDataUrl(source.logoDataUrl)) return source.logoDataUrl;
    if (typeof isLogoDataUrl === "function" && isLogoDataUrl(settings?.logoDataUrl)) return settings.logoDataUrl;
    return (typeof defaultLogoDataUrl === "function" && defaultLogoDataUrl()) || "";
  }

  // Lot H-B — variante ASYNC de resolveClubLogoForEmail, réservée à la préparation d'un envoi SMTP
  // réel (prepareEmailForSmtp ci-dessous) : élimine la fenêtre de course diagnostiquée en Lot H-A où
  // defaultLogoDataUrl() peut renvoyer "" si le préchargement de démarrage (preloadDefaultLogoDataUrl,
  // déclenché une seule fois, en tâche de fond, à la fin de initApp()) n'a pas encore résolu.
  // N'attend QUE si les deux premiers niveaux (logo du club / logo settings) sont absents — jamais de
  // blocage pour un club qui a déjà un logo configuré, jamais de blocage du reste de l'application
  // (cette fonction n'est appelée qu'au moment de préparer un envoi SMTP, pas au démarrage).
  async function resolveClubLogoForEmailReady(club = activeClub()) {
    const source = club || {};
    if (typeof isLogoDataUrl === "function" && isLogoDataUrl(source.logoDataUrl)) return source.logoDataUrl;
    if (typeof isLogoDataUrl === "function" && isLogoDataUrl(settings?.logoDataUrl)) return settings.logoDataUrl;
    // Lot H-B (correction étroite) — utilise DIRECTEMENT la valeur résolue par la promesse attendue
    // (le retour réel de preloadDefaultLogoDataUrl), plutôt que de relire ensuite un cache privé
    // séparé : rend la fonction authentiquement testable (un test peut fournir une promesse
    // contrôlée et vérifier que sa valeur de résolution est bien celle utilisée), et élimine tout
    // scénario où l'attente aurait lieu sans que son résultat ne soit réellement exploité.
    if (typeof preloadDefaultLogoDataUrl === "function") {
      try {
        const preloaded = await preloadDefaultLogoDataUrl();
        if (typeof isLogoDataUrl === "function" && isLogoDataUrl(preloaded)) return preloaded;
      } catch (e) {}
    }
    return (typeof defaultLogoDataUrl === "function" && defaultLogoDataUrl()) || "";
  }

  // Lot H-B — CID constant du logo dans un e-mail SMTP (voir prepareEmailForSmtp). Doit rester
  // EXACTEMENT identique à la constante de même nom dans budo-electron/main.js (smtpSend) : c'est ce
  // même identifiant que Nodemailer associe à la pièce jointe inline pour que <img src="cid:..."> la
  // retrouve. Les deux fichiers tournent dans des processus Electron séparés (renderer/main), donc
  // aucun module partagé possible ici — la valeur est dupliquée intentionnellement, pas oubliée.
  const EMAIL_LOGO_CID = "mongestaclub-club-logo@mongestaclub";

  // Lignes de pied de mail (nom du club + coordonnées si renseignées). Une ligne par info
  // disponible ; les champs vides sont simplement omis (pas de coordonnée à moitié affichée).
  function clubEmailFooterLines(club = activeClub()) {
    const ctx = clubEmailContext(club);
    const lines = [ctx.clubNom];
    const coord = [ctx.clubAdresse, [ctx.clubCodePostal, ctx.clubVille].filter(Boolean).join(" ")].filter(Boolean).join(" — ");
    if (coord) lines.push(coord);
    const contactLine = [ctx.clubTelephone, ctx.clubEmail].filter(Boolean).join(" · ");
    if (contactLine) lines.push(contactLine);
    return lines;
  }

  // Bloc "Détails" structuré : n'affiche que les variables réellement renseignées dans le
  // contexte du mail (séance, coach, groupe, montant...). Bloc entier omis si rien à montrer.
  function emailDetailRows(context = {}) {
    const rows = [];
    const push = (label, value) => {
      const v = safeTemplateValue(value);
      if (v) rows.push([label, v]);
    };
    push("Discipline", context.discipline);
    push("Date", context.dateSeance || context.date);
    const horaire = [context.heureDebut, context.heureFin].filter((v) => safeTemplateValue(v)).join(" - ");
    if (horaire) push("Horaire", horaire);
    push("Lieu", context.lieu || context.salleNom);
    const coach = [context.coachPrenom, context.coachNom].filter((v) => safeTemplateValue(v)).join(" ") || context.groupeCoach;
    push("Coach", coach);
    push("Groupe", context.groupeNom);
    push("Statut", context.statutSeance || context.factureStatut);
    push("Montant", context.montant || context.montantDu || context.factureReste);
    return rows;
  }

  // Lot H-B — cœur du template "carte e-mail", factorisé pour être PARTAGÉ, à l'octet près, entre
  // l'aperçu local (logoSrc = data:...) et l'envoi SMTP réel (logoSrc = cid:...) : un seul template
  // visuel, deux façons de désigner la MÊME image. Ne résout jamais lui-même le logo (ni sa
  // priorité, ni son préchargement) : reçoit logoSrc déjà décidé par l'appelant — "" => repli texte
  // (nom du club), jamais d'image cassée. Compatible Gmail/Outlook/Apple Mail/Thunderbird : tableaux
  // HTML pour la structure, styles inline uniquement, largeur fixe ~600px.
  function emailCardHtml(subject, text, logoSrc, clubName, options = {}) {
    const club = options.club;
    const details = options.details || emailDetailRows(options.context || {});
    const footerLines = options.footerLines || clubEmailFooterLines(club);
    const bodyHtml = esc(text).replace(/\n/g, "<br>");
    const headerHtml = logoSrc
      ? `<img src="${esc(logoSrc)}" alt="${esc(clubName)}" width="120" style="display:block;max-width:120px;height:auto;margin:0 auto;border:0;outline:none;" />`
      : `<strong style="display:block;font-size:20px;color:#ffffff;letter-spacing:.3px;font-family:Arial,Helvetica,sans-serif;">${esc(clubName)}</strong>`;
    const detailsHtml = details.length ? `
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:20px;border:1px solid #e2e2e2;border-radius:6px;border-collapse:collapse;">
          <tr><td colspan="2" style="padding:8px 12px;background:#f4f4f2;font:bold 12px Arial,Helvetica,sans-serif;color:#555555;border-bottom:1px solid #e2e2e2;">Détails</td></tr>
          ${details.map(([label, value]) => `<tr>
            <td style="padding:7px 12px;font:13px Arial,Helvetica,sans-serif;color:#777777;width:38%;border-bottom:1px solid #f0f0f0;vertical-align:top;">${esc(label)}</td>
            <td style="padding:7px 12px;font:13px Arial,Helvetica,sans-serif;color:#222222;border-bottom:1px solid #f0f0f0;">${esc(value)}</td>
          </tr>`).join("")}
        </table>` : "";
    const footerHtml = footerLines.filter(Boolean).map(esc).join("<br>");
    return `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>${esc(subject)}</title>
</head>
<body style="margin:0;padding:0;background:#eef0f2;overflow-x:hidden;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;background:#eef0f2;">
    <tr><td align="center" style="padding:24px 12px;">
      <!-- width="600" = repli pour les moteurs qui ignorent le CSS (vieux Outlook/Word) ; le
           style width:100%;max-width:600px rend la carte fluide (aperçu app + petits écrans mail)
           sans jamais dépasser 600px sur un vrai client mail large. Technique email standard,
           ne change rien à la compatibilité. -->
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #dfe1e4;border-radius:10px;border-collapse:separate;">
        <tr><td style="background:#2f3740;padding:22px 24px;border-radius:10px 10px 0 0;text-align:center;">
          ${headerHtml}
        </td></tr>
        <tr><td style="padding:28px 28px 8px;">
          <h1 style="margin:0 0 16px;font:bold 18px Arial,Helvetica,sans-serif;color:#20242a;">${esc(subject)}</h1>
          <div style="font:14px/1.6 Arial,Helvetica,sans-serif;color:#333333;">${bodyHtml}</div>
          ${detailsHtml}
        </td></tr>
        <tr><td style="padding:20px 28px 24px;">
          <hr style="border:none;border-top:1px solid #ececec;margin:0 0 16px;" />
          <p style="margin:0;font:12px/1.6 Arial,Helvetica,sans-serif;color:#8a8f98;text-align:center;">
            ${footerHtml}<br>
            <span style="color:#b7bbc2;">Message envoyé depuis MonGestaClub</span>
          </p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;
  }

  // Rendu HTML "carte e-mail" pour l'APERÇU LOCAL uniquement (iframe sandboxée dans le dialogue
  // e-mail / la page Newsletter) : le logo y reste une image data:... — c'est un aperçu affiché
  // localement dans l'app, jamais transmis à un serveur SMTP, donc aucune limite de client mail ne
  // s'applique ici. Pour un envoi SMTP réel, utiliser prepareEmailForSmtp() ci-dessous (logo en CID).
  function renderEmailHtml(subject = "", text = "", options = {}) {
    const club = options.club || (typeof activeClub === "function" ? activeClub() : {});
    const clubName = safeTemplateValue(options.clubName || club?.name || settings?.clubName || "MonGestaClub");
    // Lot H-B — correction du piège diagnostiqué en Lot H-A : une chaîne vide ou une valeur invalide
    // passée explicitement en options.logoDataUrl ne doit JAMAIS neutraliser silencieusement un vrai
    // logo disponible par repli. Le paramètre explicite n'est retenu que s'il est un data URL de
    // logo réellement valide (isLogoDataUrl) ; sinon, on retombe sur la priorité normale.
    const logo = (typeof isLogoDataUrl === "function" && isLogoDataUrl(options.logoDataUrl)) ? options.logoDataUrl : resolveClubLogoForEmail(club);
    return emailCardHtml(subject, text, logo, clubName, { ...options, club });
  }

  // Lot H-B — payload SMTP centralisé : même contenu (sujet/texte/détails/pied/logo choisi) que
  // l'aperçu (même template emailCardHtml, même priorité de logo via resolveClubLogoForEmailReady),
  // mais avec <img src="cid:..."> au lieu d'un data: URI directement dans le HTML transmis au
  // serveur SMTP — le logo réel est transmis SÉPARÉMENT (logoDataUrl) pour être joint en pièce
  // inline côté main process (voir smtpSend, budo-electron/main.js). Résout le logo de façon ASYNC
  // pour ne jamais rater le repli MonGestaClub par une pure question de timing de préchargement.
  // Si, malgré l'attente, aucun logo valide n'est disponible : repli texte existant, aucun cid:
  // référencé dans le HTML, aucune pièce jointe vide côté main process.
  // Lot H-B (correction étroite) — le main process applique une validation PLUS STRICTE du logo
  // (decodeLogoDataUrlForAttachment, budo-electron/main.js) que ce que le renderer peut vérifier
  // (isLogoDataUrl ne regarde que le préfixe MIME + la forme base64, jamais les octets réels). Si le
  // main process échoue à construire la pièce jointe (signature réelle incohérente, buffer vide,
  // taille excessive…), le HTML transmis à Nodemailer NE DOIT JAMAIS référencer un cid: orphelin —
  // deux variantes du MÊME template (emailCardHtml, jamais dupliqué/recopié) sont donc produites ici :
  // `html` (logo en cid:) et `htmlWithoutLogo` (repli texte). smtpSend() choisit laquelle envoyer
  // SEULEMENT une fois la pièce jointe réellement construite avec succès — jamais l'inverse.
  async function prepareEmailForSmtp(subject = "", text = "", options = {}) {
    const club = options.club || (typeof activeClub === "function" ? activeClub() : {});
    const clubName = safeTemplateValue(options.clubName || club?.name || settings?.clubName || "MonGestaClub");
    const logoDataUrl = await resolveClubLogoForEmailReady(club);
    const logoSrc = logoDataUrl ? `cid:${EMAIL_LOGO_CID}` : "";
    const html = emailCardHtml(subject, text, logoSrc, clubName, { ...options, club });
    const htmlWithoutLogo = logoDataUrl ? emailCardHtml(subject, text, "", clubName, { ...options, club }) : html;
    return { subject, text, html, htmlWithoutLogo, logoDataUrl };
  }

  function emailContextForContact(row = {}) {
    const phone = asText(row.mobile || row.phone);
    const address = [row.address, row.address2].map(safeTemplateValue).filter(Boolean).join(", ");
    const category = memberCategory(row);
    return {
      nom: asText(row.lastName),
      prenom: asText(row.firstName),
      nom_complet: personLabel(row),
      email: asText(row.email),
      telephone: phone,
      portable: asText(row.mobile),
      adresse: address,
      ville: asText(row.city),
      codePostal: asText(row.postalCode),
      contactNom: asText(row.lastName),
      contactPrenom: asText(row.firstName),
      contactEmail: asText(row.email),
      contactTelephone: phone,
      contactPortable: asText(row.mobile),
      contactAdresse: address,
      contactCodePostal: asText(row.postalCode),
      contactVille: asText(row.city),
      contactDateNaissance: dateDisplay(row.birthDate),
      contactCategorie: category,
    };
  }

  function invoiceEmailContext(invoice = {}) {
    const source = invoice && typeof invoice === "object" && !Array.isArray(invoice) ? invoice : {};
    const lines = Array.isArray(source.lines) ? source.lines : [];
    const payments = Array.isArray(source.paymentsSnapshot) ? source.paymentsSnapshot : Array.isArray(source.payments) ? source.payments : [];
    // PAY-P0-2/F2 — un email (rappel/relance) doit refléter le solde COURANT, pas seulement
    // paymentsSnapshot figé à l'émission : vivant claim-aware pour toute facture réellement identifiée.
    const totals = source.id ? invoiceLiveTotals(source) : (lines.length || payments.length ? invoiceTotalsFromLines(lines, payments) : { total: 0, paid: 0, restDue: 0 });
    const status = source.id || source.status ? invoiceStatusLabel({ ...source, status: computedInvoiceStatus(source) }) : "";
    return {
      factureNumero: safeTemplateValue(source.number || (source.status === "draft" ? "Brouillon de facture" : "")),
      factureDate: dateDisplay(source.issuedAt || source.createdAt),
      factureStatut: status,
      factureTotal: source.id || lines.length ? money(totals.total) : "",
      facturePaye: source.id || payments.length ? money(totals.paid) : "",
      factureReste: source.id || lines.length || payments.length ? money(totals.restDue) : "",
      factureLignes: lines.map((line) => [invoiceSourceTypeLabel(line.sourceType), line.label, line.total !== undefined ? money(line.total) : ""].map(safeTemplateValue).filter(Boolean).join(" - ")).join("\n"),
    };
  }

  function emailTemplateContext(values = {}, templateKey = "") {
    return {
      ...emptyEmailContext(),
      ...clubEmailContext(),
      ...invoiceEmailContext(values.invoice || values.facture || {}),
      identifiant: safeTemplateValue(license?.machineId),
      ...sanitizeTemplateContext(values),
      ...customEmailTemplateContext(templateKey),
    };
  }

  function renderTextTemplate(text = "", values = {}, templateKey = "") {
    const context = emailTemplateContext(values, templateKey);
    return asText(text).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, key) => (
      Object.prototype.hasOwnProperty.call(context, key) ? context[key] : match
    ));
  }

  function renderEmailTemplate(templateKey, values = {}) {
    const template = emailTemplates()[templateKey] || emailTemplateDefinitions()[templateKey] || {};
    return {
      subject: renderTextTemplate(template.subject || "", values, templateKey),
      body: renderTextTemplate(template.body || "", values, templateKey),
    };
  }

  // Rendu complet {subject, text, html} d'un modèle : le texte reste celui du moteur existant
  // (inchangé, utilisé par mailto/copie), le HTML est le nouvel aperçu carte e-mail (Lot 2,
  // aucun envoi réel). `text` est conservé sous ce nom (et pas `body`) pour bien distinguer ce
  // triplet du couple {subject, body} historique de renderEmailTemplate.
  function renderEmailFull(templateKey, values = {}, options = {}) {
    const rendered = renderEmailTemplate(templateKey, values);
    const context = emailTemplateContext(values, templateKey);
    return {
      subject: rendered.subject,
      text: rendered.body,
      html: renderEmailHtml(rendered.subject, rendered.body, { context, ...options }),
    };
  }

  // --- Envoi SMTP intégré (MVP, renderer) -----------------------------------------------------
  // Le renderer ne manipule jamais le mot de passe SMTP : il prépare seulement destinataires,
  // sujet, texte et HTML, puis délègue au main process via window.monGestaClubShell (IPC). Absent
  // dans la version web budo-app (pas d'Electron) : smtpShellAvailable() protège tous les appels,
  // le fallback mailto/copie reste alors la seule voie, exactement comme avant ce lot.
  function smtpShellAvailable() {
    return typeof window !== "undefined" && !!window.monGestaClubShell && typeof window.monGestaClubShell.smtpSend === "function";
  }

  function activeClubIdForSmtp() {
    try {
      return (typeof activeClub === "function" && activeClub()?.id) || "default";
    } catch (error) {
      return "default";
    }
  }

  async function refreshSmtpSecretStatus() {
    if (!smtpShellAvailable()) {
      ui.smtpSecretStatus = { present: false, secure: false };
      return ui.smtpSecretStatus;
    }
    try {
      ui.smtpSecretStatus = await window.monGestaClubShell.smtpSecretStatus(activeClubIdForSmtp());
    } catch (error) {
      ui.smtpSecretStatus = { present: false, secure: false };
    }
    return ui.smtpSecretStatus;
  }

  // À appeler à CHAQUE changement de club actif (voir loadActiveClubFromStore, seul point commun
  // à switchActiveClub / création+activation d'un club / suppression du club actif). Les réglages
  // SMTP eux-mêmes (settings.smtp) et le secret (fichier main process indexé par clubId) sont déjà
  // correctement isolés par club — le bug constaté (config du club précédent encore affichée) venait
  // uniquement de deux caches côté UI qui ne se rechargent pas tout seuls quand `settings` change
  // sous eux : le brouillon d'édition (ui.smtpDraft) et le statut du secret (ui.smtpSecretStatus).
  // Sans ce reset, un club fraîchement activé affichait encore les champs ET le "mot de passe déjà
  // enregistré" du club précédent, alors même que settings.smtp et le secret réel étaient déjà,
  // eux, ceux du bon club. Remettre ui.smtpDraft à null a aussi pour effet secondaire voulu
  // d'abandonner un brouillon non enregistré du club précédent (jamais enregistré par erreur dans
  // le nouveau club actif).
  function invalidateSmtpUiStateForClubSwitch() {
    ui.smtpDraft = null;
    ui.smtpSecretStatus = undefined;
    ui.smtpTesting = false;
    ui.smtpSending = false;
    if (smtpShellAvailable()) refreshSmtpSecretStatus().then(() => render());
  }

  // Brouillon d'édition des champs SMTP (Paramètres > E-mails) : initialisé depuis settings.smtp,
  // puis conservé tel quel entre deux rendus tant que l'utilisateur tape (évite qu'un re-render
  // écrase la saisie en cours). Le mot de passe n'est JAMAIS pré-rempli depuis settings (il n'y est
  // de toute façon jamais stocké) : le champ reste vide, y compris après enregistrement.
  function smtpDraftValues() {
    const saved = smtpSettings();
    ui.smtpDraft = { ...saved, password: "", ...(ui.smtpDraft || {}) };
    if (ui.smtpDraft.password === undefined) ui.smtpDraft.password = "";
    return ui.smtpDraft;
  }

  // Bouton "Envoyer depuis MonGestaClub" affiché seulement si tout est prêt : shell Electron
  // disponible, envoi activé + hôte/expéditeur renseignés, ET un secret déjà enregistré côté main
  // process (sans quoi l'envoi échouerait silencieusement — voir consigne produit du lot).
  function smtpReadyForSend() {
    return smtpShellAvailable() && smtpConfigured() && Boolean(ui.smtpSecretStatus?.present);
  }

  function smtpStatusLabel() {
    const s = smtpSettings();
    if (!smtpShellAvailable()) return { key: "unavailable", label: "Indisponible (version web)" };
    if (!smtpConfigured() || !ui.smtpSecretStatus?.present) return { key: "unconfigured", label: "Non configuré" };
    if (s.lastTestOk === true) return { key: "ok", label: "Test réussi" };
    if (s.lastTestOk === false) return { key: "error", label: "Dernière erreur" };
    return { key: "configured", label: "Configuré (non testé)" };
  }

  // Enregistre les champs non sensibles dans settings.smtp (persistSettings normal) et, si un
  // nouveau mot de passe a été saisi, le transmet au main process pour stockage sécurisé — jamais
  // conservé dans settings/les sauvegardes JSON. Utilisé par "Enregistrer" ET "Tester l'envoi"
  // (qui enregistre d'abord, pour tester exactement la configuration affichée à l'écran).
  async function commitSmtpDraftSettings() {
    const draft = smtpDraftValues();
    const password = asText(draft.password || "");
    settings.smtp = normalizeSmtpSettings({
      ...settings.smtp,
      enabled: Boolean(draft.enabled),
      senderName: draft.senderName,
      senderEmail: draft.senderEmail,
      host: draft.host,
      port: draft.port,
      security: draft.security,
      username: draft.username,
      testAddress: draft.testAddress,
    });
    persistSettings();
    if (smtpShellAvailable() && password) {
      const result = await window.monGestaClubShell.smtpSaveSecret(activeClubIdForSmtp(), password);
      ui.smtpSecretStatus = { present: true, secure: Boolean(result?.secure) };
    } else if (smtpShellAvailable()) {
      await refreshSmtpSecretStatus();
    }
    draft.password = "";
  }

  // Envoi réel via SMTP (main process). Retourne toujours {ok, message?, accepted?, rejected?} —
  // jamais d'exception qui remonterait jusqu'à l'appelant : un échec réseau/auth doit rester une
  // réponse normale affichable, pas un crash.
  // Lot H-B — logoDataUrl transmis SÉPARÉMENT du html (qui référence "cid:..." et non ce data URL) :
  // c'est le main process (smtpSend, budo-electron/main.js) qui le transforme en pièce jointe inline
  // Nodemailer. preload.js n'a besoin d'aucun changement : `message` y est déjà transmis tel quel
  // (smtpSend: (clubId, config, message) => ipcRenderer.invoke(..., { clubId, config, message })).
  // htmlWithoutLogo (repli sans cid:) transmis en plus de html : le main process choisit lequel des
  // deux envoyer réellement selon que la pièce jointe logo a pu être construite ou non (voir
  // smtpSend, budo-electron/main.js) — jamais de cid: orphelin possible.
  async function sendEmailIntegrated({ to = [], bcc = [], subject = "", text = "", html = "", htmlWithoutLogo = "", logoDataUrl = "" } = {}) {
    if (!smtpShellAvailable()) return { ok: false, message: "Envoi intégré indisponible dans cette version." };
    try {
      const result = await window.monGestaClubShell.smtpSend(activeClubIdForSmtp(), smtpSettings(), { to, bcc, subject, text, html, htmlWithoutLogo: htmlWithoutLogo || html, logoDataUrl });
      return result || { ok: false, message: "Réponse invalide du processus principal." };
    } catch (error) {
      return { ok: false, message: asText(error?.message) || "Erreur d'envoi inconnue." };
    }
  }

  // TLD réservées par l'IANA (RFC 2606) : ne pointent JAMAIS vers une vraie boîte mail (utilisées
  // par les données de démonstration de MonGestaClub, ex. contact.email = "...@example.test").
  // Un serveur relais SMTP (Gmail, etc.) accepte généralement le RCPT TO au moment de l'envoi —
  // l'échec de livraison ne survient qu'ensuite, en différé (rebond), jamais visible dans la
  // réponse synchrone de nodemailer.sendMail(). D'où un avertissement explicite AVANT l'envoi,
  // plutôt que de compter sur le résultat SMTP pour détecter le problème après coup.
  const RESERVED_EMAIL_TLDS = ["test", "example", "invalid", "localhost"];
  function isReservedDemoEmailDomain(email) {
    const domain = asText(email).split("@")[1]?.toLowerCase() || "";
    const tld = domain.split(".").pop();
    return RESERVED_EMAIL_TLDS.includes(tld);
  }

  // Avertit avant un envoi réel vers un domaine manifestement fictif (voir isReservedDemoEmailDomain
  // ci-dessus). N'empêche jamais l'envoi (l'utilisateur peut vouloir tester le mécanisme) : renvoie
  // simplement false si l'utilisateur annule. Ne bloque jamais une adresse réelle.
  async function confirmReservedDemoEmailIfNeeded(email) {
    if (!isReservedDemoEmailDomain(email)) return true;
    const domain = asText(email).split("@")[1] || "";
    return requestConfirm({
      title: "Adresse de démonstration",
      message: `« ${email} » utilise un domaine réservé (${domain}), qui ne correspond à aucune vraie boîte mail. Le serveur SMTP peut répondre « accepté » sans que le message soit jamais réellement livré.\n\nEnvoyer quand même (pour tester le mécanisme), ou annuler ?`,
      confirmLabel: "Envoyer quand même",
    });
  }

  // Valide un résultat sendEmailIntegrated() pour UN destinataire unique (fiche contact, relance) :
  // ok:true seul ne suffit pas — un serveur relais peut accepter la transaction SMTP tout en
  // rejetant explicitement ce destinataire précis (adresse invalide, domaine inexistant détecté
  // immédiatement...). On ne traite comme échec que le rejet EXPLICITE de cette adresse : si
  // accepted/rejected sont tous deux vides (certains transports ne renseignent pas cette info), on
  // fait confiance à `ok` (comportement historique, aucun blocage arbitraire d'un envoi qui a
  // réellement réussi). Ce même helper est utilisé par le dialogue contact et pourra l'être par
  // tout futur envoi individuel, pour ne jamais dupliquer cette logique de validation.
  function singleRecipientSendSucceeded(result, email) {
    if (!result || !result.ok) return false;
    const rejected = result.rejected || [];
    const normalized = asText(email).toLowerCase();
    return !rejected.some((r) => asText(r).toLowerCase().includes(normalized));
  }

  function mailtoHref(email, subject = "", body = "") {
    const recipient = asText(email);
    if (!recipient) return "";
    return `mailto:${encodeURIComponent(recipient).replace(/%40/g, "@")}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  }

  function contactEmailHref(row = {}) {
    if (!asText(row.email)) return "";
    const rendered = renderEmailTemplate("contact", emailContextForContact(row));
    return mailtoHref(row.email, rendered.subject, rendered.body);
  }

  function emailTemplateOptions(selected = "contact") {
    return Object.entries(configurableEmailTemplateDefinitions()).map(([key, def]) => {
      const disabled = key === "newsletter" ? "disabled" : "";
      return `<option value="${esc(key)}" ${key === selected ? "selected" : ""} ${disabled}>${esc(def.label)}${key === "newsletter" ? " (newsletter)" : ""}</option>`;
    }).join("");
  }

  function openContactEmailDialog(contact = {}, templateKey = "contact", extraContext = {}) {
    if (!asText(contact.email)) {
      alert("Ce contact n'a pas d'adresse e-mail.");
      return;
    }
    const context = {
      ...emailContextForContact(contact),
      categorie: "contact",
      detail: "",
      montant: "",
      date: dateDisplay(dateInputValue(new Date())),
      module: "",
      identifiant: license?.machineId || "",
      ...extraContext,
    };
    const initial = renderEmailTemplate(templateKey, context);
    const initialHtml = renderEmailHtml(initial.subject, initial.body, { context });
    const smtpReady = smtpReadyForSend();
    const body = [
      field("email", "Destinataire", contact.email, "email", "readonly"),
      `<label>Modèle<select name="templateKey" data-contact-email-template>${emailTemplateOptions(templateKey)}</select></label>`,
      field("subject", "Objet", initial.subject),
      textareaField("body", "Message", initial.body),
      `<div class="email-model-help"><strong>Parties automatiques</strong><p>Les informations comme le nom, le prénom, l'e-mail, le téléphone, la date ou l'identifiant ordinateur sont insérées automatiquement depuis la fiche. Tu peux modifier le texte final avant l'envoi.</p></div>`,
      !smtpReady && smtpShellAvailable() ? `<p class="muted smtp-hint">Envoi intégré non configuré. Configurez le SMTP dans Paramètres &gt; E-mails, ou utilisez le bouton « Ouvrir la messagerie externe » ci-dessous.</p>` : "",
      `<p class="muted mailto-logo-hint">La messagerie externe prépare un message texte : la mise en page et le logo du club ne sont pas inclus.</p>`,
      `<div class="email-html-preview" style="margin-top:12px">
        <strong style="display:block;font-size:.86rem;color:var(--muted);margin-bottom:6px">Aperçu de l'e-mail</strong>
        <iframe title="Aperçu de l'e-mail" sandbox="" style="width:100%;height:360px;border:1px solid var(--line);border-radius:8px;background:#eef0f2" srcdoc="${esc(initialHtml)}"></iframe>
      </div>`,
    ].join("");
    // Hiérarchie des actions (retour Thierry après vidéo) : le bouton principal (à droite,
    // position de validation habituelle, style .primary déjà fourni par showDialog via
    // submitLabel) doit être l'envoi réellement effectué au clic — l'envoi SMTP intégré quand il
    // est prêt, sinon l'ouverture de la messagerie externe (seule option alors fonctionnelle :
    // pas de faux bouton d'envoi intégré désactivé). Quand le SMTP est prêt, la messagerie externe
    // devient une action secondaire explicite (bouton neutre, zone gauche du pied de dialogue,
    // jamais confondue avec l'action principale) plutôt que de disparaître.
    const mailtoFallbackButton = smtpReady
      ? `<button type="button" class="dialog-mailto-fallback" data-action="dialog-open-mailto" title="Ouvrir votre messagerie habituelle avec ce message déjà préparé">Ouvrir la messagerie externe</button>`
      : "";
    const submitLabel = smtpReady ? "Envoyer depuis MonGestaClub" : "Ouvrir la messagerie externe";
    showDialog("Envoyer un mail", body, async (form, formElement) => {
      const email = form.get("email");
      const subject = form.get("subject");
      const message = form.get("body");
      if (smtpReady) {
        if (!(await confirmReservedDemoEmailIfNeeded(email))) return false;
        const submitBtn = formElement?.querySelector(".dialog-footer-actions button[type=\"submit\"]");
        const originalLabel = submitBtn?.textContent;
        if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Envoi..."; }
        const smtpPayload = await prepareEmailForSmtp(subject, message, { context });
        const result = await sendEmailIntegrated({
          to: [email],
          subject: smtpPayload.subject,
          text: smtpPayload.text,
          html: smtpPayload.html,
          htmlWithoutLogo: smtpPayload.htmlWithoutLogo,
          logoDataUrl: smtpPayload.logoDataUrl,
        });
        if (singleRecipientSendSucceeded(result, email)) return `E-mail envoyé à ${personLabel(contact)}`;
        if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = originalLabel; }
        alert(result.ok
          ? `Le serveur a refusé cette adresse (${email}). L'e-mail n'a pas été envoyé.`
          : `Échec de l'envoi : ${result.message || "erreur inconnue"}`);
        return false;
      }
      window.location.href = mailtoHref(email, subject, message);
      return `Préparation d'un e-mail à ${personLabel(contact)}`;
    }, (formElement) => {
      const preview = formElement.querySelector(".email-html-preview iframe");
      const refreshPreview = () => {
        if (!preview) return;
        preview.srcdoc = renderEmailHtml(formElement.elements.subject.value, formElement.elements.body.value, { context });
      };
      formElement.elements.templateKey?.addEventListener("change", () => {
        const rendered = renderEmailTemplate(formElement.elements.templateKey.value, context);
        formElement.elements.subject.value = rendered.subject;
        formElement.elements.body.value = rendered.body;
        refreshPreview();
      });
      formElement.elements.subject?.addEventListener("input", refreshPreview);
      formElement.elements.body?.addEventListener("input", refreshPreview);
      const mailtoBtn = formElement.querySelector('[data-action="dialog-open-mailto"]');
      mailtoBtn?.addEventListener("click", () => {
        window.location.href = mailtoHref(formElement.elements.email.value, formElement.elements.subject.value, formElement.elements.body.value);
      });
    }, mailtoFallbackButton, () => {}, submitLabel);
  }

  function money(value) {
    return new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR" }).format(asNumber(value));
  }

  function compactMoney(value) {
    const amount = asNumber(value);
    return new Intl.NumberFormat("fr-FR", {
      style: "currency",
      currency: "EUR",
      maximumFractionDigits: Number.isInteger(amount) ? 0 : 2,
    }).format(amount).replace(/\s/g, "");
  }

  function intValue(value) {
    return new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 2 }).format(asNumber(value));
  }

  function normalizedPaymentValue(value) {
    return asText(value).toLowerCase().normalize("NFD").replace(/\p{Diacritic}/gu, "");
  }

  function parseDate(value) {
    if (!value) return null;
    if (value instanceof Date && !Number.isNaN(value.getTime())) return value;
    const raw = asText(value);
    if (!raw) return null;
    const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
    const fr = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
    if (fr) {
      const year = Number(fr[3].length === 2 ? `20${fr[3]}` : fr[3]);
      return new Date(year, Number(fr[2]) - 1, Number(fr[1]));
    }
    const parsed = new Date(raw);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  function dateInputValue(value) {
    const date = parseDate(value);
    if (!date) return "";
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function dateDisplay(value) {
    const date = parseDate(value);
    if (!date) return "";
    return new Intl.DateTimeFormat("fr-FR").format(date);
  }

  function formatDateTimeLocal(value) {
    if (!value) return "";
    let date = value instanceof Date ? value : new Date(asText(value));
    if (Number.isNaN(date.getTime())) date = parseDate(value);
    if (!date || Number.isNaN(date.getTime())) return "";
    return new Intl.DateTimeFormat("fr-FR", {
      dateStyle: "short",
      timeStyle: "short",
    }).format(date);
  }

  function ageFromBirthDate(value) {
    const birthDate = parseDate(value);
    if (!birthDate) return null;
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) age -= 1;
    return age >= 0 ? age : null;
  }

  function memberCategory(row = {}) {
    const age = ageFromBirthDate(row.birthDate);
    if (age === null) return asText(row.category);
    return age >= 18 ? "Adulte" : "Enfant";
  }

  function memberAgeLabel(row = {}) {
    const age = ageFromBirthDate(row.birthDate);
    return age === null ? "" : `${intValue(age)} ans`;
  }

  function normalizePayment(payment = {}) {
    const stateDate = parseDate(payment.state);
    const date = dateInputValue(payment.date || (stateDate ? payment.state : ""));
    const state = stateDate ? "" : paymentStateValue(payment);
    const normalized = {
      check: payment.check || "",
      checkNumber: asText(payment.checkNumber || payment.number),
      amount: asNumber(payment.amount),
      state,
      date,
    };
    applyNormalizedTaxRate(normalized, payment);
    if (paymentMethodKind(normalized) !== "check") normalized.checkNumber = "";
    if (payment.creditNoteId) normalized.creditNoteId = payment.creditNoteId;
    // PAY-P0-2/F2 — identité + allocations : PRÉSERVÉES si présentes, jamais FABRIQUÉES ici. Une
    // ancienne donnée sans id/allocations reste sans id/allocations après normalisation (sinon une
    // source et sa copie snapshot, toutes deux sans id, se verraient attribuer deux id DIFFÉRENTS au
    // chargement et sembleraient être deux transactions distinctes — cf. doctrine legacy PAY-P0-2).
    if (asText(payment.id)) normalized.id = asText(payment.id);
    const allocations = normalizePaymentAllocations(payment.allocations, normalized.amount);
    if (allocations.length) normalized.allocations = allocations;
    return normalizeImmediatePayment(normalized);
  }

  // Normalise strictement les allocations d'un paiement : claimKey texte non vide, amount >= 0, aucune
  // entrée invalide/NaN, jamais somme(allocations) > payment.amount (tolérance centime). N'invente
  // jamais d'entrée manquante, ne mute jamais le tableau source.
  function normalizePaymentAllocations(rawAllocations, paymentAmount = 0) {
    if (!Array.isArray(rawAllocations)) return [];
    const budget = Math.max(0, asNumber(paymentAmount)) + 0.005;
    const result = [];
    let used = 0;
    rawAllocations.forEach((entry) => {
      const claimKey = asText(entry?.claimKey);
      const amount = asNumber(entry?.amount);
      if (!claimKey || !Number.isFinite(amount) || amount <= 0) return;
      if (used + amount > budget) return;
      result.push({ claimKey, amount: Math.round(amount * 100) / 100 });
      used += amount;
    });
    return result;
  }

  function normalizePayments(payments = []) {
    return (payments || []).map((payment) => normalizePayment(payment));
  }

  function normalizeInvoice(source = {}) {
    const lines = Array.isArray(source.lines) ? source.lines.map((line) => normalizeInvoiceLine(line)).filter((line) => line.label || asNumber(line.total)) : [];
    const paymentsSnapshot = normalizePayments(source.paymentsSnapshot || []);
    // PAY-P0-2/F2 — transactions créées DEPUIS la facture APRÈS émission (règlement facture, avoir
    // imputé). Jamais de copie d'un paiement source ; jamais fusionné avec paymentsSnapshot (qui reste
    // purement documentaire, figé à l'émission). Valeur legacy par défaut : [].
    const paymentsAfterIssue = normalizePayments(source.paymentsAfterIssue || []);
    const totals = invoiceTotalsFromLines(lines, paymentsSnapshot);
    const status = ["draft", "issued", "paid", "partial", "late", "cancelled"].includes(source.status) ? source.status : "draft";
    return {
      id: asText(source.id || id("invoice")),
      clubId: asText(source.clubId || activeClubId()),
      contactId: asText(source.contactId),
      contactKind: ["members", "prospects"].includes(source.contactKind) ? source.contactKind : "members",
      number: asText(source.number),
      status,
      createdAt: source.createdAt || new Date().toISOString(),
      issuedAt: source.issuedAt || "",
      updatedAt: source.updatedAt || "",
      // Métadonnée d'impression (1re impression -> facture; impressions suivantes -> duplicata).
      // N'affecte ni les lignes, ni les montants, ni les snapshots, ni les paiements.
      printedAt: asText(source.printedAt || ""),
      clubSnapshot: source.clubSnapshot && typeof source.clubSnapshot === "object" ? clone(source.clubSnapshot) : null,
      contactSnapshot: source.contactSnapshot && typeof source.contactSnapshot === "object" ? clone(source.contactSnapshot) : null,
      lines,
      paymentsSnapshot,
      paymentsAfterIssue,
      totals: {
        total: totals.total,
        paid: totals.paid,
        restDue: totals.restDue,
      },
      notes: asText(source.notes),
    };
  }

  function normalizeInvoiceLine(source = {}) {
    const quantity = Math.max(0, asNumber(source.quantity || 1));
    const unitPrice = asNumber(source.unitPrice);
    const total = source.total === undefined ? quantity * unitPrice : asNumber(source.total);
    return {
      id: asText(source.id || id("invoice-line")),
      sourceType: asText(source.sourceType || "custom"),
      sourceId: asText(source.sourceId),
      sourceKey: asText(source.sourceKey || `${source.sourceType || "custom"}:${source.sourceId || id("line")}`),
      // PAY-P0-2/F2 — créance financière (claim) de cette ligne. PRÉSERVÉ si fourni, jamais fabriqué
      // ici pour une ancienne ligne (reconstruction en lecture seule via lineClaimKey, jamais persistée
      // automatiquement — cf. doctrine legacy PAY-P0-2). Les créateurs de NOUVELLES lignes (billable,
      // ligne custom) doivent le fournir explicitement.
      claimKey: asText(source.claimKey || ""),
      // Catégorie comptable d'une ligne personnalisée (recette custom). Vide pour les lignes
      // issues de sources déjà comptabilisées (cotisation/stage/boutique…).
      category: asText(source.category || ""),
      label: asText(source.label),
      description: asText(source.description),
      quantity,
      unitPrice,
      vatRate: Math.max(0, asNumber(source.vatRate ?? effectiveDefaultVatRate())),
      total,
    };
  }

  function invoiceTotalsFromLines(lines = [], payments = []) {
    const total = (lines || []).reduce((sum, line) => sum + asNumber(line.total ?? (asNumber(line.quantity || 1) * asNumber(line.unitPrice))), 0);
    const paid = Math.min(Math.max(0, total), paidAmount(payments || []));
    return { total, paid, restDue: total - paid };
  }

  function normalizeSizeStock(sizeStock = {}) {
    return Object.fromEntries(Object.entries(sizeStock || {})
      .filter(([size]) => asText(size))
      .map(([size, quantity]) => [asText(size), asNumber(quantity)]));
  }

  function sizeStockTotal(sizeStock = {}) {
    return Object.values(normalizeSizeStock(sizeStock)).reduce((sum, quantity) => sum + asNumber(quantity), 0);
  }

  function paymentStatus(payment) {
    // Annulé est un état canonique PERSISTÉ (payment.state === "Annulé"), traité avant tout calcul
    // dérivé par montant/méthode/date : un chèque annulé (amount conservé, date vidée) ne doit jamais
    // retomber dans le calcul "A encaisser"/"En cours" qui, lui, se fie uniquement à amount/date/méthode.
    if (paymentIsCancelled(payment)) return "Annulé";
    const value = payment?.state;
    const normalized = normalizedPaymentValue(value);
    const amount = asNumber(payment?.amount);
    if ((normalized === "paye" || normalized === "payee" || normalized === "ok") && amount > 0) return "OK";
    if (normalized === "refuse" || normalized === "alerter") return "Refusé";
    if (amount <= 0) return "";
    if (isImmediatePayment(payment)) return "";
    const date = parseDate(payment?.date) || parseDate(value);
    if (date) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      date.setHours(0, 0, 0, 0);
      return date <= today ? "A encaisser" : "En cours";
    }
    return "A encaisser";
  }

  function paymentDueDate(payment = {}) {
    return parseDate(payment?.date) || parseDate(payment?.state);
  }

  function paymentIsRefused(payment = {}) {
    return paymentStatus(payment) === "Refusé" || paymentStateValue(payment) === "Refusé";
  }

  function paymentIsLate(payment = {}) {
    if (asNumber(payment?.amount) <= 0 || paymentStatus(payment) === "OK" || isImmediatePayment(payment)) return false;
    if (paymentIsRefused(payment)) return true;
    const date = paymentDueDate(payment);
    if (!date) return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    date.setHours(0, 0, 0, 0);
    return date < today;
  }

  function paymentIsPendingOrPlanned(payment = {}) {
    if (asNumber(payment?.amount) <= 0 || paymentStatus(payment) === "OK" || paymentIsRefused(payment) || isImmediatePayment(payment)) return false;
    const date = paymentDueDate(payment);
    if (date) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      date.setHours(0, 0, 0, 0);
      return date >= today;
    }
    return paymentStatus(payment) === "En cours";
  }

  function paymentToneFromPayments(payments = [], restDue = 0) {
    if (asNumber(restDue) <= 0) return "paid";
    const rows = payments || [];
    if (rows.some(paymentIsLate)) return "due";
    if (rows.some(paymentIsPendingOrPlanned)) return "pending";
    return "due";
  }

  function paidAmount(payments) {
    return (payments || []).reduce((sum, payment) => {
      return paymentStatus(payment) === "OK" ? sum + asNumber(payment.amount) : sum;
    }, 0);
  }

  function clubVatRegime(club = activeClub()) {
    return asText(club?.admin?.vatRegime).toLowerCase();
  }

  function isVatRegimeExempt(value) {
    const regime = asText(value).toLowerCase();
    return regime === "non" || regime === "franchise" || regime.includes("non soumis") || regime.includes("franchise");
  }

  function isClubVatExempt(club = activeClub()) {
    return isVatRegimeExempt(clubVatRegime(club));
  }

  function clubVatMention(club = activeClub()) {
    const mention = asText(club?.admin?.vatMention);
    if (mention) return mention;
    return isClubVatExempt(club) ? "TVA non applicable, art. 293 B du CGI" : "";
  }

  function effectiveDefaultVatRate(club = activeClub()) {
    return isClubVatExempt(club) ? 0 : Math.max(0, asNumber(settings.defaultVatRate));
  }

  function effectiveTaxRate(item = {}, club = activeClub()) {
    if (isClubVatExempt(club)) return 0;
    return hasSpecificTaxRate(item) ? Math.max(0, asNumber(item.taxRate ?? item.vatRate ?? item.tva)) : effectiveDefaultVatRate(club);
  }

  function paymentTaxRate(payment = {}) {
    return effectiveTaxRate(payment);
  }

  function hasSpecificTaxRate(item = {}) {
    const raw = item.taxRate ?? item.vatRate ?? item.tva;
    return raw !== undefined && raw !== null && asText(raw) !== "";
  }

  function tariffTaxRate(item = {}) {
    return effectiveTaxRate(item);
  }

  function taxRateLabel(item = {}) {
    if (isClubVatExempt()) return "—";
    const rate = tariffTaxRate(item);
    return `${intValue(rate)}%${hasSpecificTaxRate(item) ? "" : " global"}`;
  }

  function hasSpecificLodgingTaxRate(stage = {}) {
    const raw = stage.lodgingTaxRate ?? stage.lodgingVatRate ?? stage.lodgingTva;
    return raw !== undefined && raw !== null && asText(raw) !== "";
  }

  function lodgingTaxRate(stage = {}) {
    if (isClubVatExempt()) return 0;
    return hasSpecificLodgingTaxRate(stage) ? Math.max(0, asNumber(stage.lodgingTaxRate ?? stage.lodgingVatRate ?? stage.lodgingTva)) : effectiveDefaultVatRate();
  }

  function lodgingTaxRateLabel(stage = {}) {
    if (isClubVatExempt()) return "—";
    const rate = lodgingTaxRate(stage);
    return `${intValue(rate)}%${hasSpecificLodgingTaxRate(stage) ? "" : " global"}`;
  }

  function blendedTaxRate(segments = []) {
    const validSegments = segments
      .map((segment) => ({ amount: asNumber(segment.amount), rate: Math.max(0, asNumber(segment.rate)) }))
      .filter((segment) => segment.amount > 0);
    if (isClubVatExempt()) return 0;
    if (!validSegments.length) return effectiveDefaultVatRate();
    const net = validSegments.reduce((sum, segment) => sum + (segment.amount / (1 + (segment.rate / 100))), 0);
    const tax = validSegments.reduce((sum, segment) => sum + taxAmountFromGross(segment.amount, segment.rate), 0);
    return net > 0 ? (tax / net) * 100 : effectiveDefaultVatRate();
  }

  function taxAmountFromGross(amount, rate) {
    const gross = asNumber(amount);
    const taxRate = Math.max(0, asNumber(rate));
    if (!gross || !taxRate) return 0;
    return gross - (gross / (1 + (taxRate / 100)));
  }

  function paymentTaxAmount(payment = {}) {
    return taxAmountFromGross(payment.amount, paymentTaxRate(payment));
  }

  function paidTaxAmount(payments = []) {
    return (payments || []).reduce((sum, payment) => {
      return paymentStatus(payment) === "OK" ? sum + paymentTaxAmount(payment) : sum;
    }, 0);
  }

  function alertStatusForPayments(payments) {
    const statuses = (payments || []).map(paymentStatus).filter((status) => status && status !== "OK" && status !== "Annulé");
    if (statuses.includes("Refusé")) return "Refusé";
    if (statuses.includes("A encaisser")) return "A encaisser";
    if (statuses.includes("En cours")) return "En cours";
    return "Reste dû";
  }

  function statusClass(status) {
    if (status === "OK" || status === "Payé") return "ok";
    if (status === "A encaisser" || status === "À payer" || status === "Reste dû" || status === "Partiel") return "due";
    if (status === "Alerter" || status === "Refusé" || status === "Non payé") return "late";
    if (status === "En cours") return "wait";
    return "";
  }

  function statusLabel(status) {
    if (status === "A encaisser") return "À encaisser";
    return status;
  }

  function statusPill(status) {
    if (!status) return `<span class="muted">-</span>`;
    return `<span class="status ${statusClass(status)}">${esc(statusLabel(status))}</span>`;
  }

  function paymentStateValue(payment) {
    const raw = asText(payment?.state);
    const normalized = normalizedPaymentValue(raw);
    if (!normalized) return "";
    if (normalized === "paye" || normalized === "payee" || normalized === "ok") return "Payé";
    if (normalized === "refuse" || normalized === "alerter") return "Refusé";
    // Reconnaît les variantes Annulé/Annule/Cancelled/Canceled (après normalisation : accents et
    // casse retirés, "Annulé"/"Annule" convergent déjà vers "annule") -> valeur canonique "Annulé".
    // Une valeur vide reste vide (jamais promue en Annulé) ; un ancien chèque sans état persisté
    // reste vide lui aussi -> ne tombe JAMAIS dans cette branche (rien à normaliser).
    if (normalized === "annule" || normalized === "cancelled" || normalized === "canceled") return "Annulé";
    if (parseDate(raw)) return "";
    return raw;
  }

  // État canonique d'annulation d'un paiement, indépendant de toute heuristique sur amount/date/
  // méthode et indépendant du Journal (audit log) : uniquement payment.state, normalisé.
  function paymentIsCancelled(payment = {}) {
    return paymentStateValue(payment) === "Annulé";
  }

  // Un paiement "compte" dans la répartition/le calcul de couverture de l'échéancier (montant déjà
  // couvert, pour suggérer/masquer les échéances suivantes) s'il représente un engagement réel :
  // exclut Refusé ET Annulé, jamais seulement Refusé. Centralise ce qui était auparavant dispersé
  // en plusieurs comparaisons textuelles "!== Refusé" (paymentSuggestion, visiblePaymentCount,
  // paymentCoverageAmount).
  function paymentCountsTowardSchedule(payment = {}) {
    const status = paymentStateValue(payment);
    return status !== "Refusé" && status !== "Annulé";
  }

  // Détecte, par index, les transitions de paiement RÉELLEMENT persistées entre un snapshot "avant
  // ouverture" du formulaire et l'état final effectivement sauvegardé. Helper pur (aucun DOM, aucun
  // appel d'audit direct) : les appelants ne l'invoquent que si le parent existait déjà avant
  // l'ouverture (fiche neuve = aucun snapshot = aucun appel = aucune transition possible, jamais
  // une chronologie inventée). Un index sans "avant" (échéance jamais touchée sur une fiche déjà
  // persistée) est traité comme une ligne vide, pas comme une absence de comparaison : "vide -> Payé"
  // doit produire une transition validated au même titre que "Annulé -> Payé".
  function paymentAuditTransitions(beforePayments = [], afterPayments = []) {
    const transitions = [];
    afterPayments.forEach((after, index) => {
      const before = beforePayments[index] || {};
      const beforeStatus = paymentStatus(before);
      const afterStatus = paymentStatus(after);
      if (beforeStatus !== "OK" && afterStatus === "OK") {
        transitions.push({ action: "validated", index, payment: after });
      } else if (beforeStatus === "OK" && paymentIsCancelled(after)) {
        transitions.push({ action: "cancelled", index, payment: after });
      }
    });
    return transitions;
  }

  function paymentStateOptions(value, amount = 0) {
    const options = ["", "Refusé"];
    const normalized = paymentStateValue({ state: value });
    // "Annulé" peut apparaître comme valeur COURANTE (ligne déjà annulée) sans jamais être ajouté
    // comme choix par défaut sur une ligne neuve : normalized ne vaut "Annulé" que si la ligne l'est
    // réellement déjà, auquel cas le fallback ci-dessous l'ajoute à la liste et le sélectionne.
    const safeValue = (normalized === "Refusé" || normalized === "Annulé") ? normalized : "";
    const allOptions = options.includes(safeValue) ? options : [...options, safeValue];
    return allOptions.map((option) => `<option value="${esc(option)}" ${safeValue === option ? "selected" : ""}>${option ? esc(option) : "-"}</option>`).join("");
  }

  // Lot I-B — les deux SEULS statuts paymentStatus() correspondant à un paiement pas encore encaissé
  // (celui que le message « lecture seule » de la consultation commande peut effectivement inviter à
  // traiter). Constante partagée (payments-core, consultation, handler cancel-pending-payment,
  // refresh) pour ne jamais faire diverger la liste entre l'affichage et la garde de mutation.
  const PENDING_PAYMENT_STATUSES = ["A encaisser", "En cours"];

  function paymentControls(module, rowId, payments, options = {}) {
    // Lot 3A (clôture absolue, FIN-PAY-1) — tarif ABSENT (billable=false) : aucun paiement ne doit être
    // suggéré ni saisi tant que le tarif n'est pas défini. On remplace le tiroir par une note explicite
    // UNIQUEMENT s'il n'existe encore aucun paiement (jamais de masquage de paiements déjà saisis).
    if (options.billable === false && !(payments || []).some(hasPaymentContent)) {
      return `<div class="payment-undefined-note muted">Tarif non défini — définissez le tarif de la discipline avant d'encaisser un paiement.</div>`;
    }
    const attrs = [
      `data-payment-module="${esc(module)}"`,
      `data-id="${esc(rowId)}"`,
      options.stageId ? `data-stage-id="${esc(options.stageId)}"` : "",
      options.part ? `data-part="${esc(options.part)}"` : "",
      options.total !== undefined ? `data-payment-total="${esc(asNumber(options.total))}"` : "",
    ].filter(Boolean).join(" ");
    const paymentRows = paymentIndexes().map((index) => (payments || [])[index] || {});
    return paymentDrawer(paymentRows, {
      mode: "live",
      attrs,
      total: options.total,
      defaultTaxRate: options.defaultTaxRate ?? effectiveDefaultVatRate(),
      maxChecks: paymentCheckCount(),
      title: "Paiements",
      // Lot I-B — restriction OPTIONNELLE et rétrocompatible (absente partout ailleurs, comportement
      // historique inchangé) : quand fournie, seules les lignes dont paymentStatus() figure dans cette
      // liste restent actionnables (bouton + champs actifs) ; les autres deviennent consultatives,
      // quel que soit leur statut (OK, Refusé, Annulé, vide). Voir compactPaymentEditor.
      actionableStatuses: options.actionableStatuses,
    });
  }

  function paymentDrawer(paymentRows, options = {}) {
    const maxChecks = normalizePaymentCheckCount(options.maxChecks ?? paymentRows.length);
    const rows = paymentIndexes(maxChecks).map((index) => paymentRows[index] || {});
    const mode = options.mode || "form";
    const total = asNumber(options.total);
    const visibleCount = visiblePaymentCount(rows, total, maxChecks);
    const firstEmpty = rows.slice(0, visibleCount).findIndex((p) => !hasPaymentContent(p));
    // Lot I-B — quand actionableStatuses est fourni (zone de consultation restreinte), on préfère
    // ouvrir l'onglet sur la première ligne réellement actionnable (ex. le paiement pending à
    // traiter) plutôt que sur la première ligne avec du contenu (qui pourrait être un paiement OK
    // déjà consultatif) : simple préférence d'affichage, ne change ni le calcul ni les données.
    const actionableIndex = Array.isArray(options.actionableStatuses)
      ? rows.slice(0, visibleCount).findIndex((p) => options.actionableStatuses.includes(paymentStatus(p)))
      : -1;
    const activeIndex = actionableIndex >= 0
      ? actionableIndex
      : firstEmpty >= 0
      ? firstEmpty
      : Math.min(Math.max(0, rows.findIndex(hasPaymentContent)), visibleCount - 1);
    return `<details class="payment-drawer ${mode} ${options.className || ""}" ${mode === "form" ? "open" : ""}>
      <summary>
        <span class="payment-drawer-title">${esc(options.title || "Paiements")}</span>
        <span class="payment-mini-list">${rows.map((payment, index) => paymentMiniChip(payment, index, index === activeIndex, options.attrs || "", paymentSuggestion(rows, index, total), index >= visibleCount)).join("")}</span>
        <button type="button" class="payment-show-all" data-payment-show-all title="Afficher tous les paiements en même temps" ${mode === "live" && visibleCount > 1 ? "" : "hidden"}>Tout afficher</button>
      </summary>
      <div class="payment-drawer-body">
        ${rows.map((payment, index) => compactPaymentEditor({
        index,
        payment,
        attrs: options.attrs || "",
        mode,
        prefix: options.prefix || "",
        active: index === activeIndex,
        visible: index < visibleCount,
        suggestedAmount: paymentSuggestion(rows, index, total),
        defaultTaxRate: options.defaultTaxRate,
        actionableStatuses: options.actionableStatuses,
        claimKey: options.claimKey || "",
      })).join("")}
      </div>
    </details>`;
  }

  function paymentSuggestion(rows, index, total = 0) {
    if (!total || hasPaymentContent(rows[index])) return 0;
    const previous = rows.slice(0, index).reduce((sum, payment) => {
      return paymentCountsTowardSchedule(payment) ? sum + asNumber(payment.amount) : sum;
    }, 0);
    return Math.max(0, total - previous);
  }

  function paidTotalForRows(rows, limit) {
    return rows.slice(0, limit).reduce((sum, payment) => {
      return paymentStatus(payment) === "OK" ? sum + asNumber(payment.amount) : sum;
    }, 0);
  }

  // Lot 2G-C1 — Validation/normalisation COMMUNE d'un montant de paiement SOUMIS. Unique règle au
  // centime partagée par le tiroir live (validate-payment : membership / order / registration) ET le
  // formulaire de la fiche (validate-form-payment) — aucune exception propre à un type de créance.
  //
  // La valeur RÉELLEMENT présente dans le champ au moment de la validation fait foi : le tiroir est
  // pré-rempli à l'ouverture avec la suggestion du reste dû (proposition automatique conservée), mais
  // dès que l'utilisateur l'efface ou la remplace, c'est sa saisie qui compte — JAMAIS de repli
  // silencieux sur la suggestion au moment de valider.
  //
  // Renvoie le montant ARRONDI AU CENTIME (au plus deux décimales), ou null (refus, aucune mutation) :
  //  - champ vide / espaces seuls / non numérique / NaN / Infinity / null / undefined  -> null ;
  //  - montant arrondi à moins de 0,01 € (0, 0.001, 0.0049…) ou négatif                 -> null.
  // Cohérent au centime avec isPayableDue() et money() : le prédicat Math.round(x*100) >= 1 est la
  // même frontière d'affichage (« 0,00 € » -> refusé, « 0,01 € » et plus -> accepté si la créance le
  // permet). La virgule décimale est tolérée (saisie FR). Le trop-perçu reste géré en aval par
  // paymentOverpayMessage (montant plafonné au reste réellement dû).
  function normalizeSubmittedPaymentAmount(rawValue) {
    const text = (typeof rawValue === "string" ? rawValue : rawValue == null ? "" : String(rawValue)).trim();
    if (!text) return null;
    const parsed = Number(text.replace(",", "."));
    if (!Number.isFinite(parsed)) return null;
    const cents = Math.round(parsed * 100);
    if (cents < 1) return null;
    return cents / 100;
  }

  // La couverture financière ne détermine plus SEULE le nombre de lignes visibles (une ligne
  // Refusé/Annulé/Payé/En cours/À encaisser antérieure au point de couverture ne doit jamais
  // disparaître simplement parce qu'une autre ligne, plus loin, couvre déjà le total) : on
  // parcourt TOUJOURS l'intégralité des index jusqu'à max (jamais d'arrêt anticipé sur la
  // première ligne vide rencontrée, ni sur la couverture atteinte), afin de retrouver l'index le
  // plus élevé contenant réellement une donnée (hasPaymentContent), qui fixe le plancher de
  // visibilité. Une ligne vide supplémentaire n'est proposée qu'en complément, jamais en retrait.
  function visiblePaymentCount(rows, total = 0, maxChecks = paymentCheckCount(), showNextIfPartial = true) {
    const max = normalizePaymentCheckCount(maxChecks);
    let highestSignificant = -1;
    let covered = 0;
    for (let index = 0; index < max; index += 1) {
      const payment = rows[index] || {};
      if (hasSignificantPaymentIntent(payment, index)) highestSignificant = index;
      if (paymentCountsTowardSchedule(payment)) covered += asNumber(payment.amount);
    }
    let count = highestSignificant + 1;
    const stillDue = total > 0 && covered < total - 0.005;
    if (stillDue && count < max && showNextIfPartial) count += 1;
    return Math.min(max, Math.max(1, count));
  }

  function hasPaymentContent(payment = {}) {
    return Boolean(asNumber(payment.amount) || asText(payment.date) || asText(payment.state) || asText(payment.checkNumber));
  }

  // Ligne significative pour la VISIBILITÉ — notion distincte de la protection contre l'effacement
  // (cf. isFormPaymentRowPurelyAutomatic dans 17-dialogs-forms.js, qui décide QUOI vider). Une
  // ligne sans aucune donnée métier (hasPaymentContent) reste néanmoins significative si son moyen
  // de paiement PERSISTÉ diffère de celui proposé par défaut pour cet index : cela suffit à prouver
  // une intention utilisateur, même sans montant. La TVA spécifique n'est PAS évaluée ici : une fois
  // qu'une ligne est passée une fois par le formulaire, readPayments écrit systématiquement un
  // payment.taxRate défini (spécifique ou non), ce qui rend hasSpecificTaxRate structurellement
  // inutilisable pour cette distinction au niveau du seul objet — la protection de visibilité de la
  // TVA spécifique est donc portée par le marqueur DOM data-tax-significant (posé dans
  // compactPaymentEditor par comparaison au taux par défaut réel, lu dans
  // updatePaymentSplitDisplay), pas par ce helper pur (qui n'a pas accès au DOM et est aussi
  // utilisé, via formPaymentRows, dans un contexte où la valeur .value du champ caché est de toute
  // façon toujours définie).
  function hasSignificantPaymentIntent(payment = {}, index = 0) {
    if (hasPaymentContent(payment)) return true;
    const check = asText(payment.check);
    return Boolean(check) && normalizePaymentModeKey(check) !== normalizePaymentModeKey(defaultPaymentMethod(index));
  }

  function paymentMiniChip(payment = {}, index = 0, active = false, attrs = "", suggestedAmount = 0, hidden = false) {
    const status = paymentStatus(payment);
    const amount = asNumber(payment.amount) || asNumber(suggestedAmount);
    const filled = hasPaymentContent(payment);
    const method = paymentMethodLabel(payment, index);
    return `<button class="payment-mini-chip ${filled ? "filled" : ""} ${active ? "active" : ""} ${esc(statusClass(status))}" type="button" data-payment-tab="${index}" ${attrs} ${hidden ? "hidden" : ""} title="Paiement ${method}${amount ? ` · ${compactMoney(amount)}` : ""}${status ? ` · ${esc(statusLabel(status))}` : ""}">
      <b>${esc(method)}</b>
      <span>${amount ? esc(compactMoney(amount)) : "-"}</span>
      ${status ? `<i aria-hidden="true"></i>` : ""}
    </button>`;
  }

  function compactPaymentEditor({ index, payment = {}, attrs = "", mode = "form", prefix = "", active = false, visible = true, suggestedAmount = 0, defaultTaxRate = 0, claimKey = "", actionableStatuses = null }) {
    const amountValue = payment?.amount || suggestedAmount || "";
    const amountNumber = asNumber(amountValue);
    // Correctif Boutique — un montant affiché qui vient de suggestedAmount (aucun payment.amount
    // réel) n'est pas une saisie utilisateur : le marquer data-auto-amount="true" dès le rendu HTML
    // initial, sinon distributePaymentSplit() le traite comme une saisie figée et ne le recalcule
    // plus jamais quand le total change (cas "Vendre" : article déjà présent à l'ouverture).
    const isSuggestedAmount = !asNumber(payment?.amount) && asNumber(suggestedAmount) > 0;
    const autoAmountAttr = isSuggestedAmount ? ' data-auto-amount="true"' : "";
    const taxRateValue = payment.taxRate ?? payment.vatRate ?? payment.tva ?? defaultTaxRate ?? 0;
    const status = paymentDisplayStatus(payment, amountNumber, mode);
    const stateValue = paymentStateValue(payment);
    const immediate = isImmediatePayment(payment);
    // Paiement VALIDÉ (status « OK ») -> ligne verrouillée : champs en lecture seule et non
    // interactifs (readonly + tabindex -1 ; pointer-events désactivés via la classe .locked en CSS).
    // Seul « Annuler paiement » reste actif. Empêche de modifier un paiement validé par erreur, ce
    // qui recréait une ligne « à payer » / un reste dû incohérent.
    const paid = status === "OK";
    // Lot I-B — restriction optionnelle (zone de consultation commande) : quand actionableStatuses
    // est fourni, seul le VRAI statut du paiement (paymentStatus, jamais le statut d'AFFICHAGE
    // paymentDisplayStatus utilisé ci-dessus pour les pastilles) décide si cette ligne reste
    // manipulable. Absent partout ailleurs -> restricted=false -> actionable toujours vrai ->
    // comportement historique inchangé au bit près.
    const restricted = Array.isArray(actionableStatuses);
    const actionable = !restricted || actionableStatuses.includes(paymentStatus(payment));
    const lockedForContext = paid || (restricted && !actionable);
    const lockI = lockedForContext ? ' readonly tabindex="-1"' : "";
    const lockS = lockedForContext ? ' tabindex="-1"' : "";
    const dateVal = dateInputValue(payment.date || (parseDate(payment.state) ? payment.state : ""));
    const methodInput = mode === "form"
      ? `<label>Mode<select name="${esc(prefix)}${index}Check" data-payment-method-select${lockS}>${paymentMethodOptions(index, payment.check)}</select></label>`
      : `<label>Mode<select data-payment-field="check" data-index="${index}" ${attrs}${lockS}>${paymentMethodOptions(index, payment.check)}</select></label>`;
    const checkNumberInput = mode === "form"
      ? `<label class="payment-check-number-field">N° chèque<input name="${esc(prefix)}${index}CheckNumber" value="${esc(payment.checkNumber || "")}"${lockI} /></label>`
      : `<label class="payment-check-number-field">N° chèque<input value="${esc(payment.checkNumber || "")}" data-payment-field="checkNumber" data-index="${index}" ${attrs}${lockI} /></label>`;
    const amountInput = mode === "form"
      ? `<label>Somme<input name="${esc(prefix)}${index}Amount" type="number" step="0.01" value="${esc(amountValue)}"${autoAmountAttr}${lockI} /></label>`
      : `<label>Somme<input class="payment-amount" type="number" step="0.01" value="${esc(amountValue)}" data-payment-field="amount" data-index="${index}" ${attrs}${autoAmountAttr}${lockI} /></label>`;
    const dateInput = mode === "form"
      ? `<label class="payment-date-field">${immediate ? "Payé le" : "Encaisser le"}<input name="${esc(prefix)}${index}Date" type="date" value="${esc(dateVal)}"${lockI} /></label>`
      : `<label class="payment-date-field" title="${immediate ? "Date du paiement" : "Date d'encaissement"}">${immediate ? "Payé le" : "Encaisser le"}<input class="payment-date" type="date" value="${esc(dateVal)}" data-payment-field="date" data-index="${index}" ${attrs}${lockI} /></label>`;
    // Marqueur de VISIBILITÉ distinct de data-auto-tax (inchangé, toujours utilisé tel quel par
    // setDefaultPaymentTaxRate) : hasSpecificTaxRate ne teste que la PRÉSENCE d'un taxRate, or
    // readPayments écrit systématiquement une valeur numérique (même 0) dès qu'une ligne passe une
    // fois par ce formulaire — après quoi hasSpecificTaxRate renvoie toujours vrai, y compris pour
    // une ligne jamais réellement personnalisée. data-tax-significant compare au contraire la valeur
    // au taux par défaut RÉELLEMENT applicable à ce contexte (defaultTaxRate, recalculé à chaque
    // rendu) : seul un écart réel rend la ligne significative pour la visibilité, une TVA qui
    // coïncide avec le défaut ne l'est jamais, même après une sauvegarde antérieure.
    const specificTaxRateRaw = payment.taxRate ?? payment.vatRate ?? payment.tva;
    const isTaxSignificant = specificTaxRateRaw !== undefined && specificTaxRateRaw !== null && asText(specificTaxRateRaw) !== ""
      && Math.abs(asNumber(specificTaxRateRaw) - asNumber(defaultTaxRate)) > 0.005;
    const taxInput = mode === "form"
      ? `<input name="${esc(prefix)}${index}TaxRate" class="payment-tax" type="hidden" value="${esc(taxRateValue)}" data-auto-tax="${hasSpecificTaxRate(payment) ? "" : "true"}" data-tax-significant="${isTaxSignificant ? "true" : ""}" />`
      : "";
    // Lot I-B2 — le select "Statut" du tiroir LIVE (data-payment-field="state") n'a d'effet RÉEL que
    // via le listener "change" porté par #app (updatePaymentFromControl, src/20-demo-export.js) :
    // hors de #app — donc dans TOUT dialogue, y compris cette zone restreinte — ce listener ne peut
    // JAMAIS se déclencher (#editorDialog/.stacked-dialog sont des FRÈRES de #app dans index.html,
    // jamais des descendants). Le modifier manuellement ici n'aurait donc aucun effet persistant :
    // un affichage trompeur. Restriction ciblée sur ce SEUL select (montant/moyen/date/n° chèque
    // restent modifiables : validatePayment() lit leur valeur DOM directement au clic, sans dépendre
    // de ce listener) et UNIQUEMENT quand actionableStatuses est fourni (jamais hors de ce contexte —
    // Boutique/Paiements dus, elles, vivent bien dans #app et ce select y fonctionne normalement).
    const liveStateDisabled = restricted ? " disabled" : "";
    const stateInput = mode === "form"
      ? `<label class="payment-state-field">Statut
          <select data-form-payment-state data-prefix="${esc(prefix)}" data-index="${index}" data-claim-key="${esc(claimKey)}"${lockS}>
            ${paymentStateOptions(stateValue === "Refusé" || stateValue === "Annulé" ? stateValue : "", amountNumber)}
          </select>
          <input type="hidden" name="${esc(prefix)}${index}State" value="${esc(stateValue)}" />
        </label>`
      : `<label class="payment-state-field" title="Statut manuel">Statut<select class="payment-state" data-payment-field="state" data-index="${index}" ${attrs}${lockS}${liveStateDisabled}>${paymentStateOptions(payment?.state, amountNumber)}</select></label>`;
    // Données canoniques d'une ligne verrouillée (form) : la sauvegarde restaure ces valeurs même si
    // un champ a été modifié de force (garde côté sauvegarde), tant que la ligne reste verrouillée.
    const lockedData = (paid && mode === "form")
      ? ` data-payment-locked="1" data-locked-check="${esc(payment.check || defaultPaymentMethod(index))}" data-locked-checknumber="${esc(payment.checkNumber || "")}" data-locked-amount="${esc(amountValue)}" data-locked-tax="${esc(taxRateValue)}" data-locked-date="${esc(dateVal)}" data-locked-state="${esc(stateValue || "Payé")}"`
      : "";
    // Paiement REFUSÉ : non payable, aucune action affichée. La seule information est la pastille
    // « Refusé » (colonne État). Pas de bouton « Payer », pas de bandeau explicatif. Le menu Statut
    // reste éditable (lockS ne s'applique qu'au statut « OK ») : remettre le statut à vide réactive
    // la ligne (réactivation contrôlée côté logique métier ; message ponctuel si interdit).
    const refused = status === "Refusé";
    const payButtonLabel = paid ? "Annuler paiement" : "Payer";
    const payButtonTitle = paid
      ? "Annuler la validation du paiement"
      : amountNumber > 0 ? "Valider le paiement" : "Impossible de marquer payé avec une somme à zéro";
    // Lot I-B — dans une zone restreinte, une ligne non actionnable (OK compris) n'affiche AUCUN
    // bouton de mutation : c'est précisément ce qui empêche « Annuler paiement » d'apparaître pour
    // un paiement déjà validé dans la consultation de commande. Hors contexte restreint, comportement
    // historique strictement inchangé (refused reste le seul cas sans bouton).
    const okButton = refused || (restricted && !actionable)
      ? ""
      : mode === "live"
      ? `<button class="payment-ok ${paid ? "cancel-payment" : ""}" type="button" title="${esc(payButtonTitle)}" data-action="validate-payment" data-index="${index}" ${attrs}>${esc(payButtonLabel)}</button>`
      : mode === "form"
        ? `<button class="payment-ok ${paid ? "cancel-payment" : ""}" type="button" title="${esc(payButtonTitle)}" data-action="validate-form-payment" data-prefix="${esc(prefix)}" data-index="${index}" data-claim-key="${esc(claimKey)}">${esc(payButtonLabel)}</button>`
      : "";
    // Lot I-B — nouvelle action, UNIQUEMENT dans le contexte restreint et UNIQUEMENT pour une ligne
    // réellement actionnable (donc jamais OK/Refusé/Annulé/vide) : permet d'abandonner ce paiement
    // pas encore encaissé sans passer par « Annuler paiement » (réservé à un paiement déjà validé).
    // Réutilise exactement les mêmes identifiants que le bouton live (attrs + data-index), aucune
    // deuxième méthode d'identification du paiement.
    const cancelPendingButton = (restricted && actionable)
      ? `<button class="payment-cancel-pending" type="button" title="Annuler ce paiement en attente" data-action="cancel-pending-payment" data-index="${index}" ${attrs}>Annuler ce paiement en attente</button>`
      : "";
    return `<div class="payment-mini-row ${mode === "live" ? "live" : "form"} ${immediate ? "immediate-payment" : ""} ${lockedForContext ? "locked" : ""}" data-payment-row="${index}" data-payment-visible="${visible ? "1" : "0"}"${lockedData} ${!visible || (mode === "live" && !active) ? "hidden" : ""}>
      <span class="payment-label">${esc(paymentMethodLabel(payment, index))}</span>
      ${methodInput}
      ${checkNumberInput}
      ${amountInput}
      ${taxInput}
      ${dateInput}
      ${stateInput}
      <div class="computed-payment-status"><span>État</span>${computedPaymentStatus(status, mode, attrs)}</div>
      ${okButton}
      ${cancelPendingButton}
    </div>`;
  }

  function paymentDisplayStatus(payment = {}, amount = 0, mode = "form") {
    const status = paymentStatus(payment);
    if (status === "OK" || status === "Refusé" || status === "Annulé" || status === "En cours") return status;
    if (amount <= 0) return status;
    if (isImmediatePayment(payment)) return "À payer";
    const date = parseDate(payment.date) || parseDate(payment.state);
    if (date) return paymentStatus({ ...payment, amount });
    return "À payer";
  }

  function computedPaymentStatus(status, mode = "form", attrs = "") {
    if (status === "Refusé" || status === "À payer") {
      const action = mode === "form" ? "view-dialog-contact" : "view-payment-contact";
      return `<button class="status ${statusClass(status)} payment-contact-link" type="button" data-action="${action}" ${attrs}>${esc(statusLabel(status))}</button>`;
    }
    return statusPill(status);
  }

  // ===== Lot UX — Recherche globale fonctionnelle (pages, réglages, actions) =====
  // Registre DÉCLARATIF des destinations et commandes du logiciel. Objectif : permettre à
  // l'utilisateur d'atteindre une page, un réglage ou une action sans connaître son emplacement
  // dans les menus, sans disperser des dizaines de `if (query.includes(...))` dans le handler.
  //
  // Principes structurants :
  // - Une seule source de vérité par intitulé : les titres de PAGES sont repris de `views`
  //   (01-constants.js) plutôt que recopiés ; seuls les mots-clés/synonymes sont déclarés ici.
  // - Construction PARESSEUSE : aucune donnée n'est évaluée au chargement du bundle (les entrées
  //   lisent `settings`/`state` via des fonctions appelées au moment de la recherche seulement).
  //   Un `const` de haut niveau appelant ces helpers casserait au démarrage (TDZ).
  // - Exécution par IDENTIFIANT validé : un résultat ne transporte jamais de code, seulement un id
  //   recherché dans le registre. Une entrée inconnue ou indisponible est ignorée proprement.
  // - Sûreté : aucune action destructrice n'est exécutable depuis la recherche. Les opérations
  //   sensibles (import/restauration, suppression, remise à zéro, envoi réel d'e-mail, archivage)
  //   sont indexées comme DESTINATIONS (elles ouvrent la page/section) et jamais déclenchées.

  const SEARCH_TYPE_ORDER = ["page", "setting", "action", "module", "help", "data"];

  // Libellé + icône de chaque type. Les icônes proviennent de MGC_ICONS (aucun emoji réintroduit).
  const SEARCH_TYPE_META = {
    page: { label: "Page", icon: "search" },
    setting: { label: "Réglage", icon: "settings" },
    action: { label: "Action", icon: "menu-bolt" },
    module: { label: "Module", icon: "menu-grid" },
    help: { label: "Aide", icon: "help" },
    data: { label: "Donnée", icon: "contacts" },
  };

  function searchTypeMeta(type) {
    return SEARCH_TYPE_META[type] || SEARCH_TYPE_META.data;
  }

  // --- Normalisation ---------------------------------------------------------------------
  // Tolérante : casse, accents, apostrophes (droites et typographiques), tirets, pluriels simples.
  // « Disponibilités » / « disponibilites » / « DISPONIBILITE » donnent le même jeton.
  function normalizeSearchText(value) {
    return asText(value)
      .toLowerCase()
      .normalize("NFD")
      .replace(/\p{Diacritic}/gu, "")
      .replace(/[’'`]/g, " ")
      .replace(/[-_/\\.,;:!?()[\]{}"]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  // Pluriel simple : « salles » -> « salle ». On ne touche pas aux mots courts (« pin », « pdf »)
  // ni aux terminaisons en -ss, pour ne pas casser des mots légitimes.
  function singularizeSearchToken(token) {
    if (token.length > 3 && token.endsWith("s") && !token.endsWith("ss")) return token.slice(0, -1);
    return token;
  }

  function searchTokens(query) {
    const normalized = normalizeSearchText(query);
    if (!normalized) return [];
    return normalized.split(" ").filter(Boolean).map(singularizeSearchToken);
  }

  // Texte indexable d'une entrée, normalisé et singularisé (mémoïsé, cf. commandRegistryIndex).
  function searchableTokens(values = []) {
    const out = new Set();
    values.filter(Boolean).forEach((value) => {
      searchTokens(value).forEach((token) => out.add(token));
    });
    return out;
  }

  // --- Helpers de déclaration ---------------------------------------------------------------
  // Titre officiel d'une vue : lu dans `views` (source de vérité) plutôt que recopié.
  function viewLabel(view) {
    const found = views.find(([key]) => key === view);
    return found ? found[1] : view;
  }

  // Icône d'une vue : réutilise la bibliothèque interne, avec repli sur l'icône du type.
  function viewIconKey(view) {
    return MGC_ICONS && MGC_ICONS[view] ? view : null;
  }

  // --- Registre --------------------------------------------------------------------------
  // Chaque entrée : { id, type, title, description, keywords[], view?, panel?, action?,
  //                   feature?, module?, priority?, available?() }
  // `available()` renvoie true/false ; l'indisponibilité est expliquée par `unavailableReason`.
  function commandRegistryDefinitions() {
    const pages = [
      // [clé de vue, description, mots-clés/synonymes supplémentaires]
      ["dashboard", "Vue d'ensemble du club : alertes, tâches et chiffres clés.", ["accueil", "tableau de bord", "home", "resume", "synthese"]],
      ["tasks", "Les points à traiter : relances, documents manquants, échéances.", ["a faire", "todo", "taches", "rappels", "post it", "postit"]],
      ["search", "Rechercher partout : personnes, pages, réglages et actions.", ["rechercher", "trouver", "chercher"]],
      ["contacts", "Adhérents et non-adhérents du club : fiches, coordonnées, photos.", ["adherent", "adherents", "membre", "membres", "personne", "personnes", "prospect", "fiche", "annuaire"]],
      ["invoices", "Factures émises, brouillons et avoirs.", ["facture", "facturation", "devis", "avoir", "note de credit"]],
      ["newsletter", "Envoyer un e-mail aux contacts à partir d'un modèle.", ["email", "e mail", "mail", "courriel", "message", "messagerie", "newsletter", "infolettre"]],
      // Lot 3B-3 — l'inscription d'un adhérent se crée depuis sa fiche, pas depuis une action
      // globale : la recherche conduit donc à la page qui rassemble les inscriptions, au lieu
      // d'inventer une action exécutable sans contact.
      ["disciplines", "Disciplines enseignées et inscriptions associées.", ["discipline", "cours", "activite", "activites", "sport", "inscription", "inscriptions", "ajouter une inscription", "nouvelle inscription", "inscrire un adherent"]],
      // Lot 3B-3 — le mot-clé « categorie » est RETIRÉ de cette entrée : il conduisait aux Groupes,
      // c'est-à-dire à la mauvaise notion, et c'était le seul résultat rendu pour cette recherche.
      // Il appartient désormais à la bande « Disciplines et catégories sportives » (ci-dessous).
      ["groups", "Groupes de pratiquants et leurs membres.", ["groupe", "groupes", "equipe", "equipes", "niveau", "niveaux", "membre", "membres"]],
      ["coaches", "Coachs du club : fiches, spécialités, disponibilités, photos.", ["coach", "entraineur", "entraineurs", "professeur", "prof", "encadrant", "moniteur", "instructeur"]],
      ["rooms", "Salles et lieux de pratique.", ["salle", "gymnase", "dojo", "lieu", "lieux", "site", "installation"]],
      ["planning", "Planning des séances et des cours.", ["planning", "agenda", "calendrier", "horaire", "horaires", "seance", "seances", "emploi du temps"]],
      ["availability", "Disponibilités des coachs et des salles.", ["disponibilite", "dispo", "creneau", "creneaux", "indisponibilite"]],
      ["attendance", "Feuilles de présence des séances.", ["presence", "appel", "emargement", "pointage", "absence"]],
      ["documents", "Documents sportifs : certificats, licences, autorisations.", ["document", "certificat", "licence", "attestation", "autorisation", "dossier"]],
      ["stages", "Stages et sessions : inscriptions, hébergement, paiements.", ["stage", "camp", "session", "seminaire", "sortie"]],
      ["boutique", "Boutique du club : articles, commandes, ventes.", ["boutique", "magasin", "vente", "ventes", "commande", "commandes", "article", "articles", "shop"]],
      ["stock", "Stock des articles de la boutique.", ["stock", "inventaire", "quantite", "reassort", "approvisionnement"]],
      ["clubs", "Gérer les clubs : créer, dupliquer, activer, archiver.", ["club", "mes clubs", "multi club", "association", "changer de club"]],
      ["settings", "Réglages du logiciel : thèmes, affichage, e-mails, données, sécurité.", ["parametre", "parametres", "reglage", "reglages", "configuration", "config", "preference", "preferences", "option", "options"]],
      ["club-settings", "Identité du club : nom, adresse, responsables, mentions légales.", ["identite", "identite du club", "coordonnees", "siret", "responsable", "responsables", "bureau", "mentions legales"]],
      ["tarifs", "Tarifs des disciplines, articles, stages et assurances.", ["tarif", "tarifs", "prix", "cotisation", "montant", "grille tarifaire"]],
      ["stats", "Statistiques du club : effectifs et évolutions.", ["statistique", "statistiques", "stat", "chiffre", "chiffres", "graphique", "analyse"]],
      ["accounting", "Comptabilité : recettes, dépenses et soldes.", ["comptabilite", "compta", "recette", "depense", "depenses", "bilan", "tresorerie", "budget"]],
      ["due-payments", "Paiements dus : impayés, retards et relances.", ["paiement", "paiements", "paiement du", "impaye", "impayes", "retard", "creance", "reste a payer", "relance", "encaissement"]],
      ["notes", "Notes libres du club.", ["note", "notes", "memo", "pense bete"]],
      ["history", "Historique des actions récentes.", ["historique", "recent", "recents"]],
      ["audit-log", "Journal d'activité : trace des modifications importantes.", ["journal", "journal d activite", "activite", "audit", "trace", "log", "suivi"]],
      ["help", "Aide et documentation du logiciel.", ["aide", "documentation", "manuel", "guide", "assistance", "support", "faq"]],
      ["assistant", "Centre d'accompagnement : visites guidées et conseils.", ["accompagnement", "assistant", "visite guidee", "tutoriel", "demarrage", "prise en main"]],
    ];

    const entries = pages.map(([view, description, keywords]) => ({
      id: `page-${view}`,
      type: "page",
      title: viewLabel(view),          // source de vérité : `views`
      description,
      keywords,
      view,
      icon: viewIconKey(view),
      priority: 0,
    }));

    // --- Réglages : chaque entrée ouvre Paramètres ET déplie la bonne bande ------------------
    // Les identifiants de bande sont ceux passés à settingsCollapsibleBand() (16-settings-themes).
    const settingsBands = [
      ["themes", "Thèmes", "Changer l'apparence du logiciel.", ["theme", "apparence", "couleur", "couleurs", "graphite", "ubuntu", "classic", "sombre", "clair", "style"]],
      ["typography", "Polices", "Choisir les polices des titres, du texte et des boutons.", ["police", "polices", "typographie", "font", "taille du texte", "caractere"]],
      ["postits", "Post-it À faire", "Couleurs et modèles des post-it.", ["post it", "postit", "pense bete", "couleur des post it"]],
      ["features", "Fonctionnalités du club", "Activer ou désactiver des fonctions pour ce club.", ["fonctionnalite", "fonctionnalites", "fonction", "module", "modules", "activer", "desactiver", "option du club"]],
      ["display", "Affichage", "Mode Simple, Avancé ou Personnalisé et modules visibles.", ["affichage", "mode", "mode simple", "mode avance", "mode personnalise", "simple", "avance", "personnalise", "layout", "interface", "menu visible"]],
      ["menu-order", "Ordre du menu", "Personnaliser l'ordre et les icônes de la navigation.", ["menu", "ordre du menu", "navigation", "personnaliser le menu", "icone", "icones", "raccourci"]],
      ["checks", "Paiement en plusieurs fois", "Nombre d'échéances et de chèques autorisés.", ["cheque", "cheques", "echeance", "echeances", "plusieurs fois", "fractionne", "paiement en plusieurs fois"]],
      ["security", "Sécurité", "Mot de passe du logiciel et protection des actions sensibles.", ["securite", "mot de passe", "password", "protection", "verrouillage", "confidentialite"]],
      ["logo", "Logo", "Logo du club et icônes de l'application.", ["logo", "image", "embleme", "blason", "icone de l application"]],
      ["emails", "Messages e-mail", "Modèles de messages et relances.", ["modele", "modeles", "modele e mail", "message", "relance", "relances", "email", "e mail", "mail"]],
      ["smtp", "Envoi d'e-mails (SMTP)", "Configurer le serveur d'envoi des e-mails du club.", ["smtp", "serveur mail", "serveur d envoi", "envoi e mail", "email", "e mail", "mail", "messagerie", "port", "expediteur"]],
      ["users", "Utilisateurs", "Profils locaux, code PIN et profil actif.", ["utilisateur", "utilisateurs", "utilisateur local", "profil", "profils", "pin", "code pin", "compte", "session"]],
      ["data", "Données", "Sauvegarde, restauration, import/export et vidage.", ["donnee", "donnees", "sauvegarde", "backup", "restauration", "restaurer", "import", "importer", "export", "exporter", "archive", "archivage", "vider", "reinitialiser"]],
      ["license", "Licence", "Activation et état de la licence.", ["licence", "license", "activation", "cle", "abonnement", "essai"]],
      // Lot 3B-3 — la bande « sport-categories » était un panneau VALIDE (SETTINGS_PANEL_IDS) mais
      // jamais indexé : le catalogue des catégories sportives, les profils sportifs et tout ce que
      // les Lots 3B-2B/2C/2D y ont ajouté étaient introuvables depuis la recherche globale. Les
      // mots-clés sont déclarés sans accent : normalizeSearchText les retire des deux côtés, donc
      // « catégorie » et « categorie » atteignent la même entrée.
      ["sport-categories", "Disciplines et catégories sportives", "Profil sportif et catalogue de catégories de chaque discipline.",
        ["categorie", "categories", "categorie sportive", "categories sportives", "catalogue", "profil", "profil sportif",
          "discipline", "disciplines", "u11", "u13", "u15", "poussins", "benjamins", "cadets", "seniors"]],
    ];

    settingsBands.forEach(([panel, title, description, keywords]) => {
      entries.push({
        id: `setting-${panel}`,
        type: "setting",
        title,
        description,
        keywords,
        view: "settings",
        panel,
        icon: "settings",
        priority: 0,
      });
    });

    // --- Actions exécutables ------------------------------------------------------------------
    // UNIQUEMENT des actions sûres : elles ouvrent un dialogue de création ou produisent un
    // fichier. Aucune suppression, remise à zéro, restauration, désactivation, envoi réel
    // d'e-mail, paiement ni archivage massif n'est déclenchable depuis la recherche.
    // Volontairement ABSENTES du registre exécutable, et couvertes par des destinations :
    //   · import-json  -> écrase les données dès le choix du fichier, sans confirmation
    //                     => indexé comme destination « Importer une sauvegarde » (Paramètres > Données)
    //   · add-note     -> crée et persiste une note immédiatement (niveau d'historique)
    //                     => la page « Notes » suffit
    const actions = [
      ["action-add-contact", "Ajouter un contact", "Créer une fiche adhérent ou non-adhérent.",
        ["ajouter un contact", "nouveau contact", "creer un contact", "ajouter une personne", "nouvel adherent", "ajouter un adherent", "ajouter un membre", "inscrire"],
        "add-contact", "contacts", null],
      ["action-add-coach", "Ajouter un coach", "Créer une fiche coach.",
        ["ajouter un coach", "nouveau coach", "creer un coach", "ajouter un entraineur", "nouvel entraineur", "ajouter un professeur", "ajouter un encadrant"],
        "add-coach", "coaches", null],
      ["action-add-room", "Ajouter une salle", "Créer une salle ou un lieu de pratique.",
        ["ajouter une salle", "nouvelle salle", "creer une salle", "ajouter un gymnase", "ajouter un lieu", "ajouter un dojo"],
        "add-room", "rooms", null],
      ["action-add-group", "Ajouter un groupe", "Créer un groupe de pratiquants.",
        ["ajouter un groupe", "nouveau groupe", "creer un groupe", "ajouter une equipe"],
        "add-group", "groups", null],
      // Lot 3B-4A — la création d'une discipline manquait à cet inventaire alors que toutes les
      // autres entités du club y figurent. Contrairement à « Ajouter une inscription » (écartée au
      // Lot 3B-3), elle n'exige AUCUN contexte : ni contact, ni groupe — seulement le club actif.
      // L'entrée de réglage « Disciplines et catégories sportives » reste distincte : elle conduit
      // au catalogue existant, celle-ci ouvre le dialogue de création.
      ["action-add-discipline", "Nouvelle discipline", "Créer une discipline et, si besoin, ses premières catégories sportives.",
        ["ajouter une discipline", "ajouter une autre discipline", "nouvelle discipline", "creer une discipline",
          "multisport", "sport", "activite sportive", "nouvelle activite"],
        "open-discipline-creation", "settings", null],
      ["action-add-stage", "Ajouter un stage", "Créer un stage ou une session.",
        ["ajouter un stage", "nouveau stage", "creer un stage", "ajouter un camp", "nouvelle session"],
        "add-stage", "stages", "stages"],
      ["action-new-invoice", "Créer une facture", "Établir une nouvelle facture pour un contact.",
        ["creer une facture", "nouvelle facture", "ajouter une facture", "facturer", "editer une facture"],
        "new-invoice", "invoices", null],
      ["action-add-stock-article", "Ajouter un article boutique", "Créer un article et son stock.",
        ["ajouter un article", "nouvel article", "creer un article", "ajouter du stock", "nouveau produit", "ajouter au stock"],
        "add-stock-article", "stock", "shop"],
      ["action-add-order", "Ajouter une commande boutique", "Enregistrer une commande pour un contact.",
        ["ajouter une commande", "nouvelle commande", "creer une commande", "vendre", "vente"],
        "add-order", "boutique", "shop"],
      ["action-add-course", "Ajouter un cours au planning", "Créer une séance récurrente dans le planning.",
        ["ajouter un cours", "nouveau cours", "creer un cours", "ajouter une seance", "ajouter au planning"],
        "add-course", "planning", null],
      ["action-new-user", "Créer un utilisateur local", "Ajouter un profil local protégé par un code PIN.",
        ["creer un utilisateur", "nouvel utilisateur", "ajouter un utilisateur", "utilisateur local", "nouveau profil", "ajouter un profil"],
        "new-user", "settings", null],
      // Seul export indexable : il ne dépend d'AUCUN contexte de page (sauvegarde complète).
      ["action-export-json", "Exporter les données (sauvegarde)", "Télécharger une sauvegarde JSON complète.",
        ["exporter les donnees", "sauvegarde", "sauvegarder", "backup", "telecharger une sauvegarde", "export json", "copie de securite"],
        "export-json", null, null],
      // VOLONTAIREMENT ABSENTS du registre : `export-csv` et `export-pdf`. Ces deux actions
      // portent sur la PAGE COURANTE (exportCurrentCsv/exportCurrentPdf) : lancées depuis la
      // page Recherche, elles exporteraient celle-ci, ce qu'un intitulé de résultat ne peut pas
      // rendre sans ambiguïté. Elles restent accessibles depuis les boutons de chaque page,
      // dont le contexte est explicite. Ne pas les réintroduire ici.
    ];

    actions.forEach(([id, title, description, keywords, action, module, feature]) => {
      entries.push({ id, type: "action", title, description, keywords, action, module, feature, icon: "menu-bolt", priority: 1 });
    });

    // --- Destinations pour opérations sensibles (jamais exécutées depuis la recherche) --------
    entries.push({
      id: "setting-data-import",
      type: "setting",
      title: "Importer une sauvegarde",
      description: "Ouvre Paramètres > Données. L'import remplace les données : il se confirme depuis cette page.",
      keywords: ["import", "importer", "importer une sauvegarde", "restaurer", "restauration", "charger une sauvegarde", "recuperer"],
      view: "settings",
      panel: "data",
      icon: "settings",
      priority: 0,
    });
    entries.push({
      id: "setting-data-reset",
      type: "setting",
      title: "Vider ou réinitialiser les données",
      description: "Ouvre Paramètres > Données. Opération sensible : elle se confirme depuis cette page.",
      keywords: ["vider", "reinitialiser", "remise a zero", "effacer les donnees", "supprimer les donnees", "repartir de zero"],
      view: "settings",
      panel: "data",
      icon: "settings",
      priority: 0,
    });

    // --- Aide contextuelle ---------------------------------------------------------------------
    // Le recadrage photo n'existe QUE dans une fiche ouverte : on n'invente pas d'action globale,
    // on conduit l'utilisateur là où la fonction se trouve réellement.
    entries.push({
      id: "help-photo-crop",
      type: "help",
      title: "Recadrer une photo",
      description: "Le recadrage s'ouvre depuis la photo d'une fiche contact ou coach.",
      keywords: ["recadrer", "recadrage", "photo", "cadrer", "rogner", "zoomer une photo", "modifier une photo", "portrait", "avatar", "identite photo"],
      view: "contacts",
      icon: "contacts",
      priority: 0,
    });

    return entries;
  }

  // --- Index mémoïsé ---------------------------------------------------------------------------
  // Le registre est statique : on ne le reconstruit qu'une fois par session, et on pré-calcule les
  // jetons normalisés. La DISPONIBILITÉ, elle, est réévaluée à chaque recherche (club actif, mode
  // d'affichage et fonctionnalités peuvent changer) — c'est peu coûteux, contrairement à l'indexation.
  let commandRegistryCache = null;

  function commandRegistryIndex() {
    if (commandRegistryCache) return commandRegistryCache;
    const seen = new Set();
    const list = [];
    commandRegistryDefinitions().forEach((entry) => {
      // Une entrée invalide est ignorée proprement plutôt que de casser la recherche.
      if (!entry || typeof entry !== "object") return;
      if (!entry.id || typeof entry.id !== "string" || seen.has(entry.id)) return;
      if (!entry.type || !SEARCH_TYPE_META[entry.type]) return;
      if (!asText(entry.title)) return;
      if (!entry.view && !entry.action) return;          // une entrée doit mener quelque part
      if (entry.action && typeof entry.action !== "string") return;
      if (entry.view && !views.some(([key]) => key === entry.view)) return; // pas de destination fictive
      // Une section de réglages doit exister réellement : on la valide contre la source de vérité
      // unique SETTINGS_PANEL_IDS (01-constants.js), la même que celle vérifiée à l'affichage par
      // settingsCollapsibleBand. Sinon l'entrée conduirait à Paramètres sans rien déplier.
      if (entry.panel !== undefined && entry.panel !== null) {
        if (typeof entry.panel !== "string" || !isSettingsPanelId(entry.panel)) {
          console.warn(`registre de recherche : entrée « ${entry.id} » ignorée — section de réglages inconnue « ${entry.panel} ».`);
          return;
        }
        // Un panneau n'a de sens que sur la page Paramètres, qui l'affiche.
        if (entry.view !== "settings") {
          console.warn(`registre de recherche : entrée « ${entry.id} » ignorée — un panneau ne peut être ouvert que depuis la vue « settings ».`);
          return;
        }
      }
      seen.add(entry.id);
      const keywords = Array.isArray(entry.keywords) ? entry.keywords.filter((k) => typeof k === "string") : [];
      list.push({
        ...entry,
        keywords,
        titleNorm: normalizeSearchText(entry.title),
        titleTokens: searchableTokens([entry.title]),
        keywordTokens: searchableTokens(keywords),
        keywordNorms: keywords.map((k) => normalizeSearchText(k)),
        descriptionTokens: searchableTokens([entry.description]),
      });
    });
    commandRegistryCache = list;
    return list;
  }

  // --- Disponibilité ----------------------------------------------------------------------------
  // Trois axes distincts, déjà portés par l'application : la FONCTIONNALITÉ du club (hasFeature),
  // l'AFFICHAGE du module (isViewVisible : mode Simple/Avancé/Personnalisé) et le club actif.
  // Règle retenue : une entrée dont le module est simplement MASQUÉ reste proposée, signalée comme
  // indisponible avec le chemin pour l'activer — sinon l'utilisateur ne peut pas découvrir comment
  // réactiver ce qu'il cherche. Une entrée dont la FONCTIONNALITÉ est coupée est traitée pareil.
  function commandEntryAvailability(entry) {
    if (typeof entry.available === "function") {
      let ok = false;
      try { ok = Boolean(entry.available()); } catch (_) { ok = false; }
      if (!ok) return { available: false, reason: "Indisponible dans ce contexte." };
    }
    if (entry.feature && typeof hasFeature === "function" && !hasFeature(entry.feature)) {
      return {
        available: false,
        reason: "Fonctionnalité désactivée pour ce club.",
        fixView: "settings",
        fixPanel: "features",
      };
    }
    const targetModule = entry.module || entry.view;
    if (targetModule && typeof isViewVisible === "function" && !isViewVisible(targetModule)) {
      return {
        available: false,
        reason: "Module masqué dans ce club.",
        fixView: "settings",
        fixPanel: "display",
      };
    }
    return { available: true };
  }

  // --- Pondération -------------------------------------------------------------------------------
  // Barème explicite et stable (du plus fort au plus faible) :
  //   1. titre identique à la requête          100
  //   2. titre commençant par la requête        80
  //   3. titre contenant la requête             60
  //   4. mot-clé identique                      50
  //   5. mot-clé/synonyme commençant par        40
  //   6. description                            15
  // Tous les jetons de la requête doivent être couverts (ET logique) : « ajouter coach » ne
  // remonte pas une entrée qui ne parle que de « coach ».
  function scoreCommandEntry(entry, tokens, normalizedQuery) {
    if (!tokens.length) return 0;
    let score = 0;

    if (entry.titleNorm === normalizedQuery) score += 100;
    else if (entry.titleNorm.startsWith(normalizedQuery)) score += 80;
    else if (entry.titleNorm.includes(normalizedQuery)) score += 60;

    if (entry.keywordNorms.some((k) => k === normalizedQuery)) score += 50;
    else if (entry.keywordNorms.some((k) => k.startsWith(normalizedQuery))) score += 40;
    else if (entry.keywordNorms.some((k) => k.includes(normalizedQuery))) score += 25;

    // Couverture jeton par jeton : indispensable pour les requêtes en plusieurs mots.
    let couverts = 0;
    tokens.forEach((token) => {
      if (entry.titleTokens.has(token)) { score += 12; couverts++; return; }
      if (entry.keywordTokens.has(token)) { score += 9; couverts++; return; }
      // Préfixe : « dispo » doit atteindre « disponibilite ».
      if ([...entry.titleTokens].some((t) => t.startsWith(token))) { score += 7; couverts++; return; }
      if ([...entry.keywordTokens].some((t) => t.startsWith(token))) { score += 5; couverts++; return; }
      if (entry.descriptionTokens.has(token)) { score += 3; couverts++; }
    });
    if (couverts < tokens.length) return 0;   // tous les jetons doivent être couverts

    score += entry.priority || 0;
    return score;
  }

  // --- Recherche fonctionnelle ---------------------------------------------------------------------
  function functionalSearchResults(query = ui.globalSearch, limit = 12) {
    const normalizedQuery = normalizeSearchText(query);
    const tokens = searchTokens(query);
    if (!tokens.length) return [];
    const scored = [];
    commandRegistryIndex().forEach((entry) => {
      const score = scoreCommandEntry(entry, tokens, normalizedQuery);
      if (score <= 0) return;
      const availability = commandEntryAvailability(entry);
      scored.push({ entry, score, availability });
    });
    // Tri stable et lisible : score, puis type (ordre fixe), puis titre.
    scored.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      const ta = SEARCH_TYPE_ORDER.indexOf(a.entry.type);
      const tb = SEARCH_TYPE_ORDER.indexOf(b.entry.type);
      if (ta !== tb) return ta - tb;
      return a.entry.title.localeCompare(b.entry.title, "fr");
    });
    // Les entrées disponibles passent devant les indisponibles, à score comparable.
    const dispo = scored.filter((row) => row.availability.available);
    const indispo = scored.filter((row) => !row.availability.available);
    return [...dispo, ...indispo].slice(0, limit);
  }

  // --- Exécution ------------------------------------------------------------------------------------
  // Un résultat ne transporte qu'un identifiant : on le recherche dans le registre (liste blanche)
  // avant toute exécution. Aucune action arbitraire ne peut être déclenchée depuis le DOM.
  async function runCommandEntryById(entryId, options = {}) {
    const entry = commandRegistryIndex().find((row) => row.id === entryId);
    if (!entry) return false;                       // identifiant inconnu : ignoré proprement
    const availability = commandEntryAvailability(entry);
    if (!availability.available) {
      // On n'exécute jamais une entrée indisponible : on conduit vers le réglage qui la débloque.
      if (options.fix && availability.fixView) {
        // Le message doit être posé AVANT la navigation : openSettingsAt() rend la page une seule
        // fois (et y consomme le jeton de surlignage). Rendre une seconde fois après coup
        // reconstruirait le DOM et effacerait aussitôt le surlignage de la bande atteinte.
        ui.saveMessage = `${entry.title} — ${availability.reason}`;
        openSettingsAt(availability.fixView, availability.fixPanel);
        return true;
      }
      ui.saveMessage = `${entry.title} — ${availability.reason}`;
      render();
      return false;
    }
    // Destination : on réutilise la navigation existante (jamais de clic simulé).
    if (entry.view && !entry.action) {
      openSettingsAt(entry.view, entry.panel);
      return true;
    }
    if (entry.action) {
      // Une action rattachée à une vue s'exécute depuis cette vue (contexte cohérent, ex. le
      // dialogue de création s'ouvre sur la page concernée).
      if (entry.module && views.some(([key]) => key === entry.module) && ui.view !== entry.module) {
        navigateToViewFromMenu(entry.module);
      }
      await handleAction({ dataset: { action: entry.action } });
      return true;
    }
    return false;
  }

  // Navigation vers une vue, en dépliant au passage la bande de réglages visée.
  // N'enregistre AUCUN niveau d'historique métier (navigateTo n'appelle pas recordHistory).
  function openSettingsAt(view, panel) {
    // Seconde barrière : l'index exclut déjà les panneaux inconnus, mais openSettingsAt reçoit
    // aussi les `fixPanel` de commandEntryAvailability — on ne crée jamais une clé fantôme.
    if (panel && isSettingsPanelId(panel)) {
      ui.settingsPanels = { ...(ui.settingsPanels || {}), [panel]: true };
      // Jeton logique consommé juste après le rendu (cf. highlightSettingsSearchTarget) : il
      // indique la bande à amener à l'écran et à surligner brièvement. Il ne survit jamais à
      // l'appel courant — la consommation le purge inconditionnellement.
      ui.searchHighlightPanel = panel;
    }
    // navigateTo() court-circuite le rendu quand le point de navigation est identique (on est
    // déjà sur cette page, sans filtre). On force alors un rendu pour que la bande soit dépliée
    // et que le jeton soit consommé sur un DOM à jour.
    const rerenderNeeded = ui.view === view;
    navigateToViewFromMenu(view);
    if (rerenderNeeded) render();
    // Le rendu est synchrone (app.innerHTML) : à ce point le DOM cible existe. On consomme donc
    // le jeton « après le rendu effectif » sans setTimeout fragile en amont.
    highlightSettingsSearchTarget();
  }

  // Durée d'affichage du surlignage de la bande atteinte depuis la recherche. Doit rester alignée
  // sur l'animation CSS `settings-search-target` (styles.css) : bref, perceptible, non agressif.
  const SETTINGS_HIGHLIGHT_MS = 1500;

  // Consommateur du jeton `ui.searchHighlightPanel`. Appelé juste après le rendu de la page visée.
  // Contrats :
  //  - purge INCONDITIONNELLE du jeton logique (jamais rejoué sur un rerender, un changement de
  //    thème, de club ou de largeur, ni sur une modification sans rapport) ;
  //  - aucun effet hors page Paramètres ;
  //  - un panneau valide mais absent du DOM ne déclenche ni scroll ni erreur ;
  //  - reprise du focus a11y : la page Recherche étant détruite, le focus retomberait sinon sur
  //    BODY ; on le place sur le titre interactif de la bande atteinte (jamais laissé sur BODY) ;
  //  - respecte prefers-reduced-motion (géré côté CSS + repli de comportement de défilement).
  function highlightSettingsSearchTarget() {
    const panel = ui.searchHighlightPanel;
    ui.searchHighlightPanel = "";                 // purge immédiate et inconditionnelle
    if (!panel || ui.view !== "settings") return;
    const target = app.querySelector(`.settings-collapsible-band[data-settings-panel="${CSS.escape(panel)}"]`);
    if (!target) return;                          // panneau valide mais pas dans le DOM : rien
    const reduceMotion = typeof matchMedia === "function"
      && matchMedia("(prefers-reduced-motion: reduce)").matches;
    try {
      // block:"center" évite tout recouvrement par une barre haute et fonctionne quel que soit
      // le conteneur qui défile réellement (ici la fenêtre : .sidebar est sticky, .content sans
      // overflow propre). scrollIntoView remonte automatiquement jusqu'au bon ancêtre scrollable.
      target.scrollIntoView({ block: "center", inline: "nearest", behavior: reduceMotion ? "auto" : "smooth" });
    } catch (_) {
      target.scrollIntoView();                    // repli si l'objet d'options n'est pas supporté
    }
    // Surlignage : une classe dédiée, retirée après l'animation. Un rerender reconstruit le DOM
    // sans cette classe, donc elle ne peut pas persister ; le timeout sur le nœud (éventuellement
    // détaché) reste sans effet de bord.
    target.classList.add("search-target-highlight");
    // Reprise du focus (a11y). Le titre de la bande est la destination logique : role="button",
    // tabindex="0", aria-expanded et intitulé du réglage. preventScroll empêche un second
    // défilement qui annulerait le centrage demandé ci-dessus. .focus() ne déclenche pas l'action
    // « toggle-settings-panel » (seule une activation le ferait) : la bande reste ouverte.
    const focusTarget = target.querySelector(".collapsible-title-row[role='button'][tabindex='0']");
    if (focusTarget) {
      try { focusTarget.focus({ preventScroll: true }); }
      catch (_) { focusTarget.focus(); }
    }
    // Confirmation réelle de la prise de focus : on ne laisse JAMAIS le focus sur BODY. Repli
    // exceptionnel (titre introuvable ou focus refusé) sur la bande elle-même, via un tabindex
    // temporaire retiré au blur ou au prochain rendu — le titre interactif reste le chemin normal.
    if (focusTarget !== document.activeElement) {
      if (typeof console !== "undefined" && console.warn) {
        console.warn(`highlightSettingsSearchTarget : focus non pris sur le titre de « ${panel} » — repli sur la bande.`);
      }
      target.setAttribute("tabindex", "-1");
      try { target.focus({ preventScroll: true }); } catch (_) { target.focus(); }
      target.addEventListener("blur", () => target.removeAttribute("tabindex"), { once: true });
    }
    window.setTimeout(() => target.classList.remove("search-target-highlight"), SETTINGS_HIGHLIGHT_MS);
  }
  function includesQuery(record, query) {
    if (!query) return true;
    return JSON.stringify(record).toLowerCase().includes(query.toLowerCase());
  }

  function articleById(articleId) {
    return state.tariffs.articles.find((article) => article.id === articleId) || {};
  }

  function articleImages(article = {}) {
    const values = [
      article.image,
      ...(Array.isArray(article.images) ? article.images : []),
    ].filter((value) => typeof value === "string" && value.trim());
    return [...new Set(values)];
  }

  function articleImageCaptions(article = {}, count = articleImages(article).length) {
    const captions = Array.isArray(article.imageCaptions) ? article.imageCaptions : [];
    return Array.from({ length: count }, (_, index) => asText(captions[index]));
  }

  function setArticleImages(article = {}, images = [], captions = []) {
    const normalized = [];
    const normalizedCaptions = [];
    images.forEach((value, index) => {
      if (typeof value !== "string" || !value.trim() || normalized.includes(value)) return;
      normalized.push(value);
      normalizedCaptions.push(asText(captions[index]));
    });
    article.images = normalized;
    article.image = normalized[0] || "";
    article.imageCaptions = normalizedCaptions;
  }

  function currentArticleImageCaptions(article = {}, form = null, count = articleImages(article).length) {
    const captions = articleImageCaptions(article, count);
    if (!form) return captions;
    const data = new FormData(form);
    return captions.map((caption, index) => {
      const value = data.get(`articleImageCaption_${index}`);
      return value === null ? caption : asText(value);
    });
  }

  function moveArrayItem(items, fromIndex, toIndex) {
    if (!Array.isArray(items) || fromIndex === toIndex) return items;
    const next = [...items];
    const [item] = next.splice(fromIndex, 1);
    next.splice(toIndex, 0, item);
    return next;
  }

  function articleImage(article = {}, size = "small") {
    const className = `article-image article-image-${size}`;
    const images = articleImages(article);
    const image = images[0];
    if (image) {
      return `<button class="article-image-button" type="button" data-action="view-article-image" data-article-id="${esc(article.id || "")}" data-image-index="0" title="Afficher les images en grand">
        <img class="${className}" src="${esc(image)}" alt="${esc(article.name || "Article")}" />
        ${images.length > 1 ? `<span class="article-image-count">+${images.length - 1}</span>` : ""}
      </button>`;
    }
    return `<span class="${className} article-image-empty">IMG</span>`;
  }

  function disciplineByName(name) {
    return state.tariffs.disciplines.find((discipline) => discipline.name === name) || {};
  }

  function insuranceChoices() {
    return state.tariffs.insurance.flatMap((insurance, insuranceIndex) => {
      const options = (insurance.options || []).length ? insurance.options : [0];
      return options.map((price, optionIndex) => ({
        key: `${insuranceIndex}:${optionIndex}`,
        category: insurance.category || "",
        label: insurance.label || "",
        price: asNumber(price),
      }));
    });
  }

  function insuranceChoiceByKey(key) {
    return insuranceChoices().find((choice) => choice.key === key) || null;
  }

  function membershipInsuranceChoice(row = {}) {
    if (row.insuranceChoice && insuranceChoiceByKey(row.insuranceChoice)) return row.insuranceChoice;
    const choices = insuranceChoices().filter((choice) => choice.category === row.insuranceCategory);
    if (!choices.length) return "";
    const matching = choices.find((choice) => asNumber(choice.price) === asNumber(row.insurancePrice));
    return (matching || choices[0]).key;
  }

  function membershipInsurancePrice(row = {}) {
    const choice = insuranceChoiceByKey(row.insuranceChoice || membershipInsuranceChoice(row));
    return asNumber(choice?.price);
  }

  function stageById(stageId) {
    return state.tariffs.stages.find((stage) => stage.id === stageId) || state.tariffs.stages[0] || {};
  }

  function createStageDefaults() {
    return {
      id: id("stage"),
      name: "Nouveau stage",
      startDate: "",
      endDate: "",
      registrationDeadline: "",
      registrationReopened: false,
      publicAccess: "members",
      lodgingName: "",
      unitPrice: 0,
      lodgingUnitPrice: 0,
      investment: 0,
    };
  }

  function normalizeStagePublicAccess(value) {
    return ["members", "prospects", "all"].includes(value) ? value : "members";
  }

  function stagePublicAccessLabel(value) {
    return {
      members: "Adhérents uniquement",
      prospects: "Non-adhérents uniquement",
      all: "Adhérents et non-adhérents",
    }[normalizeStagePublicAccess(value)];
  }

  function stageAllowsContactKind(stage = {}, kind = "member") {
    const access = normalizeStagePublicAccess(stage.publicAccess);
    if (access === "all") return true;
    if (kind === "prospect" || kind === "prospects") return access === "prospects";
    return access === "members";
  }

  function todayInputValue() {
    return dateInputValue(new Date());
  }

  function stageDateRangeLabel(stage = {}) {
    const start = dateDisplay(stage.startDate);
    const end = dateDisplay(stage.endDate);
    if (start && end) return `${start} au ${end}`;
    if (start) return `A partir du ${start}`;
    if (end) return `Jusqu'au ${end}`;
    return "Dates non renseignées";
  }

  function stageIsPast(stage = {}) {
    const end = dateInputValue(stage.endDate || stage.startDate);
    return Boolean(end && end < todayInputValue());
  }

  function stageNaturallyClosed(stage = {}) {
    const deadline = dateInputValue(stage.registrationDeadline);
    return stageIsPast(stage) || Boolean(deadline && deadline < todayInputValue());
  }

  function stageRegistrationClosed(stage = {}) {
    if (stage.registrationReopened) return false;
    return stageNaturallyClosed(stage);
  }

  function stageStatusLabel(stage = {}) {
    if (stage.registrationReopened) return "Inscriptions réactivées";
    if (stageIsPast(stage)) return "Stage passé";
    if (stageRegistrationClosed(stage)) return "Inscriptions closes";
    return "Inscriptions ouvertes";
  }

  function stageStatusClass(stage = {}) {
    if (stage.registrationReopened) return "stage-reopened";
    if (stageIsPast(stage)) return "stage-past";
    if (stageRegistrationClosed(stage)) return "stage-closed";
    return "stage-open";
  }

  function stageDeadlineLabel(stage = {}) {
    return stage.registrationDeadline ? `Date limite : ${dateDisplay(stage.registrationDeadline)}` : "Date limite non renseignée";
  }

  function stageParticipantCount(stageId) {
    return (state.stageRegistrations[stageId] || []).length;
  }

  // Encore appelée par linkMemoRows() (06-normalize-state.js) — compatibilité memoRows legacy.
  function memoSource(row = {}, sourceState = state) {
    if (row.sourceType === "article") {
      return sourceState.tariffs.articles.find((article) => article.id === row.sourceId) || null;
    }
    if (row.sourceType === "stage") {
      return sourceState.tariffs.stages.find((stage) => stage.id === row.sourceId) || null;
    }
    if (row.sourceType === "discipline") {
      return sourceState.tariffs.disciplines.find((discipline) => (discipline.id || discipline.name) === row.sourceId || discipline.name === row.sourceId) || null;
    }
    return null;
  }

  function membershipHasFrozenPrice(row = {}) {
    return row.disciplinePrice !== undefined && row.disciplinePrice !== null && row.disciplinePrice !== "";
  }

  // Lot 3A (clôture financière) — DÉFINITION tarifaire actuelle d'une inscription, résolue de façon
  // AUTORITAIRE par identifiant (FIN-UNK-1) : la présence d'un `disciplineId` change définitivement la
  // règle — un repli nominal ne peut JAMAIS suivre un `disciplineById()` dans une chaîne `||`.
  //  - `disciplineDef` explicitement fournie (y compris null) fait autorité ;
  //  - `disciplineId` non vide → sa discipline si connue, sinon null (id inconnu ⇒ aucune définition,
  //    aucun emprunt par nom) ;
  //  - aucun id → résolution nominale UNIQUEMENT si le nom est unique (via disciplineDefinitionFromTarget) ;
  //  - nom ambigu → null (jamais le premier homonyme).
  function membershipDisciplineDefinition(row = {}) {
    if (row.disciplineDef !== undefined) return row.disciplineDef || null;
    const disciplineId = asText(row.disciplineId);
    if (disciplineId) return disciplineById(disciplineId) || null;
    return disciplineDefinitionFromTarget({ disciplineId: "", discipline: row.discipline });
  }
  // Lot 3A (clôture finale, FIN-ZERO-1) — une valeur monétaire n'est ABSENTE que si elle vaut
  // undefined, null ou "". Le nombre `0` est une valeur DÉFINIE (gratuité explicite) : il ne doit
  // jamais être confondu avec une absence, donc jamais sélectionné via l'opérateur `||`.
  function hasDefinedMoneyValue(value) {
    return value !== undefined && value !== null && value !== "";
  }
  // Lot 3A (clôture finale, FIN-ZERO-1) — résout UNE composante monétaire (prix ou licence) selon une
  // priorité STRICTE, sans jamais laisser `0` être écrasé :
  //   1. instantané figé (row.disciplinePrice / row.disciplineLicense), y compris 0 → source "snapshot" ;
  //   2. valeur canonique de la discipline résolue par identifiant, y compris 0 → source "canonical" ;
  //   3. montant legacy historique propre à l'inscription, uniquement si 1 et 2 sont absents → "legacy" ;
  //   4. aucune valeur définie → { value: 0, has: false, source: "none" } (tarif ABSENT ≠ gratuité 0 €).
  function resolveMoneyComponent(snapshotValue, canonicalValue, legacyValue) {
    if (hasDefinedMoneyValue(snapshotValue)) return { value: asNumber(snapshotValue), has: true, source: "snapshot" };
    if (hasDefinedMoneyValue(canonicalValue)) return { value: asNumber(canonicalValue), has: true, source: "canonical" };
    if (hasDefinedMoneyValue(legacyValue)) return { value: asNumber(legacyValue), has: true, source: "legacy" };
    return { value: 0, has: false, source: "none" };
  }
  function membershipDisciplinePricing(row = {}) {
    // Résolution centrale AUTORITAIRE (aucun appel direct à disciplineByName ici). Chaque composante
    // porte son indicateur de présence (has) et sa source, afin que l'interface distingue un tarif
    // ABSENT d'une gratuité à 0 € et un montant HISTORIQUE legacy du tarif canonique actuel.
    const discipline = membershipDisciplineDefinition(row) || {};
    const gross = resolveMoneyComponent(row.disciplinePrice, discipline.price, row.legacy?.total);
    const license = resolveMoneyComponent(row.disciplineLicense, discipline.license, row.legacy?.license);
    return {
      grossTotal: gross.value,
      license: license.value,
      hasGrossTotal: gross.has,
      hasLicense: license.has,
      grossTotalSource: gross.source,
      licenseSource: license.source,
    };
  }

  function calcMembership(row) {
    const pricing = membershipDisciplinePricing(row);
    const grossTotal = pricing.grossTotal;
    const license = pricing.license;
    const insurancePrice = membershipInsurancePrice(row);
    const discount = asNumber(row.discount);
    const localTotal = grossTotal + license + insurancePrice - discount;
    // PAY-P0-2/F2 — total/payé/reste dû AUTORITAIRES via le moteur claim (source + règlements créés
    // depuis une facture après émission ; référence FIGÉE à la facture une fois le claim émis, jamais
    // recalculée depuis un tarif source modifié ensuite). claimSourceContext ne rappelle JAMAIS
    // calcMembership pour son propre fallbackTotal (formule pure dédiée, membershipTariffValues) :
    // aucun risque de récursion. Repli sur le calcul local pur si la ligne n'a pas encore d'id
    // (cas théorique, jamais rencontré sur une adhésion réellement persistée).
    const claimState = row.id ? claimFinancialState(`membership:${row.id}`) : null;
    const total = claimState ? claimState.total : localTotal;
    const paid = claimState ? claimState.paid : paidAmount(row.payments);
    const restDue = claimState ? claimState.restDue : total - paid;
    return {
      total,
      grossTotal,
      license,
      insurancePrice,
      discount,
      paid,
      restDue,
      clubGain: total - license - Math.max(restDue, 0),
      alerts: (row.payments || []).map(paymentStatus).filter((status) => status && status !== "OK"),
      // Lot 3A (clôture absolue, FIN-ABS-2/3, FIN-PAY-1) — métadonnées de présence/source propagées
      // aux cartes, listes, factures et paiements : un `grossTotal` numérique de 0 ne suffit PLUS à
      // décider quoi afficher ou facturer. `hasGrossTotal:false` = tarif ABSENT (« Non défini », non
      // facturable) ; `grossTotalSource` distingue gratuité canonique / instantané / montant historique.
      hasGrossTotal: pricing.hasGrossTotal,
      hasLicense: pricing.hasLicense,
      grossTotalSource: pricing.grossTotalSource,
      licenseSource: pricing.licenseSource,
      claimAmbiguous: Boolean(claimState?.ambiguous),
      claimReadOnly: Boolean(claimState?.readOnly),
    };
  }

  function membershipTariffValues(row = {}) {
    const pricing = membershipDisciplinePricing(row);
    const grossTotal = pricing.grossTotal;
    const license = pricing.license;
    const insurancePrice = membershipInsurancePrice(row);
    const discount = asNumber(row.discount);
    return {
      grossTotal,
      license,
      insurancePrice,
      discount,
      total: grossTotal + license + insurancePrice - discount,
      // Lot 3A (clôture finale, FIN-ABS-1) — indicateurs de présence et sources : l'interface s'appuie
      // dessus pour afficher « Non défini » (tarif absent) plutôt qu'un trompeur « 0,00 € », et signaler
      // un montant historique legacy. Les nombres restent à 0 pour la compatibilité des calculs.
      hasGrossTotal: pricing.hasGrossTotal,
      hasLicense: pricing.hasLicense,
      grossTotalSource: pricing.grossTotalSource,
      licenseSource: pricing.licenseSource,
    };
  }

  // Lot 3A (clôture absolue, FIN-ABS-2/3) — libellés d'affichage CENTRAUX du tarif d'une inscription,
  // réutilisés par le formulaire, les cartes, les listes, les factures et les exports. Aucune surface
  // ne réimplémente localement la règle « 0 ≠ absent ». `values` peut être un objet issu de
  // membershipTariffValues() OU de calcMembership() (mêmes champs hasGrossTotal/grossTotalSource/…).
  //  - tarif ABSENT (hasGrossTotal=false) → « Non défini » / « Non calculable » ;
  //  - gratuité 0 € (hasGrossTotal=true, valeur 0) → « 0,00 € » ;
  //  - montant HISTORIQUE (grossTotalSource="legacy") → montant + drapeau grossHistoric.
  function membershipTariffDisplay(values = {}) {
    return {
      grossText: values.hasGrossTotal ? money(values.grossTotal) : "Non défini",
      totalText: values.hasGrossTotal ? money(values.total) : "Non calculable",
      grossHistoric: values.grossTotalSource === "legacy",
    };
  }
  // Lot 3A (clôture absolue, FIN-ABS-3/FIN-PAY-1) — éligibilité à la facturation / à l'encaissement :
  // un tarif ABSENT n'est jamais facturable ni réglable (aucune ligne ni échéance à 0 € trompeuse).
  // Une gratuité EXPLICITE (0 € défini) reste éligible avec son comportement normal.
  function membershipBillingEligibility(values = {}) {
    if (!values.hasGrossTotal) {
      return { billable: false, reason: "Tarif non défini : définissez le tarif de la discipline avant de facturer ou d'encaisser." };
    }
    return { billable: true, reason: "" };
  }
  // Lot 3A (clôture absolue, FIN-ABS-2) — montants affichés dans les CARTES et LISTES d'adhérents à
  // partir d'un objet calcMembership(). Un tarif ABSENT (hasGrossTotal=false) rend Total et Reste dû
  // « Non calculable » (jamais 0,00 €). « Réglé » reste factuel (paiements réellement encaissés).
  function membershipTotalDisplay(calc = {}) {
    const has = calc.hasGrossTotal;
    return {
      total: has ? money(calc.total) : "Non calculable",
      restDue: has ? money(calc.restDue) : "Non calculable",
      paid: money(calc.paid),
    };
  }

  function membershipDefaultTaxRate(row = {}) {
    // Lot 3A (clôture financière) — TVA par défaut issue de la discipline résolue de façon AUTORITAIRE
    // par identifiant (FIN-UNK-1) : un id inconnu ne fournit AUCUNE TVA (aucun emprunt par nom).
    // L'assurance conserve sa propre logique fiscale.
    const discipline = membershipDisciplineDefinition(row) || {};
    const insurance = insuranceChoiceByKey(membershipInsuranceChoice(row));
    return blendedTaxRate([
      { amount: asNumber(discipline.price), rate: tariffTaxRate(discipline) },
      { amount: asNumber(discipline.license), rate: tariffTaxRate(discipline) },
      { amount: asNumber(insurance?.price), rate: tariffTaxRate(insurance || {}) },
    ]);
  }

  function calcOrder(order) {
    const items = order.items || [];
    const gross = items.reduce((sum, item) => sum + asNumber(item.quantity) * asNumber(item.unitPrice), 0);
    const discount = asNumber(order.discount);
    const localTotal = Math.max(0, gross - discount);
    // PAY-P0-2/F2 — cf. calcMembership : total/payé/reste dû via le moteur claim, jamais de récursion
    // (claimSourceContext utilise une formule pure dédiée pour son fallbackTotal).
    const claimState = order.id ? claimFinancialState(`order:${order.id}`) : null;
    const total = claimState ? claimState.total : localTotal;
    const paid = claimState ? claimState.paid : paidAmount(order.payments);
    return {
      total,
      gross,
      discount,
      paid,
      restDue: claimState ? claimState.restDue : total - paid,
      alerts: (order.payments || []).map(paymentStatus).filter((status) => status && status !== "OK"),
      claimAmbiguous: Boolean(claimState?.ambiguous),
      claimReadOnly: Boolean(claimState?.readOnly),
    };
  }

  function orderDefaultTaxRate(order = {}) {
    const segments = orderItemDetails(order).map((item) => ({
      amount: asNumber(item.quantity) * asNumber(item.unitPrice),
      rate: tariffTaxRate(item.article || {}),
    }));
    return blendedTaxRate(segments);
  }

  function calcStageSegment(segment) {
    const subtotal = asNumber(segment.quantity) * asNumber(segment.unitPrice) - asNumber(segment.discount);
    const paid = paidAmount(segment.payments);
    return { subtotal, paid, restDue: subtotal - paid };
  }

  function stageDefaultTaxRate(stage = {}) {
    return tariffTaxRate(stage);
  }

  function lodgingDefaultTaxRate(stage = {}) {
    return lodgingTaxRate(stage);
  }

  // F2-AUDIT-002 — calcStageSegment() reste PUR à dessein (réutilisé avec des segments SYNTHÉTIQUES
  // dans des contextes non financiers : aperçu de formulaire avant sauvegarde, Journal d'audit — y
  // ajouter une dépendance au moteur claim y serait risqué et hors sujet). calcRegistration(), lui,
  // n'est JAMAIS appelé avec une inscription synthétique — uniquement de vraies lignes de
  // state.stageRegistrations[stageId] — et devient donc claim-aware quand stageId est fourni : total/
  // payé/reste dû (global ET détaillé event/lodging) reflètent alors les règlements créés depuis une
  // facture après émission, exactement comme calcMembership/calcOrder. Repli sur le calcul local pur
  // si stageId est omis (compatibilité des appelants non encore migrés).
  function calcRegistration(row, stageId = "") {
    const claimAware = Boolean(stageId && row.id);
    const event = claimAware
      ? claimFinancialState(`stage:${stageId}:${row.id}:event`)
      : (() => { const s = calcStageSegment(row.event || {}); return { total: s.subtotal, paid: s.paid, restDue: s.restDue, ambiguous: false, readOnly: false }; })();
    const lodging = claimAware
      ? claimFinancialState(`stage:${stageId}:${row.id}:lodging`)
      : (() => { const s = calcStageSegment(row.lodging || {}); return { total: s.subtotal, paid: s.paid, restDue: s.restDue, ambiguous: false, readOnly: false }; })();
    const alerts = [...(row.event?.payments || []), ...(row.lodging?.payments || [])]
      .map(paymentStatus)
      .filter((status) => status && status !== "OK");
    return {
      total: event.total + lodging.total,
      paid: event.paid + lodging.paid,
      restDue: event.restDue + lodging.restDue,
      alerts,
      event: { total: event.total, paid: event.paid, restDue: event.restDue, ambiguous: Boolean(event.ambiguous), readOnly: Boolean(event.readOnly) },
      lodging: { total: lodging.total, paid: lodging.paid, restDue: lodging.restDue, ambiguous: Boolean(lodging.ambiguous), readOnly: Boolean(lodging.readOnly) },
      claimAmbiguous: Boolean(event.ambiguous || lodging.ambiguous),
      claimReadOnly: Boolean(event.readOnly || lodging.readOnly),
    };
  }

  // Lot 2F — prédicat monétaire COMMUN à la surface « Paiements dus » (allAlerts + renderDuePayments).
  // Une créance n'est listée et actionnable que si son reste dû, ARRONDI AU CENTIME RÉELLEMENT AFFICHÉ,
  // vaut au moins 0,01 € — exactement ce que montre money(). Cela supprime la divergence historique
  // (allAlerts utilisait « > 0 », le rendu « > 0.005 ») et neutralise les résidus flottants. Attention :
  // money() affiche déjà « 0,01 € » dès 0,005 (arrondi), donc un simple « > 0.005 » masquerait à tort
  // une ligne affichée à 0,01 € ; l'arrondi en centimes est la seule règle cohérente avec l'affichage.
  // Négatif / NaN / valeur absente -> 0 centime -> jamais une dette actionnable. Ne modifie AUCUN calcul.
  function isPayableDue(amount) {
    return Math.round(asNumber(amount) * 100) >= 1;
  }

  function allAlerts() {
    const rows = [];
    for (const membership of state.memberships) {
      const calc = calcMembership(membership);
      if (isPayableDue(calc.restDue)) rows.push({ type: "membership", editAction: "edit-membership", id: membership.id, module: "Disciplines", person: membership, status: alertStatusForPayments(membership.payments), amount: calc.restDue });
    }
    // Module pilote Boutique — Lot 2F : une CRÉANCE Boutique existante est une donnée financière,
    // jamais une surface opérationnelle -> recensée INCONDITIONNELLEMENT (comme Disciplines et Stages),
    // indépendamment de settings.display.showBoutique et de hasFeature("shop"). Désactiver ou masquer
    // la Boutique retire sa vue, ses créations et ses actions de stock, mais JAMAIS une dette existante :
    // elle doit rester visible et directement soldable dans « Paiements dus » (order.payments), sans
    // réactivation ni dépendance à une facture. C'est renderDuePayments qui n'expose alors qu'une action
    // FINANCIÈRE (le tiroir de paiement de la commande), jamais une mutation structurelle. editAction
    // "edit-order" retiré : plus aucun consommateur ne le lit depuis cette surface (le tiroir remplace
    // le bouton). Aligne Boutique sur le comportement Stages (Lot 2D) dans la surface générique.
    for (const order of state.shopOrders) {
      const calc = calcOrder(order);
      if (isPayableDue(calc.restDue)) rows.push({ type: "order", id: order.id, module: "Boutique", person: order, status: alertStatusForPayments(order.payments), amount: calc.restDue });
    }
    // Module pilote Stages (Lot 2D) : une CRÉANCE existante est une donnée financière, jamais une
    // surface opérationnelle -> elle est recensée INCONDITIONNELLEMENT (comme Disciplines ci-dessus),
    // indépendamment de settings.display.showStages et de hasFeature("stages"). Désactiver le module
    // n'efface pas une dette : elle doit rester visible et encaissable dans « Paiements dus », sinon
    // l'argent dû devient invisible et inatteignable sans réactiver la fonctionnalité.
    // C'est renderDuePayments qui n'expose alors qu'une action FINANCIÈRE (le tiroir de paiement),
    // jamais une mutation structurelle. (Boutique conserve son comportement du Lot 2B, non modifié.)
    for (const stage of state.tariffs.stages) {
      for (const registration of state.stageRegistrations[stage.id] || []) {
        const payments = [...(registration.event?.payments || []), ...(registration.lodging?.payments || [])];
        // F2-AUDIT-002 — calcRegistration claim-aware (stageId fourni) : reflète les règlements créés
        // depuis une facture après émission, sur le total combiné ET par segment (event/lodging).
        const calc = calcRegistration(registration, stage.id);
        // Lot 2F — listée si et seulement si au moins un SCOPE (événement OU hébergement) est encore dû
        // au centime, avec le MÊME prédicat isPayableDue que renderDuePayments : toute ligne affichée
        // possède donc toujours au moins un tiroir de paiement (jamais de ligne « 0,00 € » sans contrôle).
        // stageId est CONSERVÉ (registrationPaymentHtml en a besoin pour retrouver l'inscription). En
        // revanche editAction "edit-registration" est retiré : depuis le Lot 2D, cette surface n'expose
        // qu'un tiroir de paiement (jamais une mutation structurelle), et plus aucun consommateur ne le lit.
        const eventDue = isPayableDue(calc.event.restDue);
        const lodgingDue = isPayableDue(calc.lodging.restDue);
        if (eventDue || lodgingDue) rows.push({ type: "registration", id: registration.id, stageId: stage.id, module: stage.name, person: registration, status: alertStatusForPayments(payments), amount: calc.restDue });
      }
    }
    return rows;
  }

  function dashboardStats() {
    const memberships = state.memberships.map(calcMembership);
    // Lot 2B/2D — point bloquant 1 : le CA global (total/réglé/reste dû) est un CALCUL HISTORIQUE. Les
    // commandes ET les inscriptions existantes y comptent toujours, que la Boutique ou les Stages soient
    // masqués (showBoutique/showStages) ou leur fonctionnalité désactivée (hasFeature). Masquer ou
    // désactiver ne retire jamais une donnée existante des totaux.
    const orders = state.shopOrders.map(calcOrder);
    const registrations = Object.values(state.stageRegistrations).flat().map(calcRegistration);
    const total = [...memberships, ...orders, ...registrations].reduce((sum, item) => sum + item.total, 0);
    const paid = [...memberships, ...orders, ...registrations].reduce((sum, item) => sum + item.paid, 0);
    const restDue = [...memberships, ...orders, ...registrations].reduce((sum, item) => sum + item.restDue, 0);
    return { total, paid, restDue, alerts: allAlerts() };
  }

  // En-tête de page : affiche devant le titre la MÊME icône que le menu (source de vérité unique
  // menuIconSvg → personnalisation settings.menuIcons incluse ; une modification d'icône se reflète
  // automatiquement dans le menu ET dans le titre). L'icône est purement décorative (aria-hidden) :
  // le titre reste l'unique nom accessible de l'en-tête, la hiérarchie <h1> est conservée, et rien
  // n'est ajouté à l'ordre de tabulation. Une seule <h1> par page (topbar du shell).
  function pageHeadingHtml(title) {
    const icon = (typeof menuIconSvg === "function") ? menuIconSvg(ui.view) : "";
    const iconHtml = icon ? `<span class="page-heading-icon" aria-hidden="true">${icon}</span>` : "";
    return `<h1 class="page-heading">${iconHtml}<span class="page-heading-label">${esc(title)}</span></h1>`;
  }

  function shell(title, body) {
    ensureMenuOrganizationV2();
    ensureMenuOrganizationV3();
    const theme = activeTheme();
    const currentClub = activeClub();
    const isBoutiqueMenuOpen = Boolean(ui.boutiqueMenuOpen);
    const isSettingsMenuOpen = Boolean(ui.settingsMenuOpen);
    const layout = resolveMenuLayout();
    const toEntry = (key) => [key, menuKeyLabel(key)];
    const isOpenGroup = (key) => key === "settings" ? isSettingsMenuOpen : key === "boutique" ? isBoutiqueMenuOpen : Boolean(ui.openMenuGroups && ui.openMenuGroups[key]);
    const parentKeys = menuParentKeys();
    // Dédoublonnage : une page n'apparaît qu'UNE seule fois dans le menu (dans le premier
    // groupe qui la contient, ordre du menu). Évite les doublons et les groupes hérités
    // redondants (ex. un ancien menu « Tarifs » alors que Tarifs est déjà dans Finances).
    const placedViews = new Set();
    const childrenByGroup = {};
    layout.main.forEach((key) => {
      if (!parentKeys.includes(key)) return;
      const kids = (layout[key] || []).filter((k) => isKnownViewKey(k) && isViewVisible(k) && !placedViews.has(k)).map(toEntry);
      kids.forEach(([k]) => placedViews.add(k));
      childrenByGroup[key] = kids;
    });
    // Un groupe PERSONNALISÉ vide (sans enfant visible) n'est pas affiché. Les groupes-pages
    // (Boutique, Paramètres) restent. Une page directe déjà placée dans un groupe est masquée.
    const visibleMain = layout.main.filter((key) => {
      if (parentKeys.includes(key)) {
        if (isCustomMenuGroup(key)) return (childrenByGroup[key] || []).length > 0;
        return isKnownViewKey(key) && isViewVisible(key);
      }
      return isKnownViewKey(key) && isViewVisible(key) && !placedViews.has(key);
    }).map(toEntry);
    const navSubmenuHtml = (groupKey) => {
      const children = childrenByGroup[groupKey] || [];
      return `<div class="nav-submenu ${isOpenGroup(groupKey) ? "open" : ""}" aria-label="Sous-menu ${esc(menuKeyLabel(groupKey))}">
        ${children.map(([subKey, subLabel]) => navButtonHtml(subKey, subLabel, ui.view === subKey)).join("")}
      </div>`;
    };
    // MODE CLASSIQUE : le menu de gauche devient une barre de menus EN HAUT du logiciel.
    // Chaque groupe ouvre ses sous-menus en déroulant ; les pages simples sont des boutons directs.
    // On réutilise exactement les mêmes entrées (visibleMain), data-view et la barre d'outils.
    if (settings.layout === "classic") {
      const topMenu = visibleMain.map(([key, label]) => {
        const isParent = menuParentKeys().includes(key);
        if (isParent) {
          const children = childrenByGroup[key] || [];
          // Si le groupe est lui-même une page (Boutique, Paramètres…), l'ajouter en tête
          // de son déroulé pour qu'elle reste accessible. Les groupes PERSONNALISÉS
          // (Adhérents, Activités, Finances…) ne sont que des conteneurs : pas de page propre
          // (sinon on créait un lien mort vers un data-view inexistant comme "grp-adherents").
          const ownPage = (!isCustomMenuGroup(key) && isViewVisible(key)) ? [[key, label]] : [];
          const entries = [...ownPage, ...children];
          if (!entries.length) return "";
          const groupActive = ui.view === key || children.some(([k]) => k === ui.view);
          return `<details class="topmenu-group">
            <summary class="${groupActive ? "active" : ""}"><span class="nav-icon">${menuIconSvg(key)}</span><span class="nav-label">${esc(label)}</span><span class="topmenu-caret">▾</span></summary>
            <div class="topmenu-dropdown">${entries.map(([sk, sl]) => navButtonHtml(sk, sl, ui.view === sk)).join("")}</div>
          </details>`;
        }
        return navButtonHtml(key, label, ui.view === key);
      }).join("");
      return `
        <div class="shell-classic-top">
          <main class="content ${ui.view === "help" ? "help-content-shell" : ""} ${settings.topbarHidden ? "topbar-hidden" : ""}">
            <header class="topbar topbar-with-menu">
              <nav class="topmenu" aria-label="Menu principal">
                <div class="topmenu-brand"><img src="${esc(appLogoSrc())}" alt="" /><strong>${esc(settings.clubName || "MonGestaClub")}</strong></div>
                <div class="topmenu-items">${topMenu}</div>
              </nav>
              <div class="topbar-title-row">
                <button class="sidebar-toggle topbar-collapse" data-action="toggle-topbar" aria-label="Masquer la barre du haut" title="Masquer la barre du haut">${toolbarIcon("collapse")}</button>
                ${pageHeadingHtml(title)}
              </div>
              ${topToolbar()}
            </header>
            <button class="topbar-show-btn" data-action="toggle-topbar" aria-label="Afficher la barre du haut" title="Afficher la barre du haut">${toolbarIcon("expand")} Barre d'outils</button>
            <section class="view ${ui.view === "help" ? "help-view" : ""}">${body}</section>
          </main>
        </div>
      `;
    }
    return `
      <div class="shell ${settings.sidebarHidden ? "sidebar-hidden" : ""}">
        <aside class="sidebar">
          <div class="brand">
            <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
            <div>
              <strong>${esc(settings.clubName || "MonGestaClub")}</strong>
              <span>${esc(settings.clubSubtitle || "Gestion de club")}</span>
            </div>
          </div>
          <div class="side-switchers">
            ${clubSwitcherHtml(currentClub)}
            ${userSwitcherHtml()}
          </div>
          <nav class="nav">
            ${visibleMain.map(([key, label]) => {
              const isParent = menuParentKeys().includes(key);
              const active = ui.view === key || (isParent && isOpenGroup(key));
              return `${navButtonHtml(key, label, active)}${isParent ? navSubmenuHtml(key) : ""}`;
            }).join("")}
          </nav>
          <div class="backup-actions">
            <button type="button" class="sidebar-mode-chip" data-action="open-display-settings" title="Mode d'affichage — cliquer pour le changer dans Paramètres">${esc(displayModeSummary())}</button>
            <div class="backup-io">
              <button type="button" class="backup-io-btn" data-action="export-json" title="Exporter une sauvegarde JSON" aria-label="Exporter une sauvegarde JSON">${toolbarIcon("download")}<span class="backup-io-label">Exporter</span></button>
              <button type="button" class="backup-io-btn" data-action="import-json" title="Importer une sauvegarde JSON" aria-label="Importer une sauvegarde JSON">${toolbarIcon("upload")}<span class="backup-io-label">Importer</span></button>
            </div>
            <span>Thème ${esc(theme.name)}</span>
          </div>
        </aside>
        <main class="content ${ui.view === "help" ? "help-content-shell" : ""} ${settings.topbarHidden ? "topbar-hidden" : ""}">
          <header class="topbar">
            <div class="topbar-title-row">
              <button class="sidebar-toggle" data-action="toggle-sidebar" aria-label="${settings.sidebarHidden ? "Afficher le menu" : "Masquer le menu"}" title="${settings.sidebarHidden ? "Afficher le menu" : "Masquer le menu"}">${settings.sidebarHidden ? "☰" : "⟨"}</button>
              <button class="sidebar-toggle topbar-collapse" data-action="toggle-topbar" aria-label="Masquer la barre du haut" title="Masquer la barre du haut">${toolbarIcon("collapse")}</button>
              ${pageHeadingHtml(title)}
            </div>
            ${topToolbar()}
          </header>
          <button class="topbar-show-btn" data-action="toggle-topbar" aria-label="Afficher la barre du haut" title="Afficher la barre du haut">${toolbarIcon("expand")} Barre d'outils</button>
          <section class="view ${ui.view === "help" ? "help-view" : ""}">${body}</section>
        </main>
      </div>
    `;
  }

  function topToolbar() {
    const withLabels = Boolean(displaySettings().toolbarLabels);
    return `<div class="topbar-actions app-toolbar ${withLabels ? "show-labels" : ""}" aria-label="Raccourcis">
      <div class="tool-group">
        <button class="tool-button" title="Page précédente" data-action="nav-back">${toolbarIcon("back")}<span class="tool-label">Précédent</span></button>
        <button class="tool-button" title="Page suivante" data-action="nav-forward">${toolbarIcon("forward")}<span class="tool-label">Suivant</span></button>
      </div>
      <div class="tool-group">
        <button class="tool-button" title="Annuler la dernière modification" data-action="undo-change">${toolbarIcon("undo")}<span class="tool-label">Annuler</span></button>
        <button class="tool-button" title="Rétablir la dernière modification" data-action="redo-change">${toolbarIcon("redo")}<span class="tool-label">Rétablir</span></button>
      </div>
      <div class="tool-group">
        <button class="tool-button" title="Couper la sélection" data-action="edit-cut">${toolbarIcon("cut")}<span class="tool-label">Couper</span></button>
        <button class="tool-button" title="Copier la sélection" data-action="edit-copy">${toolbarIcon("copy")}<span class="tool-label">Copier</span></button>
        <button class="tool-button" title="Coller dans le champ actif" data-action="edit-paste">${toolbarIcon("paste")}<span class="tool-label">Coller</span></button>
      </div>
      <div class="tool-group">
        ${ui.view === "availability" ? "" : `<button class="tool-button" title="Imprimer la page" data-action="print-page">${toolbarIcon("print")}<span class="tool-label">Imprimer</span></button>
        <button class="tool-button" title="Exporter en PDF" data-action="export-pdf"><span class="tool-text-icon">PDF</span><span class="tool-label">PDF</span></button>
        <button class="tool-button" title="Exporter la page en CSV" data-action="export-csv"><span class="tool-text-icon">CSV</span><span class="tool-label">Exporter</span></button>`}
        <button class="tool-button" title="Ouvrir l'aide dans un panneau latéral (sans quitter la page)" data-action="toggle-help-panel">${toolbarIcon("help")}<span class="tool-label">Aide</span></button>
        ${isViewVisible("assistant") ? `<button class="tool-button${ui.view === "assistant" ? " active" : ""}" title="Ouvrir le Centre d'accompagnement de l'assistant" data-action="open-dashboard-target" data-target="assistant">${toolbarIcon("assistant")}<span class="tool-label">Accompagnement</span></button>` : ""}
      </div>
      <div class="tool-group search-tool-group">
        <input class="global-search-input" type="search" placeholder="Recherche globale" value="${esc(ui.globalSearch)}" data-global-search title="Entrée pour rechercher partout" />
        <button class="tool-button" title="Rechercher partout" data-action="run-global-search" aria-label="Rechercher partout">${toolbarIcon("search")}<span class="tool-label">Recherche</span></button>
      </div>
      <div class="tool-group">
        <button class="tool-button" title="Enregistrer dans le logiciel" data-action="save-now" aria-label="Enregistrer dans le logiciel">${toolbarIcon("save")}<span class="tool-label">Enregistrer</span></button>
      </div>
      <span class="save-state" role="status" aria-live="polite">${esc(ui.saveMessage)}</span>
    </div>`;
  }


  function clubSwitcherHtml(currentClub = activeClub()) {
    const store = clubStore || normalizeClubStore(rawClubStoreFromStorage());
    const visibleClubs = store.clubs.filter((club) => !club.archived);
    if (!visibleClubs.length) {
      return `<div class="club-switcher empty"><button type="button" data-action="new-club">Créer un club</button></div>`;
    }
    return `<div class="club-switcher" title="Club actif">
      <span>Club actif</span>
      <select data-club-switch>
        ${visibleClubs.map((club) => `<option value="${esc(club.id)}" ${club.id === currentClub?.id ? "selected" : ""}>${esc(club.name)}</option>`).join("")}
      </select>
      <button type="button" data-view="clubs">Gérer</button>
    </div>`;
  }

  function licenseBanner() {
    if (!license || license.activated) return "";
    const n = license.daysLeft;
    const text = license.trialActive
      ? `Essai gratuit : ${n} jour${n !== 1 ? "s" : ""} restant${n !== 1 ? "s" : ""}`
      : "Essai terminé : activation nécessaire";
    return `<div class="license-banner ${license.trialActive ? "" : "danger"}">
      <span>${esc(text)}</span>
      <button data-action="open-license">Activer</button>
    </div>`;
  }

  function renderLicensePanel(blocking = false) {
    const status = license || {};
    if (status.activated) {
      const activatedDate = status.activatedAt
        ? new Date(status.activatedAt).toLocaleDateString("fr-FR")
        : "";
      return `<div class="license-panel ${blocking ? "blocking" : ""}">
        <div class="license-card">
          <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
          <h2>Licence</h2>
          <div class="license-badge ok">Licence activée</div>
          <div class="license-status-grid">
            <span>Numéro de série</span><strong>${esc(status.serial || "–")}</strong>
            ${activatedDate ? `<span>Activée le</span><strong>${esc(activatedDate)}</strong>` : ""}
            <span>Identifiant</span><strong>${esc(status.machineId || "–")}</strong>
          </div>
          <div class="inline-actions">
            <button data-action="copy-machine-id">Copier l'identifiant</button>
          </div>
        </div>
      </div>`;
    }
    const n = status.daysLeft ?? 0;
    return `<div class="license-panel ${blocking ? "blocking" : ""}">
      <div class="license-card">
        <img src="${esc(appLogoSrc())}" alt="MonGestaClub" />
        <h2>${blocking ? "Activation requise" : "Licence"}</h2>
        ${status.trialActive
          ? `<div class="license-badge trial">${n} jour${n !== 1 ? "s" : ""} d'essai restant${n !== 1 ? "s" : ""}</div>`
          : `<div class="license-badge expired">Essai terminé</div>`}
        <div class="license-steps">
          <span>1. Copie l'identifiant ordinateur ci-dessous</span>
          <span>2. Envoie-le pour recevoir ton numéro de série</span>
          <span>3. Saisis le numéro de série et clique Activer</span>
        </div>
        <div class="license-machine-id-row">
          <code>${esc(status.machineId || "–")}</code>
          <button type="button" data-action="copy-machine-id">Copier</button>
        </div>
        <label>Numéro de série<input data-license-input type="text" placeholder="MGC-...." autocomplete="off" /></label>
        <div class="inline-actions">
          <button data-action="request-license-email">Envoyer par email</button>
          <button class="primary" data-action="activate-license">Activer</button>
        </div>
        ${status.clockRollback ? `<p class="danger-text">La date de l'ordinateur semble avoir été reculée. Vérifie l'horloge avant d'activer.</p>` : ""}
      </div>
    </div>`;
  }

  async function refreshLicenseStatus() {
    if (!window.monGestaClubShell?.getLicenseStatus) {
      license = null;
      return;
    }
    try {
      license = await window.monGestaClubShell.getLicenseStatus();
    } catch (error) {
      console.error(error);
      license = null;
    }
  }

  function render() {
    const currentNav = app.querySelector(".nav");
    if (currentNav) ui.sidebarNavScroll = currentNav.scrollTop;
    document.documentElement.dataset.theme = settings.theme;
    applyThemeOverrides();
    applyTypographySettings();
    applyAppLogo();
    document.documentElement.dataset.themeAnimations = settings.themeAnimations ? "on" : "off";
    if (!isViewVisible(ui.view)) {
      ui.view = firstVisibleView();
      ui.settingsMenuOpen = false;
      ui.boutiqueMenuOpen = ui.view === "boutique";
      // Audit Navigation — seul point racine de la redirection silencieuse (change de mode
      // d'affichage, décochage d'un module, désactivation Boutique/Stages, ou retour arrière
      // vers une vue devenue invisible entre-temps). Un message resté d'une action précédente
      // n'a plus de rapport avec ce qui vient de se passer à l'écran : on le remplace plutôt
      // que le garder, sinon la redirection resterait aussi silencieuse qu'avant.
      const fallbackLabel = Object.fromEntries(views)[ui.view] || ui.view;
      ui.saveMessage = `Ce module n'est pas affiché dans ce club. Vous avez été redirigé vers ${fallbackLabel}.`;
    }
    if (license && !license.canUse) {
      app.innerHTML = renderLicensePanel(true);
      return;
    }
    if (!activeClub()) {
      app.innerHTML = `<main class="password-gate">
        <div class="license-card password-card">
          <img src="${esc(DEFAULT_LOGO)}" alt="MonGestaClub" />
          <h2>Aucun club actif</h2>
          <p class="muted">Crée ou sélectionne un club pour utiliser le logiciel. Les anciennes données ne sont pas supprimées.</p>
          ${ui.migrationError ? `<div class="form-error">${esc(ui.migrationError)}</div>` : ""}
          <button class="primary" type="button" data-action="new-club">Créer un club</button>
        </div>
      </main>`;
      return;
    }
    const activeKey = document.activeElement?.dataset?.focus;
    const cursor = document.activeElement && "selectionStart" in document.activeElement ? document.activeElement.selectionStart : null;
    const titles = Object.fromEntries(views);
    // Lot "Notes contextuelles par page" — POINT D'INJECTION UNIQUE : contextualNotesBlockHtml()
    // renvoie "" si aucune note active ne cible ui.view (aucun DOM ajouté), sinon un bloc compact
    // préfixé au contenu de la page. Volontairement ici (pas dans shell() ni dans chaque renderXxx()) :
    // couvre les deux layouts (Moderne/Classique, qui partagent tous les deux cette même variable
    // body) sans dupliquer de logique ni toucher les vingt renderers individuels.
    const body = contextualNotesBlockHtml(ui.view) + renderView();
    app.innerHTML = shell(titles[ui.view] || "Accueil", body) + helpPanelHtml();
    document.documentElement.dataset.helpPanel = (ui.helpPanelOpen && ui.view !== "help") ? "open" : "closed";
    const topbar = app.querySelector(".topbar");
    if (topbar) topbar.insertAdjacentHTML("afterend", licenseBanner());
    if (topbar && ui.migrationError) topbar.insertAdjacentHTML("afterend", `<div class="license-banner danger"><span>${esc(ui.migrationError)}</span></div>`);
    makeTablesResizable();
    applyClickableTooltips(app);
    enhanceNumberSteppers(app);
    setupSidebarMenuScroll();
    setupTopMenu();
    setupMenuOrderDrag();
    setupHelpPanel();
    adjustHelpLayout();
    if (activeKey) {
      const next = app.querySelector(`[data-focus="${CSS.escape(activeKey)}"]`);
      if (next) {
        next.focus();
        if (cursor !== null && "setSelectionRange" in next) next.setSelectionRange(cursor, cursor);
      }
    }
    // Assistant : visite interactive (halo/bulle), aide passive, célébration discrète.
    if (typeof assistantAfterRender === "function") assistantAfterRender();
  }

