  // Panneau d'aide latéral : réutilise EXACTEMENT renderHelp() (aucune duplication de texte).
  // Le CSS masque le héros et le sommaire à 2 colonnes pour un rendu compact en panneau.
  // Inutile par-dessus la page Aide elle-même (mêmes ids) -> pas affiché dans ce cas.
  function helpPanelHtml() {
    if (!ui.helpPanelOpen || ui.view === "help") return "";
    return `<aside class="help-panel" role="complementary" aria-label="Aide">
      <header class="help-panel-head">
        <strong>Aide</strong>
        <button type="button" class="help-panel-link" data-action="open-help-page" title="Ouvrir l'aide en pleine page">Plein écran</button>
        <button type="button" class="icon help-panel-close" data-action="close-help-panel" title="Fermer l'aide" aria-label="Fermer l'aide">×</button>
      </header>
      <div class="help-panel-body">${renderHelp()}</div>
    </aside>`;
  }

  // Positionne le panneau sur la rubrique de la page courante (contextuel) ; conserve le
  // défilement tant qu'on reste sur la même page.
  function setupHelpPanel() {
    const body = app.querySelector(".help-panel-body");
    if (!body) { ui.helpPanelView = null; return; }
    if (ui.helpPanelView !== ui.view) {
      ui.helpPanelView = ui.view;
      ui.helpPanelScroll = 0;
      const id = helpSectionForView(ui.view);
      const section = id ? body.querySelector(`#${CSS.escape(id)}`) : null;
      if (section) body.scrollTop = body.scrollTop + (section.getBoundingClientRect().top - body.getBoundingClientRect().top);
      else body.scrollTop = 0;
    } else {
      body.scrollTop = ui.helpPanelScroll || 0;
    }
    body.addEventListener("scroll", () => { ui.helpPanelScroll = body.scrollTop; });
  }

  function scrollHelpToTarget() {
    if (!ui.helpTarget) return;
    const content = app.querySelector(".help-content");
    const target = content?.querySelector(`#${CSS.escape(ui.helpTarget)}`);
    ui.helpTarget = "";
    if (!target || !content) return;
    const top = target.getBoundingClientRect().top - content.getBoundingClientRect().top + content.scrollTop - 8;
    content.scrollTo({ top: Math.max(0, top), behavior: "auto" });
  }

  function adjustHelpLayout() {
    if (ui.view !== "help") return;
    const view = app.querySelector(".help-view");
    const topbar = app.querySelector(".topbar");
    if (!view || !topbar) return;
    let above = Math.round(topbar.getBoundingClientRect().height);
    app.querySelectorAll(".license-banner").forEach((banner) => {
      above += Math.round(banner.getBoundingClientRect().height);
    });
    document.documentElement.style.setProperty("--help-view-height", `calc(100vh - ${above}px)`);
    const content = view.querySelector(".help-content");
    attachWheelScroll(view.querySelector(".help-toc"));
    attachWheelScroll(content);
    view.querySelectorAll(".help-toc a[href^='#']").forEach((link) => {
      if (link.dataset.tocReady) return;
      link.dataset.tocReady = "true";
      link.addEventListener("click", (event) => {
        const target = content?.querySelector(`#${CSS.escape(link.getAttribute("href").slice(1))}`);
        if (!target || !content) return;
        event.preventDefault();
        const top = target.getBoundingClientRect().top - content.getBoundingClientRect().top + content.scrollTop - 8;
        content.scrollTo({ top, behavior: "smooth" });
      });
    });
    scrollHelpToTarget();
  }

  function attachWheelScroll(el) {
    if (!el || el.dataset.wheelScrollReady) return;
    el.dataset.wheelScrollReady = "true";
    el.addEventListener("wheel", (event) => {
      if (event.target.closest("input, select, textarea")) return;
      if (el.scrollHeight <= el.clientHeight + 1) return;
      const before = el.scrollTop;
      el.scrollTop += event.deltaY;
      if (el.scrollTop !== before) event.preventDefault();
    }, { passive: false });
  }

  // Barre de menus du haut (mode Classique) : un seul déroulé ouvert à la fois,
  // et fermeture quand on clique en dehors. Les groupes sont des <details> recréés
  // à chaque rendu, donc les listeners "toggle" ne fuient pas. Le listener "clic
  // dehors" est posé une seule fois (drapeau global).
  function setupTopMenu() {
    const groups = [...app.querySelectorAll(".topmenu-group")];
    if (!groups.length) return;
    const closeAll = (except) => groups.forEach((g) => { if (g !== except && g.open) g.open = false; });
    const syncAria = (details) => { const s = details.querySelector("summary"); if (s) s.setAttribute("aria-expanded", details.open ? "true" : "false"); };
    groups.forEach((details) => {
      syncAria(details);
      details.addEventListener("toggle", () => {
        syncAria(details);
        if (details.open) closeAll(details); // un seul menu ouvert à la fois
      });
      // Balayage « menu desktop » : si un menu est DÉJÀ ouvert, survoler un autre l'ouvre
      // automatiquement (le toggle ci-dessus referme les autres). On n'ouvre jamais au survol
      // depuis l'état fermé -> pas d'ouverture intempestive.
      const summary = details.querySelector("summary");
      if (summary) summary.addEventListener("mouseenter", () => {
        if (!details.open && groups.some((g) => g.open)) details.open = true;
      });
    });
    // Fermeture quand la souris quitte toute la zone de menu. Le déroulé est un descendant de
    // .topmenu-items -> passer du bouton au panneau ne déclenche pas mouseleave. Petit délai +
    // annulation au ré-entrée pour éviter tout clignotement.
    const bar = app.querySelector(".topmenu-items");
    if (bar) {
      let leaveTimer = null;
      bar.addEventListener("mouseleave", () => {
        if (!groups.some((g) => g.open)) return;
        leaveTimer = setTimeout(() => closeAll(null), 240);
      });
      bar.addEventListener("mouseenter", () => { if (leaveTimer) { clearTimeout(leaveTimer); leaveTimer = null; } });
    }
    if (!window.__mgcTopMenuOutsideBound) {
      window.__mgcTopMenuOutsideBound = true;
      // "click" (et non "pointerdown") : se déclenche au relâchement, donc APRÈS un
      // éventuel glisser-déposer — ne perturbe jamais l'initiation d'un drag natif
      // (ex. réorganisation du menu dans Paramètres).
      document.addEventListener("click", (event) => {
        if (event.target.closest(".topmenu-group")) return;
        app.querySelectorAll(".topmenu-group[open]").forEach((d) => { d.open = false; });
      });
      // Échap referme le menu ouvert.
      document.addEventListener("keydown", (event) => {
        if (event.key === "Escape") app.querySelectorAll(".topmenu-group[open]").forEach((d) => { d.open = false; });
      });
    }
  }

  function setupSidebarMenuScroll() {
    const sidebar = app.querySelector(".sidebar");
    const nav = sidebar?.querySelector(".nav");
    if (!sidebar || !nav) return;
    nav.scrollTop = ui.sidebarNavScroll || 0;
    sidebar.addEventListener("wheel", (event) => {
      if (event.target.closest("input, select, textarea")) return;
      if (nav.scrollHeight <= nav.clientHeight + 1) return;
      const before = nav.scrollTop;
      nav.scrollTop += event.deltaY;
      if (nav.scrollTop !== before) {
        ui.sidebarNavScroll = nav.scrollTop;
        event.preventDefault();
      }
    }, { passive: false });
    nav.addEventListener("scroll", () => {
      ui.sidebarNavScroll = nav.scrollTop;
    }, { passive: true });
  }

  function enhanceNumberSteppers(root = document) {
    root.querySelectorAll('input[type="number"]:not([data-number-stepper-ready])').forEach((input) => {
      if (input.closest(".number-stepper")) {
        input.dataset.numberStepperReady = "1";
        return;
      }
      if (input.readOnly || input.disabled) {
        input.dataset.numberStepperReady = "1";
        return;
      }
      input.dataset.numberStepperReady = "1";
      const wrapper = document.createElement("span");
      wrapper.className = "number-stepper";
      input.parentNode.insertBefore(wrapper, input);
      wrapper.appendChild(input);
      wrapper.insertAdjacentHTML("beforeend", `<span class="number-stepper-controls" aria-hidden="false">
        <button type="button" data-number-step="-1" title="Diminuer" aria-label="Diminuer">−</button>
        <button type="button" data-number-step="1" title="Augmenter" aria-label="Augmenter">+</button>
      </span>`);
    });
  }

  function adjustNumberInput(button) {
    const input = button.closest(".number-stepper")?.querySelector('input[type="number"]');
    if (!input || input.disabled || input.readOnly) return;
    const direction = asNumber(button.dataset.numberStep) < 0 ? -1 : 1;
    const previous = input.value;
    input.focus({ preventScroll: true });
    // Les boutons + / - incrémentent toujours de 1 (la saisie au centime reste possible au clavier).
    const current = asText(input.value) ? asNumber(input.value) : 0;
    const min = asText(input.min) ? asNumber(input.min) : -Infinity;
    const max = asText(input.max) ? asNumber(input.max) : Infinity;
    const next = Math.min(max, Math.max(min, current + direction));
    input.value = String(Math.round(next * 100) / 100);
    if (input.value !== previous) {
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  function applyClickableTooltips(root = document) {
    root.querySelectorAll(".tariff-row[data-action='edit-tariff-row']").forEach((row) => {
      row.title = "Cliquer pour éditer";
    });
    root.querySelectorAll(".tariff-row.editing").forEach((row) => {
      row.title = "Modification en cours";
    });
    root.querySelectorAll([
      ".clickable-row[data-action]",
      ".clickable-row[data-agenda-action]",
      ".clickable-card[data-action]",
      ".membership-card[data-action]",
      ".registration-line[data-action]",
      ".shop-follow-row[data-action]",
      ".signal-row[data-action]",
    ].join(",")).forEach((row) => {
      if (!row.title) row.title = "Cliquer ici pour ouvrir";
    });
    root.querySelectorAll(".collapsible-title, .collapsible-title-row").forEach((row) => {
      row.title = row.getAttribute("aria-expanded") === "true" ? "Cliquer pour refermer" : "Cliquer ici pour ouvrir";
    });
  }

  function makeTablesResizable() {
    settings.columnWidths = settings.columnWidths || {};
    app.querySelectorAll("table").forEach((table, tableIndex) => {
      table.querySelectorAll("th").forEach((th, columnIndex) => {
        const label = asText(th.textContent) || `col-${columnIndex}`;
        const key = `${ui.view}:${tableIndex}:${columnIndex}:${label}`;
        if (settings.columnWidths[key]) {
          th.style.width = `${settings.columnWidths[key]}px`;
          th.style.minWidth = `${settings.columnWidths[key]}px`;
        }
        const handle = document.createElement("span");
        handle.className = "column-resizer";
        handle.title = "Agrandir ou réduire la colonne";
        handle.addEventListener("mousedown", (event) => {
          event.preventDefault();
          const startX = event.clientX;
          const startWidth = th.getBoundingClientRect().width;
          const move = (moveEvent) => {
            const width = Math.max(52, Math.round(startWidth + moveEvent.clientX - startX));
            th.style.width = `${width}px`;
            th.style.minWidth = `${width}px`;
            settings.columnWidths[key] = width;
          };
          const stop = () => {
            document.removeEventListener("mousemove", move);
            document.removeEventListener("mouseup", stop);
            persistSettings();
          };
          document.addEventListener("mousemove", move);
          document.addEventListener("mouseup", stop);
        });
        th.appendChild(handle);
      });
    });
  }

  function renderDuePayments() {
    const alerts = allAlerts();
    const totalDue = alerts.reduce((sum, a) => sum + a.amount, 0);

    if (!alerts.length) {
      return `<div class="band">
        <div class="band-title"><h2>Paiements dus</h2><strong>0 dû</strong></div>
        <div class="band-body"><p class="muted">Aucun paiement en attente. Tous les comptes sont à jour.</p></div>
      </div>`;
    }

    const groups = {};
    for (const alert of alerts) {
      const key = contactLinkForRow(alert.person) || `${personLabel(alert.person)}|${asText(alert.person.birthDate)}`;
      if (!groups[key]) groups[key] = { person: alert.person, items: [], total: 0 };
      groups[key].items.push(alert);
      groups[key].total += alert.amount;
    }
    const sorted = Object.values(groups).sort((a, b) => b.total - a.total);

    const sourceLabel = { membership: "Discipline", order: "Boutique", registration: "Stage" };
    // Lot 2D — accès FINANCIER à une créance Stage existante. « Payer » menait à edit-registration,
    // une mutation structurelle : inopérante quand la fonctionnalité est désactivée (la dette devenait
    // alors inencaissable sans réactiver Stages). On rend ici le tiroir de paiement RÉEL, celui-là même
    // qu'utilise la vue Stages : mêmes contrôles, même action validate-payment, mêmes calculs, même
    // Journal, même persistance — aucune logique financière dupliquée. Les deux accès (vue Stages et
    // « Paiements dus ») lisent et écrivent la même source de vérité (state.stageRegistrations).
    // Les scopes event et hébergement restent des dettes DISTINCTES : un tiroir par scope réellement dû.
    // Aucun champ structurel n'est exposé ici (ni tarif, ni participant, ni prestation, ni suppression).
    const registrationPaymentHtml = (item) => {
      const registration = (state.stageRegistrations[item.stageId] || []).find((row) => row.id === item.id);
      if (!registration) return "";
      const stage = stageById(item.stageId);
      // F2-AUDIT-002 — reste dû claim-aware par scope (calcRegistration, stageId fourni) ; le montant
      // de référence (segment.subtotal, pour le pré-remplissage du tiroir) reste le tarif du segment.
      const calc = calcRegistration(registration, item.stageId);
      const scopes = [
        { part: "event", label: "Stage", segment: calcStageSegment(registration.event || {}), restDue: calc.event.restDue, payments: registration.event?.payments || [], taxRate: stageDefaultTaxRate(stage) },
        { part: "lodging", label: "Hébergement", segment: calcStageSegment(registration.lodging || {}), restDue: calc.lodging.restDue, payments: registration.lodging?.payments || [], taxRate: lodgingDefaultTaxRate(stage) },
      ].filter((scope) => isPayableDue(scope.restDue));
      return scopes.map((scope) => `<div class="due-item-payment">
        <span class="due-item-payment-label">${esc(stage.name || "Stage")} · ${esc(scope.label)} · reste dû ${money(scope.restDue)}</span>
        ${paymentControls("registration", registration.id, scope.payments, { stageId: item.stageId, part: scope.part, total: scope.segment.subtotal, defaultTaxRate: scope.taxRate })}
      </div>`).join("");
    };
    // Lot 2F — accès FINANCIER à une créance Boutique existante, sur le même modèle que Stages (Lot 2D).
    // Une commande non soldée reste encaissable depuis « Paiements dus » quelle que soit la disponibilité
    // (hasFeature("shop")) ou l'affichage (showBoutique) de la Boutique : on rend le tiroir de paiement
    // RÉEL — paymentControls("order", …), celui-là même qu'utilise la vue Boutique — écrivant directement
    // dans order.payments. Même moteur (validate-payment), mêmes calculs (calcOrder), même Journal, aucune
    // logique dupliquée. Aucun champ structurel (article, quantité, stock) n'est exposé. La facture
    // éventuellement liée et son paymentsSnapshot ne sont PAS touchés (désynchronisation préexistante,
    // hors périmètre du Lot 2F). Le prédicat isPayableDue garantit qu'un tiroir n'apparaît que si dû.
    const orderPaymentHtml = (item) => {
      const order = (state.shopOrders || []).find((row) => row.id === item.id);
      if (!order) return "";
      const calc = calcOrder(order);
      if (!isPayableDue(calc.restDue)) return "";
      return `<div class="due-item-payment">
        <span class="due-item-payment-label">Boutique · reste dû ${money(calc.restDue)}</span>
        ${paymentControls("order", order.id, order.payments || [], { total: calc.total, defaultTaxRate: orderDefaultTaxRate(order) })}
      </div>`;
    };
    // Lot 2G-C1 — accès FINANCIER UNIFORME à une créance d'adhésion, sur le même modèle que Stages (2D)
    // et Boutique (2F). « Payer » ouvrait edit-membership, un dialogue de MUTATION STRUCTURELLE (discipline,
    // groupe, cotisation, licence, assurance…) : régulariser une dette ne devait pas exiger d'ouvrir la
    // fiche complète, et cette surface n'a pas à exposer une modification. On rend ici le tiroir de paiement
    // RÉEL — paymentControls("membership", …), celui-là même qu'utilisent les cartes de la vue Disciplines —
    // écrivant directement dans membership.payments. Même moteur (validate-payment), mêmes calculs
    // (calcMembership), même Journal (un seul payment.validated par paiement), même persistance. Aucune
    // logique dupliquée, aucun champ structurel exposé, aucune dépendance à la fonctionnalité memberships
    // (aucun gating par hasFeature dans ce lot : la créance reste encaissable inconditionnellement).
    // Le règlement structurel depuis la fiche (edit-membership) et l'agenda « À encaisser » restent
    // opérationnels et inchangés (allAlerts conserve editAction pour ces surfaces). isPayableDue garantit
    // qu'un tiroir n'apparaît que si la créance est réellement due au centime (jamais « 0,00 € »).
    const membershipPaymentHtml = (item) => {
      const membership = (state.memberships || []).find((row) => row.id === item.id);
      if (!membership) return "";
      const calc = calcMembership(membership);
      if (!isPayableDue(calc.restDue)) return "";
      return `<div class="due-item-payment">
        <span class="due-item-payment-label">Adhésion · reste dû ${money(calc.restDue)}</span>
        ${paymentControls("membership", membership.id, membership.payments || [], { total: calc.total, defaultTaxRate: membershipDefaultTaxRate(membership) })}
      </div>`;
    };
    const cards = sorted.map(({ person, items, total }) => {
      const label = personLabel(person);
      const email = asText(person.email);
      const phone = asText(person.phone || person.tel);
      // Lot 3B-3 — MODIFICATION STRICTEMENT PRÉSENTATIONNELLE. Ce sous-titre portait autrefois
      // `person.discipline || person.category`, c'est-à-dire une discipline OU la classe d'âge
      // (Adulte / Enfant, voire « Non-membre ») : le même emplacement visuel disait deux choses.
      // Un repli sur « Adhésion » a d'abord été essayé, puis écarté : une carte peut n'agréger
      // qu'une commande Boutique ou qu'une inscription de Stage, et le mot affirmait alors une
      // nature de créance que la ligne de détail juste en dessous démentait — sur un non-adhérent,
      // notamment. Il N'EXISTE aucun mot juste pour toutes les cartes, puisqu'une seule carte peut
      // agréger plusieurs modules. Le sous-titre ne porte donc plus QUE la discipline, et n'est pas
      // rendu du tout quand il n'y en a pas : la nature réelle de chaque créance est déjà nommée sur
      // sa propre ligne (« Boutique — … », « Stage — … », « Discipline — Disciplines »).
      // Aucun montant, aucun classement, aucune action, aucune donnée n'est touché.
      const category = asText(person.discipline);
      const itemRows = items.map((item) => {
        // Lot 2G-C1 — les TROIS types de créance (Stage, Boutique, Adhésion) exposent désormais le même
        // tiroir de paiement financier (registrationPaymentHtml / orderPaymentHtml / membershipPaymentHtml).
        // Cette surface n'ouvre plus aucune mutation structurelle : edit-membership n'y est plus routé (il
        // reste disponible dans les écrans métier — vue Disciplines, fiche contact — et dans l'agenda
        // « À encaisser », via allAlerts.editAction, inchangés). Le repli sur item.type inconnu est une
        // chaîne vide (défensif) : aucun bouton d'édition n'est produit ici.
        const usesDrawer = item.type === "registration" || item.type === "order" || item.type === "membership";
        const action = item.type === "registration"
          ? registrationPaymentHtml(item)
          : item.type === "order"
            ? orderPaymentHtml(item)
            : item.type === "membership"
              ? membershipPaymentHtml(item)
              : "";
        return `<div class="due-item ${usesDrawer ? "due-item-with-payments" : ""}">
          <div class="due-item-info">
            ${statusPill(item.status)}
            <span class="due-item-module">${esc(sourceLabel[item.type] || item.type)} — ${esc(item.module)}</span>
          </div>
          <strong class="due-item-amount">${money(item.amount)}</strong>
          ${action}
        </div>`;
      }).join("");
      return `<div class="due-card payment-${items[0]?.status === "Refusé" ? "late" : "due"}">
        <div class="due-card-head">
          <div class="due-card-identity">
            <strong>${esc(label)}</strong>
            ${category ? `<span class="muted">${esc(category)}</span>` : ""}
          </div>
          <div class="due-card-total">
            <span class="muted">Total dû</span>
            <strong class="due-amount">${money(total)}</strong>
          </div>
        </div>
        ${email || phone ? `<div class="due-card-contact">
          ${email ? (contactLinkForRow(person)
            ? `<button type="button" class="link-button" data-action="send-contact-email" data-contact-link="${esc(contactLinkForRow(person))}" title="Envoyer un mail à ce contact">${esc(email)}</button>`
            // Lot H-B — ligne fusionnée sans contact réellement résolvable (contactLinkForRow
            // échoue) : ouvre quand même le compositeur MonGestaClub à partir d'un contact minimal
            // (email + nom/prénom déjà connus ici), au lieu d'un mailto: brut qui ne garantirait
            // jamais le logo/la mise en page. Réutilise openContactEmailDialog (aucun second
            // éditeur e-mail) via la nouvelle action send-minimal-email — le contexte de paiement
            // déjà calculé ici (montant total dû, modules concernés) est transmis avec, pour que le
            // modèle « Relance » dispose des mêmes variables que sur un contact résolu.
            : `<button type="button" class="link-button" data-action="send-minimal-email" data-email="${esc(email)}" data-last-name="${esc(person.lastName || "")}" data-first-name="${esc(person.firstName || "")}" data-amount="${esc(money(total))}" data-module="${esc(items.map((item) => sourceLabel[item.type] || item.type).join(", "))}" data-detail="${esc(items.map((item) => `${sourceLabel[item.type] || item.type} — ${item.module}`).join(" · "))}" title="Envoyer un mail à ce contact">${esc(email)}</button>`) : ""}
          ${phone ? `<span>${esc(phone)}</span>` : ""}
        </div>` : ""}
        <div class="due-card-items">${itemRows}</div>
      </div>`;
    }).join("");

    return `<div class="band">
        <div class="band-title">
          <h2>Paiements dus</h2>
          <strong>${sorted.length} personne${sorted.length > 1 ? "s" : ""} — ${money(totalDue)}</strong>
        </div>
      </div>
      <div class="due-payments-grid">${cards}</div>`;
  }

  function renderView() {
    const protectionKey = viewProtectionKey(ui.view);
    if (protectionKey && !(ui.unlockedGroups && ui.unlockedGroups[protectionKey])) return renderLockedView(ui.view, protectionKey);
    if (ui.view === "tasks") return renderTasks();
    if (ui.view === "search") return renderSearch();
    if (ui.view === "contacts") return renderContacts();
    if (ui.view === "invoices") return renderInvoices();
    if (ui.view === "newsletter") return renderNewsletter();
    if (ui.view === "disciplines") return renderDisciplines();
    if (ui.view === "groups") return renderGroups();
    if (ui.view === "coaches") return renderCoaches();
    if (ui.view === "rooms") return renderRooms();
    if (ui.view === "planning") return renderPlanning();
    if (ui.view === "availability") return renderAvailability();
    if (ui.view === "attendance") return renderAttendance();
    if (ui.view === "documents") return renderSportDocuments();
    if (ui.view === "clubs") return renderClubs();
    if (ui.view === "club-settings") return renderClubSettings();
    if (ui.view === "boutique") return renderBoutique();
    if (ui.view === "stock") return renderStock();
    if (ui.view === "stages") return renderStages();
    if (ui.view === "stats") return renderStats();
    if (ui.view === "accounting") return renderAccounting();
    if (ui.view === "tarifs") return renderTarifs();
    if (ui.view === "due-payments") return renderDuePayments();
    if (ui.view === "notes") return renderNotes();
    if (ui.view === "history") return renderHistory();
    if (ui.view === "audit-log") return renderAuditLog();
    if (ui.view === "help") return renderHelp();
    if (ui.view === "assistant") return renderAssistant();
    if (ui.view === "settings") return renderSettings();
    return renderDashboard();
  }

  function kpis(items) {
    return gridItems(items.map((item) => {
      const content = `<span>${esc(item.label)}</span><strong>${esc(item.value)}</strong>`;
      if (!item.action) return `<div class="kpi">${content}</div>`;
      return `<button type="button" class="kpi kpi-link" data-action="${esc(item.action)}" ${item.scope ? `data-scope="${esc(item.scope)}"` : ""} ${item.stageId ? `data-stage-id="${esc(item.stageId)}"` : ""} title="${esc(item.title || "Voir les fiches concernées")}">${content}</button>`;
    }), 5, "kpi-grid");
  }

  function gridItems(items = [], maxColumns = 3, className = "") {
    const cards = items.filter(Boolean);
    if (!cards.length) return "";
    const columns = Math.min(Math.max(1, cards.length), Math.max(1, maxColumns));
    return `<div class="grid dynamic-grid ${className}" style="--dynamic-grid-columns:${columns}">${cards.join("")}</div>`;
  }

  function applyThemeOverrides() {
    const root = document.documentElement;
    // Axe "Disposition" indépendant du thème : modern (défaut) ou classic.
    root.dataset.layout = settings.layout === "classic" ? "classic" : "modern";
    const overrides = settings.themeColors?.[settings.theme] || {};
    for (const field of themeColorFields()) {
      if (isCssColor(overrides[field.key])) root.style.setProperty(field.css, overrides[field.key]);
      else root.style.removeProperty(field.css);
    }
    if (isCssColor(overrides.bg)) document.body.style.background = overrides.bg;
    else document.body.style.removeProperty("background");
  }

  function applyTypographySettings() {
    settings.typography = normalizeTypographySettings(settings.typography);
    const root = document.documentElement;
    root.style.setProperty("--font-body", settings.typography.bodyFont);
    root.style.setProperty("--font-title", settings.typography.titleFont);
    root.style.setProperty("--font-button", settings.typography.buttonFont);
    root.style.setProperty("--font-menu", settings.typography.menuFont);
    root.style.setProperty("--font-size-scale", fontSizeScale(settings.typography.fontSize));
    root.style.setProperty("--font-weight-base", settings.typography.fontWeight);
  }

  function postitDesignUrl(design) {
    const row = POSTIT_DESIGNS.find(([idValue]) => idValue === design) || POSTIT_DESIGNS[0];
    return row[2];
  }

  function postitStyleForTask(row = {}) {
    const key = row.postitType || "due";
    settings.postitStyles = normalizePostitStyles(settings.postitStyles);
    const style = settings.postitStyles[key] || settings.postitStyles.due;
    return `--postit-color:${esc(style.color)};--postit-image:url('${esc(postitDesignUrl(style.design))}')`;
  }

  function updatePostitStyleControl(target) {
    settings.postitStyles = normalizePostitStyles(settings.postitStyles);
    const key = target.dataset.postitStyle;
    const field = target.dataset.postitField;
    if (!settings.postitStyles[key] || !field) return false;
    recordHistory();
    settings.postitStyles[key][field] = target.value;
    settings.postitStyles = normalizePostitStyles(settings.postitStyles);
    const style = settings.postitStyles[key];
    const card = target.closest(".postit-style-card");
    if (card) {
      const postitImage = `url("${postitDesignUrl(style.design)}")`;
      card.style.setProperty("--postit-color", style.color);
      card.style.setProperty("--postit-image", postitImage);
      const preview = card.querySelector(".task-postit");
      if (preview) {
        preview.style.setProperty("--postit-color", style.color);
        preview.style.setProperty("--postit-image", postitImage);
      }
    }
    persistSettings();
    ui.saveMessage = "Post-it mis à jour";
    return true;
  }

  function overviewBand(idValue, title, items) {
    const open = Boolean(ui.overviewPanels?.[idValue]);
    return `<div class="band collapsible-band overview-band ${open ? "open" : ""}" data-overview-panel="${esc(idValue)}">
      <button type="button" class="band-title collapsible-title" data-action="toggle-overview-panel" data-panel="${esc(idValue)}" aria-expanded="${open ? "true" : "false"}">
        <h2>${esc(title)}</h2>
        <span class="collapsible-meta">${esc(open ? "Masquer" : "Afficher")}</span>
        <span class="collapsible-arrow">›</span>
      </button>
      <div class="collapsible-content">
        <div class="collapsible-inner overview-inner">${kpis(items)}</div>
      </div>
    </div>`;
  }

  function overviewDueRows(scope) {
    if (scope === "disciplines") {
      return state.memberships
        .filter((row) => includesQuery(row, ui.query))
        .filter((row) => !ui.discipline || row.discipline === ui.discipline)
        .map((row) => ({ row, calc: calcMembership(row) }))
        .filter((entry) => entry.calc.restDue > 0)
        .map(({ row, calc }) => ({
          module: row.discipline || "Disciplines",
          person: row,
          status: alertStatusForPayments(row.payments || []),
          amount: calc.restDue,
          editAction: "edit-membership",
          id: row.id,
        }));
    }
    if (scope === "boutique") {
      return state.shopOrders
        .filter((row) => includesQuery(row, ui.query))
        .map((row) => ({ row, calc: calcOrder(row) }))
        .filter((entry) => entry.calc.restDue > 0)
        .map(({ row, calc }) => ({
          module: "Boutique",
          person: row,
          status: alertStatusForPayments(row.payments || []),
          amount: calc.restDue,
          editAction: "view-order",
          id: row.id,
        }));
    }
    if (scope === "stages") {
      const stage = stageById(ui.stageId);
      return (state.stageRegistrations[stage.id] || [])
        .filter((row) => includesQuery(row, ui.query))
        .map((row) => ({ row, calc: calcRegistration(row, stage.id) }))
        .filter((entry) => entry.calc.restDue > 0)
        .map(({ row, calc }) => ({
          module: stage.name || "Stage",
          person: row,
          status: alertStatusForPayments([...(row.event?.payments || []), ...(row.lodging?.payments || [])]),
          amount: calc.restDue,
          editAction: "edit-registration",
          id: row.id,
          stageId: stage.id,
        }));
    }
    return [];
  }

  function openOverviewDueDialog(scope) {
    const rows = overviewDueRows(scope);
    const total = rows.reduce((sum, row) => sum + asNumber(row.amount), 0);
    const title = scope === "boutique" ? "Restes dus boutique" : scope === "stages" ? "Restes dus stage" : "Restes dus disciplines";
    const body = rows.length
      ? `<div class="dialog-table-wrap"><div class="dialog-table-scroll"><table>
          <thead><tr><th>Rubrique</th><th>Personne</th><th>Statut</th><th class="money">Reste dû</th><th></th></tr></thead>
          <tbody>${rows.map((row) => `<tr class="clickable-row" data-due-action="${esc(row.editAction)}" data-id="${esc(row.id)}" ${row.stageId ? `data-stage-id="${esc(row.stageId)}"` : ""}>
            <td>${esc(row.module)}</td>
            <td>${personCell(row.person)}</td>
            <td>${statusPill(row.status)}</td>
            <td class="money">${money(row.amount)}</td>
            <td><button class="icon" type="button" title="Ouvrir la fiche">✎</button></td>
          </tr>`).join("")}</tbody>
        </table></div></div>`
      : `<div class="empty">Aucun reste dû dans cette rubrique</div>`;
    showInfoDialog(title, `<div class="agenda-dialog">
      <div class="kpi"><span>Total reste dû</span><strong>${money(total)}</strong></div>
      ${body}
    </div>`);
    dialog.querySelectorAll("[data-due-action]").forEach((row) => {
      row.addEventListener("click", () => {
        const action = row.dataset.dueAction;
        const rowId = row.dataset.id;
        const stageId = row.dataset.stageId;
        dialog.close();
        if (action === "edit-membership") return openMembershipDialog(state.memberships.find((item) => item.id === rowId));
        if (action === "view-order") return openOrderForConsult(state.shopOrders.find((item) => item.id === rowId));
        if (action === "edit-registration") return openRegistrationDialog(stageId, state.stageRegistrations[stageId]?.find((item) => item.id === rowId));
      });
    });
  }

  // Libellé court de la saison active (à partir de Paramètres > Saison). Lecture seule.
  function dashboardSeasonLabel() {
    const season = (typeof normalizeSeasonSettings === "function") ? normalizeSeasonSettings(settings.season) : (settings.season || {});
    const start = asText(season.startDate), end = asText(season.endDate);
    if (start && end) {
      const y1 = start.slice(0, 4), y2 = end.slice(0, 4);
      return y1 === y2 ? `Saison ${y1}` : `Saison ${y1}–${y2}`;
    }
    if (start) return `Saison ${start.slice(0, 4)}`;
    if (end) return `Saison ${end.slice(0, 4)}`;
    return "Saison en cours";
  }

  // Carte d'alerte « À surveiller » : nombre + libellé, ton apaisé si 0. Cliquable (data-* fournis).
  // =========================================================================
  // CENTRE DE VIGILANCE (Lot 1 — interface).
  // N'invente aucun signal : il CONSOMME taskRows() (déjà calculé par les
  // modules) et regroupe par famille via taskFilterGroupOf(). Le Centre
  // affiche, hiérarchise et guide — il ne calcule rien.
  // =========================================================================
  // Chaque famille déclare : icône, destination (action ou vue), libellé COMPTEUR
  // (nom + pluriel) et CTA. Les TITRES sont formulés comme des actions, par niveau.
  function vigilanceFamilyConfig() {
    return {
      // Charte cartes : titre = FAMILLE (vigilanceFamilyLabel) · verbe = action attendue ·
      // button = verbe d'action du bouton · titles = libellés riches RÉSERVÉS aux résolveurs.
      // TEST DU PRÉSIDENT : chaque carte doit pouvoir se compléter par « Je dois… » (je dois
      // encaisser / régulariser les dossiers / trouver un remplaçant / réapprovisionner). Si la
      // phrase ne se lit pas naturellement, revoir le vocabulaire (verbe + bouton) de la famille.
      // RÈGLE ZÉRO AMBIGUÏTÉ : une carte ne doit jamais obliger le président à se poser une
      // question pour comprendre. « 703 € en attente » (en attente de quoi ?) → « 703 € à
      // encaisser » ; « 3 expirés » (quoi ?) → « 2 dossiers avec un document expiré ».
      payments:  { icon: getIconSvg("dashboard-payments-watch"), action: "show-payment-agenda", cta: "Voir les paiements", noun: ["paiement", "paiements"],
        verb: { red: "en retard", amber: "à encaisser" }, button: "Encaisser",
        titles: { red: "Paiements en retard", amber: "Paiements à suivre" } },
      documents: { icon: getIconSvg("dashboard-documents-check"), view: "documents", cta: "Voir les documents", noun: ["document concerné", "documents concernés"],
        verb: { red: "à régulariser", amber: "à renouveler" }, button: "Régulariser",
        titles: { red: "Documents à régulariser", amber: "Documents à renouveler" } },
      shop:      { icon: getIconSvg("dashboard-stock-low"), view: "stock", cta: "Voir le stock", noun: ["article", "articles"],
        verb: { red: "en rupture", amber: "à réapprovisionner" }, button: "Réapprovisionner",
        titles: { red: "Stock en rupture", amber: "Stock faible" } },
      planning:  { icon: getIconSvg("dashboard-planning-upcoming"), view: "planning", cta: "Ouvrir le planning", noun: ["créneau", "créneaux"],
        verb: { red: "en conflit", amber: "à surveiller" }, button: "Ouvrir le planning",
        titles: { red: "Conflits de planning", amber: "Créneaux à surveiller" } },
      coaches:   { icon: getIconSvg("dashboard-coach-check"), view: "planning", cta: "Ouvrir le planning", noun: ["séance", "séances"],
        verb: { red: "à remplacer", amber: "à confirmer" }, button: "Trouver un remplaçant",
        titles: { red: "Coachs à remplacer", amber: "Coachs à confirmer" } },
      rooms:     { icon: getIconSvg("dashboard-room-check"), view: "planning", cta: "Ouvrir le planning", noun: ["séance", "séances"],
        verb: { red: "à remplacer", amber: "à confirmer" }, button: "Trouver une salle",
        titles: { red: "Salles à remplacer", amber: "Salles à confirmer" } },
      misc:      { icon: getIconSvg("dashboard-group-watch"), view: "groups", cta: "Voir les groupes", noun: ["groupe", "groupes"],
        verb: { red: "complets", amber: "presque pleins" }, button: "Voir les groupes",
        titles: { red: "Groupes complets", amber: "Groupes presque pleins" } },
    };
  }

  // Navigation intelligente d'une carte qui regroupe PLUSIEURS alertes (count > 1) :
  // on ouvre le contexte de résolution filtré sur les seuls items concernés. Quand un
  // filtre exact existe dans le module (documents « bientôt », stock), on l'ouvre +
  // surbrillance ; sinon on ouvre « À faire » filtré sur la famille (liste précise, chaque
  // item gardant son action directe). Aucune logique par carte : tout est décrit ici.
  function vigilanceMultiIntentAttrs(fam, level, c) {
    const visible = (v) => typeof isViewVisible !== "function" || isViewVisible(v);
    if (c.action) return `data-action="${esc(c.action)}"`; // paiements → agenda d'encaissement (retards en tête)
    if (fam === "documents") {
      // Le compteur Documents regroupe des problèmes hétérogènes (manquants, expirés, à
      // renouveler, droit à l'image, règlement, assurances) que la page Documents ne sait
      // pas filtrer d'un seul tenant — son filtre « Expire bientôt » ne couvre que les
      // licences/certificats datés. On ouvre donc « À faire » filtré sur Documents : même
      // source que le compteur (taskRows) → la liste correspond toujours à ce qui est annoncé.
      return `data-action="vigilance-open" data-vig-tasks="documents"`;
    }
    if (fam === "shop") {
      if (visible("stock")) return `data-action="vigilance-open" data-vig-view="stock" data-vig-flash=".stock-warning, .stock-negative"`;
      return `data-action="vigilance-open" data-vig-tasks="shop"`;
    }
    if (fam === "misc") {
      if (visible("groups")) return `data-action="vigilance-open" data-vig-view="groups"`;
      return `data-action="vigilance-open" data-vig-tasks="misc"`;
    }
    // Lot Vigilance/Planning — même précédent que Stock ci-dessus : depuis le lot À faire V2
    // (fenêtre coachs/salles), taskRows() ne porte plus que les remplacements immédiats
    // (aujourd'hui/demain), donc « À faire » filtré peut afficher moins que ce que Vigilance/le
    // résolveur annoncent. Coachs/salles ont leur page naturelle (Planning), qui affiche déjà
    // chaque séance à remplacer avec la classe .course-replace (cf. courseReplacementInfoForDate) :
    // on y navigue directement avec surbrillance plutôt que de renvoyer vers À faire.
    if (fam === "coaches" || fam === "rooms") {
      if (visible("planning")) return `data-action="vigilance-open" data-vig-view="planning" data-vig-flash=".course-replace"`;
      return `data-action="vigilance-open" data-vig-tasks="${esc(fam)}"`;
    }
    // planning : « À faire » filtré sur la famille (liste ciblée, action par item)
    return `data-action="vigilance-open" data-vig-tasks="${esc(fam)}"`;
  }

  // Surbrillance temporaire et discrète des éléments concernés après navigation.
  function flashVigilanceTargets(selector) {
    if (!selector) return;
    setTimeout(() => {
      const els = [...app.querySelectorAll(selector)].slice(0, 25);
      els.forEach((el) => { el.classList.add("vigilance-flash"); setTimeout(() => el.classList.remove("vigilance-flash"), 2600); });
      if (els[0] && els[0].scrollIntoView) { try { els[0].scrollIntoView({ block: "center", behavior: "smooth" }); } catch (e) {} }
    }, 90);
  }

  // DOCUMENTS — unité = le DOSSIER (adhérent), pas le problème technique. On regroupe par
  // adhérent tous ses points à vérifier (licence, certificat, autorisation, droit image,
  // règlement, assurance) ; le niveau du dossier = le pire de ses points. Réutilise
  // getMissingDocuments() (déjà la source) + l'assurance. Aucune donnée nouvelle.
  function vigilanceDocGroups() {
    const map = new Map();
    const ensure = (m) => {
      const link = (typeof contactLinkForRow === "function" && contactLinkForRow(m)) || `name:${personKey(m)}`;
      if (!map.has(link)) map.set(link, { link, name: personLabel(m), membershipId: m.id, items: [] });
      return map.get(link);
    };
    (state.memberships || []).filter((m) => asText(m.discipline)).forEach((m) => {
      const issues = (typeof getMissingDocuments === "function") ? getMissingDocuments(m) : [];
      issues.forEach((issue) => ensure(m).items.push({ label: issue.label, tone: issue.level === "soon" ? "wait" : "late", expired: /expir/i.test(asText(issue.label)) }));
      if (!asText(m.insuranceChoice)) ensure(m).items.push({ label: "Assurance à vérifier", tone: "wait" });
    });
    return [...map.values()].filter((g) => g.items.length)
      .map((g) => ({ ...g, level: g.items.some((i) => i.tone === "late") ? "red" : "amber" }));
  }

  function vigilanceDocModel() {
    const groups = vigilanceDocGroups();
    const at = (lv) => groups.filter((g) => g.level === lv);
    const pts = (arr) => arr.reduce((n, g) => n + g.items.length, 0);
    // Levier conformité = nombre de DOSSIERS ayant au moins un document expiré (unité « dossiers »).
    const expiredDossiers = (arr) => arr.filter((g) => g.items.some((i) => i.expired)).length;
    return { red: { members: at("red").length, points: pts(at("red")), expired: expiredDossiers(at("red")) }, amber: { members: at("amber").length, points: pts(at("amber")), expired: expiredDossiers(at("amber")) } };
  }

  // Agrège les alertes de taskRows() par (famille, niveau). Le social (anniversaires,
  // tone "ok") est exclu ; les DOCUMENTS sont traités à part (par dossier, ci-dessus).
  // On retient les attrs de la 1re ligne : si UNE seule alerte, le clic ouvre directement
  // sa fiche / son dialogue exact (lien profond, réutilise l'action déjà fournie par le module).
  function vigilanceModel() {
    const rows = (typeof taskRows === "function") ? taskRows() : [];
    const cfg = vigilanceFamilyConfig();
    const groups = {};
    rows.forEach((row) => {
      if (row.tone === "ok") return;
      // Lot À faire V2 (factures en retard) — routées vers le groupe "payments" pour le filtre
      // À faire (cf. taskFilterGroupOf), mais volontairement exclues d'ici : Vigilance ne doit pas
      // gagner de nouvelle alerte pour ce lot (consigne explicite), et le montant de la facture
      // gonflerait sinon le total "€ à encaisser" des paiements sans qu'aucun de ces deux nombres
      // ne devienne cohérent avec l'autre (la ligne n'a pas de champ `amount`, contrairement aux
      // lignes de paiement source).
      if (asText(row.category).indexOf("Facture") === 0) return;
      const fam = (typeof taskFilterGroupOf === "function") ? taskFilterGroupOf(row) : "misc";
      // documents comptés par dossier ; coaches/rooms reconstruits indépendamment ci-dessous (comme
      // le stock "seuil bas") car taskRows() ne porte plus que les remplacements immédiats
      // (aujourd'hui/demain) depuis le lot À faire V2 fenêtre coachs/salles — Vigilance a besoin
      // d'une fenêtre plus large et ne doit pas les recompter une seconde fois depuis ici.
      if (!cfg[fam] || fam === "documents" || fam === "coaches" || fam === "rooms") return;
      const level = row.tone === "late" ? "red" : "amber";
      const key = `${fam}|${level}`;
      const g = groups[key] || (groups[key] = { count: 0, attrs: "", amount: 0, minDate: "", minAvail: null, minName: "", zero: 0 });
      g.count += 1;
      if (g.count === 1) g.attrs = row.attrs || "";
      // Données du qualificatif (levier de décision) : argent, temps, disponibilité.
      g.amount += asNumber(row.amount) || 0;
      if (row.nextDate && (!g.minDate || row.nextDate < g.minDate)) g.minDate = row.nextDate;
      if (row.available !== undefined && row.available !== null) {
        if (g.minAvail === null || row.available < g.minAvail) { g.minAvail = row.available; g.minName = row.title || ""; }
        if (asNumber(row.available) === 0) g.zero += 1;
      }
    });
    // Lot À faire V2 (micro-correctif) — le stock "seuil bas" (non rupture) est volontairement
    // sorti de taskRows()/« À faire », mais Vigilance doit continuer à le signaler en orange :
    // reconstruit group("shop|amber") directement depuis stockRows(), indépendamment de
    // taskRows(). Le stock RÉELLEMENT en rupture (available < 0) reste porté par taskRows()
    // ci-dessus, inchangé ; même forme de groupe donc mêmes destinations qu'avant ce correctif.
    if (isModuleEnabled("boutique") && hasFeature("shop")) {
      stockRows().filter((row) => row.available >= 0 && isStockLow(row)).forEach((row) => {
        const key = "shop|amber";
        const g = groups[key] || (groups[key] = { count: 0, attrs: "", amount: 0, minDate: "", minAvail: null, minName: "", zero: 0 });
        g.count += 1;
        if (g.count === 1) g.attrs = `data-action="edit-stock-article" data-index="${row.index}"`;
        if (g.minAvail === null || row.available < g.minAvail) { g.minAvail = row.available; g.minName = row.article.name || "Article"; }
        if (row.available === 0) g.zero += 1;
      });
    }
    // Lot À faire V2 (fenêtre coachs/salles) — même précédent que le stock ci-dessus : Vigilance
    // garde la fenêtre large (tous les remplacements pending, pas seulement aujourd'hui/demain),
    // reconstruite directement depuis pendingCoachReplacements()/pendingRoomReplacements() +
    // impactStillPendingForTasks (mêmes filtres "tâche fantôme" que taskRows(), sans le filtre de
    // date). Toujours "red" : aucune de ces deux familles n'a jamais produit de niveau "amber".
    const buildReplacementGroup = (fam, impacts, actionName) => {
      if (!impacts.length) return;
      const key = `${fam}|red`;
      const g = groups[key] || (groups[key] = { count: 0, attrs: "", amount: 0, minDate: "", minAvail: null, minName: "", zero: 0 });
      impacts.forEach((x) => {
        g.count += 1;
        if (g.count === 1) g.attrs = `data-action="${actionName}" data-course-id="${esc(x.course.id)}" data-ps="${esc(x.periodStart)}" data-pe="${esc(x.periodEnd)}"`;
        const nextDate = x.archived ? "" : (typeof impactFirstPendingDate === "function" ? impactFirstPendingDate(x) : "");
        if (nextDate && (!g.minDate || nextDate < g.minDate)) g.minDate = nextDate;
      });
    };
    if (typeof pendingCoachReplacements === "function") {
      buildReplacementGroup("coaches", pendingCoachReplacements().filter((x) => typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)), "replace-session");
    }
    if (typeof pendingRoomReplacements === "function") {
      buildReplacementGroup("rooms", pendingRoomReplacements().filter((x) => typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)), "replace-room-session");
    }
    const doc = vigilanceDocModel();
    const toCards = (level) => {
      const cards = Object.keys(groups)
        .filter((k) => k.endsWith(`|${level}`))
        // Lot Accueil V2 — évite le doublon « Paiements » rouge + orange : si l'urgence existe
        // déjà en rouge (retards/refus), ne pas répéter la famille en orange (même bouton
        // "Encaisser", même destination). Règle strictement limitée à cette famille : Documents/
        // Stock/Groupes gardent rouge et orange, qui y représentent des informations distinctes.
        .filter((k) => !(level === "amber" && k === "payments|amber" && groups["payments|red"]))
        .map((k) => {
          const fam = k.split("|")[0];
          const c = cfg[fam];
          const g = groups[k];
          // Principe de continuité — où mène le clic sans quitter inutilement l'Accueil :
          //   1 élément → ouverture directe ; 2 à 5 → fenêtre de résolution ; > 5 → page filtrée ;
          //   paiements → toujours l'agenda d'encaissement.
          let dest;
          if (g.count === 1 && g.attrs) dest = g.attrs;            // 1 → ouverture directe
          else if (c.action) dest = `data-action="${esc(c.action)}"`; // paiements → agenda
          else if (g.count <= 5) dest = `data-action="vigilance-resolve-open" data-fam="${esc(fam)}" data-level="${esc(level)}"`; // 2-5 → résolveur
          else dest = vigilanceMultiIntentAttrs(fam, level, c);     // > 5 → liste filtrée
          // Charte : titre = famille · verbe = action · qualificatif = levier de décision · bouton = action.
          let qualifier = "";
          if (fam === "payments" && g.amount > 0) qualifier = `${Math.round(g.amount).toLocaleString("fr-FR")} € ${level === "red" ? "à encaisser" : "en attente"}`;
          else if ((fam === "coaches" || fam === "rooms") && g.minDate) qualifier = `prochaine séance ${vigilanceRelativeDate(g.minDate)}`;
          else if (fam === "shop") qualifier = g.zero > 0 ? `${g.zero} article${g.zero > 1 ? "s" : ""} en rupture` : (g.minName ? `le plus bas : ${g.minName}` : "");
          return {
            fam, level, count: g.count, icon: c.icon, dest,
            title: vigilanceFamilyLabel(fam),
            countLabel: `${g.count} ${g.count > 1 ? c.noun[1] : c.noun[0]}`,
            verb: (c.verb && c.verb[level]) || "",
            qualifier,
            cta: c.button || c.cta,
          };
        });
      // Carte DOCUMENTS (unité = dossier) : « N dossiers concernés · M documents à compléter »,
      // clic → fenêtre de résolution locale (par dossier), même pour une longue liste.
      const dm = doc[level];
      if (dm.members > 0) {
        const c = cfg.documents;
        // Levier de décision = conformité : on met en avant les documents EXPIRÉS (risque
        // d'assurance), pas le volume « à compléter » (qui vit dans le résolveur).
        const qualifier = dm.expired > 0 ? `dont ${dm.expired} dossier${dm.expired > 1 ? "s" : ""} avec un document expiré` : "";
        cards.push({
          fam: "documents", level, count: dm.members, icon: c.icon,
          dest: `data-action="vigilance-doc-resolve-open" data-level="${esc(level)}"`,
          title: vigilanceFamilyLabel("documents"),
          countLabel: `${dm.members} dossier${dm.members > 1 ? "s" : ""}`,
          verb: (c.verb && c.verb[level]) || "",
          qualifier,
          cta: c.button,
        });
      }
      return cards.sort((a, b) => b.count - a.count);
    };
    const has = (fam, level) => Boolean(groups[`${fam}|${level}`]);
    // Le vert n'affirme que ce qui est RÉELLEMENT vrai (absence d'alerte sur la famille).
    const green = [];
    if (!has("payments", "red")) green.push("Aucun paiement en retard");
    if (!doc.red.members && !doc.amber.members) green.push("Tous les documents sont à jour");
    if (!has("planning", "red") && !has("coaches", "red") && !has("rooms", "red")) green.push("Aucun conflit de planning");
    if (isModuleEnabled("boutique") && hasFeature("shop") && !has("shop", "red") && !has("shop", "amber")) green.push("Stock au-dessus des seuils");
    return { red: toCards("red"), amber: toCards("amber"), green };
  }

  // Carte ACTION (pas un KPI) : titre = l'action, compteur = précision, lien = où agir.
  function vigilanceCardHtml(card) {
    // Charte : titre (famille) → chiffre clé → verbe métier → qualificatif (facultatif) → bouton.
    const verb = card.verb ? `<span class="vigilance-card-verb">${esc(card.verb)}</span>` : "";
    const qualifier = card.qualifier ? `<span class="vigilance-card-qualifier">${esc(card.qualifier)}</span>` : "";
    const tip = [card.title, card.countLabel, card.verb, card.qualifier].filter(Boolean).join(" · ");
    // Lot Accueil V2 — une seule action par carte : la carte n'est plus un bouton (elle informe),
    // seul le CTA porte data-action/data-view (elle agit). Aucune destination ni donnée changée,
    // uniquement l'élément qui les porte.
    return `<div class="vigilance-card vigilance-${esc(card.level)}" title="${esc(tip)}">
      <span class="vigilance-card-head"><span class="vigilance-card-icon" aria-hidden="true">${card.icon}</span><strong class="vigilance-card-title">${esc(card.title)}</strong></span>
      <span class="vigilance-card-count">${esc(card.countLabel)}</span>
      ${verb}${qualifier}
      <button type="button" class="vigilance-card-cta" ${card.dest}>${esc(card.cta)} →</button>
    </div>`;
  }

  // Une section (rouge ou jaune) : max 5 cartes, surplus regroupé vers « À faire ».
  function vigilanceSectionHtml(cards, level) {
    if (!cards.length) return "";
    const shown = cards.slice(0, 5);
    const extra = cards.length - shown.length;
    const overflow = extra > 0
      ? `<div class="vigilance-card vigilance-more" title="Voir toutes les alertes dans À faire">
          <span class="vigilance-card-head"><span class="vigilance-card-icon" aria-hidden="true">${getIconSvg("dashboard-alert-action")}</span><strong class="vigilance-card-title">Autres points</strong></span>
          <span class="vigilance-card-count">${extra} de plus</span>
          <button type="button" class="vigilance-card-cta" data-view="tasks">Tout voir dans « À faire » →</button></div>`
      : "";
    const heading = level === "red" ? "🔴 À traiter" : "🟠 À surveiller";
    return `<div class="band vigilance-band">
      <div class="band-title"><h2>${heading}</h2><strong>${cards.length}</strong></div>
      <div class="vigilance-grid">${shown.map(vigilanceCardHtml).join("")}${overflow}</div>
    </div>`;
  }

  // Confirmation visuelle : mémorise les familles ayant une alerte au rendu précédent ;
  // celles qui passent à zéro affichent brièvement une carte « ✓ réglé » avant disparition.
  let vigilanceShownFamilies = new Set();
  const vigilanceFlash = new Map(); // famille → instant d'expiration
  let vigilanceFlashTimer = null;
  const VIGILANCE_CONFIRM_MS = 3200;

  // Libellé de famille neutre (carte de confirmation) : « ✓ Stock » plutôt que
  // « ✓ Stock en rupture » (un ✓ devant un intitulé de problème sonnerait contradictoire).
  function vigilanceFamilyLabel(fam) {
    return { payments: "Paiements", documents: "Documents", planning: "Planning", coaches: "Coachs", rooms: "Salles", shop: "Stock", misc: "Groupes" }[fam] || "Vigilance";
  }

  function vigilanceConfirmCardHtml(fam) {
    return `<div class="vigilance-card vigilance-confirm">
      <span class="vigilance-card-head"><span class="vigilance-card-icon" aria-hidden="true">✓</span><strong class="vigilance-card-title">${esc(vigilanceFamilyLabel(fam))}</strong></span>
      <span class="vigilance-card-count">${esc(vigilanceDoneMessage(fam))}</span>
    </div>`;
  }

  // Programme la disparition douce des cartes de confirmation (fondu puis re-rendu).
  function vigilanceScheduleConfirmCleanup() {
    clearTimeout(vigilanceFlashTimer);
    if (!vigilanceFlash.size) return;
    const soonest = Math.min(...[...vigilanceFlash.values()]);
    vigilanceFlashTimer = setTimeout(() => {
      const cards = [...document.querySelectorAll(".vigilance-confirm")];
      cards.forEach((c) => c.classList.add("is-leaving"));
      setTimeout(() => { if (typeof render === "function") render(); }, cards.length ? 340 : 0);
    }, Math.max(0, soonest - Date.now()));
  }

  function vigilanceBlockHtml() {
    const model = vigilanceModel();
    const level = model.red.length ? "red" : model.amber.length ? "amber" : "green";
    const emoji = level === "red" ? "🔴" : level === "amber" ? "🟠" : "🟢";
    const stateText = level === "red" ? "Plusieurs sujets nécessitent votre attention."
      : level === "amber" ? "Quelques points méritent votre attention."
        : "Votre club est serein aujourd'hui.";
    const banner = `<div class="band vigilance-state vigilance-state-${level}">
      <span class="vigilance-state-emoji" aria-hidden="true">${emoji}</span>
      <div class="vigilance-state-text"><h2>🛡️ Vigilance</h2><p>${esc(stateText)} <span class="muted">MonGestaClub veille sur votre club.</span></p></div>
    </div>`;

    // --- Confirmation visuelle (transition d'une famille vers zéro alerte) ---
    const now = Date.now();
    const activeFamilies = new Set([...model.red, ...model.amber].map((c) => c.fam));
    vigilanceShownFamilies.forEach((fam) => { if (!activeFamilies.has(fam) && !vigilanceFlash.has(fam)) vigilanceFlash.set(fam, now + VIGILANCE_CONFIRM_MS); });
    [...vigilanceFlash.keys()].forEach((fam) => { if (vigilanceFlash.get(fam) <= now || activeFamilies.has(fam)) vigilanceFlash.delete(fam); });
    const confirmCards = [...vigilanceFlash.keys()].map(vigilanceConfirmCardHtml).join("");
    const confirmBlock = confirmCards ? `<div class="band vigilance-band vigilance-confirm-band"><div class="vigilance-grid">${confirmCards}</div></div>` : "";
    vigilanceShownFamilies = activeFamilies;
    vigilanceScheduleConfirmCleanup();

    // Le vert rassure : les vérifications vraies + la veille continue (toujours vraie),
    // sans laisser croire à un contrôle lancé à l'ouverture.
    const greenItems = [...model.green, "MonGestaClub veille sur votre club"];
    const greenIcon = `<span class="vigilance-green-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="currentColor"/><path d="M7.5 12.4l3 3 6-6.4" stroke="#fff" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`;
    const greenBlock = `<div class="band vigilance-band vigilance-green-band">
      <div class="band-title"><h2>${greenIcon} En ordre</h2></div>
      <ul class="vigilance-green">${greenItems.map((g) => `<li>${esc(g)}</li>`).join("")}</ul>
    </div>`;
    // Emplacement réservé pour le futur widget « Aujourd'hui dans votre club » (Lot ultérieur).
    const todaySlot = `<div class="vigilance-today-slot" data-vigilance-today hidden></div>`;
    return `<section class="vigilance">${banner}${confirmBlock}${vigilanceSectionHtml(model.red, "red")}${vigilanceSectionHtml(model.amber, "amber")}${greenBlock}${todaySlot}</section>`;
  }

  // --- Principe de continuité : fenêtre de résolution (2 à 5 éléments) ----------------
  // Liste les éléments concernés d'une famille ; chaque bouton ouvre le dialogue de
  // résolution EXISTANT (réutilise l'action de la ligne taskRows). Après résolution, la
  // fenêtre se met à jour toute seule (refreshOpenVigilanceResolver, branchée sur le flux
  // de sauvegarde de showDialog) — le président ne quitte jamais son Accueil.
  function vigilanceResolverRows(fam, level) {
    // Lot À faire V2 (micro-correctif) — le stock "seuil bas" (amber) n'est plus dans taskRows()
    // (retiré de « À faire »), donc reconstruit ici depuis stockRows() pour que le résolveur
    // Vigilance (2 à 5 articles) reste fonctionnel. Le stock en rupture (red) reste inchangé,
    // toujours porté par taskRows().
    if (fam === "shop" && level === "amber") {
      return stockRows().filter((row) => row.available >= 0 && isStockLow(row)).map((row) => ({
        title: row.article.name || "Article",
        detail: `${intValue(row.available)} disponible · seuil ${intValue(row.article.stockAlert || 0)}`,
        attrs: `data-action="edit-stock-article" data-index="${row.index}"`,
      }));
    }
    // Lot À faire V2 (fenêtre coachs/salles) — même précédent que le stock ci-dessus : coaches/rooms
    // ne sont plus dans taskRows() au-delà d'aujourd'hui/demain, donc reconstruits ici depuis
    // pendingCoachReplacements()/pendingRoomReplacements() pour que le résolveur Vigilance (2 à 5
    // éléments) continue de lister tous les remplacements pending, comme avant ce lot.
    if (fam === "coaches" && typeof pendingCoachReplacements === "function") {
      return pendingCoachReplacements().filter((x) => typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)).map((x) => ({
        title: `${x.course.name} · ${coachFullName(x.coach)}`,
        detail: `${x.course.day || "?"} ${x.course.startTime || ""}`,
        attrs: `data-action="replace-session" data-course-id="${esc(x.course.id)}" data-ps="${esc(x.periodStart)}" data-pe="${esc(x.periodEnd)}"`,
      }));
    }
    if (fam === "rooms" && typeof pendingRoomReplacements === "function") {
      return pendingRoomReplacements().filter((x) => typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)).map((x) => ({
        title: `${x.course.name} · ${roomName(x.room)}`,
        detail: `${x.course.day || "?"} ${x.course.startTime || ""}`,
        attrs: `data-action="replace-room-session" data-course-id="${esc(x.course.id)}" data-ps="${esc(x.periodStart)}" data-pe="${esc(x.periodEnd)}"`,
      }));
    }
    return (typeof taskRows === "function" ? taskRows() : []).filter((row) => {
      if (row.tone === "ok") return false;
      const f = (typeof taskFilterGroupOf === "function") ? taskFilterGroupOf(row) : "misc";
      const lv = row.tone === "late" ? "red" : "amber";
      return f === fam && lv === level;
    });
  }

  function vigilanceResolverCta(fam) {
    return { coaches: "Remplacer", rooms: "Remplacer", documents: "Régulariser", shop: "Réapprovisionner", payments: "Encaisser" }[fam] || "Ouvrir";
  }

  // Icône de famille pour un en-tête de dialogue. Depuis le Lot B, c.icon est un SVG
  // inline (HTML contrôlé) : il doit être INJECTÉ tel quel dans un span, jamais échappé.
  function vigilanceFamilyIcon(fam) {
    const c = vigilanceFamilyConfig()[fam];
    return (c && c.icon) || "🛡️";
  }

  // Texte du titre (sans l'icône) : toujours échappable. L'icône est rendue à part.
  function vigilanceResolverTitle(fam, level, count) {
    const c = vigilanceFamilyConfig()[fam] || { titles: {}, noun: ["élément", "éléments"] };
    const t = (c.titles && (c.titles[level] || c.titles.red)) || "Vigilance";
    return `${t} — ${count} ${count > 1 ? c.noun[1] : c.noun[0]}`;
  }

  // En-tête de dialogue de vigilance : icône (HTML contrôlé) + titre (texte échappé).
  function vigilanceDialogTitleHtml(fam, titleText) {
    return `<h2 class="vigilance-dialog-title"><span class="vigilance-dialog-ico" aria-hidden="true">${vigilanceFamilyIcon(fam)}</span><span class="vigilance-dialog-text">${esc(titleText)}</span></h2>`;
  }

  function vigilanceResolverListHtml(rows, fam) {
    const cta = vigilanceResolverCta(fam);
    return rows.map((row) => `<div class="vigilance-resolve-item">
        <div class="vigilance-resolve-info"><strong>${esc(row.title || "")}</strong>${row.detail ? `<span class="muted">${esc(row.detail)}</span>` : ""}</div>
        <button type="button" class="primary vigilance-resolve-btn" ${row.attrs || ""}>${esc(cta)}</button>
      </div>`).join("");
  }

  function vigilanceDoneMessage(fam) {
    return {
      coaches: "Tous les coachs ont été remplacés.",
      rooms: "Toutes les salles ont été réglées.",
      documents: "Tous les documents sont à jour.",
      shop: "Tout le stock est réapprovisionné.",
      misc: "Tous les groupes sont réglés.",
    }[fam] || "Tous les éléments sont traités.";
  }

  // Corps de la fenêtre : progression (total de départ + restant) + liste. Réutilisé à
  // l'ouverture ET à chaque rafraîchissement, pour que le compteur diminue visiblement.
  function vigilanceResolverBodyHtml(fam, level, initial, rows) {
    const c = vigilanceFamilyConfig()[fam] || { noun: ["élément", "éléments"] };
    const progress = `<p class="vigilance-resolve-progress"><strong>${initial} ${initial > 1 ? c.noun[1] : c.noun[0]} à traiter</strong><span class="muted">Il en reste ${rows.length}.</span></p>`;
    return progress + `<div class="vigilance-resolve-rows">${vigilanceResolverListHtml(rows, fam)}</div>`;
  }

  // Construit un bouton détaché à partir des attrs d'une ligne pour rejouer son action.
  function vigilanceButtonFromAttrs(attrs) {
    const b = document.createElement("button");
    String(attrs || "").replace(/data-([a-z-]+)="([^"]*)"/g, (_, k, v) => { b.dataset[k.replace(/-([a-z])/g, (m, ch) => ch.toUpperCase())] = v; return ""; });
    return b;
  }

  function openVigilanceResolver(fam, level) {
    const rows = vigilanceResolverRows(fam, level);
    if (!rows.length) return;
    if (rows.length === 1 && rows[0].attrs) { handleAction(vigilanceButtonFromAttrs(rows[0].attrs)); return; }
    const initial = rows.length;
    const allAttrs = vigilanceMultiIntentAttrs(fam, level, vigilanceFamilyConfig()[fam]); // « Tout traiter » → liste complète
    dialog.innerHTML = `<form class="vigilance-resolver-form">
      <div class="dialog-header">${vigilanceDialogTitleHtml(fam, vigilanceResolverTitle(fam, level, rows.length))}<button class="icon" type="button" data-dialog-close aria-label="Fermer">×</button></div>
      <div class="dialog-body"><div class="vigilance-resolve-list" data-vigilance-resolver data-fam="${esc(fam)}" data-level="${esc(level)}" data-initial="${initial}">${vigilanceResolverBodyHtml(fam, level, initial, rows)}</div></div>
      <div class="dialog-footer">
        <button type="button" class="link-button vigilance-resolve-all" ${allAttrs} data-dialog-close>Tout traiter dans la liste complète</button>
        <div class="dialog-footer-actions"><button type="button" data-dialog-close>Fermer</button></div>
      </div>
    </form>`;
    dialog.querySelectorAll("[data-dialog-close]").forEach((b) => b.addEventListener("click", () => dialog.close()));
    showFloatingDialog(dialog, ".vigilance-resolve-btn");
  }

  // Rafraîchit, sans la fermer, la fenêtre de résolution après chaque résolution (même flux
  // que refreshOpenDossierDialog). Le compteur diminue ; au dernier élément, message positif
  // puis fermeture automatique après un court délai.
  function refreshOpenVigilanceResolver() {
    document.querySelectorAll("dialog[open] [data-vigilance-resolver]").forEach((el) => {
      if (el.dataset.done === "1") return; // déjà en écran de fin
      const fam = el.dataset.fam, level = el.dataset.level;
      const initial = Number(el.dataset.initial) || 0;
      const rows = vigilanceResolverRows(fam, level);
      const dlg = el.closest("dialog");
      if (!rows.length) {
        el.dataset.done = "1";
        el.innerHTML = `<p class="vigilance-resolve-done">✓ ${esc(vigilanceDoneMessage(fam))}</p>`;
        const h2 = dlg?.querySelector(".dialog-header h2");
        if (h2) h2.textContent = "✓ Terminé";
        setTimeout(() => { if (dlg && dlg.open) dlg.close(); }, 1700);
        return;
      }
      el.innerHTML = vigilanceResolverBodyHtml(fam, level, initial, rows);
      const h2 = dlg?.querySelector(".dialog-header h2");
      if (h2) h2.textContent = vigilanceResolverTitle(fam, level, rows.length);
    });
    // Fenêtre de résolution DOCUMENTS (par dossier) : même cycle (compteur → fin → fermeture).
    document.querySelectorAll("dialog[open] [data-vigilance-doc-resolver]").forEach((el) => {
      if (el.dataset.done === "1") return;
      const level = el.dataset.level;
      const groups = vigilanceDocGroups().filter((g) => g.level === level);
      const dlg = el.closest("dialog");
      if (!groups.length) {
        el.dataset.done = "1";
        el.innerHTML = `<p class="vigilance-resolve-done">✓ Tous les documents sont à jour.</p>`;
        const h2 = dlg?.querySelector(".dialog-header h2");
        if (h2) h2.textContent = "✓ Terminé";
        setTimeout(() => { if (dlg && dlg.open) dlg.close(); }, 1700);
        return;
      }
      el.innerHTML = vigilanceDocResolverBodyHtml(level, groups);
    });
  }

  // Corps de la fenêtre Documents : progression (dossiers + points) + liste par adhérent.
  function vigilanceDocResolverBodyHtml(level, groups) {
    const points = groups.reduce((n, g) => n + g.items.length, 0);
    const progress = `<p class="vigilance-resolve-progress"><strong>${groups.length} dossier${groups.length > 1 ? "s" : ""} concerné${groups.length > 1 ? "s" : ""}</strong><span class="muted">${points} document${points > 1 ? "s" : ""} à compléter</span></p>`;
    const list = groups.map((g) => `<div class="vigilance-resolve-item">
        <div class="vigilance-resolve-info"><strong>${esc(g.name)}</strong><span class="muted">${esc(g.items.map((i) => i.label).join(" · "))}</span></div>
        <button type="button" class="primary vigilance-resolve-btn" data-action="edit-membership" data-id="${esc(g.membershipId)}">Régulariser</button>
      </div>`).join("");
    return progress + `<div class="vigilance-resolve-rows">${list}</div>`;
  }

  function openVigilanceDocResolver(level) {
    const groups = vigilanceDocGroups().filter((g) => g.level === level);
    if (!groups.length) return;
    if (groups.length === 1) { handleAction(vigilanceButtonFromAttrs(`data-action="edit-membership" data-id="${groups[0].membershipId}"`)); return; }
    const c = vigilanceFamilyConfig().documents;
    const title = level === "red" ? c.titles.red : c.titles.amber;
    // Lot Vigilance/Documents orange — depuis le lot À faire V2, « À faire » ne compte plus les
    // documents "soon" (taskRows filtré) ; y renvoyer pour le niveau amber noie le seul document
    // effectivement affiché (rendu via dossierDocumentGroups, non filtré) parmi les dossiers rouges
    // sans rapport, et ne représente jamais le cas assurance seule (angle mort connu, non traité
    // ici). La page Documents a déjà un filtre "bientôt" dédié (licence/certificat) : on y navigue
    // directement pour amber, sans toucher au cas red (inchangé, toujours vers À faire). Même
    // prudence que Stock/Coachs/Salles : si la page Documents est masquée de la navigation de ce
    // club (menu personnalisé), on garde le repli existant vers À faire plutôt qu'une destination
    // invisible (isViewVisible redirige silencieusement vers l'accueil si la vue n'est pas visible).
    const docViewVisible = typeof isViewVisible !== "function" || isViewVisible("documents");
    const allAttrs = level === "amber" && docViewVisible
      ? `data-action="vigilance-open" data-vig-view="documents" data-vig-doc-filter="soon"`
      : `data-action="vigilance-open" data-vig-tasks="documents"`;
    dialog.innerHTML = `<form class="vigilance-resolver-form">
      <div class="dialog-header">${vigilanceDialogTitleHtml("documents", title)}<button class="icon" type="button" data-dialog-close aria-label="Fermer">×</button></div>
      <div class="dialog-body"><div class="vigilance-resolve-list vigilance-doc-list" data-vigilance-doc-resolver data-level="${esc(level)}">${vigilanceDocResolverBodyHtml(level, groups)}</div></div>
      <div class="dialog-footer">
        <button type="button" class="link-button vigilance-resolve-all" ${allAttrs} data-dialog-close>Tout traiter dans la liste complète</button>
        <div class="dialog-footer-actions"><button type="button" data-dialog-close>Fermer</button></div>
      </div>
    </form>`;
    dialog.querySelectorAll("[data-dialog-close]").forEach((b) => b.addEventListener("click", () => dialog.close()));
    showFloatingDialog(dialog, ".vigilance-resolve-btn");
  }

  function renderDashboard() {
    const stats = dashboardStats();
    // Module pilote Boutique (Lot 2B) : les KPI et raccourcis OPÉRATIONNELS Boutique de l'accueil
    // suivent l'affichage isModuleEnabled("boutique") ET la fonctionnalité hasFeature("shop"). Les
    // TOTAUX de dashboardStats (CA global) restent, eux, un CALCUL HISTORIQUE INCONDITIONNEL :
    // masquer ou désactiver la Boutique ne retire jamais ses ventes existantes des totaux — seuls
    // ces indicateurs/raccourcis actionnables disparaissent avec le module.
    const boutiqueEnabled = isModuleEnabled("boutique") && hasFeature("shop");
    // Module pilote Stages (Lot 2D) : KPI et raccourcis OPÉRATIONNELS Stages suivent l'affichage
    // isModuleEnabled("stages") ET la fonctionnalité hasFeature("stages"). Les CALCULS restent inconditionnels.
    const stagesEnabled = isModuleEnabled("stages") && hasFeature("stages");
    const today = todayInputValue();
    const memberCount = state.contacts.members.length;
    const invoicesPending = (state.invoices || [])
      .filter((invoice) => invoiceBelongsToActiveClub(invoice) && ["issued", "partial"].includes(computedInvoiceStatus(invoice)))
      .length;
    const upcomingStages = stagesEnabled
      ? state.tariffs.stages.filter((stage) => { const d = dateInputValue(stage.startDate); return d && d >= today; }).length
      : 0;
    const agenda = paymentAgendaRows(null);
    const lateCount = agenda.filter((row) => (row.date && row.date < today) || row.status === "Refusé").length;
    const ds = (typeof getDashboardStats === "function") ? getDashboardStats() : { certMissing: 0, certSoon: 0, licSoon: 0 };
    const certMissing = asNumber(ds.certMissing);
    const lowStock = boutiqueEnabled ? stockRows().filter(isStockLow).length : 0;
    const upcomingDocs = asNumber(ds.certSoon) + asNumber(ds.licSoon);
    const clubName = (typeof activeClub === "function" && activeClub() && activeClub().name) || settings.clubName || "MonGestaClub";
    const allCalm = lateCount === 0 && certMissing === 0 && lowStock === 0 && upcomingDocs === 0;
    // Club tout neuf (premier démarrage) : aucun adhérent ni facture. On oriente plutôt
    // que d'afficher « tout est à jour » (trompeur quand il n'y a encore rien).
    const clubIsEmpty = memberCount === 0 && invoicesPending === 0 && !(stagesEnabled && hasStageData());
    const welcomeMsg = clubIsEmpty
      ? "Bienvenue ! Votre club est prêt. Commencez par vos disciplines et vos adhérents, puis construisez vos groupes et votre planning."
      : allCalm
        ? "Tout est à jour. Vous avez le club bien en main 👍"
        : "Voici l'essentiel de votre club. Quelques points demandent votre attention ci-dessous.";

    // Indicateurs principaux (5).
    const kpiItems = [
      { label: "Adhérents", value: intValue(memberCount) },
      { label: "Encaissé saison", value: money(stats.paid) },
      { label: "Restant à encaisser", value: money(stats.restDue) },
      { label: "Factures en attente", value: intValue(invoicesPending) },
    ];
    // KPI optionnel : affiché seulement si le module Stages est activé ET qu'il existe des données
    // de stages (helper existant hasStageData) — évite un « Stages à venir : 0 » pour un club qui
    // n'utilise pas les stages. L'action « Créer un stage » reste, elle, toujours disponible.
    if (stagesEnabled && hasStageData()) kpiItems.push({ label: "Stages à venir", value: intValue(upcomingStages) });

    // Actions rapides (dialogues = toujours sûrs ; navigation pour Boutique/Factures).
    // Club tout neuf : on propose la mise en route (disciplines/tarifs + premiers pas guidés)
    // plutôt que des actions prématurées (encaisser, facturer).
    // Chaque raccourci suit désormais isViewVisible() — le MÊME prédicat que le menu de
    // navigation (mode simple/avancé/personnalisé + drapeau fonctionnel Stages/Boutique) —
    // pour éviter qu'un raccourci reste affiché ici alors que son menu correspondant est
    // masqué dans Paramètres > Affichage (cf. correctif déjà appliqué au bas de fiche contact).
    const quickActions = clubIsEmpty
      ? [
          // Club tout neuf : « Ajouter un adhérent » ouvre une fiche contact simple (add-contact),
          // et non une inscription (add-membership) qui exigerait une discipline encore inexistante
          // — sinon impasse dès la première action. Cohérent avec l'étape assistant « premier
          // adhérent » qui utilise déjà add-contact. L'inscription à une discipline reste accessible
          // ensuite depuis la fiche contact. La branche « club configuré » ci-dessous garde
          // add-membership (une discipline existe alors, pas d'impasse).
          isViewVisible("contacts") ? `<button class="primary" data-action="add-contact">Ajouter un adhérent</button>` : "",
          isViewVisible("disciplines") ? `<button data-view="disciplines">Mes disciplines &amp; tarifs</button>` : "",
          isViewVisible("assistant") ? `<button data-action="open-dashboard-target" data-target="assistant">Premiers pas guidés</button>` : "",
        ].filter(Boolean).join("")
      : [
          isViewVisible("disciplines") ? `<button class="primary" data-action="add-membership">Ajouter un adhérent</button>` : "",
          isViewVisible("invoices") ? `<button data-action="new-invoice">Créer une facture</button>` : "",
          isViewVisible("due-payments") ? `<button data-action="show-payment-agenda">Encaisser un paiement</button>` : "",
          isViewVisible("stages") ? `<button data-action="add-stage">Créer un stage</button>` : "",
          isViewVisible("boutique") ? `<button data-view="boutique">Accéder à la boutique</button>` : "",
        ].filter(Boolean).join("");

    return `
      <div class="cockpit-hero">
        <div class="home-welcome" style="display:flex;gap:16px;align-items:center">
          <img src="${esc(appLogoSrc())}" alt="" style="width:64px;height:64px;border-radius:14px;object-fit:contain;background:rgba(255,255,255,.16);padding:6px;flex:none" />
          <div>
            <span>${esc(dashboardSeasonLabel())}</span>
            <h2>Bienvenue · ${esc(clubName)}</h2>
            <p>${esc(welcomeMsg)}</p>
          </div>
        </div>
        <div class="quick-actions">${quickActions}</div>
      </div>
      ${vigilanceBlockHtml()}
      ${typeof assistantTodayCardHtml === "function" ? assistantTodayCardHtml() : ""}
      ${kpis(kpiItems)}
    `;
  }

  function paymentAgendaRows(limit = null) {
    const rows = [];
    const push = (payments, module, person, amount, editAction, id, stageId = "") => {
      const pending = (payments || [])
        .map((payment) => ({ payment, status: paymentStatus(payment) }))
        .filter((row) => row.status && row.status !== "OK" && asNumber(row.payment?.amount) > 0);
      if (!pending.length && amount <= 0) return;
      const priority = ["Refusé", "A encaisser", "En cours"];
      const mainStatus = priority.find((status) => pending.some((row) => row.status === status)) || (pending.length ? pending[0].status : "Reste dû");
      const mainRows = pending.filter((row) => row.status === mainStatus);
      const mainAmount = mainRows.reduce((sum, row) => sum + asNumber(row.payment?.amount), 0);
      const scheduledAmount = pending
        .filter((row) => row.status === "En cours" && row.status !== mainStatus)
        .reduce((sum, row) => sum + asNumber(row.payment?.amount), 0);
      const first = mainRows
        .slice()
        .sort((a, b) => (dateInputValue(a.payment?.date || "") || "9999-99-99").localeCompare(dateInputValue(b.payment?.date || "") || "9999-99-99"))[0] || pending[0] || {};
      rows.push({
        module,
        person,
        amount: mainAmount || amount,
        scheduledAmount,
        status: mainStatus || "Reste dû",
        date: dateInputValue(first.payment?.date || ""),
        payment: first.payment || {},
        editAction,
        id,
        stageId,
      });
    };
    for (const membership of state.memberships) {
      const calc = calcMembership(membership);
      push(membership.payments, "Discipline", membership, calc.restDue, "edit-membership", membership.id);
    }
    if (isModuleEnabled("boutique") && hasFeature("shop")) {
      for (const order of state.shopOrders) {
        const calc = calcOrder(order);
        push(order.payments, "Boutique", order, calc.restDue, "view-order", order.id);
      }
    }
    // Lot 2D — liste actionnable « reste dû » (mène à edit-registration, une mutation) : suit
    // l'affichage ET la fonctionnalité, comme Boutique. Les totaux/CA restent inconditionnels ailleurs.
    if (isModuleEnabled("stages") && hasFeature("stages")) {
      for (const stage of state.tariffs.stages) {
        for (const registration of state.stageRegistrations[stage.id] || []) {
          const calc = calcRegistration(registration, stage.id);
          const payments = [...(registration.event?.payments || []), ...(registration.lodging?.payments || [])];
          push(payments, stage.name || "Stage", registration, calc.restDue, "edit-registration", registration.id, stage.id);
        }
      }
    }
    return rows
      .filter((row) => row.amount > 0)
      .sort((a, b) => (a.date || "9999-99-99").localeCompare(b.date || "9999-99-99") || b.amount - a.amount)
      .slice(0, limit || undefined);
  }

  // C2c-c : une alerte « coach/salle à remplacer » de la page À faire est-elle ENCORE pertinente ?
  // Reste-t-il au moins une occurrence réellement problématique dans la période de l'impact ?
  // On réutilise la logique par date de C2c-b (impactCoversDate + annulation prioritaire) : une
  // occurrence est neutralisée si la séance est annulée ce jour-là (planningExceptions) ou si le
  // coach/salle a été remplacé ponctuellement pour cette date (override → impactCoversDate=false).
  // Coach/salle ARCHIVÉ : pas de période → toujours pending (on garde). Ce filtre n'agit QUE sur les
  // lignes de taskRows ; il ne touche ni pendingCoachReplacements/pendingRoomReplacements ni les
  // compteurs (coachPendingReplacementCount…) ni les stats.
  function impactStillPendingForTasks(impact) {
    if (!impact) return false;
    if (impact.archived) return true; // archivage : ce n'est pas une indisponibilité ponctuelle
    const course = impact.course;
    const start = parseDate(impact.periodStart);
    const end = parseDate(impact.periodEnd || impact.periodStart) || start;
    if (!course || !start) return true; // pas de période exploitable → comportement d'origine
    const target = COACH_DAYS.indexOf(asText(course.day));
    if (target < 0) return true;
    const cur = new Date(start); cur.setHours(0, 0, 0, 0);
    const last = new Date(end); last.setHours(0, 0, 0, 0);
    for (let i = 0; i < 400 && cur <= last; i += 1, cur.setDate(cur.getDate() + 1)) {
      if (((cur.getDay() + 6) % 7) !== target) continue; // pas le jour récurrent du cours
      const dateStr = dateInputValue(cur);
      if (!courseOccursOnDate(course, dateStr)) continue; // semaine où le cours n'a pas lieu (récurrence)
      const ex = planningExceptionFor(course.id, dateStr);
      if (ex && ex.cancelled) continue; // séance annulée ce jour → occurrence neutralisée
      if (impactCoversDate(impact, course, dateStr)) return true; // occurrence encore problématique
    }
    return false; // toutes les occurrences sont annulées ou résolues par exception → tâche fantôme
  }
  // Nombre d'occurrences encore réellement problématiques dans la période d'un impact (pour le détail).
  function impactPendingDatesForTasks(impact) {
    if (!impact || impact.archived) return 0;
    const course = impact.course;
    const start = parseDate(impact.periodStart);
    const end = parseDate(impact.periodEnd || impact.periodStart) || start;
    if (!course || !start) return 0;
    const target = COACH_DAYS.indexOf(asText(course.day));
    if (target < 0) return 0;
    const cur = new Date(start); cur.setHours(0, 0, 0, 0);
    const last = new Date(end); last.setHours(0, 0, 0, 0);
    let count = 0;
    for (let i = 0; i < 400 && cur <= last; i += 1, cur.setDate(cur.getDate() + 1)) {
      if (((cur.getDay() + 6) % 7) !== target) continue;
      const dateStr = dateInputValue(cur);
      if (!courseOccursOnDate(course, dateStr)) continue; // semaine où le cours n'a pas lieu (récurrence)
      const ex = planningExceptionFor(course.id, dateStr);
      if (ex && ex.cancelled) continue;
      if (impactCoversDate(impact, course, dateStr)) count += 1;
    }
    return count;
  }
  // Première occurrence RÉELLEMENT problématique d'un impact (pour le qualificatif « la première … »).
  function impactFirstPendingDate(impact) {
    if (!impact || impact.archived) return "";
    const course = impact.course;
    const start = parseDate(impact.periodStart);
    const end = parseDate(impact.periodEnd || impact.periodStart) || start;
    if (!course || !start) return "";
    const target = COACH_DAYS.indexOf(asText(course.day));
    if (target < 0) return "";
    const cur = new Date(start); cur.setHours(0, 0, 0, 0);
    const last = new Date(end); last.setHours(0, 0, 0, 0);
    for (let i = 0; i < 400 && cur <= last; i += 1, cur.setDate(cur.getDate() + 1)) {
      if (((cur.getDay() + 6) % 7) !== target) continue;
      const dateStr = dateInputValue(cur);
      if (!courseOccursOnDate(course, dateStr)) continue;
      const ex = planningExceptionFor(course.id, dateStr);
      if (ex && ex.cancelled) continue;
      if (impactCoversDate(impact, course, dateStr)) return dateStr;
    }
    return "";
  }
  // Lot À faire V2 (fenêtre coachs/salles) — À faire = action immédiate : un impact coach/salle n'y
  // reste visible que si sa première séance encore problématique tombe aujourd'hui ou demain, ou si
  // c'est un cas archivé/sans date (urgence structurelle non bornée dans le temps, toujours ouverte).
  // N'affecte QUE taskRows() : pendingCoachReplacements/pendingRoomReplacements/impactFirstPendingDate
  // restent inchangés et continuent d'alimenter Vigilance avec une fenêtre plus large.
  function replacementImpactIsImmediateForTasks(impact) {
    if (!impact) return false;
    if (impact.archived) return true;
    const nextDate = impactFirstPendingDate(impact);
    if (!nextDate) return false;
    const d = parseDate(nextDate); if (!d) return false;
    d.setHours(0, 0, 0, 0);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const diff = Math.round((d - today) / 86400000);
    return diff >= 0 && diff <= 1;
  }
  // Date relative lisible pour les cartes : « aujourd'hui / demain / mardi / le 12/07/2026 ».
  function vigilanceRelativeDate(dateStr) {
    const d = parseDate(dateStr); if (!d) return "";
    d.setHours(0, 0, 0, 0);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const diff = Math.round((d - today) / 86400000);
    if (diff <= 0) return "aujourd'hui";
    if (diff === 1) return "demain";
    if (diff < 7) return COACH_DAYS[(d.getDay() + 6) % 7].toLowerCase();
    return "le " + dateDisplay(dateStr);
  }

  // Lot À faire V2 — une facture en retard ne doit pas doubler une alerte "Paiement en
  // retard/refusé" déjà affichée pour la même source. Déduplication stricte par sourceId
  // (invoice.lines[].sourceId correspond exactement au row.id de paymentAgendaRows : membership.id,
  // shopOrder.id ou stageRegistration.id) — jamais par contact ou montant seuls, qui peuvent
  // coïncider entre deux dettes distinctes. Une facture sans sourceId (ligne "custom") n'est
  // jamais couverte : elle est la seule preuve du retard, rien d'autre ne peut déjà l'annoncer.
  function invoiceIsCoveredBySourcePaymentAlert(invoice, sourcePaymentRows) {
    const sourceIds = new Set((invoice.lines || []).map((line) => asText(line.sourceId)).filter(Boolean));
    if (!sourceIds.size) return false;
    const coveredIds = new Set((sourcePaymentRows || []).map((row) => row.id));
    return [...sourceIds].every((sid) => coveredIds.has(sid));
  }

  function taskRows() {
    const rows = [];
    const todayKey = dateInputValue(new Date());
    const add = (row) => rows.push({ id: row.id || id("task"), tone: "", ...row });
    // Lot À faire V2 — ne garder que les vraies urgences : un paiement à venir, à encaisser
    // aujourd'hui (mais pas en retard) ou un chèque simplement "en cours" reste visible dans
    // "Paiements dus", mais sort de "À faire". Seuls refusé/en retard restent. Capturé à part
    // (au lieu d'un simple forEach+return) pour pouvoir dédupliquer les factures en retard contre
    // ces mêmes lignes juste après (cf. invoiceIsCoveredBySourcePaymentAlert plus bas).
    const alertingPaymentRows = paymentAgendaRows(null).filter((row) => {
      const isLate = row.date && row.date < todayKey;
      return row.status === "Refusé" || isLate;
    });
    alertingPaymentRows.forEach((row) => {
      const category = row.status === "Refusé" ? "Paiement refusé" : "Paiement en retard";
      add({
        id: `payment-${row.editAction}-${row.id}-${row.stageId || ""}`,
        category,
        title: `${personLabel(row.person)} · ${row.module}`,
        detail: `${money(row.amount)} · ${statusLabel(row.status)}${row.date ? ` · ${dateDisplay(row.date)}` : " · sans date"}${row.scheduledAmount ? ` · en cours ${money(row.scheduledAmount)}` : ""}`,
        person: row.person,
        amount: row.amount,
        scheduledAmount: row.scheduledAmount,
        paymentDate: row.date,
        paymentStatus: row.status,
        payment: row.payment || {},
        module: row.module,
        email: reminderEmailForPerson(row.person),
        tone: "late",
        postitType: "late",
        action: row.editAction,
        attrs: `data-action="${esc(row.editAction)}" data-id="${esc(row.id)}" ${row.stageId ? `data-stage-id="${esc(row.stageId)}"` : ""}`,
        reminder: true,
      });
    });
    // Lot À faire V2 — factures en retard (invoiceIsLate), affichées seulement quand ce retard
    // n'est pas déjà annoncé par une alerte "Paiement en retard/refusé" ci-dessus sur la même
    // source : déduplication stricte par sourceId (jamais par contact/montant, cf. audit — deux
    // pistes différentes peuvent partager un contact ou un montant sans être la même dette).
    // Une ligne de facture "custom" (sans sourceId, ex. frais de dossier) n'a par construction
    // aucune source à vérifier : elle est donc toujours affichée si la facture est en retard.
    (state.invoices || []).forEach((invoice) => {
      if (!invoiceIsLate(invoice)) return;
      if (invoiceIsCoveredBySourcePaymentAlert(invoice, alertingPaymentRows)) return;
      const totals = invoiceLiveTotals(invoice);
      const earliestLateDate = [...(invoice.paymentsSnapshot || []), ...(invoice.paymentsAfterIssue || [])]
        .filter((payment) => paymentIsLate(payment))
        .map((payment) => paymentDueDate(payment))
        .filter(Boolean)
        .sort((a, b) => a - b)[0];
      const category = asNumber(totals.paid) > 0 ? "Facture partiellement payée en retard" : "Facture en retard";
      add({
        id: `invoice-late-${invoice.id}`,
        category,
        title: `${personLabel(invoice.contactSnapshot || {})} · ${invoice.number}`,
        detail: `Reste dû ${money(totals.restDue)}${earliestLateDate ? ` · Échéance du ${dateDisplay(dateInputValue(earliestLateDate))}` : ""}`,
        tone: "late",
        postitType: "late",
        action: "open-invoice",
        attrs: `data-action="open-invoice" data-id="${esc(invoice.id)}"`,
      });
    });
    if (isModuleEnabled("boutique") && hasFeature("shop")) {
      // Lot À faire V2 — seul le stock réellement en rupture (available < 0) reste une urgence ;
      // le simple seuil bas (isStockLow non-rupture) reste visible dans la page Stock uniquement.
      stockRows().filter((row) => row.available < 0).forEach((row) => {
        add({
          id: `stock-${row.article.id || row.index}`,
          category: "Stock",
          title: row.article.name || "Article",
          detail: `${intValue(row.available)} disponible · seuil ${intValue(row.article.stockAlert || 0)}`,
          tone: "late",
          available: row.available,
          postitType: "stock",
          action: "edit-stock-article",
          attrs: `data-action="edit-stock-article" data-index="${row.index}"`,
        });
      });
    }
    // Alertes documents sportifs centralisées (licence, certificat, autorisation, droit image, règlement)
    // Lot À faire V2 — seuls les documents manquants/expirés (level "soon" exclu = "bientôt
    // expiré", pas encore bloquant) restent une urgence ; le reste vit dans la page Documents.
    state.memberships.filter((row) => asText(row.discipline)).forEach((row) => {
      getMissingDocuments(row).filter((issue) => issue.level !== "soon").forEach((issue) => {
        add({
          id: `doc-${issue.key}-${row.id}`,
          category: "Document",
          title: personLabel(row),
          detail: `${row.discipline || "Discipline"} · ${issue.label}`,
          tone: "late",
          postitType: issue.key.indexOf("certificate") === 0 ? "certificate" : "due",
          action: "edit-membership",
          attrs: `data-action="edit-membership" data-id="${esc(row.id)}"`,
        });
      });
    });
    // Alertes organisation : groupes complets (le statut "complet" reste tel quel dans ce lot,
    // cf. audit — non traité pour éviter d'élargir le périmètre). "Presque complet" sort de
    // "À faire" (Lot À faire V2) : simple information, reste visible dans la page Groupes.
    (state.groups || []).filter((g) => !g.archived).forEach((g) => {
      const cap = getGroupCapacityStatus(g.id);
      if (cap.status === "full") add({ id: `group-full-${g.id}`, category: "Groupe complet", title: g.name, detail: `${cap.count} / ${cap.max} membres · complet`, tone: "late", postitType: "due", action: "edit-group", attrs: `data-action="edit-group" data-id="${esc(g.id)}"` });
    });
    // Alertes planning : conflits coach / créneau
    allPlanningConflicts().forEach((x) => {
      add({
        id: `conflict-${x.course.id}-${x.conflict.course.id}-${x.conflict.type}`,
        category: x.conflict.type === "coach" ? "Conflit de coach" : x.conflict.type === "room" ? "Conflit de salle" : "Conflit de créneau",
        title: `${x.course.name} / ${x.conflict.course.name}`,
        detail: `${x.course.day || "?"} · horaires qui se chevauchent`,
        tone: "late",
        postitType: "due",
        action: "edit-course",
        attrs: `data-action="edit-course" data-id="${esc(x.course.id)}"`,
      });
    });
    // Alertes "coach à remplacer" : séances planifiées touchées par une indisponibilité.
    // C2c-c : on masque les tâches fantômes déjà réglées par exception dans le planning (annulation
    // ou coach ponctuel pour la/les date(s) concernée(s)). Filtrage LOCAL à taskRows uniquement.
    if (typeof pendingCoachReplacements === "function") pendingCoachReplacements().filter((x) => (typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)) && replacementImpactIsImmediateForTasks(x)).forEach((x) => {
      const periodLabel = x.periodEnd && x.periodEnd !== x.periodStart ? `${dateDisplay(x.periodStart)}–${dateDisplay(x.periodEnd)}` : dateDisplay(x.periodStart);
      const dates = x.archived ? 0 : impactPendingDatesForTasks(x);
      const datesLabel = dates > 0 ? ` · ${dates} date${dates > 1 ? "s" : ""} concernée${dates > 1 ? "s" : ""}` : "";
      const cause = x.archived ? (x.reason || "Coach archivé") : `indisponible ${periodLabel}${x.reason ? " · " + x.reason : ""}${datesLabel}`;
      add({
        id: `coach-replace-${x.course.id}-${x.periodStart}-${x.periodEnd}`,
        category: "Coach à remplacer",
        title: `${x.course.name} · ${coachFullName(x.coach)}`,
        detail: `${x.course.day || "?"} ${x.course.startTime || ""} · ${cause}`,
        tone: "late",
        nextDate: x.archived ? "" : impactFirstPendingDate(x),
        postitType: "due",
        action: "replace-session",
        attrs: `data-action="replace-session" data-course-id="${esc(x.course.id)}" data-ps="${esc(x.periodStart)}" data-pe="${esc(x.periodEnd)}"`,
      });
    });
    // Alertes "salle à remplacer" : séances planifiées touchées par une indisponibilité de salle.
    // C2c-c : même filtrage des tâches fantômes que pour les coachs (annulation ou salle ponctuelle).
    if (typeof pendingRoomReplacements === "function") pendingRoomReplacements().filter((x) => (typeof impactStillPendingForTasks !== "function" || impactStillPendingForTasks(x)) && replacementImpactIsImmediateForTasks(x)).forEach((x) => {
      const periodLabel = x.periodEnd && x.periodEnd !== x.periodStart ? `${dateDisplay(x.periodStart)}–${dateDisplay(x.periodEnd)}` : dateDisplay(x.periodStart);
      const dates = x.archived ? 0 : impactPendingDatesForTasks(x);
      const datesLabel = dates > 0 ? ` · ${dates} date${dates > 1 ? "s" : ""} concernée${dates > 1 ? "s" : ""}` : "";
      const cause = x.archived ? (x.reason || "Salle archivée") : `indisponible ${periodLabel}${x.reason ? " · " + x.reason : ""}${datesLabel}`;
      add({
        id: `room-replace-${x.course.id}-${x.periodStart}-${x.periodEnd}`,
        category: "Salle à remplacer",
        title: `${x.course.name} · ${roomName(x.room)}`,
        detail: `${x.course.day || "?"} ${x.course.startTime || ""} · ${cause}`,
        tone: "late",
        nextDate: x.archived ? "" : impactFirstPendingDate(x),
        postitType: "due",
        action: "replace-room-session",
        attrs: `data-action="replace-room-session" data-course-id="${esc(x.course.id)}" data-ps="${esc(x.periodStart)}" data-pe="${esc(x.periodEnd)}"`,
      });
    });
    // Lot À faire V2 — "Assurance à vérifier" (toujours non bloquant) et "Anniversaire à venir"
    // (purement informatif) retirés de "À faire" : aucune des deux ne constitue une urgence,
    // même en partie ; l'assurance reste visible sur la fiche adhérent.
    const priority = { late: 0, due: 1, wait: 2, ok: 3, "": 4 };
    return rows.sort((a, b) => (priority[a.tone] ?? 5) - (priority[b.tone] ?? 5) || a.category.localeCompare(b.category) || a.title.localeCompare(b.title));
  }

  function upcomingBirthday(birthDate, daysAhead = 7) {
    const date = parseDate(birthDate);
    if (!date) return null;
    const today = new Date();
    const start = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    let next = new Date(start.getFullYear(), date.getMonth(), date.getDate());
    if (next < start) next = new Date(start.getFullYear() + 1, date.getMonth(), date.getDate());
    const days = Math.round((next - start) / 86400000);
    if (days < 0 || days > daysAhead) return null;
    return { date: dateInputValue(next), days };
  }

  // Groupes de filtres d'affichage de la page « À faire » (clé stable + libellé).
  // Construits à partir des VRAIES catégories produites par taskRows (pas de fausse catégorie).
  function taskFilterGroups() {
    return [
      ["payments", "Paiements"],
      ["documents", "Documents / assurances"],
      ["shop", "Boutique / stock"],
      ["planning", "Planning"],
      ["coaches", "Coachs"],
      ["rooms", "Salles"],
      ["misc", "Divers"],
    ];
  }
  // Range une alerte dans son groupe de filtre selon sa catégorie réelle.
  function taskFilterGroupOf(row) {
    const c = asText(row && row.category);
    // Lot À faire V2 (factures en retard) — "Facture en retard"/"Facture partiellement payée en
    // retard" sont un souci financier au même titre qu'un paiement en retard/refusé : les router
    // vers "payments" comme eux, pas vers le repli "misc" (qui alimenterait à tort la carte
    // Vigilance "Groupes", conçue pour les groupes complets/presque pleins, sans rapport).
    if (c.includes("Paiement") || c === "À encaisser" || c.includes("Facture")) return "payments";
    if (c === "Document" || c === "Assurance à vérifier") return "documents";
    if (c === "Stock") return "shop";
    if (c.indexOf("Conflit") === 0) return "planning";
    if (c === "Coach à remplacer") return "coaches";
    if (c === "Salle à remplacer") return "rooms";
    return "misc"; // Groupe complet / presque complet, Anniversaire à venir, etc.
  }

  // Regroupement AFFICHAGE des alertes Documents par adhérent (ne touche pas taskRows ni les KPIs).
  // Lot Dossier incomplet (routage direct) — le nom du champ de formulaire du contact à
  // focus/scroller après ouverture, pour chaque clé d'anomalie « personne ». Source UNIQUE de cette
  // correspondance clé -> champ : jamais dupliquée ailleurs. "" pour toute clé sans champ dédié
  // (ex. anomalies d'inscription, qui n'empruntent de toute façon jamais ce chemin).
  function dossierIssueFocusField(key) {
    if (key === "parental-missing") return "parentalAuthorization";
    if (key === "image-missing") return "imageRights";
    if (key === "rules-missing") return "rulesSigned";
    return "";
  }

  // Itère les inscriptions (même source que taskRows), dédoublonne les documents « personne » (parental,
  // droit image, règlement) et garde la discipline pour les documents « inscription » (licence, certificat).
  function dossierDocumentGroups() {
    const groups = new Map();
    (state.memberships || []).filter((m) => asText(m.discipline)).forEach((m) => {
      const issues = (typeof getMissingDocuments === "function") ? getMissingDocuments(m) : [];
      if (!issues.length) return;
      const link = contactLinkForRow(m) || `name:${personKey(m)}`;
      if (!groups.has(link)) {
        const contact = (typeof contactForMembership === "function") ? contactForMembership(m) : null;
        groups.set(link, {
          link, name: personLabel(m), membership: m, items: [], seen: new Set(),
          phone: contact ? asText(contact.mobile || contact.phone) : asText(m.mobile || m.phone),
          email: contact ? asText(contact.email) : asText(m.email),
        });
      }
      const g = groups.get(link);
      issues.forEach((issue) => {
        const personLevel = /^(parental|image|rules)/.test(issue.key);
        const discipline = personLevel ? "" : asText(m.discipline);
        const dedupKey = personLevel ? `p:${issue.key}` : `d:${issue.key}|${m.discipline}`;
        if (g.seen.has(dedupKey)) return;
        g.seen.add(dedupKey);
        // Lot Dossier incomplet (routage direct) — personLevel (dérivé de issue.key, jamais du
        // libellé affiché) porte le routage du bouton "Ouvrir" : une anomalie de contact doit ouvrir
        // directement Modifier le contact, jamais transiter par Modifier l'inscription.
        g.items.push({ label: issue.label, discipline, membershipId: m.id, tone: issue.level === "soon" ? "wait" : "late", personLevel, focusField: dossierIssueFocusField(issue.key) });
      });
    });
    return groups;
  }

  // Carte post-it résumée « Dossier incomplet » (2-3 lignes max + « Voir le détail »).
  function groupedDocTaskHtml(group) {
    const items = group.items;
    const count = items.length;
    const tone = items.some((i) => i.tone === "late") ? "late" : "wait";
    // Résumé court : types de documents distincts (premier mot du libellé), sur UNE seule ligne
    // clampée. Le détail complet reste dans la popup « Voir le détail ». Évite tout débordement
    // sur le bouton, quels que soient le nombre de documents, la longueur des noms/disciplines.
    const keywords = [];
    items.forEach((i) => {
      const word = asText(i.label).split(/[\s—-]+/)[0];
      if (word && !keywords.includes(word)) keywords.push(word);
    });
    const summary = keywords.join(", ");
    const haystack = [group.name, "Document", group.phone, group.email, ...items.map((i) => i.label), ...items.map((i) => i.discipline)].filter(Boolean).join(" ");
    const styleRow = { tone, postitType: "due" };
    return `<article class="task-postit clickable-card task-postit-grouped task-${esc(tone)}" style="${postitStyleForTask(styleRow)}" data-search="${esc(haystack)}">
      <div class="task-postit-pin"></div>
      <span class="status ${statusClass(tone === "late" ? "Refusé" : "En cours")}">Dossier incomplet</span>
      <strong>${esc(group.name)}</strong>
      <div class="task-doc-body">
        <span class="task-doc-count">${count} document${count > 1 ? "s" : ""} à vérifier</span>
        ${summary ? `<span class="task-doc-summary">${esc(summary)}</span>` : ""}
      </div>
      <div class="task-postit-actions">
        <button type="button" data-action="view-dossier-documents" data-contact-link="${esc(group.link)}">Voir le détail</button>
      </div>
    </article>`;
  }

  // Popup « Voir le détail » : liste toutes les alertes Documents d'un adhérent, avec discipline et un
  // bouton « Ouvrir » par document. Routage par PROPRIÉTAIRE métier de la donnée (it.personLevel,
  // dérivé de issue.key — jamais du libellé affiché) : une anomalie de CONTACT (autorisation
  // parentale, droit à l'image, règlement) ouvre directement Modifier le contact
  // (open-linked-contact + group.link, l'IDENTIFIANT stable du contact — jamais son nom), avec le
  // focus posé sur le bon champ ; une anomalie d'INSCRIPTION (licence, certificat) garde l'ouverture
  // historique de l'inscription (edit-membership, bon data-id). group.link n'est un lien contact
  // exploitable que s'il commence par "member:"/"prospect:" (jamais le repli "name:" d'une donnée
  // legacy sans contactId) : dans ce cas on retombe sur edit-membership plutôt qu'un bouton mort.
  // Contenu (recalculé depuis state) de la liste « Voir le détail » d'un dossier. Réutilisé à
  // l'ouverture ET au rafraîchissement après résolution d'un problème.
  function dossierDetailInnerHtml(contactLink) {
    const group = dossierDocumentGroups().get(contactLink);
    const items = group?.items || [];
    if (!items.length) {
      return `<p class="dossier-doc-empty">✓ Tous les documents de ce dossier sont à jour.</p>`;
    }
    const count = items.length;
    const canLinkContact = /^(member|prospect):/.test(group.link);
    const list = items.map((it, index) => {
      const openBtn = (it.personLevel && canLinkContact)
        ? `<button type="button" class="small" data-action="open-linked-contact" data-contact-link="${esc(group.link)}"${it.focusField ? ` data-contact-focus-field="${esc(it.focusField)}"` : ""}>Ouvrir</button>`
        : `<button type="button" class="small" data-action="edit-membership" data-id="${esc(it.membershipId)}">Ouvrir</button>`;
      return `<li class="dossier-doc-item">
        <span class="dossier-doc-rank">${index + 1}.</span>
        <span class="dossier-doc-text"><strong>${esc(it.label)}</strong>${it.discipline ? ` <span class="muted">— ${esc(it.discipline)}</span>` : ""}</span>
        ${openBtn}
      </li>`;
    }).join("");
    return `<p class="muted">${count} document${count > 1 ? "s" : ""} à vérifier :</p>
      <ul class="dossier-doc-list">${list}</ul>`;
  }

  function openDossierDocumentsDialog(contactLink) {
    const group = dossierDocumentGroups().get(contactLink);
    if (!group || !group.items.length) {
      showInfoDialog("Dossier", "<p class=\"muted\">Aucun document à vérifier pour cet adhérent.</p>");
      return;
    }
    showInfoDialog(`${esc(group.name)} — Dossier incomplet`, `<div class="dossier-doc-detail" data-dossier-dialog data-contact-link="${esc(contactLink)}" data-contact-name="${esc(group.name)}">${dossierDetailInnerHtml(contactLink)}</div>`);
  }

  // Rafraîchit, sans la fermer, toute liste « dossier » ouverte après résolution d'un problème
  // (appelée dans le même flux que refreshOpenContactDialog / refreshOpenInvoiceEditor).
  function refreshOpenDossierDialog() {
    document.querySelectorAll("dialog[open] [data-dossier-dialog][data-contact-link]").forEach((el) => {
      const link = el.dataset.contactLink;
      const remaining = dossierDocumentGroups().get(link)?.items?.length || 0;
      el.innerHTML = dossierDetailInnerHtml(link);
      // Titre cohérent avec le corps : « à jour » quand plus aucun problème.
      const name = el.dataset.contactName || "Dossier";
      const h2 = el.closest("dialog")?.querySelector(".dialog-header h2");
      if (h2) h2.textContent = `${name} — ${remaining ? "Dossier incomplet" : "Dossier à jour"}`;
    });
  }

  function renderTasks() {
    const rows = taskRows();
    const paymentCount = rows.filter((row) => row.category.includes("Paiement") || row.category === "À encaisser").length;
    const lateCount = rows.filter((row) => row.tone === "late").length;
    // --- Filtres d'AFFICHAGE (jamais de suppression/résolution d'alerte) ---
    const hidden = new Set(Array.isArray(ui.taskHiddenGroups) ? ui.taskHiddenGroups : []);
    const countByGroup = {};
    rows.forEach((row) => { const g = taskFilterGroupOf(row); countByGroup[g] = (countByGroup[g] || 0) + 1; });
    const presentGroups = taskFilterGroups().filter(([key]) => countByGroup[key]);
    const visibleRows = rows.filter((row) => !hidden.has(taskFilterGroupOf(row)));
    const hiddenCount = rows.length - visibleRows.length;
    const anyHidden = presentGroups.some(([key]) => hidden.has(key));
    const filtersOpen = Boolean(ui.taskFiltersOpen);
    const summary = `${visibleRows.length} alerte${visibleRows.length > 1 ? "s" : ""} affichée${visibleRows.length > 1 ? "s" : ""}${hiddenCount ? ` · ${hiddenCount} masquée${hiddenCount > 1 ? "s" : ""} par filtre` : ""}`;
    const filterPanel = rows.length ? `<div class="task-filters">
        <div class="task-filters-head">
          <button type="button" class="task-filters-toggle" data-action="toggle-task-filters" aria-expanded="${filtersOpen}">⚲ Filtres${anyHidden ? ` · ${hidden.size} masqué${hidden.size > 1 ? "s" : ""}` : ""} <span class="tf-caret">${filtersOpen ? "▴" : "▾"}</span></button>
          <span class="muted task-filters-summary">${summary}</span>
        </div>
        ${filtersOpen ? `<div class="task-filters-body">
          ${presentGroups.map(([key, label]) => { const on = !hidden.has(key); return `<button type="button" class="task-filter-chip ${on ? "on" : "off"}" data-action="toggle-task-filter" data-group="${esc(key)}" aria-pressed="${on}"><span class="tf-box">${on ? "☑" : "☐"}</span> ${esc(label)} <span class="tf-count">${countByGroup[key]}</span></button>`; }).join("")}
          <button type="button" class="task-filter-all" data-action="task-filter-show-all" ${anyHidden ? "" : "disabled"}>Tout afficher</button>
        </div>` : ""}
      </div>` : "";
    // Grille : alertes non-Documents telles quelles + alertes Documents REGROUPÉES par adhérent.
    // (Affichage uniquement : taskRows et les KPIs restent basés sur les alertes réelles ci-dessus.)
    const priority = { late: 0, due: 1, wait: 2, ok: 3, "": 4 };
    const nonDocVisible = visibleRows.filter((row) => row.category !== "Document");
    const docGroups = hidden.has("documents") ? [] : [...dossierDocumentGroups().values()].filter((g) => g.items.length);
    const displayItems = [
      ...nonDocVisible.map((row) => ({ tone: row.tone, html: taskRowHtml(row) })),
      ...docGroups.map((g) => {
        const tone = g.items.some((i) => i.tone === "late") ? "late" : "wait";
        // Un seul document -> post-it simple (action edit-membership directe), sinon carte groupée.
        if (g.items.length === 1) {
          const it = g.items[0];
          const row = { id: `doc-grp-${g.link}`, category: "Document", title: g.name,
            detail: `${it.discipline ? `${it.discipline} · ` : ""}${it.label}`, tone: it.tone,
            postitType: "due", attrs: `data-action="edit-membership" data-id="${esc(it.membershipId)}"` };
          return { tone: it.tone, html: taskRowHtml(row) };
        }
        return { tone, html: groupedDocTaskHtml(g) };
      }),
    ].sort((a, b) => (priority[a.tone] ?? 5) - (priority[b.tone] ?? 5));
    const gridHtml = rows.length === 0
      ? `<div class="empty">Rien d'urgent pour le moment.</div>`
      : displayItems.length === 0
        ? `<div class="empty">Toutes les alertes (${rows.length}) sont masquées par les filtres. <button type="button" class="link-like" data-action="task-filter-show-all">Tout afficher</button></div>`
        : `<div class="task-postit-grid">${displayItems.map((it) => it.html).join("")}</div>`;
    // Recherche texte (filtre d'affichage par adhérent / contact / catégorie / type). Réutilise le
    // helper commun applyDialogListFilter (branché par délégation sur le listener input de #app).
    // N'altère ni taskRows, ni les données, ni les KPIs : masque/affiche les post-it uniquement.
    const listHtml = visibleRows.length
      ? `<div data-list-search-scope>
          <div class="dialog-list-search task-search">
            <input type="search" data-list-search placeholder="Rechercher dans les alertes (nom, prénom, catégorie…)" autocomplete="off" />
            <span class="dialog-list-search-count muted" data-list-search-count></span>
          </div>
          ${gridHtml}
          <div class="empty" data-list-search-empty hidden>Aucun résultat pour cette recherche.</div>
        </div>`
      : gridHtml;
    return `
      ${kpis([
        { label: "Actions", value: rows.length },
        { label: "Prioritaires", value: lateCount },
        { label: "Paiements", value: paymentCount },
        { label: "Stocks", value: rows.filter((row) => row.category === "Stock").length },
        { label: "Documents", value: rows.filter((row) => row.category === "Document" || row.category === "Assurance à vérifier").length },
      ])}
      <div class="band">
        <div class="band-title">
          <div><h2>À faire aujourd'hui</h2><p class="muted">Les vraies urgences à traiter, regroupées automatiquement.</p></div>
          <button data-action="save-now">Actualiser</button>
        </div>
        ${filterPanel}
        ${listHtml}
      </div>
    `;
  }

  // Chaîne de recherche d'une alerte (filtre d'affichage de la page À faire) : catégorie, titre,
  // détail, et — quand l'alerte est liée à une personne — nom, téléphone, e-mail, discipline.
  function taskSearchText(row) {
    const person = row && row.person;
    return [
      asText(row && row.category),
      asText(row && row.title),
      asText(row && row.detail),
      person ? personLabel(person) : "",
      person ? asText(person.mobile || person.phone) : "",
      person ? asText(person.email) : "",
      person ? asText(person.discipline) : "",
    ].filter(Boolean).join(" ");
  }

  function taskRowHtml(row) {
    return `<article class="task-postit clickable-card task-${esc(row.postitType || row.tone || "due")}" style="${postitStyleForTask(row)}" data-search="${esc(taskSearchText(row))}" ${row.attrs || ""}>
      <div class="task-postit-pin"></div>
      <span class="status ${statusClass(row.tone === "late" ? "Refusé" : row.tone === "wait" ? "En cours" : row.tone === "ok" ? "OK" : "Reste dû")}">${esc(row.category)}</span>
      <strong>${esc(row.title)}</strong>
      <p>${esc(row.detail)}</p>
      <div class="task-postit-actions">
        <button type="button" ${row.attrs || ""}>Ouvrir</button>
        ${row.reminder ? `<button type="button" data-action="open-reminder" data-task-id="${esc(row.id)}">Relancer</button>` : ""}
      </div>
    </article>`;
  }

  function reminderTextForTask(task = {}) {
    return renderEmailTemplate("reminder", reminderContext(task)).body;
  }

  function reminderEmailForPerson(person = {}) {
    const linked = contactByLink(contactLinkForRow(person)) || {};
    return asText(person.email || linked.email);
  }

  function reminderContext(task = {}) {
    const title = asText(task.title);
    const titleName = title.split("·")[0].trim();
    const module = asText(task.module || title.split("·").slice(1).join("·").trim());
    const contactContext = emailContextForContact(task.person || {});
    const amount = task.amount !== undefined ? money(task.amount) : (task.detail || "").split("·")[0]?.trim() || "";
    const payment = task.payment || {};
    const date = task.paymentDate || (task.detail || "").split("·").map((part) => part.trim()).find((part) => /\d{2}\/\d{2}\/\d{4}/.test(part)) || "";
    return {
      ...contactContext,
      nom: contactContext.nom || titleName || personLabel(task.person),
      nom_complet: contactContext.nom_complet || titleName || personLabel(task.person),
      categorie: task.category || "paiement",
      detail: task.detail || "",
      montant: amount,
      date: dateDisplay(date) || date,
      module,
      montantDu: amount,
      resteAPayer: amount,
      montantTotal: amount,
      montantPaye: "",
      dateEcheance: dateDisplay(date) || date,
      modePaiement: asText(payment.check) ? paymentModeLabel(payment.check) : "",
      numeroCheque: invoicePaymentCheckNumber(payment),
      statutPaiement: statusLabel(task.paymentStatus || paymentStatus(payment)),
      discipline: /discipline/i.test(module) ? module : asText(task.person?.discipline),
      stage: /stage/i.test(module) ? module : "",
      article: /boutique/i.test(module) ? asText(task.person?.article || task.person?.item || "") : "",
      factureNumero: "",
    };
  }

  // « Relancer » (À faire) ouvrait auparavant directement un <a href="mailto:...">, sans jamais
  // passer par l'interface e-mail MonGestaClub (pas d'aperçu HTML, pas de choix de modèle, pas de
  // bouton SMTP intégré). Corrigé pour réutiliser openContactEmailDialog (même dialogue que
  // partout ailleurs), avec le contexte de relance (montant/date/module) déjà calculé par
  // reminderContext() passé en surcharge. Si le contact ne peut pas être résolu par ID (ligne
  // libre sans lien fiable), on construit un contact minimal à partir de task.person + l'e-mail
  // connu, pour ne jamais perdre la fonctionnalité existante. Repli "copier le message" conservé
  // seulement pour le cas réellement sans e-mail (SMS/messagerie manuelle).
  function openReminderDialog(taskId) {
    const task = taskRows().find((row) => row.id === taskId);
    if (!task) return;
    const email = asText(task.email || reminderEmailForPerson(task.person));
    if (email) {
      const resolved = contactByLink(contactLinkForRow(task.person || {}));
      const contact = resolved || { ...(task.person || {}), email };
      openContactEmailDialog(contact, "reminder", reminderContext(task));
      return;
    }
    const text = reminderTextForTask(task);
    showInfoDialog("Relance prête", `<div class="dialog-section reminder-dialog">
      <p class="muted">Aucun e-mail n'est renseigné : copie le message pour l'envoyer par SMS ou messagerie.</p>
      <textarea data-reminder-text>${esc(text)}</textarea>
      <div class="inline-actions">
        <button type="button" data-action="copy-reminder">Copier le message</button>
      </div>
    </div>`);
  }

  async function copyReminderText(button) {
    const text = button.closest("dialog")?.querySelector("[data-reminder-text]")?.value || "";
    if (!text) return;
    try {
      await navigator.clipboard.writeText(text);
      ui.saveMessage = "Message de relance copié";
      if (dialog.open) dialog.close();
      render();
    } catch (error) {
      alert(text);
    }
  }

  function globalSearchRows(query = ui.globalSearch) {
    const needle = normalizedPersonText(query);
    if (!needle) return [];
    const matches = (values = []) => normalizedPersonText(values.filter(Boolean).join(" ")).includes(needle);
    const rows = [];
    const push = (row) => rows.push(row);
    state.contacts.members.forEach((contact) => {
      if (matches([contact.lastName, contact.firstName, contact.email, contact.mobile, contact.phone, contact.city])) {
        push({ type: "Adhérent", title: personLabel(contact), detail: [contact.email, contact.mobile || contact.phone, contact.city].filter(Boolean).join(" · "), attrs: `data-action="edit-contact" data-kind="members" data-id="${esc(contact.id)}"` });
      }
    });
    state.contacts.prospects.forEach((contact) => {
      if (matches([contact.lastName, contact.firstName, contact.email, contact.mobile, contact.phone, contact.city])) {
        push({ type: "Non adhérent", title: personLabel(contact), detail: [contact.email, contact.mobile || contact.phone, contact.city].filter(Boolean).join(" · "), attrs: `data-action="edit-contact" data-kind="prospects" data-id="${esc(contact.id)}"` });
      }
    });
    state.memberships.forEach((row) => {
      if (matches([row.lastName, row.firstName, row.discipline, row.email, row.city])) {
        const calc = calcMembership(row);
        // Lot 3A (clôture absolue, FIN-ABS-2) — recherche globale : « Tarif non défini » plutôt qu'un
        // trompeur « Total 0,00 € · reste 0,00 € » pour une inscription au tarif absent.
        const detail = calc.hasGrossTotal ? `Total ${money(calc.total)} · reste ${money(calc.restDue)}` : "Tarif non défini";
        push({ type: "Discipline", title: `${personLabel(row)} · ${row.discipline || "Sans discipline"}`, detail, attrs: `data-action="edit-membership" data-id="${esc(row.id)}"` });
      }
    });
    if (isModuleEnabled("boutique") && hasFeature("shop")) {
      state.tariffs.articles.forEach((article, index) => {
        if (matches([article.name, article.reference, (article.sizes || []).join(" ")])) {
          push({ type: "Article", title: article.name || "Article", detail: `${article.reference || ""} · ${money(article.priceOptions?.[0] || 0)}`, attrs: `data-action="edit-stock-article" data-index="${index}"` });
        }
      });
      state.shopOrders.forEach((order) => {
        const articles = orderItemDetails(order).map((item) => `${item.article.name} ${item.sizesText}`).join(" ");
        if (matches([order.lastName, order.firstName, order.email, order.phone, articles])) {
          const calc = calcOrder(order);
          push({ type: "Commande", title: personLabel(order), detail: `${articles || "Commande"} · reste ${money(calc.restDue)}`, attrs: `data-action="view-order" data-id="${esc(order.id)}"` });
        }
      });
    }
    // Résultats de recherche Stages : ouvrent une mutation (edit-stage/edit-registration). Surface
    // opérationnelle (Lot 2D) -> masquée quand la fonctionnalité est désactivée ou l'affichage coupé.
    // L'historique financier reste consultable via la fiche contact, les factures et la comptabilité.
    if (isModuleEnabled("stages") && hasFeature("stages")) {
      state.tariffs.stages.forEach((stage) => {
        if (matches([stage.name, stage.lodgingName])) push({ type: "Stage", title: stage.name || "Stage", detail: `${money(stage.unitPrice || 0)} · ${stageParticipantCount(stage.id)} participant(s)`, attrs: `data-action="edit-stage" data-stage-id="${esc(stage.id)}"` });
        (state.stageRegistrations[stage.id] || []).forEach((registration) => {
          if (matches([registration.lastName, registration.firstName, registration.email, stage.name])) {
            const calc = calcRegistration(registration, stage.id);
            push({ type: "Participant stage", title: `${personLabel(registration)} · ${stage.name}`, detail: `Total ${money(calc.total)} · reste ${money(calc.restDue)}`, attrs: `data-action="edit-registration" data-stage-id="${esc(stage.id)}" data-id="${esc(registration.id)}"` });
          }
        });
      });
    }
    state.notes.forEach((note) => {
      if (matches([note.title, noteText(note.content)])) push({ type: "Note", title: note.title || "Note", detail: noteText(note.content).slice(0, 120), attrs: `data-action="open-note-result" data-note-id="${esc(note.id)}"` });
    });
    (state.coaches || []).forEach((coach) => {
      if (matches([coach.firstName, coach.lastName, coach.email, coach.phone, (coach.specialties || []).join(" "), coach.notes, coachAvailabilitySummary(coach)])) {
        push({ type: "Coach", title: coachFullName(coach), detail: [(coach.specialties || []).join(", "), coach.archived ? "archivé" : ""].filter(Boolean).join(" · "), attrs: `data-action="edit-coach" data-id="${esc(coach.id)}"` });
      }
    });
    // Groupes : absents de la recherche métier jusqu'ici alors que la page existe et que les
    // groupes sont une entité de premier plan. Comblé ici (signalé comme écart préexistant).
    (state.groups || []).forEach((group) => {
      if (matches([group.name, group.discipline, group.type, group.notes])) {
        push({
          type: "Groupe",
          title: group.name || "Groupe",
          detail: [group.discipline, group.type, group.archived ? "archivé" : ""].filter(Boolean).join(" · "),
          attrs: `data-action="edit-group" data-id="${esc(group.id)}"`,
        });
      }
    });
    (state.rooms || []).forEach((room) => {
      if (matches([room.name, room.address, room.type, (room.disciplines || []).join(" "), room.equipment, room.notes, room.description, room.managerName, room.managerEmail, room.managerPhone, roomAvailabilitySummary(room)])) {
        push({ type: "Salle", title: roomName(room), detail: [room.type, (room.disciplines || []).join(", "), room.archived ? "archivée" : ""].filter(Boolean).join(" · "), attrs: `data-action="edit-room" data-id="${esc(room.id)}"` });
      }
    });
    (state.invoices || []).filter(invoiceBelongsToActiveClub).forEach((invoice) => {
      if (!invoiceMatchesSearch(invoice, query)) return;
      const contact = invoiceDisplayContact(invoice);
      const totals = invoiceDisplayTotals(invoice);
      const status = invoiceStatusLabel({ ...invoice, status: computedInvoiceStatus(invoice) });
      push({
        type: "Facture",
        title: invoice.number || "Brouillon de facture",
        detail: `${personLabel(contact) || "Contact"} · ${status} · total ${money(totals.total)} · reste ${money(totals.restDue)}`,
        attrs: `data-action="open-invoice" data-id="${esc(invoice.id)}"`,
      });
    });
    return rows.slice(0, 80);
  }

  function renderSearch() {
    // Combobox : le champ pilote une liste de résultats (aria-controls/-expanded/-activedescendant),
    // ce qui rend la navigation aux flèches annonçable par les lecteurs d'écran.
    const hasQuery = Boolean(asText(ui.globalSearch));
    return `<div class="band">
      <div class="band-title">
        <div><h2>Recherche globale</h2><p class="muted">Personnes et données du club, mais aussi pages, réglages et actions du logiciel.</p></div>
      </div>
      <div class="search-page-form">
        <input type="search" value="${esc(ui.globalSearch)}" data-global-search
          placeholder="Contact, coach, salle, facture… ou « ajouter un coach », « SMTP », « paiements dus »"
          role="combobox" aria-expanded="${hasQuery ? "true" : "false"}" aria-controls="global-search-results"
          aria-autocomplete="list" aria-label="Recherche globale" autofocus />
        <button class="primary" data-action="run-global-search">Rechercher</button>
      </div>
      <div data-search-results>
        ${searchResultsHtml()}
      </div>
    </div>`;
  }

  // Un résultat = une option de liste. `attrs` (données métier) et l'identifiant de registre
  // (résultats fonctionnels) sont les SEULS vecteurs d'action : aucun code n'est transporté.
  function searchOptionHtml(option, index) {
    const meta = searchTypeMeta(option.type);
    const iconKey = option.icon && MGC_ICONS[option.icon] ? option.icon : meta.icon;
    const icon = getIconSvg(iconKey);
    const indispo = option.unavailable ? ` search-option-unavailable` : "";
    return `<li class="search-option${indispo}" role="option" id="search-option-${index}"
      aria-selected="false" data-search-option data-index="${index}" ${option.attrs || ""}>
      <span class="search-option-icon" aria-hidden="true">${icon}</span>
      <span class="search-option-main">
        <span class="search-option-title">${esc(option.title)}</span>
        ${option.description ? `<span class="search-option-desc">${esc(option.description)}</span>` : ""}
        ${option.unavailable ? `<span class="search-option-reason">${esc(option.unavailable)}</span>` : ""}
      </span>
      <span class="search-option-badge" data-type="${esc(option.type)}">${esc(meta.label)}</span>
      ${option.destination ? `<span class="search-option-dest">${esc(option.destination)}</span>` : ""}
    </li>`;
  }

  // Construit la liste unifiée : fonctionnel d'abord (on cherche souvent « où est X ? »), puis les
  // données métier — qui ne sont jamais masquées, seulement regroupées sous leur propre titre.
  function searchOptions(query = ui.globalSearch) {
    const options = [];
    functionalSearchResults(query).forEach((row) => {
      const { entry, availability } = row;
      options.push({
        group: "Pages, réglages et actions",
        type: entry.type,
        title: entry.title,
        description: entry.description,
        icon: entry.icon,
        destination: entry.view ? viewLabel(entry.view) : "",
        unavailable: availability.available ? "" : availability.reason,
        // Exécution par identifiant, validé contre le registre au moment du clic.
        attrs: `data-action="run-search-command" data-command-id="${esc(entry.id)}"${availability.available ? "" : ' data-command-fix="1"'}`,
      });
    });
    globalSearchRows(query).forEach((row) => {
      options.push({
        group: "Données du club",
        type: "data",
        title: row.title,
        description: row.detail,
        icon: searchDataIcon(row.type),
        destination: row.type,
        attrs: row.attrs,
      });
    });
    return options;
  }

  // Icône d'un résultat métier : réutilise l'icône de la page qui héberge l'entité.
  function searchDataIcon(dataType) {
    const map = {
      "Adhérent": "contacts", "Non adhérent": "contacts", "Discipline": "disciplines",
      "Article": "stock", "Commande": "boutique", "Stage": "stages", "Participant stage": "stages",
      "Note": "notes", "Coach": "coaches", "Salle": "rooms", "Facture": "invoices", "Groupe": "groups",
    };
    return map[dataType] || "search";
  }

  function searchResultsHtml() {
    if (!asText(ui.globalSearch)) {
      // Requête vide : on garde le comportement existant, sans déverser tout le registre.
      return `<p class="muted">Tape une recherche puis valide avec Entrée. Tu peux chercher une personne, une page (« paiements dus »), un réglage (« SMTP ») ou une action (« ajouter un coach »).</p>`;
    }
    const options = searchOptions();
    if (!options.length) {
      return `<p class="muted">0 résultat pour "${esc(ui.globalSearch)}"</p>
        <div class="empty">Aucun résultat. Essaie un autre mot : un nom, une page (« stock »), un réglage (« thème ») ou une action (« ajouter une salle »).</div>`;
    }
    let index = -1;
    const groups = [];
    options.forEach((option) => {
      const last = groups[groups.length - 1];
      if (!last || last.title !== option.group) groups.push({ title: option.group, items: [option] });
      else last.items.push(option);
    });
    return `<p class="muted">${intValue(options.length)} résultat${options.length > 1 ? "s" : ""} pour "${esc(ui.globalSearch)}"</p>
      <ul class="search-results-list" id="global-search-results" role="listbox" aria-label="Résultats de recherche">
        ${groups.map((group) => `
          <li class="search-results-group" role="presentation">
            <span class="search-results-group-title">${esc(group.title)}</span>
            <ul role="group" aria-label="${esc(group.title)}">
              ${group.items.map((option) => { index += 1; return searchOptionHtml(option, index); }).join("")}
            </ul>
          </li>`).join("")}
      </ul>`;
  }

  function updateSearchResults() {
    const container = app.querySelector("[data-search-results]");
    if (!container) return;
    container.innerHTML = searchResultsHtml();
    // Nouvelle liste : aucun résultat actif tant que l'utilisateur n'a pas appuyé sur une flèche.
    ui.searchActiveIndex = -1;
    syncSearchActiveOption();
  }

  function searchOptionElements() {
    return Array.from(app.querySelectorAll("[data-search-option]"));
  }

  function activeSearchOptionElement() {
    const items = searchOptionElements();
    const index = Number.isInteger(ui.searchActiveIndex) ? ui.searchActiveIndex : -1;
    return index >= 0 && index < items.length ? items[index] : null;
  }

  // Reflète l'option active dans le DOM et l'expose aux technologies d'assistance
  // (aria-selected sur l'option, aria-activedescendant sur le champ combobox).
  function syncSearchActiveOption() {
    const items = searchOptionElements();
    const active = activeSearchOptionElement();
    items.forEach((item) => {
      const isActive = item === active;
      item.classList.toggle("is-active", isActive);
      item.setAttribute("aria-selected", isActive ? "true" : "false");
    });
    const input = app.querySelector(".search-page-form [data-global-search]");
    if (!input) return;
    input.setAttribute("aria-expanded", items.length ? "true" : "false");
    if (active && active.id) input.setAttribute("aria-activedescendant", active.id);
    else input.removeAttribute("aria-activedescendant");
    if (active) active.scrollIntoView({ block: "nearest" });
  }

  // Déplacement circulaire dans la liste. Le focus RESTE dans le champ de saisie : on ne
  // déplace qu'un curseur virtuel, ce qui évite tout piège de focus et garde la frappe fluide.
  function moveSearchActiveOption(step) {
    const items = searchOptionElements();
    if (!items.length) return;
    const current = Number.isInteger(ui.searchActiveIndex) ? ui.searchActiveIndex : -1;
    let next = current + step;
    if (next < 0) next = items.length - 1;
    if (next >= items.length) next = 0;
    ui.searchActiveIndex = next;
    syncSearchActiveOption();
  }

  function renderHistory() {
    const rows = normalizeActivityLog(state.activityLog).slice().reverse();
    const expanded = new Set(ui.historyExpandedRows || []);
    return `<div class="band">
      <div class="band-title">
        <div><h2>Historique des actions</h2><p class="muted">Les dernières modifications importantes enregistrées dans le logiciel.</p></div>
        <button class="danger" type="button" data-action="clear-history" ${rows.length ? "" : "disabled"}>Effacer l'historique</button>
      </div>
      ${rows.length ? `<div class="table-wrap"><table class="editable-table">
        <thead><tr><th>Date</th><th>Page</th><th>Action</th></tr></thead>
        <tbody>${rows.map((row) => {
          const open = expanded.has(row.id);
          return `<tr class="history-row ${open ? "expanded" : ""}" data-action="toggle-history-row" data-id="${esc(row.id)}" title="Cliquez ici pour voir le reste du texte"><td>${esc(formatDateTimeLocal(row.at))}</td><td>${esc(row.view || "-")}</td><td class="history-action-text">${esc(row.message)}</td></tr>`;
        }).join("")}</tbody>
      </table></div>` : `<div class="empty">Aucune action enregistrée pour le moment.</div>`}
    </div>`;
  }

  // Lot E-mails — Relance paiement 1a. Destinataire d'une relance pour un membre mineur :
  // si un responsable légal est déclaré (même condition que la facturation, cf.
  // contactInvoiceSnapshot), la relance lui est adressée à SON e-mail plutôt qu'à celui —
  // souvent absent — de l'enfant, pour éviter qu'il disparaisse silencieusement de la liste.
  function paymentReminderRecipient(contact) {
    if (memberCategory(contact) === "Enfant" && asText(contact.legalGuardianName)) {
      return {
        id: `guardian-${contact.id}`,
        lastName: `${asText(contact.legalGuardianName)} (resp. ${personLabel(contact)})`,
        firstName: "",
        email: asText(contact.legalGuardianEmail),
        newsletterSource: "contact",
      };
    }
    return contact;
  }

  // Contacts à relancer pour paiement (audience E-mails "late"). Périmètre aligné sur
  // À faire V2 : strictement en retard/refusé (paymentIsLate exclut déjà "À encaisser" non
  // dépassé), PLUS les factures en retard non couvertes par une alerte paiement source
  // (même règle de déduplication par sourceId que taskRows, réutilisée via
  // invoiceIsCoveredBySourcePaymentAlert plutôt que reproduite). Dédupliqué par contact via
  // un seul Set de clés — un contact avec plusieurs dettes n'apparaît qu'une fois.
  function contactsForPaymentReminders() {
    const flaggedKeys = new Set();
    const flag = (payments, contactId, prospectId) => {
      if (!(payments || []).some((payment) => paymentIsLate(payment))) return;
      if (contactId) flaggedKeys.add(`member:${contactId}`);
      if (prospectId) flaggedKeys.add(`prospect:${prospectId}`);
    };
    (state.memberships || []).forEach((row) => flag(row.payments, row.contactId, row.prospectContactId));
    (state.shopOrders || []).forEach((row) => flag(row.payments, row.contactId, row.prospectContactId));
    Object.values(state.stageRegistrations || {}).forEach((rows) => {
      (rows || []).forEach((row) => {
        const payments = [...(row.event?.payments || []), ...(row.lodging?.payments || [])];
        flag(payments, row.contactId, row.prospectContactId);
      });
    });
    const alertingPaymentRows = paymentAgendaRows(null).filter((row) => {
      const isLate = row.date && row.date < dateInputValue(new Date());
      return row.status === "Refusé" || isLate;
    });
    (state.invoices || []).forEach((invoice) => {
      if (!invoiceIsLate(invoice)) return;
      if (invoiceIsCoveredBySourcePaymentAlert(invoice, alertingPaymentRows)) return;
      const kind = (typeof contactInvoiceKind === "function") ? contactInvoiceKind(invoice.contactSnapshot?.kind) : "members";
      const cid = asText(invoice.contactSnapshot?.id);
      if (cid) flaggedKeys.add(`${kind === "prospects" ? "prospect" : "member"}:${cid}`);
    });
    const result = [];
    (state.contacts.members || []).forEach((contact) => {
      if (flaggedKeys.has(`member:${contact.id}`)) result.push(paymentReminderRecipient(contact));
    });
    (state.contacts.prospects || []).forEach((contact) => {
      if (flaggedKeys.has(`prospect:${contact.id}`)) result.push(contact);
    });
    return result;
  }

  // Source de destinataires selon le public choisi (objets normalisés {email, lastName, firstName}).
  // Coachs/salles : uniquement ACTIFS du club actif (multi-club respecté via state.coaches/state.rooms).
  function roomManagerRecipient(room) {
    return { id: `room-${room.id}`, lastName: asText(room.managerName) || roomName(room), firstName: "", email: asText(room.managerEmail), newsletterSource: "room", roomName: roomName(room) };
  }
  // Membres d'un groupe = contacts liés aux inscriptions dont groupId === groupe (source de vérité
  // unique : membership.groupId). On retrouve le contact via contactForMembership puis on déduplique
  // par contactId (puis e-mail / identité) pour qu'un membre à plusieurs inscriptions n'apparaisse
  // qu'une fois. Multi-club : state.memberships / state.contacts = club actif.
  function groupMembershipContacts(groupId) {
    if (!groupId) return [];
    const memberships = (state.memberships || []).filter((m) => m.groupId === groupId);
    const seen = new Set();
    const out = [];
    memberships.forEach((membership) => {
      const contact = (typeof contactForMembership === "function") ? contactForMembership(membership) : null;
      const row = contact || membership;
      const key = asText(contact && contact.id)
        || normalizedPersonText(asText(row.email))
        || personKey(row);
      if (!key || seen.has(key)) return;
      seen.add(key);
      out.push({ ...row, newsletterSource: "contact" });
    });
    return out;
  }
  function newsletterAudienceSource(audience = ui.newsletterAudience) {
    if (audience === "coaches") return { source: (typeof activeCoaches === "function" ? activeCoaches() : []), sourceTag: "coach" };
    if (audience === "coaches-selected") {
      // Coachs explicitement choisis : inclus même si archivés (la liste de cases n'offre
      // que des actifs, mais un e-mail préparé depuis une alerte peut viser un coach archivé).
      const ids = new Set(ui.newsletterCoachIds || []);
      return { source: (state.coaches || []).filter((c) => ids.has(c.id)), sourceTag: "coach" };
    }
    if (audience === "room-managers") return { source: (typeof activeRooms === "function" ? activeRooms() : []).map(roomManagerRecipient), sourceTag: "room" };
    if (audience === "room-manager-selected") {
      const room = (typeof roomById === "function") ? roomById(ui.newsletterRoomId) : null;
      return { source: room ? [roomManagerRecipient(room)] : [], sourceTag: "room" };
    }
    if (audience === "group-members") {
      const group = (typeof getGroupById === "function") ? getGroupById(ui.newsletterGroupId) : null;
      return { source: group ? groupMembershipContacts(group.id) : [], sourceTag: "contact" };
    }
    if (audience === "late") return { source: contactsForPaymentReminders(), sourceTag: "contact" };
    if (audience === "prospects") return { source: state.contacts.prospects, sourceTag: "contact" };
    if (audience === "all") return { source: [...state.contacts.members, ...state.contacts.prospects], sourceTag: "contact" };
    return { source: state.contacts.members, sourceTag: "contact" };
  }

  // Coachs / responsables de salle SANS e-mail dans le public courant (affichés à part).
  function newsletterMissingEmailNames(audience = ui.newsletterAudience) {
    if (audience === "coaches" || audience === "coaches-selected") {
      const ids = audience === "coaches-selected" ? new Set(ui.newsletterCoachIds || []) : null;
      return (typeof activeCoaches === "function" ? activeCoaches() : [])
        .filter((c) => !ids || ids.has(c.id))
        .filter((c) => !asText(c.email))
        .map((c) => coachFullName(c));
    }
    if (audience === "room-managers" || audience === "room-manager-selected") {
      let rooms = (typeof activeRooms === "function" ? activeRooms() : []);
      if (audience === "room-manager-selected") { const r = (typeof roomById === "function") ? roomById(ui.newsletterRoomId) : null; rooms = r && !r.archived ? [r] : []; }
      return rooms.filter((r) => !asText(r.managerEmail)).map((r) => `${roomName(r)}${asText(r.managerName) ? " (" + asText(r.managerName) + ")" : ""}`);
    }
    if (audience === "group-members") {
      const group = (typeof getGroupById === "function") ? getGroupById(ui.newsletterGroupId) : null;
      if (!group) return [];
      return groupMembershipContacts(group.id).filter((c) => !asText(c.email)).map((c) => personLabel(c));
    }
    // Lot E-mails — Relance paiement 1a : un contact en retard sans e-mail exploitable
    // (le sien, ou celui d'un responsable légal) doit rester visible ici plutôt que
    // disparaître silencieusement de la sélection.
    if (audience === "late") {
      return contactsForPaymentReminders().filter((c) => !asText(c.email)).map((c) => personLabel(c));
    }
    return [];
  }

  function newsletterRecipients(audience = ui.newsletterAudience) {
    if (ui.newsletterManualOnly) {
      const seen = new Set();
      return (Array.isArray(ui.newsletterExtraEmails) ? ui.newsletterExtraEmails : [])
        .map((email) => asText(email))
        .filter(Boolean)
        .filter((email) => {
          const key = normalizedPersonText(email);
          if (!key || seen.has(key)) return false;
          seen.add(key);
          return true;
        })
        .map((email) => ({ id: `newsletter-manual-${normalizedPersonText(email)}`, lastName: "Adresse libre", firstName: "", email, newsletterSource: "extra" }));
    }
    const { source, sourceTag } = newsletterAudienceSource(audience);
    const seen = new Set();
    const excluded = new Set((ui.newsletterExcludedEmails || []).map((email) => normalizedPersonText(email)).filter(Boolean));
    const contacts = source
      .filter((contact) => asText(contact.email))
      .filter((contact) => {
        const key = normalizedPersonText(contact.email);
        if (excluded.has(key)) return false;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .map((contact) => ({ ...contact, newsletterSource: contact.newsletterSource || sourceTag }));
    const extras = (Array.isArray(ui.newsletterExtraEmails) ? ui.newsletterExtraEmails : [])
      .map((email) => asText(email))
      .filter(Boolean)
      .filter((email) => {
        const key = normalizedPersonText(email);
        if (!key || excluded.has(key) || seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .map((email) => ({ id: `newsletter-extra-${normalizedPersonText(email)}`, lastName: "Adresse libre", firstName: "", email, newsletterSource: "extra" }));
    return [...contacts, ...extras].sort((a, b) => personKey(a).localeCompare(personKey(b)));
  }

  function addNewsletterEmail(email) {
    const values = asText(email)
      .split(/[\s,;]+/)
      .map((item) => item.trim())
      .filter(Boolean);
    const valid = values.filter((item) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(item));
    if (!valid.length) {
      alert("Indique une ou plusieurs adresses e-mail valides.");
      return;
    }
    recordHistory();
    valid.forEach((value) => {
      const key = normalizedPersonText(value);
      ui.newsletterExcludedEmails = (ui.newsletterExcludedEmails || []).filter((item) => normalizedPersonText(item) !== key);
      const alreadyInContacts = [...state.contacts.members, ...state.contacts.prospects].some((contact) => normalizedPersonText(contact.email) === key);
      if ((ui.newsletterManualOnly || !alreadyInContacts)
        && !(ui.newsletterExtraEmails || []).some((item) => normalizedPersonText(item) === key)) {
        ui.newsletterExtraEmails = [...(ui.newsletterExtraEmails || []), value];
      }
    });
    ui.newsletterNewEmail = "";
    render();
  }

  function removeNewsletterEmail(email) {
    const key = normalizedPersonText(email);
    if (!key) return;
    recordHistory();
    ui.newsletterExtraEmails = (ui.newsletterExtraEmails || []).filter((item) => normalizedPersonText(item) !== key);
    if (![...state.contacts.members, ...state.contacts.prospects].some((contact) => normalizedPersonText(contact.email) === key)) {
      render();
      return;
    }
    if (!(ui.newsletterExcludedEmails || []).some((item) => normalizedPersonText(item) === key)) {
      ui.newsletterExcludedEmails = [...(ui.newsletterExcludedEmails || []), email];
    }
    render();
  }

  function newsletterAudienceLabel(audience = ui.newsletterAudience) {
    if (ui.newsletterManualOnly) return "saisie manuelle";
    if (audience === "prospects") return "non-adhérents";
    if (audience === "all") return "adhérents et non-adhérents";
    if (audience === "late") return "rappels de paiement dépassés";
    if (audience === "coaches") return "coachs actifs";
    if (audience === "coaches-selected") return "coachs sélectionnés";
    if (audience === "room-managers") return "responsables de salles";
    if (audience === "room-manager-selected") return "responsable de la salle choisie";
    if (audience === "group-members") {
      const group = (typeof getGroupById === "function") ? getGroupById(ui.newsletterGroupId) : null;
      return group ? `membres du groupe ${asText(group.name)}` : "membres d'un groupe";
    }
    return "adhérents";
  }

  function defaultNewsletterDate() {
    return dateDisplay(dateInputValue(new Date()));
  }

  function defaultNewsletterDetail() {
    return "Le stage aura lieu au dojo du club. Prévoir une tenue de sport, une gourde et les protections habituelles.\n\nLes places peuvent être limitées. Pensez à confirmer votre présence.";
  }

  function selectedNewsletterTemplateKey() {
    const defs = configurableEmailTemplateDefinitions();
    const selected = defs[ui.newsletterTemplateKey] ? ui.newsletterTemplateKey : "newsletter";
    ui.newsletterTemplateKey = defs[selected] ? selected : Object.keys(defs)[0] || "newsletter";
    return ui.newsletterTemplateKey;
  }

  function emailPageTemplateOptions(selected = selectedNewsletterTemplateKey()) {
    return Object.entries(configurableEmailTemplateDefinitions()).map(([key, def]) => (
      `<option value="${esc(key)}" ${key === selected ? "selected" : ""}>${esc(def.label)}</option>`
    )).join("");
  }

  function renderTextTemplateWithContext(text = "", context = {}) {
    const safeContext = { ...emptyEmailContext(), ...sanitizeTemplateContext(context) };
    return asText(text).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, key) => (
      Object.prototype.hasOwnProperty.call(safeContext, key) ? safeContext[key] : ""
    ));
  }

  // Contexte de séance (variables planning) à partir d'un créneau + période/statut éventuels.
  function sessionContextFromCourse(course = {}, periodStart = "", periodEnd = "", statut = "") {
    // periodStart/periodEnd sont la fenêtre d'indisponibilité du coach (ex. "du 06/07 au
    // 13/07"), PAS la date de la séance : on cherche la date réelle du jour de la semaine du
    // cours à l'intérieur de cette fenêtre (occurrence exacte), sinon on retombe sur l'ancien
    // comportement (début de la fenêtre, ou juste le nom du jour si aucune période fournie).
    const occurrence = (periodStart && typeof courseOccurrenceDateInPeriod === "function")
      ? courseOccurrenceDateInPeriod(course, periodStart, periodEnd)
      : null;
    return {
      discipline: asText(course.discipline),
      dateSeance: occurrence ? dateDisplay(occurrence) : (periodStart ? dateDisplay(periodStart) : asText(course.day)),
      heureDebut: asText(course.startTime),
      heureFin: asText(course.endTime),
      lieu: (typeof courseRoomLabel === "function" ? courseRoomLabel(course) : asText(course.location)),
      statutSeance: asText(statut),
    };
  }

  // Prépare (sans envoyer) un e-mail sur la page E-mail : public + coach/salle + modèle +
  // contexte séance. Réutilise entièrement la page E-mail, les publics et les modèles.
  // Respecte le club actif (coachById/roomById = club actif). N'ouvre jamais d'adresse vide.
  function prepareEntityEmail(opts = {}) {
    const coachId = asText(opts.coachId);
    const roomId = asText(opts.roomId);
    const groupId = asText(opts.groupId);
    const templateKey = asText(opts.templateKey);
    let trace = "E-mail préparé";
    if (groupId) {
      const group = (typeof getGroupById === "function") ? getGroupById(groupId) : null;
      if (!group) return;
      const withEmail = groupMembershipContacts(group.id).filter((c) => asText(c.email));
      if (!withEmail.length) { alert("Aucun membre de ce groupe n'a d'adresse e-mail renseignée."); return; }
      recordHistory();
      ui.newsletterManualOnly = false;
      ui.newsletterAudience = "group-members";
      ui.newsletterGroupId = groupId;
      ui.newsletterCoachIds = [];
      ui.newsletterRoomId = "";
      trace = `E-mail préparé pour le groupe ${asText(group.name)}`;
    } else if (coachId) {
      const coach = (typeof coachById === "function") ? coachById(coachId) : null;
      if (!coach) return;
      if (!asText(coach.email)) { alert("Ce coach n'a pas d'adresse e-mail renseignée."); return; }
      recordHistory();
      ui.newsletterManualOnly = false;
      ui.newsletterAudience = "coaches-selected";
      ui.newsletterCoachIds = [coachId];
      ui.newsletterRoomId = "";
      trace = `E-mail préparé pour le coach ${coachFullName(coach)}`;
    } else if (roomId) {
      const room = (typeof roomById === "function") ? roomById(roomId) : null;
      if (!room) return;
      if (!asText(room.managerEmail)) { alert("Le responsable de cette salle n'a pas d'adresse e-mail renseignée."); return; }
      recordHistory();
      ui.newsletterManualOnly = false;
      ui.newsletterAudience = "room-manager-selected";
      ui.newsletterRoomId = roomId;
      ui.newsletterCoachIds = [];
      trace = `E-mail préparé pour le responsable de la salle ${roomName(room)}`;
    } else {
      return;
    }
    if (templateKey) ui.newsletterTemplateKey = templateKey;
    ui.newsletterSubject = "";
    ui.newsletterBody = "";
    const course = opts.courseId ? (state.planningCourses || []).find((c) => c.id === opts.courseId) : null;
    ui.newsletterSessionContext = course ? sessionContextFromCourse(course, asText(opts.periodStart), asText(opts.periodEnd), asText(opts.statut)) : {};
    if (course) trace += ` — séance ${asText(course.name)}`;
    [...document.querySelectorAll("dialog[open]")].forEach((d) => d.close());
    navigateToViewFromMenu("newsletter");
    persist(trace);
  }

  function newsletterTemplateValues(templateKey = selectedNewsletterTemplateKey()) {
    const place = asText(ui.newsletterPlace || "Dojo du club");
    const savedCustom = customEmailTemplateContext(templateKey);
    const isNewsletter = templateKey === "newsletter";
    // Contexte coach/salle : rempli quand UNE seule entité est ciblée (aperçu personnalisé).
    // Pour un envoi groupé, ces variables restent vides (chaîne vide propre).
    const aud = ui.newsletterManualOnly ? "manual" : (ui.newsletterAudience || "members");
    let entityContext = {};
    if (aud === "room-manager-selected" && typeof roomById === "function") {
      const room = roomById(ui.newsletterRoomId);
      if (room) entityContext = roomEmailContext(room);
    } else if (aud === "coaches-selected" && (ui.newsletterCoachIds || []).length === 1 && typeof coachById === "function") {
      const coach = coachById(ui.newsletterCoachIds[0]);
      if (coach) entityContext = coachEmailContext(coach);
    } else if (aud === "group-members" && typeof getGroupById === "function") {
      const group = getGroupById(ui.newsletterGroupId);
      if (group) entityContext = groupEmailContext(group);
    }
    return {
      ...clubEmailContext(),
      ...entityContext,
      ...savedCustom,
      titre: asText(ui.newsletterTitle) || savedCustom.titre || (isNewsletter ? "Stage découverte self-défense" : ""),
      detail: asText(ui.newsletterDetail) || savedCustom.detail || (isNewsletter ? defaultNewsletterDetail() : ""),
      message: asText(ui.newsletterMessage) || savedCustom.message || "",
      note: asText(ui.newsletterNote) || savedCustom.note || "",
      complement: asText(ui.newsletterComplement) || savedCustom.complement || "",
      signatureLibre: asText(ui.newsletterSignatureLibre) || savedCustom.signatureLibre || "",
      public: newsletterAudienceLabel(),
      date: asText(ui.newsletterDate) || defaultNewsletterDate(),
      lieu: place,
      // Contexte de séance (depuis une fiche/alerte) — en dernier pour remplir discipline/dateSeance/
      // heureDebut/heureFin/statutSeance et, si fourni, surcharger {lieu} par le lieu réel de la séance.
      ...Object.fromEntries(Object.entries(ui.newsletterSessionContext || {}).filter(([, v]) => asText(v) !== "")),
    };
  }

  function newsletterSubject() {
    const templateKey = selectedNewsletterTemplateKey();
    const template = emailTemplates()[templateKey] || configurableEmailTemplateDefinitions()[templateKey] || {};
    if (asText(ui.newsletterSubject)) return ui.newsletterSubject;
    return renderTextTemplateWithContext(template.subject || "", newsletterTemplateValues(templateKey));
  }

  function newsletterBody() {
    const templateKey = selectedNewsletterTemplateKey();
    const template = emailTemplates()[templateKey] || configurableEmailTemplateDefinitions()[templateKey] || {};
    if (asText(ui.newsletterBody)) return ui.newsletterBody;
    return renderTextTemplateWithContext(template.body || "", newsletterTemplateValues(templateKey));
  }

  function emailPageCustomFieldsHtml(templateKey = selectedNewsletterTemplateKey()) {
    const def = configurableEmailTemplateDefinitions()[templateKey] || {};
    const template = emailTemplates()[templateKey] || {};
    const sourceText = `${def.variables || ""} ${template.subject || ""} ${template.body || ""}`;
    const hasVar = (name) => new RegExp(`\\{${name}\\}`, "i").test(sourceText);
    const rows = [];
    if (hasVar("titre")) rows.push(["title", "Titre", "titre", "input", asText(ui.newsletterTitle) || (templateKey === "newsletter" ? "Stage découverte self-défense" : "")]);
    if (hasVar("date")) rows.push(["date", "Date affichée", "date", "input", asText(ui.newsletterDate) || defaultNewsletterDate()]);
    if (hasVar("lieu")) rows.push(["place", "Lieu", "lieu", "input", asText(ui.newsletterPlace) || "Dojo du club"]);
    if (hasVar("detail")) rows.push(["detail", "Détail personnalisé", "detail", "textarea", asText(ui.newsletterDetail) || (templateKey === "newsletter" ? defaultNewsletterDetail() : "")]);
    if (hasVar("message")) rows.push(["message", "Message personnalisé", "message", "textarea", asText(ui.newsletterMessage)]);
    if (hasVar("note")) rows.push(["note", "Note", "note", "textarea", asText(ui.newsletterNote)]);
    if (hasVar("complement")) rows.push(["complement", "Complément", "complement", "textarea", asText(ui.newsletterComplement)]);
    if (hasVar("signatureLibre")) rows.push(["signatureLibre", "Signature libre", "signatureLibre", "textarea", asText(ui.newsletterSignatureLibre)]);
    if (!rows.length) return `<div class="newsletter-variable-fields muted-panel"><strong>Champs du modèle</strong><p class="muted">Ce modèle n'utilise pas de variable personnalisable visible sur cette page.</p></div>`;
    return `<div class="newsletter-variable-fields">
      <p class="muted">Les champs ci-dessous alimentent les variables du modèle. Les variables automatiques viennent du contact, du club ou du paiement quand le contexte existe.</p>
      <div class="form-grid compact">
        ${rows.map(([field, label, variable, type, value]) => type === "textarea"
          ? `<label>${esc(label)} <small>{${esc(variable)}}</small><textarea rows="4" data-newsletter-field="${esc(field)}">${esc(value)}</textarea></label>`
          : `<label>${esc(label)} <small>{${esc(variable)}}</small><input type="text" data-newsletter-field="${esc(field)}" value="${esc(value)}" /></label>`).join("")}
      </div>
    </div>`;
  }

  function renderNewsletter() {
    if (ui.smtpSecretStatus === undefined && typeof refreshSmtpSecretStatus === "function") {
      ui.smtpSecretStatus = { present: false, secure: false };
      refreshSmtpSecretStatus().then(() => render());
    }
    const recipients = newsletterRecipients();
    const missingMembers = state.contacts.members.filter((contact) => !asText(contact.email)).length;
    const missingProspects = state.contacts.prospects.filter((contact) => !asText(contact.email)).length;
    const templateKey = selectedNewsletterTemplateKey();
    const templateDef = configurableEmailTemplateDefinitions()[templateKey] || {};
    const audience = ui.newsletterManualOnly ? "manual" : (ui.newsletterAudience || "members");
    const audienceOption = (value, label) => `<option value="${value}" ${audience === value ? "selected" : ""}>${esc(label)}</option>`;
    const missingEmailNames = newsletterMissingEmailNames();
    // Lot E-mails — Relance paiement 1b : résumé explicite uniquement pour l'audience
    // "late" (relance paiement), pour que la sélection soit compréhensible d'un coup
    // d'œil sans devoir se souvenir du sens du sélecteur "Public" ci-dessus. Recalculé à
    // chaque rendu (mêmes données que la liste juste en dessous) : reste à jour après
    // décoche / réaffichage sans logique de sélection supplémentaire.
    const recipientsSummary = ui.newsletterAudience === "late"
      ? `${intValue(recipients.length)} contact${recipients.length > 1 ? "s" : ""} avec paiement en retard sélectionné${recipients.length > 1 ? "s" : ""}`
      : `${intValue(recipients.length)} destinataire${recipients.length > 1 ? "s" : ""}`;
    return `<div class="newsletter-page">
      ${kpis([
        { label: "Destinataires", value: recipients.length },
        { label: "Adhérents sans e-mail", value: missingMembers },
        { label: "Non-adhérents sans e-mail", value: missingProspects },
        { label: "Public", value: newsletterAudienceLabel() },
      ])}
      <div class="grid two">
        <div class="band pad newsletter-composer">
          <div class="band-title">
            <div><h2>Préparer un e-mail</h2><p class="muted">Préparez vos newsletters, relances et messages personnalisés à partir des modèles configurés.</p></div>
          </div>
          <label>Destinataires
            <select data-newsletter-field="audience">
              <optgroup label="Contacts du club">
                ${audienceOption("members", "Tous les adhérents")}
                ${audienceOption("prospects", "Tous les non-adhérents")}
                ${audienceOption("all", "Tout le monde")}
                ${audienceOption("late", "Rappels de paiement dépassés")}
              </optgroup>
              <optgroup label="Coachs">
                ${audienceOption("coaches", "Tous les coachs actifs")}
                ${audienceOption("coaches-selected", "Coachs sélectionnés")}
              </optgroup>
              <optgroup label="Salles">
                ${audienceOption("room-managers", "Responsables de salles")}
                ${audienceOption("room-manager-selected", "Responsable de la salle sélectionnée")}
              </optgroup>
              <optgroup label="Groupes">
                ${audienceOption("group-members", "Membres d'un groupe")}
              </optgroup>
              <optgroup label="Libre">
                ${audienceOption("manual", "Libre / saisie manuelle uniquement")}
              </optgroup>
            </select>
          </label>
          ${audience === "coaches-selected" ? `<div class="newsletter-picker"><span class="muted">Coachs à inclure :</span>${(typeof activeCoaches === "function" ? activeCoaches() : []).map((c) => `<label class="form-check"><input type="checkbox" data-newsletter-coach="${esc(c.id)}" ${(ui.newsletterCoachIds || []).includes(c.id) ? "checked" : ""} ${asText(c.email) ? "" : "disabled"}/> ${esc(coachFullName(c))}${asText(c.email) ? "" : " (sans e-mail)"}</label>`).join("") || `<span class="muted">Aucun coach actif.</span>`}</div>` : ""}
          ${audience === "room-manager-selected" ? `<label>Salle concernée<select data-newsletter-room><option value="">— Choisir une salle —</option>${(typeof activeRooms === "function" ? activeRooms() : []).map((r) => `<option value="${esc(r.id)}" ${ui.newsletterRoomId === r.id ? "selected" : ""}>${esc(roomName(r))}${asText(r.managerEmail) ? "" : " (responsable sans e-mail)"}</option>`).join("")}</select></label>` : ""}
          ${audience === "group-members" ? `<label>Groupe<select data-newsletter-group><option value="">— Choisir un groupe —</option>${(state.groups || []).filter((g) => !g.archived).map((g) => { const count = (typeof getMembersByGroup === "function") ? getMembersByGroup(g.id).length : 0; const label = [asText(g.name), asText(g.discipline)].filter(Boolean).join(" — ") + ` — ${count} membre${count > 1 ? "s" : ""}`; return `<option value="${esc(g.id)}" ${ui.newsletterGroupId === g.id ? "selected" : ""}>${esc(label)}</option>`; }).join("") || ""}</select>${(state.groups || []).filter((g) => !g.archived).length ? "" : `<span class="muted">Aucun groupe dans ce club. Crée un groupe dans Activités &gt; Groupes.</span>`}</label>` : ""}
          <label>Modèle d'e-mail
            <select data-newsletter-field="templateKey">
              ${emailPageTemplateOptions(templateKey)}
            </select>
          </label>
          <div class="inline-actions">
            <button type="button" data-action="edit-current-email-template">Modifier ce modèle</button>
            <button type="button" data-action="open-payment-reminders">Relances paiement</button>
          </div>
          <p class="muted">Modèle sélectionné : ${esc(templateDef.label || "Modèle")} · Les modèles se configurent dans Paramètres > Messages e-mail.</p>
          ${emailPageCustomFieldsHtml(templateKey)}
          <label>Objet
            <input type="text" data-newsletter-field="subject" value="${esc(newsletterSubject())}" />
          </label>
          <label>Message
            <textarea rows="13" data-newsletter-field="body">${esc(newsletterBody())}</textarea>
          </label>
          <div class="newsletter-paper">${newsletterPreviewInnerHtml()}</div>
          <div class="inline-actions">
            <button ${smtpReadyForSend() ? "" : `class="primary"`} type="button" data-action="open-newsletter-mail">Ouvrir la messagerie externe</button>
            ${smtpReadyForSend() ? `<button class="primary" type="button" data-action="send-newsletter-mail-integrated" ${ui.smtpSending ? "disabled" : ""}>${ui.smtpSending ? "Envoi en cours…" : "Envoyer depuis MonGestaClub"}</button>` : ""}
            <button type="button" data-action="copy-newsletter-emails">Copier les e-mails</button>
            <button type="button" data-action="copy-newsletter-message">Copier le message</button>
            <button type="button" data-action="reset-newsletter-template">Recharger le modèle</button>
            <button type="button" data-action="open-payment-reminders">Relances paiement</button>
          </div>
          ${smtpReadyForSend() ? "" : `<p class="muted smtp-hint">Envoi intégré non configuré. Configurez le SMTP dans Paramètres &gt; E-mails, ou utilisez le bouton « Ouvrir la messagerie externe » ci-dessus.</p>`}
          <p class="muted mailto-logo-hint">La messagerie externe prépare un message texte : la mise en page et le logo du club ne sont pas inclus.</p>
          <p class="muted">Les adresses sont placées en copie cachée pour préserver la confidentialité. Pour de très grosses listes, il vaut mieux envoyer en plusieurs fois.</p>
        </div>
        <div class="band pad newsletter-recipients-panel">
          <div class="band-title">
            <div><h2>Contacts sélectionnés</h2><p class="muted">Liste utilisée pour l'envoi en copie cachée.</p></div>
            <strong>${esc(recipientsSummary)}</strong>
          </div>
          <div class="newsletter-add-email">
            <textarea rows="3" data-newsletter-field="newEmail" placeholder="Écris une ou plusieurs adresses, séparées par virgule, point-virgule, espace ou retour à la ligne">${esc(ui.newsletterNewEmail || "")}</textarea>
            <button type="button" data-action="add-newsletter-email">Ajouter</button>
          </div>
          <div class="inline-actions">
            <button type="button" data-action="restore-newsletter-recipients" ${ui.newsletterExcludedEmails?.length ? "" : "disabled"}>Réafficher les contacts retirés</button>
          </div>
          ${recipients.length ? `<div class="newsletter-recipient-list">
            ${recipients.map((contact) => `<div class="${contact.newsletterSource === "extra" ? "is-extra" : ""}"><strong>${esc(contact.newsletterSource === "extra" ? contact.email : personLabel(contact))}</strong><span>${esc(contact.newsletterSource === "extra" ? "Adresse ajoutée manuellement" : contact.email)}</span><button type="button" class="icon danger" data-action="remove-newsletter-email" data-email="${esc(contact.email)}" title="Retirer de cet envoi">×</button></div>`).join("")}
          </div>` : `<div class="empty">Aucun e-mail disponible pour ce public.</div>`}
          ${missingEmailNames.length ? `<p class="muted newsletter-missing">⚠ Sans e-mail (non inclus) : ${esc(missingEmailNames.join(", "))}</p>` : ""}
        </div>
      </div>
    </div>`;
  }

  // Aperçu HTML "carte e-mail" (Lot 2) + texte brut conservé (utilisé pour mailto/copie,
  // inchangé). Factorisé pour être identique au premier rendu et lors des mises à jour en
  // direct (updateNewsletterPreview), sans dupliquer le calcul.
  function newsletterPreviewInnerHtml() {
    const subject = newsletterSubject();
    const bodyText = newsletterBody();
    const html = renderEmailHtml(subject, bodyText, { context: newsletterTemplateValues() });
    return `<span>Aperçu de l'e-mail</span>
      <iframe title="Aperçu de l'e-mail" sandbox="" style="width:100%;height:420px;border:1px solid var(--line);border-radius:8px;background:#eef0f2;margin-top:4px" srcdoc="${esc(html)}"></iframe>
      <details style="margin-top:8px;font-size:.86rem;color:var(--muted)">
        <summary>Texte brut (utilisé pour l'ouverture de la messagerie et la copie)</summary>
        <pre style="white-space:pre-wrap;font-family:inherit;margin:8px 0 0;padding:8px;background:var(--surface-3);border-radius:6px;color:inherit">${esc(subject)}

${esc(bodyText)}</pre>
      </details>`;
  }

  function updateNewsletterPreview() {
    const paper = app.querySelector(".newsletter-paper");
    if (!paper) return;
    paper.innerHTML = newsletterPreviewInnerHtml();
  }

  function updateNewsletterGeneratedFields() {
    const subjectInput = app.querySelector('[data-newsletter-field="subject"]');
    const bodyInput = app.querySelector('[data-newsletter-field="body"]');
    if (subjectInput && !asText(ui.newsletterSubject)) subjectInput.value = newsletterSubject();
    if (bodyInput && !asText(ui.newsletterBody)) bodyInput.value = newsletterBody();
    updateNewsletterPreview();
  }

  function newsletterEmailList() {
    return newsletterRecipients().map((contact) => contact.email).join(",");
  }

  function newsletterMailtoHref() {
    const emails = newsletterEmailList();
    if (!emails) return "";
    return `mailto:?bcc=${encodeURIComponent(emails)}&subject=${encodeURIComponent(newsletterSubject())}&body=${encodeURIComponent(newsletterBody())}`;
  }

  async function copyTextToClipboard(text, message) {
    if (!asText(text)) return;
    try {
      await navigator.clipboard.writeText(text);
      ui.saveMessage = message;
      render();
    } catch (error) {
      alert(text);
    }
  }

  function signalList(rows, emptyLabel) {
    if (!rows.length) return `<div class="empty">${esc(emptyLabel)}</div>`;
    return `<div class="signal-list payment-signal-list">
      ${rows.map((row) => `<button class="signal-row" data-action="${esc(row.editAction)}" data-id="${esc(row.id)}" ${row.stageId ? `data-stage-id="${esc(row.stageId)}"` : ""}>
        <span>${esc(row.module)}</span>
        ${personCell(row.person)}
        ${statusPill(row.status)}
        <strong>${money(row.amount)}</strong>
      </button>`).join("")}
    </div>`;
  }

  function stockSignalList(rows) {
    if (!rows.length) return `<div class="empty">Aucun stock en alerte</div>`;
    return `<div class="signal-list">
      ${rows.slice(0, 8).map((row) => `<button class="signal-row stock-signal-row ${stockAlertTone(row)}" data-action="edit-stock-article" data-index="${row.index}">
        <strong class="stock-signal-name">${esc(row.article.name)}</strong>
        <span class="stock-signal-current">Actuel ${intValue(row.available)}</span>
        <span class="stock-signal-threshold">Seuil ${intValue(row.article.stockAlert)}</span>
      </button>`).join("")}
    </div>`;
  }

  function openPaymentAgendaDialog() {
    const rows = paymentAgendaRows();
    const total = rows.reduce((sum, row) => sum + asNumber(row.amount), 0);
    const body = rows.length
      ? `<div class="dialog-table-wrap"><div class="dialog-table-scroll"><table>
          <thead><tr><th>Module</th><th>Personne</th><th>Statut</th><th>Date</th><th class="money">Reste dû</th><th></th></tr></thead>
          <tbody>${rows.map((row) => `<tr class="clickable-row" data-agenda-action="${esc(row.editAction)}" data-id="${esc(row.id)}" ${row.stageId ? `data-stage-id="${esc(row.stageId)}"` : ""}>
            <td>${esc(row.module)}</td>
            <td>${personCell(row.person)}</td>
            <td>${statusPill(row.status)}</td>
            <td>${dateDisplay(row.date) || `<span class="muted">Non daté</span>`}</td>
            <td class="money">${money(row.amount)}</td>
            <td><button class="icon" type="button" title="Modifier l'encaissement">✎</button></td>
          </tr>`).join("")}</tbody>
        </table></div></div>`
      : `<div class="empty">Aucun encaissement à suivre</div>`;
    showInfoDialog("À encaisser", `<div class="agenda-dialog">
      <div class="kpi"><span>Total à suivre</span><strong>${money(total)}</strong></div>
      ${body}
    </div>`);
    dialog.querySelectorAll("[data-agenda-action]").forEach((row) => {
      row.addEventListener("click", () => {
        const action = row.dataset.agendaAction;
        const rowId = row.dataset.id;
        const stageId = row.dataset.stageId;
        dialog.close();
        if (action === "edit-membership") return openMembershipDialog(state.memberships.find((item) => item.id === rowId));
        if (action === "view-order") return openOrderForConsult(state.shopOrders.find((item) => item.id === rowId));
        if (action === "edit-registration") return openRegistrationDialog(stageId, state.stageRegistrations[stageId]?.find((item) => item.id === rowId));
      });
    });
  }

  function chartBand(title, rows, formatValue = money) {
    return `<div class="band"><div class="band-title"><h2>${esc(title)}</h2></div>${chartContent(rows, formatValue)}</div>`;
  }

  function chartContent(rows, formatValue = money) {
    const max = Math.max(1, ...rows.map((row) => asNumber(row[1])));
    const content = rows.length
      ? rows
          .filter((row) => row[0])
          .slice(0, 12)
          .map(([label, value]) => {
            const width = Math.max(2, Math.round((asNumber(value) / max) * 100));
            return `<div class="bar-row"><div class="bar-label">${esc(label)}</div><div class="bar-track"><div class="bar-fill" style="width:${width}%"></div></div><div class="money">${formatValue(value)}</div></div>`;
          })
          .join("")
      : `<div class="empty">Aucune donnée</div>`;
    return `<div class="bar-list">${content}</div>`;
  }

  function shopCollapsibleBand(idValue, title, summary, body) {
    const open = Boolean(ui.shopPanels?.[idValue]);
    return `<div class="band collapsible-band shop-collapsible-band ${open ? "open" : ""}" data-shop-panel="${esc(idValue)}">
      <button type="button" class="band-title collapsible-title" data-action="toggle-shop-panel" data-panel="${esc(idValue)}" aria-expanded="${open ? "true" : "false"}">
        <h2>${esc(title)}</h2>
        <span class="collapsible-meta">${esc(summary)}</span>
        <span class="collapsible-arrow">›</span>
      </button>
      <div class="collapsible-content">
        <div class="collapsible-inner">${body}</div>
      </div>
    </div>`;
  }

  function pieChartBand(title, rows, formatValue = money, totalLabel = "Total", countLabel = "Nombre", modeKey = "") {
    const mode = modeKey ? (ui.statsPieModes?.[modeKey] || "amount") : "amount";
    const useQuantity = mode === "quantity";
    const valueIndex = useQuantity ? 2 : 1;
    const activeFormat = useQuantity ? intValue : formatValue;
    const activeTotalLabel = useQuantity ? countLabel : totalLabel;
    const palette = ["#0f7b63", "#d5a51d", "#315f9d", "#c64236", "#7c3aed", "#0891b2", "#f97316", "#16a34a", "#db2777", "#64748b"];
    const entries = rows
      .filter((row) => row[0] && asNumber(row[valueIndex]) > 0)
      .sort((a, b) => asNumber(b[valueIndex]) - asNumber(a[valueIndex]));
    const total = entries.reduce((sum, row) => sum + asNumber(row[valueIndex]), 0);
    if (!entries.length || !total) {
      return `<div class="band stats-pie-band"><div class="band-title"><h2>${esc(title)}</h2></div><div class="empty">Aucune donnée</div></div>`;
    }
    let start = 0;
    const segments = entries.map(([label, value, countValue], index) => {
      const amount = asNumber(useQuantity ? countValue : value);
      const moneyAmount = asNumber(value);
      const count = asNumber(countValue || value);
      const percent = (amount / total) * 100;
      const end = start + percent;
      const color = palette[index % palette.length];
      const style = `${color} ${start.toFixed(4)}% ${end.toFixed(4)}%`;
      start = end;
      return { label, amount, moneyAmount, count, percent, color, style };
    });
    const controls = modeKey ? `<div class="segmented stats-pie-mode">
      <button type="button" data-action="set-stats-pie-mode" data-stats-pie="${esc(modeKey)}" data-mode="amount" class="${useQuantity ? "" : "active"}">Prix</button>
      <button type="button" data-action="set-stats-pie-mode" data-stats-pie="${esc(modeKey)}" data-mode="quantity" class="${useQuantity ? "active" : ""}">Quantités</button>
    </div>` : "";
    return `<div class="band stats-pie-band">
      <div class="band-title"><h2>${esc(title)}</h2>${controls}<strong>${activeFormat(total)}</strong></div>
      <div class="stats-pie-layout">
        <div class="stats-pie" style="background: conic-gradient(${segments.map((segment) => segment.style).join(", ")});">
          <div><strong>${activeFormat(total)}</strong><span>${esc(activeTotalLabel)}</span></div>
        </div>
        <div class="stats-pie-legend">
          ${segments.map((segment) => `<div class="stats-pie-legend-row">
            <span class="stats-pie-color" style="background:${segment.color}"></span>
            <strong>${esc(segment.label)}</strong>
            <span>${intValue(segment.count || segment.amount)} ${esc(countLabel)}</span>
            <span class="money">${useQuantity ? `${intValue(segment.amount)} ${esc(countLabel)}` : formatValue(segment.moneyAmount)}</span>
          </div>`).join("")}
        </div>
      </div>
    </div>`;
  }

  function renderAlertTable(alerts) {
    if (!alerts.length) return `<div class="empty">Aucune alerte</div>`;
    return `<div class="table-wrap"><table><thead><tr><th>Module</th><th>Nom</th><th>Statut</th><th class="money">Reste dû</th></tr></thead><tbody>
      ${alerts.map((alert) => `<tr class="clickable-row" data-action="${esc(alert.editAction)}" data-id="${esc(alert.id)}" ${alert.stageId ? `data-stage-id="${esc(alert.stageId)}"` : ""}><td>${esc(alert.module)}</td><td>${personCell(alert.person)}</td><td>${alertStatusCell(alert)}</td><td class="money">${money(alert.amount)}</td></tr>`).join("")}
    </tbody></table></div>`;
  }

  function alertStatusCell(alert) {
    return statusPill(alert.status);
  }

  function groupMemberships() {
    const map = new Map();
    for (const row of state.memberships) {
      const calc = calcMembership(row);
      const item = map.get(row.discipline) || { name: row.discipline || "Sans discipline", count: 0, gain: 0 };
      item.count += 1;
      item.gain += calc.clubGain;
      map.set(item.name, item);
    }
    return [...map.values()].sort((a, b) => b.gain - a.gain);
  }

  function groupArticles() {
    if (!isModuleEnabled("boutique")) return [];
    const map = new Map();
    for (const article of state.tariffs.articles) map.set(article.id, { articleId: article.id, article, name: article.name, count: 0, total: 0 });
    for (const order of state.shopOrders) {
      for (const item of order.items || []) {
        const article = articleById(item.articleId);
        const row = map.get(item.articleId) || { articleId: item.articleId, article, name: article.name || "Article", count: 0, total: 0 };
        row.count += asNumber(item.quantity);
        row.total += asNumber(item.quantity) * asNumber(item.unitPrice);
        map.set(item.articleId, row);
      }
    }
    return [...map.values()].sort((a, b) => b.total - a.total);
  }

  function articleSalesById() {
    // Lot 2B — point bloquant 1 : dérivation de DONNÉES HISTORIQUES (ventes par article). Elle
    // alimente stockRows(), la comptabilité, les statistiques et les exports : elle ne dépend donc
    // NI de settings.display.showBoutique NI de hasFeature. La visibilité se décide aux appelants.
    const map = new Map();
    for (const article of state.tariffs.articles) {
      map.set(article.id, { quantity: 0, total: 0, bySize: {} });
    }
    for (const order of state.shopOrders) {
      for (const item of order.items || []) {
        const sales = map.get(item.articleId) || { quantity: 0, total: 0, bySize: {} };
        sales.quantity += asNumber(item.quantity);
        sales.total += asNumber(item.quantity) * asNumber(item.unitPrice);
        for (const [size, quantity] of Object.entries(item.sizes || {})) {
          sales.bySize[size] = asNumber(sales.bySize[size]) + asNumber(quantity);
        }
        map.set(item.articleId, sales);
      }
    }
    return map;
  }

  function orderItemDetails(order = {}) {
    return (order.items || [])
      .filter((item) => asNumber(item.quantity))
      .map((item) => {
        const article = articleById(item.articleId);
        const quantity = asNumber(item.quantity);
        const unitPrice = asNumber(item.unitPrice);
        return {
          ...item,
          article,
          quantity,
          unitPrice,
          total: quantity * unitPrice,
          sizesText: Object.entries(item.sizes || {})
            .filter((entry) => asNumber(entry[1]))
            .map(([size, qty]) => `${size}: ${intValue(qty)}`)
            .join(", "),
        };
      });
  }

  function shopOrderStatus(order, calc = calcOrder(order)) {
    if (calc.restDue <= 0 && calc.total > 0) return "Payé";
    const alert = alertStatusForPayments(order.payments);
    if (alert === "Reste dû") return calc.paid > 0 ? "Partiel" : "Non payé";
    return alert;
  }

  function stockRows() {
    // Lot 2B — point bloquant 1 : stock DÉRIVÉ (initial − vendus) = donnée historique inconditionnelle.
    // Consommée par la comptabilité, les statistiques, les factures et les exports ; ne dépend pas de
    // settings.display.showBoutique (affichage) ni de hasFeature (fonction). Gardé aux appelants.
    const sales = articleSalesById();
    return state.tariffs.articles.map((article, index) => {
      const sale = sales.get(article.id) || { quantity: 0, total: 0, bySize: {} };
      const sold = sale.quantity || 0;
      const sizeStock = normalizeSizeStock(article.sizeStock);
      const sizeStockTotalValue = sizeStockTotal(sizeStock);
      const usesSizeStock = articleHasSizes(article) && Object.keys(sizeStock).length > 0;
      const initial = usesSizeStock ? sizeStockTotalValue : asNumber(article.stockInitial);
      const available = initial - sold;
      const purchasePrice = asNumber(article.priceOptions?.[1]);
      return {
        article,
        index,
        sold,
        available,
        availableBySize: sizeAvailability(article, sale.bySize || {}),
        soldBySize: sale.bySize || {},
        total: sale.total || 0,
        purchasePrice,
        purchaseTotal: available * purchasePrice,
      };
    });
  }

  function articleSizeKeys(article = {}) {
    return [...new Set([...(article.sizes || []), ...Object.keys(normalizeSizeStock(article.sizeStock))].filter(Boolean))];
  }

  function articleHasSizes(article = {}) {
    return articleSizeKeys(article).length > 0;
  }

  function sizeAvailability(article = {}, soldBySize = {}) {
    const stock = normalizeSizeStock(article.sizeStock);
    return Object.fromEntries(articleSizeKeys(article).map((size) => [
      size,
      asNumber(stock[size]) - asNumber(soldBySize[size]),
    ]));
  }

  function stockMovements() {
    const rows = [];
    if (!isModuleEnabled("boutique")) return rows;
    for (const order of state.shopOrders) {
      for (const item of order.items || []) {
        if (!asNumber(item.quantity)) continue;
        const article = articleById(item.articleId);
        rows.push({
          order,
          article,
          quantity: asNumber(item.quantity),
          total: asNumber(item.quantity) * asNumber(item.unitPrice),
          sizes: Object.entries(item.sizes || {}).filter((entry) => asNumber(entry[1])).map(([size, qty]) => `${size}: ${qty}`).join(", "),
        });
      }
    }
    return rows;
  }

  function groupStages() {
    // Lot 2D — lecture historique inconditionnelle : le regroupement des stages/inscriptions ne dépend
    // ni de l'affichage (showStages) ni de la fonctionnalité (hasFeature). L'affichage éventuel de ce
    // regroupement se décide chez l'appelant ; la donnée reste identique dans tous les états.
    return state.tariffs.stages.map((stage) => {
      const rows = state.stageRegistrations[stage.id] || [];
      return {
        name: stage.name,
        count: rows.length,
        total: rows.reduce((sum, row) => sum + calcRegistration(row, stage.id).total, 0),
      };
    });
  }

  function toolbar(addAction, addLabel, extra = "", rightBefore = "") {
    return `<div class="toolbar">
      <div class="left">
        <input class="search" data-focus="query" data-filter="query" placeholder="Rechercher" value="${esc(ui.query)}" />
        ${extra}
      </div>
      <div class="right">${rightBefore}${addAction ? `<button class="primary" data-action="${esc(addAction)}">${esc(addLabel)}</button>` : ""}</div>
    </div>`;
  }

  function dueFilterButton(key, active) {
    return `<button type="button" data-action="toggle-due-filter" data-filter-key="${esc(key)}" class="${active ? "active" : ""}">Reste dû</button>`;
  }

  function personCell(row = {}) {
    return `<div class="person-cell"><strong>${esc(row.lastName || "")}</strong><span>${esc(row.firstName || "")}</span></div>`;
  }

  function alertInfoBadge(text) {
    return `<span class="alert-info-badge">${esc(text)}</span>`;
  }

  // Classe d'âge d'un contact pour le filtre Enfants/Adultes. Réutilise ageFromBirthDate
  // (enfant = moins de 18 ans, adulte = 18 ans ou plus). Repli sur une catégorie explicite
  // éventuelle. "" = indéterminé (sans date de naissance ni catégorie) → seulement dans « Tous ».
  function contactAgeClass(row = {}) {
    const age = ageFromBirthDate(row.birthDate);
    if (age !== null) return age >= 18 ? "adult" : "child";
    const cat = asText(row.category).toLowerCase();
    if (cat === "enfant") return "child";
    if (cat === "adulte") return "adult";
    return "";
  }

  function renderContacts() {
    const kind = ui.contactKind;
    const category = ["all", "child", "adult"].includes(ui.contactCategory) ? ui.contactCategory : "all";
    const rows = state.contacts[kind]
      .filter((row) => includesQuery(row, ui.query))
      .filter((row) => category === "all" || contactAgeClass(row) === category)
      .sort((a, b) => personKey(a).localeCompare(personKey(b)));
    const catButton = (value, label) => `<button data-action="set-contact-category" data-category="${value}" class="${category === value ? "active" : ""}">${label}</button>`;
    const extra = `<div class="segmented">
      <button data-contact-kind="members" class="${kind === "members" ? "active" : ""}">Adhérents</button>
      <button data-contact-kind="prospects" class="${kind === "prospects" ? "active" : ""}">Non adhérents</button>
    </div>
    <div class="segmented" role="group" aria-label="Filtrer par âge">
      ${catButton("all", "Tous")}${catButton("child", "Enfants")}${catButton("adult", "Adultes")}
    </div>`;
    return `
      ${toolbar("add-contact", "Nouveau contact", extra)}
      <div class="band discipline-binder">
        <div class="band-title"><h2>${kind === "members" ? "Adhérents" : "Non adhérents"}${category === "child" ? " · enfants" : category === "adult" ? " · adultes" : ""}</h2><strong>${rows.length} contacts</strong></div>
        ${(state.contacts[kind] || []).length === 0 ? emptyStateHtml(kind === "members" ? "members" : "prospects") : contactBinder(rows, kind)}
      </div>`;
  }

  // Lot 3B-3 — cette colonne n'a pas d'en-tête et sert les DEUX onglets. Pour un adhérent elle
  // affiche la classe d'âge calculée (Adulte / Enfant), qui se lit seule ; pour un non-adhérent elle
  // affiche « Non-membre », qui n'est pas une classe d'âge et que rien ne qualifiait. La valeur des
  // non-adhérents est donc préfixée « Statut : », conformément à la doctrine du lot. Le champ
  // technique `category` et sa valeur sont inchangés — seul le texte rendu diffère.
  function contactStatusCellText(row = {}, kind, fallback = "") {
    if (kind === "members") return memberCategory(row);
    const value = asText(row.category) || asText(fallback);
    return value ? `Statut : ${value}` : "";
  }

  function contactRow(row, kind) {
    const tel = row.mobile || row.phone || "";
    // Lot H-B — même correctif que contactCard() ci-dessous (colonne e-mail de la liste desktop) :
    // l'adresse cliquable ouvrait directement la messagerie externe (mailto: brut, aucun logo/mise
    // en page possible) au lieu du compositeur MonGestaClub. Réutilise exactement le même chemin que
    // le bouton « Envoyer un mail » de la fiche (data-action="send-contact-email").
    const contactLink = `${kind === "members" ? "member" : "prospect"}:${row.id}`;
    return `<tr class="clickable-row" data-action="edit-contact" data-kind="${esc(kind)}" data-id="${esc(row.id)}">
      <td>${esc(row.lastName)}</td>
      <td>${esc(row.firstName)}</td>
      <td>${row.email ? `<button type="button" class="link-button" data-action="send-contact-email" data-contact-link="${esc(contactLink)}" title="Envoyer un mail à ce contact">${esc(row.email)}</button>` : ""}</td>
      <td>${tel ? `<a href="tel:${esc(tel)}">${esc(tel)}</a>` : ""}</td>
      <td>${esc(row.city)}</td>
      <td>${dateDisplay(row.birthDate) || `<span class="muted">-</span>`}</td>
      <td>${memberAgeLabel(row) || `<span class="muted">-</span>`}</td>
      <td>${esc(contactStatusCellText(row, kind))}</td>
    </tr>`;
  }

  function contactBinder(rows, kind) {
    return alphabetBinder(rows, {
      empty: "Aucun contact",
      selectedLetter: ui.contactLetter,
      action: "set-contact-letter",
      card: (row) => contactCard(row, kind),
    });
  }

  function contactCard(row, kind) {
    const tel = row.mobile || row.phone || "";
    const tone = contactPaymentTone(kind, row);
    const documentCount = normalizeContactDocuments(row.documents).length;
    // L'adresse e-mail cliquable de la liste des contacts était un <a href="mailto:...">
    // brut : elle ouvrait directement la messagerie externe sans jamais passer par le
    // dialogue MonGestaClub (aperçu HTML, modèle, bouton SMTP intégré). C'est l'action
    // qu'un utilisateur clique le plus naturellement pour « envoyer un mail à ce contact »
    // depuis la liste — corrigé pour réutiliser exactement le même chemin que le bouton
    // « Envoyer un mail » du bas de fiche (data-action="send-contact-email", déjà correct).
    const contactLink = `${kind === "members" ? "member" : "prospect"}:${row.id}`;
    return `<article class="membership-card contact-line clickable-card ${tone ? `payment-${tone}` : ""}" data-action="edit-contact" data-kind="${esc(kind)}" data-id="${esc(row.id)}">
      <div>${personCell(row)}</div>
      <div class="membership-card-meta contact-line-info">
        ${row.email ? `<button type="button" class="link-button" data-action="send-contact-email" data-contact-link="${esc(contactLink)}" title="Envoyer un mail à ce contact">${esc(row.email)}</button>` : alertInfoBadge("E-mail non renseigné")}
        ${tel ? `<a href="tel:${esc(tel)}">${esc(tel)}</a>` : alertInfoBadge("Téléphone non renseigné")}
      </div>
      <div class="membership-card-meta">
        ${row.city ? `<span>${esc(row.city)}</span>` : alertInfoBadge("Ville non renseignée")}
        ${dateDisplay(row.birthDate) ? `<span>${dateDisplay(row.birthDate)}</span>` : alertInfoBadge("Date naissance non renseignée")}
        ${memberAgeLabel(row) ? `<span>${memberAgeLabel(row)}</span>` : alertInfoBadge("Âge non calculé")}
      </div>
      <div class="membership-card-meta contact-line-status">
        <span>${esc(contactStatusCellText(row, kind, "Non adhérent"))}</span>
        ${documentCount ? `<span class="contact-paperclip" title="${documentCount} document${documentCount > 1 ? "s" : ""} joint${documentCount > 1 ? "s" : ""}">📎 ${intValue(documentCount)}</span>` : ""}
      </div>
    </article>`;
  }

  function contactPaymentTone(kind, row = {}) {
    const modules = kind === "members" ? ["disciplines", "boutique", "stages"] : ["boutique", "stages"];
    const entries = modules.flatMap((module) => contactModuleEntries(row, module));
    const invoices = contactInvoices(row, kind).filter((invoice) => invoice.status !== "cancelled");
    const invoiceEntries = invoices.map((invoice) => ({ row: invoice, calc: invoiceLiveTotals(invoice), invoice }));
    const allEntries = [...entries, ...invoiceEntries];
    if (!allEntries.length) return "";
    const dueEntries = allEntries.filter((entry) => asNumber(entry.calc.restDue) > 0);
    if (!dueEntries.length) return "paid";
    if (dueEntries.some((entry) => entry.invoice && ["late", "cancelled"].includes(computedInvoiceStatus(entry.invoice)))) return "due";
    const payments = dueEntries.flatMap((entry) => moduleEntryPayments(entry));
    if (payments.some(paymentIsLate)) return "due";
    if (payments.some(paymentIsPendingOrPlanned) || dueEntries.some((entry) => entry.invoice && ["issued", "partial", "draft"].includes(computedInvoiceStatus(entry.invoice)))) return "pending";
    return "due";
  }

  function renderDisciplines() {
    const activeDisciplines = state.tariffs.disciplines.filter((d) => d.archived !== true);
    // Lot 2A — une discipline archivée n'est plus proposée comme filtre courant. Si ui.discipline
    // pointait justement sur une discipline devenue archivée entre-temps, l'affichage ET le filtrage
    // retombent proprement sur « Toutes » (aucune donnée modifiée, ui.discipline lui-même n'est
    // jamais réécrit ici — si la discipline est restaurée plus tard, le filtre redevient actif de
    // lui-même, sans action de l'utilisateur).
    const disciplineFilter = activeDisciplines.some((d) => d.name === ui.discipline) ? ui.discipline : "";
    const options = [`<option value="">Toutes les disciplines</option>`]
      .concat(activeDisciplines.map((discipline) => `<option value="${esc(discipline.name)}" ${disciplineFilter === discipline.name ? "selected" : ""}>${esc(discipline.name)}</option>`))
      .join("");
    const rows = state.memberships
      .filter((row) => includesQuery(row, ui.query))
      .filter((row) => !disciplineFilter || row.discipline === disciplineFilter)
      .filter((row) => !ui.disciplineDueOnly || calcMembership(row).restDue > 0)
      .sort((a, b) => personKey(a).localeCompare(personKey(b)));
    // Lot 3A (clôture absolue, FIN-ABS-2) — les inscriptions au tarif ABSENT ne sont pas comptées comme
    // 0 € dans les agrégats sans le dire : elles sont exclues des sommes et signalées à part, pour que
    // « Total »/« Reste dû » ne soient pas silencieusement sous-évalués.
    const calcs = rows.map((row) => calcMembership(row));
    const billableCalcs = calcs.filter((calc) => calc.hasGrossTotal);
    const undefinedCount = calcs.length - billableCalcs.length;
    const total = billableCalcs.reduce((sum, calc) => sum + calc.total, 0);
    const paid = billableCalcs.reduce((sum, calc) => sum + calc.paid, 0);
    const due = billableCalcs.reduce((sum, calc) => sum + calc.restDue, 0);
    return `
      ${overviewBand("disciplines", "Disciplines en un coup d'oeil", [
        { label: "Inscriptions", value: rows.length },
        { label: "Total", value: money(total) },
        { label: "Réglé", value: money(paid) },
        { label: "Reste dû", value: money(due), action: "show-overview-due", scope: "disciplines", title: "Voir les adhérents avec un reste dû" },
        ...(undefinedCount > 0 ? [{ label: "Tarif non défini", value: undefinedCount }] : []),
      ])}
      <div class="band collapsible-band overview-band ${ui.overviewPanels?.disciplineManagement ? "open" : ""}">
        <div class="band-title collapsible-title-row" data-action="toggle-overview-panel" data-panel="disciplineManagement" role="button" tabindex="0" aria-expanded="${ui.overviewPanels?.disciplineManagement ? "true" : "false"}">
          <div>
            <h2>Gérer les disciplines</h2>
            <p class="muted">Ajoute, modifie ou supprime les disciplines utilisées dans les inscriptions.</p>
          </div>
          <span class="collapsible-meta">${ui.overviewPanels?.disciplineManagement ? "Masquer" : "Afficher"}</span>
          <button data-action="add-tariff-discipline" data-origin="disciplines">Nouvelle discipline</button>
          <span class="collapsible-arrow">›</span>
        </div>
        <div class="collapsible-content">
          <div class="collapsible-inner">${editableDisciplines()}</div>
        </div>
      </div>
      ${toolbar("add-membership", "Nouvelle inscription", `<select data-filter="discipline">${options}</select><div class="segmented">${dueFilterButton("disciplineDueOnly", ui.disciplineDueOnly)}</div>`)}
      <div class="band discipline-binder">
        <div class="band-title"><h2>${disciplineFilter ? esc(disciplineFilter) : "Toutes les disciplines"}</h2><strong>${rows.length} adhérents</strong></div>
        ${(state.memberships || []).length === 0
          // Lot 3B-4A — deux états vides DISTINCTS : sans discipline au catalogue, on ne propose
          // pas de créer une inscription (elle n'aurait rien à quoi se rattacher).
          ? emptyStateHtml(disciplinesList().length === 0 ? "disciplines-empty-catalog" : "disciplines")
          : membershipBinder(rows)}
      </div>`;
  }

  function membershipRow(row) {
    const calc = calcMembership(row);
    // Lot 3A (clôture absolue, FIN-ABS-2) — Total/Reste dû « Non calculable » pour un tarif absent.
    const disp = membershipTotalDisplay(calc);
    return `<tr>
      <td>${personCell(row)}</td><td>${paymentControls("membership", row.id, row.payments || [], { total: calc.total, defaultTaxRate: membershipDefaultTaxRate(row), billable: calc.hasGrossTotal })}</td><td>${esc(row.discipline)}</td>
      <td>${row.medicalCertificate ? "Oui" : "Non"}</td>
      <td class="money">${disp.total}</td><td class="money">${disp.paid}</td><td class="money">${disp.restDue}</td>
      <td><div class="actions"><button class="icon" title="Modifier" data-action="edit-membership" data-id="${row.id}">✎</button><button class="icon danger" title="Retirer" data-action="delete-membership" data-id="${row.id}">×</button></div></td>
    </tr>`;
  }

  function personInitial(row) {
    const raw = normalizedPersonText(row.lastName || row.firstName).charAt(0).toUpperCase();
    return /^[A-Z]$/.test(raw) ? raw : "#";
  }

  function alphabetBinder(rows, options = {}) {
    if (!rows.length) return `<div class="empty">${esc(options.empty || "Aucune ligne")}</div>`;
    const letters = [..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"];
    const groups = new Map();
    rows.forEach((row) => {
      const letter = personInitial(row);
      if (!groups.has(letter)) groups.set(letter, []);
      groups.get(letter).push(row);
    });
    const activeLetters = new Set(groups.keys());
    const selectedLetter = activeLetters.has(options.selectedLetter) ? options.selectedLetter : "";
    const visibleEntries = selectedLetter ? [[selectedLetter, groups.get(selectedLetter) || []]] : [...groups.entries()];
    const groupMarkup = visibleEntries.map(([letter, groupRows]) => `
      <section class="membership-letter-group">
        <div class="membership-letter-title"><span>${letter}</span><strong>${groupRows.length}</strong></div>
        <div class="membership-card-list">${groupRows.map(options.card).join("")}</div>
      </section>`).join("");
    const tabs = letters.map((letter) => activeLetters.has(letter)
      ? `<button type="button" data-action="${esc(options.action)}" data-letter="${letter}" class="${selectedLetter === letter ? "active" : ""}">${letter}</button>`
      : `<span>${letter}</span>`).join("");
    return `<div class="membership-binder">
      <div class="membership-binder-content">${groupMarkup}</div>
      <nav class="membership-alpha-tabs" aria-label="Index alphabétique">
        <button type="button" data-action="${esc(options.action)}" data-letter="" class="${selectedLetter ? "" : "active"}">Tous</button>
        ${tabs}
      </nav>
    </div>`;
  }

  function membershipBinder(rows) {
    return alphabetBinder(rows, {
      empty: "Aucune inscription",
      selectedLetter: ui.disciplineLetter,
      action: "set-discipline-letter",
      card: membershipCard,
    });
  }

  function membershipCard(row) {
    const calc = calcMembership(row);
    const tone = membershipPaymentTone(row, calc);
    // Lot 3A (clôture absolue, FIN-ABS-2) — Total/Reste dû « Non calculable » pour un tarif absent
    // (jamais 0,00 €) ; un badge signale explicitement le tarif non défini.
    const disp = membershipTotalDisplay(calc);
    return `<article class="membership-card payment-${tone}" data-action="edit-membership" data-id="${esc(row.id)}">
      <div class="membership-card-head">
        ${personCell(row)}
      </div>
      <div class="membership-card-meta">
        <span>${esc(row.discipline || "Sans discipline")}</span>
        ${calc.hasGrossTotal ? "" : alertInfoBadge("Tarif non défini")}
        ${row.medicalCertificate ? `<span>Certificat OK</span>` : alertInfoBadge("Certificat manquant")}
      </div>
      <div class="membership-card-totals">
        <div><span>Total</span><strong>${disp.total}</strong></div>
        <div><span>Réglé</span><strong>${disp.paid}</strong></div>
        <div class="${calc.restDue > 0 && calc.hasGrossTotal ? "due" : ""}"><span>Reste dû</span><strong>${disp.restDue}</strong></div>
      </div>
      <div class="membership-card-payments">${paymentControls("membership", row.id, row.payments || [], { total: calc.total, defaultTaxRate: membershipDefaultTaxRate(row), billable: calc.hasGrossTotal })}</div>
    </article>`;
  }

  function membershipPaymentTone(row, calc = calcMembership(row)) {
    return paymentToneFromPayments(row.payments || [], calc.restDue);
  }

  function renderBoutique() {
    const rows = state.shopOrders
      .filter((row) => includesQuery(row, ui.query))
      .filter((row) => !ui.shopDueOnly || calcOrder(row).restDue > 0)
      .sort((a, b) => calcOrder(b).restDue - calcOrder(a).restDue || personKey(a).localeCompare(personKey(b)));
    const articleRows = groupArticles().filter((row) => asNumber(row.count) || asNumber(row.total));
    const catalogRows = stockRows()
      .filter(({ article }) => article.active !== false)
      .filter(({ article }) => includesQuery(article, ui.query));
    const total = rows.reduce((sum, row) => sum + calcOrder(row).total, 0);
    const paid = rows.reduce((sum, row) => sum + calcOrder(row).paid, 0);
    const due = rows.reduce((sum, row) => sum + calcOrder(row).restDue, 0);
    const articleCount = rows.reduce((sum, row) => sum + orderItemDetails(row).reduce((itemSum, item) => itemSum + item.quantity, 0), 0);
    const unpaidRows = rows.filter((row) => calcOrder(row).restDue > 0);
    return `
      ${overviewBand("boutique", "Boutique en un coup d'oeil", [
        { label: "Commandes", value: rows.length },
        { label: "Articles achetés", value: intValue(articleCount) },
        { label: "Total boutique", value: money(total) },
        { label: "Réglé", value: money(paid) },
        { label: "Reste dû", value: money(due), action: "show-overview-due", scope: "boutique", title: "Voir les clients boutique avec un reste dû" },
        { label: "À suivre", value: unpaidRows.length },
      ])}
      ${toolbar("add-order", "Nouvelle commande", `<div class="segmented">${dueFilterButton("shopDueOnly", ui.shopDueOnly)}</div>`)}
      <div class="band shop-catalog-band">
        <div class="band-title"><h2>Articles à vendre</h2><strong>${intValue(catalogRows.length)}</strong></div>
        <div class="shop-catalog-grid">
          ${catalogRows.map(shopCatalogCard).join("") || (((state.tariffs && state.tariffs.articles) || []).length === 0 ? emptyStateHtml("boutique") : `<div class="empty">Aucun article disponible</div>`)}
        </div>
      </div>
      ${shopCollapsibleBand("payments", "Encaissements boutique", money(due), shopPaymentFollowUp(unpaidRows))}
      ${shopCollapsibleBand("articles", "Articles vendus", intValue(articleRows.reduce((sum, row) => sum + row.count, 0)), shopArticleSummary(articleRows))}
      ${shopCollapsibleBand("orders", "Commandes clients", money(total), `
        <div class="shop-order-list">
          ${rows.map(orderCard).join("") || `<div class="empty">Aucune commande</div>`}
        </div>
      `)}
      ${shopCollapsibleBand("chart", "Ventes par article", intValue(articleRows.length), chartContent(articleRows.map((row) => [row.name, row.total])))}`;
  }

  function shopCatalogCard(row) {
    const { article, available, availableBySize } = row;
    const price = article.priceOptions?.[0] ?? article.defaultPrice ?? 0;
    const sizeText = (article.sizes || []).length
      ? (article.sizes || []).map((size) => `${size} ${intValue(availableBySize?.[size] ?? 0)}`).join(" · ")
      : "Sans taille";
    const tone = available < 0 ? "stock-negative" : isStockLow(row) ? "stock-warning" : "";
    return `<article class="shop-catalog-card ${tone}">
      <div class="shop-catalog-image">${articleImage(article, "medium")}</div>
      <div class="shop-catalog-info">
        <strong>${esc(article.name || "Article")}</strong>
        <span>${esc(article.reference || "Référence auto")}</span>
        <small>${esc(sizeText)}</small>
      </div>
      <div class="shop-catalog-footer">
        <div><span>Prix</span><strong>${money(price)}</strong></div>
        <div><span>Stock</span><strong>${intValue(available)}</strong></div>
        <button class="primary" data-action="sell-article" data-article-id="${esc(article.id)}">Vendre</button>
      </div>
    </article>`;
  }

  function shopPaymentFollowUp(rows) {
    const content = rows.slice(0, 8).map((row) => {
      const calc = calcOrder(row);
      return `<button class="shop-follow-row" data-action="view-order" data-id="${esc(row.id)}">
        <div>${personCell(row)}</div>
        ${statusPill(shopOrderStatus(row, calc))}
        <strong>${money(calc.restDue)}</strong>
      </button>`;
    }).join("");
    return `<div class="shop-follow-list">${content || `<div class="empty">Aucun reste dû boutique</div>`}</div>`;
  }

  function shopArticleSummary(rows) {
    const topRows = rows.slice(0, 8);
    if (!topRows.length) return `<div class="empty">Aucune vente enregistrée</div>`;
    return `<div class="shop-article-list">
      ${topRows.map((row) => `<div class="shop-article-row">
        ${articleImage(row.article || articleById(row.articleId), "tiny")}
        <span>${esc(row.name || "Article")}</span>
        <strong>${intValue(row.count)}</strong>
        <span class="money">${money(row.total)}</span>
      </div>`).join("")}
    </div>`;
  }

  function orderItemsList(row) {
    const items = orderItemDetails(row);
    if (!items.length) return `<div class="empty compact">Aucun article</div>`;
    return `<div class="shop-items-list">
      ${items.map((item) => `<div class="shop-item-line">
        ${articleImage(item.article, "tiny")}
        <div>
          <strong>${esc(item.article.name || "Article supprimé")}</strong>
          <span>${item.sizesText ? esc(item.sizesText) : esc(item.article.reference || "")}</span>
        </div>
        <span>Qté ${intValue(item.quantity)}</span>
        <span>${money(item.unitPrice)}</span>
        <strong class="money">${money(item.total)}</strong>
      </div>`).join("")}
    </div>`;
  }

  function orderItemsPreview(row) {
    const items = orderItemDetails(row);
    if (!items.length) return `<span class="shop-order-item-chip muted">Aucun article</span>`;
    return `<div class="shop-order-items-preview">
      ${items.map((item) => `<span class="shop-order-item-chip">
        <strong>${esc(item.article.name || "Article supprimé")}</strong>
        <em>${item.sizesText ? esc(item.sizesText) : `Qté ${intValue(item.quantity)}`}</em>
      </span>`).join("")}
    </div>`;
  }

  function orderCard(row) {
    const calc = calcOrder(row);
    const status = shopOrderStatus(row, calc);
    const items = orderItemDetails(row);
    const itemCount = items.reduce((sum, item) => sum + item.quantity, 0);
    const clientName = [row.lastName, row.firstName].filter(Boolean).join(" ") || "Client sans nom";
    const contact = [row.phone, row.email].filter(Boolean).join(" · ");
    const address = [row.address, row.postalCode, row.city].filter(Boolean).join(" ");
    // Lot intégrité commandes : mêmes règles que les handlers edit-order/delete-order
    // (shopOrderIntegrityState, 18-contacts-invoices.js) — un seul calcul, jamais dupliqué.
    const integrity = shopOrderIntegrityState(row);
    const invoice = integrity.invoice;
    const editTitle = integrity.editBlocked ? ` title="${esc(shopOrderIntegrityMessage(integrity.editReasons, "edit"))}"` : "";
    const deleteTitle = integrity.deleteBlocked ? ` title="${esc(shopOrderIntegrityMessage(integrity.deleteReasons, "delete"))}"` : "";
    return `<details class="shop-order-card ${calc.restDue > 0 ? "has-due" : "is-paid"}">
      <summary class="shop-order-summary">
        <span class="shop-order-client">
          <strong>${esc(clientName)}</strong>
          <small>${itemCount ? `${intValue(itemCount)} article${itemCount > 1 ? "s" : ""}` : "Aucun article"}</small>
        </span>
        ${statusPill(status)}
        <span class="shop-order-amount"><small>Total</small><strong>${money(calc.total)}</strong></span>
        <span class="shop-order-amount"><small>Réglé</small><strong>${money(calc.paid)}</strong></span>
        <span class="shop-order-amount ${calc.restDue > 0 ? "due" : ""}"><small>Reste dû</small><strong>${money(calc.restDue)}</strong></span>
        <span class="shop-order-toggle">›</span>
        ${orderItemsPreview(row)}
      </summary>
      <div class="shop-order-detail">
        ${(contact || address) ? `<div class="shop-order-meta">
          ${contact ? `<span>${esc(contact)}</span>` : ""}
          ${address ? `<span>${esc(address)}</span>` : ""}
        </div>` : ""}
        ${orderItemsList(row)}
        <div class="shop-total-grid">
          <div><span>Articles</span><strong>${intValue(itemCount)}</strong></div>
          <div><span>Total</span><strong>${money(calc.total)}</strong></div>
          <div><span>Réglé</span><strong>${money(calc.paid)}</strong></div>
          <div><span>Reste dû</span><strong>${money(calc.restDue)}</strong></div>
        </div>
        <details class="shop-payments">
          <summary>Paiements</summary>
          ${paymentControls("order", row.id, row.payments || [], { total: calc.total, defaultTaxRate: orderDefaultTaxRate(row) })}
        </details>
        <div class="shop-order-actions">
          <button data-action="edit-order" data-id="${esc(row.id)}" ${integrity.editBlocked ? "disabled" : ""}${editTitle}>Modifier la commande</button>
          <button data-action="open-order-invoice" data-id="${esc(row.id)}">${invoice ? "Ouvrir la facture" : "Créer / éditer la facture"}</button>
          <button data-action="print-order-invoice" data-id="${esc(row.id)}">Imprimer la facture</button>
          <button data-action="export-order-invoice-pdf" data-id="${esc(row.id)}">PDF facture</button>
          <button class="danger" data-action="delete-order" data-id="${esc(row.id)}" ${integrity.deleteBlocked ? "disabled" : ""}${deleteTitle}>Supprimer</button>
        </div>
      </div>
    </details>`;
  }

  function renderStock() {
    const rows = stockRows().filter(({ article }) => includesQuery(article, ui.query));
    const movements = stockMovements().filter((row) => includesQuery(row, ui.query)).slice(0, 80);
    const sold = rows.reduce((sum, row) => sum + row.sold, 0);
    const available = rows.reduce((sum, row) => sum + row.available, 0);
    const low = rows.filter((row) => isStockLow(row)).length;
    const purchaseTotal = rows.reduce((sum, row) => sum + row.purchaseTotal, 0);
    const soldTotal = rows.reduce((sum, row) => sum + row.total, 0);
    return `
      ${kpis([
        { label: "Articles", value: rows.length },
        { label: "Vendus", value: intValue(sold) },
        { label: "En stock", value: intValue(available) },
        { label: "Total achat", value: money(purchaseTotal) },
        { label: "Total vendu", value: money(soldTotal) },
        { label: "Seuils atteints", value: low },
      ])}
      ${toolbar("add-stock-article", "Nouvel article")}
      ${stockCollapsibleBand("articles", "Articles et stock", intValue(rows.length), `
        <div class="table-wrap"><table class="stock-table">
          <thead><tr><th>Image</th><th>Article</th><th>Prix</th><th>Tailles</th><th>Stock</th><th>Seuil d'alerte</th><th>Valeur</th><th></th></tr></thead>
          <tbody>${rows.map(stockArticleRow).join("") || (((state.tariffs && state.tariffs.articles) || []).length === 0 ? `<tr><td colspan="8">${emptyStateHtml("stock")}</td></tr>` : `<tr><td colspan="8" class="empty">Aucun article</td></tr>`)}</tbody>
        </table></div>
      `)}
      ${stockCollapsibleBand("movements", "Mouvements boutique", intValue(movements.length), `
        <div class="table-wrap"><table>
          <thead><tr><th>Client</th><th>Article</th><th>Tailles</th><th class="money">Quantité</th><th class="money">Total</th></tr></thead>
          <tbody>${movements.map(stockMovementRow).join("") || `<tr><td colspan="5" class="empty">Aucun mouvement</td></tr>`}</tbody>
        </table></div>
      `)}`;
  }

  function stockCollapsibleBand(idValue, title, summary, body, extraClass = "") {
    const open = Boolean(ui.stockPanels?.[idValue]);
    return `<div class="band collapsible-band ${open ? "open" : ""} ${extraClass}" data-stock-panel="${esc(idValue)}">
      <button type="button" class="band-title collapsible-title" data-action="toggle-stock-panel" data-panel="${esc(idValue)}" aria-expanded="${open ? "true" : "false"}">
        <h2>${esc(title)}</h2>
        <span class="collapsible-meta">${esc(summary)}</span>
        <span class="collapsible-arrow">›</span>
      </button>
      <div class="collapsible-content">
        <div class="collapsible-inner">${body}</div>
      </div>
    </div>`;
  }

  function stockArticleRow(row) {
    const { article, index, sold, available, purchaseTotal, total } = row;
    const alert = isStockLow(row);
    const tone = stockAlertTone(row);
    return `<tr class="stock-row ${tone}">
      <td>${articleImage(article, "small")}</td>
      <td>
        <div class="stock-article-main">
          <strong>${esc(article.name || "Article")}</strong>
          <span>${esc(article.reference || "Référence auto")}</span>
        </div>
      </td>
      <td><div class="stock-price-cell"><span>Vente <strong>${money(article.priceOptions?.[0] ?? article.defaultPrice ?? 0)}</strong></span><span>Achat <strong>${money(article.priceOptions?.[1] ?? 0)}</strong></span></div></td>
      <td>${stockSizeEditor(row)}</td>
      <td><div class="stock-count-cell"><strong>${intValue(available)}</strong><span>vendu ${intValue(sold)}</span>${alert ? `<span class="status due">${available < 0 ? "Stock négatif" : `Alerte ${intValue(article.stockAlert || 0)}`}</span>` : `<span class="status ok">OK</span>`}</div></td>
      <td><input class="stock-alert-inline" data-stock="stockAlert" data-index="${index}" type="number" step="1" min="0" value="${esc(article.stockAlert || 0)}" /></td>
      <td><div class="stock-value-cell"><span>Achat ${money(purchaseTotal)}</span><span>Vendu ${money(total)}</span></div></td>
      <td><div class="actions"><button class="icon" title="Modifier l'article" data-action="edit-stock-article" data-index="${index}">✎</button><button class="icon danger" title="Supprimer l'article" data-action="delete-stock-article" data-index="${index}">×</button></div></td>
    </tr>`;
  }

  function stockSizeEditor(row) {
    const { article, index } = row;
    const sizes = articleSizeKeys(article);
    if (!sizes.length) {
      return `<div class="stock-size-editor no-sizes">
        <input class="stock-qty-stepper" title="Modifier le stock disponible" data-stock="available" data-index="${index}" type="number" step="1" min="0" value="${esc(row.available || 0)}" />
        <button type="button" title="Ajouter une gestion par tailles" data-action="edit-article-sizes" data-index="${index}">+ tailles</button>
      </div>`;
    }
    return `<div class="stock-size-editor">
      <button type="button" data-action="edit-article-sizes" data-index="${index}">Tailles</button>
      <span class="muted">${intValue(row.available)} en stock</span>
    </div>`;
  }

  function sizeStockRows(article = {}, currentStock = null, options = {}) {
    const stock = normalizeSizeStock(currentStock || article.sizeStock);
    const sizes = articleSizeKeys(article);
    if (!sizes.length && options.allowEmpty) return sizeStockRow("", "", 0);
    return sizes.map((size, index) => sizeStockRow(size, stock[size], index)).join("");
  }

  function sizeStockRow(size = "", quantity = "", index = 0) {
    return `<div class="size-stock-form-row" data-size-stock-row>
      <label>Taille<input name="stockSize_${index}" value="${esc(size)}" placeholder="M" /></label>
      <label>Quantité<input name="stockQty_${index}" type="number" step="1" min="0" value="${esc(quantity || "")}" /></label>
      <button class="icon danger" type="button" title="Supprimer la taille" data-action="remove-size-stock-row">×</button>
    </div>`;
  }

  function validateSizeStockForm(form, parsed, wasSized = false) {
    // Gestion par tailles non activée : la section reste masquée tant que l'utilisateur n'a pas
    // cliqué « Ajouter des tailles ». L'article est alors en stock simple (compteur « En stock
    // total ») et la ligne de taille vide présente par défaut ne doit RIEN bloquer.
    const section = form?.querySelector("[data-size-stock-section]");
    if (section && section.hidden) return null;
    const rows = [...(form?.querySelectorAll("[data-size-stock-row]") || [])];
    if (!rows.length) return null;
    const nameOf = (row) => asText(row.querySelector('input[name^="stockSize_"]')?.value);
    const qtyOf = (row) => asNumber(row.querySelector('input[name^="stockQty_"]')?.value);
    const filledNames = rows.map(nameOf).filter(Boolean);
    // Une ligne sans nom mais avec une quantité est incohérente ; une ligne totalement vide est ignorée.
    const orphanQty = rows.some((row) => !nameOf(row) && qtyOf(row) > 0);
    if (orphanQty) return "Une quantité est saisie sans nom de taille. Donne un nom à la taille ou retire la quantité.";
    if (filledNames.length === 0) {
      return wasSized
        ? "Toutes les tailles ont un nom vide. Supprime les lignes inutiles ou saisis un nom pour chaque taille."
        : "Saisis au moins un nom de taille pour activer la gestion par tailles.";
    }
    const unique = new Set(filledNames);
    if (unique.size < filledNames.length) return "Deux tailles ont le même nom. Les noms de taille doivent être uniques.";
    return null;
  }

  function readSizeStockForm(form) {
    const sizes = [];
    const sizeStock = {};
    form.querySelectorAll("[data-size-stock-row]").forEach((row) => {
      const size = asText(row.querySelector('input[name^="stockSize_"]')?.value);
      if (!size) return;
      sizes.push(size);
      sizeStock[size] = asNumber(row.querySelector('input[name^="stockQty_"]')?.value);
    });
    return { sizes: [...new Set(sizes)], sizeStock };
  }

  function sizeStockFormTotal(form) {
    return sizeStockTotal(readSizeStockForm(form).sizeStock);
  }

  function sizeStockFormHasSizes(form) {
    return [...(form?.querySelectorAll('input[name^="stockSize_"]') || [])].some((input) => asText(input.value));
  }

  function updateStockTotalMode(form) {
    const input = form?.elements?.stockInitial;
    if (!input) return;
    const hint = form.querySelector("[data-stock-total-hint]");
    const hasSizes = sizeStockFormHasSizes(form);
    if (hasSizes) {
      input.value = intValue(sizeStockFormTotal(form));
      input.readOnly = true;
      input.classList.add("readonly");
      if (hint) hint.textContent = "Article avec tailles : ce total est calculé automatiquement avec les quantités par taille.";
    } else {
      input.readOnly = false;
      input.classList.remove("readonly");
      if (hint) hint.textContent = "Article sans taille : utilise simplement les flèches du compteur pour ajuster la quantité.";
    }
  }

  function updateSizeStockDialogTotal(form) {
    const total = form?.querySelector("[data-size-stock-total]");
    const quantity = sizeStockFormTotal(form);
    if (total) total.textContent = `${intValue(quantity)} article${quantity > 1 ? "s" : ""} en stock`;
    updateStockTotalMode(form);
  }

  function setupSizeStockDialogTotal(form) {
    updateSizeStockDialogTotal(form);
    form.querySelector("[data-size-stock-list]")?.addEventListener("input", () => updateSizeStockDialogTotal(form));
  }

  function showSizeStockSection(source) {
    const form = source.closest("form");
    const section = form?.querySelector("[data-size-stock-section]");
    const starter = form?.querySelector("[data-size-stock-starter]");
    if (!section) return;
    section.hidden = false;
    starter?.remove();
    updateSizeStockDialogTotal(form);
    section.querySelector('input[name^="stockSize_"]')?.focus();
  }

  function saveArticleSizeStock(article, next) {
    const soldBySize = articleSalesById().get(article.id)?.bySize || {};
    article.sizes = next.sizes;
    article.sizeStock = Object.fromEntries(next.sizes.map((size) => [
      size,
      asNumber(next.sizeStock[size]) + asNumber(soldBySize[size]),
    ]));
    article.stockInitial = sizeStockTotal(article.sizeStock);
  }

  function articleImageEditor(article, index, isDraft = false) {
    const images = articleImages(article);
    const captions = articleImageCaptions(article, images.length);
    // En création (brouillon hors-state), les actions image agissent sur le brouillon local
    // (cf. ui.stockArticleDraft) et ne persistent rien tant que « Enregistrer » n'est pas cliqué.
    const draftAttr = isDraft ? ' data-article-draft="1"' : "";
    return `<div class="article-image-editor">
      <div class="dialog-mini-title"><h3>Images</h3><span class="muted">${intValue(images.length)} photo${images.length > 1 ? "s" : ""}</span></div>
      ${images.length ? `<div class="article-image-library" data-article-image-library data-gallery-index="0">
        <div class="article-library-main">
          ${images.map((image, imageIndex) => `<figure class="${imageIndex === 0 ? "active" : ""}" data-gallery-item>
            <button class="article-library-preview" type="button" data-action="view-article-image" data-article-id="${esc(article.id || "")}" data-image-index="${imageIndex}" title="Afficher en grand">
              <img src="${esc(image)}" alt="${esc(captions[imageIndex] || article.name || "Article")}" />
            </button>
            <figcaption>${captions[imageIndex] ? esc(captions[imageIndex]) : "Sans légende"}</figcaption>
          </figure>`).join("")}
        </div>
        <div class="article-library-thumbs" aria-label="Miniatures">
          ${images.map((image, imageIndex) => `<button class="article-library-thumb ${imageIndex === 0 ? "active" : ""}" type="button" data-action="select-article-editor-image" data-image-index="${imageIndex}" data-gallery-thumb title="Afficher cette image">
            <img src="${esc(image)}" alt="${esc(captions[imageIndex] || article.name || "Article")}" />
          </button>`).join("")}
        </div>
        <div class="article-caption-list">
          ${images.map((image, imageIndex) => `<div class="article-caption-row">
            <button class="article-library-thumb mini ${imageIndex === 0 ? "active" : ""}" type="button" data-action="select-article-editor-image" data-image-index="${imageIndex}" data-gallery-thumb title="Afficher cette image">
              <img src="${esc(image)}" alt="${esc(captions[imageIndex] || article.name || "Article")}" />
            </button>
            <label class="article-caption-field">Légende ${imageIndex + 1}<input name="articleImageCaption_${imageIndex}" value="${esc(captions[imageIndex] || "")}" placeholder="Ex : pantalon noir XL" /></label>
            <div class="article-image-order-actions" aria-label="Ordre de l'image">
              <button class="icon" type="button" title="Mettre cette image en première" data-action="move-article-image" data-index="${index}" data-image-index="${imageIndex}" data-direction="first"${draftAttr} ${imageIndex === 0 ? "disabled" : ""}>1</button>
              <button class="icon" type="button" title="Monter cette image" data-action="move-article-image" data-index="${index}" data-image-index="${imageIndex}" data-direction="-1"${draftAttr} ${imageIndex === 0 ? "disabled" : ""}>↑</button>
              <button class="icon" type="button" title="Descendre cette image" data-action="move-article-image" data-index="${index}" data-image-index="${imageIndex}" data-direction="1"${draftAttr} ${imageIndex === images.length - 1 ? "disabled" : ""}>↓</button>
            </div>
            <button class="icon danger" type="button" title="Supprimer cette image" data-action="delete-article-image" data-index="${index}" data-image-index="${imageIndex}"${draftAttr}>×</button>
          </div>
          `).join("")}
        </div>
      </div>` : `<span class="article-image article-image-medium article-image-empty">IMG</span>`}
      <label class="article-image-upload">Ajouter des images<input name="articleImageFile" type="file" accept="image/*" multiple data-article-image-file${draftAttr} /></label>
      <div class="article-pending-images" data-pending-image-list hidden></div>
      <p class="muted">Ajoute plusieurs photos pour présenter l'article. La première image sert de vignette.</p>
    </div>`;
  }

  function previewArticleImageFiles(input) {
    const list = input.closest(".article-image-editor")?.querySelector("[data-pending-image-list]");
    if (!list) return;
    const files = [...(input.files || [])].filter((file) => file.type.startsWith("image/"));
    if (!files.length) {
      list.hidden = true;
      list.innerHTML = "";
      return;
    }
    list.hidden = false;
    list.innerHTML = `<strong>${files.length} image${files.length > 1 ? "s" : ""} à ajouter</strong><div class="article-pending-grid"></div>`;
    const grid = list.querySelector(".article-pending-grid");
    files.forEach((file, fileIndex) => {
      const reader = new FileReader();
      reader.onload = () => {
        const card = document.createElement("div");
        card.className = "article-pending-card";
        card.innerHTML = `
          <img src="${esc(reader.result)}" alt="${esc(file.name)}" />
          <span title="${esc(file.name)}">${esc(file.name)}</span>
          <label>Légende
            <input name="articleNewImageCaption_${fileIndex}" placeholder="Ex : vue de face, taille M..." />
          </label>`;
        grid?.appendChild(card);
      };
      reader.readAsDataURL(file);
    });
  }

  function stockTotalField(value, hasSizes = false) {
    return `<label class="stock-total-field" data-stock-total-field>En stock total
      <input name="stockInitial" type="number" step="1" min="0" value="${esc(value ?? "")}" ${hasSizes ? "readonly" : ""} />
      <small data-stock-total-hint>${hasSizes ? "Article avec tailles : ce total est calculé automatiquement avec les quantités par taille." : "Article sans taille : utilise simplement les flèches du compteur pour ajuster la quantité."}</small>
    </label>`;
  }

  function openStockArticleDialog(index, options = {}) {
    const isCreate = options.create === true;
    const article = isCreate ? options.draftArticle : state.tariffs.articles[index];
    if (!article) return;
    // En création : le brouillon est exposé pour que les actions image (déplacer/supprimer/ajouter)
    // l'éditent en local, sans le persister tant que « Enregistrer » n'est pas validé.
    if (isCreate) ui.stockArticleDraft = article;
    const row = stockRows()[index] || {};
    const hasSizes = articleHasSizes(article);
    const sizeStarter = hasSizes ? "" : `<div class="dialog-section size-stock-starter" data-size-stock-starter>
        <button type="button" data-action="show-size-stock-section">Ajouter des tailles</button>
        <p class="muted">L'article reste en compteur simple tant que tu ne renseignes aucune taille.</p>
      </div>`;
    const sizeSection = `<div class="dialog-section size-stock-form" data-size-stock-section ${hasSizes ? "" : "hidden"}>
        <div class="dialog-mini-title"><h3>Tailles</h3><button type="button" data-action="add-size-stock-row">+ taille</button></div>
        <p class="muted" data-size-stock-total>${intValue(row.available || 0)} en stock</p>
        <div data-size-stock-list>${sizeStockRows(article, row.availableBySize, { allowEmpty: !hasSizes })}</div>
        <p class="muted">${hasSizes ? "Modifie ici les quantités de chaque taille déjà utilisée par l'article." : "Renseigne au moins une taille pour passer cet article en gestion par tailles."}</p>
      </div>`;
    // En création, le tarif est saisissable directement (il alimente la même structure que la page
    // Tarifs : priceOptions[0]/defaultPrice). En édition, les champs prix restent verrouillés : le
    // prix ne se modifie alors plus que depuis Tarifs (protection par mot de passe éventuelle incluse).
    const priceLockAttr = isCreate ? "" : ' class="locked-price" readonly title="Tarif défini dans la page Tarifs"';
    const taxLockAttr = (isCreate && !isClubVatExempt()) ? "" : ' readonly class="locked-price" title="Tarif défini dans la page Tarifs"';
    const body = [
      `<div class="dialog-section stock-article-dialog-head">
        ${articleImageEditor(article, index, isCreate)}
      </div>`,
      field("name", "Article", article.name),
      field("reference", "Référence", article.reference || ""),
      field("priceSale", "Prix de vente", article.priceOptions?.[0] ?? article.defaultPrice ?? 0, "number", `step="0.01"${priceLockAttr}`),
      field("priceBuy", "Prix d'achat", article.priceOptions?.[1] ?? 0, "number", `step="0.01"${priceLockAttr}`),
      field("taxRate", "TVA %", hasSpecificTaxRate(article) ? tariffTaxRate(article) : "", "number", `step="0.01" min="0"${taxLockAttr} placeholder="${esc(intValue(effectiveDefaultVatRate()))}"`),
      isCreate
        ? `<p class="muted" style="grid-column:1/-1;margin:2px 0 0">Fixe le tarif de l'article maintenant. Après enregistrement, le prix se modifiera uniquement depuis la page Tarifs.</p>`
        : `<p class="muted" style="grid-column:1/-1;margin:2px 0 0">Les prix et la TVA se modifient uniquement dans la page <button type="button" class="link-button" data-action="open-tarifs-page">Tarifs</button>.</p>`,
      stockTotalField(row.available, hasSizes),
      field("stockAlert", "Stock alerte", article.stockAlert ?? 0, "number", 'step="1"'),
      sizeStarter,
      sizeSection,
    ].join("");
    setNextWindowKey(isCreate ? null : `stock-article:${article.id}`);
    // Snapshot AVANT mutation (Lot 5B) : uniquement en édition, l'article de création n'existe pas
    // encore dans state.tariffs.articles. Capturé avant tout champ modifié ci-dessous.
    const beforeSnapshot = isCreate ? null : shopItemSnapshot(article);
    showDialog(isCreate ? "Nouvel article" : "Modifier l'article", body, async (data, form) => {
      // Garde de MUTATION (Lot 2B) au MOMENT exact de l'enregistrement : bloque toute écriture si la
      // Boutique a été désactivée pendant que ce dialogue restait ouvert (ou après un changement de
      // club). return false -> aucune mutation, aucun persist, message affiché.
      if (!ensureFeatureEnabledForMutation("shop")) return false;
      // VALIDER avant MUTER (Lot Undo/Redo transactionnel) : la validation des tailles doit se
      // terminer AVANT toute écriture sur l'objet article réel, pour qu'un return false ci-dessous
      // laisse l'article strictement inchangé (sinon aucun checkpoint Undo ne capture la mutation).
      const parsed = readSizeStockForm(form);
      const sizeMsg = validateSizeStockForm(form, parsed, hasSizes);
      if (sizeMsg) { alert(sizeMsg); return false; }
      const nextName = data.get("name") || "Article";
      article.name = nextName;
      article.reference = data.get("reference") || makeArticleReference(nextName, index);
      article.referenceAuto = !asText(data.get("reference"));
      article.priceOptions = article.priceOptions || [];
      article.priceOptions[0] = asNumber(data.get("priceSale"));
      article.priceOptions[1] = asNumber(data.get("priceBuy"));
      article.defaultPrice = article.priceOptions[0] || 0;
      if (asText(data.get("taxRate"))) article.taxRate = Math.max(0, asNumber(data.get("taxRate")));
      else delete article.taxRate;
      article.stockAlert = asNumber(data.get("stockAlert"));
      if (parsed.sizes.length) {
        saveArticleSizeStock(article, parsed);
      } else {
        article.sizes = [];
        article.sizeStock = {};
        const sold = articleSalesById().get(article.id)?.quantity || 0;
        article.stockInitial = asNumber(data.get("stockInitial")) + sold;
      }
      const currentImages = articleImages(article);
      const nextImages = [...currentImages];
      const nextCaptions = currentImages.map((_, imageIndex) => asText(data.get(`articleImageCaption_${imageIndex}`)));
      const files = [...(form.elements.articleImageFile?.files || [])].filter((file) => file.type.startsWith("image/"));
      if (files.length) {
        for (const [fileIndex, file] of files.entries()) {
          if (!file.type.startsWith("image/")) {
            alert("Choisis uniquement des fichiers image.");
            continue;
          }
          nextImages.push(await imageFileToDataUrl(file));
          nextCaptions.push(asText(data.get(`articleNewImageCaption_${fileIndex}`)));
        }
      }
      setArticleImages(article, nextImages, nextCaptions);
      syncArticlePriceToOrders(article);
      // Mode création : l'article n'est ajouté au catalogue qu'ICI, à l'enregistrement validé.
      // (showDialog a déjà appelé recordHistory() avant onSave et appellera persist() après.)
      if (isCreate && !state.tariffs.articles.includes(article)) {
        ui.stockArticleDraft = null;
        state.tariffs.articles.push(article);
        audit.shopItemCreated(article);
        return "Article créé";
      }
      // Édition : un seul événement, uniquement si une différence métier suivie existe réellement
      // (voir shopItemAuditChanges — jamais pour une sauvegarde sans changement réel).
      if (!isCreate) {
        const changes = shopItemAuditChanges(beforeSnapshot, shopItemSnapshot(article));
        audit.shopItemUpdated(article, changes);
      }
    }, setupSizeStockDialogTotal, "", () => {
      // Annulation/fermeture sans enregistrement : on jette le brouillon, rien n'est persisté.
      if (isCreate) ui.stockArticleDraft = null;
    });
  }

  // Rafraîchit en place uniquement l'éditeur d'images du dialogue de CRÉATION, sans toucher au
  // state ni persister. Les autres champs (nom, référence, stock…) restent intacts.
  function refreshDraftArticleImageEditor(form, article) {
    if (!form || !article) return;
    const editor = form.querySelector(".article-image-editor");
    if (!editor) return;
    editor.outerHTML = articleImageEditor(article, state.tariffs.articles.length, true);
  }

  // Ajout de photos en mode création : on lit les fichiers, on les ajoute au brouillon local
  // (avec légende vide) puis on réaffiche l'éditeur pour permettre le classement immédiat.
  async function addDraftArticleImages(input) {
    const article = ui.stockArticleDraft;
    if (!article) return;
    const form = input.closest("form");
    const files = [...(input.files || [])].filter((file) => file.type.startsWith("image/"));
    if (!files.length) return;
    const images = articleImages(article);
    const captions = currentArticleImageCaptions(article, form, images.length);
    for (const file of files) {
      images.push(await imageFileToDataUrl(file));
      captions.push("");
    }
    setArticleImages(article, images, captions);
    input.value = "";
    refreshDraftArticleImageEditor(form, article);
  }

  function openArticleSizeDialog(index) {
    const article = state.tariffs.articles[index];
    if (!article) return;
    const row = stockRows()[index] || {};
    const hasSizes = articleHasSizes(article);
    const body = `
      <div class="dialog-section">
        <h3>${esc(article.name || "Article")}</h3>
        <p class="muted">${hasSizes ? "Saisis le stock réel disponible par taille. Le total sera recalculé automatiquement." : "Ajoute une première taille pour basculer cet article en gestion par tailles."}</p>
      </div>
      <div class="dialog-section size-stock-form">
        <div class="dialog-mini-title"><h3>Tailles</h3><button type="button" data-action="add-size-stock-row">+ taille</button></div>
        <p class="muted" data-size-stock-total>${intValue(row.available || 0)} en stock</p>
        <div data-size-stock-list>${sizeStockRows(article, row.availableBySize, { allowEmpty: true })}</div>
      </div>`;
    // Chemin de sauvegarde SÉPARÉ du dialogue article (openStockArticleDialog) : même liste
    // blanche, même événement (shop.item.updated), snapshot avant/après autour de la seule mutation
    // réelle ici (saveArticleSizeStock).
    const beforeSnapshot = shopItemSnapshot(article);
    showDialog("Stock par taille", body, (data, form) => {
      const next = readSizeStockForm(form);
      const msg = validateSizeStockForm(form, next, hasSizes);
      if (msg) { alert(msg); return false; }
      saveArticleSizeStock(article, next);
      audit.shopItemUpdated(article, shopItemAuditChanges(beforeSnapshot, shopItemSnapshot(article)));
    }, setupSizeStockDialogTotal);
  }

  function orderSizeKeys(article = {}, item = {}) {
    return [...new Set([...(article.sizes || []), ...Object.keys(item.sizes || {})].filter(Boolean))];
  }

  function sizeQtyFieldName(articleId, size) {
    return `sizeQty_${articleId}_${size}`;
  }

  function orderSizeEditor(article, item = {}, stock = {}) {
    const sizes = orderSizeKeys(article, item);
    if (!sizes.length) {
      const current = asNumber(item.quantity);
      const available = asNumber(stock?.available) + current;
      return `<div class="order-stock-control">
        <input name="qty_${esc(article.id)}" data-order-summary-input data-order-stock-input data-stock-available="${esc(available)}" data-stock-threshold="${esc(article.stockAlert || 0)}" data-order-qty="${esc(article.id)}" type="number" step="1" min="0" value="${esc(current || "")}" />
        <small data-order-stock-message></small>
      </div>`;
    }
    const currentSizes = item.sizes || {};
    const total = Object.values(currentSizes).reduce((sum, quantity) => sum + asNumber(quantity), 0) || asNumber(item.quantity);
    const lines = sizes.map((size) => {
      const current = asNumber(currentSizes[size]);
      const available = stock.availableBySize?.[size];
      const availableForSize = available === undefined ? "" : asNumber(available) + current;
      const availableText = available === undefined ? "stock ?" : `reste ${intValue(availableForSize)}`;
      return `<label class="order-size-pill">
        <span>${esc(size)}</span>
        <input name="${esc(sizeQtyFieldName(article.id, size))}" data-order-summary-input data-order-stock-input data-stock-available="${esc(availableForSize)}" data-stock-threshold="${esc(article.stockAlert || 0)}" data-order-size-qty="${esc(article.id)}" type="number" step="1" min="0" value="${esc(current || "")}" />
        <small>${esc(availableText)}</small>
        <small data-order-stock-message></small>
      </label>`;
    }).join("");
    return `<details class="order-size-editor">
      <summary><strong data-order-size-total="${esc(article.id)}">${intValue(total)}</strong> article${total > 1 ? "s" : ""} · tailles</summary>
      <div class="order-size-grid">${lines}</div>
      <input type="hidden" name="qty_${esc(article.id)}" data-order-qty="${esc(article.id)}" value="${esc(total || "")}" />
    </details>`;
  }

  function stockMovementRow(row) {
    return `<tr>
      <td>${personCell(row.order)}</td>
      <td>${esc(row.article.name || "Article supprimé")}</td>
      <td>${esc(row.sizes)}</td>
      <td class="money">-${intValue(row.quantity)}</td>
      <td class="money">${money(row.total)}</td>
    </tr>`;
  }

  function isStockLow(row) {
    const threshold = asNumber(row.article.stockAlert);
    return row.available < 0 || (threshold > 0 && row.available <= threshold);
  }

  function stockAlertTone(row) {
    const threshold = asNumber(row.article.stockAlert);
    if (row.available < 0) return "stock-negative";
    if (threshold > 0 && row.available <= threshold) return "stock-warning";
    return "";
  }

  // Tonalité du badge de statut (réutilise les pastilles doc-badge des modules sport).
  function stageStatusBadgeTone(stage = {}) {
    const c = stageStatusClass(stage);
    return c === "stage-open" ? "doc-ok" : c === "stage-reopened" ? "doc-soon" : "doc-missing";
  }

  function stageInfoRow(label, value) {
    return value ? `<div class="stage-info-row"><dt>${esc(label)}</dt><dd>${value}</dd></div>` : "";
  }

  // Carte « Informations du stage » : toute l'identité du stage en un seul endroit
  // (principe « une carte = une responsabilité »). N'affiche que les données présentes.
  function stageInfoCardHtml(stage) {
    const price = `${money(asNumber(stage.unitPrice))}${hasSpecificTaxRate(stage) ? ` <span class="muted">(TVA ${esc(intValue(tariffTaxRate(stage)))} %)</span>` : ""}`;
    const coach = coachLabelFor(stage.coachId, stage.coach);
    const room = roomLabelFor(stage.roomId, stage.location);
    const lodging = stage.lodgingName ? `${esc(stage.lodgingName)} — ${money(asNumber(stage.lodgingUnitPrice))}` : "";
    // « Investissement » volontairement absent de la fiche principale : donnée de gestion
    // interne, conservée dans le modèle et dans l'édition du stage (openStageDialog), mais
    // hors de la lecture opérationnelle quotidienne.
    const rows = [
      stageInfoRow("Dates", esc(stageDateRangeLabel(stage))),
      stageInfoRow("Date limite d'inscription", stage.registrationDeadline ? esc(dateDisplay(stage.registrationDeadline)) : ""),
      stageInfoRow("Public autorisé", esc(stagePublicAccessLabel(stage.publicAccess))),
      stageInfoRow("Coach / intervenant", coach ? esc(coach) : ""),
      stageInfoRow("Salle / lieu", room ? esc(room) : ""),
      stageInfoRow("Tarif du stage", price),
      stageInfoRow("Hébergement", lodging),
    ].join("");
    return `<div class="band stage-info-band ${stageStatusClass(stage)}">
      <div class="band-title stage-info-title">
        <h2>Informations du stage</h2>
        <span class="doc-badge ${stageStatusBadgeTone(stage)}">${esc(stageStatusLabel(stage))}</span>
      </div>
      <div class="stage-info-name">${esc(stage.name || "Stage")}</div>
      <dl class="stage-info-grid">${rows}</dl>
      ${stage.registrationReopened ? `<p class="stage-info-note">Réactivation exceptionnelle : les nouvelles inscriptions sont de nouveau possibles.</p>`
        : stageIsPast(stage) ? `<p class="stage-info-note">Les inscriptions sont stoppées, mais les paiements et la comptabilité restent conservés.</p>` : ""}
    </div>`;
  }

  function renderStages() {
    const stage = stageById(ui.stageId);
    if (!state.tariffs.stages.length) {
      return `<div class="band pad">${emptyStateHtml("stages")}</div>`;
    }
    const rows = (state.stageRegistrations[stage.id] || [])
      .filter((row) => includesQuery(row, ui.query))
      .filter((row) => !ui.stageDueOnly || calcRegistration(row, stage.id).restDue > 0)
      .sort((a, b) => personKey(a).localeCompare(personKey(b)));
    const total = rows.reduce((sum, row) => sum + calcRegistration(row, stage.id).total, 0);
    const paid = rows.reduce((sum, row) => sum + calcRegistration(row, stage.id).paid, 0);
    const due = rows.reduce((sum, row) => sum + calcRegistration(row, stage.id).restDue, 0);
    const stageButtons = `<div class="segmented stage-tabs">${state.tariffs.stages.map((item) => `<button data-stage-id="${item.id}" class="${stage.id === item.id ? "active" : ""} ${stageStatusClass(item)}" title="${esc(`${stageStatusLabel(item)} - ${stageDateRangeLabel(item)}`)}"><span>${esc(item.name)}</span><small>${esc(stageStatusLabel(item))}</small></button>`).join("")}</div>`;
    const registrationsClosed = stageRegistrationClosed(stage);
    const canToggleRegistration = stageNaturallyClosed(stage) || stage.registrationReopened;
    return `
      ${overviewBand("stages", "Stages en un coup d'oeil", [
        { label: "Participants", value: rows.length },
        { label: "Total", value: money(total) },
        { label: "Réglé", value: money(paid) },
        { label: "Reste dû", value: money(due), action: "show-overview-due", scope: "stages", stageId: stage.id, title: "Voir les participants avec un reste dû" },
      ])}
      <div class="toolbar stage-toolbar">
        <div class="left">
          <input class="search" data-focus="query" data-filter="query" placeholder="Rechercher" value="${esc(ui.query)}" />
          ${stageButtons}
          <div class="segmented">${dueFilterButton("stageDueOnly", ui.stageDueOnly)}</div>
        </div>
        <div class="right">
          <button data-action="add-stage">Nouveau stage</button>
          <button data-action="duplicate-stage" data-stage-id="${esc(stage.id)}">Relancer ce stage</button>
          <button data-action="edit-stage" data-stage-id="${esc(stage.id)}">Modifier le stage</button>
          ${canToggleRegistration ? `<button data-action="${stage.registrationReopened ? "close-stage-registration" : "reactivate-stage"}" data-stage-id="${esc(stage.id)}">${stage.registrationReopened ? "Refermer inscriptions" : "Réactiver inscriptions"}</button>` : ""}
          <button class="danger" data-action="delete-stage" data-stage-id="${esc(stage.id)}" ${stageParticipantCount(stage.id) ? "disabled" : ""}>Supprimer stage vide</button>
          <button class="primary" data-action="add-registration" data-stage-id="${esc(stage.id)}" ${registrationsClosed ? "disabled" : ""} title="${registrationsClosed ? "Les inscriptions de ce stage sont fermées." : "Ajouter un participant"}">Nouvelle inscription</button>
        </div>
      </div>
      ${stageInfoCardHtml(stage)}
      <div class="band discipline-binder stage-participants-band ${stageStatusClass(stage)}">
        <div class="band-title"><h2>Participants</h2><strong>${rows.length}</strong></div>
        ${stageRegistrationBinder(rows, stage.id)}
      </div>`;
  }

  function registrationRow(row, stageId) {
    const stage = stageById(stageId);
    // F2-AUDIT-002 — calc.event/calc.lodging (calcRegistration claim-aware) plutôt que
    // calcStageSegment séparé : reste dû/payé par segment reflètent les règlements créés depuis une
    // facture après émission. Les totaux BRUTS (tarif) affichés dans les colonnes Stage/Hébergement
    // restent ceux du segment (montant de référence, pas un « payé/reste dû »).
    const event = calcStageSegment(row.event || {});
    const lodging = calcStageSegment(row.lodging || {});
    const calc = calcRegistration(row, stageId);
    return `<tr>
      <td>${personCell(row)}</td><td>
        <div class="payment-stack">
          <strong>Stage</strong>
          ${paymentControls("registration", row.id, row.event?.payments || [], { stageId, part: "event", total: event.subtotal, defaultTaxRate: stageDefaultTaxRate(stage) })}
          <strong>Hébergement</strong>
          ${paymentControls("registration", row.id, row.lodging?.payments || [], { stageId, part: "lodging", total: lodging.subtotal, defaultTaxRate: lodgingDefaultTaxRate(stage) })}
        </div>
      </td>
      <td class="money">${money(event.subtotal)}</td><td class="money">${money(lodging.subtotal)}</td>
      <td class="money">${money(calc.total)}</td><td class="money">${money(calc.restDue)}</td>
      <td><div class="actions"><button class="icon" title="Modifier" data-action="edit-registration" data-stage-id="${stageId}" data-id="${row.id}">✎</button><button class="icon danger" title="Supprimer" data-action="delete-registration" data-stage-id="${stageId}" data-id="${row.id}">×</button></div></td>
    </tr>`;
  }

  function stageRegistrationBinder(rows, stageId) {
    return alphabetBinder(rows, {
      empty: "Aucune inscription",
      selectedLetter: ui.stageLetter,
      action: "set-stage-letter",
      card: (row) => registrationCard(row, stageId),
    });
  }

  function registrationCard(row, stageId) {
    const stage = stageById(stageId);
    const event = calcStageSegment(row.event || {});
    const lodging = calcStageSegment(row.lodging || {});
    const calc = calcRegistration(row, stageId);
    const tone = registrationPaymentTone(row, calc);
    return `<article class="membership-card registration-line payment-${tone}" data-action="edit-registration" data-stage-id="${esc(stageId)}" data-id="${esc(row.id)}">
      <div class="membership-card-head">
        ${personCell(row)}
      </div>
      <div class="membership-card-totals">
        <div><span>Stage</span><strong>${money(event.subtotal)}</strong></div>
        <div><span>Hébergement</span><strong>${money(lodging.subtotal)}</strong></div>
        <div class="${calc.restDue > 0 ? "due" : ""}"><span>Reste dû</span><strong>${money(calc.restDue)}</strong></div>
      </div>
      <div class="payment-stack registration-payments">
        <strong>Stage</strong>
        ${paymentControls("registration", row.id, row.event?.payments || [], { stageId, part: "event", total: event.subtotal, defaultTaxRate: stageDefaultTaxRate(stage) })}
      </div>
      <div class="payment-stack registration-payments">
        <strong>Hébergement</strong>
        ${paymentControls("registration", row.id, row.lodging?.payments || [], { stageId, part: "lodging", total: lodging.subtotal, defaultTaxRate: lodgingDefaultTaxRate(stage) })}
      </div>
    </article>`;
  }

  function registrationPaymentTone(row, calc = calcRegistration(row)) {
    const payments = [...(row.event?.payments || []), ...(row.lodging?.payments || [])];
    return paymentToneFromPayments(payments, calc.restDue);
  }

  function disciplineUsageStats() {
    // Lot 3A (D3) — agrégation par IDENTIFIANT de discipline quand il existe : deux disciplines
    // homonymes d'id distincts ne sont plus fusionnées. Repli historique par nom normalisé pour les
    // adhésions anciennes sans id (jamais fusionnées au hasard avec une discipline canonique). Le
    // libellé affiché suit l'id (nom courant), sinon le nom historique stocké. Isolé par club actif.
    const disciplineKey = (discipline) => discipline.id ? `id:${asText(discipline.id)}` : `legacy:${disciplineNameKey(discipline.name)}`;
    const membershipKey = (membership) => {
      if (asText(membership.disciplineId)) return `id:${asText(membership.disciplineId)}`;
      return `legacy:${disciplineNameKey(membership.discipline)}`;
    };
    const map = new Map(state.tariffs.disciplines.map((discipline) => [disciplineKey(discipline), {
      name: discipline.name || "Sans discipline",
      count: 0,
      total: 0,
      paid: 0,
      due: 0,
      gain: 0,
    }]));
    for (const membership of state.memberships) {
      const key = membershipKey(membership);
      const label = disciplineLabelFor(membership) || asText(membership.discipline) || "Sans discipline";
      const row = map.get(key) || { name: label, count: 0, total: 0, paid: 0, due: 0, gain: 0 };
      const calc = calcMembership(membership);
      row.count += 1;
      row.total += calc.total;
      row.paid += calc.paid;
      row.due += calc.restDue;
      row.gain += calc.clubGain;
      map.set(key, row);
    }
    return [...map.values()].sort((a, b) => b.count - a.count || b.total - a.total);
  }

  function stageUsageStats() {
    // Lot 2D — statistiques d'usage = calcul historique inconditionnel (comme boutiqueUsageStats). Le
    // masquage éventuel de la section (affichage) se décide dans renderStats/exports, jamais ici : la
    // donnée rapportée reste identique quel que soit showStages / hasFeature.
    return state.tariffs.stages.map((stage) => {
      const rows = state.stageRegistrations[stage.id] || [];
      return rows.reduce((acc, registration) => {
        const calc = calcRegistration(registration, stage.id);
        acc.count += 1;
        acc.total += calc.total;
        acc.paid += calc.paid;
        acc.due += calc.restDue;
        return acc;
      }, { name: stage.name || "Stage", count: 0, total: 0, paid: 0, due: 0 });
    }).sort((a, b) => b.count - a.count || b.total - a.total);
  }

  function boutiqueUsageStats() {
    // Lot 2B — point bloquant 1 : statistiques d'usage = calcul historique inconditionnel. Le masquage
    // éventuel de la section (settings.display.showBoutique) se décide à l'affichage (renderStats),
    // pas ici : la donnée exportée/rapportée reste identique quel que soit l'état d'affichage.
    const stockById = new Map(stockRows().map((row) => [row.article.id, row]));
    const map = new Map(state.tariffs.articles.map((article) => [article.id, {
      id: article.id,
      name: article.name || "Article",
      quantity: 0,
      total: 0,
      orders: 0,
      stock: stockById.get(article.id)?.available || 0,
    }]));
    for (const order of state.shopOrders) {
      for (const item of order.items || []) {
        const quantity = asNumber(item.quantity);
        if (!quantity) continue;
        const article = articleById(item.articleId);
        const row = map.get(item.articleId) || { id: item.articleId, name: article.name || "Article", quantity: 0, total: 0, orders: 0, stock: 0 };
        row.quantity += quantity;
        row.total += quantity * asNumber(item.unitPrice);
        row.orders += 1;
        map.set(item.articleId, row);
      }
    }
    return [...map.values()].sort((a, b) => b.quantity - a.quantity || b.total - a.total);
  }

  function statsTable(headers, rows, emptyLabel, footerRow = "") {
    if (!rows.length) return `<div class="empty">${esc(emptyLabel)}</div>`;
    return `<div class="table-wrap"><table>
      <thead><tr>${headers.map((header) => `<th class="${header.className || ""}">${esc(header.label)}</th>`).join("")}</tr></thead>
      <tbody>${rows.join("")}</tbody>
      ${footerRow ? `<tfoot>${footerRow}</tfoot>` : ""}
    </table></div>`;
  }

  // KPI « Coachs & salles » pour la page Statistiques. Réutilise les helpers d'alertes
  // existants (pendingCoachReplacements / pendingRoomReplacements) ; tout est lu sur le
  // club actif (state.coaches / state.rooms déjà filtrés par club). « à remplacer » = nombre
  // de coachs/salles DISTINCTS ayant au moins une séance en attente de remplacement.
  // « sans e-mail » ne compte que les actifs (on ne contacte pas un archivé).
  function statsCoachRoomKpis() {
    const coaches = state.coaches || [];
    const rooms = state.rooms || [];
    const coachReplace = typeof pendingCoachReplacements === "function"
      ? new Set(pendingCoachReplacements().map((x) => x.coach && x.coach.id).filter(Boolean)).size : 0;
    const roomReplace = typeof pendingRoomReplacements === "function"
      ? new Set(pendingRoomReplacements().map((x) => x.room && x.room.id).filter(Boolean)).size : 0;
    return [
      { label: "Coachs actifs", value: intValue(coaches.filter((c) => !c.archived).length) },
      { label: "Coachs archivés", value: intValue(coaches.filter((c) => c.archived).length) },
      { label: "Coachs à remplacer", value: intValue(coachReplace) },
      { label: "Coachs sans e-mail", value: intValue(coaches.filter((c) => !c.archived && !asText(c.email)).length) },
      { label: "Salles actives", value: intValue(rooms.filter((r) => !r.archived).length) },
      { label: "Salles archivées", value: intValue(rooms.filter((r) => r.archived).length) },
      { label: "Salles à remplacer", value: intValue(roomReplace) },
      { label: "Responsables sans e-mail", value: intValue(rooms.filter((r) => !r.archived && !asText(r.managerEmail)).length) },
    ];
  }
  // KPI « Synthèse comptable » : EXACTEMENT la même logique que la page Comptabilité
  // (mêmes helpers, même formule du solde corrigé) → aucun recalcul divergent, aucun double comptage.
  function statsAccountingKpis() {
    const data = accountingData();
    const expenseTotalAll = expensesTotal(clubExpenses());
    // F2-REAUDIT-006 — cashPaid (avoirs utilisés exclus) : creditNoteActiveTotal() retranche déjà les
    // avoirs encore actifs. Utiliser data.totals.paid (avoir-inclusive) ici double-comptait un avoir
    // utilisé (−50 sur avoirTotal ET +50 sur paid = +100 sur le solde corrigé pour un avoir de 50€).
    const customTotal = customIncomeCashTotal();
    const avoirTotal = creditNoteActiveTotal();
    const refundTotal = refundExpenseTotal();
    const correctedBalance = (data.totals.cashPaid - expenseTotalAll) + customTotal - avoirTotal;
    return [
      { label: "Recettes custom", value: money(customTotal) },
      { label: "Dépenses saisies", value: money(expenseTotalAll) },
      { label: "Remboursements", value: money(refundTotal) },
      { label: "Avoirs actifs", value: money(avoirTotal) },
      { label: "Solde corrigé", value: money(correctedBalance) },
    ];
  }

  // ===== Affichage conditionnel des sections de statistiques selon l'usage réel des modules =====
  // Règle : une section s'affiche si son module est VISIBLE dans le mode d'affichage courant
  // (navigation) OU s'il possède déjà des DONNÉES (on ne cache jamais de l'historique).
  // Lecture seule : aucune donnée supprimée, aucun calcul modifié — on conditionne l'affichage.
  function hasStageData() {
    return (state.tariffs && state.tariffs.stages || []).length > 0
      || Object.values(state.stageRegistrations || {}).some((list) => (list || []).length > 0);
  }
  function hasBoutiqueData() {
    return (state.tariffs && state.tariffs.articles || []).length > 0 || (state.shopOrders || []).length > 0;
  }
  function hasCoachData() { return (state.coaches || []).length > 0; }
  function hasRoomData() { return (state.rooms || []).length > 0; }
  function hasGroupData() { return (state.groups || []).length > 0; }
  function hasPlanningData() { return (state.planningCourses || []).length > 0; }
  function hasAttendanceData() { return (state.attendanceSessions || []).length > 0; }
  function hasDocumentData() {
    return (state.memberships || []).some((m) => asText(m.licenseNumber) || asText(m.medicalCertificateDate)
      || asText(m.medicalCertificateEndDate) || m.medicalCertificate === true
      || (Array.isArray(m.documents) && m.documents.length));
  }
  function hasAccountingData() {
    return (state.memberships || []).length > 0 || (state.expenses || []).length > 0
      || (state.shopOrders || []).length > 0 || (state.invoices || []).length > 0
      || (state.creditNotes || []).length > 0
      || Object.values(state.stageRegistrations || {}).some((list) => (list || []).length > 0);
  }
  function statsModuleHasData(moduleKey) {
    switch (moduleKey) {
      case "coaches": return hasCoachData();
      case "rooms": return hasRoomData();
      case "stages": return hasStageData();
      case "boutique": case "stock": return hasBoutiqueData();
      case "accounting": return hasAccountingData();
      case "groups": return hasGroupData();
      case "planning": return hasPlanningData();
      case "attendance": return hasAttendanceData();
      case "documents": return hasDocumentData();
      default: return true;
    }
  }
  function shouldShowStatsSection(moduleKey) {
    const visible = (typeof isModuleVisibleByMode === "function") ? isModuleVisibleByMode(moduleKey) : true;
    return visible || statsModuleHasData(moduleKey);
  }

  function renderStats() {
    // Lot 2D — la section Stages (rapport historique) ne dépend plus de la fonctionnalité ni de
    // l'affichage : elle suit les DONNÉES (jamais absente uniquement parce que Stages est désactivé ou
    // masqué ; seulement absente s'il n'existe aucune donnée Stages).
    const stagesEnabled = hasStageData();
    const boutiqueEnabled = isModuleEnabled("boutique");
    // Sections conditionnées : module visible (mode courant) OU données présentes.
    const showStagesStats = stagesEnabled && shouldShowStatsSection("stages");
    const showBoutiqueStats = boutiqueEnabled && shouldShowStatsSection("boutique");
    const showStaffStats = shouldShowStatsSection("coaches") || shouldShowStatsSection("rooms");
    const showAccountingStats = shouldShowStatsSection("accounting");
    const disciplineRows = disciplineUsageStats();
    const stageRows = stageUsageStats();
    const boutiqueRows = boutiqueUsageStats();
    const totalMembers = disciplineRows.reduce((sum, row) => sum + row.count, 0);
    const totalStageParticipants = stageRows.reduce((sum, row) => sum + row.count, 0);
    const totalShopArticles = boutiqueEnabled ? state.tariffs.articles.filter((article) => article.active !== false).length : 0;
    const disciplineTotals = disciplineRows.reduce((totals, row) => ({
      count: totals.count + row.count,
      total: totals.total + row.total,
      paid: totals.paid + row.paid,
      due: totals.due + row.due,
    }), { count: 0, total: 0, paid: 0, due: 0 });
    const stageTotals = stageRows.reduce((totals, row) => ({
      count: totals.count + row.count,
      total: totals.total + row.total,
      paid: totals.paid + row.paid,
      due: totals.due + row.due,
    }), { count: 0, total: 0, paid: 0, due: 0 });
    const boutiqueTotals = boutiqueRows.reduce((totals, row) => ({
      quantity: totals.quantity + row.quantity,
      orders: totals.orders + row.orders,
      stock: totals.stock + row.stock,
      total: totals.total + row.total,
    }), { quantity: 0, orders: 0, stock: 0, total: 0 });
    const kpiItems = [
      { label: "Adhérents disciplines", value: intValue(totalMembers) },
      showStagesStats ? { label: "Participants stages", value: intValue(totalStageParticipants) } : null,
      showBoutiqueStats ? { label: "Articles boutique", value: intValue(totalShopArticles) } : null,
      { label: "Adhérents", value: intValue(state.contacts.members.length) },
      { label: "Non-adhérents", value: intValue(state.contacts.prospects.length) },
    ].filter(Boolean);
    return `
      ${kpis(kpiItems)}
      ${gridItems([
        chartBand("Utilisation disciplines", disciplineRows.map((row) => [row.name, row.count]), intValue),
        showStagesStats ? chartBand("Utilisation stages", stageRows.map((row) => [row.name, row.count]), intValue) : "",
        showBoutiqueStats ? chartBand("Achats boutique", boutiqueRows.map((row) => [row.name, row.quantity]), intValue) : "",
      ], 3)}
      ${gridItems([
        `<div class="band">
          <div class="band-title"><h2>Disciplines</h2></div>
          ${statsTable([
            { label: "Discipline" },
            { label: "Adhérents", className: "money" },
            { label: "Total", className: "money" },
            { label: "Réglé", className: "money" },
            { label: "Reste dû", className: "money" },
          ], disciplineRows.map((row) => `<tr><td>${esc(row.name)}</td><td class="money">${intValue(row.count)}</td><td class="money">${money(row.total)}</td><td class="money">${money(row.paid)}</td><td class="money">${money(row.due)}</td></tr>`), "Aucune discipline",
            `<tr><td>Total</td><td class="money">${intValue(disciplineTotals.count)}</td><td class="money">${money(disciplineTotals.total)}</td><td class="money">${money(disciplineTotals.paid)}</td><td class="money">${money(disciplineTotals.due)}</td></tr>`)}
        </div>`,
        showStagesStats ? `<div class="band">
          <div class="band-title"><h2>Stages</h2></div>
          ${statsTable([
            { label: "Stage" },
            { label: "Participants", className: "money" },
            { label: "Total", className: "money" },
            { label: "Réglé", className: "money" },
            { label: "Reste dû", className: "money" },
          ], stageRows.map((row) => `<tr><td>${esc(row.name)}</td><td class="money">${intValue(row.count)}</td><td class="money">${money(row.total)}</td><td class="money">${money(row.paid)}</td><td class="money">${money(row.due)}</td></tr>`), "Aucun stage",
            `<tr><td>Total</td><td class="money">${intValue(stageTotals.count)}</td><td class="money">${money(stageTotals.total)}</td><td class="money">${money(stageTotals.paid)}</td><td class="money">${money(stageTotals.due)}</td></tr>`)}
        </div>` : "",
        showBoutiqueStats ? `<div class="band">
          <div class="band-title"><h2>Boutique</h2></div>
          ${statsTable([
            { label: "Article" },
            { label: "Vendu", className: "money" },
            { label: "Commandes", className: "money" },
            { label: "En stock", className: "money" },
            { label: "Total vendu", className: "money" },
          ], boutiqueRows.map((row) => `<tr><td>${esc(row.name)}</td><td class="money">${intValue(row.quantity)}</td><td class="money">${intValue(row.orders)}</td><td class="money">${intValue(row.stock)}</td><td class="money">${money(row.total)}</td></tr>`), "Aucun achat boutique",
            `<tr><td>Total</td><td class="money">${intValue(boutiqueTotals.quantity)}</td><td class="money">${intValue(boutiqueTotals.orders)}</td><td class="money">${intValue(boutiqueTotals.stock)}</td><td class="money">${money(boutiqueTotals.total)}</td></tr>`)}
        </div>` : "",
      ], 3)}
      ${gridItems([
        pieChartBand("Chiffres disciplines", disciplineRows.map((row) => [row.name, row.total, row.count]), money, "Total", "adh.", "disciplines"),
        showStagesStats ? pieChartBand("Chiffres stages", stageRows.map((row) => [row.name, row.total, row.count]), money, "Total", "part.", "stages") : "",
        showBoutiqueStats ? pieChartBand("Chiffres boutique", boutiqueRows.map((row) => [row.name, row.total, row.quantity]), money, "Total vendu", "vendu", "boutique") : "",
      ], 3)}
      ${showStaffStats ? `<h2 class="stats-kpi-title">Coachs &amp; salles</h2>${kpis(statsCoachRoomKpis())}` : ""}
      ${showAccountingStats ? `<h2 class="stats-kpi-title">Synthèse comptable</h2>${kpis(statsAccountingKpis())}` : ""}
    `;
  }

  function refusedAmount(payments = []) {
    return (payments || []).reduce((sum, payment) => {
      return paymentStatus(payment) === "Refusé" ? sum + asNumber(payment.amount) : sum;
    }, 0);
  }

  function accountingData() {
    // Lot 2B/2D — point bloquant 1 : la comptabilité est un CALCUL HISTORIQUE. Les commandes, le stock,
    // les inscriptions et l'investissement des stages existants comptent toujours ; settings.display
    // (showBoutique/showStages) et hasFeature n'y ont AUCUNE influence — seuls les totaux/synthèses
    // restent la source unique (aucun 2e moteur).
    // F2-REAUDIT-005 — paid/tax/refused dérivés des MÊMES slices canoniques (claimCanonicalPaymentSlices) :
    // un règlement créé depuis une facture après émission (invoice.paymentsAfterIssue) est déjà compté
    // dans calc.paid (via claimFinancialState) et doit l'être EXACTEMENT autant dans tax/refused — plus
    // jamais "paid vivant + tax source-only". Repli sur l'ancien calcul pur si la ligne n'a pas encore
    // d'id (cas théorique, jamais rencontré sur une donnée réellement persistée, même garde que calcMembership).
    const disciplineRows = state.memberships.map((membership) => {
      const calc = calcMembership(membership);
      const license = asNumber(calc.license);
      const claim = membership.id ? claimCanonicalPaymentSlices(`membership:${membership.id}`) : null;
      const tax = claim ? claimSlicesTax(claim.slices) : paidTaxAmount(membership.payments);
      const paidNet = calc.paid - tax;
      // F2-REAUDIT-006 — cashPaid/cashTax/cashPaidNet : mêmes slices, mais un avoir utilisé (slice.cash
      // === false) en est exclu. paid/tax/paidNet/due/result restent inchangés (règlement de la créance,
      // avoir inclus) ; seuls ces trois champs dérivés alimentent les affichages "encaissé"/bancaires.
      const cashPaid = claim ? claimSlicesCash(claim.slices) : calc.paid;
      const cashTax = claim ? claimSlicesTax(claim.slices.filter((s) => s.cash !== false)) : tax;
      return {
        module: "Disciplines",
        name: [membership.lastName, membership.firstName].filter(Boolean).join(" ") || "Adhérent",
        detail: membership.discipline || "",
        total: calc.total,
        paid: calc.paid,
        tax,
        paidNet,
        cashPaid,
        cashTax,
        cashPaidNet: cashPaid - cashTax,
        due: calc.restDue,
        costs: license,
        result: paidNet - license,
        refused: claim ? claim.refused : refusedAmount(membership.payments),
      };
    });
    // Lot 2D — point bloquant : la comptabilité est un CALCUL HISTORIQUE inconditionnel. Les inscriptions
    // et l'investissement des stages existants comptent TOUJOURS (comme orderRows Boutique), quel que
    // soit showStages ou hasFeature. Masquer/désactiver ne retire jamais l'historique des totaux.
    const stageRows = state.tariffs.stages.flatMap((stage) => (state.stageRegistrations[stage.id] || []).map((registration) => {
      const calc = calcRegistration(registration, stage.id);
      const payments = [...(registration.event?.payments || []), ...(registration.lodging?.payments || [])];
      // event/lodging restent deux claims INDÉPENDANTS (même doctrine que calcRegistration) : leurs
      // slices/tax/refused s'additionnent, jamais fusionnés en un seul claim.
      const eventClaim = registration.id ? claimCanonicalPaymentSlices(`stage:${stage.id}:${registration.id}:event`) : null;
      const lodgingClaim = registration.id ? claimCanonicalPaymentSlices(`stage:${stage.id}:${registration.id}:lodging`) : null;
      const tax = (eventClaim || lodgingClaim)
        ? claimSlicesTax(eventClaim?.slices || []) + claimSlicesTax(lodgingClaim?.slices || [])
        : paidTaxAmount(payments);
      const paidNet = calc.paid - tax;
      const refused = (eventClaim || lodgingClaim)
        ? asNumber(eventClaim?.refused) + asNumber(lodgingClaim?.refused)
        : refusedAmount(payments);
      const cashPaid = (eventClaim || lodgingClaim)
        ? claimSlicesCash(eventClaim?.slices || []) + claimSlicesCash(lodgingClaim?.slices || [])
        : calc.paid;
      const cashTax = (eventClaim || lodgingClaim)
        ? claimSlicesTax((eventClaim?.slices || []).filter((s) => s.cash !== false)) + claimSlicesTax((lodgingClaim?.slices || []).filter((s) => s.cash !== false))
        : tax;
      return {
        module: "Stages",
        name: [registration.lastName, registration.firstName].filter(Boolean).join(" ") || "Participant",
        detail: stage.name || "Stage",
        total: calc.total,
        paid: calc.paid,
        tax,
        paidNet,
        cashPaid,
        cashTax,
        cashPaidNet: cashPaid - cashTax,
        due: calc.restDue,
        costs: 0,
        result: paidNet,
        refused,
      };
    }));
    const stageInvestmentRows = state.tariffs.stages
      .filter((stage) => asNumber(stage.investment))
      .map((stage) => ({
        module: "Stages",
        name: stage.name || "Stage",
        detail: "Investissement stage",
        total: 0,
        paid: 0,
        tax: 0,
        paidNet: 0,
        cashPaid: 0,
        cashTax: 0,
        cashPaidNet: 0,
        due: 0,
        costs: asNumber(stage.investment),
        result: -asNumber(stage.investment),
        refused: 0,
      }));
    const orderRows = state.shopOrders.map((order) => {
      const calc = calcOrder(order);
      const costs = orderItemDetails(order).reduce((sum, item) => {
        const article = articleById(item.articleId);
        return sum + item.quantity * asNumber(article.priceOptions?.[1]);
      }, 0);
      const claim = order.id ? claimCanonicalPaymentSlices(`order:${order.id}`) : null;
      const tax = claim ? claimSlicesTax(claim.slices) : paidTaxAmount(order.payments);
      const paidNet = calc.paid - tax;
      const cashPaid = claim ? claimSlicesCash(claim.slices) : calc.paid;
      const cashTax = claim ? claimSlicesTax(claim.slices.filter((s) => s.cash !== false)) : tax;
      return {
        module: "Boutique",
        name: [order.lastName, order.firstName].filter(Boolean).join(" ") || "Client",
        detail: orderItemDetails(order).map((item) => `${item.article.name || "Article"} x${intValue(item.quantity)}`).join(", "),
        total: calc.total,
        paid: calc.paid,
        tax,
        paidNet,
        cashPaid,
        cashTax,
        cashPaidNet: cashPaid - cashTax,
        due: calc.restDue,
        costs,
        result: paidNet - costs,
        refused: claim ? claim.refused : refusedAmount(order.payments),
      };
    });
    const rows = [...disciplineRows, ...stageRows, ...stageInvestmentRows, ...orderRows];
    const stock = stockRows();
    const stockInvestment = stock.reduce((sum, row) => sum + Math.max(0, row.available) * asNumber(row.purchasePrice), 0);
    const totalInvestment = stock.reduce((sum, row) => sum + Math.max(0, row.available + row.sold) * asNumber(row.purchasePrice), 0);
    const soldPurchaseCost = stock.reduce((sum, row) => sum + Math.max(0, row.sold) * asNumber(row.purchasePrice), 0);
    const negativeStockValue = stock.reduce((sum, row) => sum + Math.max(0, -row.available) * asNumber(row.purchasePrice), 0);
    const disciplineInvestment = disciplineRows.reduce((sum, row) => sum + row.costs, 0);
    const stageInvestment = stageInvestmentRows.reduce((sum, row) => sum + row.costs, 0);
    const knownInvestment = disciplineInvestment + stageInvestment + totalInvestment;
    const totals = rows.reduce((acc, row) => ({
      total: acc.total + row.total,
      paid: acc.paid + row.paid,
      tax: acc.tax + row.tax,
      paidNet: acc.paidNet + row.paidNet,
      cashPaid: acc.cashPaid + asNumber(row.cashPaid),
      cashTax: acc.cashTax + asNumber(row.cashTax),
      cashPaidNet: acc.cashPaidNet + asNumber(row.cashPaidNet),
      due: acc.due + row.due,
      costs: acc.costs + row.costs,
      result: acc.result + row.result,
      refused: acc.refused + row.refused,
    }), { total: 0, paid: 0, tax: 0, paidNet: 0, cashPaid: 0, cashTax: 0, cashPaidNet: 0, due: 0, costs: 0, result: 0, refused: 0 });
    const moduleRows = accountingModuleNames().map((module) => {
      const moduleItems = rows.filter((row) => row.module === module);
      return moduleItems.reduce((acc, row) => ({
        module,
        count: acc.count + 1,
        total: acc.total + row.total,
        paid: acc.paid + row.paid,
        tax: acc.tax + row.tax,
        paidNet: acc.paidNet + row.paidNet,
        cashPaid: acc.cashPaid + asNumber(row.cashPaid),
        cashTax: acc.cashTax + asNumber(row.cashTax),
        cashPaidNet: acc.cashPaidNet + asNumber(row.cashPaidNet),
        due: acc.due + row.due,
        costs: acc.costs + row.costs,
        result: acc.result + row.result,
        refused: acc.refused + row.refused,
      }), { module, count: 0, total: 0, paid: 0, tax: 0, paidNet: 0, cashPaid: 0, cashTax: 0, cashPaidNet: 0, due: 0, costs: 0, result: 0, refused: 0 });
    });
    return { rows, moduleRows, totals, stockInvestment, totalInvestment, soldPurchaseCost, negativeStockValue, disciplineInvestment, stageInvestment, knownInvestment };
  }

  function accountingMetric(label, value, note = "", tone = "") {
    return `<div class="accounting-metric ${tone}">
      <span>${esc(label)}</span>
      <strong>${esc(value)}</strong>
      ${note ? `<small>${esc(note)}</small>` : ""}
    </div>`;
  }

  function accountingModuleCard(row = {}) {
    const title = row.module || "Activité";
    // F2-REAUDIT-006 — Recettes TTC/TVA/Recettes HT reflètent l'encaissement bancaire réel (cashPaid/
    // cashTax/cashPaidNet, avoirs utilisés exclus). Reste dû/Résultat restent sur le règlement complet
    // de la créance (avoir inclus, inchangé) : un avoir utilisé peut donc faire apparaître un écart
    // entre "Recettes HT" et "Résultat + investissement" pour ce module — c'est attendu, la note le dit.
    return `<section class="band accounting-module-card">
      <div class="band-title"><h2>${esc(title)}</h2><strong>${money(row.result || 0)}</strong></div>
      <div class="accounting-module-grid">
        ${accountingMetric("Recettes TTC", money(row.cashPaid || 0), "Encaissé en banque (hors avoirs utilisés)", "is-paid")}
        ${accountingMetric("TVA", money(row.cashTax || 0), "TVA incluse")}
        ${accountingMetric("Recettes HT", money(row.cashPaidNet || 0), "TTC - TVA, hors avoirs utilisés")}
        ${accountingMetric("Investissement", money(row.costs || 0), title === "Stages" ? "Frais stage saisis" : title === "Disciplines" ? "Licences" : "Coût d'achat vendu")}
        ${accountingMetric("Reste dû", money(row.due || 0), "Argent dehors", row.due > 0 ? "is-due" : "")}
        ${accountingMetric("Résultat", money(row.result || 0), "HT - investissement (avoirs utilisés inclus)", row.result >= 0 ? "is-paid" : "is-danger")}
      </div>
    </section>`;
  }

  function paymentTaxYear(payment = {}) {
    const date = parseDate(payment.date) || parseDate(payment.state);
    return date ? String(date.getFullYear()) : "Sans date";
  }

  function ensureTaxYear(map, year) {
    if (!map.has(year)) {
      map.set(year, {
        year,
        count: 0,
        gross: 0,
        tax: 0,
        net: 0,
        costs: 0,
        result: 0,
        modules: Object.fromEntries(accountingModuleNames().map((module) => [module, 0])),
        // F2-REAUDIT-005 — dédup du nombre de "Paiements" (transactions bancaires) PAR ANNÉE : un
        // règlement facture multi-claims (ex. 200€ = 150 Disciplines + 50 Boutique) produit une slice
        // par module mais reste UNE seule transaction bancaire — comptée une seule fois globalement,
        // jamais une fois par module qu'elle traverse. Sans id (legacy sans identité), toujours compté
        // (chaque entrée reste sa propre transaction, aucune dédup possible ni souhaitable).
        countedPaymentIds: new Set(),
      });
    }
    return map.get(year);
  }

  // F2-REAUDIT-005 — consomme une SLICE canonique (claimCanonicalPaymentSlices), pas un payment brut :
  // amount/taxRate sont déjà ceux de l'allocation réelle de ce claim (jamais la transaction entière
  // pour un règlement multi-claims), le taux suit les lignes figées de la facture quand elle existe
  // (cf. claimCanonicalPaymentSlices). Les slices sont déjà filtrées OK par construction (Refusé/
  // Annulé/pending n'y apparaissent jamais) : aucun filtre paymentStatus ici.
  // F2-REAUDIT-006 — un avoir utilisé (slice.cash === false) ne crée jamais de TTC encaissé / TVA
  // collectée / transaction "Paiements" dans la déclaration fiscale (règle minimale : utilisation d'un
  // avoir != nouvel encaissement positif). Sa part de coût (licence proportionnelle) reste en revanche
  // imputée normalement : c'est une charge réelle du club, indépendante du mode de règlement du client.
  function addTaxPaymentSlice(map, module, slice = {}, costShare = 0) {
    const gross = asNumber(slice.amount);
    if (gross <= 0.005 && Math.abs(asNumber(costShare)) <= 0.005) return;
    const row = ensureTaxYear(map, slice.year || "Sans date");
    if (slice.cash !== false) {
      const tax = taxAmountFromGross(gross, slice.taxRate);
      const net = gross - tax;
      const pid = asText(slice.paymentId);
      if (!pid || !row.countedPaymentIds.has(pid)) {
        if (pid) row.countedPaymentIds.add(pid);
        row.count += 1;
      }
      row.gross += gross;
      row.tax += tax;
      row.net += net;
      row.modules[module] = asNumber(row.modules[module]) + net;
    }
    row.costs += asNumber(costShare);
  }

  function addDatedInvestment(map, year, amount) {
    const value = asNumber(amount);
    if (!value) return;
    ensureTaxYear(map, year).costs += value;
  }

  // Année du PLUS ANCIEN encaissement d'un ensemble de slices (pour dater l'investissement d'un
  // stage) : comparaison sur slice.year (déjà résolu par paymentTaxYear à la création de la slice,
  // même fallback date/state que l'historique), jamais sur issuedAt.
  function firstSliceYear(slices = []) {
    const years = (slices || []).map((slice) => slice.year).filter((year) => year && year !== "Sans date");
    return years.length ? years.slice().sort()[0] : "Sans date";
  }

  function taxDeclarationRows() {
    const map = new Map();
    // F2-REAUDIT-005 — les slices canoniques (source + allocations paymentsAfterIssue) remplacent la
    // simple lecture de membership.payments : un règlement créé depuis une facture émise après coup ne
    // disparaît plus de la déclaration fiscale. paid (pour la répartition du coût licence) redevient la
    // somme des MÊMES slices, jamais paidAmount(membership.payments) seul (même risque de divergence
    // "paid vivant + tax source-only" que celui corrigé pour accountingData).
    state.memberships.forEach((membership) => {
      const license = asNumber(calcMembership(membership).license);
      const claim = membership.id ? claimCanonicalPaymentSlices(`membership:${membership.id}`) : null;
      const slices = claim ? claim.slices : (membership.payments || []).filter((p) => paymentStatus(p) === "OK").map((p) => ({ amount: asNumber(p.amount), taxRate: paymentTaxRate(p), year: paymentTaxYear(p), paymentId: asText(p.id) }));
      const paid = claim ? claim.paid : slices.reduce((sum, s) => sum + s.amount, 0);
      slices.forEach((slice) => {
        const share = paid > 0.005 ? license * (slice.amount / paid) : 0;
        addTaxPaymentSlice(map, "Disciplines", slice, share);
      });
    });
    // Lot 2D — point bloquant : la TVA encaissée sur les inscriptions existantes fait partie de la
    // déclaration fiscale HISTORIQUE ; elle est comptée inconditionnellement (indépendant de
    // settings.display.showStages et de hasFeature), exactement comme la TVA Boutique ci-dessous.
    state.tariffs.stages.forEach((stage) => {
      const allSlices = [];
      (state.stageRegistrations[stage.id] || []).forEach((registration) => {
        const eventClaim = registration.id ? claimCanonicalPaymentSlices(`stage:${stage.id}:${registration.id}:event`) : null;
        const lodgingClaim = registration.id ? claimCanonicalPaymentSlices(`stage:${stage.id}:${registration.id}:lodging`) : null;
        const slices = eventClaim || lodgingClaim
          ? [...(eventClaim?.slices || []), ...(lodgingClaim?.slices || [])]
          : [...(registration.event?.payments || []), ...(registration.lodging?.payments || [])].filter((p) => paymentStatus(p) === "OK").map((p) => ({ amount: asNumber(p.amount), taxRate: paymentTaxRate(p), year: paymentTaxYear(p), paymentId: asText(p.id) }));
        allSlices.push(...slices);
        slices.forEach((slice) => addTaxPaymentSlice(map, "Stages", slice));
      });
      addDatedInvestment(map, firstSliceYear(allSlices), asNumber(stage.investment));
    });
    // Lot 2B — point bloquant 1 : la TVA encaissée sur les commandes existantes fait partie de la
    // déclaration fiscale HISTORIQUE ; elle est comptée inconditionnellement (indépendant de
    // settings.display.showBoutique et de hasFeature).
    state.shopOrders.forEach((order) => {
      const costs = orderItemDetails(order).reduce((sum, item) => {
        const article = articleById(item.articleId);
        return sum + item.quantity * asNumber(article.priceOptions?.[1]);
      }, 0);
      const claim = order.id ? claimCanonicalPaymentSlices(`order:${order.id}`) : null;
      const slices = claim ? claim.slices : (order.payments || []).filter((p) => paymentStatus(p) === "OK").map((p) => ({ amount: asNumber(p.amount), taxRate: paymentTaxRate(p), year: paymentTaxYear(p), paymentId: asText(p.id) }));
      const paid = claim ? claim.paid : slices.reduce((sum, s) => sum + s.amount, 0);
      slices.forEach((slice) => {
        const share = paid > 0.005 ? costs * (slice.amount / paid) : 0;
        addTaxPaymentSlice(map, "Boutique", slice, share);
      });
    });
    return [...map.values()]
      .map(({ countedPaymentIds, ...row }) => ({ ...row, result: row.net - row.costs }))
      .sort((a, b) => {
        if (a.year === "Sans date") return 1;
        if (b.year === "Sans date") return -1;
        return b.year.localeCompare(a.year);
      });
  }

  function renderTaxDeclaration(rows) {
    const moduleNames = accountingModuleNames();
    const totals = rows.reduce((acc, row) => ({
      count: acc.count + row.count,
      gross: acc.gross + row.gross,
      tax: acc.tax + row.tax,
      net: acc.net + row.net,
      costs: acc.costs + row.costs,
      result: acc.result + row.result,
      modules: Object.fromEntries(moduleNames.map((module) => [module, asNumber(acc.modules?.[module]) + asNumber(row.modules?.[module])])),
    }), { count: 0, gross: 0, tax: 0, net: 0, costs: 0, result: 0, modules: Object.fromEntries(moduleNames.map((module) => [module, 0])) });
    const moduleHeaders = moduleNames.map((module) => ({ label: `${module} HT`, className: "money" }));
    const moduleTotalCells = moduleNames.map((module) => `<td class="money">${money(totals.modules[module])}</td>`).join("");
    return `<div class="band accounting-tax-band">
      <div class="band-title"><h2>Déclaration fiscale annuelle indicative</h2><strong>${money(totals.net)}</strong></div>
      <div class="accounting-tax-note">
        Montants à titre indicatif uniquement : ils sont calculés avec les paiements marqués Payé et les données saisies dans le logiciel. Les comptes doivent être vérifiés avec les justificatifs et, si besoin, par le comptable avant toute déclaration.
      </div>
      ${statsTable([
        { label: "Année" },
        { label: "Paiements", className: "money" },
        { label: "TTC encaissé", className: "money" },
        { label: "TVA collectée", className: "money" },
        { label: "HT à déclarer", className: "money" },
        ...moduleHeaders,
        { label: "Invest. connus", className: "money" },
        { label: "Résultat indicatif", className: "money" },
      ], rows.map((row) => `<tr>
        <td>${esc(row.year)}</td>
        <td class="money">${intValue(row.count)}</td>
        <td class="money">${money(row.gross)}</td>
        <td class="money">${money(row.tax)}</td>
        <td class="money">${money(row.net)}</td>
        ${moduleNames.map((module) => `<td class="money">${money(row.modules?.[module])}</td>`).join("")}
        <td class="money">${money(row.costs)}</td>
        <td class="money">${money(row.result)}</td>
      </tr>`), "Aucun paiement payé à déclarer",
        `<tr><td>Total</td><td class="money">${intValue(totals.count)}</td><td class="money">${money(totals.gross)}</td><td class="money">${money(totals.tax)}</td><td class="money">${money(totals.net)}</td>${moduleTotalCells}<td class="money">${money(totals.costs)}</td><td class="money">${money(totals.result)}</td></tr>`)}
    </div>`;
  }

  // ===== Dépenses manuelles (Phase 1) — sorties d'argent saisies à la main =====
  function clubExpenses() {
    return (state.expenses || []).slice().sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
  }
  function expensesTotal(list) {
    return (list || []).reduce((sum, e) => sum + asNumber(e.amount), 0);
  }
  function expenseYears() {
    return [...new Set(clubExpenses().map((e) => String(e.date || "").slice(0, 4)).filter(Boolean))].sort().reverse();
  }
  function filteredExpenses() {
    const cat = ui.expenseCategory || "";
    const year = ui.expenseYear || "";
    return clubExpenses().filter((e) => {
      if (cat && e.category !== cat) return false;
      if (year && String(e.date || "").slice(0, 4) !== year) return false;
      return true;
    });
  }
  function openExpenseDialog(expense = {}) {
    const boutiqueHelpText = "Le prix d'achat saisi dans la boutique sert au calcul de la marge et du stock. Cette dépense sert uniquement à enregistrer une sortie réelle de caisse. Ne cumulez pas mentalement les deux comme s'il s'agissait du même calcul.";
    const boutiqueHelpVisible = (expense.category || "Autre dépense") === "Achat boutique / stock";
    const body = [
      `<div class="form-grid compact">${field("date", "Date *", expense.date || todayInputValue(), "date", "required")}${field("amount", "Montant (€) *", expense.amount ?? "", "number", 'step="0.01" min="0" required')}</div>`,
      field("label", "Libellé *", expense.label || "", "text", "required"),
      `<div class="form-grid compact">
        <label>Catégorie<select name="category">${EXPENSE_CATEGORIES.map((c) => `<option value="${esc(c)}" ${(expense.category || "Autre dépense") === c ? "selected" : ""}>${esc(c)}</option>`).join("")}</select></label>
        <label>Mode de paiement<select name="paymentMethod"><option value="">—</option>${paymentModeDefinitions().map(([k, l]) => `<option value="${esc(k)}" ${expense.paymentMethod === k ? "selected" : ""}>${esc(l)}</option>`).join("")}</select></label>
      </div>`,
      `<p class="form-hint" data-expense-boutique-help style="margin:-2px 0 2px;font-size:12px;line-height:1.4;color:var(--muted,#64748b)${boutiqueHelpVisible ? "" : ";display:none"}">${esc(boutiqueHelpText)}</p>`,
      field("beneficiary", "Bénéficiaire / fournisseur", expense.beneficiary || ""),
      textareaField("note", "Note", expense.note || ""),
    ].join("");
    const footer = expense.id ? `<button type="button" class="danger" data-action="delete-expense" data-id="${esc(expense.id)}">Supprimer</button>` : "";
    setNextWindowKey(expense.id ? `expense:${expense.id}` : null);
    showDialog(expense.id ? "Modifier la dépense" : "Nouvelle dépense", body, (data) => {
      const label = asText(data.get("label"));
      const amount = asNumber(data.get("amount"));
      if (!label) { alert("Le libellé est obligatoire."); return false; }
      if (!(amount > 0)) { alert("Le montant doit être supérieur à 0."); return false; }
      const now = new Date().toISOString();
      const next = {
        ...expense,
        id: expense.id || id("expense"),
        date: data.get("date") || todayInputValue(),
        label,
        amount: Math.max(0, amount),
        category: data.get("category") || "Autre dépense",
        paymentMethod: data.get("paymentMethod") || "",
        beneficiary: asText(data.get("beneficiary")),
        note: asText(data.get("note")),
        linkedType: expense.linkedType || "",
        linkedId: expense.linkedId || "",
        createdAt: expense.createdAt || now,
        updatedAt: now,
      };
      state.expenses = state.expenses || [];
      upsert(state.expenses, next);
      return `${expense.id ? "Modification" : "Ajout"} de la dépense ${label} (${money(next.amount)})`;
    }, (form) => {
      // Affiche l'aide « Achat boutique / stock » uniquement quand cette catégorie est sélectionnée.
      const select = form.elements.category;
      const help = form.querySelector("[data-expense-boutique-help]");
      if (!select || !help) return;
      const sync = () => { help.style.display = select.value === "Achat boutique / stock" ? "" : "none"; };
      select.addEventListener("change", sync);
      sync();
    }, footer);
  }
  function expensesBandHtml() {
    const list = filteredExpenses();
    const grandTotal = expensesTotal(clubExpenses());
    const filtered = Boolean(ui.expenseCategory || ui.expenseYear);
    const years = expenseYears();
    return `<section class="band accounting-expenses">
      <div class="band-title"><h2>Dépenses</h2><strong>-${money(grandTotal)}</strong></div>
      <div class="coach-toolbar">
        <button class="primary" type="button" data-action="add-expense">+ Nouvelle dépense</button>
        <label>Catégorie <select data-filter="expenseCategory"><option value="">Toutes</option>${EXPENSE_CATEGORIES.map((c) => `<option value="${esc(c)}" ${ui.expenseCategory === c ? "selected" : ""}>${esc(c)}</option>`).join("")}</select></label>
        ${years.length ? `<label>Année <select data-filter="expenseYear"><option value="">Toutes</option>${years.map((y) => `<option value="${esc(y)}" ${ui.expenseYear === y ? "selected" : ""}>${esc(y)}</option>`).join("")}</select></label>` : ""}
      </div>
      ${statsTable([
        { label: "Date" }, { label: "Libellé" }, { label: "Catégorie" }, { label: "Bénéficiaire" }, { label: "Mode" }, { label: "Montant", className: "money" }, { label: "" },
      ], list.map((e) => `<tr>
        <td>${esc(dateDisplay(e.date))}</td>
        <td>${esc(e.label)}</td>
        <td>${esc(e.category)}</td>
        <td>${asText(e.beneficiary) ? esc(e.beneficiary) : `<span class="muted">—</span>`}</td>
        <td>${e.paymentMethod ? esc(paymentModeLabel(e.paymentMethod)) : `<span class="muted">—</span>`}</td>
        <td class="money">${money(e.amount)}</td>
        <td><div class="actions"><button type="button" class="icon" data-action="edit-expense" data-id="${esc(e.id)}" title="Modifier">✎</button><button type="button" class="icon danger" data-action="delete-expense" data-id="${esc(e.id)}" title="Supprimer">×</button></div></td>
      </tr>`), "Aucune dépense saisie. Clique sur « Nouvelle dépense » pour en ajouter.",
        `<tr><td colspan="5">Total${filtered ? " (filtré)" : ""}</td><td class="money">${money(expensesTotal(list))}</td><td></td></tr>`)}
    </section>`;
  }

  // ===== Phase 3 : recettes custom (factures purement personnalisées) + avoirs + remboursements =====
  // Règle d'or : on ne compte jamais deux fois le même argent. La comptabilité lit les SOURCES
  // (cotisations, stages, boutique…), pas les factures. On n'ajoute donc que les factures dont
  // TOUTES les lignes sont "custom" (aucune ligne issue d'une source déjà comptée).
  function isPureCustomInvoice(invoice) {
    const lines = invoice.lines || [];
    return lines.length > 0 && lines.every((line) => asText(line.sourceType) === "custom");
  }
  function invoiceContactDisplay(invoice) {
    const snap = invoice.contactSnapshot || {};
    const name = [snap.lastName, snap.firstName].map(asText).filter(Boolean).join(" ");
    return name || "—";
  }
  function customInvoiceIncomes() {
    return (state.invoices || [])
      .filter((invoice) => invoiceBelongsToActiveClub(invoice))
      .filter((invoice) => ["issued", "paid", "partial", "late"].includes(invoice.status))
      .filter(isPureCustomInvoice)
      .map((invoice) => {
        const totals = invoiceLiveTotals(invoice);
        const catLine = (invoice.lines || []).find((line) => asText(line.category));
        const category = asText(catLine && catLine.category) || "Autre recette";
        // F2-REAUDIT-006 — une facture custom réglée (en tout ou partie) via un avoir suit la même règle
        // que les autres modules : paid reste le règlement complet (avoir inclus, inchangé) ; cashPaid
        // exclut les slices d'avoir, clampé sur le même total que paid.
        const claims = new Set();
        (invoice.lines || []).forEach((line) => {
          const claimKey = lineClaimKey(invoice, line);
          if (claimKey) claims.add(claimKey);
        });
        let cashPaid = 0;
        claims.forEach((claimKey) => { cashPaid += claimSlicesCash(claimCanonicalPaymentSlices(claimKey).slices); });
        cashPaid = Math.min(Math.max(0, asNumber(totals.total)), Math.max(0, cashPaid));
        return {
          invoice,
          category,
          contact: invoiceContactDisplay(invoice),
          total: asNumber(totals.total),
          paid: asNumber(totals.paid),
          cashPaid,
          due: Math.max(0, asNumber(totals.restDue)),
        };
      })
      .sort((a, b) => String(b.invoice.date || "").localeCompare(String(a.invoice.date || "")));
  }
  function customIncomeTotal() {
    return customInvoiceIncomes().reduce((sum, row) => sum + row.paid, 0);
  }
  function customIncomeCashTotal() {
    return customInvoiceIncomes().reduce((sum, row) => sum + row.cashPaid, 0);
  }
  function clubCreditNotes() {
    return (state.creditNotes || []).slice().sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
  }
  function creditNoteActiveTotal() {
    // Lot B3b — un avoir "utilisé" partiellement laisse un reliquat actif distinct (nouvel avoir) :
    // compter aussi "utilisé" doublonnerait ce reliquat avec l'avoir d'origine. Seul "actif" reflète
    // l'encours réel d'avoirs disponibles.
    return clubCreditNotes().filter((cn) => cn.status === "actif").reduce((sum, cn) => sum + asNumber(cn.amount), 0);
  }
  function refundExpenses() {
    return (state.expenses || []).filter((expense) => expense.category === "Remboursement");
  }
  function refundExpenseTotal() {
    return refundExpenses().reduce((sum, expense) => sum + asNumber(expense.amount), 0);
  }
  function creditNoteInvoiceLabel(invoiceId) {
    if (!asText(invoiceId)) return "";
    const invoice = (state.invoices || []).find((inv) => inv.id === invoiceId);
    if (!invoice) return "";
    return [invoice.number || "Facture", invoiceContactDisplay(invoice)].filter((part) => part && part !== "—").join(" · ");
  }
  function openCreditNoteDialog(creditNote = {}) {
    const types = [["réduction", "Avoir / crédit"], ["crédit", "Crédit à valoir"], ["annulation", "Annulation"]];
    const statuses = [["actif", "Actif"], ["utilisé", "Utilisé"], ["annulé", "Annulé"]];
    const invoiceOptions = (state.invoices || [])
      .filter((invoice) => invoiceBelongsToActiveClub(invoice) && invoice.status !== "draft")
      .sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
    const body = [
      `<p class="muted">Un avoir est un crédit disponible pour ce contact. Il est visible sur la fiche contact et les factures liées, mais il n'est pas encore déduit automatiquement d'un achat ou d'un paiement. Pour une remise immédiate, utilisez le champ « Remise » dans l'achat ou l'inscription.</p>`,
      `<div class="form-grid compact">${field("date", "Date *", creditNote.date || todayInputValue(), "date", "required")}${field("amount", "Montant (€) *", creditNote.amount ?? "", "number", 'step="0.01" min="0" required')}</div>`,
      field("reason", "Motif *", creditNote.reason || "", "text", "required"),
      `<div class="form-grid compact">
        <label>Type<select name="type">${types.map(([k, l]) => `<option value="${esc(k)}" ${(creditNote.type || "réduction") === k ? "selected" : ""}>${esc(l)}</option>`).join("")}</select></label>
        <label>Statut<select name="status">${statuses.map(([k, l]) => `<option value="${esc(k)}" ${(creditNote.status || "actif") === k ? "selected" : ""}>${esc(l)}</option>`).join("")}</select></label>
      </div>`,
      `<label>Facture liée (facultatif)<select name="invoiceId"><option value="">— Aucune —</option>${invoiceOptions.map((invoice) => `<option value="${esc(invoice.id)}" ${creditNote.invoiceId === invoice.id ? "selected" : ""}>${esc([invoice.number || "Facture", invoiceContactDisplay(invoice)].filter((part) => part && part !== "—").join(" · "))}</option>`).join("")}</select></label>`,
      textareaField("note", "Note", creditNote.note || ""),
    ].join("");
    // Lot V1 Avoirs — Imprimer/PDF uniquement sur un avoir déjà enregistré (id existant), comme
    // Supprimer juste à côté ; rien sur un formulaire de création pas encore validé.
    const footer = creditNote.id
      ? `<button type="button" data-action="print-credit-note" data-id="${esc(creditNote.id)}">Imprimer</button>
         <button type="button" data-action="export-credit-note-pdf" data-id="${esc(creditNote.id)}">PDF</button>
         <button type="button" class="danger" data-action="delete-credit-note" data-id="${esc(creditNote.id)}">Supprimer</button>`
      : "";
    setNextWindowKey(creditNote.id ? `credit-note:${creditNote.id}` : null);
    showDialog(creditNote.id ? "Modifier l'avoir" : "Nouvel avoir", body, (data) => {
      const reason = asText(data.get("reason"));
      const amount = asNumber(data.get("amount"));
      if (!reason) { alert("Le motif est obligatoire."); return false; }
      if (!(amount > 0)) { alert("Le montant doit être supérieur à 0."); return false; }
      const now = new Date().toISOString();
      const selectedInvoice = (state.invoices || []).find((inv) => inv.id === data.get("invoiceId"));
      const next = {
        ...creditNote,
        id: creditNote.id || id("avoir"),
        date: data.get("date") || todayInputValue(),
        amount: Math.max(0, amount),
        reason,
        type: ["réduction", "crédit", "annulation"].includes(data.get("type")) ? data.get("type") : "réduction",
        status: ["actif", "utilisé", "annulé"].includes(data.get("status")) ? data.get("status") : "actif",
        invoiceId: asText(data.get("invoiceId")),
        contactId: selectedInvoice ? asText(selectedInvoice.contactId) : asText(creditNote.contactId),
        note: asText(data.get("note")),
        createdAt: creditNote.createdAt || now,
        updatedAt: now,
      };
      state.creditNotes = state.creditNotes || [];
      upsert(state.creditNotes, next);
      return `${creditNote.id ? "Modification" : "Ajout"} de l'avoir ${reason} (${money(next.amount)})`;
    }, () => {}, footer);
  }

  // Lot V1 Avoirs — document imprimable/PDF dédié. UNE SEULE fonction de payload, réutilisée par
  // Imprimer (showPagePrintPreview, même mécanique que la feuille de présence) et PDF (exportPdf,
  // même mécanique que les factures) : jamais deux templates. Aucun recalcul de reliquat/statut/
  // montant ici, tout est lu tel quel depuis l'avoir déjà normalisé ailleurs. Pas de numérotation
  // officielle inventée : l'avoir n'a pas de compteur séquentiel (contrairement aux factures), on
  // affiche donc son identifiant interne existant plutôt qu'un faux "n°" qui laisserait croire à une
  // numérotation officielle.
  function creditNoteDocumentPayload(creditNote = {}) {
    creditNote = normalizeCreditNote(creditNote);
    const club = activeClub() || {};
    const contactId = asText(creditNote.contactId);
    const member = contactId ? (state.contacts.members || []).find((c) => c.id === contactId) : null;
    const prospect = !member && contactId ? (state.contacts.prospects || []).find((c) => c.id === contactId) : null;
    const contact = member || prospect || {};
    const contactKind = prospect ? "prospects" : "members";
    const linkedInvoice = asText(creditNote.invoiceId) ? (state.invoices || []).find((inv) => inv.id === creditNote.invoiceId) : null;
    // Réutilise EXACTEMENT le helper facture (aucune logique dupliquée) : si l'avoir est lié à une
    // facture, on prend sa vraie déclinaison (snapshot compris) ; sinon on construit un objet minimal
    // avec le contact courant, pour bénéficier du même repli "responsable légal manquant".
    const billing = invoiceBillingDisplay(linkedInvoice || { contactKind, contactId }, contact);
    const beneficiaryName = billing.billedTo ? billing.billedTo.name : (personLabel(contact) || "Contact non renseigné");
    const beneficiaryFor = billing.billedTo ? (billing.beneficiary || personLabel(contact)) : "";
    const typeLabels = { "réduction": "Avoir / crédit", "crédit": "Crédit à valoir", "annulation": "Annulation" };
    const statusLabels = { "actif": "Actif — utilisable", "utilisé": "Utilisé", "annulé": "Annulé" };
    const logo = isLogoDataUrl(club.logoDataUrl) ? club.logoDataUrl
      : isLogoDataUrl(settings.logoDataUrl) ? settings.logoDataUrl
      : defaultLogoDataUrl();
    const dateLabel = dateDisplay(creditNote.date);
    const docTitle = `Avoir${creditNote.reason ? " — " + creditNote.reason : ""}${dateLabel ? " — " + dateLabel : ""}`;
    return {
      title: "Avoir",
      html: `<!doctype html><html lang="fr"><head><meta charset="utf-8" />
        <title>${esc(docTitle)}</title>
        <style>
          @page { size: A4 portrait; margin: 16mm; }
          * { box-sizing: border-box; }
          body { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; color: #1f2937; background: #fff; margin: 0; font-size: 12.5px; line-height: 1.5; }
          .head { display: flex; gap: 14px; align-items: center; margin: 0 0 16px; padding-bottom: 12px; border-bottom: 2px solid #1f2937; }
          .head img, .head .fallback { width: 48px; height: 48px; object-fit: contain; }
          .head .fallback { border: 1px solid #d7dce5; border-radius: 10px; display: grid; place-items: center; font-weight: 800; color: #1f2937; background: #f8fafc; }
          .head .club { font-size: 15px; font-weight: 800; color: #1f2937; margin: 0; }
          .head .club-details { color: #64748b; font-size: 11px; }
          h1 { font-size: 24px; margin: 14px 0 4px; color: #111827; }
          .ref { font-size: 11px; color: #6b7280; margin: 0 0 14px; }
          .status-badge { display: inline-block; border-radius: 999px; padding: 4px 10px; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; border: 1px solid #cbd5e1; background: #f8fafc; color: #334155; margin-bottom: 14px; }
          .status-badge.actif { background: #ecfdf5; border-color: #a7f3d0; color: #047857; }
          .status-badge.utilisé { background: #fff7ed; border-color: #fed7aa; color: #b45309; }
          .status-badge.annulé { background: #e5e7eb; border-color: #9ca3af; color: #374151; }
          table { width: 100%; border-collapse: collapse; margin: 0 0 16px; }
          th, td { border: 1px solid #d8dce3; padding: 8px 10px; text-align: left; vertical-align: top; }
          th { background: #f3f4f6; width: 34%; font-weight: 700; color: #374151; }
          .amount { font-size: 18px; font-weight: 800; color: #111827; }
          .sub { color: #64748b; font-size: 11px; margin-top: 2px; }
          .guardian-warning { color: #b45309; font-size: 12px; margin-top: 6px; }
          .note { border: 1px dashed #cbd5e1; border-radius: 8px; padding: 10px 12px; color: #475569; margin-top: 6px; }
        </style></head><body>
          <header class="head">
            ${logo ? `<img src="${esc(logo)}" alt="${esc(club.name || settings.clubName || "Club")}" />` : `<div class="fallback">${esc(initialsForText(club.name || settings.clubName || "Club"))}</div>`}
            <div>
              <p class="club">${esc(club.name || settings.clubName || "Club")}</p>
              <div class="club-details">${invoiceClubDetailsHtml(club).split("<br>").map((row) => `<div>${row}</div>`).join("")}</div>
            </div>
          </header>
          <h1>Avoir</h1>
          <p class="ref">Référence interne : ${esc(creditNote.id)}</p>
          <span class="status-badge ${esc(creditNote.status)}">${esc(statusLabels[creditNote.status] || creditNote.status)}</span>
          <table>
            <tr><th>Bénéficiaire</th><td><strong>${esc(beneficiaryName)}</strong>${beneficiaryFor ? `<div class="sub">Pour : ${esc(beneficiaryFor)}</div>` : ""}${billing.guardianMissing ? `<div class="guardian-warning">Responsable légal non renseigné</div>` : ""}</td></tr>
            <tr><th>Date</th><td>${esc(dateLabel)}</td></tr>
            <tr><th>Motif</th><td>${esc(creditNote.reason || "Non renseigné")}</td></tr>
            <tr><th>Type</th><td>${esc(typeLabels[creditNote.type] || creditNote.type)}</td></tr>
            <tr><th>Facture d'origine</th><td>${linkedInvoice ? esc(linkedInvoice.number || "Facture sans numéro") : "Aucune"}</td></tr>
            <tr><th>Montant</th><td class="amount">${money(creditNote.amount)}</td></tr>
          </table>
          ${creditNote.note ? `<div class="note">${esc(creditNote.note).replaceAll("\n", "<br>")}</div>` : ""}
        </body></html>`,
    };
  }

  function printCreditNote(creditNote = {}) {
    if (!creditNote?.id) return;
    showPagePrintPreview(creditNoteDocumentPayload(creditNote));
  }

  // Correctif "PDF honnête" (même principe que exportInvoicePdf) : hors Electron, ce bouton ouvre
  // désormais l'aperçu partagé en mode "pdf" (libellé « Enregistrer en PDF » + aide dédiée) au lieu
  // de réutiliser tel quel printCreditNote (qui affichait un bouton « Imprimer » trompeur sous une
  // action nommée PDF). Jamais de téléchargement HTML, jamais de faux fichier renommé.
  async function exportCreditNotePdf(creditNote = {}) {
    if (!creditNote?.id) return;
    const payload = creditNoteDocumentPayload(creditNote);
    if (window.monGestaClubShell?.exportPdf) {
      ui.saveMessage = "Création du PDF avoir...";
      render();
      try {
        const result = await window.monGestaClubShell.exportPdf(payload);
        ui.saveMessage = result?.ok ? "PDF avoir créé" : result?.message || "Export PDF avoir annulé";
        render();
      } catch (error) {
        console.error(error);
        ui.saveMessage = "Erreur PDF avoir";
        render();
        alert("Impossible de créer le PDF de l'avoir.");
      }
      return;
    }
    showPagePrintPreview(payload, { mode: "pdf" });
    ui.saveMessage = "Aperçu ouvert : choisissez « Enregistrer en PDF » dans la nouvelle fenêtre.";
    render();
  }

  // Section d'affichage : recettes custom + remboursements + avoirs, sans surcharger l'UI.
  function correctionsBandHtml(data, expenseTotalAll) {
    const customIncomes = customInvoiceIncomes();
    // F2-REAUDIT-006 — cashPaid (avoirs utilisés exclus) partout où « encaissé » désigne un encaissement
    // bancaire réel : ce bandeau calcule sa propre version du solde corrigé (même formule que
    // statsAccountingKpis, dupliquée ici pour l'affichage détaillé) — même correctif requis ici.
    const customTotal = customIncomes.reduce((sum, row) => sum + row.cashPaid, 0);
    const creditNotes = clubCreditNotes();
    const avoirTotal = creditNoteActiveTotal();
    const refundTotal = refundExpenseTotal();
    const cashBalance = data.totals.cashPaid - expenseTotalAll;
    const correctedBalance = cashBalance + customTotal - avoirTotal;
    const totalEncaisse = data.totals.cashPaid + customTotal;
    const typeLabels = { "réduction": "Avoir / crédit", "crédit": "Crédit à valoir", "annulation": "Annulation" };
    const statusLabels = { "actif": "Actif", "utilisé": "Utilisé", "annulé": "Annulé" };
    return `<section class="band accounting-corrections">
      <div class="band-title"><h2>Autres recettes / corrections</h2><strong>${money(correctedBalance)}</strong></div>
      <div class="accounting-metrics">
        ${accountingMetric("Recettes sources encaissées", money(data.totals.cashPaid), "Cotisations, stages, boutique… (hors avoirs utilisés)", "is-paid")}
        ${accountingMetric("Recettes custom encaissées", money(customTotal), "Factures dons / frais / prestations (hors avoirs utilisés)", customTotal ? "is-paid" : "")}
        ${accountingMetric("Total encaissé", money(totalEncaisse), "Sources + recettes custom")}
        ${accountingMetric("Remboursements", money(refundTotal), "Déjà inclus dans les dépenses", refundTotal ? "is-due" : "")}
        ${accountingMetric("Avoirs actifs", money(avoirTotal), "Crédits / avoirs accordés", avoirTotal ? "is-due" : "")}
        ${accountingMetric("Solde corrigé", money(correctedBalance), "Encaissé + custom - dépenses - avoirs", correctedBalance >= 0 ? "is-paid" : "is-danger")}
      </div>
      <div class="coach-toolbar">
        <button class="primary" type="button" data-action="add-credit-note">+ Nouvel avoir</button>
        <button type="button" data-action="add-refund">+ Remboursement</button>
      </div>
      <h3 class="accounting-subtitle">Recettes custom encaissées</h3>
      ${statsTable([
        { label: "Date" }, { label: "Facture" }, { label: "Contact" }, { label: "Catégorie" }, { label: "Encaissé", className: "money" }, { label: "Reste dû", className: "money" },
      ], customIncomes.map((row) => `<tr>
        <td>${esc(dateDisplay(row.invoice.date))}</td>
        <td>${esc(row.invoice.number || "Brouillon")}</td>
        <td>${esc(row.contact)}</td>
        <td>${esc(row.category)}</td>
        <td class="money">${money(row.cashPaid)}</td>
        <td class="money">${row.due ? money(row.due) : `<span class="muted">—</span>`}</td>
      </tr>`), "Aucune facture personnalisée comptabilisée. Les factures issues des cotisations / stages / boutique ne sont pas recomptées ici.",
        `<tr><td colspan="4">Total recettes custom</td><td class="money">${money(customTotal)}</td><td></td></tr>`)}
      <h3 class="accounting-subtitle">Avoirs</h3>
      ${statsTable([
        { label: "Date" }, { label: "Motif" }, { label: "Facture liée" }, { label: "Type" }, { label: "Statut" }, { label: "Montant", className: "money" }, { label: "" },
      ], creditNotes.map((cn) => `<tr${cn.status === "annulé" ? ' class="muted"' : ""}>
        <td>${esc(dateDisplay(cn.date))}</td>
        <td>${esc(cn.reason)}</td>
        <td>${creditNoteInvoiceLabel(cn.invoiceId) ? esc(creditNoteInvoiceLabel(cn.invoiceId)) : `<span class="muted">—</span>`}</td>
        <td>${esc(typeLabels[cn.type] || cn.type)}</td>
        <td>${esc(statusLabels[cn.status] || cn.status)}</td>
        <td class="money">${money(cn.amount)}</td>
        <td><div class="actions"><button type="button" class="icon" data-action="edit-credit-note" data-id="${esc(cn.id)}" title="Modifier">✎</button><button type="button" class="icon danger" data-action="delete-credit-note" data-id="${esc(cn.id)}" title="Supprimer">×</button></div></td>
      </tr>`), "Aucun avoir enregistré.",
        `<tr><td colspan="5">Total avoirs actifs</td><td class="money">${money(avoirTotal)}</td><td></td></tr>`)}
    </section>`;
  }

  // Vue effective de la Comptabilité (P4). Préférence par club ("simple"/"detailed") ; sinon "auto"
  // → suit le mode global (Simple → vue simple, sinon vue détaillée). Lecture seule, aucun calcul.
  function resolveAccountingView() {
    const display = displaySettings();
    if (display.accountingView === "simple" || display.accountingView === "detailed") return display.accountingView;
    return display.mode === "simple" ? "simple" : "detailed";
  }

  function accountingViewToggle(view) {
    return `<div class="band accounting-view-toggle"><div class="segmented">
      <button type="button" data-action="set-accounting-view" data-accounting-view="simple" class="${view === "simple" ? "active" : ""}">Vue simple</button>
      <button type="button" data-action="set-accounting-view" data-accounting-view="detailed" class="${view === "detailed" ? "active" : ""}">Vue détaillée</button>
    </div></div>`;
  }

  function renderAccounting() {
    // Lot 2D — la rubrique Stages (rapport historique) suit les DONNÉES, jamais la fonctionnalité ni
    // l'affichage : jamais absente uniquement parce que Stages est désactivé/masqué. Les totaux, eux,
    // sont déjà inconditionnels (accountingData / taxDeclarationRows / accountingModuleNames).
    const stagesEnabled = hasStageData();
    const boutiqueEnabled = isModuleEnabled("boutique");
    const data = accountingData();
    const expenseTotalAll = expensesTotal(clubExpenses());
    // F2-REAUDIT-006 — cashPaid (avoirs utilisés exclus) : "Solde caisse"/"Encaissé" désignent de
    // l'argent réellement en banque, jamais un avoir utilisé pour solder une créance.
    const cashBalance = data.totals.cashPaid - expenseTotalAll;
    // ----- Vue simple (P4) : 4 cartes, calculs réutilisés (aucun calcul parallèle) -----
    const accountingView = resolveAccountingView();
    if (accountingView === "simple") {
      const encaisse = data.totals.cashPaid + customIncomeCashTotal(); // Total encaissé = sources + recettes custom (hors avoirs utilisés)
      const result = encaisse - expenseTotalAll;                // Résultat = Encaissé − Dépensé
      return `
        ${accountingViewToggle("simple")}
        <section class="band accounting-group accounting-simple">
          <div class="band-title"><h2>Vue d'ensemble</h2></div>
          <div class="accounting-metrics">
            ${accountingMetric("Encaissé", money(encaisse), "Argent entré dans le club", "is-paid")}
            ${accountingMetric("Dépensé", money(expenseTotalAll), "Dépenses enregistrées", expenseTotalAll ? "is-due" : "")}
            ${accountingMetric("Reste dû", money(data.totals.due), "Argent encore attendu", data.totals.due ? "is-due" : "")}
            ${accountingMetric("Résultat", money(result), "Encaissé − Dépensé", result >= 0 ? "is-paid" : "is-danger")}
          </div>
        </section>`;
    }
    const taxRows = taxDeclarationRows();
    const dueRows = data.rows
      .filter((row) => row.due > 0)
      .sort((a, b) => b.due - a.due || String(a.name || "").localeCompare(String(b.name || ""), "fr"));
    const stockRowsData = boutiqueEnabled ? stockRows()
      .filter((row) => asNumber(row.purchasePrice) || row.available || row.sold)
      .sort((a, b) => b.purchaseTotal - a.purchaseTotal) : [];
    const boutiqueModule = data.moduleRows.find((row) => row.module === "Boutique") || {};
    const disciplineModule = data.moduleRows.find((row) => row.module === "Disciplines") || {};
    const stageModule = data.moduleRows.find((row) => row.module === "Stages") || {};
    const moduleCards = [
      accountingModuleCard(disciplineModule),
      stagesEnabled ? accountingModuleCard(stageModule) : "",
      boutiqueEnabled ? accountingModuleCard(boutiqueModule) : "",
    ].filter(Boolean);
    const investmentMetrics = [
      accountingMetric("Investissement disciplines", money(data.disciplineInvestment), "Licences à reverser"),
      stagesEnabled ? accountingMetric("Investissement stages", money(data.stageInvestment), "Frais saisis dans Tarifs") : "",
      boutiqueEnabled ? accountingMetric("Investissement boutique", money(data.totalInvestment), "Stock acheté estimé") : "",
      boutiqueEnabled ? accountingMetric("Stock restant", money(data.stockInvestment), "Valeur au prix d'achat") : "",
      boutiqueEnabled ? accountingMetric("Stock négatif", money(data.negativeStockValue), "À régulariser", data.negativeStockValue ? "is-danger" : "") : "",
    ].filter(Boolean).join("");
    const miniCards = [
      `<div class="band pad accounting-mini">
        <h3>Disciplines</h3>
        <strong>${money(disciplineModule.result || 0)}</strong>
        <span>Résultat estimé après licences</span>
      </div>`,
      stagesEnabled ? `<div class="band pad accounting-mini">
        <h3>Stages</h3>
        <strong>${money(stageModule.result || 0)}</strong>
        <span>Recettes stages - investissements saisis</span>
      </div>` : "",
      boutiqueEnabled ? `<div class="band pad accounting-mini">
        <h3>Boutique</h3>
        <strong>${money(boutiqueModule.result || 0)}</strong>
        <span>Encaissé boutique - coût d'achat</span>
      </div>` : "",
    ].filter(Boolean);
    return `
      ${accountingViewToggle("detailed")}
      <div class="accounting-board">
        <section class="band accounting-group accounting-due">
          <div class="band-title"><h2>Argent à encaisser</h2><strong>${money(data.totals.due)}</strong></div>
          <div class="accounting-metrics">
            ${accountingMetric("Reste dû total", money(data.totals.due), "Sommes encore dehors", "is-due")}
            ${accountingMetric("Paiements refusés", money(data.totals.refused), "À relancer en priorité", data.totals.refused ? "is-danger" : "")}
            ${accountingMetric("Lignes concernées", intValue(dueRows.length), "Tous les restes dus affichés")}
          </div>
        </section>
        <section class="band accounting-group accounting-invest">
          <div class="band-title"><h2>Investissements / achats</h2><strong>${money(data.knownInvestment)}</strong></div>
          <div class="accounting-metrics">
            ${investmentMetrics}
          </div>
        </section>
        <section class="band accounting-group accounting-profit">
          <div class="band-title"><h2>Bénéfices / résultat</h2><strong>${money(data.totals.result)}</strong></div>
          <div class="accounting-metrics">
            ${accountingMetric("Encaissé TTC", money(data.totals.cashPaid), "Argent réellement rentré en banque (hors avoirs utilisés)", "is-paid")}
            ${accountingMetric("TVA encaissée", money(data.totals.cashTax), "À isoler de la recette")}
            ${accountingMetric("Encaissé HT", money(data.totals.cashPaidNet), "TTC - TVA, hors avoirs utilisés")}
            ${accountingMetric("Achats imputés", money(data.totals.costs), boutiqueEnabled ? "Licences + achats boutique" : "Licences et modules actifs")}
            ${accountingMetric("Résultat estimé", money(data.totals.result), "Encaissé HT - achats imputés (avoirs utilisés inclus)", data.totals.result >= 0 ? "is-paid" : "is-danger")}
            ${accountingMetric("Dépenses saisies", money(expenseTotalAll), "Sorties manuelles (hors investissements)", expenseTotalAll ? "is-due" : "")}
            ${accountingMetric("Solde caisse", money(cashBalance), "Encaissé TTC - dépenses saisies", cashBalance >= 0 ? "is-paid" : "is-danger")}
          </div>
        </section>
      </div>
      ${expensesBandHtml()}
      ${correctionsBandHtml(data, expenseTotalAll)}
      ${gridItems(moduleCards, 3)}
      ${renderTaxDeclaration(taxRows)}
      ${gridItems([
        `<div class="band">
          <div class="band-title"><h2>Synthèse par activité</h2></div>
          ${statsTable([
            { label: "Activité" },
            { label: "Lignes", className: "money" },
            { label: "Attendu", className: "money" },
            { label: "Encaissé TTC", className: "money" },
            { label: "TVA", className: "money" },
            { label: "Encaissé HT", className: "money" },
            { label: "Dehors", className: "money" },
            { label: "Achats", className: "money" },
            { label: "Résultat", className: "money" },
          ], data.moduleRows.map((row) => `<tr><td>${esc(row.module)}</td><td class="money">${intValue(row.count)}</td><td class="money">${money(row.total)}</td><td class="money">${money(row.cashPaid)}</td><td class="money">${money(row.cashTax)}</td><td class="money">${money(row.cashPaidNet)}</td><td class="money">${money(row.due)}</td><td class="money">${money(row.costs)}</td><td class="money">${money(row.result)}</td></tr>`), "Aucune écriture",
            `<tr><td>Total</td><td class="money">${intValue(data.rows.length)}</td><td class="money">${money(data.totals.total)}</td><td class="money">${money(data.totals.cashPaid)}</td><td class="money">${money(data.totals.cashTax)}</td><td class="money">${money(data.totals.cashPaidNet)}</td><td class="money">${money(data.totals.due)}</td><td class="money">${money(data.totals.costs)}</td><td class="money">${money(data.totals.result)}</td></tr>`)}
        </div>`,
        `<div class="band">
          <div class="band-title"><h2>Argent dehors</h2><strong>${money(data.totals.due)}</strong></div>
          ${statsTable([
            { label: "Module" },
            { label: "Contact" },
            { label: "Détail" },
            { label: "Reste dû", className: "money" },
          ], dueRows.map((row) => `<tr><td>${esc(row.module)}</td><td>${esc(row.name)}</td><td>${esc(row.detail)}</td><td class="money">${money(row.due)}</td></tr>`), "Aucun reste dû")}
        </div>`,
      ], 2)}
      ${gridItems([
        chartBand("Reste dû par activité", data.moduleRows.map((row) => [row.module, row.due])),
        chartBand("Résultat par activité", data.moduleRows.map((row) => [row.module, row.result])),
        chartBand("Encaissements", data.moduleRows.map((row) => [row.module, row.cashPaid])),
      ], 3)}
      ${gridItems([
        boutiqueEnabled ? `<div class="band">
          <div class="band-title"><h2>Investissement boutique</h2></div>
          ${statsTable([
            { label: "Article" },
            { label: "Prix achat", className: "money" },
            { label: "Vendus", className: "money" },
            { label: "En stock", className: "money" },
            { label: "Valeur stock", className: "money" },
            { label: "Total vendu", className: "money" },
          ], stockRowsData.map((row) => `<tr><td>${esc(row.article.name || "Article")}</td><td class="money">${money(row.purchasePrice)}</td><td class="money">${intValue(row.sold)}</td><td class="money">${intValue(row.available)}</td><td class="money">${money(Math.max(0, row.available) * row.purchasePrice)}</td><td class="money">${money(row.total)}</td></tr>`), "Aucun stock valorisé")}
        </div>` : "",
        `<div class="band">
          <div class="band-title"><h2>Détail des écritures</h2><strong>${data.rows.length}</strong></div>
          ${statsTable([
            { label: "Module" },
            { label: "Contact" },
            { label: "Attendu", className: "money" },
            { label: "TTC", className: "money" },
            { label: "TVA", className: "money" },
            { label: "HT", className: "money" },
            { label: "Dehors", className: "money" },
            { label: "Résultat", className: "money" },
          ], data.rows.slice().sort((a, b) => b.due - a.due || b.paid - a.paid).map((row) => `<tr><td>${esc(row.module)}</td><td>${esc(row.name)}</td><td class="money">${money(row.total)}</td><td class="money">${money(row.paid)}</td><td class="money">${money(row.tax)}</td><td class="money">${money(row.paidNet)}</td><td class="money">${money(row.due)}</td><td class="money">${money(row.result)}</td></tr>`), "Aucune écriture")}
        </div>`,
      ], 2)}
      ${gridItems(miniCards, 3)}
      <div class="band pad accounting-footnote">
        <p class="muted">Le résultat est une estimation basée sur les modules actifs : paiements encaissés HT, licences, investissements et achats connus. Les modules désactivés ne sont pas additionnés, mais leurs données reviennent dès qu'ils sont réactivés.</p>
      </div>`;
  }

  function renderLockedView(view, key) {
    const label = menuKeyLabel(view);
    // key === view : protection INDIVIDUELLE de la page ; sinon key = id d'une rubrique protégée.
    const isPageProtection = key === view;
    const heading = isPageProtection ? `${label} — page protégée` : `${label} — rubrique protégée`;
    const detail = isPageProtection ? "Cette page est protégée" : "Cette rubrique est protégée";
    return `
      <div class="tarifs-locked">
        <div class="tarifs-locked-card paper">
          <div class="tarifs-locked-icon" aria-hidden="true">🔒</div>
          <h2>${esc(heading)}</h2>
          <p class="muted">${detail} par le mot de passe du logiciel. Saisis-le pour accéder à cette page.</p>
          <button type="button" class="primary" data-action="unlock-protected" data-unlock-key="${esc(key)}">Déverrouiller</button>
        </div>
      </div>`;
  }

  function renderTarifs() {
    return `
      ${tariffCollapsibleBand("vat", "TVA actuelle", isClubVatExempt() ? "—" : `${intValue(settings.defaultVatRate || 0)}%`, `
        <div class="tariff-vat-panel pad">
          <div>
            <p class="muted">Ce taux s'applique automatiquement à tous les paiements et à toutes les lignes de tarifs qui n'ont pas de TVA spécifique.</p>
          </div>
          <label>TVA globale (%)
            <input type="number" min="0" step="0.01" value="${esc(settings.defaultVatRate || 0)}" data-setting="defaultVatRate" />
          </label>
        </div>
      `)}
      ${isModuleEnabled("boutique") && hasFeature("shop") ? tariffCollapsibleBand("articles", "Articles", intValue(state.tariffs.articles.length), editableArticles(), "add-tariff-article") : ""}
      ${tariffCollapsibleBand("disciplines", "Disciplines", intValue(state.tariffs.disciplines.length), editableDisciplines(), "add-tariff-discipline")}
      ${isModuleEnabled("stages") && hasFeature("stages") ? tariffCollapsibleBand("stages", "Stages", intValue(state.tariffs.stages.length), editableStages(), "add-tariff-stage") : ""}
      ${tariffCollapsibleBand("insurance", "Assurances", intValue(state.tariffs.insurance.length), editableInsurance(), "add-tariff-insurance")}`;
  }

  function editableArticles() {
    return `<div class="table-wrap tariff-table-wrap"><table class="editable-table tariff-table">
      <thead><tr><th>Nom</th><th>Prix de vente</th><th>Prix d'achat</th><th class="tariff-tax-cell">TVA</th><th></th></tr></thead><tbody>
      ${state.tariffs.articles.map(tariffArticleRow).join("")}</tbody></table></div>`;
  }

  // Lot 2C — liste ACTIVE par défaut, même patron que coachs/salles (ui.showArchivedDisciplines,
  // partagé avec Paramètres > Disciplines et catégories sportives : même collection). L'INDEX RÉEL
  // (position dans state.tariffs.disciplines, utilisé par updateTariff/data-index) est calculé AVANT
  // le filtrage et transmis tel quel à tariffDisciplineRow — jamais recalculé sur la liste filtrée,
  // sous peine d'éditer/supprimer la mauvaise ligne.
  function editableDisciplines() {
    const showArchived = Boolean(ui.showArchivedDisciplines);
    const archivedCount = state.tariffs.disciplines.filter((d) => d.archived === true).length;
    const rows = state.tariffs.disciplines
      .map((discipline, index) => (showArchived || discipline.archived !== true) ? tariffDisciplineRow(discipline, index) : "")
      .join("");
    const archivedToggle = archivedCount
      ? `<label class="form-check"><input type="checkbox" data-toggle-archived-disciplines ${showArchived ? "checked" : ""}/> Afficher archivées (${intValue(archivedCount)})</label>`
      : "";
    return `<div class="table-wrap tariff-table-wrap">
      ${archivedToggle}
      <table class="editable-table tariff-table">
      <thead><tr><th>Nom</th><th>Tarif</th><th>Licence</th><th class="tariff-tax-cell">TVA</th><th></th></tr></thead><tbody>
      ${rows}</tbody></table></div>`;
  }

  function editableStages() {
    return `<div class="table-wrap tariff-table-wrap"><table class="editable-table tariff-table">
      <thead><tr><th>Nom</th><th>Prix stage</th><th class="tariff-tax-cell">TVA stage</th><th>Invest.</th><th>Nom hébergement</th><th>Prix héb.</th><th class="tariff-tax-cell">TVA héb.</th><th></th></tr></thead><tbody>
      ${state.tariffs.stages.map(tariffStageRow).join("")}</tbody></table></div>`;
  }

  function editableInsurance() {
    return `<div class="table-wrap tariff-table-wrap"><table class="editable-table tariff-table">
      <thead><tr><th>Catégorie</th><th>Libellé</th><th>Montants</th><th class="tariff-tax-cell">TVA</th><th></th></tr></thead><tbody>
      ${state.tariffs.insurance.map(tariffInsuranceRow).join("")}</tbody></table></div>`;
  }

  function tariffCollapsibleBand(idValue, title, summary, body, addAction = "") {
    const open = Boolean(ui.tariffPanels?.[idValue]);
    return `<div class="band collapsible-band tariff-collapsible-band ${open ? "open" : ""}" data-tariff-panel="${esc(idValue)}">
      <div class="band-title collapsible-title-row" data-action="toggle-tariff-panel" data-panel="${esc(idValue)}" role="button" tabindex="0" aria-expanded="${open ? "true" : "false"}">
        <h2>${esc(title)}</h2>
        <span class="collapsible-meta">${esc(summary)}</span>
        ${addAction ? `<button class="icon" title="${esc(addAction === "add-tariff-discipline" ? "Nouvelle discipline" : "Ajouter")}" data-action="${esc(addAction)}" ${addAction === "add-tariff-discipline" ? `data-origin="tarifs"` : ""}>+</button>` : ""}
        <span class="collapsible-arrow">›</span>
      </div>
      <div class="collapsible-content">
        <div class="collapsible-inner">${body}</div>
      </div>
    </div>`;
  }

  function tariffKey(kind, index) {
    return `${kind}:${index}`;
  }

  function isTariffEditing(kind, index) {
    return ui.tariffEditKey === tariffKey(kind, index);
  }

  function tariffActions(kind, index, deleteAction) {
    const editing = isTariffEditing(kind, index);
    return `<div class="actions">
      ${editing
        ? `<button class="icon tariff-check" title="Valider la modification" data-action="close-tariff-row">✓</button>`
        : ""}
      <button class="icon danger" title="Supprimer" data-action="${esc(deleteAction)}" data-index="${index}">×</button>
    </div>`;
  }

  function commitTariffRow(source) {
    const row = source.closest(".tariff-row.editing");
    if (!row) {
      ui.tariffEditKey = "";
      render();
      return;
    }
    // Garde de MUTATION (Lot 2B) — chemin hors handleAction (validation d'une ligne Tarifs au clavier).
    // Si la ligne éditée est un ARTICLE et que la Boutique est désactivée, on bloque l'écriture avant
    // tout recordHistory/persist ; les autres tarifs (disciplines, stages, assurances) restent libres.
    const [editKind, editIndexRaw] = asText(ui.tariffEditKey).split(":");
    if (editKind === "article" && !ensureFeatureEnabledForMutation("shop")) {
      ui.tariffEditKey = "";
      render();
      return;
    }
    recordHistory();
    // Lot 5B : la page Tarifs modifie le MÊME state.tariffs.articles[] que le dialogue Boutique
    // (nom, prix de vente/achat, TVA) — un seul type d'événement (shop.item.updated), jamais un
    // "tariff.updated" séparé pour ces mêmes champs. Snapshot capturé avant que ui.tariffEditKey
    // (format "kind:index") ne soit effacé, uniquement si la ligne éditée est un article.
    const [editingKind, editingIndexRaw] = asText(ui.tariffEditKey).split(":");
    const editingArticle = editingKind === "article" ? state.tariffs.articles[Number(editingIndexRaw)] : null;
    const beforeSnapshot = editingArticle ? shopItemSnapshot(editingArticle) : null;
    row.querySelectorAll("[data-tariff]").forEach(updateTariff);
    ui.tariffEditKey = "";
    persist("Tarif enregistré");
    if (editingArticle) {
      audit.shopItemUpdated(editingArticle, shopItemAuditChanges(beforeSnapshot, shopItemSnapshot(editingArticle)));
    }
    render();
  }

  function tariffArticleRow(article, index) {
    const editing = isTariffEditing("article", index);
    if (editing) {
      return `<tr class="tariff-row editing">
        <td><input data-tariff="article-name" data-index="${index}" value="${esc(article.name)}" /></td>
        <td><input type="number" step="0.01" data-tariff="article-price" data-index="${index}" data-price-index="0" value="${esc(article.priceOptions?.[0] ?? article.defaultPrice ?? 0)}" /></td>
        <td><input type="number" step="0.01" data-tariff="article-price" data-index="${index}" data-price-index="1" value="${esc(article.priceOptions?.[1] ?? "")}" /></td>
        <td class="tariff-tax-cell"><input type="number" step="0.01" min="0" placeholder="${esc(intValue(effectiveDefaultVatRate()))}" data-tariff="article-tax" data-index="${index}" value="${esc(hasSpecificTaxRate(article) ? tariffTaxRate(article) : "")}" /></td>
        <td>${tariffActions("article", index, "delete-tariff-article")}</td>
      </tr>`;
    }
    return `<tr class="tariff-row" data-action="edit-tariff-row" data-kind="article" data-index="${index}">
      <td><strong>${esc(article.name)}</strong></td>
      <td class="money">${money(article.priceOptions?.[0] ?? article.defaultPrice ?? 0)}</td>
      <td class="money">${money(article.priceOptions?.[1] ?? 0)}</td>
      <td class="tariff-tax-cell">${esc(taxRateLabel(article))}</td>
      <td>${tariffActions("article", index, "delete-tariff-article")}</td>
    </tr>`;
  }

  function tariffDisciplineRow(discipline, index) {
    const editing = isTariffEditing("discipline", index);
    // Lot 2C — le renommage inline reste possible même archivée (résout une collision au restore,
    // cf. « Renommez l'une des deux disciplines avant de restaurer celle-ci. »), aucun blocage ajouté.
    const archivedBadge = discipline.archived === true ? ' <span class="archived-badge">Archivée</span>' : "";
    if (editing) {
      return `<tr class="tariff-row editing">
        <td><input data-tariff="discipline-name" data-index="${index}" value="${esc(discipline.name)}" />${archivedBadge}</td>
        <td><input type="number" step="0.01" data-tariff="discipline-price" data-index="${index}" value="${esc(discipline.price)}" /></td>
        <td><input type="number" step="0.01" data-tariff="discipline-license" data-index="${index}" value="${esc(discipline.license)}" /></td>
        <td class="tariff-tax-cell"><input type="number" step="0.01" min="0" placeholder="${esc(intValue(effectiveDefaultVatRate()))}" data-tariff="discipline-tax" data-index="${index}" value="${esc(hasSpecificTaxRate(discipline) ? tariffTaxRate(discipline) : "")}" /></td>
        <td>${tariffActions("discipline", index, "delete-tariff-discipline")}</td>
      </tr>`;
    }
    // « À définir » : montant vide (discipline seedée par le wizard, jamais tarifée). Distinct d'un
    // 0 explicite (gratuité voulue) qui reste affiché « 0,00 € ». Seul price/license === "" déclenche
    // ce libellé ; les ajouts manuels (0) et les clubs existants (0 numérique) ne sont pas concernés.
    const tariffAmountCell = (value) => value === ""
      ? `<span class="tariff-to-define" title="Tarif non encore renseigné — à compléter">À définir</span>`
      : money(value);
    return `<tr class="tariff-row" data-action="edit-tariff-row" data-kind="discipline" data-index="${index}">
      <td><strong>${esc(discipline.name)}</strong>${archivedBadge}</td>
      <td class="money">${tariffAmountCell(discipline.price)}</td>
      <td class="money">${tariffAmountCell(discipline.license)}</td>
      <td class="tariff-tax-cell">${esc(taxRateLabel(discipline))}</td>
      <td>${tariffActions("discipline", index, "delete-tariff-discipline")}</td>
    </tr>`;
  }

  function tariffStageRow(stage, index) {
    const editing = isTariffEditing("stage", index);
    if (editing) {
      return `<tr class="tariff-row editing">
        <td><input data-tariff="stage-name" data-index="${index}" value="${esc(stage.name)}" /></td>
        <td><input type="number" step="0.01" data-tariff="stage-price" data-index="${index}" value="${esc(stage.unitPrice)}" /></td>
        <td class="tariff-tax-cell"><input type="number" step="0.01" min="0" placeholder="${esc(intValue(effectiveDefaultVatRate()))}" data-tariff="stage-tax" data-index="${index}" value="${esc(hasSpecificTaxRate(stage) ? tariffTaxRate(stage) : "")}" /></td>
        <td><input type="number" step="0.01" data-tariff="stage-investment" data-index="${index}" value="${esc(stage.investment || "")}" /></td>
        <td><input data-tariff="stage-lodging-name" data-index="${index}" value="${esc(stage.lodgingName)}" /></td>
        <td><input type="number" step="0.01" data-tariff="stage-lodging-price" data-index="${index}" value="${esc(stage.lodgingUnitPrice)}" /></td>
        <td class="tariff-tax-cell"><input type="number" step="0.01" min="0" placeholder="${esc(intValue(effectiveDefaultVatRate()))}" data-tariff="stage-lodging-tax" data-index="${index}" value="${esc(hasSpecificLodgingTaxRate(stage) ? lodgingTaxRate(stage) : "")}" /></td>
        <td>${tariffActions("stage", index, "delete-tariff-stage")}</td>
      </tr>`;
    }
    return `<tr class="tariff-row" data-action="edit-tariff-row" data-kind="stage" data-index="${index}">
      <td><strong>${esc(stage.name)}</strong></td>
      <td class="money">${money(stage.unitPrice)}</td>
      <td class="tariff-tax-cell">${esc(taxRateLabel(stage))}</td>
      <td class="money">${money(stage.investment || 0)}</td>
      <td>${esc(stage.lodgingName) || `<span class="muted">-</span>`}</td>
      <td class="money">${money(stage.lodgingUnitPrice)}</td>
      <td class="tariff-tax-cell">${esc(lodgingTaxRateLabel(stage))}</td>
      <td>${tariffActions("stage", index, "delete-tariff-stage")}</td>
    </tr>`;
  }

  function tariffInsuranceRow(item, index) {
    const editing = isTariffEditing("insurance", index);
    if (editing) {
      return `<tr class="tariff-row editing">
        <td><input data-tariff="insurance-category" data-index="${index}" value="${esc(item.category)}" /></td>
        <td><input data-tariff="insurance-label" data-index="${index}" value="${esc(item.label)}" /></td>
        <td><input data-tariff="insurance-options" data-index="${index}" value="${esc((item.options || []).join(", "))}" /></td>
        <td class="tariff-tax-cell"><input type="number" step="0.01" min="0" placeholder="${esc(intValue(effectiveDefaultVatRate()))}" data-tariff="insurance-tax" data-index="${index}" value="${esc(hasSpecificTaxRate(item) ? tariffTaxRate(item) : "")}" /></td>
        <td>${tariffActions("insurance", index, "delete-tariff-insurance")}</td>
      </tr>`;
    }
    return `<tr class="tariff-row" data-action="edit-tariff-row" data-kind="insurance" data-index="${index}">
      <td><strong>${esc(item.category)}</strong></td>
      <td>${esc(item.label) || `<span class="muted">-</span>`}</td>
      <td>${esc((item.options || []).map(money).join(" / ")) || `<span class="muted">-</span>`}</td>
      <td class="tariff-tax-cell">${esc(taxRateLabel(item))}</td>
      <td>${tariffActions("insurance", index, "delete-tariff-insurance")}</td>
    </tr>`;
  }

  function memoPriorityOptions(value) {
    return ["Normale", "Important", "Urgent", "Archive"]
      .map((option) => `<option value="${esc(option)}" ${value === option ? "selected" : ""}>${esc(option)}</option>`)
      .join("");
  }

  // Lot "Notes contextuelles par page" — libellé humain d'une destination de note. "" = refuge
  // "Notes uniquement" (valeur par défaut, jamais migrée automatiquement depuis l'ancien "category").
  // Une valeur non vide mais absente de l'allowlist (page exclue volontairement, ou identifiant
  // obsolète/importé) reste affichée avec un repli lisible, JAMAIS silencieusement effacée : c'est
  // la seule façon pour l'utilisateur de la repérer et de la réaffecter depuis la page Notes.
  function noteTargetViewLabel(targetView) {
    const value = asText(targetView);
    if (!value) return "Notes uniquement";
    if (NOTE_TARGET_VIEW_IDS.includes(value)) {
      const label = Object.fromEntries(views)[value];
      if (label) return label;
    }
    return `Page inconnue (${value})`;
  }

  // Options du <select> "Afficher dans" : dérivées EXCLUSIVEMENT de NOTE_TARGET_VIEW_IDS + views
  // (jamais une seconde table de libellés). Si la valeur courante ne fait pas partie de l'allowlist
  // (destination inconnue ou volontairement exclue), une option supplémentaire la garde sélectionnée
  // et visible avec son libellé de repli, pour permettre une réaffectation explicite sans la perdre.
  function noteTargetViewOptions(selected) {
    const value = asText(selected);
    const labels = Object.fromEntries(views);
    const knownOptions = NOTE_TARGET_VIEW_IDS
      .map((key) => `<option value="${esc(key)}" ${value === key ? "selected" : ""}>${esc(labels[key] || key)}</option>`)
      .join("");
    const unknownOption = (value && !NOTE_TARGET_VIEW_IDS.includes(value))
      ? `<option value="${esc(value)}" selected>${esc(noteTargetViewLabel(value))}</option>`
      : "";
    return `<option value="" ${!value ? "selected" : ""}>— Notes uniquement —</option>${unknownOption}${knownOptions}`;
  }

  // Rendu d'UN champ d'édition de note rapide, factorisé pour être réutilisé identiquement par la
  // ligne de tableau (page Notes) ET par le bloc contextuel (Modifier depuis la page cible) — un seul
  // moteur d'édition, jamais deux formulaires presque identiques qui pourraient diverger.
  // Lot G3 — le champ Montant n'a plus de rendu (retiré de l'UI) : "amount" est un champ legacy,
  // conservé en données (normalizeMemoRow, src/06-normalize-state.js) et toujours accepté par
  // updateQuickNote (src/21-handlers.js), mais plus jamais proposé à l'édition ici. Même doctrine
  // que "category" au-dessus.
  function quickNoteFieldHtml(field, row) {
    const rowId = esc(row.id);
    if (field === "targetView") return `<select data-quick-note-field="targetView" data-id="${rowId}" title="Afficher dans">${noteTargetViewOptions(row.targetView)}</select>`;
    if (field === "title") return `<input data-quick-note-field="title" data-id="${rowId}" value="${esc(row.title)}" placeholder="Sujet" />`;
    if (field === "note") return `<textarea data-quick-note-field="note" data-id="${rowId}">${esc(row.note)}</textarea>`;
    if (field === "priority") return `<select data-quick-note-field="priority" data-id="${rowId}" title="Priorité">${memoPriorityOptions(row.priority)}</select>`;
    return "";
  }

  // Lot "Notes contextuelles par page" — badge de priorité LOCAL aux notes rapides, réutilisant les
  // classes .status déjà thémées (clair/sombre) plutôt qu'un nouveau système : statusClass() global
  // ne reconnaît pas ces valeurs de priorité et reste volontairement inchangé (voir rapport
  // d'analyse). Urgent = rouge (late), Important = orange (wait), Normale/Archive = discret (muted) :
  // pas de "sapin de Noël".
  function quickNotePriorityBadge(priority) {
    if (priority === "Urgent") return `<span class="status late">Urgent</span>`;
    if (priority === "Important") return `<span class="status wait">Important</span>`;
    if (priority === "Archive") return `<span class="muted">Archive</span>`;
    return `<span class="muted">Normale</span>`;
  }

  function quickNoteRow(row) {
    const editing = ui.quickNoteEditId === row.id;
    if (editing) {
      return `<tr class="memo-row editing">
        <td>${quickNoteFieldHtml("targetView", row)}</td>
        <td>${quickNoteFieldHtml("title", row)}</td>
        <td>${quickNoteFieldHtml("note", row)}</td>
        <td>${quickNoteFieldHtml("priority", row)}</td>
        <td><div class="actions"><button class="icon" title="Terminer la modification" data-action="close-quick-note">✓</button><button class="icon danger" title="Supprimer" data-action="delete-quick-note" data-id="${esc(row.id)}">×</button></div></td>
      </tr>`;
    }
    return `<tr class="memo-row">
      <td>${esc(noteTargetViewLabel(row.targetView))}</td>
      <td><strong>${esc(row.title) || `<span class="muted">-</span>`}</strong></td>
      <td class="memo-note">${esc(row.note) || `<span class="muted">-</span>`}</td>
      <td>${statusPill(row.priority || "Normale")}</td>
      <td><div class="actions"><button class="icon" title="Modifier cette note" data-action="edit-quick-note" data-id="${esc(row.id)}">✎</button><button class="icon danger" title="Supprimer" data-action="delete-quick-note" data-id="${esc(row.id)}">×</button></div></td>
    </tr>`;
  }

  function quickNotesSection() {
    const rows = state.memoRows || [];
    return `
      <div class="band quick-notes-band">
        <div class="band-title">
          <div>
            <h2>Notes personnalisées</h2>
            <p class="muted">Créez vos notes et choisissez où les afficher dans le logiciel. Elles restent toutes accessibles et modifiables ici.</p>
          </div>
          <button data-action="add-quick-note">+ Nouvelle note</button>
        </div>
        <div class="table-wrap">
          <table class="editable-table memo-table">
            <thead><tr><th>Afficher dans</th><th>Sujet</th><th>Note</th><th>Priorité</th><th></th></tr></thead>
            <tbody>
              ${rows.length ? rows.map(quickNoteRow).join("") : `<tr><td colspan="5"><div class="empty compact">Aucune note personnalisée. Utilisez + Nouvelle note pour en ajouter une.</div></td></tr>`}
            </tbody>
          </table>
        </div>
      </div>`;
  }

  // Lot "Notes contextuelles par page" — notes actives (hors Archive) ciblant précisément viewId,
  // triées Urgent > Important > Normale, ordre stable (index d'origine) à priorité identique.
  // viewId doit appartenir à NOTE_TARGET_VIEW_IDS : une note stockée avec un targetView hors
  // allowlist (page volontairement exclue comme "settings", ou valeur inconnue/legacy) reste
  // intacte en données mais ne doit JAMAIS produire de bloc contextuel — seul le rendu filtre,
  // la normalisation reste non destructive (cf. normalizeMemoRow, src/06-normalize-state.js).
  function notesForView(viewId) {
    const targetView = asText(viewId);
    if (!NOTE_TARGET_VIEW_IDS.includes(targetView)) return [];
    const priorityRank = { Urgent: 0, Important: 1, Normale: 2 };
    return (state.memoRows || [])
      .map((row, index) => ({ row, index }))
      .filter(({ row }) => row.targetView === targetView && row.priority !== "Archive")
      .sort((a, b) => (priorityRank[a.row.priority] ?? 2) - (priorityRank[b.row.priority] ?? 2) || a.index - b.index)
      .map(({ row }) => row);
  }

  // Une ligne compacte du bloc contextuel : mêmes actions (edit-quick-note/delete-quick-note) et
  // mêmes champs (quickNoteFieldHtml) que la page Notes — aucun second moteur d'édition/suppression.
  function contextualNoteRowHtml(row) {
    const editing = ui.quickNoteEditId === row.id;
    if (editing) {
      return `<div class="contextual-note-row editing" data-id="${esc(row.id)}">
        <div class="contextual-note-edit-fields">
          ${quickNoteFieldHtml("targetView", row)}
          ${quickNoteFieldHtml("title", row)}
          ${quickNoteFieldHtml("note", row)}
          ${quickNoteFieldHtml("priority", row)}
        </div>
        <div class="actions"><button class="icon" title="Terminer la modification" data-action="close-quick-note">✓</button><button class="icon danger" title="Supprimer" data-action="delete-quick-note" data-id="${esc(row.id)}">×</button></div>
      </div>`;
    }
    return `<div class="contextual-note-row" data-id="${esc(row.id)}">
      <strong>${esc(row.title) || `<span class="muted">-</span>`}</strong>
      <span class="contextual-note-text">${esc(row.note)}</span>
      ${quickNotePriorityBadge(row.priority)}
      <div class="actions"><button class="icon" title="Modifier cette note" data-action="edit-quick-note" data-id="${esc(row.id)}">✎</button><button class="icon danger" title="Supprimer" data-action="delete-quick-note" data-id="${esc(row.id)}">×</button></div>
    </div>`;
  }

  // Lot "Notes contextuelles par page" — POINT UNIQUE de production du bloc, appelé une seule fois
  // depuis render() (src/10-calcs-shell.js). "" si aucune note active ne cible viewId : AUCUN DOM
  // supplémentaire (pas de cadre/titre/placeholder vide) — jamais un renderer de page individuel à
  // modifier.
  function contextualNotesBlockHtml(viewId) {
    const rows = notesForView(viewId);
    if (!rows.length) return "";
    return `<div class="band contextual-notes-band">
      <div class="band-title compact"><h3>📌 Notes</h3></div>
      <div class="contextual-notes-list">
        ${rows.map(contextualNoteRowHtml).join("")}
      </div>
    </div>`;
  }

  function activeNote() {
    let note = state.notes.find((item) => item.id === ui.noteId) || state.notes[0];
    if (!note) {
      note = { id: id("note"), title: "", content: "", updatedAt: new Date().toISOString() };
      state.notes.push(stampRecordClubId(note));
      ui.noteId = note.id;
    }
    return note;
  }

  function renderNotes() {
    const note = activeNote();
    return `<div class="notes-page">
      <div class="band notes-tabs-band">
        <div class="band-title">
          <h2>Notes</h2>
          <button data-action="add-note">+ Note</button>
        </div>
        <div class="note-tabs">
          ${state.notes.map((item) => `<button class="note-tab ${item.id === note.id ? "active" : ""}" data-action="select-note" data-id="${esc(item.id)}" title="${esc(item.title || "Note")}">${esc(item.title || "Note")}</button>`).join("")}
        </div>
      </div>
      <div class="band note-editor-band">
        <div class="band-title note-title-row">
          <input class="note-title-input" data-note-title value="${esc(note.title)}" />
          <div class="actions">
            <button data-action="save-note">Enregistrer</button>
            <button class="danger" data-action="delete-note">Supprimer l'onglet</button>
          </div>
        </div>
        <div class="note-toolbar">
          <select data-note-command="fontName" title="Police">
            ${FONT_OPTIONS.map((font) => `<option value="${esc(font.label)}">${esc(font.label)}</option>`).join("")}
          </select>
          <select data-note-command="fontSize" title="Taille">
            <option value="2">Petit</option>
            <option value="3" selected>Normal</option>
            <option value="5">Grand</option>
            <option value="7">Très grand</option>
          </select>
          <input type="color" value="#17211e" data-note-command="foreColor" title="Couleur du texte" />
          <input type="color" value="#fff1db" data-note-command="hiliteColor" title="Surlignage" />
          <button class="icon" data-note-command="bold" title="Gras"><b>B</b></button>
          <button class="icon" data-note-command="italic" title="Italique"><i>I</i></button>
          <button class="icon" data-note-command="underline" title="Souligné"><u>U</u></button>
          <button class="icon" data-note-command="strikeThrough" title="Barré"><s>S</s></button>
          <button class="icon" data-note-command="justifyLeft" title="Aligner à gauche">≡</button>
          <button class="icon" data-note-command="justifyCenter" title="Centrer">≣</button>
          <button class="icon" data-note-command="justifyRight" title="Aligner à droite">≡</button>
          <button class="icon" data-note-command="insertUnorderedList" title="Liste">•</button>
          <button class="icon" data-note-command="insertOrderedList" title="Liste numérotée">1.</button>
          <button data-note-command="removeFormat">Effacer style</button>
        </div>
        <div class="note-editor" contenteditable="true" spellcheck="true" data-note-editor>${sanitizeNoteHtml(note.content || "")}</div>
      </div>
      ${quickNotesSection()}
    </div>`;
  }

  function renderHelp() {
    const stagesEnabled = isModuleEnabled("stages") && hasFeature("stages");
    const boutiqueEnabled = isModuleEnabled("boutique");
    return `
      <div class="help-page">
        <section class="help-layout">
          <nav class="help-toc band pad">
            <a href="#help-resume">Résumé rapide</a>
            <a href="#help-demarrer">Démarrer</a>
            <a href="#help-clubs">Clubs</a>
            <a href="#help-a-faire">À faire</a>
            <a href="#help-recherche">Recherche</a>
            <a href="#help-contacts">Contacts</a>
            <a href="#help-factures">Factures</a>
            <a href="#help-newsletter">E-mail</a>
            <a href="#help-disciplines">Disciplines</a>
            <a href="#help-groupes">Groupes</a>
            <a href="#help-coachs">Coachs</a>
            <a href="#help-salles">Salles</a>
            <a href="#help-planning">Planning</a>
            <a href="#help-disponibilites">Disponibilités</a>
            <a href="#help-presences">Présences</a>
            <a href="#help-documents">Documents sportifs</a>
            <a href="#help-paiements">Paiements</a>
            <a href="#help-couleurs">Codes couleurs</a>
            ${boutiqueEnabled ? `<a href="#help-boutique">Boutique</a>` : ""}
            ${boutiqueEnabled ? `<a href="#help-stock">Stock</a>` : ""}
            ${stagesEnabled ? `<a href="#help-stages">Stages</a>` : ""}
            <a href="#help-tarifs">Tarifs</a>
            <a href="#help-parametres">Paramètres</a>
            <a href="#help-utilisateurs">Utilisateurs</a>
            <a href="#help-notes">Notes</a>
            <a href="#help-stats">Statistiques</a>
            <a href="#help-compta">Comptabilité</a>
            <a href="#help-historique">Historique</a>
            <a href="#help-journal">Journal d'activité</a>
            <a href="#help-donnees">Données</a>
          </nav>

          <div class="help-content">
            <section class="help-hero">
              <div>
                <span>Guide intégré</span>
                <h2>Utiliser MonGestaClub</h2>
                <p>Cette aide décrit le fonctionnement complet du logiciel. Elle sera complétée au fur et à mesure des évolutions de l'application.</p>
                <button type="button" class="feedback-cta" data-action="open-feedback"><span class="feedback-cta-icon" aria-hidden="true">💬</span> Donner mon avis / signaler un bug</button>
              </div>
              <div class="help-version">
                <strong>Version actuelle</strong>
                <span>Multi-clubs, contacts, factures, e-mails, disciplines, coachs, salles, planning${boutiqueEnabled ? ", boutique, stock" : ""}${stagesEnabled ? ", stages" : ""}, dépenses, statistiques, comptabilité, tarifs, notes et sauvegardes.</span>
              </div>
            </section>

            ${helpSection("help-resume", "Résumé rapide", [
              "En haut de l'Accueil, le bloc Vigilance résume en quelques secondes l'état du club : ce qui est À traiter (rouge), À surveiller (jaune) et ce qui est en ordre (vert). Chaque carte mène au plus court vers la résolution : la fiche concernée s'il n'y a qu'un cas, une petite fenêtre pour régler quelques cas sans quitter l'Accueil, ou la liste filtrée s'il y en a beaucoup. MonGestaClub veille en continu : tu n'as rien à lancer.",
              "Astuce : sur chaque page, le bouton Aide de la barre du haut ouvre directement la partie de l'aide qui concerne cette page. Depuis Contacts il ouvre l'aide Contacts, depuis Factures l'aide Factures, etc.",
              "Commence par Paramètres : choisis le thème, vérifie les modules affichés, règle le paiement en plusieurs fois et le mot de passe.",
              "Au premier démarrage, l'assistant propose déjà le minimum : identité du club, logo, thème, modules visibles, paiement en plusieurs fois, mot de passe et activation éventuelle.",
              `Va dans Tarifs : crée ou vérifie les éléments utilisés par le club : disciplines, assurances${boutiqueEnabled ? ", articles" : ""}${stagesEnabled ? ", stages" : ""}.`,
              `Ajoute les personnes dans Contacts, ou directement depuis une inscription${boutiqueEnabled ? ", une vente" : ""}${stagesEnabled ? " ou un stage" : ""}.`,
              "Depuis une fiche contact, le bouton Créer / éditer une facture centralise les lignes à facturer pour cette personne.",
              "Les factures peuvent reprendre une inscription, une discipline, une cotisation, une licence, une assurance, un stage, une commande boutique ou une ligne libre.",
              "Utilise E-mail pour annoncer un stage, envoyer une newsletter, préparer une relance ou écrire un message personnalisé.",
              "Pour inscrire un adhérent, ouvre Disciplines puis Nouvelle inscription. Choisis le contact, la discipline, l'assurance et le paiement.",
              "Les paiements utilisent les modes acceptés du club actif : espèces, chèque, carte bancaire, virement, coupons sport, chèques vacances ou autre selon les réglages. Le logiciel affiche le reste dû et les alertes automatiquement.",
              boutiqueEnabled ? "Pour vendre un article, ouvre Boutique. Choisis l'article, la taille, la quantité, le client, puis le paiement." : "",
              boutiqueEnabled ? "Le Stock suit les articles, les tailles, les photos, les seuils d'alerte et les mouvements de boutique." : "",
              stagesEnabled ? "Pour gérer un stage, ouvre Stages. Crée le stage si besoin, ajoute les participants, puis valide stage et hébergement." : "",
              "L'accueil sert à surveiller rapidement les encaissements, les alertes et les actions importantes.",
              "Statistiques donne une vue d'ensemble de l'activité. Comptabilité donne les recettes, restes dus, TVA et résultats indicatifs.",
              "Notes sert à écrire librement les informations utiles du club.",
              "Exporte régulièrement une sauvegarde JSON. Le CSV sert surtout à sortir la page active vers un tableur.",
            ].filter(Boolean))}

            ${helpSection("help-demarrer", "Démarrer", [
              "L'accueil est le cockpit du club : il affiche les encaissements à suivre, les stocks bas, les raccourcis et les indicateurs principaux.",
              "L'accueil n'affiche que l'utile : certains indicateurs comme Stages à venir ou Stocks faibles apparaissent seulement si le module est réellement utilisé. Les actions de démarrage restent toujours disponibles (Créer un stage, Accéder à la boutique…) pour pouvoir commencer même sans données.",
              "Le menu principal permet d'aller vers chaque module. Selon la disposition choisie dans Paramètres > Affichage > Disposition, il s'affiche à gauche (Moderne) ou en haut du logiciel (Classique). Les boutons Exporter JSON et Importer JSON servent aux sauvegardes complètes.",
              "Dans l'application installée, le menu système Fichier / Édition / Affichage / Aide donne les mêmes accès que les boutons du logiciel : enregistrer, exporter, importer, imprimer, naviguer vers une page, ouvrir l'aide ou afficher les informations de licence.",
              "Sur Windows, ce menu reste visible en haut de la fenêtre. Sur Mac, il apparaît dans la barre de menus du système.",
              `Les boutons rapides de l'accueil ouvrent directement les formulaires les plus utilisés : inscription, contact${boutiqueEnabled ? ", vente" : ""}${stagesEnabled ? ", stage" : ""}.`,
              "La barre du haut affiche d'abord le titre de la page, puis les raccourcis sur la ligne dessous : page précédente, page suivante, annuler, rétablir, couper, copier, coller, imprimer, exporter CSV, ouvrir l'aide et enregistrer.",
              "Le bouton Aide de la barre du haut ouvre directement la section de l'aide qui correspond à la page d'où on le clique : depuis Contacts il ouvre l'aide Contacts, depuis Factures l'aide Factures, etc.",
              "Dans l'aide, le sommaire à gauche reste fixe : il liste toutes les sections et permet d'aller directement à l'une d'elles. Seul le texte de droite défile.",
              "Le bouton PDF crée un fichier PDF qui reprend la même présentation que la page imprimable, sans la barre latérale ni les boutons du logiciel. Dans la version installée, c'est un vrai fichier PDF ; dans un navigateur, le bouton peut utiliser la fenêtre d'impression du système.",
              `La recherche globale en haut permet de retrouver rapidement un contact, une inscription${boutiqueEnabled ? ", une commande, un article" : ""}${stagesEnabled ? ", un stage" : ""} ou une note.`,
              "Dans Paramètres > Affichage, on peut ajouter le texte sous les icônes de cette barre pour rendre les boutons plus lisibles.",
              `Le menu principal garde les pages de travail au premier niveau.${boutiqueEnabled ? " Boutique ouvre Stock," : ""} Paramètres ouvre Tarifs, Statistiques, Comptabilité, Notes et Aide.`,
              "Les éléments cliquables affichent une infobulle au survol : ouvrir une fiche, dérouler une rubrique ou éditer une ligne selon le contexte.",
              "Les fenêtres flottantes peuvent être déplacées en maintenant leur barre de titre avec la souris.",
              "Le bouton Enregistrer confirme la sauvegarde dans le logiciel. L'export JSON reste une sauvegarde de secours à conserver à part.",
            ])}

            ${helpSection("help-clubs", "Mes clubs", [
              "MonGestaClub peut gérer plusieurs clubs séparés dans le même logiciel.",
              "Le club actif est visible dans le menu principal (à gauche en disposition Moderne, en haut en disposition Classique). Le sélecteur de club permet de passer d'un club à l'autre.",
              "Quand un club est actif, les contacts, inscriptions, paiements, boutique, stocks, notes, historique, thèmes et paramètres affichés appartiennent uniquement à ce club.",
              "La page Mes clubs permet de créer un club, modifier son identité, le dupliquer, l'activer ou l'archiver.",
              "En haut de Mes clubs, le bouton Créer un club démo ajoute un club de démonstration séparé avec des données fictives, sans toucher aux vrais clubs.",
              "Si le club démo existe déjà, le bouton Réinitialiser le club démo supprime uniquement ce club de démonstration puis le recrée proprement.",
              "Un club archivé n'est plus proposé dans la sélection normale. Il peut être retrouvé avec l'option Afficher archivés.",
              "Le bouton Supprimer retire définitivement un club et toutes ses données après confirmation et mot de passe. Il est conseillé d'exporter une sauvegarde JSON avant cette action.",
              "Le dernier club disponible ne peut pas être supprimé : il faut toujours garder ou créer au moins un club.",
              "La page Paramètres du club contient l'identité visuelle, les informations administratives, l'adresse, les responsables, les paiements et les informations prévues pour de futurs documents.",
              "Le bouton Assistant complet ouvre un assistant étape par étape pour modifier l'identité, l'administratif, l'adresse, les responsables, les paiements et les documents du club actif.",
              "Lors de la mise à jour multi-clubs, les anciennes données sont automatiquement placées dans un premier club par défaut. Une sauvegarde technique de l'ancien format est conservée avant migration.",
            ])}

            ${helpSection("help-a-faire", "À faire aujourd'hui", [
              "La page À faire regroupe automatiquement les vraies urgences du moment, pas les simples rappels.",
              `Elle affiche des post-it colorés pour les paiements en retard ou refusés, les documents manquants ou expirés, les coachs ou salles à remplacer, les conflits de planning${boutiqueEnabled ? ", le stock en rupture" : ""} et les groupes complets.`,
              `Chaque post-it indique le type d'alerte, la personne${boutiqueEnabled ? " ou l'article" : ""} concerné, le détail utile et l'action disponible.`,
              "Le bouton Ouvrir ouvre clairement la fiche concernée. Le bouton Relancer prépare un e-mail quand une relance est possible.",
              `Cliquer sur un post-it de paiement${boutiqueEnabled ? " ou de stock" : ""} ouvre la fiche correspondante pour agir tout de suite.`,
              "Le bouton Relancer prépare un message simple pour prévenir la personne concernée.",
              "Si la fiche contient un e-mail, la relance propose Ouvrir l'e-mail : la messagerie s'ouvre avec le destinataire, l'objet et le message déjà remplis.",
              "Le texte de relance est modifiable dans Paramètres > Messages e-mail.",
            ])}

            ${helpSection("help-recherche", "Recherche globale", [
              "La page Recherche affiche les résultats trouvés dans tout le logiciel.",
              `On peut chercher par nom, prénom, téléphone, e-mail, ville, discipline${stagesEnabled ? ", stage" : ""}${boutiqueEnabled ? ", article" : ""}, note ou texte présent dans une fiche.`,
              "La recherche de la barre du haut fonctionne depuis n'importe quelle page : taper le texte puis appuyer sur Entrée ou OK.",
              "Les résultats indiquent la rubrique et ouvrent directement la fiche ou la page utile quand un lien existe.",
              "Exporter CSV depuis Recherche exporte la liste des résultats affichés.",
            ])}

            ${helpSection("help-contacts", "Contacts", [
              "La page Contacts contient deux listes : Adhérents et Non adhérents.",
              "Un adhérent créé depuis une inscription discipline est automatiquement ajouté ou mis à jour dans les contacts adhérents.",
              "Sans discipline choisie, une fiche saisie depuis l'inscription discipline est rangée dans Non adhérents et aucune inscription discipline n'est créée.",
              boutiqueEnabled && stagesEnabled ? "Une vente boutique ou une inscription stage faite sans adhérent sélectionné crée ou met à jour un contact non adhérent." : boutiqueEnabled ? "Une vente boutique faite sans adhérent sélectionné crée ou met à jour un contact non adhérent." : stagesEnabled ? "Une inscription stage faite sans adhérent sélectionné crée ou met à jour un contact non adhérent." : "Un contact peut rester non adhérent tant qu'aucune discipline ne lui est associée.",
              "Les fiches contacts gardent le nom, prénom, e-mail, téléphone, adresse, ville et date de naissance.",
              "Pour enregistrer une fiche contact, seuls le nom, le prénom et au moins un moyen de contact (téléphone ou e-mail) sont obligatoires. L'adresse, le code postal, la ville et la date de naissance restent recommandés mais facultatifs : ils restent utiles pour les factures et pour calculer la catégorie Adulte / Enfant.",
              "Quand Internet est disponible, saisir un code postal complète ou propose la ville, et saisir une ville complète ou propose le code postal.",
              "Le bouton Envoyer un mail ouvre une fenêtre avec l'adresse du contact déjà remplie. On choisit un modèle e-mail, puis le sujet et le message restent modifiables avant ouverture de la messagerie.",
              "La fiche contact peut contenir une photo d'identité. Sans photo, le logiciel affiche automatiquement une silhouette homme, femme, fille ou garçon selon les informations connues.",
              "Si la silhouette automatique ne correspond pas, choisis manuellement Garçon, Fille, Femme ou Homme dans la fiche contact.",
              "La photo s'affiche en haut à gauche de la fenêtre, se réduit automatiquement au bon format, s'ouvre en grand au clic et peut être remplacée ou retirée.",
              `La photo d'identité suit le contact : elle apparaît aussi dans les fiches Discipline${stagesEnabled ? " et Stage" : ""} liées à cette personne.`,
              "La catégorie Adulte ou Enfant est calculée automatiquement avec la date de naissance : adulte à partir de 18 ans.",
              "La couleur à gauche d'une fiche contact résume l'état financier du contact : rouge s'il reste quelque chose à payer, vert si tout est réglé.",
              `Dans une fiche contact, les boutons${boutiqueEnabled ? " Boutique," : ""} Disciplines${stagesEnabled ? " et Stages" : ""} reprennent le même code couleur : vert quand tout est réglé, orange pour un paiement en cours ou à venir, rouge pour un paiement dépassé, refusé ou annulé.`,
              "Les boutons en bas de la fiche contact (Envoyer un mail, Créer / éditer une facture, Boutique, Disciplines, Stages) suivent les modules actifs dans Paramètres > Affichage : si un module est masqué, son bouton n'est plus proposé. Les données déjà enregistrées ne sont jamais supprimées.",
              `La fiche contact affiche aussi un récapitulatif en lecture seule des disciplines${stagesEnabled ? ", stages" : ""}${boutiqueEnabled ? ", achats boutique" : ""}, montants réglés et restes dus liés à la personne.`,
              "Le bloc Documents permet d'ajouter des fichiers utiles au contact : certificat, autorisation, justificatif ou autre document interne.",
              "Les documents ajoutés restent attachés à la fiche contact et sont inclus dans la sauvegarde JSON.",
              "Quand un contact possède des documents, un trombone apparaît sur sa ligne avec le nombre de pièces jointes.",
              "Quand on choisit un document, il apparaît immédiatement dans la fiche. Le bouton Lire ouvre le document, et Retirer supprime la copie enregistrée dans MonGestaClub.",
              `Quand on ouvre${boutiqueEnabled ? " Boutique," : ""} Disciplines${stagesEnabled ? " ou Stages" : ""} depuis une fiche contact, une deuxième fenêtre s'ouvre par-dessus. Enregistrer le paiement ferme seulement cette deuxième fenêtre : la fiche contact reste ouverte pour continuer.`,
              boutiqueEnabled ? "Le bouton Boutique ouvre la commande du contact ou prépare une nouvelle vente avec ses coordonnées déjà remplies." : "",
            ].filter(Boolean))}

            ${helpSection("help-factures", "Factures", [
              "Les factures sont centralisées par contact : on ne crée pas une facture séparée par discipline, stage ou article.",
              "Depuis une fiche contact, le bouton Créer / éditer une facture ouvre l'éditeur de facture de cette personne.",
              `Depuis une fiche Discipline${boutiqueEnabled ? ", Boutique" : ""}${stagesEnabled ? " ou Stage" : ""}, le bouton Fiche contact / facture permet de revenir à la fiche contact pour gérer sa facture.`,
              "L'éditeur propose les éléments payants liés au contact : inscription, discipline, cotisation, licence, assurance, stage, boutique, frais ou ligne personnalisée.",
              "Un élément déjà présent dans une facture émise est signalé comme déjà facturé pour éviter les doublons.",
              "Tant que la facture est en brouillon, les lignes peuvent être choisies et modifiées.",
              "Quand la facture est émise, elle reçoit un numéro unique propre au club actif et ses lignes sont verrouillées.",
              "Une facture émise garde une copie des informations du club et du contact utilisées au moment de l'émission.",
              "Les paiements liés à la facture font évoluer le montant payé, le reste à payer et le statut sans recréer une nouvelle facture.",
              "Le bouton Ajouter un règlement sert à enregistrer un nouveau paiement sur une facture déjà émise. Le montant est prérempli avec le reste à payer.",
              "Dans Ajouter un règlement, quand la facture a plusieurs lignes, on peut cocher seulement les lignes à régler (cotisation, licence, assurance, stage, boutique, frais...) : la somme se met à jour automatiquement, limitée au reste à payer. Pratique pour encaisser une partie seulement, par exemple la licence d'abord.",
              "Après un règlement, le reste à payer de la facture se met à jour immédiatement, même quand le règlement a été ajouté par-dessus la fiche facture.",
              "Le bouton Imprimer la facture ouvre une version texte propre, sans l'interface du logiciel. La même facture peut être réimprimée autant de fois que nécessaire.",
              "Le bouton PDF facture crée un PDF texte dans l'application installée. Dans le navigateur, il utilise l'impression du document texte.",
              "La page Factures liste uniquement les factures du club actif et permet de retrouver les brouillons, factures émises, partielles, payées ou à régler.",
            ])}

            ${helpSection("help-newsletter", "E-mail", [
              "La page E-mail sert à préparer un message collectif : relance de paiement, annonce de stage, changement d'horaire, information importante, nouveauté boutique ou message général du club.",
              "Commence par choisir le modèle d'e-mail : relance de paiement, e-mail simple, newsletter ou un modèle personnalisé créé dans Paramètres > Messages e-mail.",
              "Choisis ensuite les destinataires : tous les adhérents, tous les non adhérents, tout le monde, rappels de paiement dépassés, ou saisie manuelle.",
              "Il existe aussi des publics dédiés à l'encadrement : coachs actifs, coachs sélectionnés, responsables de salles, ou responsable de la salle choisie. Ils ne reprennent que les coachs et salles du club actif.",
              "Pour les coachs sélectionnés ou la salle choisie, une liste de cases permet de cibler précisément les personnes concernées, par exemple pour une demande de remplacement.",
              "Le public Membres d'un groupe permet d'écrire aux adhérents d'un groupe : choisis ce public puis le groupe dans le menu qui apparaît. Le logiciel reprend les inscriptions affectées à ce groupe (membership.groupId), retrouve les contacts et ajoute leurs e-mails. Les membres sans e-mail sont ignorés et listés à part sous « Sans e-mail (non inclus) », et un membre inscrit à plusieurs disciplines n'apparaît qu'une seule fois.",
              "Depuis la fiche d'un groupe (bouton Membres du groupe), le bouton « Envoyer un e-mail au groupe » ouvre directement la page E-mail avec ce groupe présélectionné et le modèle « Message aux membres d'un groupe ». Le message est seulement préparé : rien n'est envoyé tant que tu n'as pas vérifié et cliqué pour envoyer ou copier.",
              "Le modèle « Message aux membres d'un groupe » accepte les variables {groupeNom}, {groupeDiscipline}, {groupeCoach}, {groupeSalle} et {groupeNombreMembres}. Une variable sans valeur reste vide.",
              "Le public Rappels de paiement dépassés ne garde que les adhérents et non adhérents qui ont un paiement à relancer : échéance dépassée, à encaisser ou refusé. Les paiements en cours ou à venir ne sont pas concernés.",
              "Le mode Libre / saisie manuelle permet d'envoyer uniquement aux adresses tapées à la main, sans reprendre les contacts du logiciel.",
              "On peut coller plusieurs adresses d'un coup, séparées par virgule, point-virgule, espace ou retour à la ligne, puis cliquer sur Ajouter.",
              "En saisie manuelle uniquement, une adresse est ajoutée à la liste même si elle existe déjà dans les contacts, car l'envoi suit exactement la liste tapée.",
              "Le logiciel construit automatiquement la liste des destinataires à partir des contacts du public choisi qui possèdent une adresse e-mail.",
              "Les personnes sans e-mail ne sont pas ajoutées à l'envoi. Les compteurs en haut indiquent aussi combien d'adhérents et de non adhérents n'ont pas d'e-mail.",
              "Le sujet et le message sont préremplis avec le modèle choisi, configuré dans Paramètres > Messages e-mail.",
              "Les champs Titre de l'information, Détail du message, Date affichée et Lieu remplissent les variables {titre}, {detail}, {date} et {lieu} du modèle.",
              "On peut modifier le sujet et le texte directement dans la page E-mail avant l'envoi.",
              "La colonne de droite affiche directement les contacts sélectionnés pour l'envoi.",
              "On peut ajouter une adresse libre qui n'existe pas dans les contacts, uniquement pour l'envoi en cours.",
              "On peut retirer un destinataire de la sélection avec la croix placée sur sa ligne.",
              "Le bouton Réafficher les contacts retirés remet dans la liste les contacts supprimés de l'envoi sans modifier le sujet ni le message.",
              "L'aperçu du message reste visible sous le texte pour vérifier rapidement le contenu avant l'ouverture de la messagerie.",
              "Le bouton Ouvrir la messagerie prépare un e-mail avec les destinataires en copie cachée pour préserver la confidentialité.",
              "Le logiciel ne force pas l'envoi : il prépare le message, puis l'envoi final se fait depuis la messagerie de l'utilisateur. Aucun e-mail n'est envoyé automatiquement sans validation.",
              "Les modèles d'e-mail incluent aussi des modèles pour les coachs et les salles (message simple ou demande de remplacement / changement), modifiables dans Paramètres > Messages e-mail.",
              "Les variables entre accolades sont remplacées automatiquement à l'envoi. En plus des variables contact, club, paiement et facture, il existe des variables coach ({coachNom}, {coachPrenom}, {coachEmail}, {coachTelephone}, {coachSpecialites}), salle ({salleNom}, {salleAdresse}, {salleType}, {salleCapacite}, {salleResponsableNom}, {salleResponsableEmail}, {salleResponsableTelephone}, {salleTarif}) et séance ({dateSeance}, {heureDebut}, {heureFin}, {statutSeance}, {discipline}, {lieu}).",
              "La liste complète des variables, avec leur description, est cliquable pour copie dans Paramètres > Messages e-mail. Une variable sans valeur dans le contexte est simplement laissée vide.",
              "Pour une grosse liste de destinataires, il vaut mieux envoyer en plusieurs fois afin d'éviter les limites de la messagerie.",
              "Les boutons Copier les e-mails et Copier le message permettent d'utiliser un autre outil d'envoi si besoin.",
              "Exporter CSV depuis E-mail exporte la liste des destinataires affichés, utile pour vérifier ou préparer un envoi externe.",
              "La page E-mail peut être affichée ou masquée dans Paramètres > Affichage.",
            ])}

            ${helpSection("help-disciplines", "Disciplines", [
              "La page Disciplines sert à gérer les inscriptions annuelles ou régulières.",
              "Le bloc Disciplines en un coup d'oeil est replié par défaut. Cliquer sur sa ligne affiche les totaux.",
              "Le bloc Gérer les disciplines est repliable comme les fiches en un coup d'oeil. Il permet d'ajouter, modifier ou supprimer une discipline sans passer par Tarifs.",
              "Cliquer sur une ligne de discipline la rend éditable. La petite coche valide la modification et met à jour les inscriptions liées.",
              "Lors d'une nouvelle inscription, on peut choisir un contact existant ou saisir une nouvelle fiche avec sa date de naissance.",
              "Le code postal et la ville se complètent automatiquement comme dans les contacts quand Internet est disponible.",
              "Dans une inscription discipline, la discipline et les coordonnées principales sont obligatoires pour enregistrer.",
              "La discipline est ce qui rend la personne adhérente : si elle reste vide, la personne est conservée comme non adhérente.",
              "Le tarif de la discipline et le prix de l'assurance viennent de la page Tarifs : ils ne sont pas à retaper à la main.",
              "Le prix de la discipline est figé au moment de l'inscription : si tu modifies ensuite ce tarif dans la page Tarifs, les inscriptions déjà enregistrées gardent leur prix d'origine. Seules les nouvelles inscriptions prennent le nouveau tarif.",
              "Pour ré-appliquer le tarif courant à une inscription existante, il suffit de rouvrir sa fiche et de re-sélectionner la discipline.",
              "Dans la sélection d'assurance, le menu affiche seulement le nom de l'assurance. Le montant apparaît dans la case Prix assurance à côté.",
              "La licence fédérale s'ajoute au tarif de la discipline (elle n'est pas comprise dedans). Une remise peut aussi être appliquée. Le total attendu se calcule ainsi : tarif discipline + licence + assurance - remise.",
              "La liste des adhérents est organisée par lettres. Cliquer sur A, B, C, etc. filtre la liste sur les noms correspondants.",
              "Dans Disciplines en un coup d'oeil, cliquer sur Reste dû ouvre la liste des adhérents concernés. Cliquer sur une ligne ouvre directement la fiche à régulariser.",
              "Chaque adhérent apparaît sur une ligne compacte. Cliquer sur la ligne ouvre la fiche d'inscription.",
              "Le certificat médical, les pathologies et les paiements sont conservés dans la fiche d'inscription.",
              "Si le certificat médical est sur Non, l'inscription reste possible mais une alerte apparaît dans la fiche et dans À faire.",
              "Si l'assurance n'est pas encore renseignée, l'inscription reste possible mais une alerte rappelle de la vérifier.",
              "Le champ Niveau / grade est une note libre sur l'inscription (par exemple Débutant, Confirmé, Ceinture jaune). Elle s'affiche dans le récapitulatif de cette inscription, mais ce n'est ni une entité structurée ni un filtre automatique.",
              "Dans Paramètres > Disciplines et catégories sportives, chaque discipline peut avoir ses propres catégories sportives : Poussins, Benjamins, Seniors, Confirmés, Tous niveaux, Intermédiaire… Une catégorie sportive appartient toujours à une seule discipline, et sert selon le club à représenter une tranche d'âge, un niveau, un type de public ou un simple repère interne.",
              "Le catalogue proposé pour certains sports (par exemple Poussins, Benjamins, Seniors pour un profil Judo) reste une suggestion : ce n'est pas une liste fermée. Le club reste libre de créer d'autres catégories, y compris pour une discipline personnalisée qui ne correspond à aucun sport du catalogue.",
              "Dans le dialogue Gérer d'une discipline, on crée, modifie, réordonne et archive ses catégories. L'ordre choisi ici est celui utilisé partout où la catégorie est proposée dans un menu.",
              "Une catégorie sportive se choisit ensuite sur une inscription, et éventuellement sur un groupe entier. Une catégorie archivée n'est plus proposée pour une nouvelle affectation, mais reste affichée sur les inscriptions qui l'utilisaient déjà, pour garder une référence historique lisible.",
            ])}

            ${helpSection("help-groupes", "Groupes", [
              "La page Groupes rassemble des adhérents qui s'entraînent ensemble, pour faciliter l'appel et le planning.",
              "Le champ Type de groupe (repère) sert seulement à classer vos groupes (par exemple Débutants, Confirmés, Enfants, Adultes, Loisir, Compétition). Ce n'est pas un niveau automatique : il ne pilote ni les inscriptions ni les tarifs.",
              "La discipline reliée au groupe sert à proposer des coachs compatibles et à relier le groupe aux bons créneaux du planning.",
              "La capacité maximale signale quand le groupe est plein. La tranche d'âge aide à orienter chaque adhérent vers le bon groupe.",
              "Un groupe archivé n'est plus proposé pour de nouvelles séances mais reste dans l'historique.",
            ])}

            ${helpSection("help-coachs", "Coachs", [
              "La page Coachs regroupe les encadrants du club : entraîneurs, bénévoles, salariés ou intervenants extérieurs.",
              "Le bouton Nouveau coach crée une fiche avec nom, prénom, e-mail, téléphone, type et qualification.",
              "Les spécialités indiquent les disciplines que le coach peut encadrer. Elles servent à proposer le bon coach dans le planning.",
              "Les disponibilités décrivent les créneaux habituels du coach. Les indisponibilités ponctuelles signalent une absence sur une date précise.",
              "Quand une indisponibilité ou un archivage touche une séance déjà planifiée, le coach apparaît comme coach à remplacer dans À faire.",
              "Un coach archivé n'est plus proposé pour de nouvelles séances mais reste dans les fiches et l'historique. L'option Afficher archivés permet de le retrouver.",
              "Le bouton e-mail prépare un message au coach avec son adresse déjà remplie, à partir des modèles coach configurés dans Paramètres > Messages e-mail.",
              "Le tarif horaire du coach reste informatif : il n'est jamais compté tout seul. Pour le comptabiliser, il faut cocher Comptabiliser comme dépense dans sa fiche, puis créer la dépense avec le bouton dédié (voir Comptabilité).",
            ])}

            ${helpSection("help-salles", "Salles", [
              "La page Salles regroupe les lieux d'entraînement : dojo, gymnase, salle polyvalente, terrain extérieur, etc.",
              "Le bouton Nouvelle salle crée une fiche avec le nom, le type, la capacité, la surface, le matériel et les disciplines compatibles.",
              "Le responsable de salle (nom, e-mail, téléphone) sert à prévenir la personne en charge du lieu, par exemple la mairie ou un gestionnaire.",
              "Les disponibilités décrivent les créneaux d'ouverture habituels. Les indisponibilités ponctuelles signalent une fermeture sur une date précise.",
              "Quand une indisponibilité ou un archivage touche une séance déjà planifiée, la salle apparaît comme salle à remplacer dans À faire.",
              "Une salle archivée n'est plus proposée pour de nouvelles séances mais reste dans les fiches et l'historique. L'option Afficher archivés permet de la retrouver.",
              "Le bouton e-mail prépare un message au responsable de la salle, à partir des modèles salle configurés dans Paramètres > Messages e-mail.",
              "Le tarif de la salle reste informatif : il n'est jamais compté tout seul. Pour le comptabiliser, il faut cocher Comptabiliser comme dépense dans sa fiche, puis créer la dépense avec le bouton dédié (voir Comptabilité).",
            ])}

            ${helpSection("help-planning", "Planning", [
              "Le planning est hebdomadaire : chaque créneau (nom, discipline, jour, horaires, coach, salle) est récurrent, il revient automatiquement sans avoir à le recréer.",
              "Récurrence : on choisit d'abord un type. Hebdomadaire = toutes les semaines (défaut), ou toutes les 2, 3 ou 4 semaines, avec un « Premier cours » qui fixe la phase. Mensuelle = soit la même position (1er lundi, 3e samedi, dernier vendredi… le jour vient du champ Jour), soit la même date (le 15 de chaque mois, clampé au dernier jour pour les mois courts).",
              "Le créneau n'apparaît que les bonnes semaines / dates ; les conflits, les remplacements (À faire) et les présences ne tiennent compte que des séances qui ont réellement lieu.",
              "Dans une séance, le coach se choisit dans une liste filtrée selon la discipline et ses spécialités (ou un coach marqué « polyvalent »). On n'affecte que des coachs déclarés dans la page Coachs.",
              "La salle se choisit dans une liste filtrée selon les disciplines compatibles ; les salles indisponibles sur ce créneau sont signalées. Une saisie libre du lieu reste possible.",
              "Le logiciel détecte les conflits : un même coach ou une même salle utilisé sur des horaires qui se chevauchent. Ces conflits apparaissent dans À faire.",
              "Quand un coach ou une salle devient indisponible (absence ponctuelle ou archivage), les séances concernées sont signalées comme à remplacer dans À faire.",
              "Depuis une alerte à remplacer, on peut désigner un remplaçant, annuler la séance ou prévenir le coach ou le responsable de salle par e-mail.",
              "Modifier une seule date : sur chaque séance affichée, le bouton « 📅 Modifier cette date » crée une exception ponctuelle au planning hebdomadaire. Pour ce jour précis seulement, on peut annuler la séance, changer l'horaire, le coach ou la salle, ou ajouter une note — sans jamais toucher au créneau récurrent.",
              "Pour rester lisible, le planning signale une séance exceptionnelle par un badge discret (« ✏️ Modifiée », « ⛔ Annulé »). Le détail complet « Habituel → Cette date » (horaire, coach, salle) s'affiche dans la fiche de la séance quand on l'ouvre, où l'on voit aussi les valeurs réellement appliquées ce jour-là.",
            ])}

            ${helpSection("help-disponibilites", "Centre des disponibilités", [
              "Le Centre des disponibilités est un assistant de création de cours hebdomadaires : il répond à la question « quand puis-je placer un nouveau cours ? » sans avoir à tester les horaires un par un dans le planning.",
              "Tu décris le cours souhaité — discipline, coach, salle, groupe et durée, tout est facultatif — et le logiciel cherche les créneaux où c'est réellement possible.",
              "MonGestaClub croise automatiquement les disponibilités des coachs et des salles, les groupes déjà occupés, les cours déjà programmés et les conflits, puis met en avant le meilleur créneau, indique les meilleurs jours et les périodes à éviter.",
              "Il ne tient compte que des modules activés pour le club : si les coachs, les salles ou les groupes ne sont pas utilisés, il n'en parle pas.",
              "Quand un créneau convient, « Créer ce cours » ouvre le formulaire du planning déjà prérempli : jour, horaires, discipline et groupe, et même le coach ou la salle lorsqu'un seul est disponible à ce moment-là.",
              "C'est plus sûr qu'une création directe dans le planning : le créneau proposé est déjà vérifié sans conflit, alors qu'une création manuelle peut chevaucher un coach, une salle ou un groupe déjà pris.",
              "Cette page est un outil d'aide à la décision : elle ne modifie rien tant que tu n'as pas créé un cours, et elle n'a pas vocation à être imprimée ou exportée.",
              "Dans la grille, chaque niveau de disponibilité a aussi son propre motif (hachures plus ou moins denses, bordure pointillée), en plus de la couleur : les niveaux restent reconnaissables même si les couleurs sont difficiles à distinguer.",
            ])}

            ${helpSection("help-presences", "Présences", [
              "La page Présences sert à faire l'appel : une feuille de présence est toujours liée à un groupe et à une date.",
              "Le bouton Nouvelle feuille d'appel crée une feuille vide à remplir. Depuis une séance du Planning, un bouton dédié ouvre directement l'appel pour ce groupe, cette date et ce coach déjà préremplis.",
              "Pour chaque adhérent du groupe, on choisit un statut : Présent, Retard, Absent, Excusé, Blessé ou Essai. Une remarque libre peut être ajoutée par personne.",
              "Le bouton Imprimer sort la feuille de présence telle qu'elle est affichée à l'écran, y compris les statuts pas encore enregistrés.",
              "La page garde toutes les feuilles déjà enregistrées dans le tableau Séances : cliquer sur une ligne rouvre cette feuille pour la consulter ou la corriger.",
              "En haut de la page, Assiduité par groupe indique le taux de présence de chaque groupe. Assiduité par adhérent détaille présences, absences, retards et taux pour chaque personne ayant déjà été appelée au moins une fois.",
            ])}

            ${helpSection("help-documents", "Documents sportifs", [
              "La page Documents sportifs est une synthèse en lecture seule : elle rassemble, pour chaque inscription, l'état des documents administratifs et sportifs. Cliquer sur une ligne ouvre la fiche d'inscription pour corriger un document.",
              "Les documents suivis sont : le numéro et la date de fin de licence fédérale, la date de fin du certificat médical, et l'assurance choisie pour l'inscription.",
              "L'autorisation parentale, le droit à l'image et le règlement signé sont aussi affichés : ces informations sont enregistrées une seule fois sur la fiche contact de la personne, pas séparément sur chacune de ses inscriptions.",
              "L'autorisation parentale n'est demandée et affichée que pour les adhérents mineurs, repérés par un badge Mineur à côté de leur nom.",
              "Chaque document a un badge de statut : OK, Manquant, Expiré ou Expire bientôt selon la date de fin renseignée.",
              "En haut de la page, des compteurs résument le nombre de dossiers complets, de documents manquants, expirés, qui expirent bientôt, et d'assurances encore à vérifier.",
              "Les boutons de filtre permettent d'afficher uniquement les dossiers qui correspondent à un cas précis : documents OK, manquants, expirés, expire bientôt, mineurs incomplets, licence manquante, certificat manquant ou assurance à vérifier.",
            ])}

            ${helpSection("help-paiements", "Paiements et statuts", [
              "Les champs numériques du logiciel utilisent des boutons − et + séparés : le nombre reste visible dans la case et les boutons évitent les clics accidentels sur la mauvaise flèche.",
              "Les boutons − et + incrémentent toujours de 1 (1 €, 1 unité). Pour une valeur au centime près, on tape directement le montant au clavier (ex. 19,50).",
              "Quand une remise réduit le total à payer, les paiements déjà saisis sont ajustés automatiquement pour ne jamais dépasser le nouveau total : le reste à payer suit le total, sans fausse alerte de dépassement.",
              "Chaque paiement utilise un tiroir compact avec un menu Mode alimenté par les modes acceptés dans le club actif.",
              "Dans Paramètres > Paiement en plusieurs fois, on choisit le nombre maximum de paiements proposés, de 1 à 5 maximum.",
              "Le logiciel affiche d'abord le paiement 1. Si son montant ne couvre pas tout, le paiement 2 apparaît automatiquement, déjà prérempli avec le reste à payer, puis les suivants jusqu'à la limite choisie.",
              "Un paiement marqué Refusé n'est pas compté comme encaissé : le reste à payer est aussitôt reporté sur la ligne suivante.",
              "Pour chaque ligne, le menu Mode peut proposer espèces, chèque, carte bancaire, virement, coupons sport, chèques vacances ou autre selon les paramètres du club.",
              "Pour les chèques, on peut renseigner le numéro du chèque et une date d'encaissement.",
              "Pour un paiement autre que par chèque (espèces, carte, virement…), la date « Payé le » s'enregistre automatiquement au clic sur Payer : le paiement est considéré comme encaissé immédiatement, donc aucune alerte d'encaissement n'est créée. Seuls les chèques peuvent avoir une date d'encaissement à venir.",
              "Si le dernier paiement autorisé est affiché, il doit couvrir toute la somme restante. Sinon, la validation est refusée avec un message.",
              "Le résumé affiche les montants et statuts des paiements visibles. On ouvre le tiroir uniquement pour modifier le détail.",
              "Pour chaque paiement, on peut saisir le mode et le montant. Pour un chèque, on peut aussi saisir la date d'encaissement et le statut Refusé.",
              "La TVA n'est pas affichée dans le mini-formulaire de paiement : elle vient des tarifs ou du taux global configuré.",
              "Les montants saisis sont considérés TTC. La TVA est isolée automatiquement en Comptabilité pour obtenir le montant HT.",
              "Le statut Payé compte dans le montant réglé. Les autres statuts ne comptent pas comme encaissés.",
              "Si une date est passée, le statut calculé devient À encaisser. Si la date est future, il devient En cours.",
              "Le reste dû est toujours calculé ainsi : total attendu - paiements marqués Payé.",
              "Le bouton Payer marque immédiatement le paiement affiché comme Payé quand le montant est correct.",
              "Si un paiement est déjà marqué Payé, le bouton devient Annuler paiement pour enlever la validation sans supprimer la ligne.",
            ])}

            ${helpSection("help-couleurs", "Codes couleurs", [
              "Vert signifie que la fiche ou le module est réglé : il n'y a plus de reste dû.",
              "Rouge signifie qu'il reste de l'argent à payer, qu'un paiement est refusé, ou que le stock est passé en négatif.",
              "Orange signifie qu'un paiement est en cours ou qu'un article a atteint son seuil de stock alerte.",
              "Les informations manquantes, comme e-mail, téléphone, date de naissance, âge ou certificat, sont affichées dans une pastille rouge très pâle pour les repérer discrètement sans les confondre avec les informations complètes.",
              `Dans Contacts, Disciplines${stagesEnabled ? " et Stages" : ""}, la couleur se trouve sur la bordure gauche de la fiche ou de la ligne compacte.`,
              `Dans les fiches contacts, les boutons${boutiqueEnabled ? " Boutique," : ""} Disciplines${stagesEnabled ? " et Stages" : ""} passent en vert, orange ou rouge selon l'état réel des paiements du module.`,
              "Dans Stock, une ligne d'article orange indique que l'article est arrivé au seuil d'alerte. Une ligne rouge indique que le stock disponible est négatif.",
              "Dans Accueil, les articles du bloc Stock à surveiller reprennent les mêmes couleurs et ouvrent directement la fiche de l'article.",
              "Les pastilles de statut indiquent le détail : Payé, En cours, À encaisser, À payer, Refusé, OK ou Stock négatif selon le contexte.",
            ])}

            ${boutiqueEnabled ? helpSection("help-boutique", "Boutique", [
              "La boutique sert à créer des ventes pour un adhérent ou pour un non adhérent.",
              "En arrivant sur Boutique, les articles disponibles sont affichés. On choisit d'abord l'article, puis la taille et la quantité, puis le client et le paiement.",
              "Un article peut avoir plusieurs photos. Les miniatures permettent de choisir l'image à afficher en grand, et les flèches permettent de passer d'une image à l'autre.",
              "Le bloc Boutique en un coup d'oeil est replié par défaut pour garder les chiffres discrets. Cliquer sur sa ligne l'affiche ou le masque.",
              "Dans Boutique en un coup d'oeil, cliquer sur Reste dû ouvre la liste des clients qui doivent encore quelque chose.",
              "Sous Articles à vendre, les rubriques Encaissements boutique, Articles vendus, Commandes clients et Ventes par article sont des lignes repliables.",
              "Cliquer sur une ligne de rubrique boutique l'ouvre. Recliquer dessus la referme.",
              "Dans Nouvelle commande, sélectionner un client enregistré remplit automatiquement ses coordonnées.",
              "Si aucun client n'est sélectionné, la vente libre crée ou met à jour un contact Non adhérent.",
              "Une commande affiche seulement les articles achetés par le client, avec les tailles et quantités sélectionnées.",
              "Dans Nouvelle commande, le résumé affiche aussi les articles, tailles et quantités avant l'enregistrement.",
              "Les quantités se règlent avec les boutons − et + placés côte à côte. Le chiffre reste aligné à gauche pour rester lisible dans tous les thèmes.",
              "Le prix de vente affiché dans la commande est verrouillé : il reprend le tarif défini dans la page Tarifs et ne se modifie pas à la main. Pour accorder une réduction, saisis un montant dans le champ Remise commande de l'étape paiement.",
              "La Remise commande est déduite du total à payer et apparaît comme une ligne dédiée sur la facture.",
              "Les quantités et tailles se modifient seulement sur les articles présents dans la commande.",
              "Le champ quantité reste normal si le stock est suffisant, devient orange si le stock restant passe sous le seuil d'alerte, et rouge si la quantité dépasse le stock disponible.",
              "Mettre la quantité d'un article à zéro ou utiliser la croix retire l'article de la commande.",
              "La fiche commande affiche le total, le réglé, le reste dû, les articles achetés et les paiements.",
            ]) : ""}

            ${boutiqueEnabled ? helpSection("help-stock", "Stock", [
              "La page Stock contient les articles de boutique, leurs références, tailles, prix de vente, prix d'achat et quantités.",
              "Stock est rangé sous Boutique dans le menu principal.",
              "Les quantités de stock, avec ou sans tailles, utilisent les mêmes boutons − et + séparés que le reste du logiciel.",
              "Les blocs Articles et stock et Mouvements boutique se déplient en cliquant sur leur ligne de titre.",
              "Le seuil d'alerte est directement dans Articles et stock, sur la ligne de chaque article.",
              "En stock correspond à la quantité réelle disponible. Les ventes boutique diminuent automatiquement le disponible.",
              "Pour un article sans taille, le stock se règle avec un simple compteur. Le formulaire de tailles n'apparaît pas tout seul pour éviter de créer des tailles par erreur.",
              "Dans Articles et stock, un article sans taille affiche ce compteur et un bouton + tailles si tu veux passer volontairement en gestion par tailles.",
              "Pour un article avec tailles, En stock total est calculé automatiquement : il faut saisir les quantités dans le bloc Tailles pour savoir combien il y a de S, M, L, XL, etc.",
              "Chaque taille ajoutée doit avoir un nom, et deux tailles ne peuvent pas porter le même nom : le logiciel le vérifie avant d'enregistrer pour éviter les saisies vides ou en double.",
              "Dans la fiche article, le bloc Images fonctionne comme une petite bibliothèque photo : grande prévisualisation, miniatures cliquables, légende modifiable pour chaque image et suppression photo par photo.",
              "Dans Images, les boutons 1, ↑ et ↓ permettent de choisir l'ordre des photos. L'image placée en première devient la vignette principale de l'article.",
              "Quand on sélectionne de nouvelles images, elles apparaissent immédiatement dans Images à ajouter avec un champ Légende pour chaque photo, avant de cliquer sur Enregistrer.",
              "La galerie est volontairement compacte pour voir l'image principale, les miniatures et la navigation sans devoir descendre dans la fenêtre.",
              "La première photo de la galerie sert de vignette dans Stock, Boutique et les commandes.",
              "Total achat correspond à la valeur d'achat du stock restant : quantité disponible x prix d'achat.",
              "Total vendu correspond au chiffre généré par les ventes de l'article.",
              "Stock alerte indique le seuil à partir duquel l'article apparaît dans les alertes de stock.",
              "Quand le seuil est atteint, la ligne devient orange. Quand le stock est négatif, la ligne devient rouge.",
              "La colonne Seuil d'alerte dans Articles et stock permet de modifier directement le niveau d'alerte de chaque article.",
              "Depuis l'accueil, cliquer sur un article dans Stock à surveiller ouvre directement la fiche de l'article.",
              "Les mouvements boutique montrent les sorties de stock liées aux commandes.",
            ]) : ""}

            ${stagesEnabled ? helpSection("help-stages", "Stages", [
              "La page Stages permet de gérer les participants aux stages et, si besoin, l'hébergement.",
              "Le bloc Stages en un coup d'oeil est replié par défaut. Cliquer sur sa ligne affiche les chiffres du stage sélectionné.",
              "Le bouton Nouveau stage crée un stage uniquement quand on en a besoin.",
              "Modifier le stage permet de changer son nom, ses dates, sa date limite d'inscription, son tarif et l'hébergement du stage sélectionné.",
              "Quand la date de fin ou la date limite d'inscription est passée, le stage est grisé et les nouvelles inscriptions sont stoppées.",
              "Les paiements, refus, restes dus, statistiques et comptabilité d'un stage passé restent conservés et modifiables.",
              "Le bouton Réactiver inscriptions permet d'ajouter exceptionnellement un participant après la fermeture du stage.",
              "Chaque stage possède un réglage Public autorisé : adhérents uniquement, non adhérents uniquement, ou adhérents et non adhérents.",
              "Depuis la fiche d'un non adhérent, le bouton Stages propose uniquement les stages ouverts aux non adhérents et ne transforme pas le contact en adhérent.",
              "Le bouton Relancer ce stage crée une nouvelle session du même stage avec les mêmes tarifs, mais avec de nouvelles dates et sans participants.",
              "Supprimer stage vide retire un stage sans participant. Un stage avec des inscriptions doit d'abord être vidé.",
              "Les prix du stage et de l'hébergement restent repris dans Tarifs pour les calculs, mais la création courante se fait directement depuis Stages.",
              "Un participant peut être lié à un adhérent, à un non adhérent, ou être créé directement depuis le formulaire.",
              "Nom, prénom, téléphone, e-mail, adresse, code postal et ville sont obligatoires pour enregistrer une inscription stage.",
              "Le code postal et la ville se complètent automatiquement dans la fiche stage quand Internet est disponible.",
              "Les participants sont présentés en lignes compactes, avec un filtrage alphabétique pour aller vite sur une lettre.",
              "Dans Stages en un coup d'oeil, cliquer sur Reste dû ouvre la liste des participants du stage sélectionné avec un paiement à régulariser.",
              "Cliquer sur la ligne d'un participant ouvre sa fiche de stage.",
              "Dans la fiche d'un participant déjà enregistré, le bouton Supprimer ce participant permet de le retirer du stage.",
              "Dans la fiche participant, Nombre, Prix U et Remise sont regroupés sur une même ligne pour le stage, et pareil pour l'hébergement.",
              "Le Prix U est verrouillé : il reprend automatiquement le tarif défini dans la page Tarifs et ne se modifie pas à la main. Pour accorder un geste commercial, utilise le champ Remise.",
              "Les paiements du stage et de l'hébergement sont séparés pour garder une lecture claire, et chacun peut être réglé en plusieurs fois indépendamment.",
              "En bas de la fiche, une ligne Total inscription récapitule le stage, l'hébergement et leur somme dès qu'un montant de stage est saisi.",
            ]) : ""}

            ${helpSection("help-tarifs", "Tarifs", [
              "La page Tarifs est la base de calcul du logiciel.",
              "Le bloc TVA actuelle définit le taux global appliqué automatiquement dans les paiements.",
              "Dans les lignes de tarifs, la colonne TVA peut rester vide pour utiliser la TVA globale, ou contenir un taux spécifique pour l'article, la discipline, le stage, l'hébergement ou l'assurance.",
              "Disciplines : nom, tarif et licence.",
              "Assurances : catégorie, libellé et montants disponibles.",
              "Stages : nom du stage, prix stage, TVA stage, investissement stage, hébergement, prix hébergement et TVA hébergement.",
              "Articles : nom, prix de vente et prix d'achat.",
              "Les lignes de tarifs sont en lecture simple. Cliquer sur une ligne la rend éditable, puis la petite coche valide la ligne.",
              "Au survol d'une ligne de tarif, l'infobulle indique que la ligne peut être éditée.",
              "Les modifications d'une ligne Tarif ne sont enregistrées que si la coche est cliquée. Cliquer ailleurs ou sur une autre ligne annule le brouillon en cours.",
              "Toute modification de tarif ou de TVA impacte les prochains calculs affichés dans les formulaires concernés.",
              "Renommer une discipline met à jour les inscriptions liées. Changer un prix article ou stage met à jour les ventes ou inscriptions liées.",
            ])}

            ${helpSection("help-parametres", "Paramètres", [
              "La page Paramètres regroupe les réglages généraux du logiciel : apparence, logo, données et licence.",
              "Les rubriques de Paramètres sont repliées comme dans Tarifs. Cliquer sur une ligne ouvre la rubrique, recliquer la referme.",
              "Les polices proposées par le logiciel sont embarquées localement : elles restent disponibles sans connexion Internet.",
              "La rubrique Polices permet de choisir séparément les polices des titres, du texte, des boutons et des menus. Par défaut : Lobster pour les titres, Inter pour le texte, Poppins pour les boutons et Ubuntu pour les menus.",
              "Le bouton Réinitialiser les polices par défaut remet immédiatement ces polices, la taille normale et l'épaisseur normale.",
              "La rubrique Post-it À faire permet de choisir la couleur et le modèle d'image des alertes : paiement en retard, à encaisser, stock faible, certificat, assurance et anniversaire.",
              "Quand on change une couleur ou un modèle de post-it, l'aperçu se met à jour tout de suite. La couleur reste dans la forme du post-it, sans fond coloré derrière l'image.",
              "À la première utilisation, le logiciel démarre avec le thème Graphite clair. Les thèmes permettent ensuite de changer l'ambiance visuelle du logiciel.",
              "Chaque carte de thème propose Choisir pour l'appliquer et Personnaliser ce thème pour ouvrir une fenêtre dédiée aux couleurs.",
              "La personnalisation d'un thème affiche une mini-interface à gauche et les couleurs modifiables à droite. Il faut cliquer sur les pastilles colorées pour changer une couleur.",
              "Dans la personnalisation, le bouton Origine de chaque ligne remet seulement cette couleur, sans annuler les autres couleurs déjà choisies.",
              "Les couleurs Bordure fine et Bordure forte règlent les contours des fenêtres, boutons, champs et séparations.",
              "Chaque couleur indique à quoi elle sert, et l'aperçu affiche aussi toutes les couleurs du thème pour voir immédiatement ce qui change.",
              "Les changements de couleur restent en brouillon tant que Enregistrer n'est pas cliqué. Annuler ou fermer la fenêtre remet les anciennes couleurs.",
              "Changer de thème ne modifie aucune donnée du club. Cela change uniquement les couleurs, les arrondis, les fonds et l'apparence générale.",
              "Le thème Contraste élevé renforce les écarts de couleur pour une meilleure lisibilité. Il fonctionne comme les autres thèmes : Choisir pour l'appliquer, sans modifier aucune donnée du club.",
              "Le bloc Affichage contient des cases à cocher pour ajouter ou retirer le texte sous les icônes de la barre du haut, et pour afficher ou masquer certaines pages comme Accueil, E-mail, Tarifs, Statistiques ou Notes.",
              "Le bloc Affichage propose aussi trois modes d'interface : Simple (menu allégé pour les petits clubs), Avancé (tous les modules visibles) et Personnalisé (choisir précisément les pages visibles). Changer de mode ne supprime aucune donnée : seules des entrées du menu sont masquées, et les vues masquées restent fonctionnelles. Un nouveau club démarre en mode Simple ; le club de démonstration démarre en mode Avancé pour montrer tout de suite l'ensemble des fonctions.",
              "Une puce en bas du menu indique le mode courant (Mode simple, Mode avancé ou Mode personnalisé). Cliquer dessus ouvre directement Paramètres > Affichage pour changer de mode.",
              "Le réglage Disposition (dans Affichage) choisit la mise en page générale : Moderne place le menu principal à gauche (l'affichage par défaut, inchangé) ; Classique le transforme en une barre de menus en haut du logiciel, avec sous-menus déroulants, façon logiciel de bureau. Les deux dispositions donnent accès aux mêmes pages ; on bascule de l'une à l'autre à tout moment, sans rien perdre.",
              "On peut replier le menu et la barre d'outils pour gagner de la place. En disposition Moderne : le bouton ⟨ / ☰ masque ou réaffiche le menu de gauche, et le bouton ⌃ replie la barre du haut (le bouton ⌄ la rouvre). En disposition Classique, le menu fin du haut reste toujours visible : le bouton ⌃ replie uniquement la barre d'outils, et le bouton ⌄ Barre d'outils la réaffiche. Ces préférences sont mémorisées d'une session à l'autre.",
              "En mode Personnalisé, décocher une page (Factures, E-mail, Disciplines, Boutique, Stages…) la masque partout où elle apparaît : menu, accueil, fiche contact et exports liés, sans supprimer aucune donnée. Le bloc Affichage permet aussi de désactiver spécifiquement Stages ou Boutique dans les statistiques et la comptabilité.",
              "Le bloc Ordre du menu permet de personnaliser le menu principal (à gauche en Moderne, en haut en Classique) : réordonne les éléments du menu et de ses sous-menus (Paramètres, Boutique) en les faisant glisser ou avec les flèches.",
              "Dans Ordre du menu, on peut aussi déplacer un élément d'un groupe à l'autre : sortir une entrée du sous-menu Paramètres vers le menu principal, ou inversement, par glisser-déposer ou avec le bouton ⇄. Le bouton Ordre par défaut remet la navigation d'origine.",
              "Le bouton + Créer un menu ajoute un menu personnalisé : donne-lui un nom et choisis une icône dans la liste proposée, puis fais glisser dedans les entrées de ton choix pour les transformer en sous-menu. Ce menu apparaît dans le menu principal (à gauche en Moderne, en haut en Classique) et se déplie au clic, comme Boutique ou Paramètres.",
              "Le bouton 🎨 sur chaque entrée (menus personnalisés comme menus d'origine) permet de changer son icône parmi une bibliothèque au même style. L'option Auto remet l'icône d'origine. Le bouton Ordre par défaut réinitialise aussi les icônes.",
              "Un menu personnalisé peut être renommé (✎) ou supprimé (×) ; à la suppression, ses entrées reviennent dans le menu principal. Le bouton Ordre par défaut supprime aussi les menus personnalisés.",
              "À la création ou la modification d'un menu personnalisé, on peut cocher Menu protégé : ses pages demanderont alors le mot de passe du logiciel avant de s'afficher. Il faut qu'un mot de passe du logiciel soit défini dans Paramètres > Sécurité. Le menu reste déverrouillé tant qu'on circule dedans, et se reverrouille dès qu'on en sort.",
              "Par défaut, la page Tarifs est placée dans un menu protégé « Tarifs ». La protection des Tarifs dépend donc de ce menu : pour la retirer, il suffit de décocher Menu protégé sur ce menu (ou d'en sortir la page Tarifs). C'est un menu personnalisé comme un autre, qu'on peut renommer, déplacer ou compléter.",
              "Le bloc Paiement en plusieurs fois permet de choisir combien de paiements maximum sont proposés dans les formulaires, avec une limite à 5.",
              "Le bloc Sécurité permet de créer ou changer le mot de passe du logiciel.",
              "Ce mot de passe est demandé à l'ouverture du logiciel et avant chaque vidage de données.",
              "Le mot de passe n'est pas enregistré en clair : le logiciel garde seulement une empreinte sécurisée.",
              "Le bloc Logo permet de remplacer le logo affiché dans le menu principal, dans la fenêtre A propos et dans l'icône de page.",
              "Pour garder un logo détouré, il faut utiliser une image PNG avec transparence. Le logiciel conserve cette transparence lors du changement de logo et au premier démarrage.",
              "Le bouton Appliquer à l'icône Mac tente aussi d'utiliser ce logo pour l'icône de l'application. Sur Mac, il peut falloir redémarrer l'application. Sur Windows, l'icône visible du .exe ne changera pas.",
              "Le bloc Messages e-mail permet de modifier les textes préparés par le logiciel : relance de paiement, e-mail simple à un contact et newsletter.",
              "Dans Messages e-mail, un sélecteur affiche un seul modèle à la fois. Cliquer sur Modifier déverrouille le brouillon, Enregistrer applique la nouvelle version, Annuler revient à la configuration enregistrée.",
              "Les variables automatiques entre accolades viennent du logiciel : contact, club, paiement, facture ou date utile.",
              "Les variables personnalisables comme {detail}, {message}, {note}, {titre}, {complement} et {signatureLibre} se remplissent dans le bloc Variables personnalisables du modèle.",
              "Chaque club garde ses propres modèles et ses propres textes personnalisés.",
              "Dans Messages e-mail, les zones Modifiable et Automatique expliquent ce que l'utilisateur peut changer et ce qu'il vaut mieux laisser sous forme de variable.",
              "La demande de licence reste séparée : elle se trouve uniquement dans le bloc Licence, avec le bouton Demander par email.",
              "Le club de démonstration se crée depuis Mes clubs avec le bouton Créer un club démo. Il ajoute des données fictives dans un club séparé pour tester le logiciel.",
              "Le bouton Réinitialiser le club démo recrée uniquement ce club de démonstration. Les autres clubs ne sont pas supprimés.",
              "Le bloc Données affiche directement les boutons de réinitialisation : tout vider, vider seulement boutique, stages, disciplines, adhérents, non adhérents, stats, notes ou comptabilité.",
              "Tout vider remet réellement la base à zéro. Les autres boutons vident uniquement la catégorie concernée.",
              "Chaque réinitialisation demande une confirmation, rappelle d'exporter une sauvegarde JSON, puis redemande le mot de passe du logiciel avant suppression.",
              "Le bloc Licence affiche l'état du logiciel : essai gratuit, nombre de jours restants, licence activée ou activation requise.",
              "Pendant l'essai, le logiciel fonctionne normalement pendant 30 jours.",
              "Pour activer le logiciel, l'utilisateur copie l'identifiant ordinateur affiché dans Paramètres > Licence et te l'envoie après paiement.",
              `Le bouton Demander par email prépare automatiquement un message adressé à ${APP_INFO.emails.licence} avec l'identifiant ordinateur déjà renseigné.`,
              `Si l'email automatique ne s'ouvre pas, l'utilisateur peut envoyer lui-même un email à ${APP_INFO.emails.licence} en indiquant son identifiant ordinateur.`,
              "Tu génères ensuite son numéro de série avec ton outil Admin licences, que tu gardes uniquement pour toi, puis tu lui envoies le numéro.",
              "L'utilisateur colle le numéro de série dans Paramètres > Licence et clique sur Activer.",
              "Le numéro de série est lié à l'ordinateur du client. Il ne doit pas fonctionner sur un autre ordinateur.",
              "L'application client ne contient pas le générateur de licence. Elle sait seulement vérifier un numéro de série valide.",
              "La version installée vérifie aussi l'intégrité de ses fichiers sensibles au démarrage. Si l'application a été modifiée, elle demande de réinstaller une version officielle.",
              "Dans l'application installée, le correcteur orthographique français fonctionne dans les champs texte. Un clic droit sur un mot propose les corrections, tout en gardant Couper, Copier, Coller et Tout sélectionner.",
              "Les crédits, licences et ressources tierces sont accessibles depuis le menu Aide > Licences et ressources tierces. La fenêtre À propos reste volontairement courte.",
            ])}

            ${helpSection("help-utilisateurs", "Utilisateurs", [
              "Dans Paramètres > Utilisateurs, chaque profil permet de distinguer qui utilise le logiciel sur cet ordinateur : ce n'est pas le club, c'est la personne installée devant l'écran. Le club actif (voir Mes clubs) reste un réglage séparé : un même utilisateur peut travailler sur plusieurs clubs, et un même club peut être ouvert par plusieurs utilisateurs.",
              "Le bouton Créer un utilisateur ajoute un nouveau profil, avec un nom modifiable à tout moment (bouton Renommer).",
              "Un utilisateur peut être ajouté à un ou plusieurs clubs. Pour chaque club, on lui attribue un rôle (Administrateur, Président, Secrétaire, Trésorier, Encadrant ou Lecture seule) : ce rôle est aujourd'hui uniquement informatif, il prépare un futur système de droits mais ne restreint encore aucune action.",
              "Le sélecteur d'utilisateur (barre latérale) permet de changer de profil actif sans fermer le logiciel.",
              "Un utilisateur désactivé n'apparaît plus dans le sélecteur mais reste visible dans Paramètres > Utilisateurs, avec un bouton Réactiver.",
              "Dans la version installée (Mac/Windows), chaque profil peut être protégé par un PIN à 6 chiffres. Dès qu'il existe au moins deux profils sur le poste, un PIN devient obligatoire pour chacun ; avec un seul profil sans PIN, le logiciel s'ouvre directement.",
              "Le PIN protège l'accès à votre profil dans MonGestaClub sur cet ordinateur et aide à garantir que les actions du Journal d'activité sont attribuées à la bonne personne. Chacun configure et change son propre PIN depuis son profil actif (boutons Configurer le PIN / Changer le PIN).",
              "À la création d'un PIN, un code de récupération s'affiche une seule fois : il permet de redéfinir un nouveau PIN en cas d'oubli. Il faut le noter et le conserver en lieu sûr, en dehors de l'application.",
              "Cette protection par PIN n'existe que dans la version installée : dans un navigateur (par exemple la démo en ligne), les profils fonctionnent sans PIN.",
            ])}

            ${helpSection("help-notes", "Notes", [
              "MonGestaClub propose deux façons complémentaires de garder une information par écrit : les Notes (texte riche, pour rédiger librement) et les Notes personnalisées (petites fiches courtes, avec une page de destination). Les deux se retrouvent sur la page Notes.",
              "Les Notes sont un éditeur de texte libre, présenté sous forme d'onglets : une note par onglet, avec son propre titre.",
              "La barre d'édition d'une note permet de choisir la police, la taille, la couleur, le surlignage, le gras, l'italique, le souligné, le barré, l'alignement et les listes.",
              "Les polices disponibles dans Notes suivent les mêmes choix que la personnalisation des polices dans Paramètres.",
              "Le bouton + Note crée un nouvel onglet. Supprimer l'onglet retire la note active. Si la dernière note est supprimée, une nouvelle note vide est automatiquement créée pour rester prêt à écrire.",
              "Les Notes sont enregistrées automatiquement, et le bouton Enregistrer confirme la sauvegarde. Exporter PDF depuis Notes crée un PDF propre avec seulement le titre et le contenu de la note active. Exporter CSV exporte les titres et le texte brut de toutes les notes.",
              "Plus bas sur la même page, le tableau Notes personnalisées sert à de courts pense-bêtes, avec quatre colonnes : Afficher dans, Sujet, Note et Priorité.",
              "Afficher dans choisit où la note doit aussi apparaître, en plus de la page Notes. Laissé sur Notes uniquement, la note ne vit que dans ce tableau. En choisissant une page (par exemple Stock, Paiements dus ou Planning), la même note reste dans ce tableau ET apparaît en plus sur cette page, dans un petit bloc « 📌 Notes ».",
              "Ce ne sont pas deux notes différentes : c'est la même Note personnalisée, simplement affichée à un deuxième endroit utile. Depuis ce bloc sur la page cible, on peut directement la modifier (sujet, note, priorité, destination) ou la supprimer, sans repasser par la page Notes.",
              "La Priorité (Normale, Important, Urgent ou Archive) sert à trier ces notes. Sur une page cible, les notes urgentes s'affichent en premier, puis les importantes, puis les normales.",
              "Mettre une note en priorité Archive ne la supprime pas : elle reste dans le tableau Notes personnalisées, garde sa destination enregistrée, mais n'apparaît plus dans le petit bloc de la page cible. C'est une façon de la ranger sans perdre l'historique.",
            ])}

            ${helpSection("help-stats", "Statistiques", [
              `La page Statistiques regroupe l'utilisation des disciplines${stagesEnabled ? ", des stages" : ""}${boutiqueEnabled ? " et de la boutique" : ""}.`,
              "Elle permet de voir les volumes, les montants attendus, les montants réglés et les restes dus.",
              "Les blocs en haut se lisent comme des synthèses rapides et les totaux de colonnes sont affichés en bas des tableaux.",
              boutiqueEnabled ? "Les statistiques boutique affichent le nombre d'articles en boutique, les ventes par article, le nombre de commandes, le stock restant et le total vendu." : "",
              stagesEnabled ? "Les statistiques stages affichent les participants, recettes, hébergements et restes dus par stage." : "",
              "Les chiffres des graphiques affichent les nombres plutôt que les pourcentages pour rester lisibles.",
              "Les graphiques circulaires du bas ont deux boutons : Prix pour répartir par montant, Quantités pour répartir par nombre d'adhérents, participants ou articles vendus.",
              "Le bloc Coachs & salles résume l'encadrement : coachs actifs, coachs archivés, coachs à remplacer, coachs sans e-mail, salles actives, salles archivées, salles à remplacer et responsables de salles sans e-mail.",
              "Dans ce bloc, à remplacer compte les coachs ou salles distincts ayant au moins une séance en attente de remplacement, et sans e-mail ne compte que les fiches actives.",
              "Le bloc Synthèse comptable reprend les mêmes chiffres que la page Comptabilité : recettes custom, dépenses saisies, remboursements, avoirs actifs et solde corrigé. Aucun calcul n'est refait ici.",
            ].filter(Boolean))}

            ${helpSection("help-compta", "Comptabilité", [
              "La Comptabilité propose deux lectures, via la bascule en haut de la page : la Vue simple affiche quatre chiffres clés — Encaissé, Dépensé, Reste dû et Résultat (Résultat = Encaissé − Dépensé) — pour comprendre la situation en un coup d'œil ; la Vue détaillée affiche tous les indicateurs ci-dessous. Le choix de vue est mémorisé par club, et en mode d'interface Simple la Comptabilité s'ouvre directement en Vue simple.",
              "La page Comptabilité regroupe les recettes, les investissements, les montants attendus, encaissés, l'argent dehors et le résultat estimé.",
              `La synthèse par activité compare Disciplines${stagesEnabled ? ", Stages" : ""}${boutiqueEnabled ? " et Boutique" : ""} avec total attendu, encaissé TTC, TVA encaissée, encaissé HT, reste dû, achats et résultat.`,
              "La TVA encaissée vient du taux indiqué dans chaque paiement. Avec un taux à 0%, aucune TVA n'est isolée.",
              `Les fiches comptables affichées pour Disciplines${stagesEnabled ? ", Stages" : ""}${boutiqueEnabled ? " et Boutique" : ""} montrent les recettes TTC, la TVA, les recettes HT, l'investissement, le reste dû et le résultat.`,
              "La déclaration fiscale annuelle indicative regroupe par année les paiements marqués Payé : TTC encaissé, TVA collectée, HT à déclarer, recettes HT par activité, investissements connus et résultat indicatif.",
              "Les lignes sans date d'encaissement apparaissent dans Sans date afin d'être corrigées avant contrôle.",
              "Ces montants restent indicatifs : il faut vérifier les comptes, les justificatifs et la situation fiscale du club avant toute déclaration.",
              `L'investissement disciplines correspond aux licences.${stagesEnabled ? " L'investissement stage vient du champ Investissement stage dans Tarifs." : ""}${boutiqueEnabled ? " L'investissement boutique utilise les prix d'achat des articles." : ""}`,
              boutiqueEnabled ? "L'investissement boutique utilise aussi le stock disponible pour estimer la valeur du stock restant." : "",
              boutiqueEnabled ? "Le coût des articles vendus utilise le prix d'achat de chaque article vendu en boutique." : "",
              "Les recettes sources sont l'argent encaissé via les modules déjà comptés : disciplines, stages et boutique. Elles ne passent pas par les factures pour éviter tout double comptage.",
              "Les recettes custom viennent uniquement des factures entièrement personnalisées (don, frais divers, prestation, location ponctuelle…). Une facture liée à une cotisation, un stage ou la boutique n'est jamais recomptée : seule l'encaissement de sa source est compté.",
              "Le module Dépenses enregistre les sorties d'argent manuelles : location de salle, matériel, intervenant, administration, etc. Chaque dépense est datée, classée par catégorie et déduite du Solde caisse.",
              "Les dépenses liées aux coachs et aux salles ne sont jamais automatiques : depuis la fiche, après avoir coché Comptabiliser comme dépense, le bouton dédié crée volontairement une dépense réelle.",
              "Un remboursement est une dépense de catégorie Remboursement : c'est une vraie sortie de caisse, déjà incluse dans le Solde caisse.",
              "Un avoir est une correction comptable rattachée à une facture (réduction, crédit ou annulation). Un avoir actif est déduit du Solde corrigé ; un avoir annulé n'est pas compté.",
              "Un avoir a un statut : actif (utilisable), utilisé (déjà appliqué à un paiement) ou annulé. S'il dépasse le reste dû d'une facture, seule la part nécessaire est utilisée et un nouvel avoir actif est créé automatiquement pour le reliquat.",
              "Depuis sa fiche, un avoir peut être imprimé ou exporté en PDF pour être remis à l'adhérent. Il porte une référence interne (pas un numéro de facture officiel), avec le bénéficiaire, le motif, le statut et le montant.",
              "Le Solde caisse correspond à l'argent réellement disponible : encaissé des sources moins les dépenses saisies. Le Solde corrigé ajoute les recettes custom et retire les avoirs actifs.",
              "Le Résultat estimé est une vue de marge (recettes HT moins achats imputés comme les licences et le prix d'achat boutique). Le Solde caisse est une vue de trésorerie. Ce sont deux lectures différentes : il ne faut pas les additionner.",
              "Pour la catégorie Achat boutique / stock : le prix d'achat saisi dans la boutique sert déjà au calcul de la marge et du stock. Une dépense de cette catégorie sert seulement à enregistrer une vraie sortie de caisse ; il ne faut pas cumuler mentalement les deux comme un seul chiffre.",
              "L'argent dehors liste tous les contacts ou clients pour lesquels il reste quelque chose à payer. Si la liste est longue, la navigation latérale permet de tout parcourir.",
              "Le résultat est une estimation : les frais réels non saisis dans le logiciel ne peuvent pas encore être déduits automatiquement.",
              "Exporter CSV depuis Comptabilité exporte les écritures comptables ligne par ligne.",
            ].filter(Boolean))}

            ${helpSection("help-historique", "Historique", [
              "La page Historique liste les dernières actions importantes enregistrées dans le logiciel, pour le club actif.",
              "Elle permet de voir rapidement ce qui a été modifié : inscription, paiement, stock, note, paramètre ou sauvegarde.",
              "La colonne Action affiche une phrase plus détaillée. Si le texte est trop long, il est coupé avec des points de suspension et un clic sur la ligne l'agrandit.",
              "L'historique garde les actions récentes pour aider à comprendre ce qui vient de changer.",
              "Le bouton Effacer l'historique vide uniquement ce journal. Il ne supprime pas les contacts, paiements, ventes, notes ou autres données du club.",
              "Il ne remplace pas une sauvegarde JSON : il sert surtout de journal de contrôle rapide.",
              "Exporter CSV depuis Historique sort le journal affiché.",
              "Historique est un fil de confort, propre au club et effaçable à tout moment. Pour une trace plus complète et durable, qui n'est jamais effacée, voir Journal d'activité.",
            ])}

            ${helpSection("help-journal", "Journal d'activité", [
              "Le Journal d'activité conserve une trace des actions importantes réalisées dans l'application : qui a fait quoi, quand, et sur quel club.",
              "Contrairement à l'Historique, le Journal d'activité conserve une trace des actions réalisées dans l'application indépendamment du club actif, et il n'existe aucun bouton pour l'effacer : c'est la trace durable, pas un simple fil de confort.",
              "Chaque ligne affiche la date, l'utilisateur, le club concerné, l'action réalisée en une phrase claire, et l'élément concerné (par exemple le nom d'une facture, d'une discipline ou d'un utilisateur).",
              "Le Journal enregistre notamment : la création et la modification des utilisateurs et de leur PIN, la création, la duplication, l'archivage et la suppression de clubs, les changements de réglages du club, le cycle de vie des factures et des paiements, la création et la suppression des stages et de leurs inscriptions, les articles de boutique, ainsi que la création, la modification, l'archivage et l'affectation des disciplines et des catégories sportives.",
              "Le sélecteur Affichage bascule entre Club actif (par défaut) et Tous les clubs, pour retrouver une action même après avoir changé de club.",
              "Si cette page n'apparaît pas dans le menu, active le mode Avancé (ou coche-la spécifiquement en mode Personnalisé) dans Paramètres > Affichage : elle existe toujours et enregistre les actions même quand elle n'est pas affichée.",
            ])}

            ${helpSection("help-donnees", "Sauvegardes et données", [
              "Exporter JSON crée une sauvegarde complète des données du logiciel.",
              "Exporter en PDF crée directement un fichier PDF de données dans l'application installée Mac/Windows. Le PDF reprend les listes et tableaux sans capturer tout le design de l'écran.",
              "La sauvegarde JSON inclut aussi les réglages, le logo et les images d'articles de boutique enregistrées dans le logiciel.",
              "Importer JSON restaure une sauvegarde précédemment exportée.",
              "Exporter CSV exporte uniquement la page active, utile pour retravailler une liste dans un tableur.",
              "Les nombres exportés en CSV sont limités à deux décimales maximum pour garder des tableaux propres.",
              "Dans Paramètres > Données, on peut choisir une date de début et une date de fin de saison.",
              "Archiver la période crée une archive JSON de cette saison sans vider le logiciel.",
              "Archiver puis vider la saison active crée l'archive JSON puis vide les inscriptions, ventes et participations après confirmation par mot de passe.",
              "La sauvegarde automatique de saison peut être activée : quand la date de fin est dépassée, le logiciel prépare une archive JSON une seule fois pour cette période.",
              "Les fichiers CSV sont exportés en UTF-8 compatible avec les tableurs pour conserver les accents : É, À, Ç, ê, etc.",
              "Le logiciel corrige automatiquement les caractères mal encodés quand c'est identifiable, par exemple L&dat devient Lédat et Fran‡aise devient Française.",
              "La réinitialisation, dans Paramètres, vide réellement les données choisies : tout, boutique, stages, disciplines, adhérents, non adhérents, stats, notes ou comptabilité.",
              "La TVA globale se règle dans Tarifs. Elle sert à préremplir les nouveaux paiements et reste modifiable paiement par paiement.",
              "Les thèmes Classique, Ubuntu, Cuir/Inox, Graphite, Multi-sport et Windows 11 existent en clair et en sombre dans Paramètres. Ils changent les couleurs, les arrondis, les fonds et l'ambiance générale du logiciel.",
            ])}
          </div>
        </section>
      </div>`;
  }

  function helpSection(idValue, title, items) {
    return `<article class="band help-section" id="${esc(idValue)}">
      <div class="help-section-head">
        <h3>${esc(title)}</h3>
        <span>${items.length} point${items.length > 1 ? "s" : ""}</span>
      </div>
      <div class="help-point-list">
        ${items.map((item, index) => `<div class="help-point">
          <span>${index + 1}</span>
          <p>${esc(item)}</p>
        </div>`).join("")}
      </div>
    </article>`;
  }

  function displaySettingToggle(key, label, detail = "") {
    const display = displaySettings();
    const checked = key === "toolbarLabels" ? Boolean(display[key]) : display[key] !== false;
    return `<label class="settings-check">
      <input type="checkbox" data-display-setting="${esc(key)}" ${checked ? "checked" : ""} />
      <span>
        <strong>${esc(label)}</strong>
        ${detail ? `<small>${esc(detail)}</small>` : ""}
      </span>
    </label>`;
  }

  // Case « module visible dans le menu » (mode Personnalisé). Désactivée hors mode personnalisé.
  // Les modules protégés (Accueil, Paramètres, Aide) sont cochés et verrouillés : jamais masquables.
  function visibleModuleToggle(key) {
    const display = displaySettings();
    const label = (Object.fromEntries(views)[key]) || key;
    const forced = DISPLAY_FORCED_MODULES.includes(key);
    // Bloc unique Boutique & Stock : Stock suit toujours Boutique (isModuleVisibleByMode), donc sa
    // case n'a rien à régler en propre — verrouillée avec un libellé explicite plutôt qu'un clic
    // sans effet visible (audit modules désactivables).
    const linkedToBoutique = key === "stock";
    // L'état coché reflète la visibilité RÉELLE selon le mode courant : en Simple → modules du mode
    // simple ; en Avancé → tous ; en Personnalisé → choix enregistré (visibleModules). Ainsi l'utilisateur
    // voit ce qui est réellement actif dans le mode sélectionné. Les cases ne sont éditables qu'en
    // Personnalisé (disabled sinon), et le choix Personnalisé reste conservé même en Simple/Avancé.
    const checked = isModuleVisibleByMode(key);
    const disabled = forced || linkedToBoutique || display.mode !== "custom";
    return `<label class="settings-check"${disabled ? ' style="opacity:.55"' : ""}>
      <input type="checkbox" data-visible-module="${esc(key)}" ${checked ? "checked" : ""} ${disabled ? "disabled" : ""} />
      <span>
        <strong>${esc(label)}</strong>
        ${forced ? `<small>Toujours visible</small>` : linkedToBoutique ? `<small>Visible avec Boutique</small>` : ""}
      </span>
    </label>`;
  }

  function displayModeSummary() {
    const mode = displaySettings().mode;
    return mode === "simple" ? "Mode simple" : mode === "advanced" ? "Mode avancé" : "Mode personnalisé";
  }

  function displayModeButton(mode, label, detail) {
    const active = displaySettings().mode === mode;
    return `<button type="button" class="${active ? "primary" : ""}" data-action="set-display-mode" data-mode="${esc(mode)}" style="flex:1;min-width:150px;text-align:left;padding:10px 12px;border-radius:8px">
      <strong style="display:block">${esc(label)}</strong>
      <small style="display:block;font-weight:400;opacity:.85;margin-top:2px">${esc(detail)}</small>
    </button>`;
  }

  // Regroupement PRÉSENTATIONNEL des menus pour le panneau Affichage (indépendant de l'organisation
  // réelle du menu de gauche, qui reste personnalisable). Couvre toutes les clés DISPLAY_MODULE_KEYS.
  function displayModuleGroups() {
    return [
      ["Général", ["dashboard", "tasks"]],
      ["Gestion du club", ["contacts", "invoices", "due-payments", "tarifs"]],
      ["Gestion sportive", ["disciplines", "groups", "coaches", "rooms", "planning", "attendance", "documents", "stages"]],
      ["Boutique", ["boutique", "stock"]],
      ["Outils", ["search", "newsletter", "notes", "history", "audit-log"]],
      ["Analyse", ["stats", "accounting"]],
      ["Configuration", ["clubs", "club-settings", "settings", "help"]],
    ];
  }

  // Liste des menus regroupés par catégorie, avec cases reflétant la visibilité du mode courant.
  function displayVisibleModulesHtml() {
    const known = new Set();
    const groupsHtml = displayModuleGroups().map(([label, keys]) => {
      const valid = keys.filter((key) => DISPLAY_MODULE_KEYS.includes(key));
      valid.forEach((key) => known.add(key));
      if (!valid.length) return "";
      return `<div class="display-modules-group">
        <h5>${esc(label)}</h5>
        <div class="settings-check-grid">${valid.map(visibleModuleToggle).join("")}</div>
      </div>`;
    }).join("");
    // Filet de sécurité : si une clé n'a pas été classée (évolution future), on l'affiche à part.
    const others = DISPLAY_MODULE_KEYS.filter((key) => !known.has(key));
    const othersHtml = others.length ? `<div class="display-modules-group">
        <h5>Autres</h5>
        <div class="settings-check-grid">${others.map(visibleModuleToggle).join("")}</div>
      </div>` : "";
    return `<div class="display-modules-groups">${groupsHtml}${othersHtml}</div>`;
  }

  // Lot 2C — écran « Fonctionnalités du club ». Axe FONCTIONNALITÉ (settings.features / hasFeature),
  // strictement distinct de l'axe AFFICHAGE (settings.display), des permissions et de l'historique.
  // Les préférences d'affichage showBoutique et showStages ne sont JAMAIS modifiées ici.
  function featureDisplayHiddenNote(def) {
    // Actif mais masqué à l'écran = fonctionnalité disponible, mais préférence d'affichage sur
    // « masquer ». Seules Boutique et Stages ont un réglage d'affichage lié ; une fonctionnalité qui
    // n'en a pas n'est jamais dans cet état. Lecture seule : ne modifie JAMAIS settings.display.
    const displayKeys = { shop: "showBoutique", stages: "showStages" };
    const displayKey = displayKeys[def.key];
    if (!displayKey) return false;
    return displaySettings()[displayKey] === false;
  }

  function featureCardHtml(def) {
    const active = hasFeature(def.key);
    const displayHidden = active && featureDisplayHiddenNote(def);
    const statusText = active
      ? (displayHidden ? "Activée — masquée par les réglages d'affichage" : "Activée")
      : "Désactivée";
    return `<div class="feature-card feature-${esc(def.key)} ${active ? "is-on" : "is-off"}">
      <label class="settings-check feature-toggle">
        <input type="checkbox" data-feature-setting="${esc(def.key)}" ${active ? "checked" : ""} role="switch" aria-checked="${active ? "true" : "false"}" />
        <span>
          <strong>${esc(def.label)}</strong>
          ${def.ui.description ? `<small>${esc(def.ui.description)}</small>` : ""}
        </span>
      </label>
      <div class="feature-card-meta">
        <span class="feature-badge ${active ? "is-on" : "is-off"}">${esc(statusText)}</span>
        ${def.ui.dataRetention ? `<small class="muted">${esc(def.ui.dataRetention)}</small>` : ""}
        <small class="muted">Ce réglage ne concerne que le club actif.</small>
      </div>
    </div>`;
  }

  function featuresClubBandSummary() {
    const n = screenFeatures().filter((def) => hasFeature(def.key)).length;
    return `${n} fonctionnalité${n > 1 ? "s" : ""} activée${n > 1 ? "s" : ""}`;
  }

  function featuresClubBandBody() {
    const clubName = (typeof activeClub === "function" && activeClub() && activeClub().name) || "ce club";
    const configured = Boolean(settings.features && settings.features.configured === true);
    const intro = `<p class="muted">Ces fonctionnalités s'appliquent uniquement au club « ${esc(clubName)} ». Les autres clubs ne sont pas modifiés. Désactiver une fonctionnalité ne supprime pas ses données. Les droits des utilisateurs sont gérés séparément.</p>`;
    const originInfo = configured
      ? ""
      : `<p class="muted feature-origin-note">Ce club utilise encore sa configuration d'origine. Le premier changement sera enregistré uniquement pour ce club.</p>`;
    const cards = screenFeatures().map(featureCardHtml).join("");
    return `<div class="settings-panel features-club-panel">${intro}${originInfo}${cards}</div>`;
  }

  function renderSettings() {
    const macIconAvailable = canInstallMacAppIcon();
    return `<div class="settings-stack">
      ${settingsCollapsibleBand("themes", "Thèmes", activeTheme().name, `
        <div class="theme-anim-row">
          <div>
            <strong>Animations visuelles</strong>
            <small>Effets subtils de mouvement sur le fond et les éléments du thème actif</small>
          </div>
          <button class="${settings.themeAnimations ? "primary" : ""}" data-action="toggle-theme-animations">
            ${settings.themeAnimations ? "Activées" : "Désactivées"}
          </button>
        </div>
        <div class="settings-themes">
          ${themes.map((theme) => `<article class="theme-card ${settings.theme === theme.id ? "active" : ""}">
            <span class="theme-icon">${esc(theme.icon)}</span>
            <strong>${esc(theme.name)}</strong>
            <small>${esc(theme.note)}</small>
            <span class="theme-swatch theme-swatch-${esc(theme.id)}"></span>
            <div class="theme-card-actions">
              <button data-action="set-theme" data-theme="${esc(theme.id)}">${settings.theme === theme.id ? "Thème actif" : "Choisir"}</button>
              <button class="primary" data-action="customize-theme" data-theme="${esc(theme.id)}">Personnaliser ce thème</button>
            </div>
          </article>`).join("")}
        </div>`)}
      ${settingsCollapsibleBand("typography", "Polices", "Titres, texte, boutons", typographySettingsHtml())}
      ${settingsCollapsibleBand("postits", "Post-it À faire", "Couleurs et modèles", postitSettingsHtml())}
      ${settingsCollapsibleBand("features", "Fonctionnalités du club", featuresClubBandSummary(), featuresClubBandBody())}
      ${settingsCollapsibleBand("sport-categories", "Disciplines et catégories sportives", sportCategoriesBandSummary(), sportCategoriesBandBody())}
      ${settingsCollapsibleBand("group-age-policy", "Gestion des tranches d'âge", groupAgePolicyBandSummary(), groupAgePolicyBandBody())}
      ${settingsCollapsibleBand("display", "Affichage", displayModeSummary(), `<div class="settings-panel display-settings-panel">
          <label class="layout-mode-select">
            <span><strong>Disposition de l'interface</strong><small>Choisissez entre l'affichage moderne actuel et une interface classique avec menus en haut.</small></span>
            <select data-action="set-layout-mode">
              <option value="modern" ${settings.layout !== "classic" ? "selected" : ""}>Moderne</option>
              <option value="classic" ${settings.layout === "classic" ? "selected" : ""}>Classique</option>
            </select>
          </label>

          <div class="settings-subsection">
            <h4>Mode d'affichage</h4>
            <p class="muted">Choisissez la richesse de l'interface. Aucune donnée n'est supprimée : seuls les menus changent. Les vues masquées restent accessibles et fonctionnelles.</p>
            <div class="display-mode-row" style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 2px">
              ${displayModeButton("simple", "Simple", "Interface allégée pour les petits clubs")}
              ${displayModeButton("advanced", "Avancé", "Tous les modules visibles")}
              ${displayModeButton("custom", "Personnalisé", "Choisir précisément les modules visibles")}
            </div>
          </div>

          <div class="settings-subsection">
            <h4>Menus affichés dans ce mode</h4>
            <p class="muted">${displaySettings().mode === "custom"
              ? "Cochez les menus optionnels que vous souhaitez afficher. Les fonctions de base restent toujours visibles : Accueil, Recherche, E-mails, Documents sportifs, Paramètres et Aide."
              : "Ce mode est prédéfini. Passez en <strong>Personnalisé</strong> pour modifier les menus optionnels. Les fonctions de base restent toujours visibles : Accueil, Recherche, E-mails, Documents sportifs, Paramètres et Aide."}</p>
            ${displayVisibleModulesHtml()}
          </div>

          <div class="settings-subsection">
            <h4>Options &amp; modules de données</h4>
            <div class="settings-check-grid">
              ${displaySettingToggle("showAssistant", "Afficher le Centre d'accompagnement et les visites guidées", "Désactivez cette option si vous connaissez déjà le logiciel et ne souhaitez plus afficher les aides guidées.")}
              ${displaySettingToggle("toolbarLabels", "Texte sous les icônes", "Ajoute un petit libellé sous les boutons de la barre du haut.")}
              ${displaySettingToggle("showStages", "Afficher les Stages lorsqu'ils sont activés", "Ce réglage masque ou affiche les écrans des Stages sans activer ni désactiver la fonctionnalité et sans modifier les données.")}
              ${displaySettingToggle("showBoutique", "Afficher la Boutique lorsqu'elle est activée", "Ce réglage masque ou affiche les écrans de la Boutique sans activer ni désactiver la fonctionnalité et sans modifier les données.")}
            </div>
            ${!hasFeature("stages") ? `<p class="muted feature-display-context">Les Stages sont actuellement désactivés dans Fonctionnalités du club. Ce réglage d'affichage sera conservé pour une prochaine réactivation.</p>` : ""}
            ${!hasFeature("shop") ? `<p class="muted feature-display-context">La Boutique est actuellement désactivée dans Fonctionnalités du club. Ce réglage d'affichage sera conservé pour une prochaine réactivation.</p>` : ""}
          </div>
        </div>`)}
      ${settingsCollapsibleBand("menu-order", "Ordre du menu", menuOrderBandSummary(), `<div class="settings-panel menu-order-panel">
          <p class="muted">Voici la structure réelle de ton menu : les rubriques dans leur ordre, avec leurs pages juste en dessous. Fais glisser un élément pour le réordonner ou le déplacer d'une rubrique à l'autre, ou utilise les flèches ▲▼ (accessibles au clavier). Le cadenas 🔒 protège une page ou une rubrique par le mot de passe du logiciel ; 🎨 change l'icône ; ⇄ déplace vers une autre rubrique.</p>
          ${hasAppPassword() ? "" : `<p class="muted menu-order-nopass">Astuce : définis d'abord un mot de passe du logiciel dans « Sécurité » pour que les protections 🔒 prennent effet.</p>`}
          ${menuOrderTreeHtml()}
          <div class="inline-actions menu-order-actions">
            <button type="button" data-action="create-menu-group">+ Créer une rubrique</button>
            <button type="button" data-action="reset-menu-order">Réinitialiser l'ordre</button>
            ${(Array.isArray(settings.protectedViews) && settings.protectedViews.length) || customMenuGroups().some((g) => g.protected)
              ? `<button type="button" class="danger" data-action="remove-all-protections">Supprimer toutes les protections</button>` : ""}
          </div>
          <p class="muted">Crée une rubrique pour regrouper des entrées : fais-y glisser les pages du menu principal. La rubrique apparaît dans le menu — à gauche en disposition Moderne, en haut en disposition Classique (Affichage &gt; Disposition) — et se déplie au clic. « Réinitialiser l'ordre » restaure l'organisation et les icônes par défaut sans toucher aux protections.</p>
        </div>`)}
      ${settingsCollapsibleBand("checks", "Paiement en plusieurs fois", `${paymentCheckCount()} maximum`, `<div class="settings-panel">
          <p class="muted">Choisis le nombre maximum de paiements proposés. Pour chaque ligne, le menu Mode reprend les modes acceptés dans Paramètres du club.</p>
          <p class="muted">Pour les paiements autres que par chèque (espèces, carte, virement…), la date « Payé le » s'enregistre automatiquement au clic sur Payer : le paiement est considéré comme encaissé immédiatement, donc aucune alerte d'encaissement n'est créée. Seuls les chèques peuvent avoir une date d'encaissement à venir.</p>
          <label>Paiement en plusieurs fois
            <select data-setting="paymentCheckCount">
              ${paymentIndexes(MAX_PAYMENT_CHECK_COUNT).map((index) => {
                const value = index + 1;
                return `<option value="${value}" ${paymentCheckCount() === value ? "selected" : ""}>${value} paiement${value > 1 ? "s" : ""} maximum</option>`;
              }).join("")}
            </select>
          </label>
          <p class="muted">Si le dernier paiement autorisé est affiché, il doit couvrir tout le reste à payer avant validation.</p>
        </div>`)}
      ${settingsCollapsibleBand("security", "Sécurité", hasAppPassword() ? "Protection active" : "Aucun mot de passe", `<div class="settings-panel security-settings-panel">
          <p class="muted">Le même mot de passe protège l'ouverture du logiciel et le vidage des données. Il n'est pas stocké en clair. Le mot de passe est facultatif : tu peux le supprimer si tu préfères ne pas en avoir.</p>
          <div class="security-status ${hasAppPassword() ? "ok" : "due"}">
            <strong>${hasAppPassword() ? "Protection active" : "Aucun mot de passe"}</strong>
            <span>${hasAppPassword() ? "Le logiciel demandera le mot de passe au prochain démarrage." : "Le logiciel s'ouvre directement, sans mot de passe. Tu peux en créer un ci-dessous pour protéger l'ouverture du logiciel et le vidage des données."}</span>
          </div>
          <div class="form-grid compact">
            ${hasAppPassword() ? field("currentPassword", "Mot de passe actuel", "", "password", "data-security-current autocomplete=\"current-password\"") : ""}
            ${field("newPassword", hasAppPassword() ? "Nouveau mot de passe" : "Mot de passe", "", "password", "data-security-new autocomplete=\"new-password\"")}
            ${field("confirmPassword", "Confirmer", "", "password", "data-security-confirm autocomplete=\"new-password\"")}
          </div>
          <div class="inline-actions">
            <button class="primary" type="button" data-action="update-app-password">${hasAppPassword() ? "Changer le mot de passe" : "Créer le mot de passe"}</button>
            ${hasAppPassword() ? `<button type="button" class="danger" data-action="remove-app-password" title="Retirer le mot de passe (saisis d'abord le mot de passe actuel)">Supprimer le mot de passe</button>` : ""}
          </div>
          ${hasAppPassword() ? `<div class="security-recovery">
            <div class="security-status ${hasRecoveryCode() ? "ok" : "due"}">
              <strong>${hasRecoveryCode() ? "Code de récupération configuré" : "Aucun code de récupération"}</strong>
              <span>${hasRecoveryCode()
                ? "En cas d'oubli du mot de passe, le code de récupération permet d'en définir un nouveau depuis l'écran de démarrage. Il n'est jamais affiché en clair après sa création."
                : "Générez un code de récupération pour pouvoir réinitialiser le mot de passe en cas d'oubli (recommandé). Le code n'est affiché qu'une seule fois."}</span>
            </div>
            <div class="inline-actions">
              <button type="button" data-action="generate-recovery-code" title="Saisis d'abord le mot de passe actuel. Le nouveau code remplace l'ancien.">${hasRecoveryCode() ? "Générer un nouveau code de récupération" : "Générer un code de récupération"}</button>
            </div>
          </div>` : ""}
        </div>`)}
      ${settingsCollapsibleBand("logo", "Logo", "Image et icônes", `<div class="settings-panel logo-settings">
          <div class="settings-logo-preview">
            <img src="${esc(appLogoSrc())}" alt="Logo actuel" />
            <div>
              <p class="muted">Ce logo remplace l'icône de la page, le logo du menu et l'image de la fenêtre À propos. Dans l'application installée, il est aussi envoyé comme icône de fenêtre quand le système l'autorise.</p>
              <div class="form-grid compact">
                ${field("clubName", "Nom du club", settings.clubName || "MonGestaClub", "text", 'data-setting="clubName"')}
                ${field("clubSubtitle", "Sous-titre", settings.clubSubtitle || "Gestion de club", "text", 'data-setting="clubSubtitle"')}
              </div>
              <div class="inline-actions">
                <label class="button-like">Changer le logo<input type="file" accept="image/*" data-setting-logo hidden /></label>
                <button data-action="install-app-icon" ${macIconAvailable ? "" : "disabled"} title="${macIconAvailable ? "Appliquer ce logo à l'icône du fichier .app Mac" : "Disponible uniquement dans la version Mac"}">Appliquer à l'icône Mac</button>
                <button data-action="reset-logo">Logo d'origine</button>
              </div>
              <p class="muted">Ce bouton est actif uniquement dans la version Mac. Sur Windows, l'icône visible du .exe ne changera pas.</p>
            </div>
          </div>
        </div>`)}
      ${settingsCollapsibleBand("emails", "Messages e-mail", "Relances et modèles", `<div class="settings-panel email-template-settings">
          <p class="muted">Modifie ici les textes préparés automatiquement par le logiciel. Les variables entre accolades sont remplacées au moment de l'envoi.</p>
          <div class="email-template-list">
            ${emailTemplateSettingsHtml()}
          </div>
        </div>`)}
      ${settingsCollapsibleBand("smtp", "Envoi d'e-mails (SMTP)", smtpStatusLabel().label, `<div class="settings-panel smtp-settings">
          ${smtpSettingsHtml()}
        </div>`)}
      ${settingsCollapsibleBand("users", "Utilisateurs", activeUserDisplayName() || "Profils locaux", `<div class="settings-panel users-settings-panel">
          ${usersSettingsHtml()}
        </div>`)}
      ${settingsCollapsibleBand("data", "Données", "Sauvegarde et vidage", `<div class="settings-panel">
          <p class="muted">Ces boutons vident réellement les données enregistrées dans la catégorie choisie. Avant de supprimer, exporte une sauvegarde JSON.</p>
          <div class="dialog-section demo-data-settings">
            <h3>Données exemple</h3>
            <p class="muted">Crée un club séparé nommé ${esc(DEMO_CLUB_NAME)} avec des contacts, disciplines, stages, boutique, factures, notes, historique et alertes fictifs. Une sauvegarde JSON complète est téléchargée avant toute création ou réinitialisation.</p>
            <div class="inline-actions">
              <button type="button" data-action="create-demo-data">Créer les données exemple</button>
              <button type="button" class="danger" data-action="reset-demo-data">Réinitialiser le club démo</button>
            </div>
          </div>
          <div class="dialog-section season-settings">
            <h3>Saison</h3>
            <p class="muted">Choisis une période pour archiver uniquement la saison voulue. L'archive par dates ne vide pas le logiciel, sauf si tu choisis explicitement le vidage après archive.</p>
            <div class="form-grid compact">
              ${field("seasonStartDate", "Début saison", settings.season?.startDate || "", "date", "data-season-setting=\"startDate\"")}
              ${field("seasonEndDate", "Fin saison", settings.season?.endDate || "", "date", "data-season-setting=\"endDate\"")}
            </div>
            <label class="settings-check">
              <input type="checkbox" data-season-setting="autoBackup" ${settings.season?.autoBackup ? "checked" : ""} />
              <span><strong>Sauvegarde automatique JSON en fin de saison</strong><small>Quand la date de fin est passée, le logiciel prépare automatiquement une archive JSON une seule fois pour cette période.</small></span>
            </label>
            <div class="inline-actions">
              <button type="button" data-action="archive-season">Archiver la période sans vider</button>
              <button type="button" class="danger" data-action="archive-season-clear">Archiver puis vider la saison active</button>
            </div>
          </div>
          <div class="dialog-section reset-scope-settings">
            <h3>Vider par module</h3>
            <p class="muted">Un bouton = un module métier. Le logiciel supprime aussi les données dépendantes et nettoie les références internes. Chaque vidage ne concerne que le club actif ; la confirmation indique précisément ce qui sera supprimé et ce qui reste intact (les factures émises restent toujours consultables). Exporte une sauvegarde JSON avant.</p>
            ${resetScopeGroups().map((grp) => {
              const main = grp.scopes.filter((entry) => !entry.advanced);
              if (!main.length) return "";
              return `<div class="reset-scope-group">
              <h4>${esc(grp.group)}</h4>
              <div class="reset-scope-grid settings-reset-grid">
                ${main.map((entry) => `<button type="button" class="${entry.key === "all" ? "danger" : ""}" data-action="run-reset-scope" data-scope="${esc(entry.key)}" title="${esc(entry.detail)}">Vider · ${esc(entry.label)}</button>`).join("")}
              </div>
            </div>`;
            }).join("")}
            ${(() => {
              const advanced = resetScopeGroups().flatMap((grp) => grp.scopes.filter((entry) => entry.advanced).map((entry) => ({ ...entry, group: grp.group })));
              if (!advanced.length) return "";
              return `<details class="reset-scope-advanced">
              <summary><strong>Maintenance avancée</strong></summary>
              <p class="muted">Ces outils permettent d'effectuer des nettoyages très spécifiques. Ils sont rarement nécessaires dans une utilisation normale du logiciel.</p>
              <div class="reset-scope-grid settings-reset-grid">
                ${advanced.map((entry) => `<button type="button" data-action="run-reset-scope" data-scope="${esc(entry.key)}" title="${esc(entry.detail)}">Vider · ${esc(entry.group)} : ${esc(entry.label)}</button>`).join("")}
              </div>
            </details>`;
            })()}
          </div>
        </div>`)}
      ${settingsCollapsibleBand("license", "Licence", license?.activated ? "Activée" : "Essai ou activation", `<div class="settings-panel">
          ${license ? renderLicensePanel(false) : `<p class="muted">La licence est gérée dans l'application installée Mac/Windows.</p>`}
        </div>`)}
    </div>`;
  }

  function renderClubs() {
    const store = clubStore || normalizeClubStore(rawClubStoreFromStorage());
    const clubs = store.clubs.filter((club) => ui.showArchivedClubs || !club.archived);
    const demoExists = store.clubs.some((club) => club.id === DEMO_CLUB_ID || club.name === DEMO_CLUB_NAME);
    return `<div class="settings-stack">
      <div class="band">
        <div class="band-title">
          <div>
            <h2>Club démo</h2>
            <p class="muted">Crée un club séparé avec des données fictives pour tester MonGestaClub sans toucher à tes vrais clubs.</p>
          </div>
          <div class="inline-actions">
            <button class="primary" type="button" data-action="create-demo-club">Créer un club démo</button>
            ${demoExists ? `<button class="danger" type="button" data-action="reset-demo-club">Réinitialiser le club démo</button>` : ""}
          </div>
        </div>
      </div>
      <div class="band">
        <div class="band-title">
          <h2>Mes clubs</h2>
          <div class="inline-actions">
            <label class="settings-check compact-check"><input type="checkbox" data-toggle-archived-clubs ${ui.showArchivedClubs ? "checked" : ""} /><span>Afficher archivés</span></label>
            <button class="primary" type="button" data-action="new-club">Nouveau club</button>
          </div>
        </div>
        <div class="club-cards">
          ${clubs.map((club) => clubCardHtml(club, store.activeClubId === club.id)).join("") || `<p class="muted">Aucun club disponible. Crée un club pour commencer.</p>`}
        </div>
      </div>
    </div>`;
  }

  function clubCardHtml(club, active = false) {
    return `<article class="club-card ${active ? "active" : ""} ${club.archived ? "archived" : ""}">
      <div class="club-card-head">
        <img src="${esc(club.logoDataUrl || DEFAULT_LOGO)}" alt="${esc(club.name)}" />
        <div>
          <strong>${esc(club.name)}</strong>
          <span>${esc(club.shortName || "Club")} · ${esc(club.subtitle || "Gestion de club")}</span>
        </div>
        ${active ? `<em>Actif</em>` : ""}
        ${club.archived ? `<em class="archived-badge">Archivé</em>` : ""}
      </div>
      <div class="club-card-meta">
        <span>${esc(club.contact.city || "Ville non renseignée")}</span>
        <span>${esc(club.admin.legalStatus || "Statut non renseigné")}</span>
        <span>${esc(themes.find((theme) => theme.id === club.theme)?.name || club.theme)}</span>
      </div>
      <div class="inline-actions">
        <button type="button" data-action="switch-club" data-club-id="${esc(club.id)}" ${active || club.archived ? "disabled" : ""}>Activer</button>
        <button type="button" data-action="edit-club" data-club-id="${esc(club.id)}">Modifier</button>
        <button type="button" data-action="duplicate-club" data-club-id="${esc(club.id)}">Dupliquer</button>
        ${club.archived ? "" : `<button type="button" data-action="populate-club-demo" data-club-id="${esc(club.id)}" title="Remplir ce club avec des données de démonstration">Peupler avec la démo</button>`}
        ${club.archived
          ? `<button type="button" class="primary" data-action="unarchive-club" data-club-id="${esc(club.id)}">Réactiver</button>`
          : `<button type="button" class="danger" data-action="archive-club" data-club-id="${esc(club.id)}">Archiver</button>`}
        <button type="button" class="danger" data-action="delete-club" data-club-id="${esc(club.id)}">Supprimer</button>
      </div>
    </article>`;
  }

  function renderClubSettings() {
    const club = activeClub();
    if (!club) {
      return `<div class="band"><h2>Aucun club actif</h2><p class="muted">Crée ou sélectionne un club pour accéder à ses paramètres.</p><button class="primary" data-action="new-club">Créer un club</button></div>`;
    }
    return `<form class="settings-stack club-settings-form" data-club-settings-form>
      <div class="band">
        <div class="band-title">
          <h2>Paramètres du club actif</h2>
          <span class="club-active-badge">${esc(club.name)}</span>
        </div>
        <p class="muted">Ces informations ne modifient que le club actif. Elles serviront aussi plus tard aux documents et factures, sans créer la facturation maintenant.</p>
      </div>
      ${clubFormSectionsHtml(club)}
      <div class="form-actions-sticky">
        <button type="button" data-action="club-assistant" data-club-id="${esc(club.id)}">Assistant complet</button>
        <button type="button" class="primary" data-action="save-club-settings">Enregistrer les paramètres du club</button>
      </div>
    </form>`;
  }

