  function settingsCollapsibleBand(idValue, title, summary, body) {
    // Garde de cohérence : toute bande rendue doit être déclarée dans SETTINGS_PANEL_IDS
    // (01-constants.js), qui sert aussi à valider les entrées du registre de recherche.
    // On n'empêche pas le rendu (l'utilisateur ne doit jamais perdre une section), on signale.
    if (!isSettingsPanelId(idValue)) {
      console.warn(`settingsCollapsibleBand : bande « ${idValue} » absente de SETTINGS_PANEL_IDS (01-constants.js). La recherche globale ne pourra pas y conduire.`);
    }
    const open = Boolean(ui.settingsPanels?.[idValue]);
    return `<div class="band collapsible-band settings-collapsible-band ${open ? "open" : ""}" data-settings-panel="${esc(idValue)}">
      <div class="band-title collapsible-title-row" data-action="toggle-settings-panel" data-panel="${esc(idValue)}" role="button" tabindex="0" aria-expanded="${open ? "true" : "false"}">
        <h2>${esc(title)}</h2>
        <span class="collapsible-meta">${esc(summary || (open ? "Masquer" : "Afficher"))}</span>
        <span class="collapsible-arrow">›</span>
      </div>
      <div class="collapsible-content">
        <div class="collapsible-inner">${body}</div>
      </div>
    </div>`;
  }

  function formValue(form, name) {
    return asText(new FormData(form).get(name));
  }

  function clubFromForm(form, baseClub = {}) {
    const base = normalizeClubIdentity(baseClub);
    const managerLabels = clubManagerLabels();
    const paymentModes = paymentModeDefinitions().map(([mode]) => mode).filter((mode) => form.querySelector(`[name="paymentMode_${CSS.escape(mode)}"]`)?.checked);
    const club = normalizeClubIdentity({
      ...base,
      name: formValue(form, "clubName") || "Mon club",
      shortName: formValue(form, "shortName"),
      subtitle: formValue(form, "subtitle") || "Gestion de club",
      logoDataUrl: isLogoDataUrl(formValue(form, "logoDataUrl")) ? formValue(form, "logoDataUrl") : "",
      theme: formValue(form, "theme"),
      mainDiscipline: formValue(form, "mainDiscipline"),
      disciplines: formValue(form, "disciplines").split(/[,;\n]/).map((item) => item.trim()),
      season: {
        startDate: formValue(form, "seasonStartDate"),
        endDate: formValue(form, "seasonEndDate"),
        autoBackup: base.season?.autoBackup,
        lastAutoBackupKey: base.season?.lastAutoBackupKey,
      },
      admin: {
        legalStatus: formValue(form, "legalStatus"),
        rna: formValue(form, "rna"),
        siret: formValue(form, "siret"),
        siren: formValue(form, "siren"),
        apeNaf: formValue(form, "apeNaf"),
        vatNumber: formValue(form, "vatNumber"),
        vatRegime: formValue(form, "vatRegime"),
        vatMention: formValue(form, "vatMention"),
        creationDate: formValue(form, "creationDate"),
        federation: formValue(form, "federation"),
        federationNumber: formValue(form, "federationNumber"),
        approvalNumber: formValue(form, "approvalNumber"),
      },
      contact: {
        address: formValue(form, "address"),
        address2: formValue(form, "address2"),
        postalCode: formValue(form, "postalCode"),
        city: formValue(form, "city"),
        country: formValue(form, "country") || "France",
        phone: formValue(form, "phone"),
        email: formValue(form, "email"),
        website: formValue(form, "website"),
        social: formValue(form, "social"),
      },
      managers: Object.entries(managerLabels).map(([role, label]) => ({
        id: base.managers?.find((manager) => manager.role === role)?.id || id("manager"),
        role,
        function: formValue(form, `manager_${role}_function`) || label,
        lastName: formValue(form, `manager_${role}_lastName`),
        firstName: formValue(form, `manager_${role}_firstName`),
        email: formValue(form, `manager_${role}_email`),
        phone: formValue(form, `manager_${role}_phone`),
        notes: formValue(form, `manager_${role}_notes`),
      })),
      payments: {
        acceptedModes: paymentModes.length ? paymentModes : ["cash", "check", "card"],
        maxSplitPayments: normalizePaymentCheckCount(formValue(form, "maxSplitPayments")),
        maxChecks: normalizePaymentCheckCount(formValue(form, "maxChecks")),
        checkOrder: formValue(form, "checkOrder"),
        iban: formValue(form, "iban"),
        bic: formValue(form, "bic"),
        bankName: formValue(form, "bankName"),
        defaultConditions: formValue(form, "defaultConditions"),
        scheduleMessage: formValue(form, "scheduleMessage"),
      },
      documents: {
        prefix: formValue(form, "documentPrefix") || "MGC",
        numberingFormat: formValue(form, "numberingFormat") || "MGC-2026-0001",
        footer: formValue(form, "documentFooter"),
        legalMentions: formValue(form, "legalMentions"),
        paymentTerms: formValue(form, "paymentTerms"),
        defaultMessage: formValue(form, "documentDefaultMessage"),
      },
      updatedAt: new Date().toISOString(),
    });
    return club;
  }

  function saveClub(club, options = {}) {
    const beforeRaw = appStorage.getItem(CLUBS_KEY);
    const beforeActiveClubId = appStorage.getItem(ACTIVE_CLUB_KEY);
    const store = normalizeClubStore(rawClubStoreFromStorage() || clubStore);
    const previousClubIds = new Set(store.clubs.map((row) => row.id));
    const activeId = store.activeClubId;
    if (activeId) {
      updateActiveClubFromSettings(store);
      const activeClub = store.clubs.find((row) => row.id === activeId);
      store.data[activeId] = {
        state: scopeStateToClub(state, activeId),
        settings: settingsForClub(settings, activeClub),
      };
    }

    let normalizedClub = normalizeClubIdentity(club);
    let index = store.clubs.findIndex((row) => row.id === normalizedClub.id);
    if (options.create && previousClubIds.has(normalizedClub.id)) {
      do {
        normalizedClub = normalizeClubIdentity({ ...normalizedClub, id: id("club") });
      } while (previousClubIds.has(normalizedClub.id));
      index = -1;
    }

    if (index >= 0) store.clubs[index] = normalizedClub;
    else store.clubs.push(normalizedClub);
    store.activeClubId = options.activate ? normalizedClub.id : (store.activeClubId || normalizedClub.id);
    const previousPayload = store.data[normalizedClub.id] || {};
    // Duplication "avec toutes les données" : on copie le state complet du club source,
    // ré-estampillé avec le nouveau clubId (mode rebrand). Les ids internes sont conservés,
    // donc les relations (facture→contact, créneau→coach/salle, dépense→linkedId…) restent justes.
    const cloneSource = options.cloneFromClubId && store.data[options.cloneFromClubId] ? store.data[options.cloneFromClubId] : null;
    store.data[normalizedClub.id] = cloneSource ? {
      state: scopeStateToClub(cloneSource.state || normalizeState({}), normalizedClub.id, { rebrand: true }),
      // La config SMTP (serveur/port/expéditeur...) n'est JAMAIS dupliquée automatiquement, même
      // en "duplication avec données" : le secret (mot de passe) ne suit de toute façon jamais
      // (stocké séparément par clubId côté main process, jamais copié) — dupliquer les seuls
      // champs non sensibles laisserait un club affiché "configuré" mais incapable d'envoyer.
      settings: settingsForClub({ ...(cloneSource.settings || normalizeSettings({})), smtp: undefined }, normalizedClub),
    } : {
      // Lot 2 — création atomique par l'assistant : un state/settings pré-construits (disciplines,
      // installations, groupes, clubProfile, fonctionnalités) peuvent être fournis pour un club
      // NEUF, écrits en une seule passe (aucune création partielle). scopeStateToClub réestampille
      // le clubId ; settingsForClub renormalise. Sans ces options, comportement historique inchangé.
      state: scopeStateToClub(options.initialState || previousPayload.state || normalizeState({}), normalizedClub.id),
      settings: settingsForClub(options.initialSettings || previousPayload.settings || normalizeSettings({}), normalizedClub),
    };
    // Démarrage du club : la discipline principale saisie à la création devient une discipline
    // utilisable (tarifs.disciplines), réutilisée partout (adhérents, groupes, coachs, salles,
    // planning, tarifs). Sans doublon, et uniquement quand le créateur le demande (options.seedMainDiscipline).
    if (options.seedMainDiscipline) {
      const payload = store.data[normalizedClub.id];
      const discName = asText(normalizedClub.mainDiscipline);
      if (discName && payload && payload.state) {
        payload.state.tariffs = payload.state.tariffs || {};
        payload.state.tariffs.disciplines = payload.state.tariffs.disciplines || [];
        if (!payload.state.tariffs.disciplines.some((d) => asText(d.name).toLowerCase() === discName.toLowerCase())) {
          // Tarif/licence « à définir » (chaîne vide) plutôt que 0 : le wizard ne saisit que le NOM
          // de la discipline, jamais un prix. Une valeur vide signale « tarif non encore renseigné »
          // (affiché « À définir » dans les tarifs), à distinguer d'un 0 explicite = gratuité voulue.
          // asNumber("") = 0 → les calculs restent sûrs ; normalizeState ne touche pas price/license.
          payload.state.tariffs.disciplines.push({ id: id("discipline"), clubId: normalizedClub.id, name: discName, price: "", license: "" });
        }
      }
    }
    const savedStore = writeClubStore(store);
    const missingClubIds = [...previousClubIds].filter((clubId) => !savedStore.clubs.some((row) => row.id === clubId));
    if (missingClubIds.length) {
      if (beforeRaw) appStorage.setItem(CLUBS_KEY, beforeRaw);
      if (beforeActiveClubId) appStorage.setItem(ACTIVE_CLUB_KEY, beforeActiveClubId);
      throw new Error("Sécurité multi-club : la sauvegarde aurait supprimé un club existant.");
    }
    // Journal — APRÈS l'écriture réussie du magasin, jamais avant.
    //
    // `options.auditAction` (Lot 3B-4B-0) : un appelant peut déclarer l'action MÉTIER réelle quand
    // elle diffère du détail technique du stockage. Le premier lancement réutilise le club bootstrap
    // (create:false) : techniquement une mise à jour, métier une création. Le journal doit décrire
    // le geste de l'utilisateur, pas la mécanique du magasin.
    //
    // `options.onAuditFailure` (Lot 3B-4B-0) : sans ce rappel, une panne du journal remonte comme
    // avant — comportement historique STRICTEMENT inchangé pour tous les autres appelants. Avec lui,
    // elle est capturée et transmise : le club est déjà sur le disque à cet instant, une erreur de
    // journal ne peut donc plus transformer une création persistée en faux échec (même doctrine que
    // la création de disciplines du Lot 3B-4A).
    const auditFailures = [];
    try {
      if (options.auditAction === "club.created") {
        audit.clubCreated(normalizedClub);
      } else if (options.create) {
        // La duplication peut avoir lieu SANS copie des données ("Identité seulement") : on se
        // base sur duplicateSourceId (toujours renseigné en cas de duplication), pas sur
        // cloneFromClubId (qui ne l'est que pour la copie "avec toutes les données").
        const isDuplicateAction = Boolean(options.duplicateSourceId);
        if (isDuplicateAction) {
          const sourceClub = store.clubs.find((row) => row.id === options.duplicateSourceId);
          audit.clubDuplicated(normalizedClub, options.duplicateSourceId, sourceClub);
        } else {
          audit.clubCreated(normalizedClub);
        }
      } else {
        audit.clubSettingsUpdated(normalizedClub);
      }
    } catch (error) {
      if (typeof options.onAuditFailure !== "function") throw error;
      auditFailures.push(error);
    }
    if (auditFailures.length) options.onAuditFailure(auditFailures);
    if (savedStore.activeClubId === normalizedClub.id) loadActiveClubFromStore(savedStore);
    return savedStore;
  }

  function loadActiveClubFromStore(store = clubStore) {
    const normalized = normalizeClubStore(store);
    const payload = normalized.data[normalized.activeClubId];
    if (!payload) return false;
    clubStore = normalized;
    settings = settingsForClub(payload.settings || {}, normalized.clubs.find((club) => club.id === normalized.activeClubId));
    state = scopeStateToClub(payload.state || {}, normalized.activeClubId);
    ui.contactLetter = "";
    ui.disciplineLetter = "";
    ui.stageLetter = "";
    ui.query = "";
    // Lot 3A (D5) — le filtre de discipline (par nom) ne doit jamais survivre à un changement de
    // club : sans cela, filtrer « Judo » dans un club puis basculer sur un club sans « Judo »
    // produirait une vue vide/incohérente. Point central couvrant switch, création, duplication,
    // import, restauration et retour dans un club déjà ouvert (tous passent par ici).
    ui.discipline = "";
    ui.disciplineDueOnly = false;
    if (typeof invalidateSmtpUiStateForClubSwitch === "function") invalidateSmtpUiStateForClubSwitch();
    // Mode permissif (Lot 1 utilisateurs) : garantit une appartenance de l'utilisateur actif
    // sur le club désormais actif, sans jamais bloquer si elle n'existait pas encore.
    if (typeof ensureActiveUserMembershipForActiveClub === "function") ensureActiveUserMembershipForActiveClub();
    return true;
  }

  function switchActiveClub(clubId) {
    let store = normalizeClubStore(clubStore || rawClubStoreFromStorage());
    const club = store.clubs.find((row) => row.id === clubId && !row.archived);
    if (!club) {
      alert("Ce club n'est pas disponible ou il est archivé.");
      return false;
    }
    saveCurrentClubPayload({ reloadActive: false });
    store = normalizeClubStore(rawClubStoreFromStorage());
    store.activeClubId = club.id;
    writeClubStore(store);
    loadActiveClubFromStore(store);
    ui.saveMessage = `Club actif : ${club.name}`;
    return true;
  }

  function openClubEditorDialog(clubId = "", options = {}) {
    const store = normalizeClubStore(rawClubStoreFromStorage() || clubStore);
    const existing = store.clubs.find((club) => club.id === clubId);
    const isDuplicate = Boolean(options.duplicate);
    const base = isDuplicate && existing
      ? normalizeClubIdentity({ ...existing, id: id("club"), name: `${existing.name} copie`, archived: false, createdAt: new Date().toISOString() })
      : existing || defaultClubIdentity({ clubName: "Mon club", clubSubtitle: "Gestion de club", theme: settings.theme }, {});
    const title = existing && !isDuplicate ? "Modifier le club" : "Assistant de création du club";
    setNextWindowKey(existing && !isDuplicate ? `club:${existing.id}` : null);
    showDialog(title, clubFormSectionsHtml(base), async (_data, form) => {
      const club = clubFromForm(form, base);
      if (!asText(club.name)) {
        alert("Le nom du club est obligatoire.");
        return false;
      }
      try {
        const cloneFromClubId = isDuplicate && options.withData && existing ? existing.id : "";
        // Distinct de cloneFromClubId : renseigné dès qu'il s'agit d'une duplication, MÊME sans
        // copie des données ("Identité seulement"), pour que la journalisation (club.duplicated
        // vs club.created) reste correcte indépendamment du clonage effectif du state.
        const duplicateSourceId = isDuplicate && existing ? existing.id : "";
        saveClub(club, { activate: !existing || isDuplicate || options.activate, create: !existing || isDuplicate, cloneFromClubId, duplicateSourceId, seedMainDiscipline: !existing && !isDuplicate });
      } catch (error) {
        console.error(error);
        alert(error.message || "Impossible d'enregistrer le club sans conserver les clubs existants.");
        return false;
      }
      return existing && !isDuplicate
        ? `Modification du club ${club.name}`
        : (isDuplicate && options.withData ? `Duplication complète du club ${club.name}` : `Création du club ${club.name}`);
    }, (form) => {
      setupClubLogoPreview(form);
      setupThemePreview(form);
      setupAddressAutocomplete(form);
    });
  }

  function openClubAssistantDialog(clubId = "", options = {}) {
    const store = normalizeClubStore(rawClubStoreFromStorage() || clubStore);
    const existing = store.clubs.find((club) => club.id === clubId);
    const base = existing || defaultClubIdentity({ clubName: "Mon club", clubSubtitle: "Gestion de club", theme: settings.theme }, {});
    const steps = [
      ["Identité", "Nom, logo, couleurs, saison"],
      ["Administratif", "Statut, TVA, affiliation"],
      ["Adresse", "Coordonnées officielles"],
      ["Responsables", "Bureau et rôles"],
      ["Paiements", "Modes acceptés et échéanciers"],
      ["Documents", "Mentions préparées pour plus tard"],
    ];
    const wizardBody = `<div class="club-wizard" data-club-wizard>
      <div class="club-wizard-intro">
        <strong>${existing ? "Assistant de modification du club" : "Assistant de création du club"}</strong>
        <span>Avance étape par étape. Chaque page garde les informations déjà saisies, puis l'enregistrement final met à jour uniquement ce club.</span>
      </div>
      <div class="club-wizard-steps" data-club-wizard-steps>
        ${steps.map(([label], index) => `<button type="button" data-club-wizard-step="${index}">${esc(index + 1)}. ${esc(label)}</button>`).join("")}
      </div>
      ${clubFormSectionsHtml(base)}
      <div class="club-wizard-actions">
        <button type="button" data-club-wizard-prev>Précédent</button>
        <span data-club-wizard-caption></span>
        <button type="button" class="primary" data-club-wizard-next>Suivant</button>
      </div>
    </div>`;
    showDialog(existing ? "Assistant du club" : "Assistant de création du club", wizardBody, async (_data, form) => {
      const club = clubFromForm(form, base);
      if (!asText(club.name)) {
        alert("Le nom du club est obligatoire.");
        return false;
      }
      try {
        saveClub(club, { activate: !existing || options.activate, create: !existing, seedMainDiscipline: !existing });
      } catch (error) {
        console.error(error);
        alert(error.message || "Impossible d'enregistrer le club sans conserver les clubs existants.");
        return false;
      }
      return existing ? `Modification du club ${club.name}` : `Création du club ${club.name}`;
    }, (form) => {
      setupClubLogoPreview(form);
      setupThemePreview(form);
      setupAddressAutocomplete(form);
      setupClubWizard(form);
    });
  }

  function setupClubWizard(form) {
    const root = form.querySelector("[data-club-wizard]");
    if (!root) return;
    const sections = [...root.querySelectorAll(".club-form-section")];
    const stepButtons = [...root.querySelectorAll("[data-club-wizard-step]")];
    const previous = root.querySelector("[data-club-wizard-prev]");
    const next = root.querySelector("[data-club-wizard-next]");
    const caption = root.querySelector("[data-club-wizard-caption]");
    const submit = form.querySelector('button[type="submit"]');
    let current = 0;
    const update = () => {
      sections.forEach((section, index) => {
        section.hidden = index !== current;
      });
      stepButtons.forEach((button, index) => {
        button.classList.toggle("active", index === current);
        button.setAttribute("aria-current", index === current ? "step" : "false");
      });
      if (previous) previous.disabled = current === 0;
      if (next) next.hidden = current === sections.length - 1;
      if (caption) caption.textContent = `Étape ${current + 1} sur ${sections.length}`;
      if (submit) {
        submit.hidden = current !== sections.length - 1;
        submit.textContent = "Terminer et enregistrer";
      }
    };
    stepButtons.forEach((button) => {
      button.addEventListener("click", () => {
        current = Math.max(0, Math.min(sections.length - 1, Number(button.dataset.clubWizardStep)));
        update();
      });
    });
    previous?.addEventListener("click", () => {
      current = Math.max(0, current - 1);
      update();
    });
    next?.addEventListener("click", () => {
      current = Math.min(sections.length - 1, current + 1);
      update();
    });
    update();
  }

  async function archiveClub(clubId) {
    const store = normalizeClubStore(clubStore || rawClubStoreFromStorage());
    const club = store.clubs.find((row) => row.id === clubId);
    if (!club) return;
    const activeClubs = store.clubs.filter((row) => !row.archived);
    if (activeClubs.length <= 1) {
      alert("Impossible d'archiver le dernier club actif. Crée ou réactive un autre club avant.");
      return;
    }
    const confirmed = await requestDialogConfirmation(
      "Archiver le club",
      `Archiver ${club.name} ?\n\nLe club ne sera pas supprimé. Il disparaîtra de la sélection normale, mais tu pourras l'afficher avec l'option Voir archivés.`,
      "Archiver",
      true,
    );
    if (!confirmed) return;
    saveCurrentClubPayload({ reloadActive: false });
    const latest = normalizeClubStore(rawClubStoreFromStorage());
    const latestClub = latest.clubs.find((row) => row.id === clubId);
    if (!latestClub) return;
    const workingStore = latest;
    const workingClub = latestClub;
    workingClub.archived = true;
    workingClub.updatedAt = new Date().toISOString();
    if (workingStore.activeClubId === workingClub.id) {
      workingStore.activeClubId = workingStore.clubs.find((row) => !row.archived && row.id !== workingClub.id)?.id || "";
    }
    writeClubStore(workingStore);
    audit.clubArchived(workingClub);
    loadActiveClubFromStore(workingStore);
    ui.saveMessage = `Club archivé : ${workingClub.name}`;
    render();
  }

  function unarchiveClub(clubId) {
    const store = normalizeClubStore(clubStore || rawClubStoreFromStorage());
    const club = store.clubs.find((row) => row.id === clubId);
    if (!club) return;
    club.archived = false;
    club.updatedAt = new Date().toISOString();
    writeClubStore(store);
    audit.clubUnarchived(club);
    ui.saveMessage = `Club réactivé : ${club.name}`;
    render();
  }

  async function deleteClub(clubId) {
    saveCurrentClubPayload({ reloadActive: false });
    const store = normalizeClubStore(rawClubStoreFromStorage() || clubStore);
    const club = store.clubs.find((row) => row.id === clubId);
    if (!club) return;
    const remainingClubs = store.clubs.filter((row) => row.id !== club.id);
    if (!remainingClubs.length) {
      alert("Impossible de supprimer le dernier club. Crée un autre club avant de supprimer celui-ci.");
      return;
    }
    const message = `Supprimer définitivement le club "${club.name}" ?\n\nCette action supprime le club et toutes ses données dans le logiciel : contacts, inscriptions, paiements, boutique, stocks, notes, historique et factures.\n\nCette suppression est définitive. Exporte une sauvegarde JSON avant si tu veux pouvoir revenir en arrière.`;
    const confirmed = await requestProtectedDangerAction("Supprimer le club", message, "Supprimer définitivement");
    if (!confirmed) return;
    const latest = normalizeClubStore(rawClubStoreFromStorage() || store);
    const latestClub = latest.clubs.find((row) => row.id === club.id);
    if (!latestClub) return;
    latest.clubs = latest.clubs.filter((row) => row.id !== latestClub.id);
    delete latest.data[latestClub.id];
    // Nettoyage du secret SMTP de CE club uniquement (jamais celui des autres clubs) : évite de
    // laisser un secret orphelin indéfiniment côté main process une fois le club supprimé.
    if (typeof smtpShellAvailable === "function" && smtpShellAvailable()) {
      window.monGestaClubShell.smtpClearSecret(latestClub.id).catch(() => {});
    }
    if (latest.activeClubId === latestClub.id) {
      latest.activeClubId = latest.clubs.find((row) => !row.archived)?.id || latest.clubs[0]?.id || "";
    }
    const saved = writeClubStore(latest);
    // Événement journalisé AVANT que loadActiveClubFromStore() ne bascule le club actif : le
    // club supprimé n'existe déjà plus dans clubStore.clubs à ce stade, mais `latestClub` (capturé
    // plus haut, avant filtrage) garde son id/nom pour une trace lisible malgré la suppression.
    audit.clubDeleted(latestClub);
    // Supprime uniquement les appartenances liées à CE club (jamais celles des autres clubs) ;
    // les utilisateurs eux-mêmes restent, même s'ils n'ont plus aucun club (pas de désactivation
    // automatique — voir Lot 1 utilisateurs).
    if (typeof normalizeUserStore === "function") {
      const uStore = normalizeUserStore(userStore || rawUserStoreFromStorage());
      uStore.memberships = uStore.memberships.filter((row) => row.clubId !== latestClub.id);
      writeUserStore(uStore);
    }
    loadActiveClubFromStore(saved);
    ui.saveMessage = `Club supprimé : ${latestClub.name}`;
    render();
  }

  // Groupes de menu et clés "parent" qui doivent rester dans le menu principal
  const BASE_MENU_GROUPS = ["main", "settings", "boutique"];
  const BASE_MENU_PARENT_KEYS = ["boutique", "settings"];

  // Organisation logique par défaut du menu de gauche (groupes thématiques clairs).
  // Boutique et Configuration sont gérés par les parents intégrés "boutique" et "settings".
  function defaultMenuGroups() {
    return [
      { id: "grp-gestion", label: "Gestion du club" },
      { id: "grp-sport", label: "Gestion sportive" },
      { id: "grp-outils", label: "Outils" },
      { id: "grp-analyse", label: "Analyse" },
    ];
  }

  // Source unique des icônes par défaut des groupes par défaut (organisation moderne V3).
  // Utilisée à la fois pour l'icône d'origine réellement rendue (defaultMenuIconSvg) ET pour
  // les pré-réglages de la migration/reset, afin que la tuile « Auto » du sélecteur affiche
  // exactement l'icône que le menu utilise par défaut (pas de mapping divergent).
  const DEFAULT_MENU_GROUP_ICONS = {
    "grp-gestion": "folder",
    "grp-sport": "trophy",
    "grp-outils": "bolt",
    "grp-analyse": "stats",
  };
  function applyDefaultMenuGroupIcons() {
    Object.entries(DEFAULT_MENU_GROUP_ICONS).forEach(([id, iconId]) => setMenuIcon(id, iconId));
  }

  // Groupes de menu (parents personnalisés du menu de gauche). Tant que le club n'a
  // jamais été configuré, on propose les groupes par défaut ci-dessus.
  function customMenuGroups() {
    if (!Array.isArray(settings.customMenuGroups)) return defaultMenuGroups();
    return settings.customMenuGroups.filter((group) => group && group.id);
  }
  function customMenuGroupIds() {
    return customMenuGroups().map((group) => group.id);
  }
  function isCustomMenuGroup(key) {
    return customMenuGroupIds().includes(key);
  }

  // Menu parent (sous-menu) qui contient une vue : "settings", "boutique" ou un id
  // de menu personnalisé. null si la vue est dans le menu principal ou est elle-même un parent.
  function menuGroupContainingView(view) {
    const layout = resolveMenuLayout();
    return menuParentKeys().find((group) => (layout[group] || []).includes(view)) || null;
  }

  // Clé de protection d'une vue : l'id du menu personnalisé marqué « protégé » qui
  // contient cette vue. null = pas de protection. La protection des Tarifs n'est plus
  // codée en dur : elle dépend uniquement du menu (protégé) dans lequel se trouve la page
  // (voir ensureTarifsProtectionSetup pour le menu protégé par défaut).
  // (Sans mot de passe défini, aucune protection n'est applicable.)
  // Vue protégée individuellement (indépendamment de son groupe) : présente dans
  // settings.protectedViews. Purement déclaratif ; l'enforcement dépend de hasAppPassword().
  function isViewIndividuallyProtected(view) {
    return Array.isArray(settings.protectedViews) && settings.protectedViews.includes(view);
  }

  // Clé de protection EFFECTIVE d'une vue (source de vérité unique de l'enforcement, utilisée par
  // renderView + le déverrouillage + la RAZ à la sortie du périmètre). Règle déterministe :
  //   1. si la vue est dans un GROUPE protégé → clé = id du groupe (priorité : déverrouiller le
  //      groupe circule dans tout le groupe, un seul mot de passe) ;
  //   2. sinon si la vue est protégée INDIVIDUELLEMENT → clé = la vue elle-même ;
  //   3. sinon null.
  // Une seule clé effective par vue ⇒ jamais deux demandes successives pour le même secret.
  // Sans mot de passe défini, aucune protection n'est applicable (comme historiquement).
  function viewProtectionKey(view) {
    if (!hasAppPassword()) return null;
    const layout = resolveMenuLayout();
    const group = customMenuGroups().find((grp) => grp.protected && (layout[grp.id] || []).includes(view));
    if (group) return group.id;
    if (isViewIndividuallyProtected(view)) return view;
    return null;
  }

  // Toute action qui réduit la protection d'un menu protégé (le modifier/décocher,
  // le supprimer, en sortir une page) exige le mot de passe du logiciel — sinon la
  // protection ne servirait à rien.
  function requireProtectedMenuPassword(groupId) {
    const group = customMenuGroups().find((g) => g.id === groupId);
    if (!group || !group.protected || !hasAppPassword()) return Promise.resolve(true);
    return requestPasswordConfirmation("Menu protégé", "Saisis le mot de passe du logiciel pour modifier ce menu protégé.");
  }

  // Nouveau design : la page Tarifs vit dans « Gestion du club » et N'EST PLUS protégée
  // automatiquement (l'utilisateur peut toujours créer un menu protégé à la main). On ne crée
  // donc plus de menu « Tarifs » protégé par défaut pour les nouveaux clubs. Les configurations
  // existantes qui ont DÉJÀ un menu protégé (déjà migrées) ne sont pas touchées : leur protection
  // est préservée par ailleurs (customMenuGroups + ensureMenuOrganizationV3).
  function ensureTarifsProtectionSetup() {
    if (settings.tarifsProtectionMigrated) return;
    settings.tarifsProtectionMigrated = true;
    persistSettings();
  }
  // Tous les groupes (built-in + personnalisés) et toutes les "têtes" de sous-menu.
  function menuGroupIds() {
    return [...BASE_MENU_GROUPS, ...customMenuGroupIds()];
  }
  function menuParentKeys() {
    return [...BASE_MENU_PARENT_KEYS, ...customMenuGroupIds()];
  }
  // Libellé d'une clé de menu (vue connue ou groupe personnalisé).
  function menuKeyLabel(key) {
    const labels = Object.fromEntries(views);
    if (labels[key]) return labels[key];
    const custom = customMenuGroups().find((group) => group.id === key);
    return custom ? custom.label : key;
  }

  // Une clé de menu est "réelle" si elle correspond à une page connue. Sert à filtrer
  // les entrées orphelines (clé invalide, reste de migration) qui s'afficheraient sinon
  // avec leur clé brute (ex. "tatifs"). Les groupes personnalisés sont gérés à part.
  function isKnownViewKey(key) {
    return views.some(([viewKey]) => viewKey === key);
  }

  // Icône d'origine (sans personnalisation) d'une clé de menu.
  function defaultMenuIconSvg(key) {
    if (typeof MGC_ICONS !== "undefined" && MGC_ICONS[key]) return MGC_ICONS[key]; // mini-lot illustré (priorité)
    if (navIcons[key]) return navIcons[key];
    // Groupes par défaut (Gestion du club / sportive / Outils / Analyse) : icône d'origine réelle
    // (folder / trophy / bolt / stats), pour que la tuile « Auto » corresponde au rendu du menu.
    const defaultGroupIcon = DEFAULT_MENU_GROUP_ICONS[key];
    if (defaultGroupIcon && MENU_ICON_LIBRARY[defaultGroupIcon]) return MENU_ICON_LIBRARY[defaultGroupIcon];
    if (isCustomMenuGroup(key)) return MENU_ICON_LIBRARY.folder; // groupes créés par l'utilisateur : dossier
    return toolbarIcon("help");
  }

  // Icône effective d'une clé de menu (personnalisée si choisie, sinon d'origine).
  function menuIconSvg(key) {
    const chosen = (settings.menuIcons || {})[key];
    if (chosen && MENU_ICON_LIBRARY[chosen]) return MENU_ICON_LIBRARY[chosen];
    return defaultMenuIconSvg(key);
  }

  function setMenuIcon(key, iconId) {
    const icons = { ...(settings.menuIcons || {}) };
    if (iconId && MENU_ICON_LIBRARY[iconId]) icons[key] = iconId;
    else delete icons[key];
    settings.menuIcons = icons;
  }

  // Champ de choix d'icône : une tuile "d'origine" puis la bibliothèque.
  function iconPickerFieldHtml(selectedId = "", defaultSvg = "") {
    const tiles = [`<button type="button" class="icon-picker-btn icon-picker-default${selectedId ? "" : " selected"}" data-icon-pick="" title="Icône d'origine"><span class="nav-icon">${defaultSvg || MENU_ICON_LIBRARY.folder}</span><span class="icon-picker-default-label">Auto</span></button>`]
      .concat(Object.keys(MENU_ICON_LIBRARY).map((id) => `<button type="button" class="icon-picker-btn${id === selectedId ? " selected" : ""}" data-icon-pick="${esc(id)}" title="${esc(id)}"><span class="nav-icon">${MENU_ICON_LIBRARY[id]}</span></button>`));
    return `<div class="icon-picker-field">
      <input type="hidden" name="menuIcon" value="${esc(selectedId)}" data-icon-value />
      <div class="icon-picker" data-icon-picker>${tiles.join("")}</div>
    </div>`;
  }

  // Dialogue de personnalisation d'un menu : nom optionnel + grille d'icônes + protection éventuelle.
  function requestMenuCustomization({ title = "Personnaliser", name = null, icon = "", defaultSvg = "", confirmLabel = "Valider", protectable = false, isProtected = false } = {}) {
    return new Promise((resolve) => {
      let settled = false;
      const targetDialog = dialogForNewWindow();
      targetDialog.classList.remove("has-identity-photo");
      targetDialog.innerHTML = `<form class="menu-customizer-form">
        <div class="dialog-header"><h2>${esc(title)}</h2><button class="icon" type="button" data-dialog-close title="Fermer" aria-label="Fermer">×</button></div>
        <div class="dialog-body">
          <div class="dialog-section">
            ${name !== null ? `<label>Nom du menu<input type="text" name="menuName" value="${esc(name)}" placeholder="Ex. Administration" autofocus /></label>` : ""}
            <h3>Icône</h3>
            ${iconPickerFieldHtml(icon, defaultSvg)}
            ${protectable ? (hasAppPassword()
              ? `<label class="menu-protect-toggle"><input type="checkbox" name="menuProtected" ${isProtected ? "checked" : ""} /> Menu protégé par le mot de passe du logiciel</label>
                 <p class="muted">Les pages de ce menu demanderont le mot de passe du logiciel avant d'être affichées.</p>`
              : `<p class="muted">Pour protéger un menu par mot de passe, définis d'abord un mot de passe du logiciel dans Paramètres &gt; Sécurité.</p>`) : ""}
          </div>
        </div>
        <div class="dialog-footer">
          <span></span>
          <div class="dialog-footer-actions"><button type="button" data-dialog-close>Annuler</button><button class="primary" type="submit">${esc(confirmLabel)}</button></div>
        </div>
      </form>`;
      const finish = (result) => { if (settled) return; settled = true; resolve(result); };
      targetDialog.querySelectorAll("[data-dialog-close]").forEach((button) => button.addEventListener("click", () => { finish(null); targetDialog.close(); }));
      targetDialog.addEventListener("close", () => finish(null), { once: true });
      const form = targetDialog.querySelector("form");
      form.querySelectorAll("[data-icon-pick]").forEach((button) => button.addEventListener("click", () => {
        form.querySelector("[data-icon-value]").value = button.dataset.iconPick || "";
        form.querySelectorAll("[data-icon-pick]").forEach((b) => b.classList.toggle("selected", b === button));
      }));
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const resultName = name !== null ? asText(form.elements.menuName?.value).trim() : null;
        if (name !== null && !resultName) { form.elements.menuName?.focus(); return; }
        finish({ name: resultName, icon: asText(form.querySelector("[data-icon-value]")?.value), protected: Boolean(form.elements.menuProtected?.checked) });
        targetDialog.close();
      });
      showFloatingDialog(form, name !== null ? "input[name='menuName']" : "[data-icon-pick]", targetDialog);
    });
  }

  // Ancienne organisation (V2) — conservée pour rester cohérent avec les clubs encore sur les
  // anciens groupes (ex. menu protégé par mot de passe non migré). Évite que des pages disparaissent.
  function legacyDefaultMenuLayout() {
    const base = {
      main: ["dashboard", "tasks", "search", "grp-adherents", "grp-activites", "newsletter", "grp-finances", "boutique", "clubs", "settings"],
      "grp-adherents": ["contacts", "disciplines", "documents"],
      "grp-activites": ["groups", "coaches", "rooms", "planning", "attendance", "stages"],
      "grp-finances": ["invoices", "tarifs", "accounting", "stats"],
      settings: settingsViews.map(([k]) => k),
      boutique: boutiqueViews.map(([k]) => k),
    };
    customMenuGroupIds().forEach((id) => { if (!base[id]) base[id] = []; });
    return base;
  }

  // Nouvelle organisation (V3) — catégories claires : Gestion du club / Gestion sportive /
  // Boutique / Outils / Analyse / Configuration (parent intégré Paramètres).
  function modernDefaultMenuLayout() {
    const base = {
      main: ["dashboard", "tasks", "grp-gestion", "grp-sport", "boutique", "grp-outils", "grp-analyse", "settings"],
      "grp-gestion": ["contacts", "invoices", "due-payments", "tarifs"],
      "grp-sport": ["disciplines", "groups", "coaches", "rooms", "planning", "attendance", "documents", "stages"],
      "grp-outils": ["search", "newsletter", "notes", "history", "audit-log"],
      "grp-analyse": ["stats", "accounting"],
      settings: ["clubs", "club-settings", "help"],
      boutique: boutiqueViews.map(([k]) => k),
    };
    customMenuGroupIds().forEach((id) => { if (!base[id]) base[id] = []; });
    return base;
  }

  // Layout par défaut ADAPTÉ aux groupes actifs : si le club est encore sur les anciens groupes
  // (grp-adherents…), on renvoie l'ancien layout cohérent ; sinon le nouveau. Évite toute
  // désynchronisation groupes/layout (qui ferait disparaître des pages du menu).
  function defaultMenuLayout() {
    const ids = customMenuGroupIds();
    const hasModern = ids.includes("grp-gestion") || ids.includes("grp-sport") || ids.includes("grp-outils") || ids.includes("grp-analyse");
    const hasLegacy = ids.includes("grp-adherents") || ids.includes("grp-activites") || ids.includes("grp-finances");
    if (hasLegacy && !hasModern) return legacyDefaultMenuLayout();
    return modernDefaultMenuLayout();
  }

  // Migration unique par club : adopte l'organisation logique (groupes Adhérents /
  // Activités / Finances). Si le club avait un menu protégé par mot de passe (pages
  // financières), on RECRÉE la protection sur le groupe « Finances » pour ne rien
  // déverrouiller. Le mot de passe lui-même (settings.security) n'est pas touché.
  function ensureMenuOrganizationV2() {
    if (settings.menuOrganizationV2) return;
    settings.menuOrganizationV2 = true;
    const prevGroups = (Array.isArray(settings.customMenuGroups) ? settings.customMenuGroups : []).filter((g) => g && g.id);
    const wasProtected = prevGroups.some((g) => g.protected);
    settings.customMenuGroups = [
      { id: "grp-adherents", label: "Adhérents" },
      { id: "grp-activites", label: "Activités" },
      { id: "grp-finances", label: "Finances", protected: wasProtected },
    ];
    setMenuIcon("grp-adherents", "users");
    setMenuIcon("grp-activites", "whistle");
    setMenuIcon("grp-finances", wasProtected ? "key" : "tag");
    settings.menuLayout = defaultMenuLayout();
    persistSettings();
  }

  // Migration V3 : nouvelle organisation claire (Gestion du club / Gestion sportive / Boutique /
  // Outils / Analyse / Configuration). On NE réorganise PAS automatiquement un club dont un menu
  // est protégé par mot de passe (sécurité : on ne déplace pas une page protégée). Ces clubs
  // gardent leur organisation actuelle et peuvent réorganiser à la main ; les autres adoptent
  // la nouvelle organisation par défaut. Aucune donnée ni page n'est supprimée.
  function ensureMenuOrganizationV3() {
    const ids = customMenuGroupIds();
    const hasLegacy = ["grp-adherents", "grp-activites", "grp-finances"].some((id) => ids.includes(id));
    if (settings.menuOrganizationV3) {
      // Déjà migré. Auto-réparation : si d'anciens groupes réapparaissent (ex. chargement de
      // données démo plus anciennes) alors que le layout moderne est posé, on ré-applique pour
      // éviter une désynchronisation groupes/layout. On respecte une protection réelle (mot de passe).
      const protectedKept = (settings.customMenuGroups || []).some((g) => g && g.protected) && hasAppPassword();
      if (!hasLegacy || protectedKept) return;
    }
    settings.menuOrganizationV3 = true;
    const prevGroups = (Array.isArray(settings.customMenuGroups) ? settings.customMenuGroups : []).filter((g) => g && g.id);
    // On ne préserve l'ancienne organisation QUE si une protection par mot de passe est RÉELLEMENT
    // active (un menu protégé sans mot de passe est inerte). Ainsi les nouveaux utilisateurs et les
    // clubs sans mot de passe adoptent bien la nouvelle organisation. Sinon, le layout par défaut
    // reste « legacy » (cohérent avec leurs anciens groupes) grâce à defaultMenuLayout().
    const hasRealProtection = prevGroups.some((g) => g.protected) && hasAppPassword();
    if (hasRealProtection) { persistSettings(); return; }
    settings.customMenuGroups = defaultMenuGroups();
    applyDefaultMenuGroupIcons();
    settings.menuLayout = modernDefaultMenuLayout();
    persistSettings();
  }

  // Reconstruit un layout complet et cohérent : affectation + ordre de chaque vue
  // à partir de settings.menuLayout, en réinjectant les nouvelles vues à leur place
  // par défaut. Les parents (Boutique/Paramètres et groupes personnalisés) restent
  // dans le menu principal.
  function resolveMenuLayout() {
    const def = defaultMenuLayout();
    const groups = menuGroupIds();
    const parents = menuParentKeys();
    const saved = settings.menuLayout || {};
    const customIds = new Set(customMenuGroupIds());
    // knownViews = TOUTES les pages réelles (pas seulement main/settings/boutique). Sans cela, les
    // enfants des rubriques personnalisées (ex. disciplines, groups… dans grp-sport) n'étaient pas
    // « placeables » : l'ordre sauvé de ces pages était ignoré et retombait sur le défaut. On préserve
    // désormais l'ordre sauvé de n'importe quel groupe (les clés orphelines/invalides restent filtrées).
    const knownViews = new Set(views.map(([k]) => k).filter((k) => !customIds.has(k)));
    const isPlaceable = (key) => knownViews.has(key) || customIds.has(key);
    const layout = {};
    groups.forEach((group) => { layout[group] = []; });
    const placed = new Set();
    groups.forEach((group) => {
      (saved[group] || []).forEach((key) => {
        if (!isPlaceable(key) || placed.has(key)) return;
        if (parents.includes(key) && group !== "main") return; // les parents restent dans le menu principal
        layout[group].push(key);
        placed.add(key);
      });
    });
    groups.forEach((group) => {
      (def[group] || []).forEach((key) => {
        if (!placed.has(key)) { layout[group].push(key); placed.add(key); }
      });
    });
    // tout groupe personnalisé sans position connue apparaît dans le menu principal
    customIds.forEach((id) => { if (!placed.has(id)) { layout.main.push(id); placed.add(id); } });
    // FILET DE SÉCURITÉ : aucune page connue ne doit jamais disparaître du menu, même si les
    // groupes et le layout sont temporairement désynchronisés. Les vues non placées (hors parents)
    // atterrissent dans le menu principal — l'utilisateur les retrouve toujours.
    views.forEach(([key]) => {
      if (parents.includes(key)) return;
      if (!placed.has(key)) { layout.main.push(key); placed.add(key); }
    });
    return layout;
  }

  // Libellé lisible d'un groupe de menu (pour le sélecteur de destination).
  function menuGroupName(group) {
    if (group === "main") return "Menu principal";
    if (group === "settings") return "Sous-menu Paramètres";
    if (group === "boutique") return "Sous-menu Boutique";
    const custom = customMenuGroups().find((g) => g.id === group);
    return custom ? custom.label : group;
  }

  // Liste des groupes où l'on peut déplacer une entrée (hors groupe courant).
  function menuTargetGroups(currentGroup) {
    const groups = [["main", "Menu principal", MENU_ICON_LIBRARY.grid]];
    if (isViewVisible("settings")) groups.push(["settings", "Sous-menu Paramètres", menuIconSvg("settings")]);
    if (isViewVisible("boutique")) groups.push(["boutique", "Sous-menu Boutique", menuIconSvg("boutique")]);
    customMenuGroups().forEach((g) => groups.push([g.id, g.label, menuIconSvg(g.id)]));
    return groups.filter(([id]) => id !== currentGroup);
  }

  // Dialogue : choisir le menu de destination d'une entrée (inclut les menus personnalisés).
  function requestMenuTargetGroup(currentGroup, key) {
    return new Promise((resolve) => {
      let settled = false;
      const targetDialog = dialogForNewWindow();
      targetDialog.classList.remove("has-identity-photo");
      const groups = menuTargetGroups(currentGroup);
      targetDialog.innerHTML = `<div class="menu-target-chooser">
        <div class="dialog-header"><h2>Déplacer « ${esc(menuKeyLabel(key))} »</h2><button class="icon" type="button" data-dialog-close title="Fermer" aria-label="Fermer">×</button></div>
        <div class="dialog-body"><div class="dialog-section">
          <p class="muted">Choisis le menu de destination :</p>
          <div class="menu-target-list">
            ${groups.map(([id, label, icon]) => `<button type="button" class="menu-target-btn" data-target-group="${esc(id)}"><span class="nav-icon">${icon}</span><span>${esc(label)}</span></button>`).join("")}
          </div>
        </div></div>
      </div>`;
      const finish = (value) => { if (settled) return; settled = true; resolve(value); };
      targetDialog.querySelectorAll("[data-dialog-close]").forEach((b) => b.addEventListener("click", () => { finish(null); targetDialog.close(); }));
      targetDialog.addEventListener("close", () => finish(null), { once: true });
      targetDialog.querySelectorAll("[data-target-group]").forEach((b) => b.addEventListener("click", () => { finish(b.dataset.targetGroup); targetDialog.close(); }));
      showFloatingDialog(targetDialog, "[data-target-group]", targetDialog);
    });
  }

  function saveMenuLayout(layout) {
    const next = {};
    menuGroupIds().forEach((group) => { next[group] = layout[group] || []; });
    settings.menuLayout = next;
    persistSettings();
    ui.saveMessage = "Menu mis à jour";
    render();
  }

  // Conserve l'API existante utilisée par le rendu de la sidebar
  function orderedSubViews(group, viewsArr) {
    const order = resolveMenuLayout()[group] || [];
    const byKey = Object.fromEntries(viewsArr.map((v) => [v[0], v]));
    const labels = Object.fromEntries(views);
    return order.filter((k) => byKey[k] || labels[k]).map((k) => byKey[k] || [k, labels[k] || k]);
  }

  // Une page peut-elle être masquée/affichée depuis l'arborescence ? Seulement en mode d'affichage
  // « Personnalisé » (les autres modes sont pilotés par le mode lui-même) et hors modules forcés.
  function canTogglePageVisibility(key) {
    return displaySettings().mode === "custom" && !DISPLAY_FORCED_MODULES.includes(key) && key !== "stock" && isKnownViewKey(key);
  }

  // Rangée unique de l'arborescence du menu (page OU rubrique), réutilisée pour tous les niveaux.
  // opts.isGroup = rubrique (parent) ; opts.level = niveau ARIA (1 rubrique/entrée principale, 2 page).
  function menuOrderItemHtml(key, group, idx, total, opts = {}) {
    const isGroup = Boolean(opts.isGroup);
    const level = opts.level || 1;
    const label = menuKeyLabel(key);
    const isCustomGroup = isCustomMenuGroup(key);
    const visible = isGroup ? true : isViewVisible(key);
    // Protection : rubrique custom → drapeau du groupe ; page → protection effective (couverte par une
    // rubrique protégée OU protégée individuellement). Le bouton cadenas agit sur le drapeau propre.
    const groupProtected = isCustomGroup && Boolean(customMenuGroups().find((g) => g.id === key)?.protected);
    const coveredByGroup = !isGroup && Boolean(menuParentKeys().find((g) => customMenuGroups().find((c) => c.id === g)?.protected && (resolveMenuLayout()[g] || []).includes(key)));
    const selfProtected = isGroup ? groupProtected : isViewIndividuallyProtected(key);
    const effectiveProtected = isGroup ? groupProtected : (coveredByGroup || selfProtected);
    const lockLabel = isGroup
      ? (groupProtected ? `Retirer la protection de la rubrique ${label}` : `Protéger la rubrique ${label} (protège toutes ses pages)`)
      : (selfProtected ? `Retirer la protection de la page ${label}` : `Protéger la page ${label}`);
    const protectBtn = (isGroup && !isCustomGroup)
      ? "" // rubriques intégrées (Paramètres/Boutique) : protection non gérée dans ce lot
      : `<button type="button" class="menu-order-lock${selfProtected ? " is-on" : ""}" data-action="${isGroup ? "toggle-group-protection" : "toggle-view-protection"}" ${isGroup ? `data-group-id="${esc(key)}"` : `data-menu-key="${esc(key)}"`} aria-pressed="${selfProtected ? "true" : "false"}" title="${esc(lockLabel)}" aria-label="${esc(lockLabel)}"><span aria-hidden="true">${effectiveProtected ? "🔒" : "🔓"}</span></button>`;
    const visBtn = (!isGroup && canTogglePageVisibility(key))
      ? `<button type="button" class="menu-order-vis" data-action="toggle-page-visibility" data-menu-key="${esc(key)}" aria-pressed="${visible ? "true" : "false"}" title="${visible ? `Masquer la page ${label}` : `Afficher la page ${label}`}" aria-label="${visible ? `Masquer la page ${label}` : `Afficher la page ${label}`}"><span aria-hidden="true">${visible ? "👁" : "🚫"}</span></button>`
      : "";
    const iconBtn = `<button type="button" data-action="change-menu-icon" data-menu-key="${esc(key)}" title="Changer l'icône de ${esc(label)}" aria-label="Changer l'icône de ${esc(label)}"><span aria-hidden="true">🎨</span></button>`;
    const groupEditBtns = isCustomGroup
      ? `<button type="button" data-action="rename-menu-group" data-group-id="${esc(key)}" title="Renommer la rubrique ${esc(label)}" aria-label="Renommer la rubrique ${esc(label)}"><span aria-hidden="true">✎</span></button>
         <button type="button" class="icon danger" data-action="delete-menu-group" data-group-id="${esc(key)}" title="Supprimer la rubrique ${esc(label)}" aria-label="Supprimer la rubrique ${esc(label)}"><span aria-hidden="true">×</span></button>`
      : "";
    const moveGroupBtn = (!isGroup)
      ? `<button type="button" data-action="move-menu-item-group" data-menu-key="${esc(key)}" data-menu-group="${esc(group)}" title="Déplacer ${esc(label)} vers une autre rubrique…" aria-label="Déplacer ${esc(label)} vers une autre rubrique">⇄</button>`
      : "";
    return `<div class="menu-order-item${isGroup ? " menu-order-item-group" : ""}${visible ? "" : " menu-order-item-hidden"}" data-menu-drag-item data-menu-key="${esc(key)}" data-menu-group="${esc(group)}" draggable="true" role="treeitem" aria-level="${level}" aria-label="${esc((isGroup ? "Rubrique " : "Page ") + label)}">
      <span class="menu-order-handle" aria-hidden="true">≡</span>
      <span class="menu-order-icon" aria-hidden="true">${menuIconSvg(key)}</span>
      <span class="menu-order-label">${esc(label)}</span>
      ${!visible ? `<span class="menu-order-badge">masqué</span>` : ""}
      ${coveredByGroup ? `<span class="menu-order-badge menu-order-badge-lock" title="Cette rubrique protège toutes les pages qu'elle contient">protégée par la rubrique</span>` : ""}
      <div class="menu-order-btns">
        ${iconBtn}${protectBtn}${visBtn}${moveGroupBtn}
        <button type="button" data-action="move-menu-item-up" data-menu-key="${esc(key)}" data-menu-group="${esc(group)}" ${idx === 0 ? "disabled" : ""} title="Monter ${esc(label)}" aria-label="Monter ${esc(label)}">▲</button>
        <button type="button" data-action="move-menu-item-down" data-menu-key="${esc(key)}" data-menu-group="${esc(group)}" ${idx === total - 1 ? "disabled" : ""} title="Descendre ${esc(label)}" aria-label="Descendre ${esc(label)}">▼</button>
        ${groupEditBtns}
      </div>
    </div>`;
  }

  // Arborescence du menu : reproduit visuellement le vrai menu (rubriques dans leur ordre réel, avec
  // leurs pages indentées juste en dessous). MÊME source de vérité que la sidebar (resolveMenuLayout).
  // Chaque conteneur porte data-menu-order-list/data-menu-group pour le glisser-déposer inter-groupes.
  function menuOrderTreeHtml() {
    const layout = resolveMenuLayout();
    const parents = menuParentKeys();
    const mainKeys = layout.main || [];
    const rows = mainKeys.map((key, idx) => {
      const isParent = parents.includes(key);
      const row = menuOrderItemHtml(key, "main", idx, mainKeys.length, { isGroup: isParent, level: 1 });
      if (!isParent) return row;
      const childKeys = layout[key] || [];
      const children = childKeys.map((ck, i) => menuOrderItemHtml(ck, key, i, childKeys.length, { isGroup: false, level: 2 })).join("");
      return `${row}
        <div class="menu-order-children menu-order-list" data-menu-order-list data-menu-group="${esc(key)}" role="group" aria-label="Pages de ${esc(menuKeyLabel(key))}">
          ${children || `<p class="menu-order-empty muted">Aucune page — glisse une page ici.</p>`}
        </div>`;
    }).join("");
    return `<div class="menu-order-tree menu-order-list" data-menu-order-list data-menu-group="main" role="tree" aria-label="Structure du menu">${rows}</div>`;
  }

  // Résumé de la bande « Ordre du menu » : nombre d'éléments protégés (pages + rubriques).
  function menuOrderBandSummary() {
    const pages = Array.isArray(settings.protectedViews) ? settings.protectedViews.length : 0;
    const groups = customMenuGroups().filter((g) => g.protected).length;
    const total = pages + groups;
    if (!total) return "Personnaliser la navigation";
    return `${total} protection${total > 1 ? "s" : ""}`;
  }

  let menuDragKey = null;
  let menuDragGroup = null;

  function setupMenuOrderDrag() {
    const lists = [...app.querySelectorAll("[data-menu-order-list]")];
    if (!lists.length) return;
    const clearOver = () => app.querySelectorAll(".menu-order-item.drag-over, .menu-order-list.drag-over").forEach((i) => i.classList.remove("drag-over"));

    const applyDrop = async (targetGroup, targetKey) => {
      const sourceKey = menuDragKey;
      const sourceGroup = menuDragGroup;
      if (!sourceKey) return;
      if (menuParentKeys().includes(sourceKey) && targetGroup !== "main") return; // parent reste dans le menu principal
      // Sortir une page d'un menu protégé exige le mot de passe.
      if (targetGroup !== sourceGroup && !await requireProtectedMenuPassword(sourceGroup)) return;
      const layout = resolveMenuLayout();
      menuGroupIds().forEach((g) => { layout[g] = layout[g].filter((k) => k !== sourceKey); });
      const list = layout[targetGroup];
      let idx = targetKey ? list.indexOf(targetKey) : list.length;
      if (idx < 0) idx = list.length;
      list.splice(idx, 0, sourceKey);
      saveMenuLayout(layout);
    };

    lists.forEach((container) => {
      const group = container.dataset.menuGroup || "main";
      container.addEventListener("dragover", (e) => { e.preventDefault(); });
      container.addEventListener("drop", (e) => {
        e.preventDefault();
        e.stopPropagation(); // conteneurs imbriqués (arbre) : le plus interne gère seul le drop
        clearOver();
        if (e.target.closest("[data-menu-drag-item]")) return; // géré par l'item
        applyDrop(group, null);
      });
      // :scope > : uniquement les items DIRECTS de ce conteneur. En arborescence, les listes enfants
      // sont imbriquées dans le conteneur « main » ; sans cela leurs items seraient gérés deux fois.
      container.querySelectorAll(":scope > [data-menu-drag-item]").forEach((item) => {
        item.addEventListener("dragstart", (e) => {
          menuDragKey = item.dataset.menuKey;
          menuDragGroup = group;
          item.classList.add("dragging");
          e.dataTransfer.effectAllowed = "move";
          e.dataTransfer.setData("text/plain", menuDragKey || "");
        });
        item.addEventListener("dragend", () => {
          menuDragKey = null; menuDragGroup = null;
          item.classList.remove("dragging");
          clearOver();
        });
        item.addEventListener("dragover", (e) => {
          e.preventDefault();
          if (menuDragKey && menuDragKey !== item.dataset.menuKey) {
            clearOver();
            item.classList.add("drag-over");
          }
        });
        item.addEventListener("dragleave", () => item.classList.remove("drag-over"));
        item.addEventListener("drop", (e) => {
          e.preventDefault();
          e.stopPropagation();
          clearOver();
          if (!menuDragKey || menuDragKey === item.dataset.menuKey) return;
          applyDrop(group, item.dataset.menuKey);
        });
      });
    });
  }

  function setupThemePreview(form) {
    form.querySelector('[name="theme"]')?.addEventListener("change", (event) => {
      document.documentElement.dataset.theme = event.target.value;
      applyThemeOverrides();
    });
  }

  function setupClubLogoPreview(form) {
    const fileInput = form.querySelector("[data-club-logo-file]");
    const valueInput = form.querySelector("[data-club-logo-value]");
    const preview = form.querySelector("[data-club-logo-preview]");
    fileInput?.addEventListener("change", async () => {
      const file = fileInput.files?.[0];
      if (!file) return;
      if (!file.type.startsWith("image/")) {
        alert("Choisis un fichier image.");
        fileInput.value = "";
        return;
      }
      const dataUrl = await logoFileToDataUrl(file);
      valueInput.value = dataUrl;
      preview.src = dataUrl;
    });
  }

  function saveClubSettingsFromPage() {
    const form = app.querySelector("[data-club-settings-form]");
    const club = activeClub();
    if (!form || !club) return;
    const updated = clubFromForm(form, club);
    saveClub(updated, { activate: true });
    ui.saveMessage = "Paramètres du club enregistrés";
    render();
  }

  function fontSelect(name, label, value, detail = "") {
    return `<label>${esc(label)}
      <select data-typography="${esc(name)}">
        ${FONT_OPTIONS.map((font) => `<option value="${esc(font.value)}" ${font.value === value ? "selected" : ""}>${esc(font.label)} - ${esc(font.note)}</option>`).join("")}
      </select>
      ${detail ? `<small>${esc(detail)}</small>` : ""}
    </label>`;
  }

  function typographySettingsHtml() {
    settings.typography = normalizeTypographySettings(settings.typography);
    return `<div class="settings-panel typography-settings">
      <p class="muted">Choisis les polices du logiciel. Lobster est proposée pour les titres, mais les polices plus simples restent meilleures pour lire tous les jours.</p>
      <div class="form-grid compact">
        ${fontSelect("titleFont", "Police des titres", settings.typography.titleFont, "Titres de pages, fiches et indicateurs.")}
        ${fontSelect("bodyFont", "Police du texte", settings.typography.bodyFont, "Texte principal, formulaires et tableaux.")}
        ${fontSelect("buttonFont", "Police des boutons", settings.typography.buttonFont, "Boutons et actions.")}
        ${fontSelect("menuFont", "Police des menus", settings.typography.menuFont, "Menu de gauche et navigation.")}
        <label>Taille générale
          <select data-typography="fontSize">${FONT_SIZE_OPTIONS.map(([key, label]) => `<option value="${esc(key)}" ${settings.typography.fontSize === key ? "selected" : ""}>${esc(label)}</option>`).join("")}</select>
        </label>
        <label>Épaisseur du texte
          <select data-typography="fontWeight">${FONT_WEIGHT_OPTIONS.map(([key, label]) => `<option value="${esc(key)}" ${settings.typography.fontWeight === key ? "selected" : ""}>${esc(label)}</option>`).join("")}</select>
        </label>
      </div>
      <div class="typography-preview">
        <h3>Aperçu du titre MonGestaClub</h3>
        <p>Voici un texte de formulaire, une information secondaire et un bouton pour vérifier la lisibilité.</p>
        <button type="button">Bouton exemple</button>
      </div>
      <div class="inline-actions">
        <button type="button" data-action="reset-typography">Réinitialiser les polices par défaut</button>
      </div>
    </div>`;
  }

  function postitSettingsHtml() {
    settings.postitStyles = normalizePostitStyles(settings.postitStyles);
    return `<div class="settings-panel postit-settings">
      <p class="muted">Personnalise la couleur et le modèle de post-it utilisés dans la page À faire, selon chaque type d'alerte.</p>
      <div class="postit-style-grid">
        ${VISIBLE_POSTIT_TYPES.map(([key, label]) => {
          const style = settings.postitStyles[key];
          const previewStyle = `--postit-color:${esc(style.color)};--postit-image:url('${esc(postitDesignUrl(style.design))}')`;
          return `<section class="postit-style-card" style="${previewStyle}">
            <div class="task-postit mini-preview task-${esc(key)}" style="${previewStyle}">
              <span class="status">${esc(label)}</span>
              <strong>Exemple</strong>
              <p>Couleur et modèle du post-it.</p>
            </div>
            <label>Couleur
              <input type="color" data-postit-style="${esc(key)}" data-postit-field="color" value="${esc(style.color)}" />
            </label>
            <label>Modèle
              <select data-postit-style="${esc(key)}" data-postit-field="design">
                ${POSTIT_DESIGNS.map(([idValue, name]) => `<option value="${esc(idValue)}" ${style.design === idValue ? "selected" : ""}>${esc(name)}</option>`).join("")}
              </select>
            </label>
          </section>`;
        }).join("")}
      </div>
    </div>`;
  }

  function emailTemplateSettingsHtml() {
    const defs = configurableEmailTemplateDefinitions();
    const selected = selectedEmailTemplateKey();
    const def = defs[selected];
    const draft = activeEmailTemplateDraft(selected);
    const locked = !ui.emailTemplateEditing;
    const isCustom = !emailTemplateDefinitions()[selected];
    return `<section class="email-template-card">
      <div class="email-template-toolbar">
        <label>Modèle
          <select data-email-template-select>
            ${Object.entries(defs).map(([key, item]) => `<option value="${esc(key)}" ${key === selected ? "selected" : ""}>${esc(item.label)}</option>`).join("")}
          </select>
        </label>
        <div class="inline-actions">
          <button type="button" data-action="new-email-template">Nouveau modèle</button>
          ${locked
            ? `<button type="button" class="primary" data-action="edit-email-template">✏️ Modifier ce modèle</button>`
            : `<button type="button" class="primary" data-action="save-email-template">Enregistrer</button><button type="button" data-action="cancel-email-template">Annuler les modifications</button>`}
          ${isCustom ? `<button type="button" class="danger" data-action="delete-email-template">Supprimer</button>` : ""}
        </div>
      </div>
      <div class="email-template-head">
        <div>
          <strong>${esc(def.label)}</strong>
          <span>${esc(def.note)}</span>
        </div>
      </div>
      ${locked
        ? `<div class="email-mode-hint locked" role="note"><span class="email-mode-ico">🔒</span><span>Ce modèle est en <strong>lecture seule</strong>. Pour le changer, clique sur le bouton <strong>« ✏️ Modifier ce modèle »</strong> ci-dessus.</span></div>`
        : `<div class="email-mode-hint editing" role="note"><span class="email-mode-ico">✏️</span><span><strong>Modification en cours</strong> · « Enregistrer » garde vos changements, « Annuler les modifications » remet la version enregistrée.</span></div>`}
      <div class="email-model-legend">
        <div class="editable"><strong>Modifiable</strong><span>Objet, texte, phrase personnalisée, note ajoutée avant l'envoi.</span></div>
        <div class="automatic"><strong>Automatique</strong><span>Les blocs entre accolades viennent du logiciel. Garde-les si tu veux que les données du contact ou du paiement se remplissent seules.</span></div>
      </div>
      ${isCustom ? `<div class="form-grid compact">
        <label>Nom du modèle
          <input type="text" value="${esc(draft.label || def.label)}" data-email-template-draft-field="label" ${locked ? "readonly" : ""} />
        </label>
        <label>Type du modèle
          <select data-email-template-draft-field="type" ${locked ? "disabled" : ""}>
            ${["e-mail simple", "newsletter", "relance", "autre"].map((type) => `<option value="${esc(type)}" ${asText(draft.type || "autre") === type ? "selected" : ""}>${esc(type)}</option>`).join("")}
          </select>
        </label>
      </div>` : ""}
      <label>Objet
        <input type="text" value="${esc(draft.subject)}" data-email-template-draft-field="subject" ${locked ? "readonly" : ""} />
      </label>
      <label>Texte
        <textarea rows="9" data-email-template-draft-field="body" ${locked ? "readonly" : ""}>${esc(draft.body)}</textarea>
      </label>
      ${emailTemplateCustomVariablesHtml(selected, draft, locked)}
      <div class="email-variable-help">${emailVariableHelp(def.variables)}</div>
    </section>`;
  }

  // Paramètres > Envoi d'e-mails (SMTP) — MVP. Le mot de passe n'est jamais relu depuis
  // settings (il n'y est jamais stocké) : le champ reste vide, y compris après enregistrement ;
  // seul un indicateur "déjà enregistré" (via ui.smtpSecretStatus, alimenté par IPC) informe
  // l'utilisateur sans jamais réafficher le secret en clair.
  function smtpSettingsHtml() {
    if (!smtpShellAvailable()) {
      return `<div class="muted-panel"><strong>Envoi intégré indisponible ici</strong><p class="muted">L'envoi SMTP intégré n'est disponible que dans la version de bureau (Electron) de MonGestaClub. MonGestaClub continue d'ouvrir votre messagerie habituelle pour les e-mails.</p></div>`;
    }
    const draft = smtpDraftValues();
    const status = smtpStatusLabel();
    const secretPresent = Boolean(ui.smtpSecretStatus?.present);
    const secretSecure = Boolean(ui.smtpSecretStatus?.secure);
    return `
      <p class="muted">MonGestaClub peut envoyer vos e-mails directement, en se connectant au serveur SMTP de l'adresse mail du club (Gmail, Outlook, OVH…). Gmail et Outlook demandent souvent un <strong>mot de passe d'application</strong> plutôt que votre mot de passe habituel. Si rien n'est configuré ici, MonGestaClub continue d'ouvrir votre messagerie externe comme avant.</p>
      <div class="smtp-status smtp-status-${esc(status.key)}"><strong>État :</strong> ${esc(status.label)}${draft.lastTestMessage ? ` — <span class="muted">${esc(draft.lastTestMessage)}</span>` : ""}</div>
      <div class="form-grid compact">
        <label>Envoi intégré
          <select data-smtp-field="enabled">
            <option value="0" ${!draft.enabled ? "selected" : ""}>Désactivé</option>
            <option value="1" ${draft.enabled ? "selected" : ""}>Activé</option>
          </select>
        </label>
        <label>Nom d'expéditeur
          <input type="text" data-smtp-field="senderName" value="${esc(draft.senderName)}" placeholder="${esc(settings.clubName || "Mon club")}" />
        </label>
        <label>Adresse d'expéditeur
          <input type="email" data-smtp-field="senderEmail" value="${esc(draft.senderEmail)}" placeholder="club@example.com" />
        </label>
        <label>Serveur SMTP
          <input type="text" data-smtp-field="host" value="${esc(draft.host)}" placeholder="smtp.gmail.com" />
        </label>
        <label>Port
          <input type="number" min="1" max="65535" data-smtp-field="port" value="${esc(String(draft.port ?? 587))}" />
        </label>
        <label>Sécurité
          <select data-smtp-field="security">
            <option value="starttls" ${draft.security === "starttls" ? "selected" : ""}>STARTTLS (recommandé, port 587)</option>
            <option value="ssl" ${draft.security === "ssl" ? "selected" : ""}>SSL/TLS (port 465)</option>
            <option value="none" ${draft.security === "none" ? "selected" : ""}>Aucune</option>
          </select>
        </label>
        <label>Identifiant
          <input type="text" data-smtp-field="username" value="${esc(draft.username)}" placeholder="${esc(draft.senderEmail || "identifiant")}" />
        </label>
        <label>Mot de passe ${secretPresent ? `<small class="muted">— déjà enregistré${secretSecure ? "" : ", non chiffré sur ce système"}</small>` : ""}
          <input type="password" data-smtp-field="password" value="" autocomplete="new-password" placeholder="${secretPresent ? "•••••••• (laisser vide pour ne pas changer)" : "Mot de passe ou mot de passe d'application"}" />
        </label>
        <label>Adresse de test
          <input type="email" data-smtp-field="testAddress" value="${esc(draft.testAddress)}" placeholder="toi@example.com" />
        </label>
      </div>
      ${secretPresent && !secretSecure ? `<p class="muted smtp-warning">⚠ Le chiffrement sécurisé du système (trousseau) n'est pas disponible ici : le mot de passe est stocké hors des sauvegardes JSON, mais sans chiffrement fort. Évitez un mot de passe sensible si possible sur cette machine.</p>` : ""}
      <div class="inline-actions">
        <button type="button" class="primary" data-action="save-smtp-settings">Enregistrer</button>
        <button type="button" data-action="test-smtp-settings" ${ui.smtpTesting ? "disabled" : ""}>${ui.smtpTesting ? "Test en cours…" : "Tester l'envoi"}</button>
        <button type="button" class="danger" data-action="clear-smtp-settings" ${(draft.host || secretPresent) ? "" : "disabled"}>Supprimer la configuration SMTP</button>
      </div>
    `;
  }

  function emailTemplateCustomVariablesHtml(templateKey, draft = {}, locked = true) {
    const fields = emailTemplateCustomFields(templateKey);
    if (!fields.length) {
      return `<div class="email-custom-variables muted-panel">
        <strong>Variables personnalisables du modèle</strong>
        <p class="muted">Ce modèle utilise ses propres champs au moment de l'envoi. Pour le modèle Newsletter, les variables {titre}, {detail}, {date} et {lieu} se remplissent directement depuis la page E-mail.</p>
      </div>`;
    }
    const values = draft.customVariables || {};
    return `<div class="email-custom-variables">
      <div class="email-variable-title">
        <strong>Variables personnalisables du modèle</strong>
        <span>Ces textes sont enregistrés avec ce modèle, uniquement pour le club actif.</span>
      </div>
      <div class="email-custom-variable-grid">
        ${fields.map(([fieldName, label, help]) => `
          <label>${esc(label)} <small class="email-variable-chip" role="button" tabindex="0" data-action="copy-email-variable" data-variable="{${esc(fieldName)}}" title="Cliquer pour copier {${esc(fieldName)}}">{${esc(fieldName)}}</small>
            <textarea rows="3" data-email-template-custom-field="${esc(fieldName)}" ${locked ? "readonly" : ""}>${esc(values[fieldName] || "")}</textarea>
            <span>${esc(help)}</span>
          </label>
        `).join("")}
      </div>
    </div>`;
  }

