      "{clubEmail}": "e-mail officiel du club",
      "{clubTelephone}": "téléphone du club",
      "{clubAdresse}": "adresse du club",
      "{clubCodePostal}": "code postal du club",
      "{clubVille}": "ville du club",
      "{clubPays}": "pays du club",
      "{clubSite}": "site web du club",
      "{clubSiret}": "SIRET du club",
      "{clubSiren}": "SIREN du club",
      "{clubRna}": "numéro RNA du club",
