    const today = demoToday();
    const plusDays = (d) => { const x = new Date(today); x.setDate(x.getDate() + d); return x.toISOString().slice(0, 10); };
    // Lot C (pérennité) — âge cible via demoBirthDateForAge(age, 90, today), même ancre `today` que
